    }
  }
  for (auto k = 1; k < 60; k++)
  {
    for (auto i = 0; i < N; i++)
    {
      a[k][i] = a[k - 1][i] + a[k - 1][(a[k - 1][i] + i) % N];
    }
  }
}

ll calc_start(ll N, ll K, const vector<vector<ll>> &a)
{
  ll sum = 0;
  ll now = 0;
  const ll C = N * K;
  while (true)
  {
    int ind = 0;
    for (auto k = 0; k < 60; k++)
    {
      if (a[k][now] + sum >= C)
      {
        ind = k - 1;
        break;
      }
    }
    if (ind == -1)
    {
      break;
    }
    sum += a[ind][now];
    now = sum % N;
  }
  return now;
}

deque<int> last_state(ll start, ll N, const vector<int> &A)
{
  deque<int> D;
  vector<bool> stacked(200010, false);
  for (auto i = start; i < N; i++)
  {
    if (!stacked[A[i]])
    {
      D.push_back(A[i]);
      stacked[A[i]] = true;
    }
    else
    {
      while (true)
      {
        int x = *D.rbegin();
        D.pop_back();
        stacked[x] = false;
        if (x == A[i])
        {
          break;
        }
      }
    }
  }
  return D;
}

void flush(const deque<int> &D)
{
  for (auto i = 0u; i < D.size(); i++)
  {
    cout << D[i];
    if (i < D.size() - 1)
    {
      cout << " ";
    }
  }
  cout << endl;
}

int main()
{
  ll N, K;
  cin >> N >> K;
  vector<int> A(N);
  for (auto i = 0; i < N; i++)
  {
    cin >> A[i];
  }
  vector<vector<ll>> a(60, vector<ll>(N));
  doubling(N, A, a);
  ll start = calc_start(N, K, a);
  deque<int> D = last_state(start, N, A);
  flush(D);
}

