    for (int i = 1; i <= n; i++) {
        a[i + n] = a[i];
        a[i + 2 * n] = a[i];
        a[i + 3 * n] = a[i];
    }
    for (int i = 2 * n; i >= 1; i--) {
        if (i <= n) {
            up[0][i].second = nxt[a[i]] % n + 1;
            if (nxt[a[i]] < n) up[0][i].first = 0;
            else if (nxt[a[i]] < 2 * n) up[0][i].first = 1;
            else up[0][i].first = 2;
        }
        nxt[a[i]] = i;
    }
    for (int j = 0; j + 1 < LG; j++) {
        for (int i = 1; i <= n; i++) {
            up[j + 1][i].first = up[j][i].first + up[j][up[j][i].second].first;
            up[j + 1][i].second = up[j][up[j][i].second].second;
        }
    }
    ll cur_jumps = 0;
    int cur_val = 1;
    for (int k = LG - 1; k >= 0; k--) {
        if (cur_jumps + up[k][cur_val].first <= K - 1) {
            cur_jumps += up[k][cur_val].first;
            cur_val = up[k][cur_val].second;
        }
    }
    vector < bool > has(maxN, false);
    vector < int > now;
    for (int i = cur_val; i <= (K - 1 - cur_jumps) * n + n; i++) {
        if (!has[a[i]]) {
            now.push_back(a[i]);
            has[a[i]] = true;
        }
        else {
            while (has[a[i]]) {
                has[now.back()] = false;
                now.pop_back();
            }
        }
    }
    for (int v : now) cout << v << " ";
    return 0;
}

