const int limit = 200010;

int last[limit];

const int upper = 60;
int nxt[upper + 1][limit];
ll step[upper + 1][limit];

const ll val_limit = 1LL << 60;

inline ll add_with_limit(ll a, ll b){
	if(max(a, b) >= val_limit) return val_limit;
	return min(val_limit, a + b);
}

int main(void){
	ll n, k;
	cin >> n >> k;
	vector<int> a(n);

	rep(i, n) cin >> a[i];
	rep(i, limit) last[i] = -1;

	rep(i, 2 * n){
		int &pos = last[a[i % n]];

		if(pos != -1){
			nxt[0][pos] = (i + 1) % n;
			step[0][pos] = i + 1 - pos;
		}

		if (i < n)
			pos = i;
		else
			pos = -1;
	}

	rep(t, upper){
		rep(i, n){
			nxt[t + 1][i] = nxt[t][nxt[t][i]];
			step[t + 1][i] = add_with_limit(step[t][nxt[t][i]], step[t][i]);
		}
	}

	const ll thr = n * k;
	ll cur = 0;

	rrep(t, upper){
		const ll pos = cur % n;
		if (cur + step[t][pos] > thr) continue;
		cur += step[t][pos];
	}

	set<int> used;
	vector<int> ans;

	for(ll i = cur; i < thr; ++i){
		const int val = a[i % n];
		if(used.find(val) != end(used)){
			while(ans.back() != val) {
				const int tmp = ans.back();
				used.erase(tmp);
				ans.pop_back();
			}
			used.erase(val);
			ans.pop_back();
		} else {
			used.insert(val);
			ans.push_back(val);
		}
	}

	const int m = ans.size();
	rep(i, m) cout << (i? " " : "") << ans[i];
	cout << endl;

	return 0;
}

