vector<pair<int, ll> > jump;

pair<int, ll> nxtPos(int i){
    int x = lower_bound(pos[a[i]].begin(), pos[a[i]].end(), i) - pos[a[i]].begin();
    int j = pos[a[i]][x + 1];
    ll len = j - pos[a[i]][x] + 1;
    return make_pair((i + len) % n, len);
}

void preCal(){
    jump.push_back(nxtPos(0));
    while(true){
        int pos = jump.back().first;
        if(pos == 0){
            break;
        }
        jump.push_back(nxtPos(pos));
    }
}

deque<int> ans;
