    for(int i = 0, L = (int)jump.size(); i < L; i++){
        //cout << jump[i].first << ' ' << jump[i].second << '\n';
        m += jump[i].second;
    }

    ll rem = (((ll)n % m) * (k % m)) % m;

    int from = 0;
    ll psum = 0, step = rem;

    for(int i = 0, L = (int)jump.size(); i < L; i++){
        psum += jump[i].second;
        if(psum <= rem){
            from = jump[i].first;
            step = rem - psum;
        }
    }

    for(ll i = 1; i <= step; i++, from = (from + 1) % n){
