struct Permutation {
    vector<int64_t> container;
    Permutation(size_t size)
        : container(size)
    {
        for (int i = 0; i < size; i++) {
            container[i] = 0;
        }
    }
    size_t size() const
    {
        return container.size();
    }
    int64_t& operator[](size_t i)
    {
        return container[i];
    }
    const int64_t& operator[](size_t i) const
    {
        return container[i];
    }
    Permutation operator*(const Permutation& other) const
    {
        int64_t n = container.size();
        Permutation result(n);
        for (int64_t i = 0; i < n; i++) {
            result[i] = (*this)[i] + other[(i + (*this)[i]) % n];
        }
        return result;
    }
};

Permutation ppow(const Permutation& p, int64_t x)
{
    if (x == 0) {
        return Permutation(p.size());
    } else if (x % 2 == 0) {
        return ppow(p * p, x / 2);
    } else {
        return p * ppow(p, x - 1);
    }
}

class UFTree {
    vector<int> parent;
    vector<int> height;

public:
    UFTree(int size)
    {
        for (int i = 0; i < size; i++) {
            parent.push_back(i);
            height.push_back(0);
        }
    }
    int root(int node)
    {
        if (parent[node] == node) {
            return node;
        }
        return parent[node] = root(parent[node]);
    }
    void merge(int n0, int n1)
    {
        int r0 = root(n0), r1 = root(n1);
        if (r0 == r1) {
            return;
        }
        if (height[r0] < height[r1])
            swap(r0, r1);
        if (height[r0] == height[r1])
            height[r0]++;
        parent[r1] = r0;
    }
};

