		A[i] = lower_bound(all(zip),A[i])-zip.begin();
		vec[A[i]].pb(i);
		vec[A[i]].pb(i+N);
	}
	for(int i=0;i<zip.size();i++)sort(all(vec[i]));
	for(int i=0;i<N;i++){
		nxt[i] = (*upper_bound(all(vec[A[i]]),i))+1;
		cost[i] = nxt[i]-i;
		while(nxt[i]>=N)nxt[i]-=N;
	}
	/*for(int i=0;i<N;i++){
		cout << i << ' ' << nxt[i] << ' ' << cost[i] << endl; 
	}*/
	int now = 0;
	int sum = 0;
	do{
		sum += cost[now];
		now = nxt[now];
	}while(now!=0);
	//cout << now << ' ' << sum << endl;
	ll rem =  K*((ll)N)%((ll)sum);
	now = 0;
	while(rem>cost[now]){
		rem -= cost[now];
		now = nxt[now]; 
	}
	vector<int> ans;
	vector<int> cnt(zip.size());
	for(int i=0;i<rem;i++){
		int idx = (now+i)%N;
		if(cnt[A[idx]]>0){
			while(cnt[A[idx]]>0){
				int k = ans.back();
				ans.pop_back();
				cnt[k]--;
			}
		}else{
			cnt[A[idx]]++;
			ans.pb(A[idx]);
		}
	}
	for(int i=0;i<ans.size();i++){
		cout << zip[ans[i]];
		if(i+1<ans.size())cout << ' ';
		else cout << endl;
	}
	return 0;
}

