		{
			lst = pos[a[idx]];
			pos[ans[lst]] = -1;
			pos[a[idx]] = -1;
			idx = pos[a[idx]];
		}
		else
		{
			ans[lst] = a[idx];
			pos[a[idx]] = lst;
			lst++;
			pos[ans[lst]] = -1;
			idx++;idx %= n;
		}
	}
}

void go()
{
	while(1)
	{
		int add;
		auto it = upper_bound(vec[a[idx]].begin(),vec[a[idx]].end(),idx);
		//cout << idx << ' ' << tot << '\n';
