vector<vector<int> > G; // G[i]はAの同じ数字のiteratorの集合
vector<int> visit, indx, ans;
int N, K;

void dfs(int i){ // iは数列Aのiterator
  if(i==N) return;

  if(G[indx[i]].size()==1) {
    ans.push_back(i);
    dfs(i+1);
  } else {
    for(int j=0; j<G[indx[i]].size(); j++){
      if(i==G[indx[i]][j]){
        if(j==G[indx[i]].size()-1) {
          visit[G[indx[i]][0]] = 1;
          ans.push_back(G[indx[i]][0]);
          dfs(G[indx[i]][0]+1);
        } else {
          visit[G[indx[i]][j+1]] = 1;
          ans.push_back(G[indx[i]][j+1]);
          dfs(G[indx[i]][j+1]+1);
        }
      }
    }
  }
}

int main(){
  cin >>N >>K;
  int A[N];
  pair<int,int> B[N]; // B[i] = (A_i, i)
  for(int i=0;i<N;i++){
    cin >>A[i];
    B[i] = make_pair(A[i],i);
  }
  sort(B, B+N);

  int a = B[0].first; int x=0;
  indx.assign(N,-1); // indx[i]はite iが含まれているG[j]のjを格納
  vector<int> ite;
  for(int i=0;i<N;i++){ // グラフ作成
    if(a != B[i].first) {
      G.push_back(ite);
      x++;
      ite.clear();
      a = B[i].first;
    }
    ite.push_back(B[i].second);
    indx[B[i].second] = x;
  }
  G.push_back(ite);

  visit.assign(N+1,0);
  visit[0] = 1;
  dfs(0);

  vector<int> final_ans;
  if(ans[0]==0) final_ans.push_back(1);
  for(int i=1; i<ans.size(); i++){
    if(ans[i]<=ans[i-1]+1) final_ans.push_back(ans[i-1]+1);
  }

  int k = K%(final_ans.size()+1);
  if(k==0) cout << " " << endl;
  else {
    for(int i=final_ans[k-1]; i<N; i++){
      cout << A[i] << " ";
    }
    cout << endl;
  }
  return 0;
}

