    // step[i][j] = 2^i回進んだ場合の距離
    vector<vector<ll>> step(60, vector<ll>(n));
    vector<ll> next(200000);
    for(ll i=2*n-1; i>=0; --i) {
        if(i < n) step[0][i] = next[a[i]] - i + 1;
        next[a[i%n]] = i;
    }
    FOR(i, 1, 60) REP(j, n) {
        step[i][j] = step[i-1][j] + step[i-1][(j+step[i-1][j])%n];
