using namespace std;

typedef long long ll;

ll N, K;
int A[200000 + 100];
int nxtsame[200000 + 100];

void printans(int from) {
	vector<int> ans;
	map<int, int> is_appear;
	for (int i = from; i < N; i++) {
		if (!is_appear[A[i]]) {
			is_appear[A[i]] = i + 1;
			ans.push_back(A[i]);
		}
		else {
			while (ans.size()) {
				if (ans.back() == A[i]) {
					ans.pop_back();
					is_appear[A[i]] = 0;
					break;
				}
				is_appear[ans.back()] = 0;
				ans.pop_back();
			}
		}
	}
	for (int i = 0; i < ans.size(); i++) {
		cout << ans[i] << " ";
	}
	cout << endl;
}

int main() {
	cin >> N >> K;
	for (int i = 0; i < N; i++) {
		cin >> A[i];
		nxtsame[i] = -1;
	}

	map<int, int> is_appear, first_appear;
	for (int i = 0; i < N; i++) {
		if (is_appear[A[i]] == 0) {
			is_appear[A[i]] = i + 1;//+1の下駄をはかせる
			first_appear[A[i]] = i + 1;
		}
		else {
			nxtsame[is_appear[A[i]] - 1] = i;
			is_appear[A[i]] = i + 1;
		}
	}
	for (int i = 0; i < N; i++)
		if (nxtsame[i] == -1) nxtsame[i] = first_appear[A[i]] - 1;

	vector<int> rotation;
	vector<bool> used(N + 100, false);
	int nowidx = 0;
	ll cycle_size = 0;
	while (true) {
		if (used[nowidx]) {
			cycle_size++;
			break;
		}
		rotation.push_back(nowidx);
		if (nowidx >= nxtsame[nowidx])cycle_size++;
		used[nowidx] = true;
		nowidx = (nxtsame[nowidx] + 1) % N;
	}

	ll amari = K % cycle_size;
	int cnt_cycle = 0;
	for (int i = 1; i < rotation.size(); i++) {
		if (rotation[i] <= rotation[i - 1] + 1)cnt_cycle++;
		if (cnt_cycle >= amari) {
			//print ans
			printans(rotation[i - 1]);
			return 0;
		}
	}
	return 0;
}

