int main(){
  using namespace std;
  cpp_int n;
  cpp_int k;
  cin>>n>>k;
  int a[n];
  REP(i, n) cin>>a[i];

  vector<int> prev(20'0010, -1);
  vector<bool> used(n, false);
  cpp_int g[n][61];
  REP(i, 2 * n){
    int ni = i % n;
    if(prev[a[ni]] < 0){
      prev[a[ni]] = i;
      continue;
    }

    int start = prev[a[ni]];
    if(used[start]) continue;
    g[start][0] = i - start + 1;
    used[start] = true;
  }
  REPP(j, 60){
    REP(i, n){
      g[i][j] = g[i][j - 1];
      cpp_int mid = i + g[i][j - 1];
      cpp_int temp = g[mid % n][j - 1];
      g[i][j] += temp;
    }
  }

  cpp_int now = 0;
  while(now < n * k){
    int i = now % n;
    long long nj = -1;
    for(int j = 0; j <= 60; j++){
      if(now + g[i][j] < n * k){
        nj = j;
      }
    }
    if(nj < 0) break;
    now = now + g[i][nj];
  }

  vector<bool> exist(200'010, false);
  stack<int> st;
  for(int i = now % n; i < n; i++){
    if(!exist[a[i]]){
      st.push(a[i]);
      exist[a[i]] = true;
      continue;
    }
    while(!st.empty()){
      if(st.top() == a[i]){
        st.pop();
        exist[a[i]] = false;
        break;
      }else{
        exist[st.top()] = false;
        st.pop();
      }
    }
  }
  vector<int> ans;
  while(!st.empty()){
    ans.push_back(st.top());
    st.pop();
  }
  reverse(ALL(ans));
  for(int& x: ans) cout << x << ' ';
  cout << endl;  
  return 0;
}

