  vecint nxt(n);
  vecint old(200001, -1);
  REP(i,n) {
    if (old[a[i]] >= 0) {
      nxt[old[a[i]]] = i+1;
    }
    old[a[i]] = i;
  }
  REP(i,n) {
    if (old[a[i]] >= i) {
      nxt[old[a[i]]] = i+1+n;
    }
    old[a[i]] = i;
  }
  vecint step(n);
  for (int i=n-1; i>=0; --i) {
    if (nxt[i] >= n) {
      step[i] = nxt[i]-n;
    } else {
      step[i] = step[nxt[i]];
    }
  }
  int init_len = 0;
  int loop_size = 0;
  int index = 0;
  int count = 0;
  map<int, int> idxmap;
  idxmap[0] = 0;
  while (1) {
    ++count;
    index = step[index];
    //cerr<<index<<endl;
    if (idxmap.count(index)) {
      init_len = idxmap[index];
      loop_size = count - init_len;
      break;
    } else {
      idxmap[index] = count;
    }
  }
  map<int, int> revmap;
  for (auto p : idxmap) {
    revmap[p.second] = p.first;
  }
  int idx = 0;
  --k;
  if (k >= init_len) {
    k -= init_len;
    k %= loop_size;
    k += init_len;
  }
