typedef long long ll;

constexpr int MAXN = 2e5 + 42;

int val[MAXN], succ[MAXN], last[MAXN], pos[MAXN], in[MAXN];

int main() {
  int N;
  ll K;
  cin >> N >> K;
  for (int i = 0; i < N; i++) {
    cin >> val[i];
    last[val[i]] = i;
  }
  for (int i = 0; i < N; i++) {
    succ[last[val[i]]] = i;
    last[val[i]] = i;
  }

  int x = 0, t = 0;
  do {
    if (succ[x] <= x || succ[x] == N - 1) {
      pos[t++] = x;
    }
    x = (succ[x] + 1) % N;
  } while (x != 0);

  K = (K - 1) % t;

  vector<int> stk;
  for (int i = pos[K]; i < N; i++) {
    if (in[val[i]]) {
      while(stk.back() != val[i]) {
        in[stk.back()] = 0;
        stk.pop_back();
      }
      stk.pop_back();
    } else {
      stk.push_back(val[i]);
    }
    in[val[i]] ^= 1;
  }

  for (int i : stk) {
    cout << i << ' ';
  }
  cout << endl;

  return 0;
}

