const int LOG = 50;
const int N = 2e5+10;
const ll K = 1e12;
int jmp[LOG][N];
ll dist[LOG][N];

vector<int> sim(vector<int>& v) {
    unordered_set<int> have;
    vector<int> cur;
    for(auto x : v) {
        if (have.count(x)) {
            while (true) {
                // if (cur.empty()) {while(1) {}}
                int last = cur.back();
                cur.pop_back();
                if (last == x) {
                    break;
                }
            }
            have.erase(x);
        } else {
            cur.push_back(x);
            have.insert(x);
        }
    }
    return cur;
}

int main() {
    ios_base::sync_with_stdio(false);
    int n;
    ll k;
    cin >> n >> k;
    vector<int> a(n);
    cin >> a;

    unordered_map<int, vector<int>> occ;

    rep(i,0,n) {
        occ[a[i]].push_back(i);
    }

    for(auto& x : occ) {
        rep(i,0,x.second.size()) {
            int cur = x.second[i];
            int nxt = x.second[(i+1)%x.second.size()];
            jmp[0][cur] = (nxt + 1) % n;
            dist[0][cur] = nxt - cur + 1;
            if (dist[0][cur] <= 1) dist[0][cur] += n;
        }
    }

    rep(l,1,LOG) {
        rep(i,0,n) {
            jmp[l][i] = jmp[l-1][jmp[l-1][i]];
            dist[l][i] = min(dist[l-1][i] + dist[l-1][jmp[l-1][i]], N*K+10);
        }
    }

    // rep(l,0,3){
    //     cout << "----------- " << l << endl;
    //     rep(i,0,n) {
    //         cout << i << ": " << jmp[l][i] << " " << dist[l][i] << endl;
    //     }
    // }

    int cur = 0;
    ll rem = n * k;
    per(l,0,LOG) {
        if (dist[l][cur] <= rem) {
            // cout << "jump " << l << " " << cur << " " << jmp[l][cur] << " " << rem << endl;
            rem -= dist[l][cur];
            cur = jmp[l][cur];
            l++;
        }
    }

    // assert(rem <= N*2);

    vector<int> rest;

    while (rem > 0) {
        rem--;
        rest.push_back(a[cur]);
        cur = (cur + 1) % n;
    }
    vector<int> res = sim(rest);

    cout << res << endl;
}

