ll n, m;

ll a[maxn], last[maxn], nex[maxn], w[maxn], link[maxn], cnt, start;

ll ans[maxn], tot;

ll s[maxn];

ll vis[maxn];

void search(ll now, ll step)
{
	if(vis[now])
	{
		if(vis[now] == cnt) start = now, link[now] = step - s[now];
		return;
	}
	vis[now] = cnt;
	s[now] = step;
	search(nex[now], step + w[now]);
	if(start == now) start = 0;
	if(start) link[now] = link[nex[now]];
	return ;
}

signed main()
{
	scanf("%lld %lld", &n, &m);
	rep(i, 1, n) scanf("%lld", &a[i]);
	rep(i, n + 1, 2 * n) a[i] = a[i - n];
	per(i, 2 * n, 1)
	{
		if(i <= n)
		{
			nex[i] = last[a[i]] % n + 1;
			w[i] = (last[a[i]]) / n - (i - 1) / n;
		}
		last[a[i]] = i;
	}
	rep(i, 1, n) if(!vis[i]) ++cnt, search(i, 0);
	// rep(i, 1, n) printf("%lld %lld %lld\n", nex[i], w[i], link[i]);
	// puts("");
	ll now = 0;
	while(m >= 0)
	{
		// printf("%lld %lld %lld\n", m, now, tot);
		if(!m && now == n) break;
		now = now % n + 1;
		ans[++tot] = a[now];
		if(now == 1) m--;
		if(link[now]) if(m >= link[now]) m %= link[now];
		if(w[now] - (nex[now] == 1) <= m)
		{
			m -= w[now] - (nex[now] == 1);
			tot --, now = nex[now] == 1 ? n : nex[now] - 1;
		}
	}
	rep(i, 1, tot) printf("%lld ", ans[i]);
	return 0;
}

