int N;
ll K;
int arr[MAXN];
int loc[MAXN];
int to[MAXN];
ll go[72][MAXN];
ll pos;
vl seq;

int32_t main()
{
	ios_base::sync_with_stdio(0); cin.tie(0);
	cin >> N >> K;
	FOR(i, 0, N)
	{
		cin >> arr[i];
		arr[i + N] = arr[i];
	}
	FORD(i, 2 * N, N)
	{
		loc[arr[i]] = i;
	}
	FORD(i, N, 0)
	{
		to[i] = loc[arr[i]] + 1 - i;
		loc[arr[i]] = i;
	}
	FOR(i, 0, N)
	{
		go[0][i] = to[i];
	}
	FOR(i, 1, 69)
	{
		bool die = false;
		FOR(j, 0, N)
		{
			go[i][j] = go[i - 1][j] + go[i - 1][(j + go[i - 1][j]) % N];
			if (go[i][j] > LLINF)
			{
				die = true;
			}
		}
		if (die) break;
	}
	pos = 0;
	FORD(i, 69, 0)
	{
		if (pos + go[i][pos % N] <= K * N)
		{
			pos += go[i][pos % N];
		}
	}
	if (pos == K * N)
	{
		return 0;
	}
	seq.PB(arr[pos % N]);
	FOR(i, 0, MAXN)
	{
		loc[i] = 0;
	}
	loc[arr[pos % N]] = 1;
	//so now you just have a sequence!
	FOR(i, pos + 1, K * N)
	{
		ll x = arr[i % N];
		if (loc[x])
		{
			while(true)
			{
				int y = seq.back();
				seq.pop_back();
				loc[y]--;
				if (x == y) break;
			}
		}
		else
		{
			seq.PB(x);
			loc[x]++;
		}
	}
	FOR(i, 0, SZ(seq))
	{
		if (i) cout << ' ';
		cout << seq[i];
	}
	cout << '\n';
	return 0;
	//now keep on applying this thing till we hit like smth in N*(K-1)...N*K-1
}

