void pre(int n) {
  for(int i=0;i<n;i++) num[n+i]=num[i];
  for(int i=2*n-1;i>=0;i--) {
  	if (i<n) {
  		f[i][0]=(last[num[i]]+1)%n;
  		g[i][0]=last[num[i]]-i+1;
	  }
	last[num[i]]=i;
  }
  for(int i=1;i<60;i++)
    for(int j=0;j<n;j++) {
    	f[j][i]=f[f[j][i-1]][i-1];
    	g[j][i]=g[j][i-1]+g[f[j][i-1]][i-1];
	}
}

int query(ll k) {
  int x=0;
  for(int i=59;i>=0;i--)
    if (g[x][i]<=k) {
    	k-=g[x][i];
    	x=f[x][i];
	}
  return k;
}

