        a[i]--;
    }

    vector<vector<int>> idx(200'000);
    rep(i, n)
    {
        idx[a[i]].push_back(i);
    }

    Permutation p(n);
    rep(i, idx.size())
    {
        int m = idx[i].size();
        rep(j, m)
        {
            p[idx[i][j]] = (idx[i][(j + 1) % m] - idx[i][j] + 1 + n) % n;
        }
    }
    rep(i, n)
    {
        if (p[i] == 1) {
            p[i] = n + 1;
        }
    }

    UFTree uft(n);
    rep(i, n)
    {
        uft.merge(i, (i + p[i]) % n);
    }
    int64_t T = 0;
    int cnt = 0;
    rep(i, n)
    {
        if (uft.root(0) == uft.root(i)) {
            T += p[i];
            cnt++;
        }
    }

    int64_t M = (k * n) % T;
    int64_t lb = 0, ub = cnt;
    while (ub - lb > 1) {
        int64_t mid = (lb + ub) / 2;

        Permutation q = ppow(p, mid);
        if (q[0] <= M) {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    Permutation q = ppow(p, lb);

