vector<int> v[20001]; // v[n]には A_k = n となるkが入ってる, ソート済みなので二分探索で値がlog n

// v[i] の k = j の index を二分探索で取得
int biSearch(int i, int j){
    int lb=0, ub = v[i].size() - 1;
    while( v[i][ub] != j ){
        int mid = (lb+ub)/2;
        if( v[i][mid] >= j){
            ub = mid;
        }else{
            lb = mid;
        }
    }
    return ub;
}

