signed main(void){

    int n, k;
    cin >> n >> k;

    vector<int> a(n);
    rep(i, n)cin >> a[i];

    //ループするから、それをうまく使うしかない
    //n回で1回はかならず全て消える
    //試さなきゃいけないのはせいぜいn回
    //ある数字が先頭に来た時、それが消えるのは次に同じ数字が来た時
    //もしその数字が答えに影響しないなら、それが消えるまでの過程は関係ない
    //1, 2, 3, 4, 1, 5, 4のとき1, 5, 4, 1, 2, 3, 4と先頭の文字は変わる
    //次同じ文字が出てくるまでの距離の合計が1回のループの操作回数(上の例だと5+8+5+4+8+8+4=42)
    //vectorにその数字が次に出てくる場所とそこまでの距離をを入れておく
    //変なループになったりしないか？　いや、それは関係ないか

    vector<int> b(n * 2), c(n), d(n);
    rep(i, n)b[i] = b[i + n] = a[i];

    map<int, int> mp;
    rep(i, n * 2){
        if(mp.find(b[i]) == mp.end()){
            mp[b[i]] = i % n;
        } else {
            c[mp[b[i]]] = i % n;
            mp[b[i]] = i % n;
        }
    }

    rep(i, n){
        if(c[i] == i)d[i] = n + 1;
        else d[i] = (c[i] - i + n) % n + 1;
    }

    int sum = 0;
    vector<bool> used(n, false);
    int pos = 0;
    while(true){
        if(used[pos])break;
        sum += d[pos];
        used[pos] = true;
        pos = (c[pos] + 1) % n;
    }

    k *= n;
    k %= sum;

    pos = 0;
    while(true){
        if(k < d[pos])break;
        k -= d[pos];
        pos = (c[pos] + 1) % n;
    }

    int now = 0;
    mp.clear();
    vector<int> ans(n);
    rep(i, k){
        if(mp.find(b[pos]) == mp.end()){
            mp[b[pos]] = now;
            ans[now++] = b[pos++];
        } else {
            now = mp[b[pos]];
            mp.erase(b[pos]);
        }
    }

    rep(i, now){
        if(i > 0)cout << ' ';
        cout << ans[i];
    }
    cout << endl;

}

