int main(int argc, const char * argv[]) {
  ll N, K; cin >> N >> K;
  vector<int> A(N);
  for(int i=0; i<N; i++)
    cin >> A[i];

  vector<int> B(2*N);
  for(int i=0; i<2*N; i++)
    B[i] = A[i%N];

  vector<vector<int>> jump(300000);
  for(int i=0; i<2*N; i++)
    jump[B[i]].push_back(i);

  vector<int> next(N); // Aiからjumpしたときのindex
  for(int i=0; i<N; i++){
    auto it = upper_bound(jump[A[i]].begin(), jump[A[i]].end(), i);
    next[i] = (*it) + 1;
  }
  vector<int> start; // i個目Aをまたぐjumpにおける始点のindex
  int now;
  now = 0;
  while(true){
    if(next[now] > N) {
      start.push_back(now);
    }
    if(next[now]%N == 0) {
      start.push_back(now);
      break;
    }
    now = next[now]%N;
  }

  K %= (int)start.size();

  for(int i=start[K-1]; i<N; i++){
    if(next[i] <= N) i = next[i] - 1;
    else cout << A[i] << " ";
  }
  cout << endl;

  return 0;
}

