void solve(){
	vector<int> npos(B+1,N), next(N);
	vector<int> q;
	for(int i = N - 1;i >= 0;i--){
		if(npos[A[i]] != N)next[i] = npos[A[i]];
		else q.push_back(i);
		npos[A[i]] = i;
	}
	for(auto &&i:q){
		next[i] = npos[A[i]] + N;
	}
	int t = 0;
	Int u = 0;
	do{
		u += next[t] - t + 1;
		t = u % N;
	}while(t!=0);
	K %= (u/N);
	Int M = K * N;
	for(Int i = 0;i < M;){
		int j = i % N;
		Int ni = i + next[j] - j;
		if(ni<M){
			i = ni + 1;
			continue;
		}else{
			for(Int j = i;j < M;j++){
				int k = j % N;
				Int nj = j + next[k] - k;
