int res,poss;
int n,k,a[200010],dist[200010],nxt[200010];
vector<int> v[200010];
int last[200010];

inline void dfs(int pos,int lvl,bool flag)
{
	if(!flag){
		if(dist[pos]!=-1){
			res=lvl;
			poss=pos;
			return;
		}
		dist[pos]=lvl;
		int u=nxt[pos];
		if(u<=pos){last[lvl]=pos;dfs(u,lvl+1,1);}
		else dfs(u,lvl,1);
	}
	else{
		pos++;
		if(pos<=n){
			dfs(pos,lvl,0);
		}
		else dfs(1,lvl+1,0);
	}
}

signed main()
{
	ios::sync_with_stdio(false);
	cin>>n>>k;
	memset(dist,-1,sizeof(dist));
	memset(last,-1,sizeof(last));
	for(int i=1;i<=n;i++) cin>>a[i];
	for(int i=1;i<=n;i++) v[a[i]].push_back(i);
	for(int i=1;i<=2e5;i++) if(!v[i].empty()){
		for(int j=0;j<v[i].size()-1;j++){
			nxt[v[i][j]]=v[i][j+1];
		}
		nxt[v[i][v[i].size()-1]]=v[i][0];
	}
	dfs(1,1,0);
	int v1=dist[poss],v2=res-dist[poss],st=0;
	if(k<=v1){
		if(last[k]==-1){
			st=n+1;
		}
		else{
			st=last[k];
		}
	}
	else{
		k-=v1;
		k=(k-1)%v2+1;
		k+=v1;
		if(last[k]==-1){
			st=n+1;
		}
		else{
			st=last[k];
		}
	}
	vector<int> ans;
	for(int i=st;i<=n;i++){
		if(nxt[i]<=i){
			ans.push_back(a[i]);
		}
		else{
			i=nxt[i];
		}
	}
	for(int i=0;i<ans.size();i++) cout<<ans[i]<<" ";
	cout<<endl;
	return 0;
}

