const int MAXN = 262144;
const int LOG = 64;

int n;
ll k;
int a[MAXN];

vc<int> poses[MAXN];
il void GetPoses(){
	For(i,n) poses[a[i]].Eb(i);
}
il int Next( int num , int pos ){
	// 获取 [pos,n] 中第一个 num 的位置，没有就返回 n+2
	auto it = lower_bound(All(poses[num]),pos);
	return it == poses[num].end() ? n+2 : *it;
}

int nxtlayer[MAXN];
void GetNxtlayer(){
	nxtlayer[n+1] = 1;
	fOR(i,n){
		int pos = i;
		pos = Next(a[i],i+1);
		if( pos > n ){
			pos = (*poses[a[i]].begin()) + 1;
			nxtlayer[i] = pos;
		}
		else if( pos == n ) nxtlayer[i] = 1;
		else nxtlayer[i] = nxtlayer[pos+1];
	}
}

int to[LOG][MAXN];
void GetTo(){
	For(i,n+1) to[0][i] = nxtlayer[i];
	For(i,LOG-1)
		For(j,n+1)
			to[i][j] = to[i-1][to[i-1][j]];
}

