void solve(istream& input, ostream& output) {
	int N; cin >> N;
	ll K; cin >> K;
	vector<int> A(2*N);
	vector<set<int>> pos(200001);
	for (int i = 0; i < N; i++) {
		cin >> A[i]; A[i+N] = A[i];
		pos[A[i]].insert(i); pos[A[i]].insert(i+N);
	}
	vector<int> loops(N, -1);
	for (int p = 0, l = 1; p < N; p++) {
		p = *(++(pos[A[p]].lower_bound(p)));
		if (p >= N) {
			l++;
			p -= N;
		}
		loops[p] = l;
	}
	K %= loops[N-1];
	if (K == 0) {
		cout << endl; return;
	}
	int P = -1, L = 1;
	for (int i = 0; i < N; i++) {
		if (loops[i] <= K && L <= loops[i]) {
			P = i; L = loops[i];
		}
	}
	P++;
	K -= L-1;
	set<int> num;
	vector<int> res;
	while (K--) {
		for (; P < N; P++) {
			if (num.count(A[P])) {
				while (res.back() != A[P]) {
					num.erase(res.back());
					res.pop_back();
				}
				num.erase(res.back());
				res.pop_back();
			} else {
				res.push_back(A[P]);
				num.insert(A[P]);
			}
		}
		P = 0;
	}
	for (unsigned int i = 0; i < res.size(); i++) {
		if (i) cout << " ";
		cout << res[i];
	}
	cout << endl;
}

