void solve() {
  int N;
  i64 K;
  cin >> N >> K;
  vi32 A(N);
  cin >> A;
  vector<vi64> next(41, vi64(N));
  {
    unordered_map<int, int> mp;
    rep(i, N * 2) {
      int idx = i % N;
      if (mp.count(A[idx]) && next[0][mp[A[idx]]] == 0) {
        next[0][mp[A[idx]]] = i + 1 - mp[A[idx]];
      }
      mp[A[idx]] = idx;
    }
    rep(i, 40) rep(j, N) {
      next[i + 1][j] = min((i64) 1e18, next[i][j] + next[i][(j + next[i][j]) % N]);
    }
  }
  i64 now = 0;
  while ((K - 1) * N > now) {
    rrep(i, 40) {
      if (K * N > now + next[i][now % N]) now += next[i][now % N];
    }
  }
  unordered_set<int> se;
  vi32 ans;
  for (i64 idx = now; idx < K * N; idx++) {
    int i = idx % N;
    if (!se.count(A[i])) {
      ans.push_back(A[i]);
      se.insert(A[i]);
    } else {
      while (ans.back() != A[i]) ans.pop_back();
      ans.pop_back();
      se.erase(A[i]);
    }
  }
  cout << ans << endl;
}

