int main() {
    int n; long long k; cin >> n >> k;
    vector<int> v(n), before(n, -1);
    map<int, int> m;
    for (int i = 0; i < n; i++) cin >> v[i];

    // calc before
    for (int i = 0; i <= n; i++) {
        if (before[i] != -1) continue;
        if (m.find(v[i]) != m.end()) {
            before[i] = m[v[i]];
        } 
        m[v[i]] = i;
    }
    for (int i = 0; i <= n; i++) {
        if (before[i] != -1) continue;
        if (m.find(v[i]) != m.end()) {
            before[i] = m[v[i]];
        } 
        m[v[i]] = i;
    }
    long long count_loop = 0;
    int index = n-1;
    while (true) {
        int next_index = before[index];
        if (index <= next_index) count_loop++;
        index = (n + next_index-1) % n;
        if (index == n-1) {
            count_loop++;
            break;
        }
    }
    long long remain = (count_loop - 1) - (k % count_loop - 1);
    remain %= count_loop;
    index = n-1;
    while (remain) {
        int next_index = before[index];
        if (index <= next_index) remain--;
        index = (n + next_index-1) % n;
    }
    vector<int> ans(n+1, -1); map<int, int> mm;
    int ans_index = 1;
    while (++index) {
        if (index == n) break;
        int c = v[index];
        if (mm[c] == 0) {
            ans[ans_index] = c;
            mm[c] = ans_index;
            ans_index++;
        } else {
            int t = mm[c];
            for (int i = t; i < ans_index; i++) {
                ans[i] = -1;
            }
            mm[c] = 0;
            ans_index = t;
        }
    }
    for (int i = 1; i < ans_index; i++) {
        if (i == ans_index) break;
        if (i != 1) cout << " ";
        cout << ans[i];
    }
    cout << endl;
    return 0;
