#define maxn 200100

using namespace std;
vector<long long>q[maxn];
int  main()
{
	long long N,K;
	long long a[maxn];
	long long ma[maxn],L[maxn];
	scanf("%lld%lld",&N,&K);
	for(long long i=0;i<N;i++)
	{
		scanf("%lld",&a[i]);
		q[a[i]].push_back(i);
	}
	for(long long i=0;i<maxn;i++)
		if(!q[i].empty())
			L[i]=q[i].size();
	long long o=a[N-1],p=1,sign=N-1;
	while(1)
	{
		int S=lower_bound(q[o].begin(),q[o].end(),sign)-q[o].begin();
		if(S==0)
		{
			S=L[o]-1;
			p++;
		}
		else
			S--;
		if(q[o][S]==0)
			break;
		else
		{
			sign=q[o][S]-1;
			o=a[sign];
		}
	}
	//printf("%lld\n",p);
	K=K%p;
	stack<long long>U;
	for(long long j=0;j<maxn;j++)
		ma[j]=0;
	while(K--)
	{
		for(long long j=0;j<N;j++)
			if(ma[a[j]])
			{
				ma[a[j]]=0;
				int Tp=U.top();
				while(Tp!=a[j])
				{
					ma[Tp]=0;
					U.pop();
					Tp=U.top();
				}
				U.pop();
			}
			else
			{
				U.push(a[j]);
				ma[a[j]]++;
			}
		//printf("%d\n",U.size());
	}
	long long f[maxn];
	long long l=U.size();
	for(long long i=l;i>0;i--)
	{
		f[i]=U.top();
		U.pop();
	}
	for(long long i=1;i<=l;i++)
		printf("%lld ",f[i]);
	printf("\n");
}

