int main() {

	SINT64 N;	cin >> N;
	SINT64 K;	cin >> K;

	vector<SINT64> data(N);
	vector<vector<SINT64>> dat(200005);

	vector<vector<Pll>> D(N);

	rep(i,0,N) {
		cin >> data[i];
		dat[data[i]].emplace_back(i);
	}

	rep(i,0,200005) {
		rep(j,0,dat[i].size()) {
			Pll buf;
			if (j == dat[i].size() - 1) {
				buf.F = dat[i][0];
				buf.S = 1;
			} else {
				buf.F = dat[i][j+1];
				buf.S = 0;
			}
			if (buf.F != N-1) {
				buf.F++;
			} else {
				buf.F = 0;
				buf.S++;
			}
			D[dat[i][j]].emplace_back(buf);
		}
	}

	SINT64 cnt = 1;
	SINT64 ok = 0;
	while(1) {
		rep(i,0,N) {
			Pll buf;
			buf.F = D[D[i][cnt-1].F][cnt-1].F;
			buf.S = D[D[i][cnt-1].F][cnt-1].S + D[i][cnt-1].S;
			D[i].emplace_back(buf);
			if (buf.S > K) {
				ok = 1;
			}
		}
		cnt++;
		if(ok == 1) break;
	}

	cnt = 0;
	K--;
	SINT64 f = 0;
	while(1) {
		if (K == 0) {
			break;
		}
		f = 1;
		rep(i,0,D[cnt].size()) {
			if (i == D[cnt].size()-1) {
				K -= D[cnt][i].S;
				cnt = D[cnt][i].F;
				break;
			}

			if (D[cnt][i+1].S > K) {
				K -= D[cnt][i].S;
				cnt = D[cnt][i].F;
				break;
			}
		}
	}

	vector<SINT64> ldat(200005,0);
	vector<SINT64>	ans;

	if ((cnt == 0) && (f == 1)) {
		return 0;
	}

	rep(i,cnt,N) {
		if (ldat[data[i]] == 0) {
			ldat[data[i]]++;
			ans.emplace_back(data[i]);
		} else {
			while(1) {
				if (ans[ans.size()-1] == data[i]) {
					ldat[ans[ans.size()-1]] = 0;
					ans.pop_back();
					break;
				} else {
					ldat[ans[ans.size()-1]] = 0;
					ans.pop_back();
				}
			}
		}
	}
	rep(i,0,ans.size()) {
		puts(ans[i]);
	}

	return 0;
}


