int main(){

	ll N, K;
	cin >> N >> K;

	vector<ll> A(N);
	rep(i, N) cin >> A[i];

	vector<ll> nx(N);
	vector<ll> use(300000, -1);

	rep(i, 2 * N) {
		ll x = A[i%N];

		if (use[x] == -1) { use[x] = i; }
		else if (use[x] < N) { nx[use[x]] = i - use[x]; use[x] = i; }
	}

	//rep(i, N) cout << nx[i] << endl;

	vector<ll> emp;
	ll v = nx[0];
	emp.push_back(-1);
	emp.push_back(nx[0]);

	while ((v+1)%N != 0) {
		v = v + 1 + nx[(v + 1) % N];
		emp.push_back(v);
	}

	//rep(i, emp.size()) { cout << emp[i] << endl; }

	ll t = (K * N-1)%(v+1);

	auto itr = upper_bound(emp.begin(), emp.end(), t);
	ll e = *(--itr);

	//cout << t << e << endl;

	vector<bool> ct(30000, 0);
	stack<ll> st;

	for (ll i = e + 1; i <= t; i++) {
		ll x = A[i%N];

		if (ct[x] == 0) { st.push(x); ct[x] = 1; }

		else {
			while (st.top() != x) {
				ct[st.top()] = 0;
				st.pop();
			}
			ct[x] = 0;
			st.pop();
		}
	}

	vector<ll> rvans;
	while (!st.empty()) {
		rvans.push_back(st.top());
		st.pop();
	}

	reverse(rvans.begin(), rvans.end());

	rep(i, rvans.size()) {
		cout << rvans[i] << " ";
	}




	system("PAUSE");
}

