map<int, int> lst;
vector<int> ans;
ll K;

int32_t main () {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

//    freopen("test.INP", "r", stdin);

    cin >> n >> K; --K;
    for (int i = 1; i <= n; ++i) cin >> a[i];

    for (int i = n; i > 0; --i) {
        if (lst.count(a[i]) ) nxt[i][0] = lst[ a[i] ];
        else nxt[i][0] = -1;
        lst[ a[i] ] = i;
    }

    for (int i = 1; i <= n; ++i) {
        if (nxt[i][0] == -1) nxt[i][0] = lst[ a[i] ];
        nxt[i][0] = nxt[i][0] % n + 1;
        if (nxt[i][0] <= i + 1) cost[i][0] = 1;
    }

    for (int j = 1; j < LOG; ++j) {
        for (int i = 1; i <= n; ++i) {
            nxt[i][j] = nxt[ nxt[i][j - 1] ][j - 1];
            cost[i][j] = cost[i][j - 1] + cost[ nxt[i][j - 1] ][j - 1];
        }
    }

    int cur = 1;
    for (int i = LOG - 1; i >= 0; --i) if (cost[cur][i] < K) {
        K -= cost[cur][i];
        cur = nxt[cur][i];
    }

    for (int i = cur; i <= n; ++i) {
        if (ex[ a[i] ]) {
            while (ans.back() != a[i]) {
                ex[ans.back()] = 0;
                ans.pop_back();
            }
            ex[ans.back()] = 0;
            ans.pop_back();
        }
        else {
            ans.push_back(a[i]);
            ex[ a[i] ] = 1;
        }
    }

    if (K--) {
        for (int i = 1; i <= n; ++i) {
            if (ex[ a[i] ]) {
                while (ans.back() != a[i]) {
                    ex[ans.back()] = 0;
                    ans.pop_back();
                }
                ex[ans.back()] = 0;
                ans.pop_back();
            }
            else {
                ans.push_back(a[i]);
                ex[ a[i] ] = 1;
            }
        }
    }

    for (int i = 0; i < (int)ans.size(); ++i) cout << ans[i] << ' '; cout << '\n';

    return 0;
}

