using ll = long long;

void solve() {
    ll AMAX = 2e5 + 1;
    ll N, K;
    cin >> N >> K;
    vector<ll> A(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> A[i];
    }
    vector<ll> pos(AMAX, -1);
    for ( int i = 0; i < N; i++ ) {
        pos[A[i]] = i;
    }
    vector<ll> B(N);
    for ( int i = 0; i < N; i++ ) {
        ll b = i - pos[A[i]];
        if ( b <= 0 ) b += N;
        B[i] = b;
        pos[A[i]] = i;
    }
    ll c = 1;
    ll p = N-1;
    while ( true ) {
        p -= B[p];
        if ( p < 0 ) {
            p += N;
            c++;
        }
        if ( p == 0 ) {
            break;
        }
        p--;
    }
    vector<ll> L(c+1);
    p = 0;
    for ( int i = 1; i <= c; i++ ) {
        while ( B[p] > p ) p = B[p];
        L[i] = p;
        p = B[p];
    }

    K %= c;

    if ( K == 0 ) {
        return;
    } else {
        vector<int> X;
        set<int> S;
        for ( int i = L[K]; i < N; i++ ) {
            int a = A[i];
            if ( S.find(a) == S.end() ) {
                S.insert(a);
                X.push_back(a);
            } else {
                for ( int j = X.size() - 1; j >= 0 ; j-- ) {
                    if ( X[j] == a ) {
                        S.erase(X.back());
                        X.pop_back();
                        break;
                    } else {
                        S.erase(X.back());
                        X.pop_back();
                    }
                }
            }
        }
        for ( int i = 0; i < X.size(); i++ ) {
            cout << X[i] << " ";
        }
        cout << "\n";
    }

}

