      if (now_ind >= n) {
        k--;
        now_ind -= n;
      }
    }
    assert(k == 1 || (k == 0 && now_ind == 0));
    return simulate(
      k == 0
      ? n
      : now_ind
    );
  };
  auto calc_cycle[[maybe_unused]] = [&] {
    int now_cycle = 0;
    int now_ind   = 0;
    while (now_ind != n) {
      now_ind = next.at(now_ind);
      if (now_ind > n) {
        now_cycle++;
        now_ind -= n;
      }
    }
    return now_cycle + 1;
  };
  k %= calc_cycle();
  auto ans = calc(k);
  for (auto& x : ans) x++;
  int sz = ans.size();
  for (int i = 0; i < sz; i++) {
    std::cout << (i > 0 ? " " : "") << ans.at(i);
  }
  std::cout << std::endl;
  return 0;
}

