using namespace std;
using ll = long long;

int main(){
	ios_base::sync_with_stdio(false);
	int n;
	ll k;
	cin >> n >> k;
	vector<int> a(n);
	for(int i = 0; i < n; ++i){ cin >> a[i]; }
	const int m = *std::max_element(a.begin(), a.end()) + 1;

	vector<int> last(m);
	for(int i = 0; i < n; ++i){ last[a[i]] = i; }

	vector<int> prev(n);
	for(int i = 0; i < n; ++i){
		prev[i] = last[a[i]];
		last[a[i]] = i;
	}

	vector<int> heads;
	int last_head = 0;
	do {
		const int t1 = (last_head - 1 + n) % n;
		const int s1 = prev[t1];
		if(last_head == 0 || s1 >= t1){
			heads.push_back(s1);
		}
		last_head = s1;
	} while(last_head != 0);
	reverse(heads.begin(), heads.end());

	vector<int> next(n);
	last.assign(m, n);
	for(int i = n - 1; i >= 0; --i){
		next[i] = last[a[i]];
		last[a[i]] = i;
	}

	vector<int> b;
	for(int i = heads[(k - 1) % heads.size()]; i < n; ++i){
		if(next[i] < n){
			i = next[i];
		}else{
			b.push_back(a[i]);
		}
	}
	for(const auto x : b){
		cout << x << " ";
	}
	cout << endl;
	return 0;
}

