const int N = 2e5 + 10;
const int LOG = 55;

int a[N];

int fr[N];
int go[N][LOG];
ll sz[N][LOG];
const ll oo = 1e18 + 10;

ll bigsum(ll a, ll b) {
    ld ret = a + b;
    if (ret > oo)
        return oo;
    return a + b;
}
int n;

ll dist(int l, int r) {
    if (l >= r) {
        return n - l + r;
    }
    return r - l;
}

void smain() {

    ll k;
    cin >> n >> k;
    fori (i, n) {
        cin >> a[i];
        if (a[i] != a[0] && fr[a[i]] == 0) {
            fr[a[i]] = i;
        }
    }

    for (int i = n - 1; i >= 0; --i) {
        go[i][0] = (fr[a[i]] + 1) % n;
        sz[i][0] = dist(i, fr[a[i]]) + 1;
        fr[a[i]] = i;
    }

    for (int h = 1; h < LOG; ++h) {
        for (int i = 0; i < n; ++i) {
            go[i][h] = go[go[i][h - 1]][h - 1];
            sz[i][h] = bigsum(sz[i][h - 1], sz[go[i][h - 1]][h - 1]);
        }
    }


    int j = 0;
    ll need = n * k;
    while (true) {
        bool ok = false;
        for (int h = LOG - 1; h >= 0; --h) {
            if (sz[j][h] <= need) {
                need -= sz[j][h];
                j = go[j][h];
                ok = true;
                break;
            }
        }
        if (!ok)
            break;
    }

    set<int> have;
    vi cur;
    for (; j < n; ++j) {
        if (have.count(a[j])) {
            while (have.count(a[j])) {
                have.erase(cur.back());
                cur.pop_back();
            }
        } else {
            cur.push_back(a[j]);
            have.insert(a[j]);
        }
    }

    for (auto x : cur) {
        cout << x << ' ';
    }
}

