int main()
{
	ios::sync_with_stdio(false);

	int n;
	ll k;
	cin >> n >> k;
	vector<int> a(n), next(n,-1);
	for(int i=0; i<n; ++i)
		cin >> a[i];

	int last[200111] = {0};
	for(int i=0; i<2*n; ++i)
	{
		if(last[a[i%n]])
		{
			next[(last[a[i%n]] - 1)%n] = i%n;
		}

		last[a[i%n]] = i+1;
	}
	dprint(next);

	vector<Lead> leads;
	leads.push_back({0,0});

	while(1)
	{
		int j = next[leads.back().i];
		int step = (j - leads.back().i);
		if(step <= 0)
			step += n;
		j = (j+1)%n;
		leads.push_back({j,leads.back().step + step+1});
		if(j == leads[0].i)
			break;
	}

	for(auto l : leads)
	{
		dprint(l.i, l.step);
	}

	ll period = leads.back().step;
	leads.pop_back();
	ll nk = (n*k-1) % period;

	//ll last_step = 0;
	Lead last_lead = {-1,0};
	for(Lead x : leads)
	{
		if(nk < x.step)
			break;

		last_lead = x;
	}

	dprint(nk, period, last_lead.step);

	int last2[200111] = {0};
	vector<int> ans;
	//ans.push_back(a[last_lead.i]);
	for(int i=last_lead.step; i<=nk; ++i)
	{
		int j = (last_lead.i + i - last_lead.step)%n;
		if(last2[a[j]])
			ans.resize(last2[a[j]]-1);
		else
		{
			ans.push_back(a[j]);
			last2[a[j]] = ans.size();
		}
	}

	for(int i=0; i<ans.size(); ++i)
		cout << ans[i] << " ";
	cout << "\n";

	return 0;
}

