set<int> ex;

bool us[MAX];
vector<int> ret;
void make(int star,long long int A){
	while(A--){
		if(us[v[star]]){
			while(true){
				us[ret.back()]=false;
				int z=ret.back();
				ret.pop_back();
				if(z==v[star]){
					break;
				}
			}
		}
		else{
			us[v[star]]=true;
			ret.push_back(v[star]);
		}
		star++;
		star%=n;
	}
	for(int i=0;i<ret.size();i++){
		if(i)printf(" ");
		printf("%d",ret[i]);
	}
	puts("");
	exit(0);
}

int main(){
	cin>>n>>k;
	for(int i=0;i<n;i++){
		int a;
		scanf("%d",&a);
		v.push_back(a);
	}
	for(int i=0;i<n;i++){
		v.push_back(v[i]);
	}
	for(int i=v.size()-1;i>=0;i--){
		if(i<n){
			int nex=mp[v[i]];
			nex++;
			len[i]=nex-i;
		}
		mp[v[i]]=i;
	}
	int pos=0;
	long long int len2=0;
	long long int A=n*k;
	while(true){
		ex.insert(pos);
		c.push_back(pos);
		if(A-len[pos]<=0){
			make(pos,A);
		}
		len2+=len[pos];
		A-=len[pos];
		pos+=len[pos];
		pos%=n;
		if(ex.count(pos)==0){
			continue;
		}
		long long int w=len2;
		for(int j=0;j<c.size();j++){
			if(c[j]==pos)break;
			w-=len[pos];
		}
		A%=w;
		if(A<n){
			make(pos,A);
		}
		break;
	}
	len2=0;
	ex.clear();
	c.clear();
	while(true){
		ex.insert(pos);
		c.push_back(pos);
		if(A-len[pos]<=0){
			make(pos,A);
		}
		len2+=len[pos];
		A-=len[pos];
		pos+=len[pos];
		pos%=n;
		if(ex.count(pos)==0){
			continue;
		}
		long long int w=len2;
		for(int j=0;j<c.size();j++){
			if(c[j]==pos)break;
			w-=len[pos];
		}
		A%=w;
		make(pos,A);
		break;
	}
	return 0;
}

