using namespace std;

typedef long long ll;
const int N = 4e5 + 10;
ll n, k, a[N], nxt[N], lst[N], stk[N], top;
bool vis[N], used[N];

void bao(int x, int step) {
    rep(i, 1, step) {
        if (!used[a[x]]) used[a[x]] = 1, stk[++top] = a[x];
        else {
            while (stk[top] != a[x]) used[stk[top]] = 0, --top;
            used[a[x]] = 0; --top;
        }
        x = x % n + 1;
    }
    rep(i, 1, top) printf("%lld ", stk[i]); puts("");
}

void solve(int st, ll step) {
    while (nxt[st] - st + 1 <= step) {
        step -= nxt[st] - st + 1;
        st = nxt[st] % n + 1;
    }
    bao(st, step);
}

int main() {
    cin >> n >> k;
    rep(i, 1, n) scanf("%lld", &a[i]);
    for (int i = n; i >= 1; i--) lst[a[i]] = i + n;
    for (int i = n; i >= 1; i--) nxt[i] = lst[a[i]], lst[a[i]] = i;

    int x = 1;
    ll sum = 0;
    while (!vis[x]) {
        vis[x] = 1, sum += nxt[x] - x + 1;
        x = nxt[x] % n + 1;
    }

    int y = x;
    ll len = 0;  // 循环节长度
    while (1) {
        len += nxt[x] - x + 1;
        x = nxt[x] % n + 1;
        if (x == y) break;
    }

    if (n * k <= sum) solve(1, n * k);
    else solve(y, (n * k - sum) % len);
    return 0;
}

