const int MaxA = 200005;

int main() {
  ll n = IN, k = IN;
  auto a = IN.vi(n);
  VVI go(MaxA);
  rep(i, n) go[a[i]].push_back(i);
  VI epoch(n, -1);
  int now = 0, at = 0;
  while (epoch[at] == -1) {
    epoch[at] = now;
    auto it = upper_bound(all(go[a[at]]), at);
    if (it == go[a[at]].end()) {
      now++;
      it = go[a[at]].begin();
    }
    at = *it + 1;
    if (at >= n) {
      now++;
      at -= n;
    }
  }
  debugv(epoch); debug(now); debug(at);
  auto simulate = [&](int from){
    debug("simulate"); debug(from);
    VI s; VB done(MaxA);
    rep(i, from, n)
      if (done[a[i]]) {
        while (s.back() != a[i]) done[s.back()] = false, s.pop_back();
        s.pop_back();
        done[a[i]] = false;
      } else s.push_back(a[i]), done[a[i]] = true;
    OUT.range(s);
    exit(0);
  };
  rep(i, n) if (epoch[i] == k-1) simulate(i);
  k -= epoch[at];
  k %= now - epoch[at];
  if (k == 0) k = now - epoch[at];
  int tar = epoch[at] + k - 1;
  debug(tar);
  rep(i, n) if (epoch[i] == tar) simulate(i);
}

