void solve() {
  i64 N, K; cin >> N >> K;
  vi32 A(N); cin >> A;
  vi32 a;
  {
    int cnt = 1;
    int prev = A[0];
    reps(i, N - 1) {
      if (A[i] == prev) cnt++;
      else {
        if (cnt % 2 == 1) a.push_back(prev);
        cnt = 1;
        prev = A[i];
      }
    }
    if (cnt % 2 == 1) a.push_back(prev);
  }
  int n = a.size();
  if (n == 0) {
    cout << "" << '\n';
    return;
  }
  vi32 next(n, -1);
  {
    map<int, int> ma;
    rep(i, n) {
      if (ma.count(a[i])) {
        next[ma[a[i]]] = i;
      }
      ma[a[i]] = i;
    }
    map<int, int> me;
    rep(i, n) {
      if (next[i] != -1 && me.count(a[i]) == 0) {
        me[a[i]] = i;
      } else if (next[i] == -1) {
        if (me.count(a[i])) {
          next[i] = -me[a[i]];
        } else {
          next[i] = -ma[a[i]];
        }
      }
    }
  }
  vi32 sta;
  unordered_set<int> se;
  sta.push_back(0);
  se.insert(0);
  int now = 0;
  while (true) {
    bool fin = false;
    while (next[now] > 0) {
      now = next[now];
      now = (now + 1) % n;
      if (now == 0) {
        fin = true;
        break;
      }
    }
    if (fin) break;
    now = -next[now];
    now = (now + 1) % n;
    if (se.count(now) > 0) break;
    sta.push_back(now);
    se.insert(now);
  }
  now = sta[(K - 1) % sta.size()];
  vi32 ans;
  while (now < n) {
    if (next[now] > 0) {
      now = next[now];
      now++;
    } else {
      ans.push_back(a[now++]);
    }
  }
  cout << ans << '\n';
}

