#define ll long long 
const int MAXN = 2e5 + 5;

int n;
ll k;
int a[MAXN], nex[MAXN];
vector<ll> drainTime;
int ans[MAXN];
int cnt[MAXN];

map<int,int> lis;

int main(){
	scanf("%d %lld", &n, &k);
	for(int i = 0; i < n; ++i){
		scanf("%d", &a[i]);
	}
	for(int j = 0; j < 2; ++j)
	for(int i = 0; i < n; ++i){
		if(lis.count(a[i])){
			nex[lis[a[i]]] = i;
		}
		lis[a[i]] = i;
	}
	// Simulate pattern
	drainTime.push_back(0);
	ll pos = 0, tmp = 0;
	do{
		if(nex[pos] > pos){
			tmp += nex[pos]-pos+1;
		}else{
			tmp += nex[pos]-pos+n+1;
		}
		drainTime.push_back(tmp);
		//printf("Add %lld\n", tmp);
		pos = (nex[pos]+1)%n;
	} while(pos != 0);

	ll tot = k*n;
	tot = tot%drainTime.back();
	//printf("Rem moves = %lld\n", tot);
	ll startTime = *(upper_bound(drainTime.begin(), drainTime.end(), tot)-1);
	ll startPos = ((startTime%n)-1+n)%n;
	tot -= startTime;
	//printf("Rem = %lld %lld\n", tot, startPos);

	lis.clear();
	int finalPos = 0;
	while(tot--){
		startPos = (startPos+1)%n;
		if(cnt[a[startPos]] > 0){
			while(cnt[a[startPos]] > 0){
				--finalPos;
				--cnt[ans[finalPos]];
			}
		}else{
			ans[finalPos++] = a[startPos];
			++cnt[a[startPos]];
		}
	}
	for(int i = 0; i < finalPos; ++i){
		if(i)
			printf(" ");
		printf("%d", ans[i]);
	}
	printf("\n");
}

