    doubling[0][i] = parent[i] + 1 - i;
    // printf("doubling[0][%d]=%lld\n", i, doubling[0][i]);
  }
  for (int i=1; i<58; i++) {
    for (int j=0; j<N; j++) {
      long long dst = doubling[i-1][j] + j;
      long long step = doubling[i-1][dst%N];
      doubling[i][j] = doubling[i-1][j] + step; 
    }
  }
  long long sum = 0;
  int now = 0;
  for (int i=58-1; i>=0; i--) {
    // printf("doubling[%d][%d]=%lld\n", i, now, doubling[i][now]);
    if (sum + doubling[i][now] <= K * N) {
      sum += doubling[i][now];
      now = (now + doubling[i][now]) % N;
      // printf("i=%d, now=%d, sum=%lld\n", i, now, sum);
    }
  }
  // printf("sum=%lld\n", sum);
  long long remain = K*(long long )N - sum;
  now = sum % N;
  std::vector<int > ans;
  std::map<int, int> mp;
  // printf("now=%d, remain=%lld\n", now, remain);
  for (int i=0; i<remain; i++) {
    int pos = (now + i) % N;
    if (mp[A[pos]]==1) {
      while(ans[ans.size()-1]!=A[pos]) {
        mp[A[ans[ans.size()-1]]] = 0;
        ans.pop_back();
      }
      mp[A[ans[ans.size()-1]]] = 0;
      ans.pop_back();
    } else {
      ans.push_back(A[pos]);
      mp[A[pos]]=1;
    }
  }
  for (int p : ans) {
    std::cout << p << std::endl;
  }
  return 0;
}

