  vi ans;
  vector<set<Int> > VS;
  Solver() {}
  void input() {
    cin >> N >> K;
    A = vi(N);
    FOR(a, A)cin >> a;
  }
  void solve() {
    if(N == 1){
      if(K % 2 == 0){
        return;
      }
      ans.push_back(A[0]);
      return;
    }
    VS = vector<set<Int>>(2 * Int(1e5) + 1);
    // VS = vector<set<Int>>(3 * 100000 + 1);
    rep(i, N){
      VS[A[i]].insert(i);
    }

    vi path = {0};
    {
      set<Int> visited;
      Int now = 0;

      while (visited.count(now) == 0) {
        visited.insert(now);
        bool loopFlag = 0;
        auto it = VS[A[now]].upper_bound(now);
        if (it == VS[A[now]].end()) {
          it = VS[A[now]].begin();
          loopFlag= true;
        }
        now = (*it + 1)%N;
        if(now == 0){
          break;
        }
        if(loopFlag){
          path.push_back(now);
        }
      }
    }

    K--;
    dump(path);
    pp(path.size());
    K %= path.size();

    Int start = path[K];
    pp(start);
    REP(i, start, N){
      auto it = VS[A[i]].upper_bound(i);
      if(it == VS[A[i]].end()){
        ans.push_back(A[i]);
      }else{
        i = *it;
      }
    }
    if(path.size() == N){
      ans.clear();
    }
  }
  void output() {
    string sep = "";
    FOR(a, ans){
      cout << sep << a;
      sep = " ";
    }
    cout <<endl;
  }
};

