		cin >> x[i];
	}

	// 初期状態をDPに保存
	dp.push_back(vector<int>());

	for (int i = 1; i <= k; i++) {
		for (int j = 0; j < n; j++) {
			auto itr = find(s.begin(), s.end(), x[j]);	// 検索
			if (itr == s.end()) {						// データがない場合
				s.push_back(x[j]);						// sの末尾に追加
			}
			else {										// データがある場合
				s.erase(itr, s.end());					// sの該当部分を削除
			}
		}
		if (s.empty()) {
			for (int j = 0; j < dp[k % i].size(); j++) {
				ans.push_back(dp[k % i][j]);
			}
			breaked = true;
			break;
		}
		else {
			dp.push_back(s);
		}
	}

	if (breaked) {
		for (int i = 0; i < ans.size(); i++)
			cout << ans[i] << " ";
	}
	else {
		for (int i = 0; i < s.size(); i++)
			cout << s[i] << " ";
	}

	cout << endl;

	return 0;

}

