#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int Maxn = 200005;

int n;
ll k;
int a[Maxn];
int nxt[Maxn];
int fir[Maxn];
int tim[Maxn];
vector <int> res;

void Solve(int v, ll cur, ll k)
{
    while (cur < k) {
        int jump = nxt[v] <= v? 1: 0;
        int u = (nxt[v] + 1) % n;
        if (cur + jump < k) {
            if (u == 0) jump++;
            cur += jump; v = u;
        } else {
            res.push_back(a[v]);
            if (v == n - 1) cur++;
            v = (v + 1) % n;
        }
    }
    for (int i = 0; i < res.size(); i++)
        printf("%d%c", res[i], i + 1 < res.size()? ' ': '\n');
}

int main()
{
    scanf("%d %lld", &n, &k);
    for (int i = 0; i < n; i++)
        scanf("%d", &a[i]);
    for (int i = 0; i < Maxn; i++)
        fir[i] = n;
    for (int i = n - 1; i >= 0; i--) {
        nxt[i] = fir[a[i]];
        fir[a[i]] = i;
    }
    for (int i = 0; i < n; i++)
        if (nxt[i] == n) nxt[i] = fir[a[i]];
    if (k <= 2 * n + 10) Solve(0, 0, k);
    else {
        for (int i = 0; i < Maxn; i++)
            tim[i] = Maxn;
        int v = 0, cur = 0;
        while (tim[v] == Maxn) {
            tim[v] = cur;
            int jump = nxt[v] <= v? 1: 0;
            if (nxt[v] == n - 1) { jump++; v = 0; }
            else v = nxt[v] + 1;
            cur += jump;
        }
        ll my = (k - 1 - tim[v]) / (cur - tim[v]) * (cur - tim[v]);
        Solve(v, my, k);
    }
    return 0;
}

