        d += (K - d) / (d - dist[now]) * (d - dist[now]);
        while(d < K){
            auto t = next[now] + 1;
            if(t >= N){
                d += t / N;
                t %= N;
            }
            if(d == K)break;
            now = t;
        }
        unordered_map<unsigned long, unsigned long> mp;
        for(; now < N; ++now){
            const auto a = A[now];
            if(mp[a]){
                while(ans.back() != a)ans.pop_back();
                ans.pop_back();
            }else{
                ans.push_back(a);
            }
            mp[a] ^= 1;
        }
    }
    copy(ans.begin(), ans.end(), ostream_iterator<unsigned long>(cout, " "));
    return 0;
}

