struct NextHead {
	int index, step;
	NextHead() {};
	NextHead(const int i, const int s) : index{ i }, step{ s }{};
};
std::vector<NextHead> cal_next(const std::vector<int>& series) {
	std::vector<int> prev_index(2000000 + 1, -1);
	std::vector<NextHead> result(series.size());
	for (auto i = 0; i < series.size(); ++i) {
		if (prev_index[series[i]] != -1) {
			result[prev_index[series[i]]] = NextHead((i + 1) % series.size(), i - prev_index[series[i]] + 1 );
		}
		prev_index[series[i]] = i;
	}
	for (auto i = 0; i < series.size(); ++i) {
		if (prev_index[series[i]] != -1) {
			result[prev_index[series[i]]] = NextHead( (i + 1) % series.size(), (i == prev_index[series[i]]) ? series.size() + 1 : (i - prev_index[series[i]] + 1 + series.size()) % series.size() );
			prev_index[series[i]] = -1;
		}
	}
	return result;
}
int main() {
	int n; long long int k; std::cin >> n >> k;
	k *= n;
	std::vector<int> series(n); for (auto& s : series) std::cin >> s;
	std::vector<NextHead> nexts = cal_next(series);
	std::vector<long long int> loop_count(n, -1);
	int current = 0;
	long long int current_step = 0LL;
	while (loop_count[current] == -1 && current_step + nexts[current].step <= k) {
		loop_count[current] = current_step;
		current_step += nexts[current].step;
		current = nexts[current].index;
	}
	long long int rest = k - current_step;
	if (loop_count[current] != -1) {
		rest %= current_step - loop_count[current];
	}
	std::set<int> set;
	std::vector<int> result;
	for (auto i = 0; i < rest; ++i) {
		if (set.find(series[current]) == set.end()) {
			set.insert(series[current]);
			result.push_back(series[current]);
		}
		else {
			while (result.back() != series[current]) {
				set.erase(result.back());
				result.pop_back();
			}
			set.erase(result.back());
			result.pop_back();
		}
		current = (current + 1) % series.size();
	}
	for (auto i = 0; i < result.size(); ++i) {
		if (i != 0) std::cout << ' ';
		std::cout << result[i];
	}
	std::cout << std::endl;
}

