        np = node[np].to;
    }while (np != 1);
    //cout << mod << endl;
    int tmp = (K-1) % mod;
    int now = 1;
    while (now <= n) {
        if (node[now].c == 1) {
            if (tmp > 0) now = node[now].to, --tmp;
            else {
                if (node[now].to != 1 || now == n) ans.pb(a[now]), ++now;
                else break;
            }
        }
        else now = node[now].to;
    }
    for (auto i: ans) cout << i << " ";
    return 0;
}

