	stack<int> s;
	int loop = 0;
	stack<int> res[100000];
	while (true) {
		rep(i, N)
	    {
	    	if (dup[A[i]] > 0) {
	    		while (true) {
					int t = s.top();
	    			if (t == A[i]) {
	    				s.pop();
						dup[t] = 0;
	    				break;
	    			}
	    			s.pop();
					dup[t] = 0;
	    		}
	    	} else {
	    		dup[A[i]]++;
	    		s.push(A[i]);
	    	}
	    }
		loop++;
		stack<int> d;
		stack<int> temp;
		copy_s_t(s, d, temp);
		copy_s(temp, s);
		res[loop] = d;
		if (s.size() == 0) {
			break;
		}
	}
	stack<int> res_st = res[K % loop];
	while (!res_st.empty()) {
		if (res_st.size() != 1) {
