void solve(istream& input, ostream& output) {
	int N; cin >> N;
	ll K; cin >> K;
	vector<int> A(N);
	for (int i = 0; i < N; i++) cin >> A[i];
	vector<int> nextA(N);
	{
		vector<set<int>> pos(200001);
		for (int i = 0; i < N; i++) pos[A[i]].insert(i);
		for (int i = 0; i < N; i++) pos[A[i]].insert(i+N);
		for (int i = 0; i < N; i++) {
			nextA[i] = *(++pos[A[i]].lower_bound(i)) - i;
		}
	}
	vector<vector<ll>> dp(50, vector<ll>(N));
	for (int i = 0; i < N; i++) {
		dp[0][i] = nextA[i] + 1;
	}
	for (int i = 1; i < 50; i++) {
		for (int j = 0; j < N; j++) {
			int p = (j + dp[i-1][j]) % N;
			dp[i][j] = dp[i-1][j] + dp[i-1][p];
			assert(dp[i][j] > 0);
		}
	}
	ll p = 0;
	for (int i = 49; i >= 0; i--) {
		if (p + dp[i][p % N] <= N * K) p += dp[i][p % N];
		assert(p >= 0);
	}
	set<int> num;
	vector<int> res;
	for (; p < N*K; p++) {
		int n = A[p%N];
		if (num.count(n)) {
			while (num.count(n)) {
				num.erase(res.back());
				res.pop_back();
			}
		} else {
			num.insert(n);
			res.push_back(n);
		}
	}
	for (int i = 0; i < (int) res.size(); i++) {
		if (i) cout << " ";
		cout << res[i];
	}
	cout << endl;
}

