#include <bits/stdc++.h>
using namespace std;
const int MAXN = 200005;
int N, A[MAXN], nxt[MAXN], prv[MAXN], vis[MAXN];
long long K;
int main()
{
	cin>>N>>K; 
	for(int i = 0; i < N; i++)
		cin>>A[i];
	memset(prv, -1, sizeof prv);
	for(int i = 0; i < 2 * N; i++)
	{
		if(prv[A[i % N]] != -1)
			nxt[prv[A[i % N]]] = i % N;//第二次出现的位置 
		prv[A[i % N]] = i % N;//第一次出现的位置 
	}
	vector <int> ans;
	memset(vis, -1, sizeof vis);
	int j = 0, k = 0;
	while(k < K)
	{
		//如果就在后面，不需要再来一遍 
		if(nxt[j] > j)
		{
			//直接变过去 
			j = nxt[j] + 1;
			if(j >= N)//超过长度了，次数记得加以，重新循环 
			{
				j -= N;
				k++;
			}
		}
		else//说明到了 下一次循环 
		{
			if(k + 1 < K)//先判断 是否要退出 ，先进行不会退出的 
			{
				j = nxt[j] + 1;//退出当前环 
				k++;//循环次数++ 
				if(j >= N)//这个时候也能要进行下一次循环 
				{
					j -= N;
					k++;
				}
			}
			else//说明要退出 
			{
				ans.push_back(A[j]);
				j = j + 1;//这个时候要一点一点往下推进 
				if(j >= N)
					break;
			}
		}
		//判断这个 位置 是否出现过，作为循环的起点 ，如果出现过的话，就是一次彻底的循环 
		if(vis[j] != -1)
		{
			int d = k - vis[j];//此时的循环 - 出现时的循环次数 
			K = k + (K - k) % d;//还需要的次数 
		}
		vis[j] = k;//记录第一次出现时的循环次数 
	}
	for(auto x : ans)
		cout<<x<<" "; 
	return 0;
}

