set<long long> pl[214514];
set<ll> fp[214514];
ll dp[214514][62];
long long n;
ll gbis_special(ll cur, ll lim){
	if( cur + dp[ (cur%n) ][0] > lim) return cur;
	ll cnt = 0;
	while( cur + dp[ (cur%n) ][cnt+1] <= lim && cnt<=49){
		cnt++;
	}
	cur += dp[ (cur%n) ][cnt];
	return gbis_special(cur,lim);
}
signed main(){
	ll k;
	cin>>n>>k;
	vector<long long> a;
	for(long long i=0;i<n;i++){
		long long x;
		cin>>x;
		a.pb(x);
		pl[x].insert(i);
	}
	for(long long i=0;i<n;i++){
		long long cur = a[i];
		set<long long>::iterator it = pl[cur].upper_bound(i);
		if( it == pl[cur].end() ){
			it = pl[cur].upper_bound(-1);
			dp[i][0] = *it + n - i + 1;
		}
		else{
			dp[i][0] = *it - i + 1;
		}
	}
	for(long long j=1;j<=50;j++){
		for(long long i=0;i<n;i++){
			dp[i][j] = dp[i][j-1] + dp[ (ll)(i+dp[i][j-1])%n ][j-1];
		}
	}
	ll stt = gbis_special(0,n*k-1);
	vector<ll> final;
	for(ll i=stt;i<=n*k-1;i++){
		final.pb(a[(ll)i%n]);
		fp[a[(ll)i%n]].insert(i);
	}
	ll idx = stt;
	vector<ll> ans;
	while(idx <= n*k-1){
		ll cur = final[idx-stt];
		set<ll>::iterator it = fp[cur].upper_bound(idx);
		if( it == fp[cur].end() ){
			ans.pb(cur);
			idx++;
		}
		else{
			idx = *it;
			idx++;
		}
	}
	for(long long i=0;i<ans.size();i++){
		cout<<ans[i]<<" ";
	}
	cout<<endl;
	return 0;
}

