#include <bits/stdc++.h>
using namespace std;
#define ll long long
const int N=200050;
const int L=61;
const ll inf=1e18;
int go[N][L];
ll sum[N][L];
int a[N],last[N];
bool in[N];
bool was[N];
int main()
{
	ll n,k;
	scanf("%lld %lld",&n,&k);
	for(int i=1;i<=n;i++)
	{
		scanf("%i",&a[i]);
		if(!last[a[i]]) last[a[i]]=i;
	}
	auto nxt=[&](int x)
	{
		return x==n?1:x+1;
	};
	for(int i=n;i>=1;i--)
	{
		go[i][0]=nxt(last[a[i]]);
		if(!was[a[i]] || go[i][0]==1) sum[i][0]=1;
		last[a[i]]=i;
		was[a[i]]=1;
	}
	for(int j=1;j<L;j++) for(int i=1;i<=n;i++)
	{
		go[i][j]=go[go[i][j-1]][j-1];
		sum[i][j]=sum[i][j-1]+sum[go[i][j-1]][j-1];
		sum[i][j]=min(sum[i][j],inf);
	}
	int u=1;
	for(int j=L-1;~j;j--)
	{
        if(sum[u][j]<k)
		{
			k-=sum[u][j];
			u=go[u][j];
		}
	}
	vector<int> ans;
	for(int i=u;i<=n;i++)
	{
		if(in[a[i]])
		{
			in[a[i]]=0;
			while(ans.back()!=a[i]) in[ans.back()]=0,ans.pop_back();
			ans.pop_back();
		}
		else ans.push_back(a[i]),in[a[i]]=1;
	}
	for(int i:ans) printf("%i ",i);
	return 0;
}

#include<bits/stdc++.h>
#define ll long long

using namespace std;

const int N = 2e5+1;

int n;
int a[N];
ll k;
int fst[N], lst[N], nxt[N];
int cnt;
int used[N];
vector<int> s;

int rgt(int i){
    return (i == n-1 ? 0 : i+1);
}

bool has[N];
vector<int> ans;
void iterate(int p){
    for(int i = p; i < n; ++i){
        if(has[a[i]]){
            while(has[a[i]]){
                has[ans.back()] = false;
                ans.pop_back();
            }
        }
        else{
            has[a[i]] = true;
            ans.push_back(a[i]);
        }
    }
}

int main(){
    ios_base::sync_with_stdio(false);
    cout.tie(0);
    cin.tie(0);
    cin >> n >> k;
    for(int i = 0; i < N; ++i)
        fst[i] = lst[i] = -1;
    for(int i = 0; i < n; ++i)
        cin >> a[i];
    for(int i = 0; i < n; ++i){
        if(fst[a[i]] == -1)
            fst[a[i]] = i;
        else nxt[lst[a[i]]] = i;
        lst[a[i]] = i;
    }
    for(int i = 0; i < N; ++i)
        if(lst[i] != -1)
            nxt[lst[i]] = fst[i];
    s.push_back(0);
    used[0] = ++cnt;
    int i = 0;
    int res = -1;
    while(true){
        int j = rgt(nxt[i]);
        if(j <= i+1){
            if(used[j]){
                res = used[j]-1;
                break;
            }
            s.push_back(j);
            used[j] = ++cnt;
        }
        i = j;
    }
    vector<int> prevperiod, period;
    for(int i = 0; i < res; ++i)
        prevperiod.push_back(s[i]);
    for(int i = res; i < s.size(); ++i)
        period.push_back(s[i]);
    --k;
    if(k < prevperiod.size())
        iterate(prevperiod[k]);
    else iterate(period[(k-prevperiod.size())%period.size()]);
    for(int el : ans)
        cout << el << ' ';
    cout << '\n';
}

