			if (pos[a[i]].back() == i) continue;
			no[i] = true;
			auto it = std::upper_bound(ALL(pos[a[i]]), i);
			ne[i] = ne[*it + 1];
		}
	}

	RREP(i, n) {
		if (pos[a[i]].size() >= 2) {
			if (pos[a[i]].back() == i) {
				int t = pos[a[i]].front() + 1;
				if (no[t]) ne[i] = ne[t];
				else ne[i] = t;
			}
		}
		else {
			if (no[i + 1]) ne[i] = ne[i + 1];
			else ne[i] = i + 1;
		}
	}

