			set.erase(t);
		}
	}

	V<int> ans;
	while (!st.empty()) {
		ans.emplace_back(st.top()); st.pop();
	}

	std::reverse(ALL(ans));
	REP(i, ans.size()) {
		OUT(ans[i] + 1)SPBR(i, ans.size());
	}

	return 0;
}

