int n;
ll k;
int a[100005];
ll nx[65][100005];
void solve() {
    cin >> n >> k;

    map<int, vector<int>> idx;
    rep(i, n) {
        cin >> a[i];
        idx[a[i]].push_back(i);
    }

    for (auto& v : idx) {
        v.second.push_back(v.second[0] + n);

        rep(i, v.second.size() - 1) {
            nx[0][v.second[i]] = v.second[i + 1] - v.second[i] + 1;
        }
    }

    rep(i, 62) rep(j, n) {
        nx[i + 1][j] = min(inf, nx[i][j] + nx[i][(j + nx[i][j]) % n]);
    }

    ll now = 0;
    repd(i, 62) {
        if (now + nx[i][now % n] <= k * n)
            now += nx[i][now % n];
    }

    if (now == k * n) return;

    set<int> s;
    vector<int> ans;
    loop(i, now % n, n) {
        if (s.count(a[i]) == 0) {
            s.insert(a[i]);
            ans.push_back(a[i]);
        }
        else {
            int cur = ans.size() - 1;
            while (ans[cur] != a[i]) {
                s.erase(ans[cur]);
                ans.pop_back();
                --cur;
            }
            s.erase(a[i]);
            ans.pop_back();
        }
    }

    rep(i, ans.size()) cout << ans[i] << " ";
    cout << endn;

}

