        mp[a[i]].push_back(i);
    }
    for (auto kv : mp) {
        auto v = kv.second;
        for (int i = 0; i < v.size(); i++) {
            if (i == v.size() - 1) {
                if (v[0] == N - 1) {
                    g[v[i]] = 0;
                } else {
                    g[v[i]] = v[0] + 1;
                }
            } else {
                if (v[i + 1] == N - 1) {
                    g[v[i]] = 0;
                } else {
                    g[v[i]] = v[i + 1] + 1;
                }
            }
        }
    }
    set<int> st;
    int prev = 0;
    int loop_ind;
    int loop_dist = 0;
    st.insert(0);
    while (1) {
        if (g[prev] > prev) {
            loop_dist += g[prev] - prev;
        } else {
            loop_dist += (N - prev) + g[prev];
        }
        if (st.count(g[prev]) == 1) {
            loop_ind = g[prev];
            break;
        } else {
            st.insert(g[prev]);
            prev = g[prev];
        }
    }
    int start = 0;
    if (loop_ind != 0) {
        prev = 0;
        while (1) {
            if (g[prev] > prev) {
                start += g[prev] - prev;
            } else {
                start += (N - prev) + g[prev];
            }
            if (g[prev] == loop_ind) {
                break;
            } else {
                prev = g[prev];
            }
        }
    }
    loop_dist -= start;
    ans = (N * K - 1 - start) % loop_dist;
    vector<int> res;
    set<int> st1;
    prev = loop_ind + 1;
    if (prev >= N) {
        prev = 0;
    }
    for (int i = 0; i < ans; i++) {
        if (st1.count(a[prev]) == 1) {
            while (a[res[res.size() - 1]] != a[prev]) {
                st1.erase(a[res[res.size() - 1]]);
                res.pop_back();
            }
            st1.erase(a[prev]);
            res.pop_back();
        } else {
            st1.insert(a[prev]);
            res.push_back(prev);
        }
        prev++;
        if (prev >= N) {
            prev = 0;
        }
    }
    for (int i = 0; i < res.size(); i++) {
        cout << a[res[i]];
        if (i == res.size() - 1) {
            cout << endl;
        } else {
