vector<int> go(int N, ll left, const vector<ll> &A, int start) {
    map<ll, int> s;
    vector<int> stk;
    stk.reserve(N);
    for(ll i = start; left > 0; i++, left--) {
        ll a = A[i % N];
        if(s[a] > 0) {
            int sa = s[a];
            while(stk.size() >= sa) {
                s[stk.back()] = 0;
                stk.pop_back();
            }
        } else {
            stk.push_back(a);
            s[a] = stk.size();
        }
        // cerr << i << ": " << stk << endl;
    }
    return stk;
}

