typedef long long LL;
const int M = 200007;

int n; LL m;
int fir[M], las[M], nxt[M];
int jp[M], stp[M], ans[M];
int a[M];

LL getloop() {
	int x = 1;
	LL res = 0;
	do {
		res += stp[x];
		x = jp[x];
	} while(x != 1);
	return res;
}

int main() {

	std::ios::sync_with_stdio(false);
	std::cin >> n >> m;
	LL s = n * m;

	for (int i = 1; i <= n; ++i) std::cin >> a[i];
	for (int i = 1; i <= n; ++i) if (!fir[a[i]]) fir[a[i]] = i;
	for (int i = n; i >= 1; --i) {
		if (!las[a[i]]) {
			nxt[i] = fir[a[i]];
		}
		else nxt[i] = las[a[i]];
		las[a[i]] = i;
	}
	for (int i = 1; i <= n; ++i) {
		jp[i] = nxt[i] == n ? 1 : nxt[i] + 1;
		stp[i] = nxt[i] > i ? nxt[i] - i + 1 : nxt[i] + n - i + 1;
	}

	LL d = getloop();
	s = s % d;

	int x = 1;
	while (s >= stp[x]) {
		s -= stp[x];
		x = jp[x];
	}
	if (s != 0) {
		memset(las, 0, sizeof las);
		int tot = 0;
		while (s--) {
			if (!las[a[x]]) {
				ans[++tot] = a[x];
				las[a[x]] = tot;
			}
			else {
				tot = las[a[x]] - 1;
				las[a[x]] = 0;
			}
			x = x == n ? 1 : x + 1;
		}
		assert(tot != 0);
		for (int i = 1; i <= tot; ++i) {
			std::cout << ans[i] << (i == tot ? "" : " ");
		}
		std::cout << std::endl;
	}

	return 0;
}

