int main() {
    init();

    int n; ll k; cin >> n >> k;
    VI a(n); cin >> a;

    constexpr int log = 60;
    auto to = vec<int>(log + 1, n);
    auto len = vec<ll>(log + 1, n);
    map<int, VI> m;
    FOR(i, 0, n)m[a[i]].push_back(i);
    each(i, m)FOR(j, 0, i.second.size()) {
        int x = i.second[j];
        int y = i.second[(j + 1) % int(i.second.size())];
        to[0][x] = (y + 1) % n;
        len[0][x] = x < y ? y - x + 1 : y + n - x + 1;
    }
    FOR(i, 0, log)FOR(j, 0, n) {
        to[i + 1][j] = to[i][to[i][j]];
        len[i + 1][j] = len[i][j] + len[i][to[i][j]];
    }
    function<pair<int, ll>(ll)> check = [&](ll x)->pair<int, ll> {
        pair<int, ll> ret{ 0,0 };
        for (int i = 0; x; ++i, x >>= 1) {
            if (x & 1) {
                ret.second += len[i][ret.first];
                ret.first = to[i][ret.first];
            }
        }
        return ret;
    };

    ll g = 0;
    FOR(i, 0, n)g += len[0][i];

    ll ok = 0, ng = n * k / g + 2;
    while (ng - ok > 1) {
        ll mid = ok + ng >> 1;
        if (check(mid).second <= n * k)ok = mid;
        else ng = mid;
    }

    map<int, int> used;
    VI ans;
    pair<int, ll> res = check(ok);
    FOR(i, res.first, res.first + n * k - res.second) {
        int x = a[i % n];
        if (0 < used[x]) {
            while (used[x]) {
                --used[ans.back()];
                ans.pop_back();
            }
        }
        else {
            ++used[x];
            ans.push_back(x);
        }
    }
    print(ans);

    return 0;
}

