using namespace std;
typedef long long ll;
typedef vector<int> vi;
typedef vector<ll> vll;
typedef pair<int, int> P;
typedef pair<int, pair<int, int> > PP;
const int MAX=2e5+10;

int N;
ll K;
int A[MAX];
vi lis[MAX];

void input(){
  cin>>N>>K;
  rep(i,N){
    cin>>A[i];
    A[i]--;
    lis[A[i]].pb(i);
  }
}
int nex[MAX];
int up[MAX];
vi loop, ct;
int t;
int start;
void solve(){
  rep(j,MAX){
    int s=sz(lis[j]);
    rep(i,s){
      int ind=lis[j][i];
      int nexto=i+1;
      if(nexto==s){
        up[ind]++;
        nexto=0;
      }
      int nextind=lis[j][nexto]+1;
      nex[ind]=nextind%N;
    }
  }
  int tmpind=0;
  int tmpct=0;
  while(true){
    loop.pb(tmpind);
    ct.pb(tmpct);
    tmpct+=up[tmpind];
    tmpind=nex[tmpind];
    if(tmpind==0)break;
  }
  t=tmpct+1;
  ll r=K%(ll)t;
  if(r==0)start=N;
  else{
    rep(i,sz(ct)){
      if((ll)ct[i]>=r)break;
      start=loop[i];
    }
  }
}

deque<int> ans;
bool in[MAX];
void output(){
  for(int i=start; i<N; i++){
    if(in[A[i]]){
      while(true){
        int p=ans.back();
        ans.pop_back();
        if(p==A[i])break;
      }
      in[A[i]]=false;
    }
    else{
      ans.push_back(A[i]);
      in[A[i]]=true;
    }
  }
  while(!ans.empty()){
    cout<<ans.front()+1<<" ";
    ans.pop_front();
  }
}

int main(){
  input();
  solve();
  output();
}

