				}
			}
			else{
				cycles_left--;
			}
		}
		cur = (ne[cur])%n + 1;
		trace(cur, cycles_left, cur);
	}
}

void solve(){
	int k; cin>>n>>k;
	fr(i,1,n){
		cin>>a[i];
