		if((ne[cur])%n + 1 <= cur + 1){
			iter++;
		}
		cur = (ne[cur])%n + 1;
		// trace(cur, iter, cur);
	}
	if(iter == k){
		brute(cur,0);
	}
	else{
		int cycles = iter - vis[cur];
		k -= vis[cur]-1;
		trace(k);
		int cycles_left = (k-1)%cycles;
		trace(cycles_left, iter, vis[cur]);
		trace(cycles_left, cycles, cur, vis[cur]);
		brute(cur, cycles_left);
	}
}

