	for (int i = 0; i < N; ++i) {
		num[A[i]].insert(i);
	}
	vector<int>link(N);
	for (int i = 0; i < N; ++i) {
		auto itr = num[A[i]].find(i);
		++itr;
		if (itr == num[A[i]].end()) {
			itr = num[A[i]].begin();
		}
		link[i] = (*itr + 1) % N;
	}
	unordered_map<int, int> node;	//id,cost
	int pos = 0;
	int next;
	int nextCost;
	while (true) {
		next = link[pos];
		if (next <= pos + 1) {
			nextCost = node[pos] + 1;
		}
		else {
			nextCost = node[pos];
		}
		auto itr = node.find(next);
		if (itr != node.end()) {
			break;
		}
		node[next] = nextCost;
		pos = next;
	}
	int period = nextCost - node[next];
	int offset = node[next];
	if (offset < K) {
		K -= offset;
		K %= period;
		K += offset + period;
	}
	pos = 0;
	int cost = 0;
	while (true) {
		int next = link[pos];
		if (next <= pos + 1) {
			++cost;
		}
		if (cost >= K)break;
		pos = link[pos];
	}
	std::vector<int>res;
	res.reserve(N);
	unordered_set<int>kind;
	for (int i = pos; i < N; ++i) {
		auto itr = kind.find(A[i]);
		if (itr == kind.end()) {
			kind.insert(A[i]);
			res.push_back(A[i]);
		}
		else {
			while (true) {
				int back = res.back();
				res.pop_back();
				kind.erase(back);
				if (back == A[i])break;
			}
		}

	}
	for (int i = 0; i < res.size(); ++i) {
		cout << res[i];
		if (i + 1 != res.size()) {
			cout << " ";
		}
	}
	//
}


