	{
		int add;
		//cout << idx << ' ' << tot << '\n';
		if(viz[idx])
		{
			int rem = n * k - tot;
			int period = tot - b[idx];
			tot = n * k - (rem % period);
			go();
			break;
		}
		viz[idx] = 1;
		b[idx] = tot;
		auto it = upper_bound(vec[a[idx]].begin(),vec[a[idx]].end(),idx);
		if(it == vec[a[idx]].end()) add = n - idx + vec[a[idx]][0];
