template<class T>
vector<T> shrink(vector<T> a, vector<T>& b){
  b = a;
  sort(b.begin(), b.end());
  b.erase( unique(b.begin(), b.end()), b.end());
  for(int i=0; i<(int)a.size(); i++){
    a[i] = lower_bound(b.begin(), b.end(), a[i]) - b.begin();
  }
  return a;
}

void simulate(long long n, long long k, vector<int> A){
  vector<int> v;
  vector<vector<int>> vstack(*max_element(A.begin(), A.end()) + 1);
  for(long long i=0; i<n*k; i++){
    long long x = A[i%n];
    if(vstack[x].size() == 0){
      vstack[x].push_back(v.size());
      v.push_back(x);
    }else{
      long long j = vstack[x].front();
      while(v.size() > j){
        long long y = v.back();
        v.pop_back();
        vstack[y].pop_back();
      }
    }
    eprintln("turn :", i%n, ", v = ", v);
  }
}

long long get_loop(long long n, vector<int>& A, vector<vector<int>>& B, vector<int>& C){
  long long res = 0;
  int head_i = 0;
  for(; ;){
    long long x = A[head_i];
    int tail_i = B[x][(C[head_i] + 1) % B[x].size()];
    long long d = (tail_i - head_i + n) % n;
    if(d == 0) d = n;
    d += 1;
    res += d;
    head_i = (tail_i+1) % n;
    if(head_i == 0){
      break;
    }
  }
  return res;
}

void solve(int head_i, long long n, __int128 k, vector<int>& A, vector<vector<int>>& B, vector<int>& C, vector<int>& ans){
  if(k == 0) return;

  for(; k>0;){
    long long x = A[head_i];
    int tail_i = B[x][(C[head_i] + 1) % B[x].size()];
    long long d = (tail_i - head_i + n) % n;
    if(d == 0) d = n;
    d += 1;

    if(d > k){
      ans.push_back(x);
      solve((head_i+1) % n, n, k-1, A,B,C,ans);
      return;
    }

    k -= d;
    head_i = (tail_i+1) % n;
    if(head_i == 0){
      break;
    }
  }

}

int main(){
  long long n,k;
  cin >> n,k;

  vector<int> a(n);
  cin >> a;

  vector<int> b;
  auto A = shrink<int>(a, b);

  vector<vector<int>> B(b.size());
  vector<int> C(n);
  for(int i=0; i<n; i++){
    B[A[i]].push_back(i);
    C[i] = B[A[i]].size()-1;
  }

  // simulate(n, k, A);

  long long len = get_loop(n, A, B, C);

  eprintln("loop len =", len);

  __int128 K = k;
  K *= n;

  K %= len;
  vector<int> ans;
  solve(0, n, K, A, B, C, ans);

  for(int i=0; i<ans.size(); i++){
    ans[i] = b[ans[i]];
  }

  println(ans);

  return 0;
}

