vector<ll> A(202020);
vector<ll> pos[202020];

ll N, K;

pll next(ll val, ll now){
	ll next_pos, rot;
	auto itr = upper_bound(pos[val].begin(), pos[val].end(), now);
	if(itr == pos[val].end()){
		auto itr2 = upper_bound(pos[val].begin(), pos[val].end(), -1);
		int plc = itr2 - pos[val].begin();
		next_pos = pos[val][plc];
		rot = 1;
	}else{
		int plc = itr - pos[val].begin();
		next_pos = pos[val][plc];
		rot = 0;
	}

	pll res = {next_pos, rot};
	return res;
}

ll get_period(){
	ll P = 0;
	ll now = 0;
	while(1){
		ll val = A[now];
		pll tmp = next(val, now);
		ll next_pos = tmp.first;
		ll rot = tmp.second;

		P += rot;

		if(next_pos == N-1) break;
		now = next_pos+1;
	}
	P++;
	return P;
}

void solve(){
	ll R = 0;
	ll now = 0;

	while(R<K-1){
		ll val = A[now];
		pll tmp = next(val, now);
		ll next_pos = tmp.first;
		ll rot = tmp.second;

		R += rot;
		now = next_pos+1;
	}

	vector<ll> res;
	while(1){
		ll val = A[now];
		pll tmp = next(val, now);
		ll next_pos = tmp.first;
		ll rot = tmp.second;

		if(rot==0){
			now = next_pos+1;
		}else{
			res.push_back(A[now]);
			now = now+1;
		}
		if(now==N) break;
	}

	REP(i, res.size()) cout << res[i]+1 << " ";
	cout << endl;
}

