bitset<MAXN> inv;

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	ll N, K;
	cin >> N >> K;
	for (int i = 0; i < N; ++i) cin >> A[i];

	for (int i = 0; i < N; ++i) p[A[i]].push_back(i);
	for (int i = 0; i < MAXN; ++i) {
		if (!p[i].empty()) {
			for (int j = 0; j < p[i].size() - 1; ++j) nxt[p[i][j]][0] = p[i][j + 1] + 1 - p[i][j];
			nxt[p[i].back()][0] = p[i].front() + N + 1 - p[i].back();
		}
	}

	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < 63; ++j) {
			if (nxt[i][j] <= N * K) nxt[i][j + 1] = nxt[i][j] + nxt[(i + nxt[i][j]) % N][j];
			else nxt[i][j + 1] = N * K + 1;
		}
	}

	ll x = 0;
	while (x < N * K) {
		int i = 63;
		while (i >= 0 && x + nxt[x % N][i] >= N * K) --i;
		if (i < 0) break;
		x += nxt[x % N][i];
	}

