    pos[A[i % N]] = i;
  }
  debugArray(next, N);
  debugArray(cost, N);
  long long dist[N];
  fill(dist, dist + N, -1);
  long long sum = 0;
  int cur = 0, prev = 0;
  while (true) {
    if (dist[cur] != -1) {
      break;
    }
    dist[cur] = sum;
    if (dist[cur] > Y) {
      break;
    }
    sum += cost[cur];
    prev = cur;
    cur = next[cur];
  }
  if (Y < dist[cur]) {
    cur = prev;
    Y -= dist[prev];
  } else {
    Y -= dist[cur];
    Y %= sum - dist[cur];
  }
  fill(dist, dist + N, -1);
  sum = 0;
  while (true) {
    if (dist[cur] != -1) {
      break;
    }
    dist[cur] = sum;
    if (dist[cur] > Y) {
      break;
    }
    sum += cost[cur];
    prev = cur;
    cur = next[cur];
  }
  if (Y < dist[cur]) {
    cur = prev;
    Y -= dist[prev];
  }
  vector<int> s;
  bool exist[M];
  fill(exist, exist + M, false);
  while (Y--) {
    if (exist[A[cur]]) {
      while (s.back() != A[cur]) exist[s.back()] = false, s.pop_back();
      s.pop_back();
      exist[A[cur]] = false;
    } else {
      s.push_back(A[cur]);
      exist[A[cur]] = true;
    }
    cur = (cur + 1) % N;
  }
  for (size_t i = 0; i < s.size(); i++)
    cout << s[i] << (i == s.size() - 1 ? '\n' : ' ');
  return 0;
