vector<ll> divv(ll n) {
  vector<ll> v;
  for(ll i = 1; i*i <= n; i++) {
    if(n%i == 0) {
      v.push_back(i);
      if(i*i != n) v.push_back(n/i);
    }
  }
  sort(ALL(v));
  return v;
}


int main() {
    ll n, k;
    cin>>n>>k;
    vector<ll> a(n);
    cin>>a;
    decltype(a) v;
    bool first = true;
    ll turn = 0;
    auto flg = false;
    rep(i, k){
        rep(j, n){
            auto arg = a[j];
            if(v.empty() && first) {
                v.emplace_back(arg);
                first = false;
            }
            else if(v.empty()){
                v.emplace_back(arg);
            }
            else {
                if(v[0] == arg) v.clear();
                else v.emplace_back(arg);
            }
            if(j == n-1 && v.empty()) {
                turn = i+1;
                flg = true;
                break;
            }
        }
        if(flg) break;
    }
    k = k % turn;
    v.clear();
    rep(i, k){
        rep(j, n){
            auto arg = a[j];
            if(v.empty()) {
                v.emplace_back(arg);
            }
            else {
                if(v[0] == arg) v.clear();
                else v.emplace_back(arg);
            }
        }
    }
    unordered_map<ll, ll> cache;
    reverse(ALL(v));
    decltype(v) an;
    for(auto it : v){
        if(cache[it]>0) {
            an.clear();
            cache[it]=0;
        }else{
            cache[it]=1;
            an.push_back(it);
        }
    }
    reverse(ALL(an));

    prr(an);
}

