using namespace std;

pair<int,int> nxt[200000];
vector<int> P[200000];
int node_cnt, A[200000], num[200000], cnt[200000], idx[200000];
long long K;

int solve(int c, int v)
{
	num[c]=++node_cnt;
	if(v+nxt[c].second==K) return c;
	if(num[nxt[c].first]) {
		K=(K-cnt[nxt[c].first])%(cnt[c]+nxt[c].second-cnt[nxt[c].first]);
		if(K==0) K=cnt[c]+nxt[c].second-cnt[nxt[c].first];
		for(int now=nxt[c].first;;now=nxt[now].first) {
			if(K==nxt[now].second) return now;
			K-=nxt[now].second;
		}
	}
	cnt[nxt[c].first]=cnt[c]+nxt[c].second;
	return solve(nxt[c].first,v+nxt[c].second);
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(NULL); cout.tie(NULL);
	TEST(freopen("input.txt", "r", stdin));
	TEST(freopen("output.txt", "w", stdout));
	TEST(freopen("debug.txt", "w", stderr));
	int N;
	vector<int> ans;
	cin>>N>>K;
	for(int i=0;i<N;i++) {
		cin>>A[i];
		P[--A[i]].push_back(i);
	}
	if(N==1) {
		if(K&1) cout<<A[0]+1<<'\n';
		return 0;
	}
	for(int i=0;i<N;i++) {
		int idx=upper_bound(P[A[i]].begin(),P[A[i]].end(),i)-P[A[i]].begin();
		if(idx==P[A[i]].size()) {
			int n=P[A[i]][0]+1;
			nxt[i]={n%N,1};
		}
		else {
			int n=P[A[i]][idx]+1;
			nxt[i]={n%N,n==N};
		}
	}
	memset(idx,-1,sizeof(idx));
	for(int i=solve(0,0);i<N;i++) {
		if(idx[A[i]]==-1) {
			idx[A[i]]=ans.size();
			ans.push_back(A[i]);
		}
		else {
			while(ans.size()>idx[A[i]]) ans.pop_back();
			idx[A[i]]=-1;
		}
	}
	for(auto a: ans) cout<<a+1<<' ';
	return 0;
}

