            cout << B[i] << " ";
        }
        cout << endl;*/
        VB masked(SZ(B));
        unordered_map<LL, LL> c;   // number, position + 1
        REP(i, SZ(B)) {
            //$(i);
            if (c.count(B[i]) == 0) {
                c[B[i]] = i + 1;
            } else {
                FOR(j, c[B[i]] - 1, i + 1) {
                    masked[j] = true;
                }
                unordered_map<LL, LL> d;
                REP(j, c[B[i]] - 1) {
                    if (!masked[j]) {
                        d[B[j]] = j + 1;
                    }
                }
                c = d;
            }
            /*cout << "c\n";
            EACH(cc, c) {
                cout << cc.first << ":" << cc.second << " ";
            }
            cout << endl;*/
