            //$(cc.first);
        }
        SSORT(x);
        VI result;
        //$(k);
        //cout << "result\n";
        REP(i, SZ(x)) {
            //cout << "hoge\n";
            result.PB(x[i].first);
            //cout << result[i] << " ";
        }
        /*cout << "c\n";
          cout << endl;
          $(SZ(c));*/
        if (SZ(c) == 0) {   // period == k + 1
            /*cout << "d\n";
              cout << "0!\n";*/
            if (k == 0) {
                return;
            }
            VI r(results[K % (k + 1) - 1]);
            REP(i, SZ(r)) {
                cout << r[i] << " ";
            }
            cout << endl;
            return;
            //cout << "0!" << endl;
        }
        //cout << "1\n";
        results.PB(result);
        //cout << "2\n";
        REP(i, SZ(A)) {
            result.PB(A[i]);
        }
        B = result;
    }
    VI r(results[SZ(results) - 1]);
    REP(i, SZ(r)) {
        cout << r[i] << " ";
    }
    cout << endl;
}

