                const int v = A[(p + i) % N];
                if (in[v]) {
                    for (; not ans.empty() and ans.back() != v;) { ans.pop_back(); }
                    ans.pop_back(), in[v] = false;
                } else {
                    ans.push_back(v), in[v] = true;
                }
            }
            for (const int v : ans) { std::cout << v << " "; }
            std::cout << std::endl;
            return 0;
        }
        K -= plus[p];
        if (dist[to] != -1 and plen == -1) { plen = cost - dist[to], K %= plen; }
        dist[to] = cost, p = to;
    }
    return 0;
}

