	{
		loc[arr[i]] = i;
	}
	FORD(i, N, 0)
	{
		to[i] = loc[arr[i]] + 1 - i;
		loc[arr[i]] = i;
	}
	FOR(i, 0, N)
	{
		go[0][i] = to[i];
	}
	bool die = false;
	FOR(i, 1, 61)
	{
		if (die)
		{
			FOR(j, 0, N)
			{
				go[i][j] = LLINF;
			}
			continue;
		}
		FOR(j, 0, N)
		{
			go[i][j] = go[i - 1][j] + go[i - 1][(j + go[i - 1][j]) % N];
			if (go[i][j] > LLINF)
			{
				die = true;
			}
		}
	}
	pos = 0;
	FORD(i, 61, 0)
	{
		if (pos + go[i][pos % N] <= K * N)
		{
			pos += go[i][pos % N];
		}
