		{
			while(true)
			{
				int y = seq.back();
				seq.pop_back();
				loc[y]--;
				if (x == y) break;
			}
		}
		else
		{
			seq.PB(x);
			loc[x]++;
		}
	}
	FOR(i, 0, SZ(seq))
	{
		if (i) cout << ' ';
		cout << seq[i];
	}
	cout << '\n';
	return 0;
	//now keep on applying this thing till we hit like smth in N*(K-1)...N*K-1
}

