void solve() {
    for (int i = 0; i < n + n; ++i)
        vec[a[i]].emplace_back(i);

    for (int i = 0; i < n; ++i) {
        nx[i] = *upper_bound(vec[a[i]].begin(), vec[a[i]].end(), i);
        up[i][0] = nx[i] - i + 1;
    }

    for (int i = 0; i < n; ++i)
        for (int j = 1; j < L; ++j) {
            ll d1 = up[i][j - 1];
            ll i1 = i + d1;
            ll d2 = up[i1 % n][j - 1];
            ll res = 0ull;

            if (!__builtin_add_overflow(d1, d2, &res))
                up[i][j] = res; // pizdec spasibo blackav
            else
                up[i][j] = 0;
        }

    if (K == 1) {
        vector<int> res;

        for (int i = 0; i < n; )
            if (nx[i] < n) {
                i = nx[i] + 1;
            } else {
                res.emplace_back(a[i++]);
            }

        for (const auto& i : res)
            cout << i << ' ';

        cout << endl;
    } else {
        ll cur = 0;

        for (int j = L - 1; j >= 0; --j) {
            auto i = cur % n;
            ll res = 0ull;

            if (up[i][j] != 0 && !__builtin_add_overflow(cur, up[i][j], &res) && res < (K - 1) * n)
                cur = res;
        }

        cur += up[cur % n][0];
        assert(cur / n == K - 1);

        vector<int> res;

        for (int i = cur % n; i < n; )
            if (nx[i] < n) {
                i = nx[i] + 1;
            } else {
                res.emplace_back(a[i++]);
            }

        for (const auto& i : res)
            cout << i << ' ';

        cout << endl;
    }
}

