ll N, K;
VL A(200000);

VVL doubling(ll N, const VL &A) {
    VL used(200010, -1);
    VVL ret(61, VL(N));
    REP(k, 2) REP(i, N) {
        if(used[A[i]] != -1) {
            ret[0][used[A[i]] % N] = k * N + i - used[A[i]] + 1;
        }
        used[A[i]] = k * N + i;
    }
    REP(k, 60) REP(i, N) {
        ret[k+1][i] = ret[k][i] + ret[k][(i + ret[k][i]) % N];
    }
    return ret;
}

signed main() {
    cin >> N >> K;
    REP(i, N) cin >> A[i];
    VVL dbl = doubling(N, A);
    ll now = 0, sum = 0, C = N * K;
    while(1) {
        ll num = 0;
        REP(k, 60) {
            if(dbl[k][now] + sum >= C) {
                num = k - 1;
                break;
            }
        }
        if(num == -1) break;
        sum += dbl[num][now];
        now = sum % N;
    }
    vector<bool> exist(200010, false);
    deque<ll> dq;
    while(sum < C) {
        if(!exist[A[now]]) {
            dq.emplace_back(A[now]);
            exist[A[now]] = true;
        } else {
            while(exist[A[now]]) {
                exist[dq.back()] = false;
                dq.pop_back();
            }
        }
        now++;
        sum++;
    }
    REP(i, dq.size()) cout << dq[i] << (i == N - 1 ? "\n" : " ");
}

