using namespace std;

typedef long long i64;
const int NMAX = 200010;
const int LG = 60;
int val[NMAX];
int poz[NMAX];
int jump[NMAX];
i64 up[LG][NMAX];
/// unde ajung si cate elemente am in rucsac in 2^k pasi
int n;
vector <int> v;

int main()
{
	i64 k;
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cin >> n >> k;
	k *= n;

	fill(poz, poz + NMAX, -1);
	fill(jump, jump + NMAX, -1);

	for (int i = 0; i < n; i++)
		cin >> val[i];

	for (int i = 0; i < 2 * n; i++) {
		if (poz[val[i % n]] != -1)
			jump[poz[val[i % n]]] = i % n;
		poz[val[i % n]] = i % n;
	}


	for (int i = 0; i < n; i++) {
		assert(jump[i] != -1);
		if (jump[i] <= i)
			jump[i] += n;
		up[0][i] = jump[i] - i + 1;
	}

	i64 inf = 1e18;

	for (int j = 1; j < LG; j++) {
		for (int i = 0; i < n; i++) {
			i64 middle = i + up[j - 1][i];
			i64 add = up[j - 1][i] + up[j - 1][middle % n];
			add = min(add, inf);
			up[j][i] = add;
		}
	}

	i64 pact = 0;
	for (int i = 59; i >= 0; i--)
		if (pact + up[i][pact % n] <= k)
			pact += up[i][pact % n];

	fill(poz, poz + NMAX, -1);
	while (pact != k) {
		int a = val[pact % n];
		pact++;
		if (poz[a] != -1) {
			while (poz[a] != -1)
				poz[v.back()] = -1, v.pop_back();
		}
		else
			v.push_back(a), poz[a] = 1;
	}

	for (auto i : v)
		cout << i << ' ';
	cout << '\n';
	return 0;
}

#include<bits/stdc++.h>

using namespace std;

typedef long long int ll;

const int N = 2e5 + 5;

vector < vector < int > > adj (N);
vector < int > p (N), a(N), v;
int n;

vector < int > find_cycle (int k) {
  vector < int > res;
  if (k != 0) {
    int i;
    if (p[k] > k) i = p[k];
    else {
      res.push_back(a[k]);
      i = k + 1;
    }
    while (i < n) {
      if (p[i] > i) {
        i = p[i];
      } else {
        res.push_back (a[i]);
        i++;
      }
    }
  }
  return res;
}

int main () {
  ios_base::sync_with_stdio(false);
  cin.tie(0);cout.tie(0);

  ll k;
  cin >> n >> k;
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    adj[a[i]].push_back (i);
  }

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < (int)adj[i].size() - 1; j++) {
      p[adj[i][j]] = adj[i][j + 1] + 1;
    }
    if ((int)adj[i].size() == 1) {
      p[adj[i].back()] = adj[i].back();
    } else if ((int)adj[i].size() > 0) {
      p[adj[i].back()] = adj[i][0] + 1;
    }
  }

  v.push_back(-1);
  v.push_back(p[0]);
  while (true) {
    if (v.back() == n) {
      v.pop_back();
      break;
    }
    if (v.back() == p[v.back()]) {
      if (v.back() == n - 1) {
        v.pop_back();
        break;
      }
      v.push_back(p[v.back() + 1]);
    } else {
      v.push_back (p[v.back()]);
    }
  }

  while (true && v.size() > 1) {
    vector < int > tmp = find_cycle(v.back());
    if (tmp.size() == 0) v.pop_back();
    else break;
  }

  k %= (int)v.size();

  if (k == 0) {
    cout << '\n';
    return 0;
  }

  vector < int > ans = find_cycle(v[k]);

  for (auto i : ans) cout << i << " ";
  cout << '\n';
}

