  ll n, k;
  cin >> n >> k;
  vector<ll> a(n);
  rep(i, n) cin >> a[i];

  if (n % 2 == 0) {
    bool f = true;
    rep(i, n / 2) {
      if (a[2 * i] != a[2 * i + 1]) {
        f = false;
      }
    }
    if (f) return 0;
  }
  map<ll, ll> mp;
  rep(i, n) mp[a[i]] = -1;
  vector<vector<ll>> dp;
  vector<ll> res(n);
  rep(i, 2 * n) {
    if (mp[a[i % n]] != -1 && mp[a[i % n]] < n) res[mp[a[i % n]]] = i - mp[a[i % n]] + 1;
    mp[a[i % n]] = i;
  }
  dp.push_back(res);
  while (res[0] < n * k) {
    vector<ll> nxt(n, 0);
    rep(i, n) nxt[i] = res[i] + res[(res[i] + i) % n];
    res = nxt;
    dp.push_back(res);
  }
  ll m = dp.size();
  ll pos = 0;
  repr(i, m - 1) {
    if (pos + dp[i][pos % n] < n * k) pos += dp[i][pos % n];
  }
  pos %= n;
  stack<ll> st;
  rep(i, n) mp[a[i]] = 0;
  FOR(i, pos, n) {
    //cout << i << ' ' << mp[a[i]] << '\n';
    if (mp[a[i]] == 1) {
      while (!st.empty() && st.top() != a[i]) {
        mp[st.top()] = 0;
        st.pop();
      }
      mp[a[i]] = 0;
      st.pop();
    }
    else {
      st.push(a[i]);
      mp[a[i]] = 1;
    }
  }
  if (st.empty()) {
    return 0;
  }
  vector<ll> ans;
  while (!st.empty()) {
    ans.push_back(st.top());
    st.pop();
  }
  reverse(ans.begin(), ans.end());
  rep(i, ans.size()) cout << ans[i] << ' ';
  cout << '\n';







  return 0;
}

