const int maxn = 2e5 + 5;

int a[maxn<<1];
int Next[maxn];
int num[maxn];
int q[maxn], top;
int main() {
    int n;
    long long k;
    scanf("%d%I64d", &n, &k);
    for(int i=0;i<n;i++)
    {
        scanf("%d", a + i);
        a[i+n] = a[i];
    }
    memset(Next,-1,sizeof(Next));
    for(int i=2*n-1;i>=0;i--)
    {
        Next[i] = num[a[i]];
        num[a[i]] = i;
    }
    for(int i=0;i<n;i++)
    {
        if(Next[i] >= n) Next[i] -= n;
    }
    int cnt=1, now=0, current;
    memset(num, 0, sizeof(num));
    while(1)
    {
        //printf("%dss %d\n",now, cnt);
        if(num[now]){
            current = cnt - num[now];
            break;
        }
        else{
            num[now] = cnt;
            if(Next[now] <= now){
                cnt++;
            }
            now = Next[now];
            now++;
            if(now>=n){
                now=0;
                cnt++;
            }
        }
    }
    if(k>=cnt){
        k -= cnt;
        k %= current;
        k++;
    }
    else{
        now = 0;
    }
    //printf("%lld %d %d\n", k, current, cnt);
    top = 0;
    cnt = 0;
    while(cnt < k)
    {
        if(cnt < k-1||(Next[now] > now)){
            if(Next[now] <= now) cnt++;
            now = Next[now];
        }
        else{
            q[top++] = a[now];
        }
        now++;
        if(now>=n){
            now=0;
            cnt++;
        }
    }
    for(int i=0;i<top;i++)
    {
        printf("%d%c",q[i], i==top-1?'\n':' ');
    }
    return 0;
}

