const int N = 2e5 + 10;

ll n, k, a[N], last[N], nxt[N], beg[N], follow[N], jump[N], njump[N];

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);
    cin >> n >> k;
    forn(i,n) cin >> a[i];

    beg[n] = N-1;
    dforsn(i,0,n) {
        if (last[a[i]]) {
            beg[i] = beg[last[a[i]]+1];
        }
        else beg[i] = a[i];
        last[a[i]] = i;
    }

    jump[N-1] = beg[0];
    forn(i,n) if (!follow[a[i]]) follow[a[i]] = i+1;
    forn(i,n) jump[a[i]] = beg[follow[a[i]]];

    int c = N-1;
    auto e = k-1;
    while (e > 0) {
        if (e&1) c = jump[c];
        forn(i,n) njump[a[i]] = jump[jump[a[i]]];
        forn(i,n) jump[a[i]] = njump[a[i]];
        e /= 2;
    }

    int start = c == N-1 ? 0 : follow[c];
    vector<bool> in(N);
    vi ans; forsn(i, start, n) {
        if (in[a[i]]) {
            while (1) {
                auto x = ans.back();
                ans.pop_back();
                in[x] = 0;
                if (x == a[i]) break;
            }
        }
        else {
            ans.push_back(a[i]);
            in[a[i]] = 1;
        }
    }
    for (auto x : ans) cout << x << ' ';


    return 0;
}

