void solve(int ks) {
	scanf("%d %lld", &n, &k);
	for (int i = 1; i <= n; i++) {
		scanf("%d", &num[i]);
		if (First.find(num[i]) == First.end()) First[num[i]] = i;
	}
	for (int i = n; i >= 1; i--) {
		int pos = -1;
		if (Next.find(num[i]) != Next.end()) {
			pos = Next[num[i]];
		}
		else {
			pos = First[num[i]];
		}

		if (pos > i) {
			if (pos + 1 <= n) nxt[i] = { pos + 1, 0 };
			else if (pos == n) nxt[i] = { 1, 1 };
			else assert(0);
		}
		else nxt[i] = { First[num[i]] + 1, 1 };
		Next[num[i]] = i;
	}

	MEM(come, -1);
	int now = 1, pos = 1;
	while (true) {
		if (come[0][pos] == -1) {
			come[0][pos] = now;
		}
		else if (come[1][pos] == -1) {
			come[1][pos] = now;
		}
		else break;
		now += nxt[pos].second;
		pos = nxt[pos].first;
	}

	int whr = 1;
	for (int i = n; i >= 1; i--) {
		if (come[0][i] == k) whr = i;
		if (come[1][i] == k) whr = i;
		if (come[1][i] != -1) {
			LL a = come[0][i];
			LL b = come[1][i];
			if (k >= b && (k - a) % (b - a) == 0) whr = i;
		}
	}
	map<int, int> M;
	VI ans;
	for (int i = whr; i <= n; i++) {
		if (M[num[i]]) {
			while (ans.back() != num[i]) {
				M[ans.back()]--;
				ans.pop_back();
			}
			M[ans.back()]--;
			ans.pop_back();
			continue;
		}
		ans.push_back(num[i]);
		M[num[i]]++;
	}
	for (int x : ans) printf("%d ", x);


}

