void apply(vector<int64_t> &s, int64_t a) {
  vector<int64_t> u(0);
  int64_t n = s.size();
  bool found = false;
  rep(i,n) {
    if ( s.at(i) == a ) {
      found = true;
      break;
    }
    u.push_back(s.at(i));
  }
  if ( found == false ) {
    u.push_back(a);
  }
  s = u;
}

void print(vector<int64_t> answer) {
  int n = answer.size();
  if ( n == 0 ) {
    cout << endl;
    return;
  }
  rep(i,n) {
    cout << answer.at(i);
    if ( i == n - 1 ) {
      cout << endl;
    }
    else {
      cout << " ";
    }
  }
}

int main() {
  //input
  int64_t N, K;
  cin >> N >> K;
  vector<int64_t> A(N);
  rep(j,N) {
    cin >> A.at(j);
  }
  //calc
  vector<vector<int64_t>> cache;
  vector<int64_t> s(0);
  int64_t unit_idx = -1;
  for(int64_t i = 0; i < K; i++) {
    for(int64_t j = 0; j < N; j++) {
      apply(s, A.at(j));
      if ( j < N-1 || s.size() > 0 ) {
        vector<int64_t> u = s;
//        cout << "#cached: ";
//        print(u);
        cache.push_back(u);
      }
      else {
        unit_idx = i * N + j;
        break;
      }
    }
    if ( unit_idx >= 0 ) {
      break;
    }
  }
  if ( unit_idx >= 0 ) {
    int64_t r = (N*K) % (unit_idx + 1);
    if ( r == 0 ) {
      cout << endl;
    }
    else {
      print(cache.at(r-1));
    }
  }
  else {
    print(s);
  }
}

