            ll d = ((*itr) - i + n) % n;
            if(d == 0) d = n;
            if(d < cnt) {
                i += d+1;
                cnt -= d+1;
            } else {
                que.push_back(a[i]);
                used[a[i]] = true;
                i = (i+1) % n;
                --cnt;
            }   
        }
    }

    while(!que.empty()) {
        cout << que.front() << " ";
        que.pop_front();
    }
    cout << endl;
}

