using namespace std;

int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(20);
    ll N,K;
    cin >> N >> K;
    vector<ll> A(N);
    vector<vector<ll>> spot(2e5+1); // spot[i][0] : = iが最初に出現する場所
    vector<ll> same(N,-1); // same[i] := i 番目と同じ数字が次に出現する場所
    rep(i,N){
        cin >> A[i];
        spot[A[i]].push_back(i);
    }
    // same を作成する
    rep(i,N){
        // i番目の数字について
        int now = A[i]; // 今の値
        for(auto x:spot[now]){
            // 今の値が出現する場所が x 
            if(x>i){
                same[i] = x;
                break;
            }
        }
        if(same[i]==-1){
            same[i] = spot[now][0]; // 自分より右に出現しない場合は左に出現する1番最初の場所を入れる
            //cout << same[i] << endl;
        }
    }
    // 初期状態と同じになるようにシミュレートする
    int nowpos = 0; // 現在の場所 ここと同じ数が右側に出現するのでそれを探す
    ll dis = 0; // 初期状態に戻るための移動距離
    while(dis == 0 || nowpos != 0){
        // どれだけ移動するかを出す
        if(same[nowpos] > nowpos)dis += same[nowpos] - nowpos; // 右側に自分と同じ数値がある場合
        else {
            // 左側に自分と同じ数字がある場合は 左側にある数字に N を足すことで右側に持ってくることを考える
            dis += N + same[nowpos] - nowpos;
        }
        dis ++; // 右に1つ進む ( nowposと same[nowpos]が同じ数値なため新しい要素を入れるために進む
        nowpos = (same[nowpos]+1)%N;
    }
    // cout << dis << endl; // 元の状態に戻るための距離 dis が出てきた
    ll real = (N*K) % dis; // 実質進む距離
    vector<ll> ans;
    for(ll i = 0; i < real ; i++){
        if(same[i%N] > i%N && (i + same[i%N] - i%N) < real){
            i += same[i%N] - i%N;
        }else if(same[i%N]<= i%N && i + same[i%N] + N - i% N < real){
            i += N + same[i%N] - i%N;
        }else ans.push_back(A[i%N]);
    }
    for(auto x:ans)cout << x << " ";
}

