using P = pair<int, ll>;
int n;
ll k;
vector<int> a;
vector<vector<P>> hop;
int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> n >> k;
    a = vector<int>(n);
    hop = vector<vector<P>>(60, vector<P>(n));
    REP(i, n) cin >> a[i];
    map<int, int> last;
    REP(i, n) last[a[i]] = i;
    REP(i, n) {
        int lasti = last[a[i]];
        int dist = lasti < i ? i - lasti : i + n - lasti;
        hop[0][lasti] = make_pair((i + 1) % n, dist + 1);
        last[a[i]] = i;
    }

    // doubling
    for (int k = 1; k < 60; ++k) {
        REP(i, n) {
            P prehop = hop[k - 1][i];
            P next = hop[k - 1][prehop.first];
            hop[k][i] = make_pair(next.first, next.second + prehop.second);
        }
    }

    // for (int k = 0; k < 20; ++k) {
    //     D(k); DV(hop[k]);
    // }

    ll max_steps = k * n;
    ll steps = 0;
    int i = 0;
    while(1) {
        int kok = 0;
        int kng = 60;
        while (kok + 1 < kng) {
            int kmid = (kok + kng) / 2;
            if (kmid != 60 && steps + hop[kmid][i].second <= max_steps) {
                kok = kmid;
            } else {
                kng = kmid;
            }
        }
        if (steps + hop[kok][i].second > max_steps) break;
        steps += hop[kok][i].second;
        i = hop[kok][i].first;
    }
    // DD(i, steps);
    set<int> st;
    vector<int> ans;
    while(steps < max_steps) {
        int nx = a[i];
        if (st.find(nx) == st.end()) {
            st.insert(nx);
            ans.push_back(nx);
        } else {
            while (st.find(nx) != st.end()) {
                st.erase(*ans.rbegin());
                ans.pop_back();
            }
        }
        i = (i + 1) % n;
        steps++;
        // DV(ans);
    }
    // D(steps);
    if (ans.size() > 0) {
        REP(i, ans.size() - 1) cout << ans[i] << " ";
        cout << *ans.rbegin();
    }
    cout << endl;
}

