int n;
int a[200'010];
ll k;

vector<int> wh[200'010];
int kth[200'010];

pp nxt[200'010];

int main()
{
	cppio(); cin >> n >> k;
	rrep(i, n) {
		cin >> a[i];
		kth[i] = wh[a[i]].size();
		wh[a[i]].pb(i);
	}

	rrep(i, n) {
		int np = (i == wh[a[i]].back() ? n + wh[a[i]][0] : wh[a[i]][kth[i]+1]);
		nxt[i] = {np%n + 1, np/n};
		if(0) printf("nxt[%d] = %d %d\n",
		i, nxt[i].x, nxt[i].y);
	}

	static int vis[200'010];
	static int dist[200'010];
	int p = 1, d = 0;
	for(;;) {
		if(d + nxt[p].y >= k) break;

		vis[p] = 1;
		dist[p] = d;

		d += nxt[p].y;
		p = nxt[p].x;

		if(vis[p]) {
			break;
		}
	}

	auto job = [&](int p, int cnt) {
		vector<int> ans;
		static bitset<200'010> has;

		if(cnt < 0) return;

		for(int i=p; i<=n; ++i) {
			int v = a[i];
			if(has[v]) {
				while(ans.back() != v) {
					has[ans.back()] = 0;
					ans.pop_back();
				}
				ans.pop_back(); has[v] = 0;
			} else {
				ans.pb(v);
				has[v] = 1;
			}
		}

		for(;cnt--;) {
			for(int i=1; i<=n; ++i) {
				int v = a[i];
				if(has[v]) {
					while(ans.back() != v) {
						has[ans.back()] = 0;
						ans.pop_back();
					}
					ans.pop_back(); has[v] = 0;
				} else {
					ans.pb(v);
					has[v] = 1;
				}
			}
		}

		for(int x:ans) cout << x << ' ';
		cout << endl;
	};

	if(!vis[p]) {
		job(p, k - 1 - d);
	} else {
		ll D = d - dist[p];
		ll nokori = k - dist[p];
		nokori -= D * (max(0ll, (nokori - D + 1)) / D);
		while(nokori) {
			if(nokori <= nxt[p].y) break;
			nokori -= nxt[p].y;
			p = nxt[p].x;
		}

		job(p, nokori - 1);
	}

	return 0;
}

