    }
    while (true) {
      int val = a[pos];
      const vector<int>& vec = next[val];
      size_t idx = lower_bound(all(vec), pos) - vec.begin();
      if (idx + 1 == vec.size()) {
	break;
      } else {
	pos = vec[idx + 1] + 1;
	if (pos == n) {
	  break;
	}
      }
    }
    init.push_back(pos);
    if (used.count(pos)) break;
    used[pos] = i + 1;
    pos = next[a[pos]][0] + 1;
  }

  int start_pos = 0;
  if (init.size() == k + 1) {
    start_pos = init[k];
  } else {
    int start_cycle = used[init.back()];
    int cycle = init.size() - 1 - start_cycle;
    start_pos = init[(k - start_cycle) % cycle + start_cycle];
  }
  vector<int> ans = calc(a, start_pos);
  rep(i, ans.size()) {
    cout << ans[i] << " \n"[i+1 == ans.size()];
  }
}

