void out(int S, int t){
	assert(t >= 0);
	static bool ex[N];
	static int stk[N]; int top = 0;
	for(int i = S; t; t--, i++){
		if(i > n) i -= n;
		if(ex[a[i]]){
			while(stk[top] != a[i]) 
			ex[stk[top]] = false, --top;
			ex[a[i]] = false, --top;
		} else stk[++top] = a[i], ex[a[i]] = true;
	} for(int i = 1; i <= top; i++) cout << stk[i] << " ";
}
