	lp[i]=la[a[i]], la[a[i]]=i;
//	for(int i=1; i<=n; i++) cout << lp[i]<<" ";cout<<endl;
	static ll tm[N];
	static bool ex[N]; ex[1] = 1;
	static int ic[N], _ic[N]; int x = 1;
	ll tim = 0; int ct = 1; ic[1] = _ic[1] = 1;
	while(true){
