			ll t = k * n - tm[nxt];
			t %= cir; int r = _ic[nxt], c = r;
			for(; tm[ic[c]] - tm[ic[r]] < t; ++c); --c;
			int S = ic[c]; t -= tm[ic[c]] - tm[ic[r]];
