}

#include<bits/stdc++.h>
using namespace std;

typedef long long LL;

const int N = 1e6+7;
int a[N];
int nxt[N], last[N];
int n;
LL k;

int f(int x, LL &sum) {
    sum += nxt[x];
    return (x+nxt[x])%n;
}

pair<LL, LL> floyd() {
    int h=0, t=0;
    LL hs=0, ts = 0;

    do {
        h = f(h, hs);
        h = f(h, hs);
        t = f(t, ts);
    } while (h!=t);

    LL pre = 0;
    t = 0;
    while (t!=h)    t = f(t, pre);

    return make_pair(pre, ts-pre);
}

bool is[N];

void simulate(vector<int> &v) {
    vector<int> ans;
    for (int x: v) {
        if (!is[x]) {
            is[x] = 1;
            ans.push_back(x);
        }
        else {
            while (ans.back()!=x) {
                is[ans.back()] = 0;
                ans.pop_back();
            }
            assert(ans.back() == x);
            is[ans.back()] = 0;
            ans.pop_back();
        }
    }
    v = ans;
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>k;

    for (int i=0; i<n; i++)        cin>>a[i];
    for (int i=n; i<2*n; i++)    a[i] = a[i-n];

    for (int i=2*n-1; i>=0; i--) {
        nxt[i] = last[a[i]]-i+1;
        last[a[i]] = i;
    }

    pair<LL, LL> ans = floyd();
    assert(ans.first == 0);
    assert(ans.second%n==0);

    LL len = (n*k)%ans.second;

    int cur = 0;
    LL sum = 0;

    while (true) {
        LL prv = sum;
        cur = f(cur, sum);
        if (sum > len) {
            sum = prv;
            break;
        }
    }
    LL rem = len - sum;
    assert(rem <= n);
//    cout<<":: "<<rem<<endl;

    vector<int> out;
    for (int i=0; i<rem; i++)
        out.push_back(a[n-1-i]);

    reverse(out.begin(), out.end());

//    for (int x: out)    cout<<x<<" "; cout<<endl;

    simulate(out);

    for (int x: out)    cout<<x<<" ";
}

