    for(int j = 1; j < idx[i].size(); j ++ ){
      pi[idx[i][j-1]] = (idx[i][j] + 1 == n + 1 ? 1 : idx[i][j] + 1);
      gr[idx[i][j-1]] = ((idx[i][j] + 1) == n + 1);
    }
    gr[idx[i].back()] = (idx[i][0] + 1 == n + 1) + 1;
    pi[idx[i].back()] = (idx[i][0] + 1 == n + 1 ? 1 : idx[i][0] + 1);
  }
  int p = 1;
