	ll k;
	cin >> n >> k;
	vector<int> a(n);
	for(int i = 0; i < n; ++i){ cin >> a[i]; }
	const int m = *std::max_element(a.begin(), a.end()) + 1;

	vector<int> last(m);
	for(int i = 0; i < n; ++i){ last[a[i]] = i; }

	vector<int> prev(n);
	for(int i = 0; i < n; ++i){
		prev[i] = last[a[i]];
		last[a[i]] = i;
	}

	vector<int> heads;
	int last_head = 0;
	heads.push_back(0);
	do {
		const int t = (heads.back() - 1 + n) % n;
		if(prev[t] >= last_head){
			heads.push_back(prev[t]);
		}
		last_head = prev[t];
	} while(last_head != 0);
	heads.pop_back();
	reverse(heads.begin() + 1, heads.end());

	vector<int> next(n);
	last.assign(m, n);
	for(int i = n - 1; i >= 0; --i){
		next[i] = last[a[i]];
		last[a[i]] = i;
	}

	vector<int> b;
	for(int i = heads[(k - 1) % heads.size()]; i < n; ++i){
		if(next[i] < n){
			i = next[i];
		}else{
			b.push_back(a[i]);
		}
	}
	for(const auto x : b){
		cout << x << " ";
	}
	cout << endl;
	return 0;
}

