const double EPS = 1e-9;


int main(int argc, const char * argv[]) {
  ll N, K; cin >> N >> K;
  vector<int> A(N);
  for(int i=0; i<N; i++)
    cin >> A[i];

  vector<vector<int>> jump(200001);
  for(int i=0; i<N; i++)
    jump[A[i]].push_back(i+1);

  vector<ll> log;
  ll len, period, diff;
  int Xi, indexA;
  len = 1;
  log.push_back(len);
  indexA = (int)(len-1)%N;
  Xi = A[indexA];
  while(true){
    int i = (int) (find(jump[Xi].begin(), jump[Xi].end(), indexA+1) - jump[Xi].begin());
    assert(i != jump[Xi].size());
    if(i+1 != jump[Xi].size()){
      diff = (ll) jump[Xi][i+1] - jump[Xi][i];
    }else {
      diff = (ll) (N - jump[Xi][i]) + jump[Xi][0];
    }
    len += diff + 1;
    log.push_back(len);
    indexA = (int) (len-1)%N;
    Xi = A[indexA];
    if(indexA == 0){
      period = (len-1)/N;
      break;
    }
  }

  K %= period;
  vector<int> ans;
  if (period != 1){
    auto it = lower_bound(log.begin(), log.end(), K*N);
    it--;
    int start = (int)((*it)-1)%N;
    for(int i=start; i<N; i++){
      Xi = A[i];
      auto it2 = find(jump[Xi].begin(), jump[Xi].end(), i+1);
      assert(it2 != jump[Xi].end());
      if(*it2 != jump[Xi].back()){
        it2++;
        i = (*it2) - 1;
        continue;
      }else {
        ans.push_back(Xi);
      }
    }
  }

  for(auto a: ans){
    cout << a << " ";
  }
  cout << endl;

  return 0;
}

