            d[0][p.second[i]]=p.second[i+1]-p.second[i]+1;
        }
    }
    for(int i=0;i<59;i++){
        for(int j=0;j<n;j++){
            d[i+1][j]=min(inf,d[i][j]+d[i][(j+d[i][j])%n]);
        }
    }
    ll cur=0;
    for(int i=59;i>=0;i--){
        if(cur+d[i][cur%n]<=k){
            cur+=d[i][cur%n];
        }
    }
    if(cur==k){
        return 0;
    }
    vector<int> res;
    set<int> s;
    for(ll i=cur%n;i<n;i++){
        if(s.find(a[i])==s.end()){
            res.push_back(a[i]);
            s.insert(a[i]);
        }
        else{
            while(1){
                int v=res.back();
                res.pop_back();
                s.erase(v);
                if(v==a[i])break;
            }
        }
    }
    for(int v:res){
        printf("%d ",v);
    }
    printf("\n");
}

