    {
        for(int j = 0; j < N; j++)
        {
            next[i][j] = next[i - 1][next[i - 1][j]];
            over[i][j] = over[i - 1][j] + over[i - 1][next[i - 1][j]];
        }
    }

    ll l = 0, r = 1LL << 60;
    ll mem;
    for(int i = 0; i < 64; i++)
    {
        ll mid = (l + r) / 2;
