#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

int main() {
    ll N, K;
    cin >> N >> K;
    vector<ll> A(N);
    for (ll i = 0; i < N; i++) {
        cin >> A[i];
    }

    vector<ll> pre(2 * 1e5 + 1, -1);
    vector<ll> next(N, -1);
    for (ll i = 0; i < N; i++) {
        if (pre[A[i]] != -1) {
            next[pre[A[i]]] = i;
        }
        pre[A[i]] = i;
    }
    for (ll i = 0; i < N; i++) {
        if (next[i] == -1) {
            next[i] = pre[A[i]];
        }
        pre[A[i]] = min(pre[A[i]], i);
    }

    vector<ll> pre_visit(N, -1);
    ll curr = 0;
    while (true) {
        ll pos = curr % N;
        pre_visit[pos] = curr;

        ll cost = (next[pos] > pos ? next[pos] - pos : N + next[pos] - pos) + 1;
        if (curr + cost >= N * K) {
            //ループする前に終わる
            //シミュレート
            vector<ll> ans;
            for (ll i = pos; i < N; i++) {
                cost = (next[i] > i ? next[i] - i : N + next[i] - i) + 1;
                if (i + cost >= N) {
                    ans.push_back(A[i]);
                } else {
                    i = next[i];
                }
            }
            for (ll i = 0; i < ans.size(); i++) {
                cout << ans[i] << " \n"[i == ans.size() - 1];
            }

            return 0;
        }

        //遷移
        curr += cost;

        if (pre_visit[curr % N] != -1) {
            //ループした
            break;
        }
    }

    ll diff = curr - pre_visit[curr % N];

    curr += (N * K - 1 - curr) / diff * diff;

    //currからN * K - 1まで行くシミュレーション
    vector<ll> ans;
    for (; curr < N * K;) {
        ll pos = curr % N;
        ll cost = (next[pos] > pos ? next[pos] - pos : N + next[pos] - pos) + 1;
        if (curr + cost > N * K) {
            ans.push_back(A[pos]);
            curr++;
        } else {
            curr += cost;
        }
    }
    for (ll i = 0; i < ans.size(); i++) {
        cout << ans[i] << " \n"[i == ans.size() - 1];
    }
}

