    if(dic.find(a[i])==dic.end()){
      dic.insert(make_pair(a[i],count));
      num[count]=i;
      count++;
    }
  }
  std::vector<ll> last(N+1,0), last_itr(N+1,0);
  last[N]=-1;
  map<ll, ll> pre;
  for(ll i=N-1;i>=0;i--){
    if(pre.size()==0){
      pre.insert(make_pair(a[i],i));
      last[i]=a[i];
      last_itr[i]=i;
    }else if(pre.find(a[i])==pre.end()){
      pre.insert(make_pair(a[i],i));
      last[i]=a[i];
      last_itr[i]=i;
    }else{
      last[i]=last[(*pre.find(a[i])).second+1];
      last_itr[i]=last_itr[(*pre.find(a[i])).second+1];
      pre.erase(a[i]);
      pre.insert(make_pair(a[i],i));
    }
  }

  std::vector<ll> yy(N+1,0);
  std::vector<ll> dp(N,0);
  if(last[0]==-1){
    std::cout << '\n';
    return 0;
  }
  dp[0] = last[0];
  for(ll i=1;i<N+1;i++){
    dp[i]=last[num[(*dic.find(dp[i-1])).second]+1];
    yy[i] = num[(*dic.find(dp[i-1])).second]+1;
    if(dp[i]==-1){
      X = i+1;
      break;
    }
  }

  map<ll, ll> ans;
  map<ll, ll> ans_itr;
  if(K%X==0){
    std::cout << '\n';
    return 0;
  }else{
    count=0;
    for(ll i=yy[K%X-1];i<N;i++){
      if(ans.size()==0){
        ans.insert(make_pair(a[i],count));
        ans_itr.insert(make_pair(count,a[i]));
        count++;
      }else if(ans.find(a[i])==ans.end()){
        ans.insert(make_pair(a[i],count));
        ans_itr.insert(make_pair(count,a[i]));
        count++;
      }else{
        auto itr = ans_itr.end();
        ll target = (*ans.find(a[i])).second;
        for(ll j=count-1;j>=target;j--){
          itr--;
          //std::cout << "erase" << (*ans_itr.find(j)).second<< '\n';
          ans.erase((*ans_itr.find(j)).second);
          ans_itr.erase(itr);
        }
        count=ans_itr.size();
      }
    }
    auto itr = ans_itr.begin();
    for(ll i=0;i<ans_itr.size();i++){
      std::cout << (*itr).second;
      if(i!=ans_itr.size()-1) std::cout  << " ";
      itr++;
    }
    std::cout << '\n';
  }
  return 0;
}

