        for (int i = 0; i < n; i++) scanf("%d", &a[i]);


        const int K = 60;
        vector<vector<pair<int, ll>>> p(K, vector<pair<int, ll>>(n));

        const int N = *max_element(a.begin(), a.end()) + 1;

        vector<int> last(N, -1);
        for (int i = 0; i < n * 2; i++) {
            int x = a[i % n];
            if (last[x] != -1 && last[x] < n) {
                p[0][last[x]] = make_pair((i + 1) % n, (i + 1) / n);
            }
            last[x] = i;
        }
        for (int i = 1; i < K; i++) {
            for (int j = 0; j < n; j++) {
                p[i][j].first = p[i - 1][p[i - 1][j].first].first;
                p[i][j].second = p[i - 1][j].second + p[i - 1][p[i - 1][j].first].second;
                if (p[i][j].second >= INF) p[i][j].second = INF;
            }
        }

        int cur = 0;
        for (int i = K - 1; i >= 0; i--) {
