long long N, K;

vector<int> calc_to(vector<int> &A, int l) {
    vector<int> to((int)A.size(), -1);
    map<int, int> prev;
    for (int i=l; i<2*N; ++i) {
        if (to[i%N] != -1) continue;
        if (prev.count(A[i%N])) {
            to[prev[A[i%N]]] = i%N;
            prev[A[i%N]] = i%N;
        } else {
            prev[A[i%N]] = i%N;
        }
    }
    return to;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    // rdfile("_input.txt");

