    vector<int> A(N);
    for (int i=0; i<N; ++i) cin >> A[i];

    vector<int> to = calc_to(A, 0);
    vector<int> pos;
    int k = 0;
    while (1) {
        while (k < to[k] % N) {
            if ((to[k]+1) % N == 0) break;
            k = (to[k]+1) % N;
        }
        pos.push_back(k);
        k = (to[k]+1) % N;
        if (k == 0) break;
    }

    int M = pos.size();
