vector<int> calc(const vector<int>& a, int start_pos) {
  vector<int> ans;
  set<int> used;

  for (int i = start_pos; i < a.size(); ++i) {
    if (used.count(a[i])) {
      while (ans.back() != a[i]) {
	used.erase(ans.back());
	ans.pop_back();
      }
      used.erase(ans.back());
      ans.pop_back();
    } else {
      ans.push_back(a[i]);
      used.insert(a[i]);
    }
  }

  return ans;
}

int main(){
  ll n, k;
  cin >> n >> k;
  vector<int> a(n);
  map<int, vector<int>> next;
  rep(i,n) {
    cin >> a[i];
    next[a[i]].push_back(i);
  }

  vector<int> init;
  init.push_back(n);
  map<int, int> used;
  used[n] = 0;

  int pos = 0;
  for (int i = 0; i < k; ++i) {
    while (true) {
      int val = a[pos];
      const vector<int>& vec = next[val];
      size_t idx = lower_bound(all(vec), pos) - vec.begin();
      if (idx + 1 == vec.size()) {
	break;
      } else {
	pos = vec[idx + 1] + 1;
	if (pos == n) break;
      }
    }
    init.push_back(pos);
    if (used.count(pos)) break;
    used[pos] = init.size() - 1;
    pos = (next[a[pos]][0] + 1) % n;
  }

  int start_pos = 0;
  if (init.size() == k + 1) {
    start_pos = init[k];
  } else {
    int start_cycle = used[init.back()];
    k -= start_cycle;
    int cycle = init.size() - 1 - start_cycle;
    start_pos = init[k % cycle + start_cycle];
  }
  vector<int> ans = calc(a, start_pos);
  rep(i, ans.size()) {
    cout << ans[i] << " \n"[i+1 == ans.size()];
  }
}

