            while(b[tot]!=x) pre[b[tot]]--,tot--;
            pre[x]--;tot--;
        }
        else b[++tot]=x,pre[x]++;
    }
}
int getPos(int now,ll k)
{
    while(k>=nex[now])
    {
        k-=nex[now];
        now=(now+nex[now])%n;
        if(now==0) now=n;
    }
    return now;
}
