            g[a[i]].pb(i + loop*n);
        }
    }
    //dbg(g);
    //k=0の遷移
    Vec x(2*n+1,-1);
    auto rec = [&](auto rec, ll v)->ll{
        if(x[v]!=-1) return x[v];
        if(v==2*n) return x[v] = n;
        auto itr = upper_bound(ALL(g[a[v%n]]),v);
        if(itr==g[a[v%n]].end()){
            return x[v] = v%n;
        }else{
            return x[v] = rec(rec,*itr+1);
        }
    };
    per(i,2*n-1){
        rec(rec,i);
    }
    VV dp(45,Vec(n+1));
    rep(i,n+1){
        dp[0][i] = x[i];
    }
    REP(j,1,45){
        rep(i,n+1){
            dp[j][i] = dp[j-1][dp[j-1][i]];
        }
    }
    k--;
    ll now = 0;
    rep(bit,45){
        if(k & (1LL<<bit)){
            now = dp[bit][now];
        }
    }
    //nowからシミュレーションする。
    set<ll> st;
    Vec v;
    REP(i, now, n){
        ll x = a[i];
        if(st.count(x)>0){
            while (v.back() != x){
                st.erase(v.back());
                v.pop_back();
            }
            st.erase(x);
            v.pop_back();
        }else{
            st.insert(x);
            v.pb(x);
        }
    }
    vout(v);
    return  0;
}

