struct Queue {
    Queue() {}
    Queue(int N) : s(vector<int>(N)), last(0) {}
    vector<int> s;
    int last;
};

void simulate(int N, vector<int>& A, Queue& queue) {
    unordered_map<int, int> positions; // <number, position>
    unordered_map<int, int> numbers; // <position, number>
    REP(i,0,queue.last) {
        positions[queue.s[i]] = i;
        numbers[i] = queue.s[i];
    }
    for (const int a : A) {
//        cout << "a:" << a << '\n';
        if (positions.find(a) != positions.end() && numbers[positions[a]] == a && positions[a] < queue.last) {
            queue.last = positions[a];
        } else {
            queue.s[queue.last] = a;
            positions[a] = queue.last;
            numbers[queue.last] = a;
            queue.last++;
        }
//        REP(i,0,queue.last) {
//            cout << queue.s[i] << " ";
//        }
//        cout << "\n";
    }
}

vector<int> generateDistanceListToNextIndex(int N, vector<int>& A) {
    vector<int> list(N);
    unordered_map<int, int> previousIndex; // <number, index>

    REP(i,0,2*N) {
//        debug(i);
        if (previousIndex.find(A[i%N]) != previousIndex.end() && list[previousIndex[A[i%N]] % N] == 0) {
            list[previousIndex[A[i%N]] % N] = i - previousIndex[A[i%N]];
//            debug(previousIndex[A[i%N]]);
        }
        previousIndex[A[i%N]] = i;
    }

    REP(i,0,N) {
        if (list[i] == 0) list[i] = N;
    }

    return list;
}

void solve(int N, int K, vector<int>& A) {
    Queue queue(N);

    int currentIndex = 0;
    const int limit = N * K;

    if (K > 1) {
        const auto distanceListToNextIndex = generateDistanceListToNextIndex(N, A);

        for (const auto index : distanceListToNextIndex) cout << index << " ";
        cout << '\n';

        int cycle = 0;
        vector<int> visitedWhen(N, -1);

        const int preLimit = (N-1) * K;
        while (currentIndex < preLimit) {
            if (visitedWhen[currentIndex % N] != -1) {
                cycle = currentIndex - visitedWhen[currentIndex % N];
                break;
            }
            visitedWhen[currentIndex % N] = currentIndex;
            currentIndex += distanceListToNextIndex[currentIndex % N] + 1;
        }

        if (cycle != 0 && currentIndex < preLimit) {
            currentIndex += (N * K - currentIndex) / cycle * cycle;
        }
    }

    while (currentIndex < limit) {
        simulate(N, A, queue);
        currentIndex++;
    }

    stringstream ss;
    REP(i,0,queue.last-1) {
        ss << queue.s[i] << " ";
    }
    if (queue.last != 0) ss << queue.s[queue.last-1];
	cout << ss.str() << '\n';
    return;
}

signed main() {
    int N, K;
    cin >> N >> K;

    vector<int> A(N);
    REP(i,0,N) cin >> A[i];

    solve(N, K, A);

    return 0;
}

