			it = pl[cur].upper_bound(-1);
			dp[i][0] = *it + n - i + 1;
		}
		else{
			dp[i][0] = *it - i + 1;
		}
	}
	for(int j=1;j<=61;j++){
		for(int i=0;i<n;i++){
			dp[i][j] = dp[i][j-1] + dp[ (i+dp[i][j-1])%n ][j-1];
