	for(int j = 1; j < maxm; j++){
		for(int i = 0; i < n; i++){
			nxt[j][i] = nxt[j - 1][nxt[j - 1][i]];
			cost[j][i] = sum(cost[j - 1][i],cost[j - 1][nxt[j - 1][i]]);
		}
	}
	vector<int> seq;
	int cur = 0; k--;
	for(int i = maxm - 1; i >= 0; i--){
		if(cost[i][cur] <= k){
			k -= cost[i][cur];
			cur = nxt[i][cur];
		}
	}
	set<int> now;
	vector<int> ans;
	for(int i = cur; i < n; i++){
		if(now.count(a[i])){
			while(now.count(a[i])){
				now.erase(ans.back());
				ans.pop_back();
			}
		} else {
			ans.push_back(a[i]);
			now.insert(a[i]);
		}
	}
	for(int v : ans) cout << v << " ";
	cout << endl;
	return 0;
}

