    vector<ll> tmp;
    set<int> used;
    rep(b, n) {
        ll l = v[b];
        if (find(tmp.begin(), tmp.end(), l) == tmp.end()) {
            tmp.push_back(l);
            used.insert(l);
        } else {
            while (contain(used, l)) {
                used.erase(used.find(tmp.back()));
                tmp.pop_back();
            }
        }
    }
    print(tmp);
}

