using namespace std;

typedef long long ll;

#define int ll

typedef pair<int, int> ii;

const int N = 2e5+100, M = 58, INF = 5e17;

int ls[N], a[N];

ii go[N][M];

int run(int it, int &cnt){
	for(int lg=M-1 ; lg>=0 ; lg--){
		if(go[it][lg].second > cnt)
			continue;
		cnt -= go[it][lg].second;
		it = go[it][lg].first;
		lg = M;
	}
	return it;
}

signed main(){
	ios_base::sync_with_stdio(false);cin.tie(NULL);
	int n, k;cin >> n >> k;
	for(int i=0 ; i<n ; i++)
		cin >> a[i];
	for(int i=n-1 ; i>=0 ; i--)
		ls[a[i]] = i;
	for(int i=n-1 ; i>=0 ; i--){
		int ind = ls[a[i]];
		ls[a[i]] = i;
		go[i][0].first = (ind+1)%n;
		go[i][0].second = (ind>i ? ind-i : ind-i+n) + 1;
	}

	for(int lg=1 ; lg<M ; lg++)
		for(int i=0 ; i<n ; i++){
			go[i][lg].first = go[ go[i][lg-1].first ][lg-1].first;
			go[i][lg].second = go[ go[i][lg-1].first ][lg-1].second + go[i][lg-1].second;
			if(go[i][lg].second > INF)
				go[i][lg].second = INF;
		}

	int cnt = n*k;
	int it = run(0, cnt);
	vector<int> ans;
	multiset<int> st;
	for(int i=0 ; i<cnt ; i++){
		int cur = a[(i+it)%n];
		bool f = true;
		while(st.count(cur)){
			f = false;
			st.erase(st.find(ans.back()));
			ans.pop_back();
		}
		if(f){
			ans.push_back(cur);
			st.insert(cur);
		}
	}
	for(int i=0 ; i<ans.size() ; i++)
		cout << ans[i] << " \n"[i == ans.size()-1];
 	return 0;
}

