    }
    rep(i,MAX){
        for (auto p:pos[i]){
            pos[i].push_back(p+N);
        }
    }
    ll now=0,round=1,cycle;
    vector<Pll> cnt;
    while(1){
        ll next=*upper_bound(pos[A[now]].begin(),pos[A[now]].end(),now);
        if (next>N-1){
            round++;
            next-=N;
        }
        cnt.push_back(Pll(round,next));
        if (next==N-1){
            cycle=round;
            break;
        }
        now=next+1;
    }
    ll s=cnt.size();
    K%=cycle;
    ll lb=-1,ub=s;
    while(ub-lb>1){
        ll mid=(lb+ub)/2;
        if (cnt[mid].first>K){
            ub=mid;
        }
        else {
            lb=mid;
        }
    }
    if (lb==-1){
        cout << endl;
        return 0;
