ll N, K;
vector<ll> A;
vector<ll> ans;

void calc(int num) {
	ll vacant;
	ll index;
	index = num;
	vacant = index-1;
	vector<ll> y(N);
	vector<ll> g(N);
	while (index < N*K-1) {
		// cout << index << endl;
		if (g[index%N] != 0) {
			vacant = (N*K/g[index%N]) * g[index%N] - 1;
			index = vacant + 1;
			g[index%N] = 0;
		} else {
			if (y[index%N] != 0) {
				if (index%N == 0) {
					g[0] = index-1;
				}
				if (index + y[index%N] <= N*K-1) {
					index = index + y[index%N];
					vacant = index;
					index++;
				} else {
					break;
				}
			} else {
				ll number = A[index%N];
				while (1) {
					index++;
					if (A[index%N] == number) {
						if (index <= N*K-1) {
							y[(vacant+1)%N] = index - (vacant + 1);
							vacant = index;
						}
						break;
					}
				}
				index++;
			}
		}

		// cout << index << endl;
	}

	if (vacant == N*K-1) {
		return;
	} else {
		ans.pb(A[(vacant+1)%N]);
		if (vacant+2 <= N*K-1) {
			calc(vacant+2);
		}
	}
}

