using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;
typedef pair<ll,P> PP;

struct rollinghash{
	static const int MD=3;
	static const int MAX=200005;
	const ll base[MD]={210527LL,210911LL,211231LL};
	const ll mods[MD]={999999937LL, 1000000007LL,912941443LL};
	ll hash[MD][MAX+1];
	ll pw[MD][MAX+1];
	void init(){
		memset(hash,0,sizeof(hash));
		for(int i=0;i<MD;i++){
			pw[i][0]=1;
			for(int j=0;j<MAX;j++){
				pw[i][j+1]=pw[i][j]*base[i]%mods[i];
			}
		}
	}
	void construct(const string &str){
		int n=str.size();
		for(int i=0;i<MD;i++){
			hash[i][0]=0;
			for(int j=0;j<n;j++){
				hash[i][j+1]=(hash[i][j]*base[i]%mods[i]+str[j])%mods[i];
			}
		}
	}
	void add(int pos,ll val){
		for(int i=0;i<MD;i++){
			hash[i][pos+1]=(hash[i][pos]*base[i]%mods[i]+val)%mods[i];
		}
	}
	PP get(int pos){
		return PP(hash[0][pos],P(hash[1][pos],hash[2][pos]));
	}
};

rollinghash ro;

int n;
ll k;
int a[200005];
map<PP,ll> mp[200005];
int rest[200005];
int ans[200005];
int len=0;

void print(){
	for(int i=0;i<len;i++){
		printf("%d%c",ans[i],(i+1)==len?'\n':' ');
	}
	if(len==0){
		printf("\n");
	}
}

void solve(){
	memset(rest,-1,sizeof(rest));
	for(ll loop=0;loop<k;loop++){
		for(int i=0;i<n;i++){
			//printf("(%lld %d %d)\n",loop,i,a[i]);
			//print();
			if(rest[a[i]]==-1 || rest[a[i]]>=len){
				ro.add(len,a[i]);
				rest[a[i]]=len;
				ans[len]=a[i];
				len++;
			}else{
				int tmp=len;
				len=rest[a[i]];
				for(int j=rest[a[i]];j<tmp;j++){
					//printf("erase%d\n",ans[j]);
					rest[ans[j]]=-1;
				}
				rest[a[i]]=-1;
			}
			PP val=ro.get(len);
			if(mp[i].find(val)!=mp[i].end()){
				ll dif=loop-mp[i][val];
				ll restloop=k-1LL-loop;
				ll plusloop=restloop/dif;
				loop+=plusloop*dif;
			}
			mp[i][val]=loop;
		}
	}
}

int main(void){
	scanf("%d%lld",&n,&k);
	for(int i=0;i<n;i++){
		scanf("%d",&a[i]);
	}
	ro.init();
	solve();
	for(int i=0;i<len;i++){
		printf("%d%c",ans[i],(i+1)==len?'\n':' ');
	}

	return 0;
}

