    // ダブリングで最初の方を削るパート
    vector<ll> last(200000);
    vector<vector<ll>> step(60, vector<ll>(n));
    for(ll i=2*n-1; i>=0; --i) {
        if(i < n) step[0][i] = last[a[i%n]]-i+1;
        last[a[i%n]] = i;
    }
    FOR(i, 1, 60) REP(j, n) {
        if(j+step[i-1][j] < 0) return 0;
        step[i][j] = step[i-1][j] + step[i-1][(j+step[i-1][j])%n];
    }
    ll x = 0;
    while(true) {
        bool update = false;
        for(ll i=59; i>=0; --i) {
            if(x + step[i][x%n] < n*k) {
                x += step[i][x%n];
                update = true;
                break;
            }
        }
        if(!update) break;
    }
    // 残ってる部分をシミュレーション
    stack<ll> st;
    set<ll> exist;
    FOR(i, x, n*k) {
        if(exist.find(a[i%n]) == exist.end()) {
            exist.insert(a[i%n]);
            st.push(a[i%n]);
        } else {
            while(st.size() && st.top()!=a[i%n]) {
                exist.erase(st.top());
                st.pop();
            }
            exist.erase(st.top());
            st.pop();
        }
    }
    // stackを逆順にして出力
    vector<ll> ans;
    while(st.size()) {
        ans.push_back(st.top());
        st.pop();
    }
    reverse(ALL(ans));
    REP(i, ans.size()) cout << ans[i]+1 << (i+1==ans.size()?'\n':' ');

    return 0;
}

