    cin.tie(0);
    ios::sync_with_stdio(false);

    ll n,k;
    cin >> n >> k;

    vector<ll> a(n);
    for(int i = 0; i < n; i++){
        cin >> a[i];
    }

    vector<list<ll>> tv(2*100000 + 1);

    for(int i = 0; i < n; i++){
        tv[a[i]].push_back(i);
    }

    vector<vector<pair<ll,ll>>> x;

    for(int i = 0; i <= 2*100000; i++){
        vector<pair<ll,ll>> t;
        for(auto itr = tv[i].begin(); itr != tv[i].end(); itr++){
            t.push_back({*itr,-1});
        }
        x.push_back(t);
    }

    vector<ll> next(2*100000 + 1,-1);
    next[0] = mysearch(n,-1,x,a);

    for(int i = 1; i <= 2*100000; i++){
        if(x[i].size() > 0){
            next[i] = mysearch(n,i,x,a);
        }
    }

    /*for(int i = 0; i < 10; i++){
        cerr << next[i] << endl;
    }*/

    ll count = 0;
    unordered_map<ll,ll> mp;

    ll cyclelen = 0;
    ll untcycle = 0;

    ll cur = 0;

    mp.insert({cur,count++});

    while(true){

        if(count == k){
            solve(n,cur,a);
            return 0;
        }

        cur = next[cur];

        if(mp.find(cur) == mp.end()){
            mp.insert({cur,count++});
        }else{
            cyclelen = count - mp[cur];
            untcycle = mp[cur];
            break;
        }
    }

    /*cerr << cyclelen << " ";
    cerr << untcycle << endl;*/


    k -= untcycle;

    ll rest = k - (k/cyclelen)*cyclelen;
    if(rest <= 0){
        rest += cyclelen;
    }

    while(rest > 1){
        rest--;
        cur = next[cur];
    }

    //cerr << cur << endl;

    solve(n,cur,a);

    return 0;
}

