    }
    for(int i = 0; i < N; i++) {
        if(firstappear[A[i]] != -1) {
            dp[lastappear[A[i]]][0].first = (i + 1) % N;
            if(i == (N - 1)) dp[lastappear[A[i]]][0].second++;
            lastappear[A[i]] = i;
            continue;
        } else {
            firstappear[A[i]] = i;
            lastappear[A[i]] = i;
            continue;
        }
    }
    for(int val = 1; val <= 2e5; val++) {
        if(firstappear[val] == -1) continue;
