            dp[index][timer].second += dp[index][timer-1].second;
            int now = dp[index][timer - 1].first;
            dp[index][timer].second += dp[now][timer-1].second;
            dp[index][timer].first = dp[now][timer-1].first;
        }
    }
    now = {0, 0};
    f(50);
    //cerr << now.first << " " << now.second << endl;
    while(now.second < K) {
        int pos = now.first;
        if(used[A[pos]]) {
            while(used[A[pos]]) {
                used[ans.back()] = false;
                ans.pop_back();
            }
        } else {
            used[A[pos]] = true;
            ans.push_back(A[pos]);
        }
        now.first++;
        if(now.first == N) {
