int nextIdx[200010];

void calcNextIdx() {
    unordered_map<int, int> m;
    for (int i = N - 1; i >= 0; i--) {
        auto it = m.find(A[i]);
        if (it != m.end()) {
            nextIdx[i] = it->second;
        }
        m[A[i]] = i;
    }
    for (int i = N - 1; i >= 0; i--) {
        auto it = m.find(A[i]);
        if (it != m.end()) {
            nextIdx[i] = it->second;
        }
        m[A[i]] = i;
    }
}

bool inserted[200010];

signed main() {
    cin >> N >> K;

    inputVector(A, N);

    calcNextIdx();

    int loop = 0;
    int now = 0;
    int target = -1;
    unordered_map<int, int> m, rm;
    m[N - 1] = 0;
    rm[0] = N - 1;
    //fprintf(stderr, " m[%lld] = 0\n", N - 1);
    while (true) {
        int next = nextIdx[now];
        if (next <= now || next == N - 1) {
            loop++;
            if (loop == K) {
                target = now;
                break;
            }
            if (m.find(next) != m.end()) {
                //cerr << "  next = " << next << endl;
                int start = m[next];
                int period = loop - m[next];
                int left = K - start - 1;
                //fprintf(stderr, "start:%lld period:%lld left:%lld\n", start, period, left);
                left %= period;
                //fprintf(stderr, " -> left:%lld\n", left);
                target = rm[start + left] + 1;
                //if (target == -1) target = N - 1;
                if (target == N) target = 0;
                break;
            }
            m[next] = loop;
            rm[loop] = next;
            //fprintf(stderr, " m[%lld] = %lld\n", next, loop);
        }
        //fprintf(stderr, "now:%lld next:%lld loop:%lld\n", now, next, loop);
        now = next + 1;
        if (now == N) now = 0;
    }

    assert(target != -1);
    //cerr << "target = " << target << endl;

    vector<int> ret;
    REP(i, target, N - 1) {
        if (inserted[A[i]]) {
            while (!ret.empty() && ret.back() != A[i]) {
                inserted[ret.back()] = false;
                ret.pop_back();
            }
            if (!ret.empty()) {
                inserted[ret.back()] = false;
                ret.pop_back();
            }
        } else {
            ret.push_back(A[i]);
            inserted[A[i]] = true;
        }
    }

    for (auto v : ret) cout << v << " ";
    cout << endl;

    return 0;
}

