  }

  int upper = make_doubling();

  ll jump = fast_simulate(upper);

  for (ll j = jump; j < (ll)(n) * k; ++j) {
    int ind = (int)(j % (ll)(n));

    bool flg = false;

    while (exist[a[ind]]) {
      flg = true;
      exist[s.back()] = false;
      s.pop_back();
    }

    if (!flg) {
      s.push_back(a[ind]);
