const int N=2e5+5;
deque<int> simulate(deque<int> a){
    deque<int> q;
    vector<int> cnt(N);
    for(auto p:a)
    {
        q.pb(p);
        cnt[p]++;
        if(cnt[p]>1)
        {
            q.pop_back();
            while(q.back()!=p)
                cnt[q.back()]--,q.pop_back();
            cnt[p]-=2;
            q.pop_back();
        }
    }
    return q;
}
deque<int> a;
ll k;
deque<int> solve()
{
    int n=(int)a.size();
    ll time=(ll)n*k;
    if(time<N)
    {
        for(int i=1;i<k;i++)
            for(int j=0;j<n;j++)
                a.pb(a[j]);
        return simulate(a);
    }
    for(int i=1;i<n;i++)
        if(a[i]==a[0])
        {
            for(int j=0;j<=i;j++)
                a.pop_front();
            return solve();
        }
    if(k%2)
    {
        deque<int> sl=a;
        a.pop_front();
        k/=2;
        auto it=solve();
        for(auto p:sl)
            it.pb(p);
        return simulate(it);
    }
    else
    {
        a.pop_front();
        k/=2;
        return solve();
    }
}
