void outt(int x) {
    if (S[x] == -1)
        return;
    stack<ll> st;
    for (int i = S[x]; i <= n; i++) {
        if (!add[a[i]]) {
            st.push(a[i]);
            add[a[i]] = 1;
        } else {
            while (add[a[i]]) {
                add[st.top()] = 0;
                st.pop();
            }
        }
    }
    while (!st.empty()) {
        c.pb(st.top());
        st.pop();
    }
    reverse(c.begin(), c.end());
    for (int i = 0; i < c.size(); i++)
        cout << c[i] << " ";
}


