  int a[n];
  REP(i, n) cin>>a[i];

  vector<int> prev(20'0010, -1);
  long long g[n][61];
  REP(i, 2 * n){
    int ni = i % n;
    if(prev[a[ni]] < 0){
      prev[a[ni]] = i;
      continue;
    }

    int start = prev[a[ni]];
    if(start >= n) continue;
    g[start][0] = i - start + 1;
    prev[a[ni]] = i;
  }

  //REP(i, n) cout << g[i][0] << ' '; cout << endl;


  REPP(j, 60){
    REP(i, n){
      g[i][j] = g[i][j - 1];
      long long mid = i + g[i][j - 1];
      if(mid >= n * k){
        g[i][j] = n * k;
        continue;
      }
      long temp = g[(int)(mid % n)][j - 1];
      if(temp >= n * k){
        g[i][j] = n * k;
        continue;
      }
      g[i][j] += temp;
      g[i][j] = min(g[i][j], n * k);
    }
  }

  //REP(i, n) cout << g[i][60] << ' '; cout << endl;


  //ここでプログラムが止まらなっているっぽい
