void solve(void)
{
  ll N, K; cin >> N >> K;
  vector<int> A(N);
  for (auto& a : A) { cin >> a; }
  vector<int> B(A.size()*2);
  boost::copy(A, B.begin());
  boost::copy(A, B.begin()+N);
  map<int, set<int>> mp{};
  for (int i = 0; i < B.size(); ++i) {
    mp[B[i]].emplace(i);
  }

  ll NK = N*K;
  ll logNK = 1;
  while (1LL << logNK <= NK) {
    ++logNK;
  }

  vector<vector<ll>> table(N, vector<ll>(logNK, -1));
  for (ll i = 0; i < N; ++i) {
    auto b = B[i];
    const auto& indexList = mp[b];
    auto itr = indexList.upper_bound(i);
    assert(itr != indexList.end());
    auto j = *itr;
    table[i][0] = (j + 1) - i;
  }

  for (ll i = 1; i < logNK; ++i) {
    for (int n = 0; n < N; ++n) {
      auto nn = table[n][i-1];
      table[n][i] = nn + table[(n + nn) % N][i-1];
    }
  }

  ll itr = 0;
  for (ll b = logNK-1; b >= 0; --b) {
    auto next = itr + table[itr % N][b];
    if (next > NK) {
      continue;
    } else {
      itr = next;
    }
  }

  vector<int> buff{};
  buff.reserve(N*2);
  map<int, int> memo{};
  for (ll i = itr; i < NK; ++i) {
    auto a = A[i%N];
    if (memo.count(a)) {
      auto j = memo[a];
      buff.resize(j);
      memo.erase(a);
    } else {
      buff.push_back(a);
      memo[a] = buff.size() - 1;
    }
  }
  for (int i = 0; i < buff.size(); ++i) {
    if (i)
      cout << SPACE << buff[i];
    else
      cout << buff[i];
  }
  cout << CRLF;
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}


