int P[200005];
int tmp[200005];
int tmp2[200005];
int A[200005];
long long N, K;
int gh[200005];
#define MX 200000

void perm(){
    int* lastpos = tmp;
    int* firstpos = tmp2;
    fill(lastpos, lastpos+200005, -1);
    fill(firstpos, firstpos+200005, -1);

    for (int i=0, k; i<N; i++){
        k = A[i];
        if (lastpos[k] != -1)
            P[lastpos[k]] = (i+1)%N;
        if (firstpos[k] == -1)
            firstpos[k] = i;
        lastpos[k] = i;
        P[i] = firstpos[k] + 1;
    }
}

int calc_cycle(){
    int i=0;
    int cycle=0;
    do {
//        cout << "At " << i << endl;
        if (P[i] <= i + 1)
            cycle++, gh[cycle] = i;
        i = P[i];
    } while (i != 0);
    return cycle;
}

int main(){
    cin >> N >> K;
    for (int i=0;i<N; i++)
        cin >> A[i];
    perm();
    int cycle = calc_cycle();
    K%=cycle;
    int i = gh[K];
    while (i < N){
        if (P[i] == 0)
            break;
        if (P[i] > i+1)
            i = P[i];
        else
            cout << A[i++] << ' ';
    }

}

