#define int long long

vector<int> tmp[200010];
pair<int, int> graph[200010][2];
int visited2[200010] = {};
int a[200010];
int visited[200010][2] = {};

signed main(){
    int n, k;
    cin >> n >> k;

    for(int i = 0;i < n;i++){
        cin >> a[i];
        tmp[a[i]].push_back(i);
        graph[i][1] = make_pair((i+1)%n, i == n-1 ? 1 : 0);
    }

    for(int i = 0;i < n;i++){
        int next = upper_bound(tmp[a[i]].begin(), tmp[a[i]].end(), i) - tmp[a[i]].begin();
        if(next == tmp[a[i]].size()){
            graph[i][0] = make_pair(tmp[a[i]][0], 1);
        }else{
            graph[i][0] = make_pair(tmp[a[i]][next], 0);
        }
    }


    int v = 0;
    int og = 0;
    int cost = 0;
    while(1){
        if(visited[v][og] != 0){
            break;
        }

        visited[v][og] = 1;
        int nv = graph[v][og].first;
        cost += graph[v][og].second;
        v = nv;
        og = (og+1) % 2;
    }


    k = k - (k/cost)*cost;

    v = 0;
    og = 0;
    deque<int> que;


    while(k > 0){

        k -= graph[v][og].second;

        if(k == 0){
            for(int i = v;i < n;i++){

                if(visited2[a[i]] == 0){
                    que.push_back(a[i]);
                    visited2[a[i]] = 1;
                }else{
                    while(que.back() != a[i]){
                        que.pop_back();
                    }
                    que.pop_back();
                    visited2[a[i]] = 0;
                }


            }

            break;
        }

        v = graph[v][og].first;
        og = (og+1) % 2;
    }


    while(!que.empty()){
        cout << que.front();
        que.pop_front();
        if(que.empty()){
            cout << endl;
        }else{
            cout << " ";
        }
    }
    return 0;
}

