int main() {
  int n;
  ll k;
  cin >> n >> k;
  vector<int> a(n);
  rep(i, n) cin >> a[i];

  vector<vector<ll>> next(60, vector<ll>(n)); //ダブリング
  vector<int> prev(200010, -1);
  rep(i, 2) {
    rep(j, n) {
      if (prev[a[j]] != -1)
        next[0][prev[a[j]]%n] = n*i+j-prev[a[j]]+1; //同じ値までの距離+1
      prev[a[j]] = n*i+j; //座標
    }
  }
  for (int i=1; i<60; i++) {
    rep(j, n) {
      next[i][j] = next[i-1][j]+next[i-1][(next[i-1][j]+j)%n];
