#define REP(i,n) for(int i=0; i<(n); ++i)

int N;
long long K;
vector<int> A, B;

vector<int> dp;

const int MAX = 200200;
vector<int> same[MAX];
vector<int> nxtA, nxtB;

void print_result(int piv) {
    while (piv < N) {
        if (nxtA[piv] != -1) {
            piv = nxtA[piv];
            continue;
        } else {
            cout << A[piv++] << endl;
        }
        // cout << piv << endl;
    }
}

int main() {

    cin >> N >> K;

    A.resize(N);
    REP(i, N) cin >> A[i];

    // B : Aを2回繰り返した配列
    REP(i, 2 * N) B.emplace_back(A[i % N]);

    // same[i] : 数iが格納されているindexのvector
    REP(i, 2 * N) same[B[i]].emplace_back(i);

    // all_diff : Aの要素がすべて異なる
    bool all_diff = true;
    // nxtA[i] : Aの中で, A[i]と同じ数が次に現れるindexの次のindex (無ければ-1)
    nxtA.resize(N);
    REP(i, N) nxtA[i] = (same[A[i]][(int)(upper_bound(same[A[i]].begin(), same[A[i]].end(), i) - same[A[i]].begin())] + 1);
    REP(i, N) {
        if (nxtA[i] > N) {
            nxtA[i] = -1;
        } else {
            all_diff = false;
        }
    }

    if (all_diff) {
        if (K % (N + 1) != 0) {
            print_result((K - 1) % (N + 1));
        }
        return 0;
    }

    // nxtB[i] : Bの中で, B[i]と同じ数が次に現れるindexの次のindex
    nxtB.resize(N);
    REP(i, N) nxtB[i] = (same[B[i]][(int)(upper_bound(same[B[i]].begin(), same[B[i]].end(), i) - same[B[i]].begin())] + 1) % N;

    int cur = 0;
    while (true) {
        if (nxtB[cur] == 0) break;
        dp.emplace_back(nxtB[cur]);
        cur = nxtB[cur];
    }

    // REP(i, N) cerr << nxtA[i] << endl;
    // cerr << "dpsize " << dp.size() << endl;

    print_result(dp[(K - 1) % (int)dp.size()]);

}

#include <bits/stdc++.h>
using namespace std;

#define N 200020

typedef long long ll;
int n, a[N<<1];
ll k;

int to[N], g[N];
int b[N];

int c[N];
int vis[N];

int main() {
	scanf("%d%lld", &n, &k);
	for (int i = 0; i < n; i ++) scanf("%d", &a[i]);
	for (int i = 0; i < n; i ++) a[n+i] = a[i];
	for (int i = 2 * n - 1; i >= 0; i --) {
		if (i < n) {
			g[i] = b[a[i]] + 1 - i;
			to[i] = (b[a[i]] + 1) % n;
		}
		b[a[i]] = i;
	}
	c[1] = 0;
	vis[0] = 1;
	int st, d;
	for (int i = 2;; i ++) {
		c[i] = to[c[i-1]];
		if (vis[c[i]]) {
			st = vis[c[i]];
			d = i - st;
			break;
		}
		vis[c[i]] = i;
	}
	ll up = k * n;
	ll p = 1;
	ll cur = 0;
	for (p = 1; p < st; p ++) {
		assert(cur % n == c[p]);
		if (cur + g[c[p]] >= up) break;
		cur += g[c[p]];
	}
	if (p == st) {
		ll bl = 0;
		for (ll i = st; i < st + d; i ++) {
			bl += g[c[i]];
		}
		ll step = (up - 1 - cur) / bl;
		cur += bl * step;
	}
	for (; ; p ++) {
		if (cur + g[c[p]] >= up) break;
		cur += g[c[p]];
	}
	assert(p <= st + d);
	assert(cur < up);
	memset(vis, 0, sizeof vis);
	int en = 0;
	for (ll i = cur; i < up; i ++) {
		int j = i % n;
		if (!vis[a[j]]) b[++en] = a[j], vis[a[j]] = en;
		else {
			int oen = en;
			en = vis[a[j]] - 1;
			for (int k = oen; k > en; k --) vis[b[k]] = 0;
		}
	}
	for (int i = 1; i <= en; i++) printf("%d ", b[i]);
}

