	vector<vector<ll>> doubling((log2(K)+log2(N))+10,vector<ll>(N,0));
	rep(i,N){
		ll t=lower_bound(all(index[A[i]]),i)-index[A[i]].begin();
		doubling[0][i]=1+index[A[i]][t+1]-index[A[i]][t];
	}
	repeq(k,doubling.size()-1){
		rep(i,N){
			doubling[k][i]=doubling[k-1][i]+doubling[k-1][(i+doubling[k-1][i])%N];
