#include<bits/stdc++.h>
using namespace std;
typedef long long LL;
const LL MAXN = 200007;
const LL LOG = 60;

LL last[MAXN];
LL a[MAXN];
LL exist[MAXN];

LL jump[MAXN][LOG];
LL dist[MAXN][LOG];

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    LL n, m;
    cin >> n >> m;

    for (LL i = 0; i < n; i++) cin >> a[i];

    for (LL i = n-1; i >= 0; i--) last[a[i]] = i+n;

    for (LL i = n-1; i >= 0; i--) {
        jump[i][0] = (1+last[a[i]])%n;
        dist[i][0] = 1+last[a[i]]-i;
        assert(dist[i][0] >= 0);
        last[a[i]] = i;
    }

    for (LL k = 1; k < LOG; k++) {
        for (LL i = 0; i < n; i++) {
            jump[i][k] = jump[jump[i][k-1]][k-1];
            dist[i][k] = dist[i][k-1] + dist[ jump[i][k-1] ][k-1];
        }
    }

    LL moves = n*m-1;
    LL i = 0;
    for (LL k = LOG-1; k >= 0; k--) {
        if (dist[i][k] <= moves) {
//            cout << "at " << i << " " << dist[i][k] << endl;
            moves -= dist[i][k];
            i = jump[i][k];
        }
    }

//    cout << "at " << i << " rem moves: " << moves << endl;

    vector< LL >ans;
    ans.push_back(a[i]);
    exist[a[i]] = 1;
    while (moves--) {
        i = (i+1)%n;
        if (exist[a[i]]) {
            while (exist[a[i]]) {
                exist[ans.back()] = 0;
                ans.pop_back();
            }
        } else {
            ans.push_back(a[i]);
            exist[a[i]] = 1;
        }
    }

    for (LL x : ans) cout << x << " ";

    return 0;
}

