vector<int> solve( int n, ll K, const vector<int> a )
{
    vector<int> b(n+1,0);           // b[i]: (a[i],..,a[n-1])という数列に対して
                                    //       今回の操作を行った時の結果の数列の第1項。ただし空集合の場合は0とする。
                                    //       なお便宜上b[n]=0としておく。
    int i;

    map<int,int> z;                // z[k]=(a[i]=kとなるようなi)  というメモ
    for(i=n-1; i>=0; i--) {        // 後ろから見る
        auto ret = z.insert(make_pair(a[i],i));
        if(ret.second) {       // zに無事に追加できたとき（つまり、a[i]が初めて現れた場合）
            b[i] = a[i];       // このa[i]は最後の配列まで生き残る
        }
        else {                 // すでにこのa[i]が登録済のとき（つまりもっと後ろにa[i]がある）
            int k = ret.first->second;
            b[i] = b[k+1];     // すでにあったa[i]の位置の次の箇所のbの値を見ればよい（k=n-1のときは空集合になるのでb[n]=0でよい）
            int p;
            for(p=i+1; p<=k; p++) {
                z.erase(a[p]);
            }
        }
    }

    map<int,int> id;        // id[k]=(a[i]=kとなるような最初のi)
    for(i=0; i<n; i++) {
        if(id.find(a[i])==id.end()) {
            id[a[i]]=i;
        }
    }

    // 配列Aの入力をK回繰り返すが、配列Aを何回か繰り返すと周期的になるはず。
    // 配列Aの入力をi回終えた時点での結果について、
    // aa[i]=(その時点の配列のうち一番最初の数（ただし空集合なら0））としてメモ。
    // それの周期を調べる。aaに以前出た数が初めて出た時点で、それを aa[base]=aa[siz] とする。
    // そうすれば巨大なKについてのaa[K]も周期性を使って求められる。
    int base=0;
    map<int,int> save;          // save[k]=(aa[i]=kとなるようなi)
    vector<int> aa;    
    int curr=0, next=0;
    for(i=0; i<n+1; i++) {      // aaに(n+1)個の値（0以上n未満）を登録すれば、その中に必ず重複要素が見つかるはず。
        auto it = save.find(curr);
        if(it==save.end()) {
            save[curr]=i;      // なければ登録     
        }
        else {
            base = it->second;
            break;
        }
        aa.push_back(curr);
        int tmp=b[curr];
        if(tmp==0) next=0;
        else next = id[tmp]+1;
        curr = next;
    }

    int siz=(int)aa.size();

    int K2=0;
    K--;           // (K-1)回終了時点での状況を把握して、そこから結果を出す
    if(K<siz) {
        K2 = (int)K;
    }
    else {
        K2 = base + (K-base)%(siz-base);
    }

    // solve
    vector<int> ans;
    curr=aa[K2];
    map<int,int> idsave;
    for(i=curr; i<n; i++) {
        auto it = idsave.find(a[i]);
        if(it==idsave.end()) {
            idsave[a[i]]=(int)ans.size();
            ans.push_back(a[i]);
        }
        else {
            int newsize = it->second;
            while((int)ans.size()>newsize) {
                idsave.erase(ans.back());
                ans.pop_back();
            }
        }
    }

    return ans;
}

