#define N 200005
#define MOD 998244353
using namespace std;

int n;
ll k;
ii go[N];
int ok[N];
int a[N];
int vis[N],s[N],ps[N];

void solve(int pos) {

	vector<int> res;

	for(int i=pos;i<=n;i++) {

		if(ok[a[i]]) {

			while(res.back()!=a[i]) ok[res.back()]=0,res.ppb();

			res.ppb();

			ok[a[i]]=0;

		} else res.pb(a[i]),ok[a[i]]=1;

	}

	for(auto x:res) printf("%d ",x);

	exit(0);

}

ii make(int pos,int add) {

	if(pos>n) add+=1,pos-=n;

	while(pos>n) pos-=n; 	

	return {pos,add};

}

int main() {

	map<int,vector<int>> pos;

	scanf("%d %lld",&n,&k);
	k--;

	for(int i=1;i<=n;i++) {

		scanf("%d",a+i);

		pos[a[i]].pb(i);

	}

	for(auto x:pos) {

		for(int i=0;i<sz(x.nd)-1;i++) {

			go[x.nd[i]]=make(x.nd[i+1]+1,0);

		}

		go[x.nd.back()]=make(n+x.nd[0]+1,0);

	}

	int cnt=0;
	int cur=1;

	s[cnt]=1;
	ps[1]=cnt;

	do {

		if(cnt==k) {

			solve(cur);

			return 0;

		}

		vis[cur]=1;

		int bef=cnt;

		cnt+=go[cur].nd;
		cur=go[cur].st;

		if(bef!=cnt) {

			s[cnt]=cur;
			ps[cur]=cnt;

		}

	} while(!vis[cur]);

	k-=ps[cur];

	cnt=(cnt-ps[cur]);

	k%=cnt;

	solve(s[k]);

}

