typedef long long ll;
const int N = (int) 2e5 + 7;
int n;
int a[N];
int u[N];
bool valid[N];

ll k;
vector <int> p[N];

int rep(int num) {
        return num % n;
}

vector <int> cy;

void add_cy(int x) {
        if (valid[x]) {
                cy.push_back(x);
        }
}

vector <int> sol;
set <int> cur;

void ins(int x) {
        if (cur.find(x) == cur.end()) {
                sol.push_back(x);
                cur.insert(x);
        } else {
                int deleted = -1;
                while (deleted != x) {
                        deleted = sol.back();
                        sol.pop_back();
                        cur.erase(deleted);
                }
        }
}

int main() {
        ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);

        cin >> n >> k;

        for (int i = 0; i < n; i++) {
                cin >> a[i];
                p[a[i]].push_back(i);
        }

        for (int i = 1; i < N; i++) {
                int sz = (int) p[i].size();
                if (sz > 0) {
                        for (int j = 0; j + 1 < sz; j++) {
                                u[p[i][j]] = rep(p[i][j + 1] + 1);
                        }
                        u[p[i].back()] = rep(p[i][0] + 1);
                        valid[p[i].back()] = 1;
                }
        }

        cy.push_back(n);
        add_cy(0);
        int now = u[0];

        while (now != 0) {
                add_cy(now);
                now = u[now];
        }

        int sz = (int) cy.size();
        k %= sz;

        for (int i = cy[k]; i < n; i++) {
                ins(a[i]);
        }

        for (auto &it : sol) {
                cout << it << " ";
        }
        cout << "\n";

        return 0;
}

