int main() {
	int64_t n, k; cin >> n >> k;
	int a[n]; for(int i = 0; i < n; ++i) cin >> a[i];
	int pre[200010]; for(int i = 0; i < 200010; ++i) pre[i] = -1;
	// dp[j][i] := iから2^j回遷移したときの消費回数
	int64_t dp[60][n];
	for(int i = 0; i < 2 * n; ++i) {
		if(pre[a[i % n]] != -1) {
			dp[0][pre[a[i % n]]] = (i + 1) - pre[a[i % n]];
		}
		pre[a[i % n]] = i;
	}
	for(int j = 1; j < 60; ++j) {
		for(int i = 0; i < n; ++i) {
			dp[j][i] = dp[j - 1][i] + dp[j - 1][(i + dp[j - 1][i]) % n];
		}
	}
	int64_t goal = n * k;
	int64_t mul = 0, now = 0;
	while(true) {
		bool flg = true;
		for(int j = 59; j >= 0; --j) {
			if(now + n * mul + dp[j][now] < goal) {
				if(now + n * mul + dp[j][now] < 0) continue;
				now = now + n * mul + dp[j][now];
				mul = now / n;
				now %= n;
				flg = false;
				break;
			}
		}
		if(flg) break;
	}
	deque<int> ans;
	bool used[200010] = {};
	for(int i = now; i < n; ++i) {
		if(used[a[i]]) {
			while(ans.size()) {
				int t = ans.back();
				ans.pop_back();
				if(t == a[i]) break;
			}
			used[a[i]] = false;
		} else {
			ans.push_back(a[i]);
			used[a[i]] = true;
		}
	}
	for(int i : ans) {
		cout << i << " ";
	}
	cout << "\n";
	return 0;
}

