using namespace std;

using int64 = long long;

constexpr int MAX_VALUE = 200000;

constexpr int DEBUG = 0;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n; int64 k;
  cin >> n >> k;
  vector<int> xs(n);
  for (int i = 0; i < n; i++) cin >> xs[i];

  vector<vector<int>> value_to_positions(MAX_VALUE + 1);
  for (int i = 0; i < n; i++) {
    value_to_positions[xs[i]].push_back(i);
  }
  vector<int> position_to_per_value_position(n);
  for (int v = 0; v <= MAX_VALUE; v++) {
    for (int i = 0; i < value_to_positions[v].size(); i++) {
      position_to_per_value_position[value_to_positions[v][i]] = i;
    }
  }

  int current_position = 0;
  int64 current_turn = 0;
  vector<int64> first_turn(n, -1);
  bool found_loop = false;
  while (current_turn < k - 1) {
    if (!found_loop) {
      if (first_turn[current_position] >= 0) {
        int64 cycle = current_turn - first_turn[current_position];
        found_loop = true;

        current_turn = (k - 2 - current_turn) / cycle * cycle;
      } else {
        first_turn[current_position] = current_turn;
      }
    }


    int value = xs[current_position];
    int per_value_position = position_to_per_value_position[current_position];

    per_value_position++;
    if (per_value_position >= value_to_positions[value].size()) {
      per_value_position = 0;
      current_turn++;
    }

    int next_position = value_to_positions[value][per_value_position] + 1;
    if (next_position == n) {
      next_position = 0;
      current_turn++;
    }

    current_position = next_position;

    if (DEBUG) {
      cout << "current_turn: " << current_turn
          << " current_position: " << current_position << endl;
    }
  }

  if (DEBUG) {
    cout << "current_turn: " << current_turn
         << " current_position: " << current_position << endl;
  }

  if (current_turn == k) {
    if (current_position != 0) {
      cerr << "This case should not happen!" << endl;
      exit(1);
    }
    return 0;  // Output an empty list.
  }

  // current_turn == k - 1
  vector<int> stack;
  vector<int> in_stack(MAX_VALUE + 1);
  for (int i = current_position; i < n; i++) {
    if (in_stack[xs[i]]) {
      while (true) {
        int v = stack.back();
        stack.pop_back();
        in_stack[v] = 0;
        if (v == xs[i]) break;
      }
    } else {
      stack.push_back(xs[i]);
      in_stack[xs[i]] = 1;
    }
  }

  for (int i = 0; i < stack.size(); i++) {
    if (i > 0) cout << " ";
    cout << stack[i];
  }
  cout << endl;
}

