class Solver2 {
 public:
  LL n, k;
  vector<LL> a;
  vector<vector<int>> A;
  vector<vector<LL>> tr;
  Solver2(LL n, LL k) : n(n), k(k), a(n), A(200001), tr(58, vector<LL>(n, -1)){};

  void nextRow(int i) {
    if (tr[0][i] >= 0) return;
    int now = a[i];
    auto nxtp = upper_bound(A[now].begin(), A[now].end(), i);
    if (nxtp < A[now].end()) {
      tr[0][i] = *nxtp - i + 1;
    } else {
      tr[0][i] = A[now][0] + n - i + 1;
    }
  }

  void solve() {
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
      A[a[i]].push_back(i);
    }
    for (int i = 0; i < n; ++i) {
      nextRow(i);
    }
    DBG(a)
    for (int i = 1; i < tr.size(); ++i) {
      for (int j = 0; j < n; ++j) {
        int nxt = (tr[i - 1][j] + j) % n;
        tr[i][j] = tr[i - 1][j] + tr[i - 1][nxt];
      }
      DBG(i, tr[i])
    }
    DBG(a)
    LL sum = 0;
    LL now = 0;
    while (sum < n * k) {
      int P = 0;
      for (int i = tr.size() - 1; i >= 0; --i) {
        if (sum + tr[i][now] <= n * k) {
          P = i;
          break;
        }
        if (i == 0) P = -1;
      }
      if (P == -1) break;
      sum += tr[P][now];
      DBG(P, sum)
      now = sum % n;
    }
    DBG(a)
    DBG(now)
    vector<int> ans = calc(now);
    for (auto x : ans) {
      cout << x << ' ';
    }
    cout << endl;
  }
  vector<int> calc(int p) {
    if (p == 0) return vector<int>();
    vector<vector<int>> memo(200001);
    set<int> st;
    int size = 0;
    for (int i = p; i < n; ++i) {
      int now = a[i];
      if (memo[now].size() == 0) {
        memo[now].push_back(size);
        size++;
        st.insert(now);
      } else {
        size = memo[now][0];
        set<int> er;
        for (auto x : st) {
          DBG(x, memo[x], size)
          while (memo[x].size() > 0 && memo[x].back() >= size) memo[x].pop_back();
          if (memo[x].size() == 0) er.insert(x);
        }
        for (auto x : er) st.erase(x);
      }
    }
    vector<int> ret(size);
    for (int i = 1; i <= 200000; ++i) {
      for (auto j : memo[i]) {
        ret[j] = i;
      }
    }
    return ret;
  }
};
