int main(int argc, char *argv[]) {
#if defined(DEBUG)
  // GDB on Cygwin ignores redirection at run command.
  if (argc == 2) dup2(open(argv[1], 0), 0);
#else
  // For performance.  We should not use C-style stdio functions
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
#endif
  cout << setprecision(20);

  cin >> N >> K;
  A.resize(N);
  lastPos.resize(aLim+1, -1);
  nextOccDist.resize(N);
  revNOD.resize(N);
  for (ll i = 0; i < N; i++)  cin >> A.at(i);
  for (ll i = 0; i < N; i++) {
    ll a = A.at(i);
    ll p = lastPos.at(a);
    if (p >= 0)  {
      nextOccDist.at(p) = i - p;
      revNOD.at(i % N) = i - p;
    }
    lastPos.at(a) = i;
  }
  for (ll i = 0; i < N; i++) {
    ll a = A.at(i);
    ll p = lastPos.at(a);
    if (p >= 0)  {
      nextOccDist.at(p) = N + i - p;
      revNOD.at(i % N) = N + i - p;
    }
    lastPos.at(a) = -1;
  }


  cleared.resize(N, -1);
  ll i = 0;
  while (i < N*K && cleared.at(i % N) == -1) {
    cleared.at(i % N) = i;
    i += nextOccDist.at(i % N) + 1;
  }
  if (i < N*K) {
    ll dist = i - cleared.at(i % N);
    assert (dist % N == 0);
    i +=  dist * ((N * K - i) / dist);
  }else {
    i = 0;
  }

  while (1) {
    ll j = i + nextOccDist.at(i % N) + 1;
    if (j > N*K) break;
    i = j;
  }

  if (i == N*K) { return 0; }
  vector<ll> answer;
  ll i0 = i;
  answer.push_back(A.at(i % N));
  i++;
  while (i < N*K) {
    if (i - revNOD.at(i % N) < i0) { answer.push_back(A.at(i % N)); }
    else {
      ll newSize = answer.size() - revNOD.at(i % N);
      answer.resize(newSize);
    }
    i++;
  }
  for (ll t = 0; t < (ll)answer.size(); t++) {
    if (t > 0) { cout << " "; }
    cout << answer.at(t);
  }
  cout << endl;

  return 0;
}

