    nxt[a[i]] = i;
  }

  int lg = log2(n * k);
  for(int j = 1; j <= lg; ++j) {
    for(int i = 0; i < n; ++i) {
      jump[i][j] = jump[jump[i][j - 1]][j - 1]; 
      sum[i][j] = sum[i][j - 1] + sum[jump[i][j - 1]][j - 1]; 
    }
  }

  int idx = 0;
  ll tot = 1; 
  for(int i = lg; i >= 0; --i) {
    if(tot + sum[idx][i] <= k) {
      idx = jump[idx][i];
      tot += sum[idx][i]; 
    }
  }

  vector<int> v; 
  for(int i = idx; i < n; ++i) {
    if(!vis[a[i]]) {
      vis[a[i]] = 1; 
      v.push_back(a[i]); 
    } else {
      while(vis[a[i]]) {
        vis[v.back()] = 0; 
        v.pop_back();
      }
    }
  }

  for(int x : v) printf("%d ", x); 
  puts("");

}

