//約数と素因数分解
//divisor(n): 約数が入ったvectorを返す。
vector<ll> divisor(ll n){
    vector<ll> ans;
    REP(i, 1, sqrt(n) + 1){
        if(!(n % i)){
            ans.PB(i);
            if(i * i < n){
                ans.PB(n / i);
            }
        }
    }
    return ans;
}

