int main()
{
    const ll N = read<ll>();
    ll K = read<ll>();
    K *= N;
    const auto A = readVec<ll>(N);
    constexpr int MAX = 200000;
    std::vector<ll> last(MAX + 1, INF<ll>);
    std::vector<ll> plus(N, 0);
    for (int i = 2 * N - 1; i >= 0; i--) {
        if (i < N) { plus[i] = last[A[i]] - i + 1; }
        last[A[i % N]] = i;
    }
    std::vector<ll> dist(N, -1);
    dist[0] = 0;
    for (ll p = 0, plen = -1;;) {
        const ll to = (p + plus[p]) % N;
        const ll cost = dist[p] + plus[p];
        if (plus[p] > K) {
            SHOW(N, p, K);
            std::vector<ll> ans;
            std::set<int> st;
            for (ll i = 0; i < K; i++) {
                const ll v = A[(p + i) % N];
                if (st.find(v) != st.end()) {
                    for (;;) {
                        const ll b = ans.back();
                        st.erase(b), ans.pop_back();
                        if (b == v) { break; }
                    }
                } else {
                    ans.push_back(v), st.insert(v);
                }
            }
            for (int i = 0; i < ans.size(); i++) { std::cout << ans[i] << (i + 1 < ans.size() ? " " : ""); }
            std::cout << std::endl;
            return 0;
        }
        K -= plus[p];
        if (dist[to] != -1 and plen == -1) { plen = cost - dist[to], K %= plen; }
        dist[to] = cost, p = to;
    }
    return 0;
}

