#include<string.h>

typedef int32_t i32;
typedef int64_t i64;

#define ALLOC(size,type) ((type*)calloc((size),sizeof(type)))

void run (void) {
  i32 n;
  i64 k;
  scanf ("%" SCNi32 "%" SCNi64, &n, &k);
  i32 *a = ALLOC (n, i32);
  for (i32 i = 0; i < n; ++i) {
    scanf ("%" SCNi32, a + i);
  }
  const i32 m = 200000;
  i64 *next = ALLOC (2 * n, i64);
  i64 *memo = ALLOC (m + 1, i64);
  for (i32 i = 2 * n - 1; i >= 0; --i) {
    i32 x = i % n;
    next[i] = memo[a[x]];
    memo[a[x]] = i;
  }
  for (i32 i = 0; i < n; ++i) {
    next[i] = next[i] - i + 1;
  }
  memcpy (memo, next, sizeof (i64) * n);
  i64 *tmp = ALLOC (n, i64);
  i64 now = 0;
  for (;;) {
    memcpy (next, memo, sizeof (i64) * n);
    for (;;) {
      for (i32 i = 0; i < n; ++i) {
        tmp[i] = next[(i + next[i]) % n] + next[i];
      }
      if (now + tmp[now % n] >= n * k) break;
      memcpy (next, tmp, sizeof (i64) * n);
    }
    if (now + next[now % n] >= n * k) break;
    now += next[now % n];
  }
  uint8_t *elem = ALLOC (m + 1, uint8_t);
  i32 *ans = ALLOC (n, i32);
  i32 len = 0;
  for (i64 i = now; i < n * k; ++i) {
    i32 x = i % n;
    if (elem[a[x]]) {
      while (ans[len - 1] != a[x]) {
        elem[ans[--len]] = 0;
      }
      elem[ans[--len]] = 0;
    } else {
      ans[len++] = a[x];
      elem[a[x]] = 1;
    }
  }
  for (i32 i = 0; i < len; ++i) {
    printf ("%" PRIi32, ans[i]);
    putchar (i == len - 1 ? '\n' : ' ');
  }
}

int main (void) {
  run();
  return 0;
}

