  ll A[N];
  vector<ll> S[200003];
  ll M[200003];
  for (int i = 0; i < 200003; i++) {
    M[i] = -1LL;
  }
  vector<ll> cycle(0);
  vector<ll> start(0);
  start.push_back(0LL);
  ll where[N];
  for (ll i = 0; i < N; i++) {
    cin >> A[i];
    A[i]--;
    S[A[i]].push_back(i);
    where[i] = S[A[i]].size() - 1;
  }
  ll cnt = 0;
  while (0 == 0) {
    if (S[A[start[cnt]]].size() != where[start[cnt]] + 1) {
      cycle.push_back(S[A[start[cnt]]][where[start[cnt]] + 1] - S[A[start[cnt]]][where[start[cnt]]] + 1);
      start.push_back((start[cnt] + cycle[cnt]) % N);
    } else {
      cycle.push_back(S[A[start[cnt]]][0] + N - S[A[start[cnt]]][where[start[cnt]]] + 1);
      start.push_back((start[cnt] + cycle[cnt]) % N);
    }
    if (start[cnt+1] == 0) {
      break;
    }
    cnt++;
  }
  ll sum = 0;
  for (int i = 0; i < cycle.size(); i++) {
    sum += cycle[i];
  }
  ll X = ((N % sum) * (K % sum)) % sum;
  ll n;
  for (int i = 0; i < cycle.size(); i++) {
    X -= cycle[i];
    if (X <= 0) {
      n = i;
      break;
    }
  }
  X += cycle[n] - 1;
  vector<ll> ans(0);
  for (int i = 0; i <= X; i++) {
    int a = A[(start[n] + i) % N];
    if (M[a] == -1) {
      ans.push_back(a);
      M[a] = ans.size() - 1;
    } else {
      ans.erase(ans.begin() + M[a],ans.end());
      M[a] = -1;
    }
  }
  for (int i = 0; i < ans.size(); i++) {
    cout << ans[i] + 1 << " "; 
  }
  return 0;
}

