void solve() {
	for (int i = 0; i < n; i++) {
		if (v[i].empty())
			continue;
		v[i].push_back(v[i][0] + n);
		for (int j = 0; j < sz(v[i]) - 1; j++)
			b[v[i][j]] = v[i][j + 1] - v[i][j] + 1;
	}
	for (int i = 0; i < n; i++)
