	ll moradi = (LLONG_MAX >> 2);
	for (int j = 1; j < MXLG; j++)
		for (int i = 0; i < n; i++)
			c[i][j] = min(moradi, c[i][j - 1] + c[(i + c[i][j - 1]) % n][j - 1]);
	ll pt = 0;
	for (int i = MXLG - 1; ~i; i--)
		if (pt + c[pt % n][i] <= k)
