	vector<set<int>> pos(200001);
	for (int i = 0; i < N; i++) {
		cin >> A[i]; A[i+N] = A[i];
		pos[A[i]].insert(i); pos[A[i]].insert(i+N);
	}
	vector<int> loops(N, -1);
	int cnt = 0;
	for (int p = 0, l = 1; p < N && ++cnt < 20; p++) {
		p = *(++(pos[A[p]].lower_bound(p)));
		if (p >= N) {
			l++;
			p -= N;
		}
		loops[p] = l;
	}
	K %= loops[N-1];
	if (K == 0) {
		cout << endl; return 0;
	}
	int P = 0, L = 1;
	for (int i = 0; i < N; i++) {
		if (loops[i] <= K && L <= loops[i]) {
			P = i; L = loops[i];
		}
	}
	P++;
	K -= L-1;
	set<int> num;
	vector<int> res;
	while (K--) {
		for (; P < N; P++) {
			if (num.count(A[P])) {
				while (res.back() != A[P]) {
					num.erase(res.back());
					res.pop_back();
				}
