int main()
{
    ios_base::sync_with_stdio(0);

    cin >> N >> K;
    for (int i = 0; i < N; i++)
        cin >> arr[i];
    for (int i = 0; i < MAXN; i++)
        nocc[i] = 1e9;

    for (int i = 2 * N - 1; i >= 0; i--)
    {
        if (i < N)
            njump[i][0] = (nocc[arr[i]] + 1 - i);
        nocc[arr[i%N]] = i;
    }

    for (int i = 1; i < 60; i++)
    {
        for (int j = 0; j < N; j++)
        {
            ll x = njump[j][i-1];
            njump[j][i] = min ((ll) 1e18, x + njump[(j+x)%N][i-1]);
        }
    }

    ll ctot = 0;
    int cloc = 0;
    for (int i = 59; i >= 0; i--)
    {
        if (njump[cloc][i] + ctot <= N * K)
        {
            ctot += njump[cloc][i];
            cloc = (cloc + njump[cloc][i]) % N;
        }
    }

