int dir[200001];

int main()
{
	long long N,K;cin>>N>>K;
	vector<int>A(N);
	for(int i=0;i<N;i++)cin>>A[i];

	for (int i = 0; i < 200001; i++)dir[i] = -1;
	vector<int>D(N);
	for (int i = 0; i <2*N; i++)
	{
		D[i%N] = dir[A[i%N]];
		dir[A[i % N]] = i%N;
	}
	for (int i = 0; i < 200001; i++)dir[i] = -1;
	vector<int>revD(N);
	for (int i = 2*N-1; i >= 0; i--)
	{
		revD[i % N] = dir[A[i % N]];
		dir[A[i % N]] = i % N;
	}


	int T=0;

	vector<int>B(N);
	int pos = N-1;
	int t=0;
	while (1)
	{
		B[pos] = t;

		if(D[pos] >= pos)t++;

		pos = D[pos];

		if (pos == 0)break;

		pos = pos-1;
		if (pos < 0)
		{
			pos+=N;
			t++;
		}
	}

	T = t+1;
	for(int i=0;i<N;i++)B[i] = (T-B[i])%T;

	//cerr<<T<<endl;

	K%=T;

	//cerr<<K<<endl;

	/*for (int i = 0; i < N; i++)
	{
		cerr<<B[i]<<" ";
	}
	cerr<<endl;*/


	int s = 0;
	for(int i=N-1;i>=0;i--)
	{
		if (B[i] == K)
		{
			s = i+1;
			break;
		}
	}

	vector<int>ans;
	for (int i = s; i < N; i++)
	{
		if (revD[i] > i)
		{
			i = revD[i];
			continue;
		}

		ans.push_back(A[i]);
	}

	for (int i = 0; i < ans.size(); i++)
	{
		if(i)cout<<" ";
		cout<<ans[i];
	}
	cout<<endl;

	return 0;
}

