#include <iostream>
#include <vector>
using namespace std;
using ll = long long;

const int M = 2 * (int)1e5;
const int N = 2 * (int)1e5;
const int H = 45;
int fst[M];
int lst[M];
ll nxt[N][H];
int vals[N];

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	ll n, k;
	cin >> n >> k;
	for (int v = 0; v < M; ++v) lst[v] = -1;

	for (int i = 0; i < n; ++i) {
		int v;
		cin >> v;
		--v;

		if (lst[v] != -1) {
			nxt[lst[v]][0] = i - lst[v] + 1;
		} else {
			fst[v] = i;
		}
		lst[v] = i;
		vals[i] = v;
	}
	for (int v = 0; v < M; ++v) {
		if (lst[v] == -1) continue;
		nxt[lst[v]][0] = (n - lst[v]) + fst[v] + 1;
	}
	for (int j = 1; j < H; ++j) {
		for (int i = 0; i < n; ++i) {
			ll t = nxt[i][j-1];
			nxt[i][j] = t + nxt[(i+t)%n][j-1];
		}
	}

	ll i = 0;
	for (int j = H - 1; j >= 0; --j) {
		while(true) {
			ll t = nxt[i%n][j];
			if (i + t > k * n) break;
			i += t;
		}
	}

	for (int v = 0; v < M; ++v) lst[v] = -1;

	vector<ll> res;
	for (; i < k*n; ++i) {
		int v = vals[i % n];
		if (lst[v] != -1) {
			while(res.back() != v) res.pop_back();
			res.pop_back();
			lst[v] = -1;
		} else {
			res.push_back(v);
			lst[v] = 1;
		}
	}
	for (auto v : res) cout << v+1 << ' '; cout << '\n';
}

