    ix(nexts, i) = *poss[ix(as, i)].upper_bound(i);
  dump(nexts);
  vector<Z> jumps = {};
  Z current_start = 0,
    length = 0;
  do  {
    jumps.push_back(current_start);
    Z next_start = ix(nexts, current_start) + 1;
    length += next_start - current_start;
    current_start = next_start % N;
  } while (current_start != 0);
  dump(jumps);
  dump(length);
  Z rest = (N * K) % length;
  dump(rest);
  Z js;
  for (js = 0; js < jumps.size() - 1; js++) {
    Z diff = ix(nexts, ix(jumps, js)) + 1 - ix(jumps, js);
    if (rest < diff) break;
    rest -= diff;
  }
  dump(js);
  dump(rest);
  map<Z, set<Z>> indices;
  vector<Z> raw(rest);
  for (auto i = 0; i < rest; i++) {
    Z a = ix(as, (i + ix(jumps, js)) % N);
    ix(raw, i) = a;
    indices[a].insert(i);
  }
  Z pos = 0;
  vector<Z> ans;
  while (pos < raw.size()) {
    auto next = indices[ix(raw, pos)].upper_bound(pos);
    if (next == end(indices[ix(raw, pos)])) {
      ans.push_back(ix(raw, pos));
      pos++;
      continue;
    }
    pos = *next + 1;
  }
  cout << ans << endl;
}

