#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int MAXN = 4e5 + 5;
const int LOG = 60;

ll K;
int N;
int a[MAXN];
map <int, int> lst;
int nxt[MAXN][LOG];
ll weight[MAXN][LOG];
map <int, bool> in;

void load() {
	scanf("%d%lld", &N, &K);
	for (int i = 0; i < N; i++) {
		scanf("%d", a + i);
		a[i + N] = a[i];
	}
}

void solve() {
	K--;
	for (int i = 2 * N - 1; i >= 0; i--) {
		int tmp = lst[a[i]] + 1;
		weight[i][0] = tmp >= N;
		nxt[i][0] = tmp % N;
		lst[a[i]] = i;
	}

	for (int j = 1; j < LOG; j++)
		for (int i = 0; i < N; i++) {
			nxt[i][j] = nxt[nxt[i][j - 1]][j - 1];
			weight[i][j] = weight[i][j - 1] + weight[nxt[i][j - 1]][j - 1];
		}

	int pos = 0;
	for (int i = LOG - 1; i >= 0; i--)
		if (weight[pos][i] <= K) {
			K -= weight[pos][i];
			pos = nxt[pos][i];
		}

	vector <int> ans;
	for (int i = pos; i < N; i++)
		if (in[a[i]]) 
			while (1) {
				int tmp = ans.back();
				in[tmp] = false;
				ans.pop_back();
				if (tmp == a[i])
					break;
			}
		else {
			ans.push_back(a[i]);
			in[a[i]] = true;
		}

	for (auto it : ans)
		printf("%d ", it);
	puts("");
}

int main() {
	load();
	solve();
	return 0;
}

