const ll inf = 5e15;

struct Solver {
    V<ll> A, n2idx;
    ll N, K;
    Solver() {
        cin >> N >> K;
        A = V<ll>(N);
        n2idx = V<ll>(2e5 + 10, inf);
        for(ll i = 0; i < N; i++) {
            cin >> A[i];
            chmin(n2idx[A[i]], i);
        }
    }


    ll prefix() {
        V<ll> dyn_idx(2e5 + 10, inf);
        V<ll> prefix_begin(N + 10, 0);
        for(ll i = N - 1; 0 <= i; i--) {
            ll e = A[i];
            if(dyn_idx[e] == inf) {
                prefix_begin[i] = e;
            } else {
                prefix_begin[i] = prefix_begin[dyn_idx[e] + 1];
            }
            dyn_idx[e] = i;
        }

        V<ll> op_of_prefix(2e5 + 10, -1);
        ll prefix_now = 0;

        auto operate = [&] {
            ll idx = n2idx[prefix_now];
            ll nxt_prefix = prefix_begin[(idx == inf ? 0 : idx + 1)];
            return nxt_prefix;
        };

        for(ll i = 1; i < K; i++) {
            ll nxt_prefix = operate();
            if(op_of_prefix[nxt_prefix] != -1) {
                ll loop_cnt = i - op_of_prefix[nxt_prefix];
                ll rest = (K - 1) - i;
                rest %= loop_cnt;
                prefix_now = nxt_prefix;
                for(ll j = 0; j < rest; j++) prefix_now = operate();
                return prefix_now;
            }
            op_of_prefix[nxt_prefix] = i;
            prefix_now = nxt_prefix;
        }

        return prefix_now;
    }

    void solve() {
        stack<ll> stk;
        ll prefix_now = prefix();
        ll idx = 0;
        while(A[idx] != prefix_now) idx++;
        V<bool> exist(2e5 + 10, false);
        for(ll i = idx + 1; i < N; i++) {
            ll e = A[i];
            if(!exist[e]) {
                stk.push(e);
                exist[e] = true;
            } else {
                while(true) {
                    ll tmp = stk.top();
                    stk.pop();
                    exist[tmp] = false;
                    if(tmp == e) break;
                }
            }
        }
        V<ll> ans;
        while(stk.size()) {
            ans.push_back(stk.top());
            stk.pop();
        }

        reverse(ALL(ans));
        for(ll i = 0; i < ans.size(); i++) cout << ans[i] << " \n"[i + 1 == ans.size()];
    }
};

int main() {
    Solver().solve();
    return 0;
}

