const int INF = 1000000000;

void Pisz(vector<int>& a, int k)
{
    if (k == a.size())
        return;
    vector<bool> jest(200010, false);
    vector<int> x;
    for (int i = k; i < a.size(); ++i)
    {
        if (!jest[a[i]])
        {
            jest[a[i]] = true;
            x.push_back(a[i]);
        }
        else
        {
            while (x.back() != a[i])
            {
                jest[x.back()] = false;
                x.pop_back();
            }
            jest[x.back()] = false;
            x.pop_back();
        }
    }
    if (x.size() != 0)
        for (int i = 0; i < x.size(); ++i)
            cout << x[i] << " ";
}

int main()
{
    ios_base::sync_with_stdio(0);
    ll n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int i = 0; i < n; ++i)
        cin >> a[i];
    vector<int> nast(200010, INF);
    vector<int> zacz(n + 1);
    zacz[n] = -1;
    zacz[n - 1] = a[n - 1];
    nast[a[n - 1]] = n - 1;
    for (int i = n - 2; i >= 0; --i)
    {
        if (nast[a[i]] == INF)
            zacz[i] = a[i];
        else
        {
            int pos = nast[a[i]];
            if (pos == n - 1)
                zacz[i] = -1;
            else
                zacz[i] = zacz[pos + 1];
        }
        nast[a[i]] = i;
    }
    vector<int> pier(200010, INF);
    for (int i = 0; i < n; ++i)
        if (pier[a[i]] == INF)
            pier[a[i]] = i;
    vector<int> suf;
    vector<bool> odw(n + 1, false);
    int akt = 0;
    while (true)
    {
        odw[akt] = true;
        suf.push_back(akt);
        int Zacz = zacz[akt];
        int nast;
        if (Zacz == -1)
            nast = 0;
        else
        {
            int Pier = pier[Zacz];
            if (Pier == n - 1)
                nast = n;
            else
                nast = Pier + 1;
        }
        if (odw[nast])
        {
            suf.push_back(nast);
            break;
        }
        akt = nast;
    }
    int p = 0;
    while (suf[p] != suf.back())
        ++p;
    suf.pop_back();
    vector<int> s, c;
    for (int i = 0; i < p; ++i)
        s.push_back(suf[i]);
    for (int i = p; i < suf.size(); ++i)
        c.push_back(suf[i]);
    if (k <= (ll) s.size())
        Pisz(a, s[k - 1]);
    else
        Pisz(a, c[(k - (ll) s.size()) % (ll) c.size() - 1]);
    return 0;
}

