deque<ll> next_step(deque<ll> d){
    deque<ll> Dq = d;
    set<ll> se;
    for (int i = 0; i < d.size(); i++) se.insert(d[i]);

    for (int i = 0; i < N; i++)
    {
        if(se.find(A[i])==se.end()) {Dq.push_back(A[i]);se.insert(A[i]);}
        else{
            while(Dq.back()!=A[i] && !Dq.empty()) {se.erase(Dq.back()); Dq.pop_back();}
            se.erase(A[i]);
            Dq.pop_back();
        }
    }
    return Dq;
}

