int solve(){
    // g[k][i] := (i=i+g(i)と置き換える操作を2^k回行ったあとのi)-i
    // g[0][i]を求める。
    // g[k+1][i] = g[k][g[k][i]%N]
    // a[0][i] = A[i]の数字を先頭とするブロックの要素数。
    // a[k][i] = A[i]の数字を先頭とする2^k個のブロックの要素総数
    // a[k+1][i] = a[k][i] + a[k][(i+a[k][i])%N]
    vector<vector<ll>> d(60,vector<ll>(N,0));
    for (int i = 0; i < N; i++)
    {
        auto itr = upper_bound(cnt[A[i]].begin(),cnt[A[i]].end(),i);
        if(itr!=cnt[A[i]].end()) d[0][i] = *itr-i+1;
        else d[0][i] = cnt[A[i]][0]+N-i+1;
    }
    DBG(d[0])
    for (int k = 0; k < 50; k++)
    {
        for (int i = 0; i < N; i++) d[k+1][i] = d[k][i] + d[k][(i+d[k][i])%N];
    }
    ll a=0;
    int k = 50;
    while(k--){
        if(a+d[k][a%N]<N*K) a += d[k][a%N];
    }
    DBG(a)
    deque<ll> Dq;
    set<ll> se;
    for (int i = a%N; i < N; i++)
    {
        if(se.find(A[i])==se.end()) {Dq.push_back(A[i]);se.insert(A[i]);}
        else{
            while(Dq.back()!=A[i] && !Dq.empty()) {se.erase(Dq.back()); Dq.pop_back();}
            se.erase(A[i]);
            Dq.pop_back();
        }
    }
    for(auto elem:Dq) cout << elem << " ";
    cout << endl;

    return 0;

}

