    int N; ll K;
    cin >> N >> K;
    vector<int> A(N);
    rep(i, N) cin >> A[i];

    vector<int> last(MAX_N, -1);
    vector<int> diff(N * 2, -1);
    rep(i, N) {
        if(last[A[i]] >= 0) {
            diff[last[A[i]]] = i + 1;
        }
        last[A[i]] = i;
    }
    rep(i, N) {
        if(last[A[i]] >= 0) {
            diff[last[A[i]]] = i + N + 1;
        }
        last[A[i]] = i + N;
    }

    for(ll i = N - 1; i >= 0; i--) {
        assert(diff[i] != -1);
        if(diff[i] < N) {
            diff[i] = diff[diff[i]];
        }
        diff[i] %= N;
    }

    vector<vector<int>> next(50, vector<int>(N, 0));
    rep(i, N) next[0][i] = diff[i];
    rep(k, 49) {
        rep(i, N) {
            next[k + 1][i] = next[k][next[k][i]];
        }
    }

    K--;
