void solve() {
    i64 N = RD();
    i64 K = RD();
    auto A = RD_VEC(N);

    // i から始めて数列が空になるまでを「区間」とし、その長さを求める
    vector<i64> ls(N, -1);  // ls[i]: 始点 i の区間長
    {
        i64 cnt = 0;
        vector<i64> is(200001, -1);  // is[a]: 値 a が最後に出現したインデックス
        for(i64 i = 0; cnt < N; ++i) {
            i64 a = A[i%N];
            // 区間の終了
            if(is[a] >= 0) {
                i64 j = is[a] % N;
                if(ls[j] < 0) {
                    ls[j] = i - is[a] + 1;
                    ++cnt;
                }
            }
            // 区間の開始
            is[a] = i;
        }
    }
    DBG(ls);

    // 始点が 0 になるまでシミュレートしたときの長さを求める
    i64 l_loop = 0;
    {
        i64 i = 0;
        do {
            i64 l = ls[i];
            l_loop += l;
            i += l;
            i %= N;
        } while(i != 0);
    }
    DBG(l_loop);

    // X からループ分を削除し、残ったものをシミュレート
    i64 m = N*K % l_loop; DBG(m);
    vector<i64> ans;
    {
        i64 i = 0;
        i64 l = 0;
        while(l+ls[i] < m) {
            l += ls[i];
            i += ls[i];
            i %= N;
            DBG(i,l);
        }

        auto next_a = [N,&A,&i]() {
            i64 a = A[i];
            ++i;
            i %= N;
            return a;
        };

        vector<i64> js(200001, -1);  // 値 a が最後に出現したインデックス(ans 内)
        i64 j = 0;
        REP(_, m-l) {
            DBG(ans);
            i64 a = next_a();
            if(js[a] >= 0) {
                DBG(j,a);
                DBG(ans);
                DBG(js[a]);
                i64 ans_len = js[a];
                for(auto it = begin(ans)+js[a]; it != end(ans); ++it) {
                    js[*it] = -1;
