void work(int s,int len) {
	//cerr<<s<<' '<<len<<endl;
	//exit(0);
	vector<int> v,ans;
	while(len--) v.push_back(a[s]),s=(s+1)%n;
	memset(vis,0,sizeof(vis));
	for(auto x:v) {
		if(!vis[x]) vis[x]=1,ans.push_back(x);
		else {
			while(ans.back()!=x) vis[ans.back()]=0,ans.pop_back();
			vis[ans.back()]=0,ans.pop_back();
		}
	}
	for(auto x:ans) cout<<x<<' ';
	exit(0);
}

