	cin>>n>>k;k*=n;
	for(int i=0;i<n;i++) a[i]=gi(),pos[a[i]].insert(i);
	for(int i=0;i<n;i++) {
		auto it=pos[a[i]].upper_bound(i);
		if(it==pos[a[i]].end()) nxt[i]=*pos[a[i]].begin()+1;
		else nxt[i]=*it+1;
	}
	int u=0;
	while(1) {
		if(vis[u]) {
			ll pre=0;
			for(int i=nxt[0],j=0;;j=i,i=nxt[i]) {
				ll tmp=pre;
				if(i<=j+1) pre+=i-j+n;
				else pre+=i-j;
				//cerr<<i<<' '<<pre<<endl;
				if(pre>=k) {
					//cerr<<i<<' '<<j<<endl;
					//cerr<<k<<' '<<tmp<<endl;
					work(j,k-tmp);
				}
				if(i==u) break;
			}
			k-=pre;
			//cerr<<k;
			ll len=0;
			for(int i=nxt[u],j=u;;j=i,i=nxt[i]) {
				if(i<=j+1) len+=i-j+n;
				else len+=i-j;
				if(i==u) break;
			}
			k%=len;pre=0;
			for(int i=nxt[u],j=0;;j=i,i=nxt[i]) {
				ll tmp=pre;
				if(i<=j+1) pre+=i-j+n;
				else pre+=i-j;
				if(pre>=k) {
					work(j,k-tmp);
				}
			}
		}
		vis[u]=1,u=nxt[u];
	}
	return 0;
}

