void _main() {
    cin >> N >> K;
    REP(i, N) {
        cin >> A[i];
        A[i]--;
        A[i + N] = A[i];
    }
    MINF(step);
    for (int i = 2 * N - 1; i >= 0; --i) {
        if (i < N)
            step[0][i] = last[A[i]] - i + 1;
        last[A[i]] = i;
    }
    for (int i = 0; i < 59; ++i) {
        for (int j = 0; j < N; ++j) {
            int k = (j + step[i][j]) % N;
            if (step[i][j] == INF || step[i][k] == INF)
                continue;
            CHMIN(step[i + 1][j], step[i][j] + step[i][k]);
        }
    }
    int now = 0;
    int rem = N * K;
    while (1) {
        bool update = false;
        for (int i = 59; i >= 0; --i) {
            if (step[i][now] <= rem) {
                rem -= step[i][now];
                now = (now + step[i][now]) % N;
                update = true;
                break;
            }
        }
        if (!update) break;
    }
    vector<int> cnt(200010, 0);
    stack<int> st;
    for (int i = now; i < N; ++i) {
        if (cnt[A[i]]) {
            while (st.top() != A[i]) {
                cnt[st.top()]--;
                st.pop();
            }
            cnt[A[i]]--;
            st.pop();
        } else {
            cnt[A[i]]++;
            st.push(A[i]);
        }
    }
    vector<int> ans;
    while (!st.empty()) {
        ans.push_back(st.top() + 1);
        st.pop();
    }
    REV(ans);
    cout << ans << endl;
}

