const int mod = 998244353;
const int inf = 1'000'000'007;
const ll linf = (ll)(1e18);

int power(int x, int y) {
  if (y == 0) {
    return 1;
  }
  int z = power(x, y >> 1);
  z = z * 1ll * z % mod;
  if (y & 1) {
    z = z * 1ll * x % mod;
  }
  return z;
}

void solve() {
  int n;
  ll k;
  cin >> n >> k;
  vector<int> a(n);
  vector<vector<ll> > jump(60, vector<ll> (n + 1, n + 1));
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
  }

  map<int, int> lastPos;
  for (int i = n - 1; i >= 0; --i) {
    if (lastPos.count(a[i])) {
      jump[0][i] = lastPos[a[i]] - i + 1;
    }
    lastPos[a[i]] = i;
  }
  for (int i = n - 1; i >= 0; --i) {
    if ((i + jump[0][i]) > n) {
      jump[0][i] = min(jump[0][i], 0ll + (n - i) + lastPos[a[i]] + 1);
    }
  }
  for (int j = 1; j < 60; ++j) {
    for (int i = 0; i < n; ++i) {
      int to = (i + jump[j - 1][i]) % n;
      jump[j][i] = min(linf, jump[j - 1][i] + jump[j - 1][to]);
    }
  }
  int start = 0;
  ll rem = n * 1ll * k - 1;
  for (int i = 59; i >= 0; --i) {
    if (jump[i][start] <= rem) {
      rem -= jump[i][start];
      start = (start + jump[i][start]) % n;
    }
  }

  vector<int> values;
  map<int, int> cnt;
  for (int i = start; i < n; ++i) {
    if (cnt[a[i]] == 0) {
      cnt[a[i]]++;
      values.push_back(a[i]);
    } else {
      while (true) {
        int last = values.back();
        cnt[last]--;
        values.pop_back();
        if (last == a[i]) {
          break;
        }
      }
    }
  }

  for (int i : values) {
    cout << i << " ";
  }
}

