const int maxA = 200000;
const int INF = 1 << 30;

vector<int> simulate(int l, int *a, int N){
    int cnt[maxA + 1];
    fill(cnt, cnt + maxA + 1, 0);

    stack<int> st;
    st.push(l);
    cnt[l]++;

    for(int i = 0; i < N; i++){
        if(cnt[a[i]] > 0){
            while(cnt[a[i]] > 0){
                int num = st.top();
                cnt[num]--;
                st.pop();
            }
        }

        else {
            st.push(a[i]);
            cnt[a[i]]++;
        }
    }

    vector<int> ret;
    while(!st.empty()){
        ret.push_back(st.top());
        st.pop();
    }

    reverse(ret.begin(), ret.end());
    return ret;
}

int main(){
    int N;
    cin >> N;
    ll K;
    cin >> K;

    int a[N];
    for(int i = 0; i < N; i++) cin >> a[i];

    vector<vector<int>> pos(maxA + 1);
    for(int i = 0; i <= maxA; i++) pos[i].push_back(-1);
    for(int i = 0; i < N; i++){
        pos[a[i]].push_back(i);
    }
    for(int i = 0; i <= maxA; i++) pos[i].push_back(INF);

    int dp[N];//i番目が左端のときに次の左端がなにになるか
    for(int i = N - 1; i >= 0; i--){
        int nxt_pos = *upper_bound(pos[a[i]].begin(), pos[a[i]].end(), i);
        if(nxt_pos == INF) dp[i] = a[i];
        else if(nxt_pos == N - 1) dp[i] = 0;
        else dp[i] = dp[nxt_pos + 1];
    }

    //for(int i = 0; i < N; i++) cout << dp[i] << " ";
    //cout << endl;
    //////////////////////////////////////////////////////////////////////////

    int step[maxA + 5];
    int x;
    step[0] = 0;
    for(int i = 1; i <= maxA; i++){
        if(step[i - 1] == 0){
            step[i] = dp[0];
        }
        else {
            if(pos[step[i - 1]][1] == N - 1){
                step[i] = 0;
            } else {
                step[i] = dp[pos[step[i  - 1]][1] + 1];
            }
        }

        if(step[i] == 0){
            x = i;
            break;
        }
    }

    int sousa = K % x;
    if(sousa == 0) return 0;
    else {
        int l = step[sousa - 1];
        vector<int> ans = simulate(l, a, N);
        for(int val : ans){
            cout << val << " ";
        }
        cout << endl;
    }

    return 0;
}

