void solve(long long N, long long K, std::vector<long long> A){
  vector<long long> p(N+1);
  vector<long long> pr(200000, -1);
  p[N] = -1;
  for (int i = N-1; i >= 0; i--) {
    if (pr[A[i]] == -1) {
      p[i] = i;
      pr[A[i]] = i;
    } else {
      p[i] = p[pr[A[i]]+1];
      pr[A[i]] = i;
    }
  }

  long long idx = 0;
  long long offset = 0;
  long long t = -1;
  long long o = -1;
  bool b;
  set<long long> s;
  vector<long long> l;
  while (true) {
    idx++;
    if (t == -1) {
      o = p[0];
    } else {
      o = p[pr[t]+1];
    }
    if (o == -1) {
      b = true;
      break;
    }
    t = A[o];
    if (s.find(t) != s.end()) {
      b = false;
      break;
    }
    s.insert(t);
    l.push_back(t);
  }

  for (int i = 0; i < l.size(); i++) {
    // std::cout << l[i] << std::endl;
    if ((l[i] == t) && !b) {
      offset = i;
    }
  }

  l.push_back(-1);

  if (K < offset) {
    idx = K;
  } else {
    idx = offset + ((K-offset+idx-2) % (idx-offset));
  }

  t = l[idx];

  if (t == -1) {
    o = p[0];
  } else {
    o = p[pr[t]+1];
  }

  // std::cout << t << std::endl;
  // std::cout << o << std::endl;

  vector<long long> ans;
  while (true) {
    if (o == -1) {
      break;
    }
    t = A[o];
    ans.push_back(t);
    o = p[o+1];
  }

  for (int i = 0; i < ans.size(); i++) {
    if (i == 0) {
      std::cout << ans[i];
    } else {
      std::cout << " " << ans[i];
    }
  }
  std::cout << std::endl;
}

