bool vis[200009];
stack<int> stk;
vector<int> ans;

int fun(int cur)
{
	if (vis[cur]) return from[cur];
	if (cur >= n || nxt[cur] < 0) {
		from[cur] = cur;
	}
	else {
		from[cur] = fun(nxt[cur] + 1);
	}
	vis[cur] = true;
	return from[cur];
}

int main()
{
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cin >> n >> k;
	for (int i = 0; i < n; i++) {
