		PRE = from[G];
	}
	memset(vis, 0, sizeof(vis));
	for (int i = G; i < n; i++) {
		if (!vis[a[i]]) {
			stk.push(a[i]);
			vis[a[i]] = true;
		}
		else {
			while (1) {
				int tmp = stk.top();
				stk.pop();
				vis[tmp] = false;
				if (a[i] == tmp) break;
			}
		}
	}
	while (!stk.empty()) {
		ans.pb(stk.top());
		stk.pop();
