int search(int* d, int t, int n) {
	if (d[0] == t)return 0;
	int r = 0;
	for (int i = 20; i >= 0; i--) {
		int c = r | (1 << i);
		if (c >= n)continue;
		if (d[c] == t)return c;
		if (d[c] < t)r = c;
	}
	return -1;
}

