        x -= p[i][k];
        i = (i + p[i][k]) % n;
    }
    if (x > 0) {
        vector<int> ans;
        bool flg[200200] = {};
        while (i < n) {
            if (flg[a[i]]) {
                while (ans.back() != a[i]) {
                    flg[ans.back()] = false;
                    ans.pop_back();
                }
                flg[a[i]] = false;
                ans.pop_back();
            } else {
                ans.push_back(a[i]);
                flg[a[i]] = true;
