typedef long long ll;

const int MAXN = 200 * 1000 + 132, MXLG = 61;



int n, a[MAXN], b[MAXN];
vector<int> v[MAXN], ans;
set<int> s;
ll k, c[MAXN][MXLG];

void inp();
void solve();


int main() {
	inp();
	solve();

	return 0;
}
void inp() {
	cin >> n >> k;
	k *= n;
	for (int i = 0; i < n; i++)
		cin >> a[i], v[--a[i]].push_back(i);
}
void solve() {
	for (int i = 0; i < n; i++) {
		if (v[i].empty())
			continue;
		int x = v[i][0] + n;
		v[i].push_back(x);
		for (int j = 0; j < sz(v[i]) - 1; j++)
			b[v[i][j]] = v[i][j + 1] - v[i][j] + 1;
	}
	for (int i = 0; i < n; i++)
		c[i][0] = b[i];
	ll moradi = (LLONG_MAX >> 2);
	for (int j = 1; j < MXLG; j++)
		for (int i = 0; i < n; i++)
			c[i][j] = min(moradi, c[i][j - 1] + c[(i + c[i][j - 1]) % n][j - 1]);
	ll pt = 0;
	for (int i = MXLG - 1; ~i; i--)
		if (pt + c[pt % n][i] <= k)
			pt += c[pt % n][i];
	for (int i = pt % n; i < n; i++)
		if (s.find(a[i]) != s.end()) {
			while (ans.back() != a[i])
				s.erase(ans.back()), ans.pop_back();
			ans.pop_back();
			s.erase(a[i]);
		}
		else {
			ans.push_back(a[i]);
			s.insert(a[i]);
		}
	for (int i : ans)
		cout << i + 1 << ' ';
}

