int main(){

  ll N = il();
  ll K = il();
  ll loop_num = min(10000000LL, K);

  vector<ll> As;
  rep(i, N){
    As.PB(il());
  }

  //手持ちの整数列s。0になっているところはinvalid。最大の長さはN
  vector<ll> temochi(N, 0);
  ll len = 0; //手持ちの整数列sの長さを管理する。

  vector<vector<ll> > eachans;

  rep(i, loop_num){ //iはy座標
    // 単純に探索するが、途中でループしたら抜ける
    rep(j, N){ //jはx座標
      ll now = As.at(j); //今回拾った整数
      bool isIn = false; //手持ちにあったかどうか
      //手持ちの整数列の先頭から一致を確認していく
      rep(k, len){
        if (now == temochi.at(k)){
          len = k; // [0]で一致したならlen=0, [3]で一致したならlen=3
          REP(l, k, len){
            temochi.at(k) = 0;
          }
          isIn = true; //手持ちにあった
          break; // 次の列へ移る
        }
        //一致しなければ、手持ちの整数列の中の次の整数へ目を移す(continue)
      }
      if (!isIn){
        //手持ちに無かったのなら、加える
        temochi.at(len) = now;
        len++;
      }
      //手持ちにあったのなら消して終わりだから、ここでは何もしない
    }
    //これで一行見終わった
    if (len == 0){
      //lenが0となった＝つまり、初期状態に戻ったのなら
      //今のループが何回目か？　：　i+1 回目
      if (K % (i+1) == 0){
        //丁度全消しで終わるパターン
        return 0;
      }
      else{
        //繰り返し回数を、1ループの回数で割ると、何回ループしたあとの状態が答えになるかが出る
        //何回ループしたあとか、なので、1回ループしたあとなら0ループ目の後ということになるから、-1する
        //それを答えとして出力し、終わり
        ov(eachans.at(K % (i+1) - 1));
        return 0;
      }
    }
    else{
      //lenが0でない、つまりループしてない。答えの数列を入れておく
      //eachans.at(i)でi回目(0-indexed)のループ後の答えを取り出せる
      vector<ll> tmp;
      rep(z, len){
        tmp.PB(temochi.at(z));
      }
      eachans.PB(tmp);
    }
  }

  //全行見終わったけどループしていない
  rep(i, len){
    ol(temochi.at(i));
  }


// -- main() end -- //
}

