inline ll read(){
	ll x=0,f=1;
	char c=getchar();
	while(c<'0'||c>'9'){
		if(c=='-')f=-1;
		c=getchar();
	}
	while(c>='0'&&c<='9'){
		x=(x<<1)+(x<<3)+c-'0';
		c=getchar();
	}
	return x*f;
}
int n,a[N],pre[N],nxt[N],st[N],top,vis[N];
ll k;
int main(){
	n=read(),k=read();
	for(int i=1;i<=n;++i){
		a[i]=read();
	}
	for(int i=1;i<=n;++i){
		if(pre[a[i]])nxt[pre[a[i]]]=i;
		pre[a[i]]=i;
	}
	for(int i=1;i<=n;++i){
		if(!nxt[pre[a[i]]])nxt[pre[a[i]]]=i;
	}
	int t=1;
	for(int u=1;u<=n;u=nxt[u]+1){
		if(nxt[u]<=u)++t;
	}
	k%=t;
	if(!k)return 0;
	for(int u=1,nt=1;u<=n;u=nxt[u]+1){
		if(nxt[u]<=u)++nt;
		if(nt>k){
			for(int i=u;i<=n;++i){
				if(vis[a[i]]){
					while(vis[a[i]])vis[st[top--]]=0;
				}
				else{
					vis[st[++top]=a[i]]=1;
				}
