signed main(void){

    int n, k;
    cin >> n >> k;

    vector<int> a(n);
    rep(i, n)cin >> a[i];

    vector<int> b(n * 2), c(n), d(n);
    rep(i, n)b[i] = b[i + n] = a[i];

    map<int, int> mp;
    rep(i, n * 2){
        if(mp.find(b[i]) == mp.end()){
            mp[b[i]] = i % n;
        } else {
            c[mp[b[i]]] = i % n;
            mp[b[i]] = i % n;
        }
    }

    rep(i, n){
        if(c[i] == i)d[i] = n + 1;
        else d[i] = (c[i] - i + n) % n + 1;
    }

    int sum = 0, pos = 0;
    vector<bool> used(n, false);
    while(true){
        if(used[pos])break;
        sum += d[pos];
        used[pos] = true;
        pos = (c[pos] + 1) % n;
    }

    k *= n;
    k %= sum;

    while(true){
        if(k < d[pos])break;
        k -= d[pos];
        pos = (c[pos] + 1) % n;
    }

    mp.clear();
    vector<int> ans;
    rep(i, k){
        if(mp.find(b[pos]) == mp.end()){
            mp[b[pos]] = pos;
            ans.push_back(b[pos++]);
        } else {
            int tmp = mp[b[pos++]];
            while(mp[ans.back()] != tmp){
                mp.erase(ans.back());
                ans.pop_back();
            }
            mp.erase(ans.back());
            ans.pop_back();
        }
    }

    rep(i, ans.size()){
        if(i > 0)cout << ' ';
        cout << ans[i];
    }
    cout << endl;

}

