ll gcd(ll a,ll b) { return b==0?a:gcd(b,a%b); }

const int MAXN=200000;
const int MAXLG=60;
const int MAXVAL=200000;

int n; ll times;
int a[MAXN];
int ans[MAXN],nans;

pair<int,int> o[MAXN];
ll cnt[MAXN][MAXLG+1];

int pos[MAXVAL+1];

ll safeadd(ll a,ll b) { if(a>LLONG_MAX-b) return LLONG_MAX; return a+b; }

void solve() {
	REP(i,n) o[i]=MP(a[i],i);
	sort(o,o+n);
	for(int l=0,r=l;l<n;l=r) {
		while(r<n&&o[r].first==o[l].first) ++r;
		FOR(i,l,r-1) cnt[o[i].second][0]=o[i+1].second-o[i].second+1;
		cnt[o[r-1].second][0]=o[l].second-o[r-1].second+n+1;
	}
	//printf("cnt:"); REP(i,n) printf(" %lld",cnt[i][0]); puts("");
	REP(k,MAXLG) REP(i,n) cnt[i][k+1]=cnt[i][k]==LLONG_MAX?LLONG_MAX:safeadd(cnt[i][k],cnt[(i+cnt[i][k])%n][k]);

	ll sofar=0; int at=0;
	for(int k=MAXLG;k>=0;--k) if(sofar+cnt[at][k]<=n*times) sofar+=cnt[at][k],at=(at+cnt[at][k])%n;
	//printf("sofar=%lld at=%d\n",sofar,at);

	ll rem=n*times-sofar;
	if(rem==0&&at==0) at=n;
	//printf("rem=%lld at=%d\n",rem,at);
	assert(rem<=n&&rem+at==n);

	memset(pos,-1,sizeof(pos));
	nans=0;
	FOR(i,at,n) {
		int x=a[i],z=pos[x];
		if(z!=-1) {
			//printf("x=%d z=%d nans=%d\n",x,z,nans);
			while(nans>z) --nans,pos[ans[nans]]=-1;
		} else {
			pos[x]=nans,ans[nans++]=x;
		}
	}
}

void run() {
	scanf("%d%lld",&n,&times);
	REP(i,n) scanf("%d",&a[i]);
	solve();
	REP(i,nans) { if(i!=0) printf(" "); printf("%d",ans[i]); } puts("");
}

int main() {
	run();
	return 0;
}

