vector<int> findNextIndex(const vector<int>& A) {
  int N = A.size();
  vector<int> res(N, -1);
  map<int, int> mem;
  for (int i = N - 1; i >= 0; i--) {
    if (mem.count(A[i])) {
      res[i] = mem[A[i]];
    }
    mem[A[i]] = i;
  }
  return res;
}

pair<ll, ll> findLoop(const vector<int>& A, const vector<int>& nextIndex) {
  int N = A.size();
  vector<ll> mem(N, -1);
  int x = 0;
  ll len = 0;
  while (mem[x] == -1) {
    mem[x] = len;
    int y = nextIndex[x];
    len += y - x + 1;
    x = (y + 1) % N;
  }
  return make_pair(mem[x], len - mem[x]);
}

vector<int> solveNaive(const vector<int>& A, ll bg, ll ed) {
  int N = A.size();
  vector<int> res;
  set<int> S;
  for (ll x = bg; x < ed; x++) {
    int v = A[x % N];
    if (!S.count(v)) {
      res.push_back(v);
      S.insert(v);
      continue;
    }
    while (res.back() != v) {
      S.erase(res.back());
      res.pop_back();
    }
    S.erase(v);
    res.pop_back();
  }
  return res;
}

vector<int> solve(const vector<int>& A, const vector<int>& nextIndex, ll bg, ll ed) {
  int N = A.size();
  for (ll x = bg; x < ed; ) {
    int add = nextIndex[x % N] - x % N + 1;
    if (x + add <= ed) {
      x += add;
      continue;
    }
    return solveNaive(A, x, ed);
  }
  return {};
}

int main() {
#ifdef DEBUG
  ifstream ifs("in.txt");
  cin.rdbuf(ifs.rdbuf());
#endif
  int N;
  ll K;
  while (cin >> N >> K) {
    vector<int> A(N);
    for (auto& x : A) cin >> x;
    vector<int> B(2 * N);
    for (int i = 0; i < N; i++) B[i] = B[N + i] = A[i];
    auto nextIndex = findNextIndex(B);
    auto loop = findLoop(A, nextIndex);
    assert(loop.snd > 0);
    ll rem = max(0ll, N * K - loop.fst) % loop.snd;
    vector<int> res;
    if (rem > 0) {
      res = solve(A, nextIndex, N * K - rem, N * K);
    }
    for (int x : res) cout << x << " ";
    cout << endl;
  }
  return 0;
}

