typedef long long ll;
vector<ll> idx[200005];
ll memo[200005]={0};
int main(){
  ll n;
  cin>>n;
  ll k;
  cin>>k;

  ll seq=1;
  vector<ll> vec;
  vec.push_back(0);
  for(int i=1;i<=n;i++){
    ll a;
    cin>>a;
    vec.push_back(a);
  }
  for(int i=1;i<=n;i++) vec.push_back(vec[i]);
  for(int i=1;i<=2*n;i++){
    idx[vec[i]].push_back(i);
  }
  ll pos=1;
  memo[1]=0;
  if(k>50000000){
    do{
      ll num=vec[pos];
      auto itr=upper_bound(idx[num].begin(),idx[num].end(),pos);
      ll npos=*itr;
      if(npos==n) {
        pos=1;
        break;
      }
      npos++;
      if(npos>n){
        npos-=n;
        seq++;
      }
      pos=npos;
      if(memo[pos]!=0||pos==1){
        seq-=memo[pos];
        break;
      }
      memo[pos]=seq;
    }while(1);
    if(k<memo[pos]){
      pos=1;
    }
    else{
      k-=memo[pos];
      k%=seq;
    }
  }
  if(k==0){
    cout<<" "<<endl;
    return 0;
  }
  ll cnt=1;
  while(cnt<k){
    ll num=vec[pos];
    ll kpos=upper_bound(idx[num].begin(),idx[num].end(),pos)-idx[num].begin();
    ll npos=idx[num][kpos];
    npos++;
    if(npos>n){
      npos-=n;
      cnt++;
    }
    pos=npos;
  }
  vector<ll> ans;
  while(pos<=n){
    ll num=vec[pos];
    auto itr=upper_bound(idx[num].begin(),idx[num].end(),pos);
    ll npos=*itr;
    if(npos>n) {
      ans.push_back(num);
      pos++;
    }
    else{
      pos=npos+1;
    }
  }
  for(int i=0;i<ans.size();i++) cout<<ans[i]<<" ";
  cout<<endl;
}

#include<bits/stdc++.h>
using namespace std;

typedef long long ll;

ll N, K;
ll A[200010];
ll next[60][200010], over[60][200010];
ll prev[200010];

int main()
{
    cin >> N >> K;
    for(int i = 0; i < N; i++)cin >> A[i];

    memset(prev, -1, sizeof(prev));
    for(int i = 0; i < 2 * N; i++)
    {
        if(prev[A[i % N]] == -1)prev[A[i % N]] = i + 1;
        else
        {
            int idx = (prev[A[i % N]] - 1) % N;
            next[0][idx] = (i + 1) % N;
            over[0][idx] = ((prev[A[i % N]] - 1 < N && i + 1 >= N) | (i + 1) % N == 0) ? 1 : 0;
            prev[A[i % N]] = i + 1;
        }
    }

    for(int i = 1; i < 60; i++)
    {
        for(int j = 0; j < N; j++)
        {
            next[i][j] = next[i - 1][next[i - 1][j]];
            over[i][j] = over[i - 1][j] + over[i - 1][next[i - 1][j]];
        }
    }

    ll l = 0, r = 1LL << 60;
    ll mem;
    for(int i = 0; i < 64; i++)
    {
        ll mid = (l + r) / 2;
        ll now = 0, cnt = 0;
        for(int j = 0; j < 60; j++)if(mid & (1LL << j))
        {
            cnt += over[j][now];
            now = next[j][now];
        }
        if(K - 1 == cnt)
        {
            mem = now;
            break;
        }
        if(cnt < K - 1)l = mid;
        else r = mid;
    }

    int bit[200010] = {0};
    vector<int> ans;
    for(int i = mem; i < N; i++)
    {
        if(bit[A[i]])
        {
            while(ans.back() != A[i])
            {
                bit[ans.back()] ^= 1;
                ans.pop_back();
            }
            bit[ans.back()] ^= 1;
            ans.pop_back();
        }
        else
        {
            bit[A[i]] ^= 1;
            ans.push_back(A[i]);
        }
    }

    for(int i = 0; i < ans.size(); i++)
    {
        cout << ans[i];
        if(i != ans.size())cout << " ";
    }
    cout << endl;

    return 0;
}

