template <typename K>
struct custom_hash {
    size_t operator()(const K& x) const;
};

template <>
struct custom_hash<uint64_t> {
    static uint64_t splitmix64(uint64_t x) {
        // http://xorshift.di.unimi.it/splitmix64.c
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = experimental::chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + FIXED_RANDOM);
    }
};

template <>
struct custom_hash<int> {
    custom_hash<uint64_t> h;
    size_t operator()(const int& x) const {
        return h(uint64_t(x));
    }
};

template <typename K, typename V> using munordered_map = unordered_map<K, V, custom_hash<K>>;

struct Solver {
    const int N;
    const vector<int> A;

    munordered_map<int, vector<int>> pos;
    int per;
    ll m;
    vector<int> sh;

    Solver(int N, const vector<int>& A) : N(N), A(A), sh(N) {
        REP(i, N) pos[A[i]].push_back(i);
        for (const auto& _ : pos) {
            const auto& p = _.second;
            REP(i, int(p.size())-1) {
                sh[p[i]] = p[i+1] - p[i] + 1;
            }
            sh[p.back()] = N - p.back() + p[0] + 1;
        }
        per = 0;
        m = 0;
        int cur = 0;
        do {
            ++per;
            m += sh[cur];
            cur = next(cur);
        } while (cur != 0);
    }

    int next(int i) const {
        assert(0 <= i && i < N);
        i += sh[i];
        while (i >= N) i -= N;
        assert(0 <= i && i < N);
        return i;
    }

    vector<int> query(ll K) const {
        ll d = 0;
        int cur = 0;
        K %= m;
        int x = 0;
        while (d + sh[cur] < N*K%m) {
            d += sh[cur];
            cur = next(cur);
            ++x;
            assert(x <= per);
        }
        vector<int> ans;
        set<int> s;
        REP(_, N*K%m - d) {
            if (!s.insert(A[cur]).second) {
                while (ans.back() != A[cur]) s.erase(ans.back()), ans.pop_back();
                s.erase(ans.back()), ans.pop_back();
            } else {
                s.insert(A[cur]), ans.push_back(A[cur]);
            }
            ++cur;
            if (cur == N) cur = 0;
        }
        return ans;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N; ll K; cin >> N >> K;
    vector<int> A(N);
    for (int& a : A) cin >> a;
    Solver s(N, A);
    auto ans = s.query(K);
    for (int a : ans) cout << a << " ";
    cout << '\n';

    return 0;
}

