    }
  }

  map<int, int> min_index;
  map<int, int> next;
  map<int, int> f;
  REP(i, n)
  {
    if (min_index[a[i]] != 0)
      continue;
    min_index[a[i]] = i;
  }

  map<int, int> near_index;
  for (int i = n - 1; i >= 0; i--)
  {
    if (near_index[a[i]] == 0)
    {
      next[i] = a[i];
    }
    else if (next[near_index[a[i]]] == n - 1)
    {
      next[i] = 0;
    }
    else
    {
      next[i] = next[near_index[a[i]] + 1];
    }
    near_index[a[i]] = i;
  }

  f[0] = second == 0 ? a[0] : next[second + 1];
  REP(i, n)
  {
    if (f[a[i]] != 0)
      continue;
    f[a[i]] = next[min_index[a[i]] + 1];
  }

  ll loop = 1;
  int tmp = f[0];
  REP(i, n)
  {
    if (tmp == 0)
      break;
    tmp = f[tmp];
    loop++;
  }

  // 解の構成
  tmp = 0;
  for (ll i = 0; i < (k % loop) - 1; i++)
  {
