const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, k;
ll memo[N_DIGITS + 5][MAX_N];
vl as, nxt;

void solve(){
    as = vl(n); ll aM = 0;
    rep(i, n) {in1(as[i]); chmax(aM, as[i]);}
    nxt = vl(aM + 1);
    revrep(i, n) nxt[as[i]] = i + n;

    revrep(i, n){
        // the distance from current location to the next one
        memo[0][i] = nxt[as[i]] - i + 1;
        // next occurence of as[i] is nxt[as[i]]
        nxt[as[i]] = i;
    }

    rep(d, N_DIGITS){
        rep(i, n){
            // the location of 2^d-th next i
            // nxt[nxt[nxt[...[nxt[i]]]]] = nxt_loc (2^d times)
            // -> i -> nxt_loc -> nxt[nxt[nxt[...[nxt[i]]]]] = nxt_loc (2^d times)
            // -> memo[d + 1][i] = memo[d][i] + memo[d][nxt_loc]
            ll nxt_loc = (i + memo[d][i]) % n;
            memo[d + 1][i] = min(INF, memo[d][i] + memo[d][nxt_loc]);
        }
    }

    ll cur_loc = 0;
    revrep(d, N_DIGITS){
        // find the last location where the numbers are canceled out by as[0]
        if (cur_loc + memo[d][cur_loc % n] <= n * k)
            cur_loc += memo[d][cur_loc % n];
    }

    vl ans;
    while (cur_loc < n * k){
        // next location where the numbers are canceled out
        ll nxt_loc = cur_loc + memo[0][cur_loc % n];
        // if the next location is smaller than n * k, cancel out the numbers and goes to the next location.
        // otherwise, we cannot cancel out the number anymore, so appends the number and increments the current location
        if (nxt_loc <= n * k) cur_loc = nxt_loc;
        else ans.pb(as[cur_loc % n]), cur_loc++;
    }

    if (!ans.empty())
        rep(i, ans.size()) prs(ans[i]);
    prl("");
}

int main(void){
    in2(n, k);
    // assert(k <= 1000);
    solve();
    return 0;
}

