            shuu+=(idx+1)/n;
            idx=(idx+1)%n;
        }
        answer(ans);
    };
    if(d==10){las(idx,shuu);}

    while(cnt[idx]==err){
        cnt[idx]={idx,shuu};
        ll nx=*(upper_bound(num[A[idx]].begin(),num[A[idx]].end(),idx));
        shuu+=(nx+1)/n;
        if(shuu>=k){
            las(cnt[idx].F,cnt[idx].S);
            return;
        }
        idx=(nx+1)%n;
    }
    ll shuuki=shuu-cnt[idx].S;
    k-=cnt[idx].S;
    k%=shuuki;
    cul(n,k,ans,num,A,cnt[idx].F,0,d+1);
}

