#define MAXN 200005

ll n,k;
ll arr[MAXN];

ll cnt=0;
vi start;
int startb[MAXN];

vi ans;

set<int> ind[MAXN];

void brute(int u){
	bool occ[MAXN];

	forn(i,u,n)
	{
		if(!occ[arr[i]]){
			ans.pb(arr[i]);
			occ[arr[i]]=1;
		}

		else{
			while(occ[arr[i]]){
				occ[ans.back()]=0;
				ans.pop_back();
			}
		}
	}
}

int next(int u){
	startb[u]=cnt;

	set<int>::iterator it = ind[arr[u]].upper_bound(u);
	if(it!=ind[arr[u]].end()) return *it;

	cnt++;
	return *ind[arr[u]].lower_bound(0);
}

int main()
{
	//ios_base::sync_with_stdio(0); cin.tie(0);
	mset(startb,-1);

	cin>>n>>k;
	forn(i,0,n){
		cin>>arr[i];
		ind[arr[i]].insert(i);
	}

	int cur=0, prev=cur;
	while(cnt<k && startb[cur]==-1){
		start.pb(cur);
		prev=cur;

		cur=next(cur);
		cur++;
		if(cur==n){
			cnt++;
			cur-=n;
		}		
	}

	//forn(i,0,start.size()) cout<<"start["<<i<<"]="<<start[i]<<'\n';
	//forn(i,0,n) cout<<"startb["<<i<<"]="<<startb[i]<<'\n';
	//watch(cnt); watch(prev); watch(cur);

	if(cnt>=k){ //cout<<"! cnt>k"<<'\n';
		brute(prev);
	}
	else{
		ll period=cnt-startb[cur];
		k-=startb[cur];
		k%=period;
		brute(start[startb[cur]+k]);
	}

	forn(i,0,ans.size()) cout<<ans[i]<<" ";
	cout<<'\n';

	return 0;
}

