void _main()
{
    ll n; llin(n);
    ll k; llin(k);
    S V<ll> alist; llina(alist, n);

    S V<ll> valpos[200005];
    rep (i, n) valpos[alist[i]].pb(i);

    alist.pb(-1);
    n++;

    S ll maps[200005] = {};
    S ll proceeds[200005] = {};
    rep (i, n) {
        ll a = alist[i];

        if (a < 0) {
            maps[i] = 0;
            proceeds[i] = 1;
            continue;
        }

        auto iter = upper_bound(ALL(valpos[a]), i);
        if (iter == valpos[a].end()) {
            iter = valpos[a].begin();
            proceeds[i] = 1;
        }
        ll nexti = *iter + 1LL;

        maps[i] = nexti;
    }

    debug_printf("---- maps\n");
    debug_print(maps, n);
    debug_printf("---- proceeds\n");
    debug_print(proceeds, n);

    ll mod = 0;
    ll now = 0;
    for (;;) {
        ll next = maps[now];
        ll proceed = proceeds[now];
        mod += proceed;
        now = next;
        if (!now) break;
    }

    debug_printf("mod=%lld\n", mod);

    k--;
    k %= mod;
    now = 0;

    while (k) {
        ll next = maps[now];
        ll proceed = proceeds[now];
        k -= proceed;
        now = next;
    }

    ll si = now;

    debug_printf("---- si=%lld\n", si);

    S ll cnts[200005] = {};
    S deque<ll> ans;

    srep (i, si, n-1) {
        ll a = alist[i];
        debug_printf("i=%lld a=%lld\n", i, a);
        if (cnts[a]) {
            for (;;) {
                ll b = ans.back(); ans.pop_back();
                cnts[b]--;
                if (a == b) break;
            }
        }
        else {
            ans.push_back(a);
            cnts[a]++;
        }
    }

    debug_printf("---- ans\n");
    while (ans.size()) {
        cout << ans.front() << " ";
        ans.pop_front();
    }
    cout << endl;
}

