    //g[0][i]を埋める.つまり、i番目から1回操作を行なったら何歩進むか？
    rep(x,200020){
        if(pos[x].size() == 0)continue;//xが一回も登場しなかったら無視して良い
        //iが1周期の中における最後のx登場indexだった場合は次の周期の最初のxに行く
        for(int i = 0;i < pos[x].size();i++){
            int id = pos[x][i];
            int nextid = pos[x][(i+1)%pos[x].size()];
            if(i != pos[x].size()-1){
                g[0][id] = (ll)(nextid - id + 1);
            }else{
                g[0][id] = (ll)(nextid + n - id + 1);
            }
        }
    }

    for(int p = 1;p <= 59;p++){
        //g[i][p]を埋める
        for(ll i = 0;i < n;i++){
            ll nextid = (i + g[p-1][i]) % n;//2^(p-1)step後のmod N上
            g[p][i] = g[p-1][i] + g[p-1][nextid];
        }
    }
    ll now = 0;
    while(true){
        ll id = now % n;
        int l = -1,r = 60;
