        if(l == -1)break;
        else{
            now += g[l][id];
        }
    }
    now %= n;
    vector<ll> ans;
    while(now < n){
        if(now == pos[a[now]][pos[a[now]].size()-1]){
            ans.pb(a[now]);
            now++;
