vector<ll> s, p[210000], nx(210000), cnt(210000);

ll n, k;
ll nk = 1;//今のk
ll now = 0;
ll used[210000], ok;
void solve() {
	while (1) {
		if (nk > k) {
			now = n;
			return;
		}
		if (nk == k)return;
		if (used[now] != -1 and nk < k) {
			ll c = ((k - used[now]) / (nk - used[now]));
			nk = used[now] + (nk - used[now]) * c;
			return;
		}
		else used[now] = nk;
		if (nx[now] <= now and nk == k)return;
		if (nx[now] <= now)nk++;
		now = nx[now];
		now = (now + 1) % n;
		if (now == 0)nk++;
		if (nk >= k)return;
	}
}

int main() {
	cin >> n >> k;
	REP(i, n) {
		ll a;
		cin >> a;
		s.push_back(a);
	}
	REP(i, n) {
		p[s[i]].push_back(i);
	}
	REP(i, n) {
		REP(j, p[i].size()) {
			nx[p[i][j]] = p[i][(j + 1) % p[i].size()];
		}
	}
	REP(i, 210000)used[i] = -1;
	solve();
	REP(i, 210000)used[i] = -1;
	//cout << nk << " " << now << " kore" << endl;
	solve();

	//愚直
	//cout << now <<" now " << endl;
	vector<ll> ans;
	if (nk > k)return 0;
	FOR(i, now, n) {
		if (cnt[s[i]] == 0) {
			ans.push_back(s[i]);
			cnt[s[i]]++;
		}
		else {
			while (cnt[s[i]] > 0) {
				cnt[ans.back()]--;
				ans.pop_back();
			}
		}
	}
	REP(i, ans.size()) {
		if (i != 0)cout << " ";
		cout << ans[i];
	}
	cout << endl;

}

