#include <bits/stdc++.h>
using namespace std;
#define SELECTER(_1, _2, _3, SELECT, ...) SELECT
#define REP1(i, n) for(int i=0; i<n; i++)
#define REP2(i, a, b) for(int i=a; i<b; i++)
#define REP(...) SELECTER(__VA_ARGS__, REP2, REP1,) (__VA_ARGS__)
#define MOD 1'000'000'007

template <class T> ostream& operator<<(ostream& os, const vector<T>& v){ os << "{"; for(size_t i=0; i<v.size(); i++) os << v[i] << (i+1==v.size() ? "" : ", "); os << "}"; return os; }
template <class T, class U> ostream& operator<<(ostream& os, const pair<T, U>& p){ return os << "{" << p.first << ", " << p.second << "}"; }

int main(){
    long long N, K;
    cin >> N >> K;
    vector<int> A(N);
    REP(i, N) cin >> A[i];

    map<int, vector<int>> mp;
    REP(i, N) mp[A[i]].push_back(i);
    vector<int> v_nxt(N);
    REP(i, N){
        auto &v = mp[A[i]];
        auto itr = upper_bound(v.begin(), v.end(), i);
        if(itr != v.end()){
            v_nxt[i] = *itr;
        }else{
            v_nxt[i] = v[0];
        }
    }

    int cur = 0;
    long long KN = K*N;
    set<int> hoge;
    while(true){
        if(hoge.find(cur) != hoge.end()) break;
        hoge.insert(cur);
        int nxt = v_nxt[cur];
        if(nxt <= cur){
            if(N-(cur-nxt)+1>KN) break;
            KN -= N - (cur - nxt) + 1;
        }else if(nxt > cur){
            if(nxt-cur+1>KN) break;
            KN -= nxt - cur + 1;
        }
        cur = (nxt + 1) % N;
    }
    int curzero = cur;

    long long period = 0;
    while(true){
        int nxt = v_nxt[cur];
        if(nxt <= cur){
            period += N - (cur - nxt) + 1;
        }else if(nxt > cur){
            period += nxt - cur + 1;
        }
        cur = (nxt + 1) % N;
        if(cur == curzero) break;
    }

    KN %= period;

    while(true){
        int nxt = v_nxt[cur];
        if(nxt <= cur){
            if(N-(cur-nxt)+1>KN) break;
            KN -= N - (cur - nxt) + 1;
        }else if(nxt > cur){
            if(nxt-cur+1>KN) break;
            KN -= nxt - cur + 1;
        }
        cur = (nxt + 1) % N;
    }
    assert((cur+KN)%N==0);
    vector<int> ans;
    set<int> st;
    for(int i=0; i<KN; i++){
        int j = i+cur;
        if(st.find(A[j]) == st.end()){
            ans.push_back(A[j]);
            st.insert(A[j]);
        }else{
            while(true){
                int hog = ans.back();
                ans.pop_back();
                st.erase(hog);
                if(hog==A[j]){
                    break;
                }
            }
