    for(int i=0; i<n; i++){
        mp[a[i]].push_back(mp[a[i]][0] + n);
        table[i][0] = (mp[a[i]][1] + 1) - i;

        mp[a[i]].erase(mp[a[i]].begin());
    }

    for(int j=0; j+1<60; j++){
        for(int i=0; i<n; i++){
