int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    li n, k;
    cin >> n >> k;
    vector<li> as(n);
    map<li, vector<li>> indexes;
    for (int i = 0; i < n; ++i) {
        cin >> as[i];
        indexes[as[i]].push_back(i);
    }

    vector<li> consumes(n);
    for (auto& p : indexes) {
        const li num = p.first;
        const vector<li>& poses = p.second;
        for (int i = 0; i < poses.size(); ++i) {
            li fr = poses[i];
            li to = poses[(i + 1) % poses.size()];
            if (fr < to) {
                consumes[fr] = to - fr + 1;
            } else {
                consumes[fr] = (n - fr) + to + 1;
            }
        }
    }

    li rot = 0, pos = 0;
    do {
        pos += consumes[pos];
        while (pos >= n) {
            pos -= n;
            rot += 1;
        }
    } while (pos != 0);

    k %= rot;
    rot = 0;
    pos = 0;
    vector<li> s;
    while (true) {
        if (rot >= k) {
            break;
        }
        li npos = pos + consumes[pos];
        li nrot = rot;
        while (npos >= n) {
            npos -= n;
            nrot += 1;
        }
        if (nrot >= k + 1 || (nrot == k && npos != 0)) {
            // overrun, keep.
            s.push_back(as[pos]);

            // increment instead.
            if (pos == n - 1) {
                npos = 0;
                nrot = rot + 1;
            } else {
                npos = pos + 1;
                nrot = rot;
            }
        }

        pos = npos;
        rot = nrot;
    }

    for (int i = 0; i < s.size(); ++i) {
        cout << s[i];
        if (i + 1 == s.size()) {
            cout << endl;
        } else {
            cout << " ";
        }
    }
    return 0;
}

