    put_ans(0, 0);

  } else {

    vector<pair<int,ll>> nxt(n);
    map<int,int> lst;
    for (int i = 0; i < n; i++) {
      auto a = A[i];
      if (lst.count(a) == 0) {
        lst[a] = i;
        nxt[i] = {(i + 1) % n, n + 1};
      } else {
        nxt[i] = {nxt[lst[a]].first, nxt[lst[a]].second - (i - lst[a])};
        nxt[lst[a]] = {(i + 1) % n, i + 1 - lst[a]};
        lst[a] = i;
      }
    }

    constexpr int LOGNK = 54;
    vector<vector<pair<int,ll>>> dbl(LOGNK, vector<pair<int,ll>>(n));
    for (int i = 0; i < n; i++) {
      dbl[0][i] = nxt[i];
    }
    for (int j = 1; j < LOGNK; j++) {
      for (int i = 0; i < n; i++) {
        auto fst = dbl[j-1][i];
        if (fst.first == -1)
          dbl[j][i] = {-1, -1};
        auto nxt = dbl[j-1][fst.first];
        if (fst.second + nxt.second > k*n) {
          dbl[j][i] = {-1, -1};
        } else {
          dbl[j][i] = {nxt.first,
                       fst.second + nxt.second};
        }
      }
    }

    int i = 0;
    ll sum = 0;
    for (int j = LOGNK; j >= 0; j--) {
      if (sum + dbl[j][i].second <= k*n) {
        sum += dbl[j][i].second;
        i = dbl[j][i].first;
      }
    }
    put_ans(i, sum);

  }

