int make_doubling() {
  unordered_map<int, int> ump;

  for (int i = 0; i < 2; ++i) {
    for (int j = 0; j < n; ++j) {
      int ind = i * n + j;

      if (ump.find(a[ind % n]) == ump.end()) {
        ump[a[ind % n]] = ind;
      } else {
        int start = ump[a[ind % n]];

        if (start >= n) continue;

        doubling[1][start] = ind + 1 - start;
        ump.erase(a[ind % n]);
        ump[a[ind % n]] = ind;
      }
    }
  }

  int upper = min((int)(ceil(log2(n * k))), MAX_LOG_NK);

  for (int i = 2; i < upper; ++i) {
    for (int j = 0; j < n; ++j) {
      ll fst_buff = doubling[i - 1][j];
      int fst_ind = ((ll)(j) + fst_buff) % n;
      ll snd_buff = doubling[i - 1][fst_ind];

      doubling[i][j] = (fst_buff + snd_buff);
      doubling[i][j] = (doubling[i][j] >= INF) ? INF : doubling[i][j];
    }
  }

  // for (int i = 1; i < upper; ++i) {
  //   printf("%d: ", i);
  //   for (int j = 0; j < n; ++j) {
