  return upper;
}

ll fast_simulate(int upper) {
  ll last = 0LL;

  while (true) {
    int ind = (int)(last % (ll)(n));
    bool flg = false;

    for (int i = upper - 1; i >= 1; --i) {
      if (last + doubling[i][ind] < (ll)(n) * k) {
        last += doubling[i][ind];
        flg = true;
        break;
      }
    }

    // printf("%lld\n", last);

    if (!flg) {
      return last;
    }
  }
}

