int n,k,a[200000],z,memo[200000];
vector<int> v[200000];
vector<int> ANS;
bool f;

signed main() {
    cin >> n >> k;
    rep(i,n) {
        cin >> a[i];
        v[a[i]].pb(i);
        if (!memo[a[i]]) memo[a[i]] = i+1;
    }
    while(n) {
        if (z==n-1) f=true;
        repo(i,z,n) {
            auto itr = upper_bound(all(v[a[i]]), i);
            if (itr != v[a[i]].end()) {
                i = *itr;
                if (i==n-1) f=true;
            }
