            if (hoge==0) {
                cout << endl;
                return 0;
            }
            hoge--;
            z = ANS[hoge];
            z--;
            repo(i,z,n) {
                auto itr = upper_bound(all(v[a[i]]), i);
                if (itr != v[a[i]].end()) i = *itr;
                else cout << a[i] << " ";
            }
            cout << endl;
            return 0;
        }
    }
