using namespace std;


ll A[200000];
queue<ll> que[200001];

ll op_num[200000]; // the num of op's when A[i] is the front
ll next_front[200000];

ll ans[200000];

int main(){
    ll N;
    ll K;

    cin >> N >> K;
   // N=200000;
   // K=1000000000000;

    ll turns = N*K;

    for(int i=0; i<N; i++){
        cin >> A[i];
        //A[i]=i+1;
        que[A[i]].push(i);
    }



    for(int i=0; i<N; i++){
        que[A[i]].pop();
        que[A[i]].push(i);

        ll last=que[A[i]].front();
        next_front[i]=(last+1)%N;

        if(last==i){
            op_num[i] = N+1;
        }else if(i < last){
            op_num[i] = last-i+1;
        }else if(last < i){
            op_num[i] = N+last-i+1;
        }
    }

    ll one_cycle=op_num[0];
    for(int temp=next_front[0]; temp!=0; temp=next_front[temp]){
        one_cycle+=op_num[temp];
    }

    turns%=one_cycle;
   // cout << "a " << op_num[0] << " " << op_num[1]<<endl;


    ll temp=0;
    while(turns>=op_num[temp]){
        turns-=op_num[temp];
        temp = next_front[temp];
    }



    ll exist[200001];
    for(int i=0; i<200001; i++){
        exist[i]=-1;
    }
    ll idx=0;
    for(int i=0; i<turns; i++){
        ll x=A[(i+temp)%N];
        if(exist[x]==-1){
            exist[x]=idx;
            ans[idx]=x;
            idx++;
        }else{
            idx=exist[x];
            exist[x]=-1;
        }
    }

    for(int i=0; i<idx; i++){
        cout<<ans[i];
        if(i!=idx-1){
            cout<<" ";
        }
    }
    cout<<endl;

   // cout<<"one cycle: " << one_cycle<<endl;

    return 0;
}

