inline void dfs(int pos,int lvl,bool flag)
{
	if(!flag){
		if(dist[pos]!=-1){
			res=lvl;
			poss=pos;
			return;
		}
		dist[pos]=lvl;
		int u=nxt[pos];
		if(u<=pos){last[lvl]=pos;dfs(u,lvl+1,1);}
		else dfs(u,lvl,1);
	}
	else{
		pos++;
		if(pos<=n){
			dfs(pos,lvl,0);
		}
		else dfs(1,lvl+1,0);
	}
}

signed main()
{
	ios::sync_with_stdio(false);
	cin>>n>>k;
	memset(dist,-1,sizeof(dist));
	memset(last,-1,sizeof(last));
