	for(int i=1;i<=n;i++) v[a[i]].push_back(i);
	for(int i=1;i<=2e5;i++) if(!v[i].empty()){
		for(int j=0;j<v[i].size()-1;j++){
			nxt[v[i][j]]=v[i][j+1];
		}
		nxt[v[i][v[i].size()-1]]=v[i][0];
	}
	dfs(1,1,0);
	int v1=dist[poss]-1,v2=res-dist[poss],st=0;
	if(k<=v1){
		if(last[k]==-1){
			st=n+1;
		}
		else{
			st=last[k];
		}
	}
	else{
		k-=v1;
		k=(k-1)%v2+1;
		k+=v1;
		if(last[k]==-1){
			st=n+1;
		}
		else{
			st=last[k];
		}
	}
	vector<int> ans;
	for(int i=st;i<=n;i++){
		if(nxt[i]<=i){
			ans.push_back(a[i]);
		}
