void deal(int now)
{
    for(int i=now;i<=n;i++)
    {
        if(!use[a[i]])  use[a[i]]=1,po[++tot]=a[i];
        else  
        {
            while(tot>0 && po[tot]!=a[i])  use[po[tot]]=0,tot--;
            tot--;use[a[i]]=0;
        }
    }
    for(int i=1;i<=tot;i++)  cout<<po[i]<<" ";
    cout<<endl;
}
void jump(int now,int m)
{
    int q=0;
    while(q<m)
    {
        int p=nex[now];
        if(p<=now)  q++;
        if(q==m) 
        {
            deal(p+1);return;
        }  
        now=p+1;
        if(now==n+1)  now=1,q++;
        if(q==m)  
        {
            deal(now);
            return;
        }
    }
}
int main()
{
    cin>>n>>k;
    for(int i=1;i<=n;i++)
    {
        scanf("%d",&a[i]);
        if(pre[a[i]]==0)  
        {
            head[a[i]]=i;
            pre[a[i]]=i;
        }
        else
            nex[pre[a[i]]]=i,pre[a[i]]=i;

    }
    for(int i=1;i<=n;i++)
    {
        if(nex[i]==0)  nex[i]=head[a[i]];
    }

    int now=1;vis[now]=1;num[now]=1;
    int past=1;
    while(past<=k)
    {
        if(past==k)  
        {
            deal(now);
        }
        int p=nex[now];
        if(p<=now)   past++; 
        now=p+1;
        if(now==n+1)  now=1,past++;
        if(vis[now]==1)  
        {
            int lo=num[now];
            int step=past-lo;
            long long u=k-past;
            int w=u%step;
            jump(now,w);
            break;
        } 
        vis[now]=1;num[now]=past;
    }
    return 0;
}

