const int N = (int)2e5 + 5, LOG = 40;
int n, a[N], nxt[N][LOG];
ll cost[N][LOG];
map<int, int> lst;
ll K;

int32_t main () {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

    cin >> n >> K; --K;
    for (int i = 1; i <= n; ++i) cin >> a[i];

    for (int i = n; i > 0; --i) {
        if (lst.count(a[i]) ) nxt[i][0] = lst[ a[i] ];
        else nxt[i][0] = -1;
        lst[ a[i] ] = i;
    }

    for (int i = 1; i <= n; ++i) {
        if (nxt[i][0] == -1) nxt[i][0] = lst[ a[i] ];
        if (nxt[i][0] <= i || nxt[i][0] == n) cost[i][0] = 1;
        nxt[i][0] = nxt[i][0] % n + 1;
    }

    for (int j = 1; j < LOG; ++j) {
        for (int i = 1; i <= n; ++i) {
            nxt[i][j] = nxt[ nxt[i][j - 1] ][j - 1];
            cost[i][j] = cost[i][j - 1] + cost[ nxt[i][j - 1] ][j - 1];
        }
    }

    int cur = 1;
    for (int i = LOG - 1; i >= 0; --i) if (cost[cur][i] <= K) {
        K -= cost[cur][i];
        cur = nxt[cur][i];
    }

    return 0;

    set<int> exist;
    vector<int> ans;
    for (int i = cur; i <= n; ++i) {
        if (exist.count(a[i]) ) {
            while (ans.back() != a[i]) ans.pop_back();
            ans.pop_back();
            exist.erase(a[i]);
        }
        else {
            ans.push_back(a[i]);
            exist.insert(a[i]);
        }
    }

    for (int _ : ans) cout << _ << ' '; cout << '\n';

    return 0;
}

