const int maxn = 4e5 + 555;

li n, k;
int a[maxn], pos[maxn], nxt[maxn];
li len[maxn];
bool used[maxn];

void solve(bool __attribute__((unused)) read) {
    cin >> n >> k;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    for (int i = n; i < 2 * n; ++i) {
        a[i] = a[i - n]; 
    }
    memset(pos, -1, sizeof pos);
    for (int i = 2 * n - 1; i >= 0; --i) {
        nxt[i] = pos[a[i]];
        if (nxt[i] != -1) {
            len[i] = nxt[i] - i + 1;
            nxt[i] = (nxt[i] + 1) % n;
        }
        pos[a[i]] = i;
    }
    memset(used, 0, sizeof used);
    vector <int> g = {0};
    vector <li> pref = {0};
    int v = 0;
    while (!used[v]) {
        used[v] = 1;
        pref.push_back(pref.back() + len[v]);
        v = nxt[v];
        g.push_back(v);
    }
    int pos0 = -1;
    for (int i = 0; i < (int)g.size(); ++i) {
        if (g[i] == v) {
            pos0 = i;
            break;
        }
    }
    assert(pos0 != -1);
    li L = n * k;
    li l = 0;
    int x = -1;
    if (pref[pos0] > L) {
        for (int i = 0; i < (int)g.size(); ++i) {
            if (pref[i] > L) {
                l = pref[i - 1];
                x = g[i - 1];
                break;
            }
        }
    } else {
        l = pref[pos0];
        li c = (L - l) / (pref.back() - pref[pos0]);
        l += c * (pref.back() - pref[pos0]);
        for (int i = pos0; i < (int)g.size(); ++i) {
            if (pref[i] - pref[pos0] + l > L) {
                l += pref[i - 1] - pref[pos0];
                x = g[i - 1];
                break;
            }
        }
    }
    assert(x != -1);
    memset(used, 0, sizeof used);
    vector <int> s;
    while (l < L) {
        ++l;
        if (used[a[x]]) {
            while (used[a[x]]) {
                used[s.back()] = 0;
                s.pop_back();
            }
        } else {
            used[a[x]] = 1;
            s.push_back(a[x]);
        }
        x = (x + 1) % n;
    }

    for (int x : s) {
        cout << x << " ";
    }
    cout << "\n";
}

