void solve(){
    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    rep(i,N) cin >> A[i];

    vector<vector<int>> idx(200001);
    vector<int> c(N);
    rep(i,2*N){
        int a = A[i%N];

        if(idx[a].size() > 0)
            c[idx[a].back()] = i - (idx[a].back()) + 1;


        idx[a].push_back(i);
    }
    dump(c);

    const int MAX = 40;
    //vector<vector<int>> dp;
    auto dp = make_v<int>(MAX, N);
    rep(i,N) dp[0][i] = c[i];

    rep(k, MAX-1){
        rep(v, N){
            if(dp[k][v] == INF) dp[k+1][v] = INF;
            else{
                dp[k+1][v] = dp[k][v] + dp[k][(v+dp[k][v])%N];
                if(dp[k+1][v]>K*N) dp[k+1][v]=INF;
            }
        }
    }
    dump(dp[0]);
    dump(dp[1]);
    dump(dp[2]);
    dump(dp[3]);
    dump(dp[4]);

    int now=0;
    for(int k=MAX-1; k>=0; k--){
        dump(dp[k]);
        dump(dp[k][now%N]);
        while(now + dp[k][now%N] < K*N){
            now += dp[k][now%N];
        }
        dump(k, now, now%N);
    }

    cerr << "------" << endl;

    now %= N;
/*
    for(int i=now; i<N; i++){
        if(i+c[i]<=N){ i+= c[i];}
        else{
            cout << A[i] << " ";
        }
    }
    exit(0);
 */
    stack<int> st;
    set<int> s;
    for (int _ = 0; _ < K; _++) {
        if (s.find(A[now]) == s.end()) {
            st.emplace(A[now]);
            s.emplace(A[now]);
        }
        else {
            while (st.top() != A[now]) {
                s.erase(s.find(st.top()));
                st.pop();
            }
            s.erase(s.find(st.top()));
            st.pop();
        }
        now++;
        if (now >= N) now = 0;
    }
    vector<int> v; while (!st.empty()) v.push_back(st.top()), st.pop();
    reverse(v.begin(), v.end());
    for (int i = 0; i < v.size(); i++) {
        cout << v[i];
        if (i + 1 == v.size()) cout << "\n";
        else cout << " ";
    }
}

