int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  int N; int64_t K; std::cin >> N >> K;
  std::vector<int> A(N+N);
  std::vector<int> nx(N+1, -1);
  std::map<int,int> m;
  for(int i = 0; i < N; ++i) {
    std::cin >> A[i];
    A[N+i] = A[i];
  }
  for(int i = 0; i < N+N; ++i) {
    if(m.count(A[i])>0 && m[A[i]] < N) nx[m[A[i]]] = i+1;
    m[A[i]] = i;
  }
  for(int i = N-1; i >= 0; --i) {
    if(nx[i] < N) nx[i] = nx[nx[i]];
  }
  for(int& i: nx) i -= N;
  nx[N] = 0;
  std::vector<int> ix({N, 0});
  while(nx[ix.back()]%N != 0) { int ni = nx[ix.back()]; ix.push_back(ni); }
  if(nx[ix.back()] == 0) ix.pop_back();
  K %= ix.size();
  std::vector<int> ans;
  m.clear();
  for(int i = ix[K]; i < N; ++i) {
    if(m.count(A[i]) > 0 && m[A[i]] < ans.size()) {
      ans.resize(m[A[i]]);
      m.erase(A[i]);
    } else {
      m[A[i]] = ans.size();
      ans.push_back(A[i]);
    }
  }

  if(ans.size() > 0) {
    for(int i = 0; i < ans.size()-1; ++i) std::cout << ans[i] << " ";
    std::cout << ans.back();
  }
  std::cout << std::endl;
  return 0;
}

