int main()
{
	//freopen("in.txt","r",stdin);
	cin>>n>>m;
	for(int i=1;i<=n;i++) scanf("%d",&a[i]), w=max(w,a[i]);
	for(int i=1;i<=n;i++)
	{
		if(!c[a[i]]) c[a[i]]=i;
		if(pre[a[i]]) f[0][pre[a[i]]]=i%n+1;
		if(i==n && pre[a[i]]) f[0][pre[a[n]]]=1, b[0][pre[a[n]]]=(n!=1 ? 1 : 2);
		pre[a[i]]=i;
	}

	for(int i=1;i<=n;i++) if(pre[a[i]]==i)
	{
		f[0][i]=c[a[i]]%n+1;
		b[0][i]=f[0][i]==1?2:1;
	}
	for(int i=1;i<=58;i++)
		for(int j=1;j<=n;j++) f[i][j]=f[i-1][f[i-1][j]], b[i][j]=b[i-1][f[i-1][j]]+b[i-1][j];

	w=1;
	for(int i=58;i>=0;i--) if(b[i][w]+k<m) 
		k+=b[i][w], w=f[i][w];

