using namespace std;

int main(void)
{
  int n,k,buff;

  vector<int> va;
  vector<int> vs;

  cin >> n >> k;

  for(int i = 0;i < n;i++){
    cin >> buff;
    va.push_back(buff);
  }
  for(int i = 0;i < k - 1;i++){
    for(int j = 0;j < n;j++){
      va.push_back(va[j]); // va: X
    }
  }
  for(int i = 0;i < n * k;i++){
    auto result = find(vs.begin(),vs.end(),va[i]);
    if(result == vs.end()){ // not found
      vs.push_back(va[i]);
    }
    else{
      for(auto i = vs.end();i < result;i--)
        vs.pop_back();
    }
  }

  for(const auto& e : vs){
    cout << e << ' ';
  }
  cout << endl;
  return 0;
}

