    i64 ma = 2e5 + 7;
    vector<set<i64>> m(ma);
    for(i64 i = 0; i < n; ++i)
        m[a[i]].emplace(i);

    vector<i64> v(n + 1);
    v[n] = -1;
    for(i64 i = n - 1; i >= 0; --i){
        auto it = m[a[i]].upper_bound(i);
        if(it == m[a[i]].end())
            v[i] = a[i];
        else
            v[i] = v[*it + 1];
    }
    vector<i64> w(ma, -1);
    for(i64 i = 0; i < ma; ++i)
        if(!m[i].empty())
            w[i] = v[*(m[i].begin()) + 1];

    i64 st = v[0];
    deque<i64> t(1, st);
    while(st != -1){
        st = w[st];
        t.emplace_back(st);
    }
    i64 mod = (k - 1) % t.size();
    t.pop_back();
    t.push_front(-1);
    i64 start = (t[mod] == -1 ? 0 : (*m[t[mod]].begin()) + 1);

    vector<i64> ans;
    while(start != n){
        auto iter = m[a[start]].upper_bound(start);
        if(iter == m[a[start]].end()){
            ans.emplace_back(a[start]);
            ++start;
        }
        else{
            start = *iter + 1;
        }
    }
    for(size_t i = 0; i + 1 < ans.size(); ++i)
        cout << ans[i] << " ";
    if(!ans.empty())
        cout << ans.back();
    cout << endl;

    return 0;
}


