      if(mid >= n * k){
        g[i][j] = n * k;
        continue;
      }
      long temp = g[(int)(mid % n)][j - 1];
      if(temp >= n * k){
        g[i][j] = n * k;
        continue;
      }
      g[i][j] += temp;
      g[i][j] = min(g[i][j], n * k);
    }
  }

  //REP(i, n) cout << g[i][60] << ' '; cout << endl;


  //ここでプログラムが止まらなっているっぽい
