        f = (b[f]+1)%n;
    } while (f);
    k %= cnt;
    while (1) {
        if (k == 0) break;
        if (b[f] <= f) {
            k--;
            if (k == 0) {
                k++;
                break;
            }
        }
        f = (b[f]+1)%n;
    }
    vector<int> ans;
    if (k) {
        do {
            if (b[f] > f) {
                f = (b[f]+1)%n;
            } else {
                ans.push_back(a[f]);
                f++;
                f %= n;
            }
        } while (f);
    }
    int m = ans.size();
    for (int i = 0;i < m;++i) cout << ans[i] << " \n"[i == m-1];
    return 0;
}

