    int cur = 0;
    ll rem = n * k;
    per(l,0,LOG) {
        if (dist[l][cur] <= rem) {
            // cout << "jump " << l << " " << cur << " " << jmp[l][cur] << " " << rem << endl;
            rem -= dist[l][cur];
            cur = jmp[l][cur];
            l++;
        }
    }

    // assert(rem <= N*2);

    vector<int> rest;

    while (rem > 0) {
        rem--;
        rest.push_back(a[cur]);
        cur = (cur + 1) % n;
    }
    vector<int> res = sim(rest);

    cout << res << endl;
}

