int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    int N; LL K;
    cin >> N >> K;
    vector<int> A(N); cin >> A;

    vector<int> next(N);
    {
        map<int,int> nearest;
        for (int i = N-1; i >= 0; --i) {
            nearest[A[i]] = i+N;
        }
        for (int i = N-1; i >= 0; --i) {
            next[i] = nearest[A[i]];
            nearest[A[i]] = i;
        }
    }

    int L = log2(K*N);
    auto dp = make_v<LL>(L+1,N);
    for (int i = 0; i < N; ++i) {
        dp[0][i] = next[i]-i+1;
    }
    for (int l = 0; l < L; ++l) {
        for (int i = 0; i < N; ++i) {
            dp[l+1][i] = dp[l][i] + dp[l][(dp[l][i]+i) % N];
        }
    }

    int cur = 0;
    LL total = 0;
    for (int l = L; l >= 0; --l) {
        if (total + dp[l][cur] < K*N) {
            total += dp[l][cur];
            cur = (dp[l][cur]+cur) % N;
        }
    }


    vector<int> ans;
    for (int i = cur; i < N;) {
        if (next[i] < N) {
            i = next[i]+1;
        } else {
            ans.emplace_back(A[i]);
            ++i;
        }
    }

    for (auto v : ans) {
        cout << v << " ";
    }
    cout << endl;

    return 0;
}

