                //cerr << "  next = " << next << endl;
                int start = m[next];
                int period = loop - m[next];
                int left = K - start - 1;
                if (now == next && now == N - 1) {
                    period++;
                }
                //fprintf(stderr, "start:%lld period:%lld left:%lld\n", start, period, left);
                left %= period;
                //fprintf(stderr, " -> left:%lld\n", left);
                if (now == next && now == N - 1 && left == period - 1) {
                    target = N;
                } else {
                    target = rm[start + left] + 1;
                    if (now == next && now == N - 1 && target == N) {
                        target = 0;
                    }
                }
                break;
            }
            m[next] = loop;
            rm[loop] = next;
            //fprintf(stderr, " m[%lld] = %lld\n", next, loop);
        }
        //fprintf(stderr, "now:%lld next:%lld loop:%lld\n", now, next, loop);
        now = next + 1;
        if (now == N) now = 0;
    }

    assert(target != -1);
    //cerr << "target = " << target << endl;

    vector<int> ret;
    REP(i, target, N - 1) {
        if (inserted[A[i]]) {
            while (!ret.empty() && ret.back() != A[i]) {
                inserted[ret.back()] = false;
                ret.pop_back();
            }
            if (!ret.empty()) {
                inserted[ret.back()] = false;
                ret.pop_back();
            }
        } else {
            ret.push_back(A[i]);
            inserted[A[i]] = true;
        }
    }

    for (auto v : ret) cout << v << " ";
    cout << endl;

    return 0;
}

