int nxt(int nr) {
	if (nr == n) {
		return 1;
	}
	return nr + 1;
}


void solve() {
	read();

	for (int i = n; i >= 1; i--) {
		last[v[i]] = i;
	}
	for (int i = n; i >= 1; i--) {
		pos[0][i] = last[v[i]];
		if (last[v[i]] > i) {
			val[0][i] = last[v[i]] - i;
		}
		else {
			val[0][i] = n - i + last[v[i]];
		}
		last[v[i]] = i;
	}

	for (int bit = 1; bit < LOG; bit++) {
		for (int i = 1; i <= n; i++) {

			if (val[bit-1][i] == -1 || INF - val[bit - 1][i] < 1LL + val[bit - 1][nxt(pos[bit - 1][i])]) {
				val[bit][i] = -1;
			}
			else {
				pos[bit][i] = pos[bit - 1][nxt(pos[bit - 1][i])];
				val[bit][i] = val[bit - 1][i] + 1LL + val[bit - 1][nxt(pos[bit - 1][i])];
