			//cout << "VAL " << i << " " << bit << " : " << val[bit][i] << '\n';
		}
	}

	long long VAL = 1;
	long long POS = 1;

	for (int bit = LOG-1; bit >= 0; bit--) {
		if (val[bit][POS] != -1 && VAL <= n * k - val[bit][POS]) {
			VAL += val[bit][POS] + 1LL;
			POS = nxt(pos[bit][POS]);
		}
	}

	//cout << VAL << " " << POS << '\n';

	if (VAL > n * k) {
		return;
	}

	for (int i = POS; i <= n; i++) {
		if (pos[0][i] > i) {
			i = pos[0][i];
			continue;
		}
		cout << v[i] << " ";
	}

}

