using namespace std;
vector<int> solve(int N, long long K, vector<int> A) {
	vector<int> nxt(N);
	map<int, int> d;
	for (int i = 2 * N - 1; i >= 0; --i) {
		if (i < N) nxt[i] = d[A[i]] - i;
		d[A[i % N]] = i;
	}
	vector<long long> used(N, -1);
	long long pos = 0;
	bool flag = false;
	while (used[pos % N] == -1) {
		used[pos % N] = pos;
		long long prepos = pos;
		pos += nxt[pos % N] + 1;
		if (pos > N * K) {
			pos = prepos;
			flag = true;
			break;
		}
	}
	if (!flag && pos != N * K) {
		pos = pos + (1LL * N * K - 1 - pos) / (pos - used[pos % N]) * (pos - used[pos % N]);
		while (true) {
			long long prepos = pos;
			pos += nxt[pos % N] + 1;
			if (pos > N * K) {
				pos = prepos;
				flag = true;
				break;
			}
		}
	}
	vector<int> arr;
	map<int, int> parity;
	for (long long i = pos; i < N * K; ++i) {
		if (parity[A[i % N]] == 0) {
			parity[A[i % N]] = 1;
			arr.push_back(A[i % N]);
		}
		else {
			parity[A[i % N]] = 0;
			while (arr.back() != A[i % N]) parity[arr.back()] = 0, arr.pop_back();
			arr.pop_back();
		}
	}
	return arr;
}
