signed main(){
  ll n;
  cin>>n;
  ll k;
  cin>>k;

  ll seq=1;
  vector<ll> vec;
  vec.push_back(0);
  for(int i=1;i<=n;i++){
    ll a;
    cin>>a;
    vec.push_back(a);
  }
  for(int i=1;i<=n;i++) vec.push_back(vec[i]);
  for(int i=1;i<=2*n;i++){
    idx[vec[i]].push_back(i);
  }
  ll pos=1;
  memo[1]=0;
  if(k>50000000){
    do{
      ll num=vec[pos];
      auto itr=upper_bound(idx[num].begin(),idx[num].end(),pos);
      ll npos=*itr;
      if(npos==n) {
        pos=1;
        break;
      }
      npos++;
      if(npos>n){
        npos-=n;
        seq++;
      }
      pos=npos;
      if(memo[pos]!=0||pos==1){
        seq-=memo[pos];
        break;
      }
      memo[pos]=seq;
    }while(1);
    if(k<memo[pos]){
      pos=1;
    }
    else{
      k-=memo[pos];
      k%=seq;
    }
  }
  if(k==0){
    cout<<" "<<endl;
    return 0;
  }
  ll cnt=1;
  while(cnt<k){
    ll num=vec[pos];
    ll kpos=upper_bound(idx[num].begin(),idx[num].end(),pos)-idx[num].begin();
    ll npos=idx[num][kpos];
    npos++;
    if(npos>n){
      npos-=n;
      cnt++;
    }
    pos=npos;
  }
  vector<ll> ans;
  while(pos<=n){
    ll num=vec[pos];
    auto itr=upper_bound(idx[num].begin(),idx[num].end(),pos);
    ll npos=*itr;
    if(npos>n) {
      ans.push_back(num);
      pos++;
    }
    else{
      pos=npos+1;
    }
  }
  for(int i=0;i<ans.size();i++) cout<<ans[i]<<" ";
  cout<<endl;
}

