#define REP(i,n) for (ll i = 0; i < n; ++i)
#define REPR(i,n) for (ll i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (ll i = m; i < n; ++i)
#define FORR(i,m,n) for (ll i = n-1; i >= m; --i)
#define FORE(x,xs) for (const auto& x : xs)
#define ALL(v) v.begin(), v.end()
#define CHMIN(x,y) x = min(x, y)
#define CHMAX(x,y) x = max(x, y)

const int MAX = 2e5+10;

ll N, K;
int A[MAX];
vi idx[MAX];

vi solve() {
    REP (i, N) idx[A[i]].push_back(i);
    ll ped = 0;
    int n = 0;
    while (!(ped != 0 && n == 0)) {
        int a = A[n];
        auto iter = upper_bound(ALL(idx[a]), n);
        if (iter == idx[a].end()) {
            ped++;
            n = (idx[a][0] + 1) % N;
        } else {
            n = (*iter + 1) % N;
        }
        if (n == 0) ped++;
    }
    K %= ped;

    vi ans;
    n = 0;
    while (K) {
        int a = A[n];
        auto iter = upper_bound(ALL(idx[a]), n);
        if (iter == idx[a].end()) {
            if (K == 1) {
                ans.push_back(a);
                n = (n+1) % N;
            } else {
                K--;
                n = (idx[a][0] + 1) % N;
            }
        } else {
            n = (*iter + 1) % N;
        }
        if (n == 0) {
            K--;
        }
        if (K == 0) break;
    }
    return ans;
}

int main() {
    cin >> N >> K;
    REP (i, N) cin >> A[i];
    FORE (x, solve()) cout << x << " ";
    cout << endl;
}

