//写経
void doubling(ll N, ll K, const vector<ll> &A, vector<vector<ll>> &a){


  //先ずはa[0][i]を求めて行く
  vector<ll> used(200010,-1);

  for(ll k = 0; k < 2; k++){
   for(ll i = 0; i < N; i++){ 

    if(used[A[i]] != -1){

      a[0][(used[A[i]])%N] = k*N+i-used[A[i]]+1;

    }

    used[A[i]] = k*N+i;   //最後にその数字を使った位置を記録しておく
   }//for-i
  }// for-k


  for(ll k = 1; k < 60; k++){ 

    for(ll i = 0; i < N; i++){

    a[k][i] = a[k-1][i]+a[k-1][(i+a[k-1][i])%N];

    }
  } 


}// doubling-とじ

ll starting(ll N, ll K, const vector<vector<ll>> &a){

  ll sum = 0; ll now = 0;

  const ll SIZE = N*K;

  while(true){

    ll ind = 0;

    for(ll i = 0; i < 60;i++){
     if( a[i][now]+sum >= SIZE ){ 

        ind = i-1;

        break;
      }
    }

    if( ind == -1 ){ break;}

    sum += a[ind][now];
    now = sum%N;

  }


  return now;

}


deque<ll> simulate(ll start, ll N, vector<ll> A){
  // startからN-1にかけては愚直にシミュレートを行う

  deque<ll> Q; vector<bool> used(200010,false);

  for(ll i = start; i < N; i++){

    ll a = A[i];

    if( !used[a]  ){ Q.push_back(a); used[a] = true;}
    else{

      while(true){

        ll x = *Q.rbegin();
        used[x] = false;
        Q.pop_back();

        if( x == a ){ break;}


      }
    }

  }

  return Q;
}









