	ll cur = 0;
	its[0] = 0;
	ll pos = 0;
	while (K) {
		if (next[pos] <= pos || next[pos] == N - 1) {
			--K;
			++cur;
		}
		pos = (next[pos] + 1) % N;
		if (its[pos] != -1) break;
		its[pos] = cur;
	}
	if (K != 0) {
		ll loops = cur - its[pos];
		K %= loops;
	}
	while (K) {
		if (next[pos] <= pos || next[pos] == N - 1) {
			--K;
		}
		pos = (next[pos] + 1) % N;
	}
	while (pos < N && next[pos] > pos) pos = next[pos] + 1;
	vll ans;
	while (pos < N) {
		ans.push_back(arr[pos]); 
		++pos;
		while (pos < N && next[pos] > pos) pos = next[pos] + 1;
	}

	for (ll x : ans) cout << x << " ";
	cout << endl;
}

