int n, a[200200], order[200200];
long long k;
vector<int> id[200200];

int getMove(long long step)
{
  int curId = step % n, val = a[curId], curOrder = order[curId];
  if (curOrder + 1 == id[val].size())
    return id[val][0] + n - curId;
  return id[val][curOrder + 1] - curId;
}

void solve(long long from, long long to)
{
  long long step = from;
  while (step < to)
  {
    int move = getMove(step);
    if (step + move < to) step = step + move + 1;
    else
    {
      cout << a[step % n] << ' ';
      step++;
    }
  }
  cout << endl;
  exit(0);
}

int main()
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);


  cin >> n >> k;
  for (int i = 0; i < n; i++)
  {
    cin >> a[i];
    order[i] = id[a[i]].size();
    id[a[i]].push_back(i);
  }

  vector<int> seen(n, -1);
  long long step = 0;
  while (step < k * n)
  {
    seen[step % n] = step;
    int move = getMove(step);
    if (step + move + 1 >= k * n) solve(step, k * n);
    else
    {
      step += move + 1;
      if (seen[step % n] >= 0)
      {
        long long  cycle = step - seen[step % n], startCycle = seen[step % n];
        solve(startCycle, startCycle + (k * n - startCycle) % cycle);
      }
    }
  }
}

