int main(){
    ll n, k;
    cin >> n >> k;
    vector<ll> a(n);
    REP(i, n){ cin >> a.at(i); }

    vector<ll> b = a;
    b.insert(b.end(), ALL(a));

    vector<ll> next_index(b.size(), -1);
    map<ll, ll> nmap;
    RREP(i, b.size()){
        const auto bi = b.at(i);
        if(nmap.count(bi)){
            const auto j = nmap[bi];
            if(j + 1 < 2 * n && next_index[j + 1] != -1){
                next_index[i] = next_index[j + 1];
            }else{
                next_index[i] = j + 1;
            }
        }
        nmap[bi] = i;
    }

    next_index.resize(n + 1);
    // cerr << "0 ";
    REP(i, n + 1){
        if(next_index.at(i) == -1){
            next_index.at(i) = i % n;
        }else{
            next_index.at(i) -= n;
        }
        assert(next_index.at(i) >= 0 && next_index.at(i) <= n);
        // cerr << next_index.at(i) << ' ';
    }
    // cerr << endl;

    vector<vector<ll>> next2p(42, vector<ll>(n + 1));
    next2p.at(0) = next_index;
    for(ll i = 1; i < next2p.size(); ++i){
        // cerr << i << ' ';
        REP(j, n + 1){
            const ll j2 = next2p.at(i - 1).at(j);
            next2p.at(i).at(j) = next2p.at(i - 1).at(j2);
            // cerr << next2p.at(i).at(j) << ' ';
        }
        // cerr << endl;
    }

    ll cur_idx = 0;
    k--;
    REP(i, next2p.size()){
        if((k >> i) & 1){
            cur_idx = next2p.at(i).at(cur_idx);
        }
    }

    // cerr << "cur_idx=" << cur_idx << endl;

    vector<ll> ans;
    set<ll> used;
    for(; cur_idx < n; ++cur_idx){
        const auto ai = a.at(cur_idx);
        if(used.count(ai)){
            while(used.count(ai)){
                used.erase(ans.back());
                ans.pop_back();
            }
        }else{
            ans.push_back(ai);
            used.insert(ai);
        }
    }

    REP(i, ans.size()){
        cout << ans.at(i);
        if(i + 1 < ans.size()){
            cout << ' ';
        }
    }
    cout << endl;
    return 0;
}

