int n,a[1000010],las[1000010],stk[1000010],top,ap[1000010],nxt[1000010],tp[1000010],v[1000010],now;
LL k,cir,hang;
int main(){
	cin>>n>>k;
	FOR(i,1,n) getint(a[i]);
	FOR(i,n+1,n*3) a[i]=a[i-n];
	FORD(i,n*3,n+2){
		las[a[i]]=i;
	}
	FORD(i,n,1){
		nxt[i]=(las[a[i+1]]-1)%n+1,tp[i]=(las[a[i+1]]-1)/n;
		las[a[i+1]]=i+1;
	}
	memset(v,-1,sizeof(v));
	now=n;
	hang=0;
	while (1){
		if (v[now]!=-1){
			cir=hang-v[now];
			hang+=(k-hang)/cir*cir;
			break;
		}
		v[now]=hang;
		if (hang+tp[now]<=k){
			hang+=tp[now];
			now=nxt[now];
		}
		else break;
	}
	while (1){
		if (hang+tp[now]<=k){
			hang+=tp[now];
			now=nxt[now];
		}
		else break;
	}
	while (1){
		++now;
		if (now>n){now=1;++hang;}
		if (hang>k) break;
		if (ap[a[now]]){
			while (stk[top]!=a[now]){
				ap[stk[top]]=0;
				--top;
			}
			--top;
			ap[a[now]]=0;
		}
		else stk[++top]=a[now],ap[a[now]]=1;
	}
	FOR(i,1,top) cout<<stk[i]<<' ';
	return 0;
}

