#define large 200010
typedef long long int llint;

int main()
{
	llint n, k;
	scanf("%lld %lld", &n, &k);
	int a[large] = {};
	for (int i = 0; i < n; i++) scanf("%d", &a[i]);

    int memo[large]={};
    int memol;
	int x[large] = {};
	int l = 0;
	for (llint i = 0; i < k; i++)
	{
		for (int j = 0; j < n; j++)
		{
			bool judge = true;
			for (int p = 0; p < l; p++)
			{
				if (x[p] == a[j])
				{
					judge = false;
					int le = l;
					for (int q = p; q < le; q++)
					{
						x[q] = 0;
						l--;
					}
					break;
				}
			}
			if (judge)
			{
				x[l] = a[j];
				l++;
			}
		}
        if(i==0)
        {
            for(int j=0;j<l;j++)
            {
                memo[j]=x[j];
            }
            memol=l;
        }
        else
        {
            bool judge=true;
            if(memol!=l)
            {
                judge=false;
            }
            else
            {
                for(int j=0;j<l;j++)
                {
                    if(memo[j]!=x[j])
                    {
                        judge=false;
                        break;
                    }
                }
            }
            if(judge)
            {
                i=(k/i)*i;
            }

        }

	}
    if(l==0) printf("\n");
    else
	for (int i = 0; i < l; i++)
	{
		printf("%d%c", x[i], i + 1 == l ? '\n' : ' ');
	}
}

