  {
    vec2[i] = vec[i];
    vec2[i + n] = vec[i];
  }
  // DEBUG(vec2);
  vector<int> loop(2 * n, 0);
  for (int i = 0; i < n; i++)
  {
    for (int j = i + 1; j < 2 * n; j++)
    {
      if (vec2[i] == vec2[j])
      {
        loop[i] = j + 1;
        break;
      }
    }
  }

  int l = 0;
  int pos = 0;
  while (true)
  {
    int next = loop[pos];
    if (next >= n)
      l++;
    next %= n;
    // DEBUG(pos, next, "\n");
    if (next == 0)
      break;
    pos = next;
  }
  // DEBUG(loop, l);
  k %= l;
  l = 0;
  pos = 0;
  while (true)
  {
    int next = loop[pos];
    if (next >= n)
      l++;
    next %= n;
    // DEBUG(pos, next, "\n");
    if (l >= k)
      break;
    pos = next;
  }
  vector<int> res;
  if (pos == 0)
    return;
  for (int i = pos; i < n; i++)
  {
    res.push_back(vec[i]);
    int lc = res.size();
    for (int j = 0; j < lc - 1; j++)
    {
      int vback = res.back();
      if (vback == res[j])
      {
        // DEBUG(vback);
        while (res.size() > j)
        {
          // DEBUG(res);
          res.pop_back();
        }
        break;
      }
    }
  }
  for (int i = 0; i < res.size(); i++)
  {
    if (i != 0)
      cout << char(32);
    cout << res[i];
  }
  cout << endl;

