#define fast_cin() ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0)
#define endl '\n'
#define int long long

const int N = 4e5 + 5, LG = 60;
const int inf = 1e18;

int jumpDist[N][LG];
int a[N], nxtOcc[N];

int32_t main() {
	fast_cin();  
	int n, k; cin >> n >> k;
	for (int i = 0; i < n; ++i) {
		cin >> a[i];
		a[i + n] = a[i];
	}
	for (int i = 2 * n - 1; i >= 0; --i) {
		if (i < n) {
			jumpDist[i][0] = (nxtOcc[a[i]] - i) + 1;
		}
		nxtOcc[a[i]] = i;
	}
	// binary lifting
	for (int j = 1;  j < LG; ++j) {
		for (int i = 0; i < n; ++i) {
			jumpDist[i][j] = min(inf, jumpDist[i][j - 1] + jumpDist[(i + jumpDist[i][j - 1]) % n][j - 1]);
		}
	}
	int curloc = 0;
	for (int j = LG - 1; j >= 0; --j) {
		if (curloc + jumpDist[curloc % n][j] <= n * k) {
			curloc += jumpDist[curloc % n][j];
		}
	}
	vector<int> ans;
	while (curloc < n * k) {
		if (curloc + jumpDist[curloc % n][0] <= n * k) {
			curloc += jumpDist[curloc % n][0];
		} else {
			ans.push_back(a[curloc % n]);
			++curloc;
		}
	}
	for (int &i : ans) {
		cout << i << " ";
	}
	cout << endl;
	return 0;
}

