int main(void) {

	cin >> N >> K;

	for (int i = 0; i <= N - 1; i++) {
		cin >> A[i];
	}

	for (int i = 0; i <= 200000; i++) {
		C[i] = -1;  NEXT[i][0] = -1;
	}

	for (int i = 0; i < 2 * N; i++) {
		if (C[vA(i)] == -1) { C[vA(i)] = i; }
		else {
			if (NEXT[C[vA(i)]][0] == -1) { NEXT[C[vA(i)]][0] = i - C[vA(i)] + 1; }
			C[vA(i)] = i;
		}
	}

	for (int k = 0; k <= 42; k++) {
		for (int i = 0; i <= N - 1; i++) {
			NEXT[i][k + 1] = min(NEXT[(NEXT[i][k] + i) % N][k] + NEXT[i][k], INF);
		}
	}


	/*for (int k = 0; k <= 4; k++) {
		for (int i = 0; i < N; i++) {
			cout << "NEXT[" << i << "][" << k << "]= " << NEXT[i][k] << endl;
		}
	}*/

	long long int a = 0;

	int sign = 1;

	while (sign) {
		sign = 0;
		for (int k = 40; k >= 0; k--) {
			if (a + NEXT[a%N][k] <= K*N - 1) {
				a += NEXT[a%N][k];  sign = 1;  break;
			}
		}
		//cout << "a= " << a << endl;
	}

	//cout << "a= " << a << " vA= " << vA(a) << endl;

	vector<long long int> ans;
	set<long long int > S;

	for (long long int i = a; i <= K*N - 1; i++) {

		if (S.count(vA(i)) == 0) {
			ans.push_back(vA(i)); S.insert(vA(i));
		}
		else {
			int M = ans.size();
			while (S.find(vA(i))!=S.end()) {
				long long int tmp = ans[M - 1];
				ans.pop_back(); S.erase(tmp);
				M--;
				if (tmp == vA(i)) { break; }
			}
		}
	}


	for (int i = 0; i < (int)ans.size(); i++){
