template<class T1, class T2>
inline
std::ostream&
operator<<(std::ostream& os, const std::pair<T1, T2>& p)
{
  return os << p.first << ' ' << p.second;
}

void solve(void)
{
  ui  N{}; std::cin >> N;
  ull K{}; std::cin >> K;

  typedef std::vector<ui> Vector;
  Vector A(N);
  std::map<ui, Vector> idx;
  rep(0, N)
  {
    std::cin >> A[i];
    idx[A[i]].push_back(i); // 出現位置
  }

  ui LOG_K = (ui)log2(K);
  ui LOG_N = (ui)log2(N);
  assert(LOG_K + LOG_N < 58); // 制約チェック

  typedef std::vector<ull> Vector_ull;
  std::vector<Vector_ull> dp(LOG_K + LOG_N + 1, Vector_ull(N));
  for (auto p : idx)
  {
    ui sz = p.second.size();
    p.second.push_back(p.second[0] + N);
    rep(0, sz)
    {
      dp[0][p.second[i]] = p.second[i + 1] - p.second[i] + 1; // 移動距離
    }
  }

  rep(1, dp.size())
  {
    rep_uj(0, N)
    {
      dp[i][j] = std::min(
        std::numeric_limits<ull>::max() / 3,
        dp[i - 1][j] + dp[i - 1][(dp[i - 1][j] + j) % N]);
    }
  }

  ull it{ 0 };
  ull it_max = K * N - 1;
  for(ui i = dp.size() - 1;;)
  {
    if (it + dp[i][it % N] <= it_max)
    {
      it += dp[i][it % N];
    }
    if(!i--)
      break;
  }
  assert(it <= it_max);

  Vector ans;
  ans.reserve(N);

  it %= N;
  std::set<ui> dic;
  while(it < N)
  {
    if (dic.count(A[it]))
    {
      while (true)
      {
        ui last = ans.back();
        ans.pop_back();
        dic.erase(last);
        if (last == A[it])
          break;
      }
    }
    else
    {
      ans.push_back(A[it]);
      dic.insert(A[it]);
    }
    ++it;
  }

  std::cout << ans << "\n";

  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

