const long long inf = 1.23e18;
const int N = 2e5;
const int Z = 58;

int n;
int a[N];

int nxt[Z][N];
long long cnt[Z][N];

int main() {
	ios_base::sync_with_stdio(false);

	memset(nxt, -1, sizeof(nxt));

	cin >> n;
	long long k;
	cin >> k;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}

	{
		vector<int> last(N, -1);
		for (int i = n-1; i >= 0; i--) {
			int x = a[i];
			if (last[x] != -1) {
				nxt[0][i] = (last[x]+1)%n;
				cnt[0][i] = last[x]+1 - i;
			}
			last[x] = i;
		}
		for (int i = 0; i < n; i++) {
			int x = a[i];
			if (nxt[0][i] == -1) {
				nxt[0][i] = (last[x]+1)%n;
				cnt[0][i] = n-i + last[x]+1;
			}
		}
	}
	for (int z = 1; z < Z; z++) {
		for (int i = 0; i < n; i++) {
			int j = nxt[z-1][i];
			nxt[z][i] = nxt[z-1][j];
			if (cnt[z-1][i] <= inf - cnt[z-1][j]) {
				cnt[z][i] = cnt[z-1][i] + cnt[z-1][j];
			} else {
				cnt[z][i] = inf;
			}
		}
	}

	long long tot = n*k - n;
	int i = 0;
	for (int z = Z-1; z >= 0; z--) {
		if (cnt[z][i] == inf) continue;
		while (tot >= cnt[z][i]) {
			tot -= cnt[z][i];
			i = nxt[z][i];
		}
	}
	tot += n;
	vector<int> ans;
	vector<int> was(N+1);
	while (tot--) {
		int x = a[i];
		if (was[x]) {
			while (true) {
				int y = ans.back();
				ans.pop_back();
				was[y]--;
				if (y == x) {
					break;
				}
			}
		} else {
			ans.push_back(x);
			was[x]++;
		}
		i = (i+1)%n;
	}

	for (int x : ans) {
		cout << x << ' ';
	}
	cout << endl;

	return 0;
}

