int main()
{
    long long N, K;
    cin >> N >> K;

    vector<int> A(N);
    for (int &a : A)
    {
        cin >> a;
    }

    vector<vector<int>> dp(N);
    vector<int> current;
    map<int, int> m;
    for (int i = N - 1; i >= 0; i--)
    {
        if (m.find(A[i]) == m.end())
        {
            current.push_back(A[i]);
        }
        else
        {
            int idx = m[A[i]] + 1;

            if (idx >= N)
            {
                current.clear();
            }
            else
            {
                current = dp[idx];
            }
        }
        dp[i] = current;
        m[A[i]] = i;
    }

    int loop = -1;
    vector<vector<int>> ans(1);
    ans[0].clear();
    ans.push_back(current);

    for (long long i = 2; i <= K; i++)
    {
        if (current.empty())
        {
            current = dp.front();
        }
        else
        {
            int idx = m[current.back()] + 1;
            if (idx >= N)
            {
                current.clear();
            }
            else
            {
                current = dp[idx];
            }
        }

        ans.push_back(current);
        if (loop == -1 && current.empty())
        {
            loop = i;
            break;
        }
    }

    if (loop == -1)
    {
        K = K;
    }
    else
    {
        K %= loop;
    }

    for (auto itr = ans[K].rbegin(); itr != ans[K].rend(); itr++)
    {
        cout << *itr << " ";
    }
    cout << endl;
}

