class BIT {

	static const int MAX_N = 100010;
public:
	BIT() { memset(bit, 0, sizeof(bit)); }
	int bit[MAX_N + 1], n;
	int sum(int i) {
		int s = 0;
		while (i > 0)
		{
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, int x) {
		while (i <= n)
		{
			bit[i] += x;
			i += i & -i;
		}
	}
	void clear() {
		memset(bit, 0, sizeof(bit));
	}
	int a[MAX_N];
	void bable_swap_count() {
		ll ans = 0;
		for (size_t j = 0; j < n; j++)
		{
			ans += j - sum(a[j]);
			add(a[j], 1);
		}
		printf("%lld\n", ans);
	}

	int search(int s, int x) {

		ll half = (s + x) / 2;
		ll sh = sum(x);

		ll sl = sum(half);

		ll st = sum(s);
		if (sh - sl == 0) {
			return x;
		}
		if (sh - sl < x - half) {
			return search(half, x);
		}

		if (sl - st == 0) {
			return half;
		}

		if (sl - st < half - s) {
			return search(s, half);
		}
		return -1;
	}
};
void solv() {
	ll k;
	cin >> n >> k;
	ll p[200010];
	for (size_t i = 0; i < n; i++)
	{
		cin >> p[i];
	}

	ll po[200010];
	memset(po, -1, sizeof(po));
	ll bef[200010];
	memset(bef, -1, sizeof(bef));
	for (int i = n - 1; i >= 0; i--)
	{
		if (bef[p[i]] != -1) po[i] = bef[p[i]];
		bef[p[i]] = i;
	}
	for (int i = n - 1; i >= 0; i--)
	{
		if (po[i] == -1) po[i] = bef[p[i]];
	}
	ll next[200010];
	memset(next, -1, sizeof(next));
	// 対象のindexがその周の開始地点だった場合に次の周がどこを先頭に始まるか
	// 次の周で空になる地点を探す
	for (int i = n - 1; i >= 0; i--)
	{
		int pos = i;
		if (pos >= po[pos]) {
			next[i] = (po[pos] + 1) % n;
			continue;
		}

		// 同じ周の場合
		pos = po[pos] + 1;
		if (pos == n) {
			next[i] = 0;
			continue;
		}
		next[i] = next[pos];
	}

	int lo = 0;
	int loop = 0;
	bool lop = false;
	for (size_t i = 0; i < k - 1; i++)
	{
		lo = next[lo];
		loop++;
		if (lo == 0) {
			lop = true; break;
		}
	}
	if (lop) {
		if (k % loop == 0)k = loop;
		else k = k % loop;
		for (size_t i = 0; i < k - 1; i++)
		{
			lo = next[lo];
		}
	}

	vector<int> res;
	for (size_t i = lo; i < n; i++)
	{
		if (i >= po[i]) {
			res.push_back(p[i]);
		}
		else {
			i = po[i];
		}
	}

	for (size_t i = 0; i < res.size(); i++)
	{
		cout << res[i] << endl;
	}
}
