template <class T>
int numGTE(const vector <T>& v, T x)
{
	const int N = SZ(v);
	return N - (lower_bound(v.begin(), v.end(), x) - v.begin());
}

// ＜X の要素数を求める
// ≧Xの最初のindexを求める。全ての要素がX未満のときNを返す。
// 例えば{3,5,7,8,8,10}でx=8なら3を返す
template <class T>
int numLT(const vector <T>& v, T x)
{
	return lower_bound(v.begin(), v.end(), x) - v.begin();
}

// ≦X の要素数を求める。
// ＞Xの最初のindexを求める。全ての要素がX以下のときNを返す。
// 例えば{3,5,7,8,8,10}でx=8なら5を返す
template <class T>
int numLTE(const vector <T>& v, T x)
{
	return upper_bound(v.begin(), v.end(), x) - v.begin();
}

// ある数字がどの半区間 [v[i], v[i+1)に入るかを求めるときは、1を引くこと。すごく汎用的！
//    x＜3 ... -1（最初の要素未満）
// 3≦x＜5 ...  0
// 5≦x＜7 ...  1
// 7≦x＜8 ...  2
template <class T>
int indexRange(const vector <T>& v, T x)
{
	return upper_bound(v.begin(), v.end(), x) - v.begin() - 1;
}

