int main(int argc, const char * argv[]) {
  ll N, K; cin >> N >> K;
  vector<int> A(N);
  for(int i=0; i<N; i++)
    cin >> A[i];

  vector<vector<int>> jump(200001);
  for(int i=0; i<N; i++)
    jump[A[i]].push_back(i+1);

  vector<ll> log;
  set<pair<ll, ll>> visited;
  ll len, num;
  len = 1;
  num = A[0];
  ll period;
  log.push_back(len);
  visited.emplace(len%N, num);
  while(true){
    ll i = find(jump[num].begin(), jump[num].end(), len%N) - jump[num].begin();
    if(i != jump[num].size()){
      len += jump[num][i+1] - jump[num][i] + 1;
    }else {
      len += N - jump[num][i] + jump[num][0] + 1;
    }
    num = len % N;
    if(visited.end() != visited.find(make_pair(len%N, num))){
      period = (len-1)/N;
      log.push_back(len);
      assert((len-1)%N == 0);
      break;
    }
    log.push_back(len);
    visited.emplace(len%N, num);
  }
  K %= period;
  auto it = lower_bound(log.begin(), log.end(), K*N);
  it--;
  ll start = *it;
  for(ll i=start; i<K*N; i++){
    cout << A[i%N] << " ";
  }
  cout << endl;

  return 0;
}

