int main()
{
    ll n, k;
    cin >> n >> k;
    vector<int> a(n);
    vector<set<int>> vs(2*1e5+10);
    for(int i = 0; i < n; i++)
    {
        cin >> a[i];
        vs[a[i]].insert(i);
    }
    int pos = 0;
    int cnt = 1;
    vector<int> last(n+1, 0);
    while(true)
    {
        int num = a[pos];
        if(vs[num].size() != 1)
        {
            auto itr = vs[num].lower_bound(pos+1);
            if(itr == vs[num].end())
            {
                pos = *vs[num].begin();
                cnt++;
            }
            else pos = *itr;
        }
        else cnt++;
        pos++;
        last[cnt] = pos;
        if(pos == n) break;
    }
    vector<int> ans;
    pos = last[k%cnt];
    while(pos < n)
    {
        int num = a[pos];
        auto itr = vs[num].lower_bound(pos+1);
        if(itr == vs[num].end()) ans.push_back(num);
        else pos = *itr;
        pos++;
    }
    for(int a : ans) cout << a << " ";
    cout << endl;
}

