int main() {
  ll N, K;
  get(N, K);
  vector<int> A(N);
  getv(A);
  vector<int> next(N);
  map<int, int> first, last;
  unordered_set<int> visit;
  for (int i = N - 1; i >= 0; --i) {
    if (visit.count(A[i])) {
      next[i] = last[A[i]];
    } else {
      next[i] = i;
    }
    last[A[i]] = i;
    visit.insert(A[i]);
  }
  last.clear();
  visit.clear();
  for (int i = 0; i < N; ++i) {
    if (!visit.count(A[i])) {
      first[A[i]] = i;
    }
    if (next[i] <= i) {
      next[i] = first[A[i]];
    }
    visit.insert(A[i]);
  }
  int now = 0;
  vector<int> list;
  unordered_set<int> hold;
  while (1) {
    int nxt = next[now];
    if (nxt <= now || nxt == N - 1) {
      if (!hold.count(now)) {
        list.push_back(now);
        hold.insert(now);
      } else {
        break;
      }
    }
    if (now == nxt && now == N - 1) {
      list.push_back(now + 1);
      hold.insert(now + 1);
    }
    // debug(now, nxt);
    now = (nxt + 1) % N;
  }
  int pos = list[(K - 1) % list.size()];
  // debug(list, pos);
  vector<int> ima;
  for (int i = pos; i < N; ++i) {
    if (next[i] > i && next[i] < N)
      i = next[i];
    else if (next[i] <= i)
      ima.push_back(A[i]);
  }
  for (int x : ima)
    cout << x << " ";
  return 0;
}

