ll N, K;
vector<ll> A;
vector<ll> B[200010];
bool visted[100010];
int main(){
  cin >> N >> K;
  K--;
  A.resize(N);
  rep(i, N) cin >> A[i];
  rep(i, N){
    B[A[i]].pb(i);
  }
  vector<ll> start;
  ll at = 0;
  while(true){
    if(visted[at]) break;
    visted[at] = 1;
    start.pb(at);
    while(true){
      ll lar = A[at];
      ll lar_at = lower_bound(B[lar].begin(), B[lar].end(), at) - B[lar].begin();
      if(lar_at + 1 == B[lar].size()){
        at = (B[lar][0] + 1) % N;
        break;
      }
      at = B[lar][lar_at + 1] + 1;
      if(at == N){
        at = 0;
        break;
      }
    }
  }
  ll loop_size = start.size();
  K %= loop_size;
  ll ans_start = start[K];

  vector<ll> ans;
  set<ll> used;
  for(ll i = ans_start; i < N; i++){
    if(used.count(A[i])){
      while(true){
        ll ans_end = ans.back();
        ans.erase(ans.end() - 1);
        used.erase(ans_end);
        if(ans_end == A[i]) break;
      }
    }else{
      ans.pb(A[i]);
      used.insert(A[i]);
    }
  }
  rep(i, ans.size()){
    cout << ans[i];
    if(i + 1 == ans.size()) cout << endl;
    else cout << " ";
  }
}

