                            _next[pos[j][k]][i] = make_pair((pos[j][0] + 1)%n,1);
                        }else{
                            _next[pos[j][k]][i] = make_pair((pos[j][k+1] + 1)%n,pos[j][k+1]+1>=n);
                        }
                    }else{
                        auto y = getnext(pos[j][k],i-1);
                        _next[pos[j][k]][i] = make_pair(getnextid(y.first,i-1) , y.second + getroupe(y.first,i-1));
                    }
