int main()
{
  int N;
  long long K;
  std::cin >> N >> K ;
  std::vector<int> an;
  for(int i=0; i<N; i++)
  {
    int a;
    std::cin >> a;
    an.push_back(a);
  }

  std::vector<int> startFromK;
  auto itStart = an.end();
  for(int n=0; n<N+2; n++)
  {
    for(auto it=an.begin(); it!=an.end(); it++)
    {
      if( itStart == an.end() ) { itStart = it; }
      else if(*itStart == *it) { itStart = an.end(); }
    }
    startFromK.push_back(itStart - an.begin());
    if( itStart == an.end() ) { break; }
  }

  int startFrom = startFromK[(K-1) % startFromK.size()];

  std::vector<int> result;
  for(auto it = an.begin() + startFrom; it!=an.end(); it++)
  {
    auto itFound = std::find(result.begin(), result.end(), *it);
    if( itFound==result.end() ) { result.push_back(*it); }
    else { result.resize( itFound-result.begin() ); }
  }

  for(const auto& e:result) { std::cout << e << " "; }
}

