const LL MOD = 1e9+7;

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  LL N, K;
  cin >> N >> K;
  VI as(N);
  cin >> as;

  map<int,int> memo;
  VI tail(N+1);
  tail[N] = N;
  for(int i=N-1;i>=0;--i){
    int a = as[i];
    if(!memo.count(a)){
      tail[i] = i;
    }
    else{
      int ix = memo[a];
      tail[i] = tail[ix+1];
    }
    memo[a] = i;
  }

  memo.clear();
  REP(i,N) if(!memo.count(as[i])) memo[as[i]] = i;

  VI nxt(N+1);
  nxt[N] = 0;
  REP(i,N){
    int ix = tail[i];
    if(ix == N){
      nxt[i] = 0;
    }
    else{
      int a = as[ix];
      nxt[i] = memo[a] + 1;
    }
  }

  --K;
  LL len = 0;
  memo.clear();
  int crt = 0;
  int tm = 0;
  memo[crt] = tm++;
  while(K > 0){
    int ni = nxt[crt];
    if(memo.count(ni)){
      len = tm - memo[ni];
      K %= len;
      break;
    }
    crt = ni;
    memo[crt] = tm++;
    --K;
  }

  while(K > 0){
    int ni = nxt[crt];
    crt = ni;
    --K;
  }

  // simulate
  set<int> s;
  VI ans;
  for(int i=crt;i<N;++i){
    if(!s.count(as[i])){
      s.insert(as[i]);
      ans.PB(as[i]);
    }
    else{
      s.erase(as[i]);
      while(ans.back() != as[i]){
        s.erase(ans.back());
        ans.pop_back();
      }
      ans.pop_back();
    }
  }  
  if(!ans.empty())
    cout << ans << endl;

  return 0;
}

