      if (dob[k][i] == INF) {
        dob[k + 1][i] = INF;
      } else {
        ll tmp = dob[k][i] + dob[k][(i + dob[k][i]) % N];
        dob[k + 1][i] = min(tmp, INF);
      }
    }
  }

  ll t = 0;
  for (int k = 59; k >= 0; --k) {
    if (t + dob[k][t % N] <= N * K) {
      t = t + dob[k][t % N];
    }
  }

  if (t == N * K) { // No more characters.
    cout << endl;
    return 0;
  }

  t %= N;

  while (t < N) {
    if (t + dob[0][t] - 1 > N - 1) { // No more characters same with A[t].
      cout << A[t] << " ";
      ++t;
    } else {
      t = t + dob[0][t];
    }
  }

  return 0;
}

