void construct(const V<ll> &alist, deque<ll> &stack, ll cnts[200005], 
                ll n, ll start_idx)
{
    srep (i, start_idx, n) {
        ll a = alist[i];
        if (cnts[a]) {
            while (cnts[a]) {
                ll popped = stack.back(); stack.pop_back();
                cnts[popped]--;
            }
        }
        else {
            stack.push_back(a);
            cnts[a]++;
        }
    }
}

