		if (!vis[a[i]]) {
			vis[a[i]] = true;
			pos_f[a[i]] = i;
		}
	}
	memset(pre, 0xff, sizeof(pre));
	memset(nxt, 0xff, sizeof(nxt));
	for (int i = 0; i < n; i++) {
		if (pre[a[i]] < 0) {
			pre[a[i]] = i;
		}
		else {
			nxt[pre[a[i]]] = i;
			pre[a[i]] = i;
		}
	}
	memset(vis, 0, sizeof(vis));
	for (int i = 0; i < n; i++) {
