		if (PRE >= 0) {
			V = a[PRE];
			G = pos_f[V] + 1;
		}
		else {
			G = 0;
		}
		if (G >= n) PRE = -1;
		else PRE = from[G];
		if (PRE == n || PRE == -1) break;
	}
	k = k % t;
	G = 0, PRE = from[0];
	for (int i = 1; i <= k; i++) {
		int V;
		if (PRE >= 0) {
			V = a[PRE];
			G = pos_f[V] + 1;
		}
		else {
			G = 0;
		}
