void solve(void)
{
  int n, k;
  cin >> n >> k;
  vector<int> vec(n, 0);
  for (int i = 0; i < n; i++)
  {
    cin >> vec[i];
  }
  vector<vector<int>> vec2(2 * 101010);
  for (int i = 0; i < n; i++)
  {
    vec2[vec[i]].push_back(i);
    vec2[vec[i]].push_back(i + n);
  }
  for (int i = 0; i < n; i++)
  {
    if (vec2[i].empty())
      continue;
    sort(ALL(vec2[i]));
  }

  // DEBUG(vec2);

  vector<int> loop(2 * n, 0);
  // DEBUG(loop);
  // DEBUG(vec2);
  for (int i = 0; i < 2 * 101010; i++)
  {
    // DEBUG(i);
    if (vec2[i].empty())
      continue;
    for (int j = 0; j < vec2[i].size() - 1; j++)
    {
      if (vec2[i][j] >= n)
        break;
      loop[vec2[i][j]] = vec2[i][j + 1] + 1;
    }
  }

  int l = 0;
  int pos = 0;
  while (true)
  {
    int next = loop[pos];
    if (next >= n)
      l++;
    next %= n;
    // DEBUG(pos, next, "\n");
    if (next == 0)
      break;
    pos = next;
  }
  // DEBUG(loop, l);
  k %= l;
  l = 0;
  pos = 0;
  while (true)
  {
    int next = loop[pos];
    if (next >= n)
      l++;
    next %= n;
    // DEBUG(pos, next, "\n");
    if (l >= k)
      break;
    pos = next;
  }
  vector<int> res;
  if (pos == 0)
    return;
  for (int i = pos; i < n; i++)
  {
    res.push_back(vec[i]);
    int lc = res.size();
    for (int j = 0; j < lc - 1; j++)
    {
      int vback = res.back();
      if (vback == res[j])
      {
        // DEBUG(vback);
        while (res.size() > j)
        {
          // DEBUG(res);
          res.pop_back();
        }
        break;
      }
    }
  }

  for (int i = 0; i < res.size(); i++)
  {
    if (i != 0)
      cout << char(32);
    cout << res[i];
  }
  cout << endl;

  return;
}
