int find_num_in_deque(deque<int> deq, int num) {
  auto itr = find(deq.begin(), deq.end(), num);
  size_t index = distance(deq.begin(), itr);
   // 発見したら
  if (index != deq.size()) {
    return index;
  }
  // 発見できなかったら
  else {
    return -1;
  }
}

int main() {
  int n;
  long long k;
  deque<int> s;
  deque<int> t;
  cin >> n >> k;
  int A[n];

  for (int i = 0; i < n; i++) {
    cin >> A[i];
  }
  //繰り返しのパターンを見つける
  int cnt_till_emp = 0;
  for (int j = 0; j < k; j++) {
    for (int i = 0; i <= n-1; i++) {
      int idx = find_num_in_deque(s, A[i%n]);
      if (idx == -1) {
        //cout << "push" << endl;
        s.push_front(A[i%n]);
      } else {
        //cout << "pop" << endl;
        while(idx >= 0) {
          s.pop_front();
          idx--;
        }
      }
    }
    cnt_till_emp++;
    if (s.empty()) {
      break;
    }
  }
  //cout << "cnt: " << cnt_till_emp << endl;
  //cnt_till_empごとに繰り返されるので、kを割った余りまで操作実施すれば良い
  if (cnt_till_emp >= k){
    cnt_till_emp = k;
  } else {
    cnt_till_emp = k % cnt_till_emp;
  }
  for (int i = 0; i <= (cnt_till_emp)*n-1; i++) {
    int idx = find_num_in_deque(t, A[i%n]);
    if (idx == -1) {
      //cout << "push" << endl;
      t.push_front(A[i%n]);
    } else {
      //cout << "pop" << endl;
      while(idx >= 0) {
        t.pop_front();
        idx--;
      }
    }
  }


  int a;
  while(!t.empty()) {
    a = t.back();
    t.pop_back();
    cout << a << ' ';
  }
  cout << endl;
  return 0;
}

