const int MAXN = (int)2e5 + 77;
const int MAXLOG = 61;

int a[MAXN], n;
int lst[MAXN], R[MAXN], fst[MAXN];
ll k;

ll add[MAXLOG][MAXN];
ll go[MAXLOG][MAXN];

void solve() {
	cin >> n >> k;

	for(int i = 0; i < MAXN; ++i) {
		lst[i] = NIL;
		fst[i] = NIL;
	}

	for(int i = 0; i < n; ++i) {
		cin >> a[i];

		if(fst[a[i]] == NIL) {
			fst[a[i]] = i;
		}
	}

	for(int i = n - 1; i >= 0; --i) {
		R[i] = lst[a[i]];
		lst[a[i]] = i;
	}

	for(int i = 0; i < n; ++i) {
		int j = (R[i] == NIL ? fst[a[i]] + n : R[i]);

		go[0][i] = (j + 1) % n;
		add[0][i] = j - i + 1;
	}

	for(int log = 1; log < MAXLOG; ++log) {
		for(int i = 0; i < n; ++i) {
			int i2 = go[log - 1][i];
			go[log][i] = go[log - 1][i2];
			add[log][i] = add[log - 1][i] + add[log - 1][i2];

			if(add[log][i] > LL_INF) {
				add[log][i] = LL_INF;
			}
		}
	}

	ll cur = 0, pref = 0;

	for(int log = MAXLOG - 1; log >= 0; --log) {
		if(cur + add[log][pref] <= n * k) {
			cur += add[log][pref];
			pref = go[log][pref];
		}
	}

	/*while(cur + add[0][pref] <= n * k) {
		cur += add[0][pref];
		pref = go[0][pref];
	}*/

	DBG(cur); DBG(pref);
	vector<int> answ;
	set<int> setik;

	for(; cur < n * k; pref = (pref + 1) % n, ++cur) {
		if(setik.count(a[pref])) {
			while(answ.back() != a[pref]) {
				setik.erase(answ.back());
				answ.pop_back();
			}

			setik.erase(answ.back());
			answ.pop_back();
		} else {
			setik.insert(a[pref]);
			answ.push_back(a[pref]);
		}
	}

	cout << answ << '\n';
}	

int main() {
	fast_io();
	solve();

	return 0;
}

