    ll s = v[(cnt - (K % cnt)) % cnt];
    deque<ll> ans;
    FOR(i, N, s) {
        ll n = A[i];
        if (U[n]) {
            while (!ans.empty()) {
                ll m = ans.back();
                ans.pop_back();
                if (m == n)
                    break;
            }
            U[n] = false;
            continue;
        }
        U[n] = true;
        ans.push_back(n);
    }

    while (!ans.empty()) {
        ll n = ans.front();
        ans.pop_front();
        cout << n << " ";
    }
    cout << endl;
    return 0;
}

