		ck[cur]=len;
		//printf("cur:%d, len:%lld, j:%d\n", cur, len);
		cur=(j+1)%n;
		if(ck[cur]) {
			break;
		}
	}
	for(i=0;i!=cur;i=(i+ck[i])%n) {
		if(k<=ck[i]) {
			if(k==0||k==ck[i]) return 0;
			vector<int> ans;
			while(k--) {
				if(vis[a[i]]) {
					while(ans.back()!=a[i]) { 
						vis[ans.back()]=false;
						ans.pop_back();
					}
					ans.pop_back();
					vis[a[i]]=false;
				} else {
					ans.push_back(a[i]);
					vis[a[i]]=true;
				}
				i=(i+1)%n;
			}
			for(auto& it : ans) printf("%d ", ans);
			return 0;
		}
		k-=ck[i];
	}
	ll sum = 0;
	while(1) {
		sum+=ck[i];
		i=(i+ck[i])%n;
		if(i==cur) break;
	}
	k%=sum;
	if(k==0) return 0;
	while(1) {
		for(;;i=(i+ck[i])%n) {
			if(k<=ck[i]) {
				if(k==0||k==ck[i]) return 0;
				vector<int> ans;
				while(k--) {
					if(vis[a[i]]) {
						while(ans.back()!=a[i]) {
							vis[ans.back()]=false;
							ans.pop_back();
						}
						assert(ans.back()==a[i]);
						ans.pop_back();
						vis[a[i]]=false;
					} else {
						ans.push_back(a[i]);
						vis[a[i]]=true;
					}
					i=(i+1)%n;
				}
				for(auto& it : ans) printf("%d ", it);
				return 0;
			}
			k-=ck[i];
		}
	}
	return 0;
}

