typedef long long ll;

ll N, K;
ll A[200010];
ll nxt[64][200010], over[64][200010];
ll pre[200010];

int main()
{
    cin >> N >> K;
    for(int i = 0; i < N; i++)cin >> A[i];

    for(int i = 0; i < 2 * N; i++)
    {
        if(pre[A[i % N]] == 0)pre[A[i % N]] = i + 1;
        else
        {
            int idx = (pre[A[i % N]] - 1) % N;
            nxt[0][idx] = (i + 1) % N;
            over[0][idx] = ((pre[A[i % N]] - 1 < N && i + 1 >= N) | (i + 1) % N == 0) ? 1 : 0;
            pre[A[i % N]] = i + 1;
        }
    }

    for(int i = 1; i < 64; i++)
    {
        for(int j = 0; j < N; j++)
        {
            nxt[i][j] = nxt[i - 1][nxt[i - 1][j]];
            over[i][j] = over[i - 1][j] + over[i - 1][nxt[i - 1][j]];
        }
    }

    ll l = 0, r = 1LL << 64;
    ll mem;
    for(int i = 0; i < 64; i++)
    {
        ll mid = (l + r) / 2;
        ll now = 0, cnt = 0;
        for(int j = 0; j < 64; j++)if(mid & (1LL << j))
        {
            cnt += over[j][now];
            now = nxt[j][now];
        }
        if(K - 1 == cnt)
        {
            mem = now;
            break;
        }
        if(cnt < K - 1)l = mid;
        else r = mid;
    }

    int bit[200010] = {0};
    vector<int> ans;
    for(int i = mem; i < N; i++)
    {
        if(bit[A[i]])
        {
            while(ans.back() != A[i])
            {
                bit[ans.back()] ^= 1;
                ans.pop_back();
            }
            bit[ans.back()] ^= 1;
            ans.pop_back();
        }
        else
        {
            bit[A[i]] ^= 1;
            ans.push_back(A[i]);
        }
    }

    for(int i = 0; i < ans.size(); i++)
    {
        cout << ans[i];
        if(i != ans.size())cout << " ";
    }
    cout << endl;

    return 0;
}

