    k=(k*n)%cnt;
    while(true) {
        ll new_idx=*upper_bound(all(mp[num]),idx);
        if(k-(new_idx-idx)<=0) break;
        k-=new_idx-idx+1;
        idx=(new_idx+1)%n;
        num=a[idx];
    }

    vector<ll> ans;
    map<ll,bool> used;
    rep(i,k) {
        ll now=a[(idx+(ll)i)%n];
        if(!used[now]) {
            used[now]=true;
            ans.push_back(now);
        }
        else {
            while(true) {
                ll x=ans.back();
                ans.pop_back();
                if(x==now) break;
            }
        }
    }

    for(ll x:ans) cout<<x<<endl;
}

