long long N, K;

vector<int> calc_to(vector<int> &A, int l) {
    vector<int> to((int)A.size(), -1);
    map<int, int> prev;
    for (int i=l; i<2*N; ++i) {
        if (prev.count(A[i%N])) {
            int k = prev[A[i%N]];
            to[k] = i%N;
        }
        prev[A[i%N]] = i%N;
    }
    return to;
}

int main(){
