    vector<int> A(N);
    for (int i=0; i<N; ++i) cin >> A[i];

    if (N == 1) {
        if (K % 2 == 0) return 0;
        cout << A[0] << endl;
        return 0;
    }

    vector<int> to = calc_to(A, 0);
    vector<int> pos;
    int k = 0;
    while (1) {
        while (k < to[k] % N && to[k]+1 < N) {
            k = to[k]+1;
        }
        pos.push_back(k);
        if (k == N-1 && to[k] == N-1) pos.push_back(N);
        k = (to[k]+1) % N;
        if (k == 0) break;
    }

    int M = pos.size();
    K = K % M;
    if (K == 0) return 0;

    int s = pos[K-1];
    vector<int> ans;
    while (s < N) {
        if (s < to[s]) {
            s = to[s];
        } else {
            ans.push_back(A[s]);
        }
        s ++;
    }

    for (int i=0; i<(int)ans.size(); ++i) {
        cout << (i == 0 ? "" : " ") << ans[i];
    }
    cout << endl;

    return 0;
}

