using namespace std;
using ll = long long;
const ll INF = 0xfffffffffffffff;


int main() {
  ll n, k;
  cin >> n >> k;
  vector<ll> a(n);
  for(auto& i : a) cin >> i;
  vector<ll> at(200001); // at[i] = 次に出てくる i の位置
  for(ll i = n - 1; i >= 0; i--) at[a[i]] = i + n;
  vector<vector<ll>> next(50, vector<ll>(n, INF));
  // next[0][i] = s の先頭が X[i] のとき 次に s が空になるときの X の位置,
  // つまり X[i] == X[j] である i より大きい最小の j
  for(ll i = n - 1; i >= 0; i--) {
    next[0][i] = at[a[i]];
    at[a[i]] = i;
  }
  // next[i][j] = s の先頭が X[j] のときから 2^i 回 s が空になったときの X の位置,
  // つまり (X[j] のときから 2^{i - 1} 回 s が空になったときの X の位置) から 2^{i - 1} 回 s が空になったときの X の位置
  for(ll i = 1; i < 50; i++) {
    for(ll j = 0; j < n; j++) {
      next[i][j] = next[i - 1][(next[i - 1][j] + 1) % n] + (next[i - 1][j] + 1) / n * n; // % n で減った分を足す
      if(next[i][j] > INF) next[i][j] = INF; // オーバーフロー注意
    }
  }
  // 空になった最後の位置を求める
  ll last = -1;
  for(ll i = 49; i >= 0; i--) {
    ll at = next[i][(last + 1) % n] + (last + 1) / n * n;
    assert(at>0);
    if(at < n * k) last = at;
  }
  vector<ll> ans;
  vector<bool> in(200001);
  for(ll i = last + 1; i < n * k; i++) {
    if(in[a[i % n]]) {
      while(ans.back() != a[i % n]) {
        in[ans.back()] = false;
        ans.pop_back();
      }
      in[ans.back()] = false;
      ans.pop_back();
    }
    else {
      in[a[i % n]] = true;
      ans.push_back(a[i % n]);
    }
  }
  for(ll i = 0; i < ans.size(); i++) cout << ans[i] << " \n"[i + 1 == ans.size()];
}

