using namespace std;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N, K;
    cin >> N >> K;
    vector<ll> A(N);
    map<ll, vector<ll>> idx;
    Rep (i, N) {
        cin >> A[i];
        idx[A[i]].push_back(i);
    }
    vector<ll> w(N);
    for (auto kv : idx) {
        ll s = kv.second.size();
        kv.second.push_back(kv.second[0] + N);
        Rep (i, s) {
            w[kv.second[i]] = kv.second[i+1] - kv.second[i] + 1;
        }
    }

    vector<vector<ll>> a(100, vector<ll>(N, 0));
    a[0] = w;
    const ll LL_MAX = 1e18;
    Rep (i, 99) {
        Rep (j, N) {
            a[i+1][j] = a[i][j] + a[i][(j+a[i][j]) % N];
            a[i+1][j] = min(a[i+1][j], LL_MAX);
        }
    }

    ll now = 0;
    while (now <= N*K - 1) {
        ll to_go = N*K - 1 - now;
        for (ll i = 99; i >= 0; i--) {
            if (a[i][now % N] <= to_go) {
                now += a[i][now % N];
                break;
            }
        }
        if (a[0][now % N] > to_go) break;
    }

    vector<bool> exist(2e5+1, false);
    deque<ll> d;
    for (ll i = now % N; i < N; i++) {
        if (!exist[A[i]]) {
            d.push_back(A[i]);
            exist[A[i]] = true;
        } else {
            while (true) {
                ll t = d.back();
                d.pop_back();
                exist[t] = false;
                if (A[i] == t) break;
            }
        }
    }

    for (ll e : d) {
        cout << e << " ";
    }
    cout << "\n";
}

