    rep(i, idx.size())
    {
        int m = idx[i].size();
        rep(j, m)
        {
            p[idx[i][j]] = (idx[i][(j + 1) % m] - idx[i][j] + 1 + n) % n;
        }
    }
    rep(i, n)
    {
        if (p[i] == 1) {
            p[i] = n + 1;
        }
    }

    UFTree uft(n);
    rep(i, n)
    {
        uft.merge(i, (i + p[i]) % n);
    }
    int64_t T = 0;
