const ll inf = 2e18;
const int L = 61;
const int N = 2e5 + 15;
int n, k, a[N], g[L][N], last[N], first[N];
bool used[N];
vector <int> ans;

main() {
    ios_base::sync_with_stdio(0); cout.tie(0); cin.tie(0);
    fill(last, last + N, -1);
    fill(first, first + N, -1);
    cin >> n >> k;
    for(int i = 0; i < n; ++i) {
        cin >> a[i];
        if(first[a[i]] == -1)
            first[a[i]] = i;
