        g[0][i] = last[a[i]] - i + 1;
        last[a[i]] = i;
    }
    for(int i = 1; i < L; ++i)
        for(int j = 0; j < n; ++j)
            g[i][j] = min(inf, g[i-1][j] + g[i-1][(j + g[i-1][j]) % n]);
    int j = 0;
    for(int i = L - 1; i >= 0; --i)
        if(g[i][j % n] + j <= n * k)
            j += g[i][j % n];
    for(int i = j % n; i < n; ++i) {
        if(!used[a[i]]) {
            ans.pb(a[i]);
            used[a[i]] = true;
        }
        else
            while(used[a[i]]) {
                used[ans.back()] = false;
                ans.ppb();
            }
    }
    for(int i : ans)
        cout << i << ' ';
    return 0;
}

