  const u64 k = scan<u64>();
  std::vector<usize> a;
  a.reserve(n);
  std::copy_n(std::istream_iterator<usize>(std::cin), n, std::back_inserter(a));

  using p = std::vector<usize>;

  p sigma(n);

  std::map<usize, usize> last;

  for (const auto i : revrep(0_z, n)) {
    last[a[i]] = i;
  }

  for (const auto i : revrep(0_z, n)) {
    if (last[a[i]] + 1_z == n) {
      sigma[i] = 0_z;
    } else if (last[a[i]] <= i) {
      sigma[i] = last[a[i]] + 1_z;
    } else {
      sigma[i] = sigma[last[a[i]] + 1_z];
    }
    last[a[i]] = i;
  }

  const auto cu = power(sigma, k - static_cast<u64>(1),
                        [](const p &l, const p &r) {
                          p ret(l.size());
                          for (const auto i : rep(0_z, l.size())) {
                            ret[i] = r[l[i]];
                          }
                          return ret;
                        },
                        [n]() {
                          p ret(n);
                          std::iota(ret.begin(), ret.end(), 0_z);
                          return ret;
                        }());
  const usize fst = cu[0_z];

  std::set<usize> set;
  std::vector<usize> ans;
  for (const auto i : rep(fst, n)) {
    if (set.count(a[i])) {
      while (ans.back() != a[i]) {
        set.erase(ans.back());
        ans.pop_back();
      }
      set.erase(ans.back());
      ans.pop_back();
    } else {
      ans.push_back(a[i]);
      set.insert(a[i]);
    }
  }

  for (const auto e : ans) {
    std::cout << e << " ";
  }
}

