const int N = (int)2e5 + 5, LOG = 61;
int n, a[N], nxt[N][LOG];
ll cost[N][LOG];
bool ex[N];
map<int, int> lst;
vector<int> ans;
ll K;

int32_t main () {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

//    freopen("test.INP", "r", stdin);

    cin >> n >> K; --K;
    for (int i = 0; i < n; ++i) cin >> a[i];

    for (int i = n - 1; i >= 0; --i) {
        if (lst.count(a[i]) ) nxt[i][0] = lst[ a[i] ];
        else nxt[i][0] = -1;
        lst[ a[i] ] = i;
    }

    for (int i = 0; i < n; ++i) {
        if (nxt[i][0] == -1) nxt[i][0] = lst[ a[i] ];
        if (nxt[i][0] <= i) cost[i][0] = 1;
    }

    for (int j = 1; j < LOG; ++j) {
        for (int i = 0; i < n; ++i) {
            nxt[i][j] = nxt[ (nxt[i][j - 1] + 1) % n ][j - 1];
            cost[i][j] = cost[i][j - 1] + cost[ (nxt[i][j - 1] + 1) % n ][j - 1] + (nxt[i][j - 1] == n - 1);
        }
    }

    int cur = 0;
    for (int i = LOG - 1; i >= 0; --i) if (cost[cur][i] <= K) {
        K -= cost[cur][i];
        cur = nxt[cur][i];
        if (cur == n - 1) --K;
        cur = (cur + 1) % n;
    }

    if (K < 0) return 0;

    for (int i = cur; i < n; ++i) {
        if (ex[ a[i] ]) {
            while (ans.back() != a[i]) {
                ex[ans.back()] = 0;
                ans.pop_back();
            }
            ex[ans.back()] = 0;
            ans.pop_back();
        }
        else {
            ans.push_back(a[i]);
            ex[ a[i] ] = 1;
        }
    }

    for (int _ : ans) cout << _ << ' '; cout << '\n';

    return 0;
}

