vector<int> naive_solve(long long N, long long K, std::vector<long long> A) {

    set<int> C;

    vector<int> S;

    for (int i = 0; i < N * K; i++) {
        if (C.count(A[i % N])) {
            while (true) {
                int v = S.back();
                C.erase(v);
                assert(S.size() > 0);
                S.pop_back();

                if (v == A[i % N]) break;
            }

        } else {
            S.push_back(A[i % N]);
            C.insert(A[i % N]);
        }
    }
    return S;
}

