        if (perm[i][p].second <= V) {
            V -= perm[i][p].second;
            p = perm[i][p].first;
            i++;
        }
    }
    return V;
}

vector<int> solve(long long N, long long K, std::vector<long long> A) {
    if (K < 3) {
        return naive_solve(N, K, A);
    }

    AA = A;
    memset(dp, -1, sizeof(dp));
    for (int i = 0; i < 200010; i++) B[i].clear();
    for (int i = 0; i < 2 * N; i++) {
        B[A[i % N]].push_back(i);
    }

    vector<vector<pair<long long, long long>>> perm(40, vector<pair<long long, long long>>(N));

    for (int i = 0; i < N; i++) {
        perm[0][i] = {nxt(i) % N, nxt(i) - i};
    }

    for (int i = 1; i < 40; i++) {
        for (int j = 0; j < N; j++) {
            perm[i][j] = {
                    perm[i - 1][perm[i - 1][j].first].first,
                    perm[i - 1][j].second + perm[i - 1][perm[i - 1][j].first].second
            };
        }
    }
//    cout << "====" << endl;
//    for(int i = 0 ; i < N ; i++){
//        cout << i << ":";
//        cout << perm[0][i].first << " " << perm[0][i].second << "(" << nxt(i);
//        cout << endl;
//    }

    auto lst = apply(N, K, perm);
    vector<long long> real;

    for (int i = N - lst; i < N; i++) real.push_back(A[i]);

    return naive_solve(real.size(), 1, real);


}


