void make_table() {

    for (int i = n * 2 - 1; i >= 0; i--) {
        table[i%n][0] = pre[a[i%n]] - i + 1;
        pre[a[i%n]] = i;
    }

    for (int i = 1; i < 66; i++) {
        for (int j = 0; j < n; j++) {
            table[j][i] = table[j][i-1] + table[(table[j][i-1] + j) % n][i-1];
            table[j][i] = min(table[j][i], (1LL << 61));
        }
    }

}

void solve() {
    make_table();
    ll pos = 0;
    ll left = n * k;
    // for (int i = 0; i < 64; i++) {
    //     for (int j = 0; j < n; j++) {
    //         cout << table[j][i] << " ";
    //     }
    //     cout << endl;
    // }
    for (int i = 65; i >= 0; i--) {
        if (left >= table[pos][i]) {
            left -= table[pos][i];
            pos += table[pos][i];
            pos %= n;
        }
    }

    vector<int> v;
    while (left--) {
        if (!inque[a[pos]]) {
            v.push_back(a[pos]);
            inque[a[pos]] = 1;
        } else {
            while (inque[a[pos]]) {
                inque[v[v.size() - 1]] = 0;
                v.pop_back();
            }
        }
        pos++;
        pos %= n;
    }

    for (int i = 0; i < v.size(); i++) {
        cout << v[i] << " \n"[i == v.size() - 1];
    }
}

