struct node{
    int idx;
    int next_idx;
    pair <int, int> get_next_same_num_idx(){
        int loop_added = 0;
        if (next_idx <= idx){
            loop_added = 1;
        }
        return {next_idx, loop_added};
    }
};


int main(void){
    ll n; cin >> n;
    ll k; cin >> k;
    vector <int> as;
    int a;
    REP(i, n){
        cin >> a;
        as.push_back(a);
    }
    dumparr(as)
    vector <vector <int>> matrix;
    REP(i, 2*1e5 + 1){
        vector <int> v; matrix.push_back(v);
    }
    REP(i, n){
        matrix[as[i]].push_back(i);
    }
    map <int, int> amap;
    vector <node> nodes;
    REP(i, n){
        int num = as[i];
        int cnt = matrix[num].size();
        int next_idx = matrix[num][(cnt + amap[num] + 1) % cnt];
        nodes.push_back({i, next_idx});
        amap[num]++;
    }

    int loop_cnt = 0;
    int idx = 0;
    while (1){
        pair<int, int> p = nodes[idx].get_next_same_num_idx();
        if (p.first == n-1){
            loop_cnt++;
            break;
        } else {
            loop_cnt += p.second;
            idx = p.first + 1;
        }
    }
    dump(loop_cnt)
    dump(n)
    dump(k)
    ll nk = n*k;
    nk = nk % (loop_cnt*n);

    loop_cnt = 0;
    idx = 0;
    node prev_node = nodes[n-1];
    while (loop_cnt*(n+1) + idx < nk){
        prev_node = nodes[idx];
        pair<int, int> p = nodes[idx].get_next_same_num_idx();
        if (p.first == n-1){
            exit(1);
