      nxt[i] = n - i + 1 + f[a[i]];
    }else{
      nxt[i] = lst[a[i]] - i + 1;
    }
    lst[a[i]] = i;
  }
  forn(i, 1, n) up[i][0] = nxt[i];
  forn(lvl, 1, 60){
    forn(i, 1, n){
      int x = convert(up[i][lvl - 1] + i);
      up[i][lvl] = min(200000000000000001ll, up[i][lvl - 1] + up[x][lvl - 1]);
      //cout << i << " " << lvl << " " << up[i][lvl] << " " << x << " " << endl;
    }
  }
  int cur = 1, pos = 1;
  forev(i, 60, 0){
    if(cur + up[pos][i] <= n * k){
      cur += up[pos][i];
      pos = convert(pos + up[pos][i] % n);
    }
  }
  vi v;
  forn(i, cur, n * k){
    int x = a[convert(i)];
    if(was[x]){
      while(v.back() != x) v.pop_back();
      v.pop_back();
      was[x] = 0;
    }else{
      was[x] = 1;
      v.pb(x);
    }
  }
  for(auto x : v) cout << x << " ";
}

