	for (int i = 0; i < C; i++) {
		for (int j = 0; j < len(where[i]); j++) {
			int from = where[i][j];
			int to = where[i][(j + 1) % len(where[i])];
			if (to <= from) to += n;
			go[0][from] = mp((to + 1) % n, to + 1 - from);
		}
	}
	for (int k = 1; k < P; k++) {
		for (int i = 0; i < n; i++) {
			go[k][i] = mp(go[k - 1][go[k - 1][i].x].x,
				min(go[k - 1][i].y + go[k - 1][go[k - 1][i].x].y, (ll)3e17));
		}
	}
	int jump = n * k;
	int cur = 0;
	for (int p = P - 1; p > -1; p--) {
		while (jump - n >= go[p][cur].y) {
			jump -= go[p][cur].y;
			cur = go[p][cur].x;
		}
