using namespace std;

const int MAXN = 2e5;

int last[MAXN + 1];

int main() {
    //ifstream cin("B.in");
    //ofstream cout("B.out");
    int i, n;
    ll k;
    ios::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    cin >> n >> k;

    vector <int> a(n + 1);
    for(i = 1; i <= n; i++) {
        cin >> a[i];
    }

    vector < vector <int> > nxt(n + 2, vector <int>(20));
    for(i = n; i >= 1; i--) {
        nxt[i][0] = last[a[i]];
        if(nxt[i][0] != 0) {
            nxt[i][0]++;
        }
        last[a[i]] = i;
    }

    for(int bit = 1; bit < 20; bit++) {
        for(i = 1; i <= n; i++) {
            nxt[i][bit] = nxt[nxt[i][bit - 1]][bit - 1];
        }
    }

    vector < vector <int> > anc(n + 2, vector <int>(60));

    for(i = 1; i <= n; i++) {
        int cur = i;
        for(int bit = 19; bit >= 0; bit--) {
            if(nxt[cur][bit] != 0) {
                cur = nxt[cur][bit];
            }
        }
        if(cur == n + 1) {
            anc[i][0] = 1;
        }
        else {
            anc[i][0] = last[a[cur]] + 1;
        }
    }
    anc[n + 1][0] = 1;

    for(int bit = 1; bit < 60; bit++) {
        for(i = 1; i <= n + 1; i++) {
            anc[i][bit] = anc[anc[i][bit - 1]][bit - 1];
        }
    }

    int pos = 1;
    k--;
    for(int bit = 0; bit < 60; bit++) {
        if(k & (1LL << bit)) {
            pos = anc[pos][bit];
        }
    }


    stack <int> stk;
    fill(last, last + MAXN + 1, 0);

    for(i = pos; i <= n; i++) {
        if(last[a[i]] == 0) {
            stk.push(a[i]);
            last[a[i]] = 1;
        }
        else {
            while(last[a[i]] == 1) {
                last[stk.top()] = 0;
                stk.pop();
            }
        }
    }

    vector <int> sol;
    while(stk.size()) {
        sol.push_back(stk.top());
        stk.pop();
    }

    reverse(sol.begin(), sol.end());
    for(auto it : sol) {
        cout << it << " ";
    }

    //cin.close();
    //cout.close();
    return 0;
}

