{
	cin >> n >> k;
	for(int i = 0; i < n; i++)
	{
		cin >> arr[i];
	}
	for(int i = 0; i < N; i++)
	{
		fo[i]=-1;
	}
	f[n]=mp(0, n);
	for(int i = n-1; i >= 0; i--)
	{
		if(fo[arr[i]]==-1)
		{
			f[i]=mp(arr[i], i);
		}
		else
		{
			f[i]=f[fo[arr[i]]+1];
		}
		fo[arr[i]]=i;
	}
	int cnt=1, curr=0;
