using namespace std;

using ll = long long;

const int MAXV = 200000;

// 1 3 1 2 3 2 3

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    ll K;
    cin >> n >> K;
    vector<int> a(n);
    vector<int> conv(n, -1);
    vector<int> prv(MAXV + 1, -1);
    vector<int> fst(MAXV + 1, -1);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        if (prv[a[i]] == -1) {
            prv[a[i]] = i;
            fst[a[i]] = i;
        } else {
            conv[prv[a[i]]] = i;
            prv[a[i]] = i;
        }
    }

    if (n == 1) {
        if (K % 2 == 1) cout << a[0] << "\n";
        return 0;
    }

    for (int i = 1; i <= MAXV; i++) {
        if (fst[i] == -1) continue;
        conv[prv[i]] = fst[i];
    }

    vector<int> ans;
    int cur = 0;
    ll foobar = 0;
    while (K) {
        int nex = (conv[cur] + 1) % n;
        if (cur > nex) {
            K--;
            foobar++;
            if (K == 0 && cur == conv[cur]) ans.push_back(a[cur]); 
        } else if (cur == conv[cur]) {
            if (K > 1) {
                K--;
                foobar++;
            } else {
                ans.push_back(a[cur]);
            }
        }

        if (nex == 0 && foobar >= 0) {
            //cerr << "foobar: " << foobar << endl;
            K %= foobar;
            foobar = -1000000000000000LL;
        }
        if (K == 0) {
            if (cur < nex) cur = nex;
            if (nex == 0) cur = n;
            break;
        }
        cur = nex;
    }
    //cerr << cur << endl;
    for (int i = cur; i < n; i++) {
        ans.push_back(a[i]);
    }

    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i] << " \n"[i + 1 == ans.size()];
    }
    return 0;
}

