using namespace std;

struct Monoid {
  using T = int; // type or class of monoid
  static T operate(const T& left, const T& right) {
    if (left != -1) return left;
    else return right;
  }
  static constexpr T identity() { return T(-1); } // 単位元
};

struct M_act {
  using T = int;
  using OperatorMonoid = Monoid;
  static T act(const OperatorMonoid::T& m, const T& a) {
    if (m != -1) return m;
    else return a;
  }
};

template<class M_act>
class SegTree {
private:
  using T = typename M_act::T;
  using OM = typename M_act::OperatorMonoid;
  using M = typename OM::T;
  const int n, h;
  std::vector<T> uv; // underlying values
  std::vector<M> deferred_action;

  void propagate(const M& m, int i) {
    if (i < n) deferred_action[i] = OM::operate(m, deferred_action[i]); // if not leaves, unite actions
    else {
      i -= n;
      uv[i] = M_act::act(m, uv[i]); // if leaves, act immediately
    }
  }

  void propagate_from(int i) {
    if (deferred_action[i] == OM::identity()) { return; }
    propagate(deferred_action[i], i << 1);
    propagate(deferred_action[i], i << 1 | 1);
    deferred_action[i] = OM::identity();
  }

  void propagate_to_uv(int i) {
    i += n;
    for (int j = h; j > 0; --j) propagate_from(i >> j);
  }

  int lg(int n_) {
    n_ -= 1;
    int h_ = 0;
    while (n_ >> h_) ++h_;
    return h_;
  }

public:
  SegTree(int n_, const T& x) : n(n_), h(lg(n)), uv(n, x), deferred_action(n, OM::identity()) {}
  SegTree(const std::vector<T>& v) : n(v.size()), h(lg(n)), uv(v), deferred_action(n, OM::identity()) {}
  template<class Itr>
  SegTree(Itr first, Itr last) : n(std::distance(first, last)), h(lg(n)), uv(first, last), deferred_action(n, OM::identity()) {}

  void act(int l, int r, const M& m) {
    propagate_to_uv(l);
    propagate_to_uv(r-1);
    l += n, r += n;
    for ( ; l < r; l >>= 1, r >>= 1) {
      if (l & 1) propagate(m, l++);
      if (r & 1) propagate(m, r-1);
    }
  }

  void propagate_all() {
    for (int i = 1; i < n; ++i) propagate_from(i);
  }

  void set(int i, const T& x) {
    propagate_to_uv(i);
    uv[i] = x;
  }

  T get(int i) {
    T ret = uv[i];
    i += n;
    while (i >>= 1) ret = M_act::act(deferred_action[i], ret);
    return ret;
  }

  std::vector<T> get_v() {
    return uv;
  }
};

int main() {
  int n;
  ll k;
  scan(n, k);
  vi a(n);
  scan(a);
  int m = 0;
  rep (i, n) {
    m = max(m, a[i]);
  }
  m += 1;
  vvi indices(m);
  rep (i, n) {
    indices[a[i]].push_back(i);
  }


  vi remain(n+1, n);
  {
    vi wolfi;
    vi lefti;
    set<int> si;
    for (int i = n-1; i >= 0; --i) {
      if (si.find(a[i]) == end(si)) {
        wolfi.push_back(i);
        si.insert(a[i]);
      }
    }
    reverse(all(wolfi));

    for (int ind : wolfi) {
      int lb = lower_bound(all(indices[a[ind]]), ind) - begin(indices[a[ind]]);
      if (lb == 0) {
        lefti.push_back(0);
      } else {
        lefti.push_back(indices[a[ind]][lb - 1] + 1);
      }
    }


    int sz = wolfi.size();
    auto segt = SegTree<M_act>(n, n);
    for (int i = sz-1; i >= 0; --i) {
      remain[wolfi[i]] = wolfi[i];
    }

    for (int i = n-1; i >= 0; --i) {
      if (remain[i] != n) {
        continue;
      }
      auto ub = upper_bound(all(indices[a[i]]), i);
      assert (ub != end(indices[a[i]]));
      remain[i] = remain[(*ub) + 1];
    }

  }

  vi first_index(m, -1);
  rep (i, n) {
    if (first_index[a[i]] == -1) {
      first_index[a[i]] = i;
    }
  }


  int t;
  int prev = -1; // first index remaining
  vi prevs;
  for (int i = 1; true; ++i) {
    t = i;
    if (prev == -1) {
      prev = remain[0];
    } else {
      int fi = first_index[a[prev]];
      prev = remain[fi + 1];
    }
    prevs.push_back(prev);

    if (prev == n) {
      break;
    }
  }


  int target = k % t;
  if (target == 0) {
    return 0;
  }

  int start_index;
  if (target == 1) {
    start_index = 0;
  } else {
    int prev = prevs[target - 2];
    start_index = first_index[a[prev]] + 1;
  }
  vi ans;
  for (int i = start_index; ; ) {
    if (remain[i] == n) {
      break;
    }
    ans.push_back(remain[i]);
    i = remain[i] + 1;
  }

  int sz = ans.size();
  rep (i, sz) {
    printf("%d%c", a[ans[i]], " \n"[i == sz-1]);
  }

  return 0;
}

