#define FOR(i, begin, end) for(int i=(begin),i##_end_=(end);i<i##_end_;i++)
#define IFOR(i, begin, end) for(int i=(end)-1,i##_begin_=(begin);i>=i##_begin_;i--)
#define REP(i, n) FOR(i,0,n)
#define IREP(i, n) IFOR(i,0,n)
constexpr int MOD = 1000000007;
int main()
{
    int N;
    lint K;
    cin >> N >> K;
    vector<int> X(N);
    REP(i, N) cin >> X[i];
    vector<int> first(200001, -1);
    REP(i, N) {
        if(first[X[i]] == -1) first[X[i]] = i;
    }
    vector<int> next(N+1, -1);
    vector<int> bef(N+1, -1);
    vector<int> tmp(200001, -1);
    REP(i, N) {
        if(tmp[X[i]] != -1) {
            bef[i+1] = tmp[X[i]];
        }
        tmp[X[i]] = i;
    }
    IREP(i, N) {
        int be = i+1;
        while(true) {
            if(bef[be] != -1 && next[bef[be]] < i+1) {
                next[bef[be]] = i+1;
                be = bef[be];
            } else {
                break;
            }
        }
    }
    REP(i, N+1) {
        if(next[i] == -1) {
            next[i] = i;
        }
    }

    vector<int> y;
    y.push_back(0);
    while(true) {
        int idx = y[y.size()-1];
        if(next[idx] == N) break;
        idx = first[X[next[idx]]]+1;
        y.push_back(idx);
    }
    int p = y.size();
    int z = (K-1) % p;
    vector<int> ans(N, -1);
    int aidx = 0;
    vector<int> tmp2(200001, -1);
    FOR(i, y[z], N) {
        if(tmp2[X[i]] != -1 && tmp2[X[i]] < aidx) {
            aidx = tmp2[X[i]];
            tmp2[X[i]] = -1;
        } else {
            tmp2[X[i]] = aidx;
            ans[aidx] = X[i];
            aidx++;
        }
    }
    REP(i, aidx) cout << ans[i] << (i!=aidx-1 ? " " : "");
    cout << endl;
}

