using namespace std;

typedef long long ll;

ll P[66][202020], L[66][202020];
ll A[404040], C[202020];
vector <ll> S;
ll n, k;

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(NULL);

	ll i, j, l, p;

	cin >> n >> k;

	for(i=0; i<n; i++){
		cin >> A[i];
		A[n + i] = A[i];
	}

	for(i=n+n-1; i>=0; i--){
		if(i < n){
			P[0][i] = (C[A[i]] + 1) % n;
			L[0][i] = C[A[i]] - i + 1;
		}
		C[A[i]] = i;
	}

	for(i=1; i<60; i++){
		for(j=0; j<n; j++){
			P[i][j] = P[i - 1][P[i - 1][j]];
			L[i][j] = L[i - 1][j] + L[i - 1][P[i - 1][j]];
		}
	}

	for(l=0, p=0; l<n*k; ){
		for(i=59; i>=0 && l<n*k; i--){
			if(l + L[i][p] <= n * k){
				l += L[i][p];
				p = P[i][p];
			}
		}
		if(l == n * k) break;
		S.push_back(A[p]);
		l ++; p = (p + 1) % n;
	}

	for(ll &t: S) cout << t << " ";

	cout << "\n";

	return 0;
}

