int lst;

void GO()
{
	lst = 0;
	while(tot < n * k)
	{
		tot++;
		if(pos[a[idx]] != -1)
		{
			int targ = pos[a[idx]];
			for(int i = lst - 1;i >= targ;i--) pos[ans[i]] = -1;
			lst = targ;
			idx++;idx %= n;
		}
		else
		{
			ans[lst] = a[idx];
			pos[a[idx]] = lst;
			lst++;
			idx++;idx %= n;
		}
	}
}

void go()
{
	while(1)
	{
		int add;
		auto it = upper_bound(vec[a[idx]].begin(),vec[a[idx]].end(),idx);
		//cout << idx << ' ' << tot << '\n';
		if(it == vec[a[idx]].end()) add = n - idx + vec[a[idx]][0];
		else add = (*it) - idx;
		if(n * k <= tot + 1 + add)
		{
			GO();
			break;
		}
		idx += add + 1;idx %= n;
		tot += add + 1;
	}
}

