using namespace std;

long long K;
int N, A[200009], nx[200009], c[200009], P[200009];
bool vs[200009];

long long get(int x) {
	if(vs[x]) {
		if(x != 0) while(1);
		return 0;
	}
	vs[x] = 1;
	return get(nx[x]) + c[x];
}

void go(long long x) {
	if(x + c[x%N] <= K*N) go(x + c[x%N]);
	else {
		vector<int> S;
		vector<bool> chk(200009, 0);
		for(int i=x%N; i<N; i++) {
			if(chk[A[i]]) {
				while(chk[A[i]]) {
					chk[S.back()] = 0;
					S.pop_back();
				}
			}
			else {
				chk[A[i]] = 1;
				S.push_back(A[i]);
			}
		}
		for(auto& it: S) printf("%d ", it);
		exit(0);
	}
}

int main() {
	scanf("%d%lld",&N,&K);
	for(int i=0; i<N; i++) {
		scanf("%d",&A[i]);
		A[i+N] = A[i];
	}
	for(int i=2*N-1; i>=0; i--) {
		if(i < N) nx[i] = (P[A[i]] + 1) % N, c[i] = P[A[i]] - i + 1;
		P[A[i]] = i;
	}
	long long L = get(0);
	if(L % N) while(1);
	K %= L/N;
	if(K == 0) return 0;
	go(0);
	return 0;
}

