                    g[v[i]] = v[0] + 1;
                }
            } else {
                if (v[i + 1] == N - 1) {
                    g[v[i]] = 0;
                } else {
                    g[v[i]] = v[i + 1] + 1;
                }
            }
        }
    }
    set<int> st;
    int prev = 0;
    int loop_ind;
    int loop_dist = 0;
    st.insert(0);
    while (1) {
        if (g[prev] - prev == 1) {
            loop_dist += N + 1;
        } else if (g[prev] > prev) {
            loop_dist += g[prev] - prev;
        } else {
            loop_dist += (N - prev) + g[prev];
        }
        if (st.count(g[prev]) == 1) {
            loop_ind = g[prev];
            break;
        } else {
            st.insert(g[prev]);
            prev = g[prev];
        }
    }
    ans = (N * K - 1) % loop_dist;
    int tmp = 0;
    prev = loop_ind;
    int mem;
    int mem_ans = 0;
    while (ans > tmp) {
        mem_ans = tmp;
        if (g[prev] - prev == 1) {
            tmp += N + 1;
        } else if (g[prev] > prev) {
            tmp += g[prev] - prev;
        } else {
            tmp += (N - prev) + g[prev];
        }
        mem = prev;
        prev = g[prev];
    }
    vector<int> res;
    set<int> st1;
    prev = mem;
    ans = ans - mem_ans + 1;
    for (int i = 0; i < ans; i++) {
        if (st1.count(a[prev]) == 1) {
            while (a[res[res.size() - 1]] != a[prev]) {
                st1.erase(a[res[res.size() - 1]]);
                res.pop_back();
            }
            st1.erase(a[prev]);
            res.pop_back();
        } else {
            st1.insert(a[prev]);
            res.push_back(prev);
        }
        prev++;
        if (prev >= N) {
            prev = 0;
        }
    }
    for (int i = 0; i < res.size(); i++) {
        cout << a[res[i]];
        if (i == res.size() - 1) {
            cout << endl;
        } else {
            cout << " ";
        }
    }
}

