    REP(i, n) cin >> a[i];
    map<int, int> last;
    REP(i, n) last[a[i]] = i;
    REP(i, n) {
        int lasti = last[a[i]];
        int dist = lasti < i ? i - lasti : i + n - lasti;
        hop[0][lasti] = make_pair(i + 1, dist + 1);
        last[a[i]] = i;
    }

    // doubling
    for (int k = 1; k < 60; ++k) {
        REP(i, n) {
            P prehop = hop[k - 1][i];
            P next = hop[k - 1][prehop.first];
            hop[k][i] = make_pair(next.first, next.second + prehop.second);
        }
    }

    // for (int k = 0; k < 20; ++k) {
    //     D(k); DV(hop[k]);
    // }

    ll max_steps = k * n;
    ll steps = 0;
