std::vector<int> eval(std::vector<int> & x) {
	std::vector<int> vec;
	std::set<int> st;
	for(auto v: x) {
		if(st.count(v)) {
			while(st.count(v)) {
				int p = vec.back();
				vec.pop_back();

				st.erase(p);
			}
		} else {
			st.insert(v);
			vec.push_back(v);
		}
	}

	return vec;
}

int main() {
	int n; i64 k; scanf("%d%lld", &n, &k); std::vector<int> a(n);
	for(int i = 0; i < n; i++) scanf("%d", &a[i]);

	// solve
	std::vector<int> nearest(n);
	{ // construct nearest
		std::vector<int> last(2e5 + 10, -1);
		for(int i = 0; i < 2 * n; i++) {
			int v = a[i % n];

			if(~last[v] and last[v] < n) {
				nearest[last[v]] = i;
				last[v] = i;
