	int T = 0;
	{ // 周期を求める（高々 N）
		int now = 0;
		while(true) {
			T += (n - 1 <= nearest[now]);
			now = (nearest[now] + 1) % n;

			if(!now) break;
		}
	}

	k = k % T + T;
	int now = 0;
	while(k > 1) {
		k -= (n - 1 <= nearest[now]);
		now = (nearest[now] + 1) % n;
	}

	std::vector<int> ans;
	for(int i = now; i < n; i++) ans.push_back(a[i]);
	ans = eval(ans);

	for(auto v: ans) printf("%d ", v);
	printf("\n");
