pair<ll, ll> find_loop() {
    ll i;
    ll length = 0;
    for (i=0; i<MAX; i++) B[i] = 0;
    for (i=0; i<K; i++) {
        for (ll j=0; j<N; j++) {
            int a = A[j];
            if (B[a]==1) {
                length--;
                while(S[length]!=a) {
                    B[S[length]] = 0;
                    length--;
                }
                B[a] = 0;
            } else {
                S[length++] = a;
                B[a] = 1;
            }
        }
        for (ll j=0; j<i; j++) {
            if (length==V[j].size()) {
                for (int k=0; k<V[j].size(); k++) {
                    if (V[j][k]!=S[k]) break;
                    else if (k==length) return make_pair(j, i-1);
                }
            }
        }
        for (ll j=0; j<length; j++) V[i].push_back(S[j]);
    }

    return make_pair(-1, i-1);
}

