void GO()
{
	lst = 0;
	while(tot < n * k)
	{
		tot++;
		if(pos[a[idx]] != -1)
		{
			int targ = pos[a[idx]];
			for(int i = lst - 1;i >= targ;i--) pos[ans[i]] = -1;
			lst = targ;
			idx++;idx %= n;
