		else
		{
			ans[lst] = a[idx];
			pos[a[idx]] = lst;
			lst++;
			idx++;idx %= n;
		}
	}
}

void go()
{
	while(1)
	{
		int add;
		int f = nxt[idx];
		if(f > idx) add = f - idx;
		else add = n - idx + f;
		if(n * k <= tot + 1 + add)
		{
			GO();
			break;
		}
		idx += add + 1;idx %= n;
		tot += add + 1;
	}
}

