int main() {
	lli N, K;
	cin >> N >> K;
	vector<lli> v(N);

	for (lli i = 0; i < N; i++) {
		cin >> v[i];
	}
	//keyの数字で次に対になる要素
	map<lli, lli> se;

	//i番目の要素の対の要素番号
	vector<lli> range_pair(N);
	iota(range_pair.begin(), range_pair.end(), 0);

	//対になるのを決定する(NlogN)
	for (lli i = 0; i < N; i++) {
		if (se.count(v[i])) {
			swap(range_pair[se[v[i]]], range_pair[i]);
		}
		se[v[i]] = i;
	}
	//周期は最大でもN
	vector<lli> dp(N + 1);
	//0回目及び周期に達したら空文字列
	dp[0] = N;
	//周期iにおいてdp[i]文字目から始まる
	lli beg = 0;
	//周期
	lli moddl = 0;

	//range_pair[beg] <= begで1周期またぐためdpにbegを保存

	for (int i = 1; i <= N;) {
		if (range_pair[beg] <= beg) {
			dp[i] = beg;
			i++;
		}
		//文字は再代入されないためbegはrange_pair[beg] + 1
		beg = range_pair[beg] + 1;

		//周期の終わり
		if (beg == N) {
			moddl = i;
			break;
		}
	}
	//周期のmodをとる
	K %= (moddl);
	for (lli i = dp[K]; i < N; i++) {
		//dp[K]文字目以降でペアがあったら除外する
		if (range_pair[i] > i) {
			i = range_pair[i];
			continue;
		}
		cout << v[i];
		if (i == N - 1) {
			cout << endl;
		}
		else {
			cout << " ";
		}
	}
	return 0;
}

