			dp[i][j] = dp[i][j-1] + dp[ (i+dp[i][j-1])%n ][j-1];
		}
	}
	ll stt = gbis_special(0,n*k-1);
	vector<ll> final;
	for(ll i=stt;i<=n*k-1;i++){
		final.pb(a[i%n]);
		fp[a[i%n]].insert(i);
	}
	ll idx = stt;
	vector<ll> ans;
	while(idx <= n*k-1){
		ll cur = final[idx-stt];
		set<ll>::iterator it = fp[cur].upper_bound(idx);
		if( it == fp[cur].end() ){
			ans.pb(cur);
			idx++;
		}
		else{
			idx = *it;
			idx++;
		}
	}
	for(long long i=0;i<ans.size();i++){
		cout<<ans[i]<<" ";
	}
	cout<<endl;
	return 0;
}

