    cin >> n >> k;

    vector<int> A(n);
    map<int, bool> mp2;
    map<int, int> mp;
    for (int i = 0; i < n; i++) {
        cin >> A[i];
        if (!mp2[A[i]]) {
            mp2[A[i]] = true;
            mp[A[i]] = i;
        }
    }

    vector<int> nxt(n); // 次に同じ文字が現れる最初のindex
    for (int i = n - 1; i >= 0; i--) {
        nxt[i] = mp[A[i]];
        mp[A[i]] = i;
    }

    ll count = 1;
