    }

    k = (k + count - 1) % count;
    if (k == count - 1) return 0;

    idx = 0;
    while (true) {
        if (k <= 0) break;
        if (nxt[idx] <= idx) k--;
        idx = (nxt[idx] + 1) % n;
    }

    while (true) {
        if (idx >= n) break;
        if (nxt[idx] <= idx) {
            cout << A[idx] << " ";
            idx++;
        } else {
            idx = nxt[idx] + 1;
        }
    }

