int main(){
	ios_base::sync_with_stdio(false);
	int n;
	ll k;
	cin >> n >> k;
	vector<int> a(n);
	for(int i = 0; i < n; ++i){ cin >> a[i]; }
	const int m = *std::max_element(a.begin(), a.end()) + 1;

	vector<int> last(m);
	for(int i = n - 1; i >= 0; --i){ last[a[i]] = i; }

	vector<int> next(n);
	for(int i = n - 1; i >= 0; --i){
		next[i] = last[a[i]];
		last[a[i]] = i;
	}

	vector<int> heads;
	heads.push_back(0);
	do {
		int cur = heads.back();
		while(true){
			if(next[cur] <= cur || next[cur] == n - 1){
				heads.push_back((next[cur] + 1) % n);
				break;
			}else{
				cur = next[cur] + 1;
			}
		}
	} while(heads.back() != 0);
	heads.pop_back();

	vector<int> b;
	for(int i = heads[(k - 1) % heads.size()]; i < n; ++i){
		if(next[i] > i){
			i = next[i];
		}else{
			b.push_back(a[i]);
		}
	}
	for(const auto x : b){
		cout << x << " ";
	}
	cout << endl;
	return 0;
}

