long long n, k, anssize = 0;
vector<long long> a, ans, memo;
map<long long, vector<long long> > mp;

void solve();

int main() {
  cin >> n >> k;
  a.resize(n);
  for(int i = 0; i < n; ++i) {
    cin >> a[i];
    mp[a[i]].push_back(i);
  }
  solve();
  for(int i = 0; i < ans.size(); ++i) {
    if(i != 0) cout << " ";
    cout << ans[i];
  }
  cout << endl;
  return 0;
