void solve() {
  memo.resize(n);
  for(auto now : mp) {
    int nowsize = now.second.size();
    for(int i = 0; i < nowsize; ++i)
      memo[now.second[i]] = now.second[(i + 1) % nowsize];
  }
  long long allsize = 0, nowi = 0;
  while(1) {
    allsize +=
        1 + memo[nowi] - nowi + n * (memo[nowi] <= nowi);
    nowi = (memo[nowi] + 1) % n;
    if(nowi == 0) break;
  }
  k *= n;
  k %= allsize;
  while(k > 0) {
    if(1 + memo[nowi] - nowi + n * (memo[nowi] <= nowi) > k)
      break;
    k -= 1 + memo[nowi] - nowi + n * (memo[nowi] <= nowi);
    nowi = (memo[nowi] + 1) % n;
  }
  stack<long long> st;
  set<long long> ch;
  for(int i = 0; i < k; ++i) {
    if(ch.find(a[nowi]) == ch.end()) {
      st.push(a[nowi]);
      ch.insert(a[nowi]);
    }
    else {
      while(1) {
        long long tp = st.top();
        st.pop();
        ch.erase(tp);
        if(a[nowi] == tp) break;
      }
    }
    nowi = (nowi + 1) % n;
  }
  while(!st.empty()) {
    ans.push_back(st.top());
    st.pop();
  }
  reverse(ans.begin(), ans.end());
}

