const int MAXN = 200000;
const int MAXVAL = 2000000;
const int MAXLOG = 57;
const long long INF = 1000000000000000000LL;

int Stack[1 + MAXN], top = 0, v[1 + MAXN];
int where[1 + MAXVAL];
bool in[1 + MAXVAL];
int last[1 + MAXVAL], first[1 + MAXVAL];
int go[1 + MAXLOG][1 + MAXN];
long long add[1 + MAXLOG][1 + MAXN];

int main() {
    //freopen("tema.in", "r", stdin);
    //freopen("tema.out", "w", stdout);
    int n;
    long long k;
    scanf("%d%lld", &n, &k);
    k *= n;
    for (int i = 1; i <= n; i++)
        scanf("%d", &v[i]);
    for (int i = n; i >= 1; i--)
        if (!last[v[i]])
            last[v[i]] = first[v[i]] = i;
        else {
            go[0][i] = first[v[i]] % n + 1;
            add[0][i] = first[v[i]] - i + 1;
            first[v[i]] = i;
        }
    for (int i = 1; i <= MAXVAL; i++)
        if (last[i]) {
            go[0][last[i]] = first[i] % n + 1;
            add[0][last[i]] = n - last[i] + first[i] + 1;
        }
    for (int i = 1; i <= MAXLOG; i++)
        for (int j = 1; j <= n; j++) {
            go[i][j] = go[i - 1][go[i - 1][j]];
            add[i][j] = min(INF, add[i - 1][j] + add[i - 1][go[i - 1][j]]);
        }
    int x = 1;
    for (int i = MAXLOG; i >= 0; i--)
        if (add[i][x] <= k) {
            k -= add[i][x];
            x = go[i][x];
        }
    for (int i = 1; i <= k; i++, x = x % n + 1) {
        if (!in[v[x]]) {
            top++;
            Stack[top] = v[x];
            in[v[x]] = true;
            where[v[x]] = top;
        }
        else {
            in[v[x]] = false;
            top = where[v[x]] - 1;
            where[v[x]] = 0;
        }
    }
    for (int i = 1; i <= top; i++)
        printf("%d ", Stack[i]);
    return 0;
}

