      set.emplace(a[i % n]);
      result.emplace_back(a[i % n]);
    } else {
      while (result.back() != *it) {
        set.erase(result.back());
        result.pop_back();
      }
      result.pop_back();
      set.erase(it);
    }
  }
  for (auto i : result) {
