    while (ng - ok > 1) {
        ll mid = ok + ng >> 1;
        if (check(mid).second <= n * k)ok = mid;
        else ng = mid;
    }

    map<int, int> used;
    VI ans;
    pair<int, ll> res = check(ok);
    FOR(i, res.first, res.first + n * k - res.second) {
        int x = a[i % n];
        if (0 < used[x]) {
            while (!ans.empty() && used[x]) {
                --used[ans.back()];
                ans.pop_back();
            }
        }
        else {
            ++used[x];
            ans.push_back(x);
        }
    }
    print(ans);

