const int MX = 2e5 + 100;
int v[MX], mn[MX], nxt[MX], ptr[MX];
int pass[MX];
void dfs(int p, int t, int k, int n) {
    if(pass[p]) {
        t += (k - t) / (t - pass[p]) * (t - pass[p]);
        memset(pass, 0, sizeof(pass)); 
    }
    else {
        pass[p] = t;
    }
    if(t == k) {
        vector<int> que; set<int> s;
        for(int i = p; i < n; i ++) {
            if(s.count(v[i])) {
                while(s.count(v[i])) {
                    s.erase(que.back());
                    que.pop_back();
                }
            }
            else {
                que.push_back(v[i]);
                s.insert(v[i]);
            }
        }
        for(auto it: que) cout << it << ' ';
        return;
    }
    dfs((ptr[p] + 1) % n, t + 1, k, n); 
}
