int main()
{
	long long int n;
	long long int k;
	cin >> n >> k;
	k *= n;
	// cout << k << endl;
	for(int i = 0; i < n; i++){
		cin >> a[i];
		indexList[a[i]].push_back(i);
	}
	if(n == 1){
		if((n * k) % 1 == 0) cout << a[0] << endl;
		return 0;
