		if(k <= stepNumToNextStart) break;
		if(stepNum[next] >= 0 && !loopChecked){
			int loopStart = next;
			long long int loopStepNum = stepNum[now] + stepNumToNextStart - stepNum[loopStart];
			// cout << "koko " << loopStepNum  << endl;
			k %= loopStepNum;
			now = loopStart;
			loopChecked = true;
		} else {
			stepNum[next] = stepNum[now] + stepNumToNextStart;
			now = next;
			k -= stepNumToNextStart;
		}
	}

	while(k > 0){
		long long int stepNumToNextStart = (nextStart[now] - now + n) % n;
