    rep(i,N){
        cin >> A[i];
        A[i]--;
        pos[A[i]].push_back(i);
    }
    rep(i,MAX){
        for (auto p:pos[i]){
            pos[i].push_back(p+N);
        }
    }
    ll now=0,round=1,cycle;
    vector<Pll> cnt;
    while(1){
        ll next=*upper_bound(pos[A[now]].begin(),pos[A[now]].end(),now);
        if (next>N-1){
            round++;
            next-=N;
        }
        cnt.push_back(Pll(round,next));
        if (next==N-1){
            cycle=round;
            break;
        }
        now=next+1;
    }
    ll s=cnt.size();
    K%=cycle;
    if (K==0){
        cout << endl;
        return 0;
    }
    ll lb=-1,ub=s;
    while(ub-lb>1){
        ll mid=(lb+ub)/2;
        if (cnt[mid].first>K){
            ub=mid;
        }
        else {
            lb=mid;
        }
    }
    ll start;
    if (lb==-1){
        start=0;
    }
    else {
        start=cnt[lb].second+1;
    }
    stack<ll> st;
    map<ll,ll> m;
    rep2(i,start,N){
        if (m[A[i]]==0){
            m[A[i]]++;
            st.push(A[i]);
        }
        else {
            ll g=A[i];
            while(1){
                ll x=st.top();
                st.pop();
                m[x]--;
                if (x==g){
                    break;
                }
            }
        }
    }
    vector<ll> ans;
    while(!st.empty()){
        ll t=st.top();
        ans.push_back(t+1);
        st.pop();
    }
    reverse(ans.begin(),ans.end());
    ll s2=ans.size();
    rep(i,s2){
        cout << ans[i];
        if (i!=s2){
            cout << ' ';
        }
        else {
            cout << endl;
        }
    }
}

