			ll j = (i + step[S-1][i]) % n;
			step[S][i] = step[S-1][i] + step[S-1][j];
		}
		S++;
	}

	ll i = 0, rem = k*n;
	FORD(s,0,S) {
		if (step[s][i] < rem) {
			rem -= step[s][i];
			i = (i + step[s][i]) % n;
