    rep(i, n) cin >> a[i];

    const int MAX_LOG_NK = 61;
    const int MAX_A = 200000;
    vector<vector<ll>> next(n, vector<ll>(MAX_LOG_NK));
    vector<ll> last(MAX_A + 1, -1);
    revrep(i, n) {
        if (last[a[i]] == -1) next[i][0] = -1;
        else next[i][0] = last[a[i]] - i + 1;
        last[a[i]] = i;
    }
    rep(i, n) if (next[i][0] == -1) next[i][0] = last[a[i]] + n - i + 1;

    rep(x, MAX_LOG_NK - 1) {
        rep(i, n) {
            if (next[i][x] == -1 || next[(i + next[i][x]) % n][x] == -1) continue;

            if (n * k < next[i][x] + next[(i + next[i][x]) % n][x]) next[i][x + 1] = -1;
            else next[i][x + 1] = next[i][x] + next[(i + next[i][x]) % n][x];
        }
    }

    ll now_idx = 0;
    bool update = true;
    while (update) {
        ll max_idx = 0;
        update = false;
        rep(x, MAX_LOG_NK) {
            if (next[now_idx % n][x] == -1) continue;

            if (now_idx + next[now_idx % n][x] < n * k) chmax(max_idx, now_idx + next[now_idx % n][x]);
        }
        if (chmax(now_idx, max_idx)) update = true;
    }

    deque<int> que;
