LL ds[60][200005];
void getper(){
	int i,j,k;
	for(i=n-1;i>=0;--i) pr[a[i]]=i;
	for(i=n-1;i>=0;--i){
		nx[0][i]=pr[a[i]];
		if(nx[0][i]<=i)
			ds[0][i]=(LL)(n+nx[0][i]-i);
		else
			ds[0][i]=(LL)(nx[0][i]-i);
		++ds[0][i];
		nx[0][i]=(nx[0][i]+1)%n;
//		printf("ds %d %d = %d nx=%d\n",0,i,ds[0][i],(int)nx[0][i]);
		pr[a[i]]=i;
	}
	for(i=1;i<60;++i){
		for(j=0;j<n;++j){
			nx[i][j]=nx[i-1][nx[i-1][j]];
			ds[i][j]=ds[i-1][j]+ds[i-1][nx[i-1][j]];
			ds[i][j]=min(ds[i][j],inf);
//			if(i<3) printf("ds %d %d = %d nx=%d\n",i,j,(int)ds[i][j],nx[i][j]);
		}
	}
	stt=0;
	LL lf=m*(LL)n;
	for(i=59;i>=0;--i){
		if(lf>=ds[i][stt]){
			lf-=ds[i][stt];
			stt=nx[i][stt];
		}
	}
	if(lft>n+1) exit(0);
	lft=(int)lf;
}

