const int N=200050;
const int L=61;
const ll inf=1e18;
const ll lim=2e17;
int go[N][L];
ll sum[N][L];
int a[N],last[N];
bool in[N];
bool was[N];
int main()
{
	//printf("%lld %lld %lld",(ll)1<<L,lim,((ll)1<<L)-lim);
	ll n,k;
	scanf("%lld %lld",&n,&k);
	for(int i=1;i<=n;i++)
	{
		scanf("%i",&a[i]);
		if(!last[a[i]]) last[a[i]]=i;
	}
	auto nxt=[&](int x)
	{
		return x==n?1:x+1;
	};
	for(int i=n;i>=1;i--)
	{
		go[i][0]=nxt(last[a[i]]);
		if(!was[a[i]] || go[i][0]==1) sum[i][0]=1;
		if(!was[a[i]] && go[i][0]==1) sum[i][0]=2;
		last[a[i]]=i;
		was[a[i]]=1;
	}
	for(int j=1;j<L;j++) for(int i=1;i<=n;i++)
	{
		go[i][j]=go[go[i][j-1]][j-1];
		sum[i][j]=sum[i][j-1]+sum[go[i][j-1]][j-1];
		sum[i][j]=min(sum[i][j],inf);
	}
	int u=1;
	for(int j=L-1;~j;j--)
	{
        if(sum[u][j]<k)
		{
			k-=sum[u][j];
			u=go[u][j];
		}
	}
	vector<int> ans;
	for(int i=u;i<=n;i++)
	{
		if(in[a[i]])
		{
			in[a[i]]=0;
			while(ans.back()!=a[i]) in[ans.back()]=0,ans.pop_back();
			ans.pop_back();
		}
		else ans.push_back(a[i]),in[a[i]]=1;
	}
	for(int i:ans) printf("%i ",i);
	return 0;
}

