int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  ll n,k;
  cin >> n >> k;
  VLL a(4*n);
  rep(i,n){
    cin >> a[i];
    a[i+n] = a[i];
    a[i+2*n] = a[i];
    a[i+3*n] = a[i];
  }

  ll last[(int)(2e5)+1];
  VLL r(2*n);
  // 遷移先が記載された配列を埋める
  for(ll i = n*4-1; i >= 0; i--){
    if(i < 2*n){
      r[i] = last[a[i]];
    }
    last[a[i]] = (i+1) % (2*n);
  }

  ll go[60][2*n];
  ll add[60][2*n];

  rep(i,2*n){
    go[0][i] = r[i];
    if(r[i] < i) add[0][i] = abs(i - 2*n - r[i]);
    else add[0][i] = abs(r[i] - i);
  }

  // rep(i,2*n){
  //   cout << add[0][i] << " ";
  // }
  // cout << endl;
  // rep(i,2*n){
  //   cout << go[0][i] << " ";
  // }
  // cout << endl;

  for(int log = 1; log < 60; log++){
    rep(i,2*n){
      ll i2 = go[log-1][i];
      go[log][i] = go[log-1][i2];
      add[log][i] = min<ll>(2e17+10,add[log-1][i] + add[log - 1][i2]);
    }
  }

  ll cur = 0;
  ll pref = 0;

  for(int log = 60 - 1; log >= 0; log--){
    if(cur + add[log][pref] <= n * k){
      cur += add[log][pref];
      pref = go[log][pref];
    }
  }

  if(cur == n*k) return 0;

  while(cur<=n*k){
    // cout << n*k << endl;
    while( (cur + add[0][pref]) <= n*k){
      // cout << "pref: " << pref << ", cur:" << cur << "," << n*k << endl;
      cur += add[0][pref];
      pref = go[0][pref];
    }
    // cout << "cur: " << cur << endl;
    if(cur==n*k) break;
    cout << a[pref] << " ";
    cur++;
    (pref += 1) %= (2*n);
  }
  cout << endl;
  return 0;
}

