int main()
{
    int N;
    long long K;
    cin>>N>>K;
    vector<int> A(N);
    for (int &a: A)
        cin>>a;

    vector<int> S(N, -1);
    map<int, int> M;
    for (int i=N-1; i>=0; i--)
        M[A[i]] = i;
    for (int i=N-1; i>=0; i--)
    {
        S[i] = M[A[i]];
        M[A[i]] = i;
    }

    int p = 0;
    long long k = 0;
    while (k<K-1)
    {

        if (S[p]<=p)
            k++;
        p = S[p]+1;
        if (p>=N)
        {
            p %= N;
            k++;
        }

        if (p==0)
        {
            long long t = (K-1)/k;
