        if (SS.count(A[i])>0)
        {
            while (ans.back()!=A[i])
            {
                SS.erase(ans.back());
                ans.pop_back();
            }
            ans.pop_back();
            SS.erase(A[i]);
        }
        else
        {
            ans.push_back(A[i]);
            SS.insert(A[i]);
        }
    }

    bool f = true;
