#include <bits/stdc++.h>
#define int long long
using namespace std;
const int MX = 2e5 + 100;
int v[MX], mn[MX], nxt[MX], ptr[MX], pass[MX];
void dfs(int p, int t, int k, int n) {
    if(pass[p] and t < k) {
        t += (k - t) / (t - pass[p]) * (t - pass[p]);
        memset(pass, 0, sizeof(pass));
    }
    pass[p] = t;
    if(t > k) return;
    if(t == k) {
        vector<int> que; set<int> s;
        for(int i = p; i < n; i ++) {
            if(s.count(v[i])) {
                while(s.count(v[i])) {
                    s.erase(que.back());
                    que.pop_back();
                }
            }
            else {
                que.push_back(v[i]);
                s.insert(v[i]);
            }
        }
        for(auto it: que) cout << it << ' ';
        return;
    }
    if(ptr[p] == p and p == n - 1) dfs((ptr[p] + 1) % n, t + 2, k, n);
    else                           dfs((ptr[p] + 1) % n, t + 1, k, n);
}
main() {
    for(int i = 0; i < MX; i ++) mn[i] = MX;
    int n, k; cin >> n >> k;
    for(int i = 0; i < n; i ++) cin >> v[i];
    for(int i = 0; i < n; i ++) mn[v[i]] = min(mn[v[i]], i);
    for(int i = n - 1; i >= 0; i --) {
        if(nxt[v[i]]) ptr[i] = nxt[v[i]];
        else          ptr[i] = mn [v[i]];
        nxt[v[i]] = i;
    }
    for(int i = n - 1; i >= 0; i --) {
        if((ptr[i] + 1) % n > i and ptr[i] != i) {
            ptr[i] = ptr[(ptr[i] + 1) % n];
        }
    }
    dfs(0, 1, k, n);
}

