		if(p == 0) return 0;
		p = n*(k-1) /p*p;
		while(p < n*(k-1)) {
			p += b[p%n] + 1;
		}
	}

	for(ll j = p; j < n*k; j++){
		int i = j % n;
		if(st.find(a[i]) != st.end()){
			while(que.back() != a[i]){
				st.erase(st.find(que.back()));
				que.pop_back();
			}
			st.erase(st.find(que.back()));
			que.pop_back();
		} else {
			st.emplace(a[i]);
			que.emplace_back(a[i]);
		}
	}
	for(int i : que) printf("%d ", i);
}

