        int s = p;
        while(!last[p]) {
            p = (nxt[p] + 1) % n;
            if(p == s) return 0;
        }
        if(!seq.empty() && seq[0] == p) break;
        seq.push_back(p);
        p = (nxt[p] + 1) % n;
