void solve(long long N, long long K, std::vector<long long> A){
  vector<long long> p(N+1);
  vector<long long> pr(200000, -1);
  p[N] = -1;
  for (int i = N-1; i >= 0; i--) {
    if (pr[A[i]] == -1) {
      p[i] = i;
      pr[A[i]] = i;
    } else {
      p[i] = p[pr[A[i]]+1];
      pr[A[i]] = i;
    }
  }

  long long idx = 0;
  long long t = -1;
  long long o = -1;
  while (true) {
    idx++;
    if (t == -1) {
      o = p[0];
    } else {
      o = p[pr[t]+1];
    }
    if (o == -1) {
      break;
    }
    t = A[o];
  }


  idx = K % idx;
  t = -1;
  o = -1;
  for (int i = 0; i < idx; i++) {
    if (t == -1) {
      o = p[0];
    } else {
      o = p[pr[t]+1];
    }
    if (i < idx-1) {
      t = A[o];
