const ll N_MAX = 222222;

ll nxt[N_MAX];
ll pre[N_MAX];
ll v[N_MAX];
ll ans[N_MAX];
ll n, k, cycle, itre;
vector<ll> pass;

void makeNxt(){

	REP(i, N_MAX){
		pre[i] = -1;
	}

	REP(time, 2){
		REP(i, n){
			int now = v[i];
			if(pre[now] != -1){
				nxt[pre[now]] = i;
			}
			pre[now] = i;
		}
	}
}

int makePass(){
	pass.PB(0);
	int now = 0;
	cycle = 1;

	while(1) {
		if(nxt[now] <= now){
			cycle++;
		}
		now = nxt[now];
		now = (now + 1) % n;
		pass.PB(now);
		if(now == 0){
			break;
		}
	}

	k %= cycle;
	now = 0;

	while(k > 1) {
		if(nxt[now] <= now){
			k--;
		}
		now = nxt[now];
		now = (now + 1) % n;
	}

	return now;
}

void makeAns(int start){
	//cout << "start " << start << endl;
	REP(i, N_MAX){
		pre[i] = INF;
	}

	for(int i = start;i < n;i++){
		int now = v[i];
		if(pre[now] < itre){
			itre = pre[now];
			pre[now] = INF;
		}
		else {
			ans[itre] = now;
			pre[now] = itre;
			itre++;
		}
		//cout << "makeAns " << i << endl;
		//REP(i, itre)cout << ans[i] << " ";cout << endl;
	}
}

int main(){
	cin.tie(0);cout.tie(0);ios::sync_with_stdio(false);

	cin >> n >> k;
	REP(i, n)cin >> v[i];

	if(n == 1){
		if(k % 2){
			cout << v[0];
		}
		cout << endl;
		return 0;
	}

	makeNxt();
	int start = makePass();
	makeAns(start);
	REP(i, itre){
		cout << ans[i] << " ";
	}
	cout << endl;

	return 0;
}

