typedef long long ll;
using namespace std;

const ll INF = (1LL << 60);

int main(){
    ll N, K;
    cin >> N >> K;
    int a[N];
    for(int i = 0; i < N; i++) cin >> a[i];

    map<int, vector<int>> mp;
    for(int i = 0; i < N; i++) mp[a[i]].push_back(i);

    ll d[N][60];
    for(auto it = mp.begin(); it != mp.end(); it++){
        vector<int> vec = it -> second;
        for(int i = 0; i < (int)vec.size(); i++){
            if(i == (int)vec.size() - 1){
                d[vec[i]][0] = N + vec[0] - vec[i] + 1;
            } else {
                d[vec[i]][0] = vec[i + 1] - vec[i] + 1;
            }
        }
    }

    for(int j = 1; j < 60; j++){
        for(int i = 0; i < N; i++){
            int idx = (i + d[i][j - 1]) % N;
            d[i][j] = d[i][j - 1] + d[idx][j - 1];
            d[i][j] = min(INF, d[i][j]);
        }
    }

    /*
    for(int j = 0; j < 60; j++){
        for(int i = 0; i < N; i++){
            cout << d[i][j] << " ";
        }
        cout << endl;
    }*/

    ll pos = 0;
    while(true){
        int idx = pos % N;
        bool found = false;
        for(int j = 59; j >= 0; j--){
            if(pos + d[idx][j] < N * K){
                found = true;
                pos += d[idx][j];
                break;
            }
        }

        if(found) continue;
        else break;
    }

    pos %= N;

    //pos~Nまでをシミュレート
    map<int, int> mp2;
    stack<int> st;
    for(int i = pos; i < N; i++){
        if(mp2[a[i]] > 0){
            while(mp2[a[i]] > 0){
                int x = st.top();
                mp2[x]--;
                st.pop();
            }
        }
        else {
            st.push(a[i]);
            mp2[a[i]]++;
        }
    }

    vector<int> ans;
    while(!st.empty()){
        ans.push_back(st.top());
        st.pop();
    }

    reverse(ans.begin(), ans.end());

    for(int val : ans){
        cout << val << " ";
    }
    cout << endl;
    return 0;
}

