        if (s == INF) s = -1;
        int next = *pos[a[s+1]].upper_bound(s+1);
        if (next >= n) {per++;next -= n;}
        s = next;
    }
    k %= per;
    k *= n;
    vector<int> ans;
    s = 0;
    while (1) {
        if (k == 0) break;
        int next = *pos[a[s]].upper_bound(s);
        if (next-s+1 > k) {
            ans.pb(a[s]); s++; k--;
        } else {
            k -= (next-s+1);
            s = (next+1)%n;
        }
    }
    for (auto&& A : ans) {
        cout << A << " ";
    } cout << endl;
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	solve();
}

