int main()
{
	scanf("%d %lld",&n,&k);
	fo(i,1,n) scanf("%d",&a[i]);

	fd(i,n,1)
	{
		if (occur[a[i]])
		{
			if (occur[a[i]]==n) p[i]=(D){1,1ll}; else p[i]=(D){occur[a[i]]+1,0ll};
		}
		occur[a[i]]=i;
	}
	memset(occur,0,sizeof(occur));
	fo(i,1,n)
	{
		if (!occur[a[i]]) occur[a[i]]=i;
		if (!p[i].i)
		{
			if (occur[a[i]]==n) p[i]=(D){1,2ll}; else p[i]=(D){occur[a[i]]+1,1ll};
		}
