// 1ブロックごとに必ず1回は全部消すことになる→全部消した後の始点の推移を書く？

vector<int> v[200001]; // v[n]には A_k = n となるkが入ってる, ソート済みなので二分探索で値がlog n

// v[i] の k = j の index を二分探索で取得
int biSearch(int i, int j){
    int lb=0, ub = v[i].size() - 1;
    while( v[i][ub] != j ){
        int mid = (lb+ub)/2;
        if( v[i][mid] >= j){
            ub = mid;
        }else{
            lb = mid;
        }
    }
    return ub;
}

int main() {
    int N;
    ll K;
    cin >> N >> K;
    vector<int>A(N);
    for (int i = 0; i < N; ++i) {
      cin >> A[i];
      v[A[i]].push_back(i);
    }

    vector<int> ans; // 最初に1周するまで各kの出力の始点を保存(線形で出力が求まる)
    int s = 0; // 始点

    while (true){
        int index = biSearch(A[s], s);
        if(index == v[A[s]].size() - 1) {
            ans.push_back(s);
            s = v[A[s]][0] + 1;

            // 単独で末尾の場合
            if(s == N){
                ans.push_back(-1);
                break;
            }
        }else {
            if(v[A[s]][index+1] + 1 == N){
                ans.push_back(-1);
                break;
            }else {
                s = v[A[s]][index+1] + 1;
            }
        }
    }
    K = (K-1) % ans.size();
    int i = ans[K];
    if(i != -1){
        while (i != N){
            int index = biSearch(A[i], i);
            if(index != v[A[i]].size() - 1) {
                i = v[A[i]][index+1] + 1;
            }else{
                cout << A[i] << " ";
                i++;
            }
        }
    }

    return 0;
}

