bool match(vector<ll>& a, vector<ll>& b) {
    if(a.size() != b.size())
        return false;

    for(auto i=a.begin(), j=b.begin(); i!=a.end(); i++, j++) {
        if(*i != *j)
            return false;
    }
    return true;
}

