const int MAXA = 2e5;

int main() {
    FAST_IO();
    int N;
    ll K; cin >> N >> K;
    vector<int> A(N);
    rep(i, N) cin >> A[i];
    // next[i], cnt[i]
    vector<int> next(N), cnt(N);
    // pos[i] : array of position which number 'i' appears
    vector<vector<int>> pos(MAXA + 1);
    rep(i, N) pos[A[i]].push_back(i);
    repp(i, 1, MAXA) {
        int SZ = sz(pos[i]);
        for(int j = 0; j < SZ; ++j) {
            next[pos[i][j]] = (pos[i][(j + 1)%SZ] + 1) % N;
            cnt[pos[i][j]] = (j == SZ - 1);
        }
    }
    int period = 1;
    int start = 0;
    do {
        period += cnt[start];
        start = next[start];
    } while(start != 0);
    K = (K - 1) % period + 1;
    start = 0;
    while(K > 1) {
        K -= cnt[start];
        start = next[start];
    }
    vector<int> ans;
    int idx = start;
    while(idx < N && idx >= start) {
        if(cnt[idx] == 0) {
            idx = next[idx];
        } else {
            ans.push_back(A[idx]);
            idx = idx + 1;
        }
    }
    cout << ans;
}

