inline char nc()
{
    return getchar();
	static char buf[100000], *l = buf, *r = buf;
	return l==r&&(r=(l=buf)+fread(buf,1,100000,stdin),l==r)?EOF:*l++;
}
template<class T> void read(T &x)
{
	x = 0; int f = 1, ch = nc();
	while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=nc();}
	while(ch>='0'&&ch<='9'){x=x*10-'0'+ch;ch=nc();}
	x *= f;
}
typedef long long ll;
typedef pair<int, ll> pil;
const int MAXN = 2e5 + 5;
const int MAXA = 2e5 + 5;
ll K;
int N;
int A[MAXN];
int L[MAXA], R[MAXA];
bool vis[MAXA];
pil nex[MAXN][45];
vector<int> an;
inline pil add(pil a, pil b)
{
    return make_pair(b.fi, a.se + b.se);
}
void FIND(pil &a)
{
    if(a.se) return;
    FIND(nex[a.fi][0]);
    a = nex[a.fi][0];
}
void COUNT()
{
    int m = *max_element(A, A + N);
    for(int i = 1; i <= m; ++i) if(R[i] != -1)
    {
        nex[ R[i] ][0] = make_pair((L[i] + 1) % N, 1 + (L[i] + 1) / N);
    }
    for(int i = 0; i < N; ++i)
    {
        FIND(nex[i][0]);
    }
    for(int k = 1; k < 45; ++k)
    {
        for(int i = 0; i < N; ++i)
        {
            nex[i][k] = add(nex[i][k - 1], nex[ nex[i][k - 1].first ][k - 1]);
        }
    }
}
void work(int st)
{
    for(int i = st; i < N; ++i)
    {
        int x = A[i];
        if(!vis[x])
        {
            an.push_back(x);
            vis[x] = 1;
        }
        else
        {
            while(true)
            {
                int y = an.back();
                vis[y] = 0;
                an.pop_back();
                if(x == y) break;
            }
        }
    }
}
void solve()
{
    int u = 0;
    for(int i = 44; ~i; --i)
    {
        while(K > nex[u][i].second)
        {
            K -= nex[u][i].second;
            u = nex[u][i].first;
        }
    }
    work(u);
    if(K == 2) work(0);
}
int main()
{
    read(N), read(K);
    memset(L, -1, sizeof(L));
    memset(R, -1, sizeof(R));
    for(int i = 0; i < N; ++i)
    {
        read(A[i]);
        if(L[ A[i] ] == -1) L[ A[i] ] = i;
        if(R[ A[i] ] != -1)
        {
            nex[ R[ A[i] ] ][0] = make_pair((i + 1) % N, (i + 1) / N);
        }
        R[ A[i] ]= i;
    }
    COUNT();
    solve();
    for(unsigned int i = 0; i < an.size(); ++i)
    {
        if(i) printf(" ");
        printf("%d", an[i]);
    }
    printf("\n");
    return 0;
}

