        scanf("%d", &a[i]), a[i + n] = a[i];
    for (int i = n + n ; i >= 1; i --) {
        next[i] = f[a[i]], f[a[i]] = i;
        if (!next[i])g[i] = i;
        else
            g[i] = g[next[i] + 1];
    }
    f[0] = 0;
    for (int i = 1; i <= n ; i ++) {
        if (!sum[a[i]]){
            f[++f[0]] = i;
            sum[a[i]] ++;
        } else {
            while (sum[a[i]]) sum[a[f[f[0] --]]] --;
        }
    }
    if (f[0])
        g[0] = f[1];
    int x = 0;
    while (!id[x]) {
        d[id[x] = ++d[0]] = x;
        x = g[x];
