vector<int> calcStep(vector<int> &a, int size, int maxa) {
    vector<int> last(maxa, -1);
    for (int i = 0; i < size; i++) {
        if (last[a[i]] == -1)
            last[a[i]] = i + size;
    }
    vector<int> res(size);
    for (int i = size - 1; i >= 0; i--) {
        res[i] = last[a[i]] - i;
        last[a[i]] = i;
    }
    return res;
}

