constexpr int inf = 1e9;
constexpr ll INF = 2e18;
// constexpr ll MOD = 1e9+7;
constexpr ll MOD = 998244353;

ll n,k;
ll a[1<<19];
bool inque[1<<19];
ll table[1<<19][100];
ll pre[1<<19];

void input() {
    cin >> n >> k;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
}

void make_table() {

    for (int i = n * 2 - 1; i >= 0; i--) {
        table[i%n][0] = pre[a[i%n]] - i + 1;
        pre[a[i%n]] = i;
    }

    for (int i = 1; i < 64; i++) {
        for (int j = 0; j < n; j++) {
            if (table[j][i-1] == -1 || table[(table[j][i-1] + j) % n][i-1] == -1) {
                table[j][i] = -1;
                continue;
            }
            table[j][i] = table[j][i-1] + table[(table[j][i-1] + j) % n][i-1];
            if (table[j][i] > n * k) table[j][i] = -1;
        }
    }

}

void solve() {
    make_table();
    ll pos = 0;
    ll left = n * k;
    // for (int i = 0; i < 64; i++) {
    //     for (int j = 0; j < n; j++) {
    //         cout << table[j][i] << " ";
    //     }
    //     cout << endl;
    // }
    while (1) {
        // cout << pos << " " << left << endl;
        bool f = 1;
        for (int i = 63; i >= 0; i--) {
            if (table[pos][i] == -1) continue;
            if (left >= table[pos][i]) {
                left -= table[pos][i];
                pos += table[pos][i];
                pos %= n;
                f = 0;
                break;
            }
        }
        if (f) break;
    }

    deque<int> dq;
    while (left--) {
        if (!inque[a[pos]]) {
            dq.push_back(a[pos]);
            inque[a[pos]] = 1;
        } else {
            inque[a[pos]] = 0;
            while (dq.back() != a[pos]) {
                dq.pop_back();
            }
            dq.pop_back();
        }
        pos++;
        pos %= n;
    }

    while (!dq.empty()) {
        cout << dq.front();
        dq.pop_front();
        if (dq.empty()) {
            cout << endl;
        } else {
            cout << " ";
        }
    }
}

int main(int argc, char *argv[]) {
    input();
    solve();
    return 0;
}

