deque<int> f(vector<int> a){
    deque<int> d;
    map<int,int> cnt;
    for(int i = 0; i < a.size(); i++){
        if(d.empty()){
            d.push_back(a[i]);
            cnt[a[i]]++;
        }else{
            if(cnt[a[i]] == 1){
                while(d.back() != a[i]) cnt[d.back()]--, d.pop_back();
                d.pop_back();
                cnt[a[i]] = 0;
            }else{
                d.push_back(a[i]);
                cnt[a[i]]++;
            }
        }
    }
    return d;
}

