    scanf("%lld %lld", &n, &k);

    vector<int> a(n);
    for(int i = 0; i < n; i++)  scanf("%d", a.begin()+i);

    deque<int> d = f(a);

    if(d.empty()){
        cout << endl;
        return 0;
    }

    vector<deque<int>> loop;
    int llen = d.size();
    loop.push_back(d);
    deque<int> next;
    next.push_back(d.back());
    d = next;

    while(llen < k){
        vector<int> tmp;
        for(auto it = d.begin(); it != d.end(); it++)   tmp.push_back(*it);
        tmp.insert(tmp.end(), a.begin(), a.end());
        d = f(tmp);

        loop.push_back(d);
        llen += d.size();
        if(d.empty()){
            llen++;
            break;
        }
        deque<int> next;
        next.push_back(d.back());
        d = next;
    }


    k--;
    k %= llen;
    int cnt = 0;
    for(int i = 0; i < loop.size(); i++){
        if(cnt+loop[i].size() > k){
            deque<int> ans = loop[i];
            for(int j = 0; j < k-cnt; j++)  ans.pop_front();
            for(int j = 0; j < ans.size(); j++) cout << ans[j] << " \n"[j+1==ans.size()];
            break;
        }else{
            cnt += loop[i].size();
        }
    }

    return 0;
}

