    vector<int> a(n), b(n+1,0);     // b[i]: (a[i],..,a[n-1])という数列に対して
                                    //       今回の操作を行った時の結果の数列の第1項。ただし空集合の場合は0とする。
                                    //       なお便宜上b[n]=0としておく。
    int i;
