void powF(vector<int> & a, vector<int> & b, vector<int> & r, ll e) {
  vector<int> p(n + 1), pp(n + 1);
  for (int i = 0; i <= n; i++)
    p[i] = b[i];
  while ((e & 1) == 0) {
    pp = p;
    mul(a, p, pp);
    e /= 2;
  }
  r = p;
