vector<int> runSlow(int N, ll M, const vector<int>& A) {
    vector<int> ans;
    set<int> s;
    REP(i, M) {
        if (!s.insert(A[i % N]).second) {
            while (ans.back() != A[i % N]) s.erase(ans.back()), ans.pop_back();
            s.erase(ans.back()), ans.pop_back();
        } else {
            ans.push_back(A[i % N]);
        }
    }
    return ans;
}

vector<int> solve(int N, ll K, const vector<int>& A) {
    map<int, vector<int>> pos;
    REP(i, N) pos[A[i]].push_back(i);
    map<int, int> seen;
    int cur = 0;
    ll m = 0;
    while (true) {
        if (!seen.insert({cur, m}).second) break;
        ++m;
        int next;
        if (cur == pos[A[cur]].back()) {
            next = pos[A[cur]].front();
            m += N-cur+next;
        } else {
            next = *upper_bound(pos[A[cur]].begin(), pos[A[cur]].end(), cur);
            m += next-cur;
        }
        cur = next+1;
        if (cur == N) cur = 0;
    }
    ll k = seen.find(cur)->second, M = N*K;
    M = M < k ? M : (M - k) % m + k;
    return runSlow(N, M, A);
}

