const int LOG = 50;
const int N = 2e5+10;
int jmp[LOG][N];
ll dist[LOG][N];

vector<int> sim(vector<int>& v) {
    unordered_set<int> have;
    vector<int> cur;
    for(auto x : v) {
        if (have.count(x)) {
            while (true) {
                int last = cur.back();
                cur.pop_back();
                if (last == x) {
                    break;
                }
            }
            have.erase(x);
        } else {
            cur.push_back(x);
            have.insert(x);
        }
    }
    return cur;
}

