            dist[0][cur] = nxt - cur + 1;
            if (dist[0][cur] <= 1) dist[0][cur] += n;
        }
    }

    rep(l,1,LOG) {
        rep(i,0,n) {
            jmp[l][i] = jmp[l-1][jmp[l-1][i]];
