    for(int i=0; i<N; i++) A.push_back(A[i]);

    vector<ll> next(N);
    vector<ll> index(2*N);
    for(int i=0; i<2*N; i++) index[i] = i;
    auto cmp = [&](ll a, ll b){
        if(A[a%N] == A[b%N]) return a < b;
        return A[a%N] < A[b%N];
    };
    stable_sort(index.begin(), index.end(), cmp);
