const long MOD=1000000007;
const long INF=100000000000000000;
int main(){
    long N,K;
    cin>>N>>K;
    vector<long> A(N);
    for(int i=0;i<N;i++){
        cin>>A.at(i);
    }

    vector<long> next(N);//次にその値がくる点なければ-1;
    vector<long> front(200010,-1);//計算のため。A.at(i)のそこまでの先頭
    for(int i=N-1;i>=0;i--){
        next.at(i)=front.at(A.at(i));
        front.at(A.at(i))=i;
    }

    vector<long> pass(N+1);//数列Aをiばんめから始めた時に先頭になる点の添字。次ならNとなる。
    pass.at(N)=N;
    for(int i=N-1;i>=0;i--){
        if(next.at(i)==-1) pass.at(i)=i;
        else pass.at(i)=pass.at(next.at(i)+1);
    }

    long syuki=1,prei=pass.at(0);
    while(prei!=N){
        syuki++;
        prei=pass.at(front.at(A.at(prei))+1);
    }

    //cout<<syuki<<endl;


    K%=syuki;
    long pos=0;
    //cout<<K<<endl;
    while(K-1>0){//最後は出力と同時にシミュレートする
        K--;
        pos=front.at(A.at(pass.at(pos)))+1;
    }
    //cout<<pos<<endl;
    long para=pos;
    while(para<N){
        if(next.at(para)==-1){
            cout<<A.at(para)<<" ";
            para++;
        }else{
            para=next.at(para)+1;
        }
    }
    cout<<endl;
}

