    cin >> A[i];

  vector<vector<int>> jump(300000);
  for(int i=0; i<N; i++)
    jump[A[i]].push_back(i);

  vector<ll> log;
  ll len, period, diff;
  int Xi, indexA;
  len = 0;
  log.push_back(len);
  indexA = (int)(len%N);
  Xi = A[indexA];
  while(true){
    auto it = upper_bound(jump[Xi].begin(), jump[Xi].end(), indexA);
    if(it != jump[Xi].end()){
      diff = (ll) (*it) - indexA;
    }else {
      diff = (ll) (N - indexA - 1) + (jump[Xi][0] + 1);
    }
    len += diff + 1;
    log.push_back(len);
    indexA = (int)(len%N);
    Xi = A[indexA];
    if(indexA == 0){
      period = len/N;
      break;
    }
  }

  K %= period;
  vector<int> ans;
  if (period != 1){
    auto it = lower_bound(log.begin(), log.end(), K*N);
    it--;
    int start = (int)((*it)%N);
    for(int i=start; i<N; i++){
      Xi = A[i];
      auto it2 = upper_bound(jump[Xi].begin(), jump[Xi].end(), i);
      if(it2 != jump[Xi].end()){
        i = *it2;
      }else {
        ans.push_back(Xi);
      }
    }
  }

  for(auto a: ans){
