	VI a = in[n];

	int m = 0;
	for (LL p = 1; p <= n * k; p *= 2)m++;
	dump(m);
	VVL dp(m, VL(n));
	map<int, int> ma;
	rep(j, n * 2) {
		int i = j % n;
		if (ma.count(a[i])) {
			LL v = ma[a[i]];
			dp[0][v] = (LL)(j + 1) - v;
			ma.erase(a[i]);
		}
		if (j < n) {
			ma[a[i]] = j;
		}
	}
	FOR(i, 1, m)rep(j, n) {
		LL v = dp[i - 1][j];
		dp[i][j] = v + dp[i - 1][(j + v) % n];
	}
	dump(dp);
	out.exit(0);

	LL now = 0;
	while (true) {
		int j = now % n;
		if (n * k < now + dp[0][j]) {
			break;
		}
		int pos = m - 1;
		rep(i, m - 1) {
			if (now + dp[i][j] <= n * k && n * k < now + dp[i + 1][j]) {
				pos = i;
			}
		}
		now += dp[pos][j];
	}

	VI ans;
	for (LL j = now; j < n * k; j++) {
		int i = j % n;
		int pos = -1;
		rrep(k, sz(ans)) {
			if (a[i] == ans[k]) {
				pos = k; break;
			}
		}
		if (pos != -1) {
			ans.erase(ans.begin() + pos, ans.end());
		} else {
			ans.pb(a[i]);
		}
	}
	out(ans);
}

