// Main program
void solve(){
    LL N; cin >> N;
    LL K; cin >> K;
    LL L = 60;

    map<int,VI> key_id; //key_id

    //vector<VLL> next(L+1,tmp);

    // input, next[0][]
    VLL A(N);
    VLL W(N);
    //VI B(N);

    REP(i,2*N){

        if(i<N){
            cin >> A[i];
            //A[N+i]=B[i]; // 1 2 3 2 3 1 2 3 2 3
        }

        // same exist before
        int a = A[i%N];
        if(key_id.count(a)!=0){
            int id = key_id[a].back(); //- - - 1 2, 0 3 4 ..  
            DPRINT(id);
            if (id<N) W[id] = i - id + 1;
        }
        // add key
        key_id[a].PB(i);
         //several id for one key
    }    

    VVLL next(L+1,W);
    // doubling
    REP(k,L){
        REP(i,N){
            LL nowid = i + next[k][i];
            LL nextid = nowid + next[k][nowid%N];
            next[k+1][i] = min(LINF,nextid - i); //= next[k][i] + next[k][nowid%N]
        }
    }

    /* 
    //change out of range to -1
    REP(k,max_k+1){
        REP(i,N){
            if(next[k][i]+i > N*K) next[k][i] = -1;
        }
    }
    */

    //start from id = 0
    LL gid = 0; // global id
    CIREP(k,L,0){
        DPRINT(k)
        int id = gid%N; // id in a Line
        LL nextid = gid + next[k][id];
        //DPRINT(nextid)
        if(nextid <= N*K){
            gid = nextid;
        }
        //DPRINT(id)
    }

    // Do as the task
    if(gid==N*K) return;
    int id = gid%N;
    DPRINT(id)
    VI ans;

    //gidが負になるエラーがこれで防げる
    //chmax(id,0);

    CREP(i,id,N-1){

        //already deleted
        int stop_id = next[0][i] + i - 1;

        if(next[0][i]==-1){
            continue;
        }

        //do not appear
        if(stop_id >= N){
            DPRINT(i)
            //int a = B[i];
            ans.PB(A[i]); //error here
        }
        //appear
        else{
            CREP(j,i+1,stop_id){ //stop max = N-1
                DPRINT(j)

                //error access here
                next[0][j] = -1; //delete
            }
        }


    }
    REP(i,SZ(ans)){
        cout << ans[i];
        if(i< SZ(ans)-1) cout << " ";
        else cout <<endl;
    }
}



