void check(vector<int> &A, vector<int> &data, int N, int K, int b){
	vector<int> ans;
	// cout<<"b = "<<b<<" "<<endl;
	for(int i = b; i < N*K; i++){
		if(data[i%N]+i > N*K){
			ans.push_back(A[i%N]);
		} else {
			i += data[i%N]-1;
		}
	}

	for(int i = 0; i < ans.size(); i++){
		cout<<ans[i]<<" ";
	}
	cout<<endl;
