void solve(vector<int> &A, int N, int K){
	vector<vector<pair<int,int>>> storage(MAX+10);
	vector<int> used(N+10, -1), data(N+10,0);
	int maximum = 0, minimum = INF;

	for(int i = 0; i < N; i++){
		storage[A[i]].push_back(make_pair(i,0));
		maximum = max(maximum, A[i]);
		minimum = min(minimum, A[i]);
	}
	for(int i = minimum; i <= maximum; i++){
		for(int j = 0; j < storage[i].size(); j++){
			if(j == storage[i].size()-1){
				storage[i][j].second = storage[i][0].first + (N - storage[i][j].first);
			} else {
				storage[i][j].second = storage[i][j+1].first - storage[i][j].first;
			}
			data[storage[i][j].first] = storage[i][j].second+1;
		}
	}

	// for(int i = 0; i < N; i++){
		// cout<<"data "<<data[i]<<endl; 
	// }
	for(int i = 0, now = 0, con = 0;;){ //cout<<con<<" "<<now<<endl;
		if(used[now] != -1){
			int num = con - used[now];

			// for(;;){ cout<<"X "<<con<<" "<<num<<endl;
				// if(num+con < K)con += num;
				// else break;
			// }
			// cout<<"num "<<num<<" "<<con<<endl;
			// if((N*K-con)%num) con = N*K - (num-(N*K-con)%num);
			if((N*K-con)%num) con = N*K - (N*K-con)%num;
			else con = N*K;

			// cout<<"Y "<<con<<endl;
			now = con%N;

			for(;;){ //cout<<"Z "<<con<<endl; 
				if(data[now] + con > K){
					check(A,data,N,K,con);
					// simulation(A,N,K,con);
					break;
				} else {
					con += data[now];
				}
			}
			break;
		}
		used[now] = con;

		if(data[now] + con > K){
			check(A,data,N,K,con);
			// simulation(A,N,K,con);
			break;
		} else {
			con += data[now];
			now = (con)%N;
		}
	}
}

