using namespace std;

llint n, k;
llint a[200005], b[400005];
llint succ[200005], nx[200005];
bool used[200005];
llint cp;

int main(void)
{
	cin >> n >> k; k--;
	for(int i = 0; i < n; i++) cin >> a[i];
	for(int i = 0; i < n; i++) b[i] = b[n+i] = a[i];

	for(int i = 1; i < 200005; i++) nx[i] = 2*n;
	for(int i = 2*n-1; i >= 0; i--){
		succ[i] = nx[b[i]];
		nx[b[i]] = i;
	}
	for(int i = 0; i < n; i++) succ[i] = (succ[i]+1) % n;

	int p = 0;
	while(!used[p]){
		used[p] = true;
		p = succ[p];
	}
	cp = p;

	llint cnt = 0; p = cp;
	do{
		if(p+1 >= succ[p]) cnt++;
		if(p == n-1 && succ[p] == 0) cnt++;
		p = succ[p];
	}while(p != cp);

	p = 0;
	while(k > 0 && p != cp){
		if(p+1 >= succ[p]) k--;
		if(p == n-1 && succ[p] == 0) k--;
		p = succ[p];
	}
	if(p == cp){
		k %= cnt;
		while(k > 0){
			if(p+1 >= succ[p]) k--;
			if(p == n-1 && succ[p] == 0) k--;
			p = succ[p];
		};
	}
	if(k < 0) p = n;

	vector<llint> ans; set<llint> S;
	for(int i = p; i < n; i++){
		if(S.count(a[i])){
			while(S.count(a[i])){
				S.erase(ans.back());
				ans.pop_back();
			}
		}
		else{
			ans.push_back(a[i]);
			S.insert(a[i]);
		}
	}
	for(int i = 0; i < ans.size(); i++) cout << ans[i] << " "; cout << endl;

	return 0;
}

