const int N = 5e5 + 10;
int a[N], used[N], cnt[N];
std::vector<int> nxt[N], cur;
int32_t main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(0); std::cout.tie(0);
	ll n, k;
	std::cin >> n >> k;

	FOR(i, n) {
		std::cin >> a[i];
		nxt[a[i]].pb(i);
	}
	ll now = 0;
	ll sz = 0;
	std::vector<std::pair<ll,ll>> s;
	s.pb({0, 0});
	while (!used[now] && now < n) {
		used[now] = 1;

		auto it = std::upper_bound(nxt[a[now]].begin(), nxt[a[now]].end(), now);
		// debug(now)
		if (it == nxt[a[now]].end()) {
			sz += (n - now) + nxt[a[now]][0] + 1;
			// debug(sz)
			now = nxt[a[now]][0] + 1;
		}
		else {
			sz += (*it - now + 1);
			now = *it + 1;
		}
		// debug(now << ' ' << sz);
		s.pb({now, sz});
		// return 0;
	}
	ll times = n * k;
	times %= s.back().second;
	// debug(times)
	// return 0;
	// debug(s.back().second)
	for (int j = s.size() - 1; j >= 0; --j) {
		if (s[j].second <= times) {
			times -= s[j].second;
			assert(times <= n);
			// debug(times)
			// debug(s[j].first << ' ' << times)
			now = s[j].first;
			// return 0;
			while (times != 0) {
				if (cnt[a[now % n]] == 0) {
					cur.pb(a[now % n]);
					cnt[a[now % n]]++;
				}
				else {
					while (cnt[a[now % n]] != 0) {
						cnt[cur.back()]--;
						cur.pop_back();
					}
				}
				times--;
				now++;
			}
			break;
		}
	}
	for (auto e : cur) {
		std::cout << e << ' ';
	}
}

