using namespace std;
const int maxn=2001000;
int n,a[maxn],nxt[maxn],flag[maxn];
long long k,f[maxn][100];
vector<int> pos[maxn];
vector<int> ans;
int main()
{
	scanf("%d%lld",&n,&k);
	for(int i=1;i<=n;i++) scanf("%d",a+i),pos[a[i]].push_back(i);
	for(int i=1;i<=200000;i++) for(int j=0;j<(int)pos[i].size();j++)
	{
		if(j+1==(int)pos[i].size()) nxt[pos[i][j]]=pos[i][0]+n-pos[i][j]+1;
		else nxt[pos[i][j]]=pos[i][j+1]-pos[i][j]+1;
	}
	for(int i=1;i<=n;i++) f[i][0]=nxt[i];
	for(int j=1;j<70;j++) for(int i=1;i<=n;i++)
		f[i][j]=min(n*k+1,f[i][j-1]+f[(i+f[i][j-1]-1)%n+1][j-1]);
	long long now=1;
	for(int i=69;i>=0;i--) if(f[(now-1)%n+1][i]+now<=n*k+1) now+=f[(now-1)%n+1][i];
	for(long long i=now;i<=n*k;i++)
	{
		int val=a[(i-1)%n+1];
		if(flag[val])
		{
			while(ans[ans.size()-1]!=val) flag[ans[ans.size()-1]]=0,ans.pop_back();
			ans.pop_back();flag[val]=0;
		}
		else{ans.push_back(val);flag[val]=1;}
	}
	for(int i=0;i<(int)ans.size();i++) cout<<ans[i]<<' ';
}

