    copy_n(istream_iterator<unsigned long>(cin), N, A.begin());
    {
        auto mx = *max_element(A.cbegin(), A.cend());
        deque<unsigned long> prev(mx + 1, ~0UL);
        vector<pair<unsigned long, unsigned long>> first;
        for(unsigned long index = 0; index < N; ++index){
            const auto i = A[index];
            if(~prev[i]){
                next[prev[i]] = index;
            }else{
                first.emplace_back(index, i);
            }
            prev[i] = index;
        }
        for(const auto& i : first)next[prev[i.second]] = i.first + N;
    }

    vector<unsigned long> dist(N, ~0UL);
    deque<unsigned long> ans;
    {
        unsigned long now = 0, d = 0;
        while(!~dist[now]){
            dist[now] = d;
            auto t = next[now] + 1;
            if(t >= N){
                d += t / N;
                t %= N;
            }
            now = t;
        }
        if(d == dist[now]){
            puts("sorry...");
            return 0;
        }
        d += (K - d) / (d - dist[now]) * (d - dist[now]);
        while(d < K){
            auto t = next[now] + 1;
            if(t >= N){
                d += t / N;
                t %= N;
            }
            if(d == K)break;
            now = t;
        }
        unordered_map<unsigned long, unsigned long> mp;
        for(; now < N; ++now){
            const auto a = A[now];
            if(mp[a]){
                while(ans.back() != a)ans.pop_back();
                ans.pop_back();
            }else{
                ans.push_back(a);
            }
            mp[a] ^= 1;
        }
    }
    copy(ans.begin(), ans.end(), ostream_iterator<unsigned long>(cout, " "));
    return 0;
}

