const int N=2e5+50;
long long n,k,cir;
int a[N],inq[N],p[N],s[N];
map <int,int> mp;
vector <int> pos[N];

inline int findnxt(int i) {
	int v=a[i];
	if(inq[i]==pos[v].size()) return pos[v][0];
	else return pos[v][inq[i]];
}

inline void findans(int k) {
	int last;
	for(int i=1;i<=cir;i++)
		if(s[i]<k) last=i;
	int start=p[last];
	vector <int> q;
	map <int,int> exi;
	for(int i=start;i<=n;i++) {
		if(exi[a[i]]) {
			int u;
			do {
				u=q.back();
				q.pop_back();
				exi[u]=0;
			} while(u!=a[i]);
		} else {
			q.push_back(a[i]);
			exi[a[i]]=1;
		}
	}
	for(int i=0;i<q.size();i++)
		cout<<q[i]<<' ';
}
int main() {
	cin>>n>>k;
	for(int i=1;i<=n;i++) 
		a[i]=rd(), inq[i]=pos[a[i]].size()+1, pos[a[i]].push_back(i);
	p[1]=1; mp[1]=1;

	for(int i=2;i<=n+1;i++) {
		int nxt=findnxt(p[i-1]);
		p[i]=nxt==n ? 1 : (nxt+1);
		if(!mp[p[i]]) mp[p[i]]=i;
		else {cir=i; break;}
	}
	for(int i=2;i<=cir;i++) {
		if(p[i]>p[i-1]+1) s[i]=s[i-1];
		else s[i]=s[i-1]+1;
	}
	int round=s[cir]-s[mp[p[cir]]];
	int pre=s[mp[p[cir]]];
	if(k-1<=pre) findans(k);
	else {
		k=(k-pre-1)%round+pre+1;
		findans(k);
	}
}

