        if(spotted[nxt] != -1){
            int diff = spotted[cur] + inc - spotted[nxt];
            //cout << "difference = " << diff << endl;
            cur = nxt;
            spotted[cur] += ((k - 1 - spotted[cur]) / diff) * diff;
            //cout << "New spotted = " << spotted[cur] << endl;
