    for (int i = LOG - 1; i >= 0; i--)
    {
        while (now + add[i][now % n] <= k * n)
            now += add[i][now % n];
    }
    //printf("%lld\n", add[LOG - 1][0]);
    //printf("%lld\n", now);
    if (now == k * n)
        return 0;
    memset(idx, -1, sizeof(idx));
    top = 0;
    for (ll i = now; i <= n * k - 1; i++)
    {
        ll now = i % n;
        if (idx[a[now]] >= top || idx[a[now]] == -1)
        {
            idx[a[now]] = top;
            ans[top++] = a[now];
        }
        else
            top = idx[a[now]];
    }
    for (int i = 0; i < top; i++)
        printf("%lld ", ans[i]);
    return 0;
}

