		first[a[i]] = i;
	}
	bool skipped = false;
	int pos = 0;
	for (LL i = 0; i < k - 1; ++i) {
		while (true) {
			if (!skipped && vis[pos] >= 0) {
				skipped = true;
				LL t = i - vis[pos];
				i += ((k - i - 2) / t) * t;
			} else {
				vis[pos] = i;
			}
			int next_pos = next[pos];
			if (next_pos < 0) {
				pos = first[a[pos]] + n + 1;
			} else {
				pos = next_pos + 1;
			}
			if (pos >= n) {
				pos %= n;
				break;
			}
		}
	}
	vector<int> ans;
	for (; pos < n; ++pos) {
		int next_pos = next[pos];
		if (next_pos >= 0) {
			pos = next_pos;
		} else {
			ans.push_back(a[pos]);
		}
	}
	for (auto x : ans) {
		cout << " " << x;
	}
	cout << endl;
	return 0;
}

