void solve(void)
{
  ll N, K; cin >> N >> K;
  vector<int> A(N);
  for (auto& a : A) { cin >> a; }
  vector<int> B(A.size()*2);
  boost::copy(A, B.begin());
  boost::copy(A, B.begin()+N);
  map<int, set<int>> mp{};
  for (int i = 0; i < B.size(); ++i) {
    mp[B[i]].emplace(i);
  }

  cpp_int NK = N*K;
  int logNK = 1;
  while ((cpp_int(1) << logNK) <= NK) {
    ++logNK;
  }

  vector<vector<cpp_int>> table(logNK, vector<cpp_int>(N));
  for (int i = 0; i < N; ++i) {
    auto b = B[i];
    const auto& indexList = mp[b];
    auto itr = indexList.upper_bound(i);
    assert(itr != indexList.end());
    auto j = *itr;
    table[0][i] = (j + 1) - i;
  }

  for (ll i = 1; i < logNK; ++i) {
    for (int n = 0; n < N; ++n) {
      auto nn = table[i-1][n];
      table[i][n] = nn + table[i-1][(int)((n + nn) % N)];
    }
  }

  cpp_int itr = 0;
  for (ll b = logNK-1; b >= 0; --b) {
    auto next = itr + table[b][(int)(itr % N)];
    if (next > NK) {
      continue;
    } else {
      itr = next;
    }
  }

  vector<int> buff{};
  buff.reserve(N*2);
  set<int> st{};
  for (cpp_int i = itr; i < NK; ++i) {
    auto a = A[(int)(i%N)];
    if (st.count(a)) {
      while (st.count(a)) {
        st.erase(buff.back());
        buff.pop_back();
      }
    } else {
      buff.push_back(a);
      st.emplace(a);
    }
  }
  for (int i = 0; i < buff.size(); ++i) {
    if (i)
      cout << SPACE << buff[i];
    else
      cout << buff[i];
  }
  cout << CRLF;
  return;
}

