void dfs(int p, int t, int k, int n) {
    if(pass[p] and t < k) {
        t += (k - t) / (t - pass[p]) * (t - pass[p]);
        memset(pass, 0, sizeof(pass));
    }
    pass[p] = t;
    if(t >  k) return;
    if(t == k) {
        vector<int> que; set<int> s;
        for(int i = p; i < n; i ++) {
            if(s.count(v[i])) {
                while(s.count(v[i])) s.erase(que.back()), que.pop_back();
            }
            else que.push_back(v[i]), s.insert(v[i]);
        }
        for(auto it: que) cout << it << ' ';
        return;
    }
    if(ptr[p] == p and p == n - 1) dfs((ptr[p] + 1) % n, t + 2, k, n);
    else                           dfs((ptr[p] + 1) % n, t + 1, k, n);
}
