void input(){
  cin>>N>>K;
  rep(i,N){
    cin>>A[i];
    A[i]--;
    lis[A[i]].pb(i);
  }
}
int nex[MAX];
int up[MAX];
vi loop, ct;
int t;
int start;
void solve(){
  rep(j,MAX){
    int s=sz(lis[j]);
    rep(i,s){
      int ind=lis[j][i];
      int nexto=i+1;
      if(nexto==s){
        up[ind]++;
        nexto=0;
      }
      int nextind=lis[j][nexto]+1;
      nex[ind]=nextind%N;
    }
  }
  int tmpind=0;
  int tmpct=0;
  while(true){
    loop.pb(tmpind);
    ct.pb(tmpct);
    tmpct+=up[tmpind];
    tmpind=nex[tmpind];
    if(tmpind==0)break;
  }
  t=tmpct+1;
  ll r=K%(ll)t;
  if(r==0)start=N;
  else{
    rep(i,sz(ct)){
      if((ll)ct[i]>=r)break;
      start=loop[i];
    }
  }
}

deque<int> ans;
bool in[MAX];
