  for(int i=start; i<N; i++){
    if(in[A[i]]){
      while(true){
        int p=ans.back();
        ans.pop_back();
        if(p==A[i])break;
      }
      in[A[i]]=false;
    }
    else{
      ans.push_back(A[i]);
      in[A[i]]=true;
    }
  }
  while(!ans.empty()){
    cout<<ans.front()+1<<" ";
    ans.pop_front();
  }
}

