inline int getInt(){ int s; scanf("%d", &s); return s; }
inline ll getLL(){ ll s; scanf("%lld", &s); return s; }

int main(){
  const int n = getInt();
  const ll k = getLL();
  vector<int> a(n);
  REP(i,n) a[i] = getInt();

  map<int, int> m;
  vector<int> next(n);
  REP(_,2){
    REP(j,n){
      const int i = n - 1 - j;
      next[i] = m[a[i]];
      m[a[i]] = i;
    }
  }

  vector<ll> dp(n, -1);
  int index = 0;
  ll loop = 0;

  while(true){
    // printf("!%d %d\n", loop, index);
    if(loop == k - 1){
      break;
    }
    if(dp[index] != -1){
      const ll lastLoop = dp[index];
      const ll diff = loop - lastLoop;
      loop += diff * ((k - 1 - loop) / diff);
      while(loop < k - 1){
	const int i = next[index];
	if(i <= index || i == n - 1) loop++;
	if(i == n - 1 && index == n - 1) loop++;
	index = (i + 1) % n;
      }
      break;
    }else{
      dp[index] = loop;

      const int i = next[index];
      if(i <= index || i == n - 1) loop++;
      if(i == n - 1 && index == n - 1) loop++;
      index = (i + 1) % n;
    }
  }

  set<int> s;
  vector<int> ans;
