    Vint Nxt_Index(n, -1); // 次のの場所をさす : x -> x の位置をさす
    int Loop = 0; lli b = 0; // ループの回数
    int Tidx = 0; // 考えているインデックス : 初めは 0 から
    while(true){
        // 訪れた頂点がきた場合
        if(ComeLoop[Tidx] != -1){
            break;
        }
        // 初めて訪れる頂点の場合
        else{
            ComeLoop[Tidx] = Loop;
            int val = A[Tidx];
            int end_idx; // 空集合になる頂点
            // 重複がない場合
            if(false){//Indexes[val].size() == 1){
                b += n;
                end_idx = Tidx;
                Loop++;
            }
            else{ // 重複 : 同じ数字が使われる場合
                if(Indexes[val].back() == Tidx){ // 末尾要素の場合
                    end_idx = Indexes[val].front();
                    b += (n - Tidx) + end_idx + 1;
                    Loop++;
                }
                else{
                    int inDex = std::lower_bound(ALL(Indexes[val]), Tidx) - Indexes[val].begin();
                    end_idx = Indexes[val][inDex + 1];
                    b += end_idx - Tidx + 1;
                    if(end_idx == n - 1) Loop++;
                }
            }
            Nxt_Index[Tidx] = end_idx;
            Tidx = (end_idx + 1) % n;
        }
    }
    lli M = n * k; // 空集合になってもどってくる
    if(M < b){
        int v = 0;
        while(true){
            int v2 = Nxt_Index[v];
            int cost = (v < v2) ? v2 - v + 1 : (n - v) + v2 + 1;
            if(M < cost) break;
            M -= cost; v = (v2 + 1) % n;
        }
        REP(i, M){
            printf("%d", A[(v + i) % n]);
            putchar(i == M - 1 ? '\n' : ' ');
        }
    }
    if(M > b){
        //cout << b << BR;
        M -= b;
        int LOOP = Loop - ComeLoop[Tidx]; // 何周して戻ってくるか
        M %= (LOOP * n);
        int v = Tidx;
        while(true){
            int v2 = Nxt_Index[v];
            int cost = (v < v2) ? v2 - v + 1 : (n - v) + v2 + 1;
            if(M < cost) break;
            M -= cost; v = (v2 + 1) % n;
        }
        REP(i, M){
            printf("%d", A[(v + i) % n]);
            putchar(i == M - 1 ? '\n' : ' ');
        }
    }
    return 0;
}

