const int N = 2e6 + 10;
const int mod = 998244353;

inline int fpow (int a, int b) {
	int ret = 1;
	while (b) {
		ret = 1ll * ret * a % mod;
		a = 1ll * a * a % mod;
		b >>= 1;
	}
	return ret;
}

int f[N], invf[N];

void predeal (int n) {
	f[0] = invf[0] = 1;
	for (int i = 1; i <= n; i++) {
		f[i] = 1ll * f[i - 1] * i % mod;
	}
	invf[n] = fpow(f[n], mod - 2);
	for (int i = n - 1; i >= 1; i--) {
		invf[i] = 1ll * invf[i + 1] * (i + 1) % mod; 
	}
}

inline int C (int n, int m) {
	return 1ll * f[n] * invf[m] % mod * invf[n - m] % mod;
}

int main (void) {
	predeal(2e6);

	int n, m, ans = 0;
	scanf("%d%d", &n, &m);
	for (int i = 0; i <= m; i++) {
		if ((m - i) & 1) continue;
		ans += 1ll * C(n, i) * C((3 * m - i) / 2 + n - 1, n - 1) % mod;
		cout << 1ll * C(n, i) * C((3 * m - i) / 2 + n - 1, n - 1) % mod << endl;
		if (ans >= mod) ans -= mod;
	}
	for (int i = 0; i < m; i++) {
		if ((m - 1 - i) & 1) continue;
		ans -= 1ll * C(n, 1) * C(n, i) % mod * C((m - 1 - i) / 2 + n - 1, n - 1) % mod;
		cout << 1ll * C(n, 1) * C(n, i) % mod * C((m - 1 - i) / 2 + n - 1, n - 1) % mod << endl;
		if (ans < 0) ans += mod;
	}
	printf("%d\n", ans);
}

