ll dp[214514][62];
int n;
ll gbis_special(ll cur, ll lim){
	if( cur + dp[ (cur%n) ][0] > lim) return cur;
	ll cnt = 0;
	while( cur + dp[ (cur%n) ][cnt+1] <= lim){
		cnt++;
	}
	cur += dp[ (cur%n) ][cnt];
	return gbis_special(cur,lim);
}
int main(){
