vector<lint> A;

void simulate(lint n, lint offset)
{
    set<lint> shown;
    vector<lint> ret;
    REP(i, n)
    {
        lint a = A[(i + offset) % A.size()];
        if (shown.count(a))
        {
            while (ret.back() != a)
            {
                shown.erase(ret.back());
                ret.pop_back();
            }
            shown.erase(ret.back());
            ret.pop_back();
        }
        else
        {
            shown.insert(a);
            ret.push_back(a);
        }
    }
    REP(i, ret.size()) printf("%lld ", ret[i]);
    puts("");
    exit(0);
}

int main()
{
    lint N, K;
    cin >> N >> K;
    A.resize(N);
    cin >> A;

    vector<int> nx(2 * N, N); // 何個先に同じのが出るか
    map<int, int> last_shown;
    IREP(i, N * 2)
    {
        if (last_shown.count(A[i % N]))
        {
            nx[i] = last_shown[A[i % N]] - i;
        }
        last_shown[A[i % N]] = i;
    }
    set<lint> h;
    lint now = 0;
    lint d0 = 0;
    while (true)
    {
        if (N * K - d0 < 1e6) simulate(N * K - d0, d0 % N);
        if (h.count(now)) break;
        h.insert(now);
        now = (now + nx[now] + 1) % N;
        d0 += nx[now] + 1;
    }

    lint circ = 0;
    lint tmp = now;
    while (true)
    {
        circ += nx[tmp] + 1;
        tmp = (tmp + nx[tmp] + 1) % N;
        if (tmp == now) break;
    }

    {
        lint now = d0 % N;
        lint rem = (N * K - d0) % circ;
        while (true)
        {
            if (rem < 1e6) simulate(rem, now);
            lint d = nx[now] + 1;
            now = (now + d) % N;
            rem -= d;
        }
    }
}

