int next(int u){
	startr[u]=cnt;

	set<ll>::iterator it = ind[arr[u]].upper_bound(u);
	if(it!=ind[arr[u]].end()) return *it;

	cnt++;
	return *ind[arr[u]].lower_bound(0);
}

