#include <bits/stdc++.h>
using namespace std;

int64_t dp[60][2000010];
int main() {
	const int64_t INF = 1e18 / 3;
	int64_t n, k; cin >> n >> k;
	int a[n]; for(int i = 0; i < n; ++i) cin >> a[i];
	int pre[200010]; for(int i = 0; i < 200010; ++i) pre[i] = -1;
	// dp[j][i] := iから2^j回遷移したときの消費回数
	for(int i = 0; i < 2 * n; ++i) {
		if(pre[a[i % n]] != -1) {
			dp[0][pre[a[i % n]]] = (i + 1) - pre[a[i % n]];
		}
		pre[a[i % n]] = i;
	}
	for(int j = 1; j < 60; ++j) {
		for(int i = 0; i < n; ++i) {
			dp[j][i] = min(dp[j - 1][i] + dp[j - 1][(i + dp[j - 1][i]) % n], INF);
		}
	}
	int64_t goal = n * k;
	int64_t now = 0;
	while(true) {
		bool flg = true;
		for(int j = 59; j >= 0; --j) {
			if(dp[j][now % n] == INF) continue;
			if(now + dp[j][now % n] < goal) {
				now += dp[j][now % n];
				flg = false;
				break;
			}
		}
		if(flg) break;
	}
	deque<int> ans;
	bool used[200010] = {};
	cerr << now % n << endl;
	for(int i = now % n; i < n; ++i) {
		if(used[a[i]]) {
			while(ans.size()) {
				int t = ans.back();
				ans.pop_back();
				used[t] = false;
				if(t == a[i]) break;
			}
		} else {
			ans.push_back(a[i]);
			used[a[i]] = true;
		}
	}
	for(int i : ans) {
		cout << i << " ";
	}
	cout << "\n";
	return 0;
}

