ll jump[200005];
ll cycle_cnt = 0;
ll ans[200005];
int ansl = 0;
int chk[200005];
ll step[200005];
int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    for(int i=0;i<n;i++)
    {
        cin >> a[i];
        cnt[a[i]].push_back(i);
    }
    for(int i=1;i<=200000;i++)
    {
        for(int x=0;x<cnt[i].size();x++)
        {
            int nxt = (x == cnt[i].size() - 1 ? cnt[i].front() : cnt[i][x+1]);
            if(nxt == cnt[i][x])
            {
                jump[cnt[i][x]] = n+1;
            }
            else jump[cnt[i][x]] = (nxt-cnt[i][x]+n) % n + 1;
            //cout << "jump " << cnt[i][x] << ' ' << jump[cnt[i][x]] << '\n';
        }

    }

    memset(step, -1, sizeof(step));
    while(step[cycle_cnt % n] == -1)
    {
        step[cycle_cnt % n] = cycle_cnt;
        cycle_cnt += jump[cycle_cnt % n];
    }
    ll offset = step[cycle_cnt % n];
    ll looping = cycle_cnt - step[cycle_cnt % n];

    //cout << offset << ' ' << looping << endl;
    ll target = n * k;
    if(target > offset)
    {
        target -= offset;
        target %= looping;
        target += offset;
    }
    cycle_cnt = 0;
    while(1)
    {
        if(cycle_cnt + jump[cycle_cnt % n] < target)
        {
            cycle_cnt += jump[cycle_cnt % n];
        }
        else break;
    }
    //cout << cycle_cnt << '\n';
    while(cycle_cnt < target)
    {
        if(chk[a[cycle_cnt % n]])
        {
            while(ansl)
            {
                ansl--;
                chk[ans[ansl]]--;
                //cout << "chk " << ans[ansl] << '\n';
                if(ans[ansl] == a[cycle_cnt%n]) break;
            }
        }
        else
        {
            //cout << "add " << a[cycle_cnt % n] << '\n';
            ans[ansl++] = a[cycle_cnt % n];
            chk[a[cycle_cnt % n]]++;
        }
        cycle_cnt++;
    }
    for(int i=0;i<ansl;i++)
        cout << ans[i] << " "[i != ansl-1];
}

