  for (int i = n - 1; i >= 0; i--)
  {
    if (near_index[a[i]] == 0)
    {
      next[i] = a[i];
    }
    else if (next[near_index[a[i]]] == n - 1)
    {
      next[i] = 0;
    }
    else
    {
      next[i] = next[near_index[a[i]] + 1];
    }
    near_index[a[i]] = i;
  }

  f[0] = second == 0 ? a[0] : next[second + 1];
  REP(i, n)
  {
    if (f[a[i]] != 0)
      continue;
    f[a[i]] = next[min_index[a[i]] + 1];
  }

  ll loop = 1;
  int tmp = f[0];
  REP(i, n)
  {
    if (tmp == 0)
      break;
    tmp = f[tmp];
    loop++;
  }

  // 解の構成
  tmp = 0;
  for (int i = 0; i < ((k - 1) % loop); i++)
  {
    tmp = f[tmp];
  }
  int init_index = tmp == 0 ? 0 : min_index[tmp] + 1;

  vector<int> ans;
  for (int i = init_index; i < n; i++)
  {
    bool updated = false;
    while (!q[a[i]].empty())
    {
      int po = q[a[i]].top();
      q[a[i]].pop();
      if (po > i)
      {
        i = po;
        updated = true;
        break;
      }
    }
    if (!updated)
    {
      ans.push_back(a[i]);
    }
  }

  REP(i, ans.size())
  {
    cout << ans[i];
    if (i != ans.size() - 1)
    {
      cout << " ";
    }
  }
  cout << endl;
}

