#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll INF = 1e18;

int main() {
  ll n, k;
  cin >> n >> k;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }
  for (int i = 0; i < n; i++) {
    a.push_back(a[i]);
  }

  ll nk = n * k;
  int lognk = 0;
  for (int t = nk; t > 1; t >>= 1) lognk++;

  map<int, int> nxt;
  vector<vector<ll>> dbl(lognk + 1, vector<ll>(n, INF));
  for (int i = 2 * n - 1; i >= 0; i--) {
    if (i < n) dbl[0][i] = nxt[a[i]] - i + 1;
    nxt[a[i]] = i;
  }

  for (int k = 0; k < lognk; k++) {
    for (int i = 0; i < n; i++) {
      if (dbl[k][i] == INF) continue;
      dbl[k + 1][i] = dbl[k][i] + dbl[k][(i + dbl[k][i]) % n];
      if (dbl[k + 1][i] > INF) dbl[k + 1][i] = INF;
    }
  }

  ll p = 0;
  for (int k = lognk - 1; k >= 0; k--) {
    if (p + dbl[k][p % n] > nk) continue;
    p += dbl[k][p % n];
  }

  vector<int> ans;
  set<int> st;
  for (int i = p; i < nk; ++i) {
    int x = a[i % n];
    if (st.find(x) != end(st)) {
      while (st.find(x) != end(st)) {
        st.erase(ans.back());
        ans.pop_back();
      }
    } else {
      ans.push_back(x);
      st.insert(x);
    }
  }

  for (int i = 0; i < ans.size(); i++) {
    cout << ans[i] << ((i + 1 == ans.size()) ? '\n' : ' ');
  }
}

