        pos[a[i]].push_back(i);
    }

    vector<int> nxt(n, -1);
    vector<bool> last(n);
    for(auto const& p : pos) {
        auto const& ps = p.second;
        const int sz = ps.size();
        for(int i = 0; i < sz; ++i) {
            nxt[ps[i]] = ps[(i + 1) % sz];
        }
        last[ps.back()] = true;
    }

    vector<int> seq;
    int p = 0;
    while(true) {
        int s = p;
        while(!last[p]) {
            p = (nxt[p] + 1) % n;
            if(p == s) return 0;
        }
        if(!seq.empty() && seq[0] == p) break;
        seq.push_back(p);
        p = (nxt[p] + 1) % n;
    }

    if(k % (seq.size() + 1) == 0) { // empty
        return 0;
    }

    vector<int> ans;
