    while (cin >> n >> k)
    {
        vector<int> a(n);
        for (int &x : a)
            cin >> x;

        vector<int> stck;
        map<int, int> where;

        map<vector<int>, int> when;

        for (long long i = 0; i < k; i++)
        {
            for (int x : a)
            {
                auto it = where.find(x);
                if (it != where.end())
                {
                    const int pos = it -> second;
                    for (int j = pos; j < sz(stck); j++)
                        where.erase(stck[j]);
                    stck.resize(pos);
                }
                else
                {
                    where[x] = sz(stck);
                    stck.push_back(x);
                }
            }

            if (when.count(stck))
            {
                const int cycle = i - when[stck];
                const long long skips = (k - i) / cycle;
                i += skips * cycle;
            }
            else
            {
                when[stck] = i;
            }
        }

        for (int x : stck)
            cout << x << ' ';
        cout << endl;
    }
}

