{
    long long N, K;
    cin >> N >> K;

    vector<long long> A(N);
    for (long long &a : A)
    {
        cin >> a;
    }

    vector<vector<long long>> dp(N);
    vector<long long> current;
    map<long long, long long> m;
    for (long long i = N - 1; i >= 0; i--)
    {
        if (m.find(A[i]) == m.end())
        {
            current.push_back(A[i]);
        }
        else
        {
            long long idx = m[A[i]] + 1;

            if (idx >= N)
            {
                current = vector<long long>();
            }
            else
            {
                current = dp[idx];
            }
        }
        dp[i] = current;
        m[A[i]] = i;
    }

    long long loop = -1;
    vector<vector<long long>> ans(N + 1);
    ans[0] = vector<long long>();
    ans[1] = current;

    for (long long i = 2; i <= N; i++)
    {
        if (current.empty())
        {
            current = dp.front();
        }
        else
        {
            long long idx = m[current.back()] + 1;
            if (idx >= N)
            {
                current = vector<long long>();
            }
            else
            {
                current = dp[idx];
            }
        }

        ans[i] = current;
        if (loop == -1 && current.empty())
        {
            loop = i;
            break;
        }
    }

    if (loop == -1)
    {
        K = K;
    }
    else
    {
        K %= loop;
    }
    for (auto itr = ans[K].rbegin(); itr != ans[K].rend(); itr++)
    {
        cout << *itr << " ";
    }
    cout << endl;
}

