int debug = 0;

const int N = 3e5, LG = 60;

int n, k, m, pos, INF = 5e17;
int a[N], go[LG][N], sm[LG][N], lst[N], f[N];
vector <int> st;

main() {
    scanf("%lld%lld", &n, &k);
    rep(i, 0, n) {
        scanf("%lld", &a[i]);
        lst[a[i]] = i;
    }
    rep(i, 0, n) {
        go[0][lst[a[i]]] = (i + 1) % n;
        sm[0][lst[a[i]]] = (i + n - lst[a[i]] - 1) % n + 2;
        lst[a[i]] = i;
    }
    if (debug) {
        rep(i, 0, n) {
            cerr << "       i=" << i << ' ' << go[0][i] << ' ' << sm[0][i] << '\n';
        }
    }
    rep(j, 1, LG) {
        rep(i, 0, n) {
            go[j][i] = go[j - 1][go[j - 1][i]];
            sm[j][i] = min(sm[j - 1][i] + sm[j - 1][go[j - 1][i]], INF);
        }
    }
    m = n * k;
    pos = 0;
    if (debug) { cerr << "ok\n"; }
    for (int j = LG - 1; j >= 0; --j) {
        while (sm[j][pos] <= m) {
            m -= sm[j][pos];
            pos = go[j][pos];
        }
    }
    if (debug) { cerr << "kek\n" << ' ' << m << '\n'; }
    fill(f, f + N, 0);
    while (m--) {

        if (debug) { cerr << " m=" << m << ' ' << pos << ' ' << a[pos] << '\n'; }
        if (f[a[pos]] == 0) {
            st.push_back(a[pos]);
            f[a[pos]] = 1;
        } else {

            while (st.back() != a[pos]) {
                    if (debug) { cerr << st.back() << ' ';}
                st.pop_back();
            }
            st.pop_back();
            f[a[pos]] = 0;
        }
        pos = (pos + 1) % n;
    }
    if (debug) { cerr << "fin\n"; }
    for (auto i : st) {
        printf("%lld ", i);
    }
}

