const int N = 2e5 + 5;
const int LOG = 60;

int n;
long long k;
vector<int> a;
long long nxt[LOG][N];
int lst[N];

long long curt = 0;
vector<int> ans;

int main() {
    ios::sync_with_stdio(0);
    srand(time(0));
    cin >> n >> k;
    a.resize(n);
    cin >> a;
    for (int i = 0; i < n; ++i) {
        a.pb(a[i]);
        lst[i] = -1;
    }
    for (int i = 0; i < n * 2; ++i) {
        if (lst[a[i]] != -1) {
            if (lst[a[i]] < n) {
                nxt[0][lst[a[i]]] = i - lst[a[i]];
            }
        }
        lst[a[i]] = i;
    }
    for (int t = 0; t + 1 < LOG; ++t) {
        for (int i = 0; i < n; ++i) {
            long long j = (i + nxt[t][i] + 1) % n;
            nxt[t + 1][i] = nxt[t][i] + 1 + nxt[t][j];
            chkmin(nxt[t + 1][i], n * k + 1);
        }
    }
    // cout << nxt[0][0] << endl;
    curt = 0;
    while (curt < n * k) {
        int i = curt % n;
        for (int t = LOG; t--;) {
            long long v = nxt[t][i];
            if (curt + v < n * k) {
                curt += v + 1;
                i = curt % n;
            }
        }
        if (curt < n * k) {
            ans.pb(a[i]);
            ++curt;
        }
    }
    cout << ans << '\n';
}

