void solve(){
    int N; cin >> N;
    LL K; cin >> K;
    int max_k = log2(N*K);

    map<int,VI> key_id; //key_id

    VLL tmp(N,-1);
    DPRINT(max_k)
    vector<VLL> next(max_k+1,tmp);

    // input, next[0][]
    VI A(N*2);
    REP(i,2*N){
        if(i<N){
            cin >> A[i];
            A[N+i]=A[i]; // 1 2 3 2 3 1 2 3 2 3
        }
        // same exist before
        if(key_id.count(A[i])!=0){
            int id = key_id[A[i]].back(); //- - - 1 2, 0 3 4 ..  
            DPRINT(id)
            if (id<N) next[0][id] = i - id + 1;
        }
        // add key
        key_id[A[i]].PB(i);
         //several id for one key
    }
    // doubling
    REP(k,max_k){
        DPRINT(k)
        REP(i,N){
            LL nowid = i + next[k][i];
            DPRINT(nowid)
            LL nextid = nowid + next[k][nowid%N];
           // DPRINT(nextid)
            next[k+1][i] = nextid - i;
            //DPRINT(nextid)
        }
    }
    //change out of range to -1
    REP(k,max_k){
        REP(i,N){
            if(next[k][i]+i > N*K) next[k][i] = -1;
        }
    }

    //start from id = 0
    LL gid = 0; // global id
    CIREP(k,max_k,0){
        DPRINT(k)
        int id = gid%N; // id in a Line
        LL nextid = gid + next[k][id];
        //DPRINT(nextid)
        if(next[k][id]!=-1 && nextid < N*K){
            gid = nextid;
        }
        //DPRINT(id)
    }

    // Do as the task
    int id = gid%N;
    DPRINT(id)
    VI ans;

    CREP(i,id,N-1){
        //already deleted
        int stop = next[0][i]+i-1;

        if(next[0][i]==-1){
            continue;
        }

        //do not appear
        if(stop >= N){
            DPRINT(i)
            int a = A[i];
            //ans.PB(A[i]);
        }
        //appear

        else{
            CREP(j,i,stop){
                DPRINT(j)
                next[0][j] = -1; //delete
            }
        }

    }
    REP(i,SZ(ans)) cout<<ans[i]<< " ";
    cout << endl;

}



