int nx[MAX_P][MAX_N];

signed main(void){ 

  int N,K;cin >> N >> K;

  for(int i = 0; i < N; i++){ cin >> A[i]; A[i+N] = A[i]; A[i+2*N] = A[i];}
  // next[0][i]を組み立てる

  map<int,int> mp;

  for(int i = 3*N-1; i >= 0; i--){
    int a = A[i];
    if( mp[a] > 0 ){ //
      if( i >= 2*N ){ mp[a] = i;}
      else{ nx[0][i] = mp[a]-i; mp[a] = i;}
    }
    else{
      mp[a] = i;
    }
  }

  for(int i = 0; i < N; i++){ nx[0][i]++;}


  //nxはイテレータではなく距離であることに注意

  for(int k = 1; k < MAX_P; k++){ 
    for(int i = 0; i < N; i++){
     nx[k][i] = nx[k-1][i]+nx[k-1][(nx[k-1][i]+i)%N];
    }
  }
  //ダブリング


  if(false){
  for(int i = 0; i < N; i++){ cout << nx[0][i] << " ";}
  cout << endl;
  }



  //確かめる //ここまでおk





  int pos = 0; //これは実際の位置

  while( pos < N*K ){
    int r = -1;
    while( pos+nx[r+1][pos%N] < N*K ){ r++;}
    if( r == -1 ){ break;} //もうこの先はダブリング使う必要なし
    pos += nx[r][pos%N]; //この時点で、posはギリギリN*Kを超えていない


  }

  //posより先は愚直に計算
  vector<int> vec;
  vector<int> used(MAX_N,-1);

  for(int i = pos; i < N*K; i++){

    int x = A[i%N];

    if(used[x] != -1){ //xまで消す


      // 長さ i - used[x] 回分は消去したい

      int res = i-used[x];
      for(int j = 0; j < res ; j++){ 
        int y = *vec.rbegin();
        used[y] = -1; 

        vec.pop_back();
        if( vec.empty() ){ break;}
      }

      used[x] = -1;

    }//if



    else{ used[x] = i;  vec.push_back(x);} 
    //ここでいちいち全部消していたのがまずい ここさえ直せばどうにかなるはず
  }

  for(auto ans : vec){ cout << ans << " ";}
  cout << endl;

  return 0;
}

