using namespace std;
using ll = long long;

int main() {
	int n; ll k; scanf("%d %lld", &n, &k);
	vector<int> arr(n);
	for (int i = 0; i < n; ++i) scanf("%d", &arr[i]);
	vector<int> nextAppear(n, -1), lengthToNext(n, -1);
	map<int, int> occ;
	for (int i = n - 1; i >= 0; --i) {
		if (occ.count(arr[i]) > 0) {
			nextAppear[i] = (occ[arr[i]] + 1) % n;
			lengthToNext[i] = occ[arr[i]] + 1 - i;
//			printf("LTN %d = %d\n", i, lengthToNext[i]);
		}
		occ[arr[i]] = i;
	}
	for (int i = 0; i < n; ++i) {
		if (nextAppear[i] == -1) {
			nextAppear[i] = (occ[arr[i]] + 1) % n;
			if (occ[arr[i]] == i) {
				lengthToNext[i] = n + 1;
			} else {
				lengthToNext[i] = n - (i - occ[arr[i]]) + 1;
			}
//			printf("LTN %d = %d\n", i, lengthToNext[i]);
		}
	}
	vector<vector<ll>> totalJumpLen(60, vector<ll>(n, 0));
	for (int i = 0; i < n; ++i) totalJumpLen[0][i] = lengthToNext[i];
	for (int js = 1; js < 60; ++js) {
		for (int i = 0; i < n; ++i) {
			int halfJTarget = (i + totalJumpLen[js-1][i]) % n;
			totalJumpLen[js][i] = totalJumpLen[js-1][i] + totalJumpLen[js-1][halfJTarget];
			if (totalJumpLen[js][i] >= n * k) totalJumpLen[js][i] = n * k;
		}
	}
	ll targetLength = n * (k - 1);
	ll cLenCover = 0; 
	// make jumps as long as cLenCover <= targetLength
	int cidx = 0;
	for (int js = 59; js >= 0; --js) {
		if (cLenCover + totalJumpLen[js][cidx] <= targetLength) {
//			printf("executing jump %lld\n", 1LL << js);
//			printf("length %lld\n", totalJumpLen[js][cidx]);
			cLenCover += totalJumpLen[js][cidx];
			cidx = (cidx + totalJumpLen[js][cidx]) % n;
//			printf("now crossed %lld\n", cLenCover);
		}
	}
	multiset<int> curSetIn;
	vector<int> sequence;
	auto popElement = [&curSetIn, &sequence] () {
		curSetIn.erase(curSetIn.find(sequence.back()));
		sequence.pop_back();
	};
	auto addElement = [&curSetIn, &sequence] (int x) {curSetIn.insert(x); sequence.push_back(x);};
//	printf("jumped to %lld\n", cLenCover);
	for (ll i = cLenCover; i < n * k; ++i) {
		if (curSetIn.find(arr[i % n]) == curSetIn.end()) addElement(arr[i % n]);
		else {
			while (sequence.back() != arr[i % n]) popElement();
			popElement();
		}
	}
	for (int x : sequence) printf("%d ", x);
	printf("\n");
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int N = 300 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;
const int L = 63;

using ll = unsigned long long;

int n;
long long K;
int a[N + N], nx[N + N];
vector<int> vec[N];
ll up[N][L];

bool read() {
    if (!(cin >> n >> K))
        return false;

    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        a[n + i] = a[i];
    }

    return true;
}

void solve() {
    for (int i = 0; i < n + n; ++i)
        vec[a[i]].emplace_back(i);

    for (int i = 0; i < n; ++i) {
        nx[i] = *upper_bound(vec[a[i]].begin(), vec[a[i]].end(), i);
        up[i][0] = nx[i] - i + 1;
    }

    for (int j = 1; j < L; ++j)
        for (int i = 0; i < n; ++i) {
            ll d1 = up[i][j - 1];
            ll i1 = i + d1;
            ll d2 = up[i1 % n][j - 1];
            ll res = 0ull;

            if (d1 != 0 && d2 != 0 && !__builtin_uaddll_overflow(d1, d2, &res))
                up[i][j] = res; // pizdec spasibo blackav
            else
                up[i][j] = 0;
        }

        ll cur = 0;

        for (int j = L - 1; j >= 0; --j) {
            auto i = cur % n;
            ll res = 0ull;

            if (up[i][j] != 0 && !__builtin_uaddll_overflow(cur, up[i][j], &res) && res < K * n)
                cur = res;
        }

        assert(cur / n == K - 1);
        vector<int> res;

        for (int i = cur % n; i < n; )
            if (nx[i] < n) {
                i = nx[i] + 1;
            } else {
                res.emplace_back(a[i++]);
            }

        for (const auto& i : res)
            cout << i << ' ';

        cout << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

