        do {
            int now_i = v[now];
            auto it = upper_bound(index[now_i].begin(), index[now_i].end(), now);
            int next = (*it) + 1;
            if (next >= n) {
//                printf("%d %d\n", start, next % n);
                doubling.set_next(start, next % n);
                start = next % n;
            }
