vector<lint> A;

void simulate(lint n)
{
    set<lint> shown;
    vector<lint> ret;
    REP(i, n)
    {
        lint a = A[i % A.size()];
        if (shown.count(a))
        {
            while (ret.back() != a)
            {
                shown.erase(ret.back());
                ret.pop_back();
            }
            shown.erase(a);
            ret.pop_back();
        }
        else
        {
            shown.insert(a);
            ret.push_back(a);
        }
    }
    REP(i, ret.size()) printf("%lld ", ret[i]);
    puts("");
}

int main()
{
    lint N;
    cin >> N;
    lint K;
    cin >> K;
    A.resize(N);
    cin >> A;
    vector<int> nx(2 * N, N); // 何個先に同じのが出るか
    map<int, int> last_shown;
    IREP(i, N * 2)
    {
        if (last_shown.count(A[i % N]))
        {
            nx[i] = last_shown[A[i % N]] - i;
        }
        last_shown[A[i % N]] = i;
    }
    set<int> h;
    int now = 0;
    lint d0 = 0;
    while (true)
    {
        if (h.count(now)) break;
        h.insert(now);
        now = (now + nx[now] + 1) % N;
        d0 += nx[now] + 1;
    }
    if (d0 > N * K)
    {
        simulate(N * K);
        return 0;
    }
    lint circ = 0;
    int tmp = now;
    while (true)
    {
        circ += nx[tmp] + 1;
        tmp = (tmp + nx[tmp] + 1) % N;
        if (tmp == now) break;
    }
    simulate((N * K - d0) % circ + d0);
}

