            int u = rec[i][j], v = rec[i][(j+1)%rec[i].size()];
            int diff = v - u + N;
            if(diff > N) diff -= N;
            nxt[u] = make_pair(diff + 1, (v+1)%N);
        }
    }

    ll sum = 0;
    {
        int pos = 0;
        while(true) {
            int cnt, nidx; tie(cnt, nidx) = nxt[pos];
            sum += cnt;

            if(nidx == 0) break;
            pos = nidx;
        }
    }

    ll ope = N*K % sum;
    ll cur = 0;
    while(true) {
        int cnt, nidx; tie(cnt, nidx) = nxt[cur];
        if(ope - cnt >= 0) {
            ope -= cnt;
            cur = nidx;
        }
        else break;
    }

    vector<int> vec, cnt(200010);
    while(ope--) {
        if(cnt[ A[cur] ] == 0) {
            vec.emplace_back(A[cur]);
            cnt[ A[cur] ]++;
        }
        else {
            while(cnt[ A[cur] ] > 0) {
                int num = vec.back();
                cnt[num]--;
                vec.pop_back();
            }
        }
        (cur += 1) %= N;
    }

    for(size_t i=0; i<vec.size(); i++) {
        printf("%d%c", vec[i], i+1 == vec.size() ? '\n' : ' ');
    }
    return 0;
}

