    for (int t=1; t<=k; ++t){
        for (int i=1; i<=n; ++i){
            if (!cnt[a[i]]){
                ++cnt[a[i]];
                s[++tot] = a[i];
            }
            else {
                while (cnt[a[i]]){
                    --cnt[s[tot--]];
                }
