vec pmul(vec a,vec b){
    vec ret(a.size());
    REP(i,a.size()){
        ret[i]=a[b[i]];
    }
    return ret;
}
vec ppow(vec a,ll n){
    vec ret(a.size());
    REP(i,a.size())ret[i]=i;
    while(n){
        if(n&1){
            ret=pmul(ret,a);
        }
        a=pmul(a,a);
        n>>=1;
    }
    return ret;
}
