vector<int> go(int N, ll K, const vector<ll> A, int start) {
    map<ll, int> s;
    vector<int> stk;
    for(ll i = start; i < N * K; i++) {
        ll a = A[i % N];
        if(s[a] > 0) {
            int sa = s[a];
            while(stk.size() >= sa) {
                s[stk.back()] = 0;
                stk.pop_back();
            }
        } else {
            stk.push_back(a);
            s[a] = stk.size();
        }
        // cerr << i << ": " << stk << endl;
    }
    return stk;
}

int main() {
    int N; ll K; cin >> N >> K;
    vector<ll> A(N); cin >> A;

    vector<int> next_index(N);
    map<ll, int> last;
    for(int i = N * 2 - 1; i >= 0; i--) {
        if(i < N) next_index[i] = last[A[i]];
        last[A[i%N]] = i % N;
    }
    //debug(next_index);
    ull left = K * N;
    map<int, int> visited;
    vector<ull> log;
    int now = 0;
    while(left) {
        if(visited.count(now)) {
            // cerr << "LOOP at " << now << endl;
           ull sum = 0;
            repeat(i, visited[(now-1+N)%N], log.size()) sum += log[i];
            // cerr << "sum = " << sum << " left = " << left << endl;
            left = left % sum;
            // now = (now + 1) % N;
            // break;
        }
        int next = next_index[now];
        ull diff = (now == next ? N : (next - now + N) % N) + 1;
        if(diff > left) break;
        left -= diff;
        // cerr << now << " -> " << (next + 1) % N << " (+" << diff << "), left " << left << endl;
        visited[now] = log.size();
        now = (next + 1) % N;
        log.push_back(diff);
    }
    // cerr << "go (left = " << left << " at " << now << endl;
    auto ans =  go(N, left / N + (left % N > 0), A, now);
    rep(i, ans.size()) cout << ans[i] << (i == ans.size() - 1 ? "\n" : " ");
    return 0;
}

