	for (int i = 1; i <= nums.size(); ++i) {
		next[next.size() - i] = prevs[nums[nums.size() - i]];
		step[next.size() - i] = (prevs[nums[nums.size() - i]] - next.size() + i + nums.size() * 2 - 2) % nums.size() + 2;
		prevs[nums[nums.size() - i]] = (next.size() - i + 1) % next.size();
	}
	long long int loop_length = step[0];
	auto current = next[0];
	while (current != 0) {
		loop_length += step[current];
		current = next[current];
	}
	auto rest = n * k % loop_length;
	current = 0;
	std::vector<int> result;
	while (rest > 0) {
		if (rest >= step[current]) {
			rest -= step[current];
			current = next[current];
		}
		else {
			result.push_back(nums[current]);
			current = (current + 1) % nums.size();
			--rest;
		}
	}
	for (auto i = 0; i < result.size(); ++i) {
		if (i != 0) std::cout << ' ';
		std::cout << result[i];
	}
}

