int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	int n;
	LL k;
	cin >> n >> k;
	vector<int> a(n);
	REP(i, n)
		cin >> a[i];
	REP(i, n)
		a.emplace_back(a[i]);
	debug(a);
	vector<int> nxt(2 * n, 2 * n);
	vector<int> last(int(2e5) + 1, -1);
	for(int i = 2 * n - 1; i >= 0; --i) {
		if(last[a[i]] != -1)
			nxt[i] = last[a[i]];
		last[a[i]] = i;
	}
	debug(nxt);

	int lg = 0;
	LL pot2 = 1;
	while(pot2 <= k * n) {
		pot2 *= 2;
		++lg;
	}
	lg += 2;

	vector<vector<pair<int, int>>> ptr(n, vector<pair<int, int>>(lg + 1));
	REP(i, n) {
		int layerdelta = (nxt[i] + 1) >= n;
		if(nxt[i] + 1 == 2 * n)
			++layerdelta;
		ptr[i][0] = {(nxt[i] + 1) % n, layerdelta};
	}

	for(int l = 1; l <= lg; ++l)
		REP(i, n) {
			int half = ptr[i][l - 1].first;
			ptr[i][l] = {ptr[half][l - 1].first, ptr[i][l - 1].second + ptr[half][l - 1].second};
		}
	debug(ptr);

	int i = 0, layer = 1;
	for(int l = lg; l >= 0; --l) {
		int nxtlayer = layer + ptr[i][l].second;
		if(nxtlayer > k)
			continue;
		i = ptr[i][l].first;
		layer = nxtlayer;
		debug(i, layer);
	}
	debug(i, layer) << "ended jumping";

	vector<bool> inside(int(2e5) + 1, false);
	vector<int> que;
	auto simulate_until_end = [&] {
		while(i < n) {
			if(inside[a[i]]) {
				while(inside[a[i]]) {
					int x = que.back();
					que.pop_back();
					inside[x] = false;
				}
			} else {
				que.emplace_back(a[i]);
				inside[a[i]] = true;
			}
			++i;
		}
	};
	if(layer < k) {
		simulate_until_end();
		i = 0;
		++layer;
	}
	if(layer == k) {
		simulate_until_end();
		i = 0;
		++layer;
	}
	debug(i, layer);

	debug(que);

	for(int x : que)
		cout << x << ' ';
	cout << '\n';
}

