int N;
ll K;
const int MA = (int)2e5 + 1;
int kth[MA], A[MA], from, to, loopID;
vi pos[MA];

void jump(int id, int k) {
    if (kth[id] != -1) {
        from = kth[id];
        to = k;
        loopID = id;
        return;
    }
    kth[id] = k;
    auto it = lower_bound(all(pos[A[id]]), id + 1);
    int next_id = -1, next_k = k;
    if (it == pos[A[id]].end()) {
        next_id = pos[A[id]][0] + 1;
        next_k++;
    } else {
        next_id = *it + 1;
    }
    if (next_id == N) {
        next_id = 0;
        next_k++;
    }
    jump(next_id, next_k);
}

void solve() {
    MEM(kth, -1);

    cin >> N >> K;
    rep(i, N) {
        cin >> A[i];
        pos[A[i]].push_back(i);
    }

    jump(0, 0);
    cout << from << ' ' << to << endl;
    assert(loopID == 0);
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

