using namespace std;

typedef long long int lli;

void ans(vector<int> & A, vector<int> & s, int N, int K)
{
	// int end_index = 0;
	int P = 0;
	for (lli k = 0; k < K; k++)
	{
		for (int n = 0; n < N; n++)
		{
			bool found = false;
			for (int i = 0; i < s.size(); i++)
			{
				if (s[i] == A[n])
				{
					s.resize(i);
					found = true;
					break;
				}
			}
			if (!found)
			{
				s.push_back(A[n]);
			}
		}
		// 周期
		if (s.empty())
		{
			P = k + 1;
			K = K % P;
			k = -1;
		}
	}
}

void fast(vector<int> & A, vector<int> & s, int N, int K)
{
	int P = 0;
	for (lli k = 0; k < K; k++)
	{
		for (int n = 0; n < N; n++)
		{
			if (!s.empty() && s[0] == A[n])
			{
				s.resize(0);
			}
			else
			{
				s.push_back(A[n]);
			}
		}
		// 周期
		if (s.empty())
		{
			P = k + 1;
			K = K % P;
			k = -1;
		}
	}
}

int main()
{
	int N;
	lli K;
	cin >> N >> K;
	vector<int> A(N);

	for (int i = 0; i < N; i++)
	{
		cin >> A[i];
	}
	vector<int> s;
	s.reserve(N);

	fast(A, s, N, K);

	vector<int> s2;
	s.reserve(N);
	ans(s, s2, s.size(), 1);

	for (int i = 0; i < s2.size(); i++)
	{
		cout << s2[i] << " ";
	}
	cout << endl;

	return 0;
}

