int N, A[MAX_N];
llong K;

int next_pos[MAX_N];    //A[j] = A[i]となる最小のj > i
vector<int> numpos[MAX_A + 1];

int get_period() {
    int cur = 0;
    int k = 0;
    for(;;) {
        int next = (next_pos[cur] + 1) % N;
        if(next_pos[cur] <= cur || next <= cur) {
            k++;
            if(next == 0) return k;
        }
        cur = next;
    }
}

int get_pos(int K) {
    if(K == 0) return N;
    int cur = 0;
    int k = 0;
    for(;;) {
        int next = (next_pos[cur] + 1) % N;
        if(next_pos[cur] <= cur || next <= cur) {
            k++;
            if(k == K) {
                return cur;
            }
        }
        cur = next;
    }
}

int res[MAX_N];
int simulate(int cur) {
    int pos = cur;
    for(int i = cur; i < N; ++i) {
        if(next_pos[i] > i)
            i = next_pos[i];
        else
            res[pos++] = A[i];
    }
    return pos;
}

int main(int argc, char **argv) {
    cin >> N >> K;
    for(int i = 0; i < N; ++i) {
        cin >> A[i];
        numpos[A[i]].push_back(i);
    }

    for(int i = 1; i <= MAX_A; ++i)
        for(int j = 0; j < numpos[i].size(); ++j)
            next_pos[numpos[i][j]] = numpos[i][(j + 1) % numpos[i].size()];

    int period = get_period();
    K %= period;

    int cur = get_pos(K);
    int bound = simulate(cur);

    for(int i = cur; i < bound; ++i) {
        if(i != cur) cout << " ";
        cout << res[i];
    }
    cout << endl;
}

