int N; ll K;
int nex[61][MAX_N];
ll cost[61][MAX_N];

int A[MAX_N];
vector<int> G[MAX_N];

void solve() {
	cin >> N >> K;
	rep(i, 0, N) {
		cin >> A[i];
		A[i]--;
		G[A[i]].pb(i);
	}
	rep(i, 0, 200000) {
		if(G[i].empty()) continue;
		int a = G[i].front();
		rep(j, 0, sz(G[i]) - 1) {
			int now = G[i][j], to = G[i][j + 1];
			nex[0][now] = (to + 1) % N;
			cost[0][now] = to + 1 - now;
		}
		int b = G[i].back();
		nex[0][b] = (a + 1) % N;
		cost[0][b] = N - b + a + 1;
	}
	for(int i = 0; i < 60; i++) {
		rep(j, 0, N) {
			nex[i + 1][j] = nex[i][nex[i][j]];
			cost[i + 1][j] = cost[i][j] + cost[i][nex[i][j]];
			MIN(cost[i + 1][j], 1ll * N * K);
		}
	}
	// rep(i, 0, 10) {
	// 	rep(j, 0, N) {
	// 		debug(nex[i][j], cost[i][j]);
	// 	}
	// }
	ll tmp = 0;
	int at = 0;
	rer(i, 60, 0) {
		if(tmp + cost[i][at] < 1ll * N * K) {
			tmp += cost[i][at];
			at = nex[i][at];
		}
	}
	set<int> S;
	vector<int> vec;
	// debug(tmp);
	for(ll i = tmp; i < 1ll * N * K; i++) {
		ll idx = i % N;
		if(!S.count(A[idx])) {
			vec.pb(A[idx]);
			S.insert(A[idx]);
		}
		else {
			while(vec.back() != A[idx]) {
				S.erase(vec.back());
				vec.pop_back();
			}
			S.erase(A[idx]);
			vec.pop_back();
		}
	}
	rep(i, 0, sz(vec)) {
		cout << vec[i] + 1 << " ";
	}
	cout << "\n";
}

