            l=memo[l]+1;
        }
        l-=N;
        if(l==N){
            duration=i;
            break;
        }
    }
    K%=duration;
    if(K==0) return 0;
    for(int i=1,l=N;i<=K;i++){
        while(l!=2*N&&memo[l]!=-1){
            l=memo[l]+1;
        }
        l-=N;
        if(l==N){
            duration=i;
            break;
        }
        if(i==K){
            for(;l<N;l++){
                if(memo[l]>=N){
                    cout<<A[l]<<' ';
                }else{
                    l=memo[l];
                }
            }
            cout<<endl;
        }
    }
    return 0;
}

