      if(tot+cnt[mid][idx] < nk) beg = mid;
      else end = mid-1;
    }
    if(tot+cnt[end][idx] < nk) tot += cnt[end][idx];
    else tot += cnt[beg][idx];
  }
  vector<ll> ans;
  ll idx = tot%n;
