#define MAX_LOG 57

#define MAX_N 200000

using namespace std;

typedef long long lint;

const lint sqrInf = (lint)(1e18);

lint n, k;
int a[MAX_N + 1];
int last[MAX_N + 1];
int ap[MAX_N + 1];

int stkLen;
int stk[MAX_N + 1];

int urm[MAX_LOG + 1][MAX_N + 1];
lint sum[MAX_LOG + 1][MAX_N + 1];

int first[MAX_N + 1];

void readFile()
{
    cin >> n >> k;

    for(int i = 1; i <= n; i ++)
        cin >> a[i];
}

void getNext()
{
    for(int i = n; i >= 1; i --)
    {
        if(first[a[i]] == 0)
        {
            first[a[i]] = last[a[i]] = i;
        }

        else
        {
            urm[0][i] = first[a[i]] % n + 1;
            sum[0][i] = first[a[i]] - i + 1;

            first[a[i]] = i;
        }
    }

    for(int i = 1; i <= MAX_N; i ++)
    {
        if(last[i] != 0)
        {
            urm[0][last[i]] = first[i] % n + 1;
            sum[0][last[i]] = n - last[i] + first[i] + 1;
        }
    }
}

void getJumps()
{
    for(int j = 1; j <= MAX_LOG; j ++)
    {
        for(int i = 1; i <= n; i ++)
        {
            urm[j][i] = urm[j - 1][urm[j - 1][i]];
            sum[j][i] = min(sqrInf, sum[j - 1][i] + sum[j - 1][urm[j - 1][i]]);
        }
    }
}

int cr;

void getStart()
{
    k *= n;

    cr = 1;
    for(int i = MAX_LOG; i >= 0; i --)
    {
        if(sum[i][cr] <= k)
        {
            k -= sum[i][cr];
            cr = urm[i][cr];
        }
    }
}

void getRez()
{
    memset(last, 0, sizeof(last));

    for(int i = 1; i <= k; i ++, cr = cr % n + 1)
    {
        int j = cr;
        if(last[a[j]] != 0)
        {
            int x = last[a[j]];
            while(stkLen >= x)
            {
               // cout << " AM STERS " << stk[stkLen] << " POZ " << stkLen << "\n";
                last[stk[stkLen]] = 0;
                stkLen --;
            }

            last[a[j]] = 0;
        }

        else
        {
            stkLen ++;
            stk[stkLen] = a[j];
            last[a[j]] = stkLen;
        }
    }
}

void solve()
{
    getNext();

    getJumps();

    getStart();

    getRez();
}

void printFile()
{
    for(int j = 1; j <= stkLen; j ++)
        cout << stk[j] << " " ;
    cout << "\n";
}

int main()
{
    readFile();

    solve();

    printFile();

    return 0;
}

