const int MAXV = 200000;

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n;
	ll k;
	cin >> n >> k;
	vector<int> a(n), conv(n, -1), prv(MAXV + 1, -1), fst(MAXV + 1, -1);
