		cin >> a[i];
		if(prv[a[i]] == -1){
			prv[a[i]] = i;
			fst[a[i]] = i;
		}
		else{
			conv[prv[a[i]]] = i + 1 - prv[a[i]];
			prv[a[i]] = i;
		}
	}
	if(n == 1){
		if(k%2 == 1) cout << a[0] << endl;
		return 0;
	}
	for(int i = 1; i <= MAXV; ++i){
		if(fst[i] == -1) continue;
		conv[prv[i]] = fst[i] + n + 1 - prv[i];
	}
	ll cur = 0, cycle = 0;
	while(true){
		ll nex = cur + conv[cur % n];
		if(nex > n * k) break;
		cur = nex;
		if(cur%n == 0){
			cycle = cur / n;
			break;
		}
	}
	if(cycle > 0) k %= cycle;
	cur = 0;
	while(true){
		ll nex = cur + conv[cur % n];
		if(nex > n*k){
			cur %= n;
			break;
		}
		if(nex == n*k){
			cur = n;
			break;
		}
		cur = nex;
