		if(cnt[a[i]]){
			while(cnt[a[i]]){
				cnt[ans.back()]--;
				ans.pop_back();
			}
		}
		else{
			ans.push_back(a[i]);
			cnt[a[i]]++;
		}
	}
	rep(i,ans.size()){
		cout << ans[i] << " \n"[i+1 == ans.size()];
	}
	return 0;
}

