ll MAX_N = 200001;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    ll K;
    cin >> N >> K;

    vi A(N);
    for(int i=0;i<N;i++) cin >> A[i];

    vi fst(MAX_N+1, MAX_N+1);
    vi lst(MAX_N+1, -1);
    vi nxt(N, -1);

    for(int i=0;i<N;i++) {
        fst[A[i]] = min(fst[A[i]], i);

        if (lst[A[i]] != -1) {
            nxt[lst[A[i]]] = i;
        }

        lst[A[i]] = max(lst[A[i]], i);
    }

    vi c0(N+1, -1);
    for(int i=N-1;i>=0;i--) {
        int j = nxt[i];
        if (j == -1) {
            c0[i] = A[i];
        } else {
            c0[i] = c0[j + 1];
        }
    }

    vi g(N+1, -1);
    for(int i=0;i<=N; i++) {
        if (c0[i] == -1) {
            g[i] = 0;
        } else {
            g[i] = fst[c0[i]] + 1;
        }
    }

    vi cycle(N+1, -1);
    cycle[0] = 0;
    int ind = 0;
    while (cycle[g[ind]] == -1) {
        cycle[g[ind]] = cycle[ind] + 1;
        ind = g[ind];
    }

    int pref = cycle[g[ind]];
    int clen = cycle[ind] - pref + 1;

    K--;
    if (K > pref) {
        K = pref + (K - pref) % clen;
    }

    int fini;
    for (int i=0;i<=N;i++) {
        if(cycle[i] == K) fini = i;
    }

    vi lastA(0);
    vb contains(MAX_N, false);
    for (int i = fini; i<N; i++){
        if (!contains[A[i]]) {
            contains[A[i]] = true;
            lastA.push_back(A[i]);
        } else {
            while (lastA.back() != A[i]){
                contains[lastA.back()] = false;
                lastA.pop_back();
            } 
            lastA.pop_back();
            contains[A[i]] = false;
        }
    } 


    for (int x : lastA) cout << x << " ";
    cout << endl;


    return 0;
}

