bool us[MAX];
vector<int> ret;
void make(int star,long long int A){
	while(A--){
		if(us[v[star]]){
			while(true){
				us[ret.back()]=false;
				int z=ret.back();
				ret.pop_back();
				if(z==v[star]){
					break;
				}
			}
		}
		else{
			us[v[star]]=true;
			ret.push_back(v[star]);
		}
		star++;
		star%=n;
	}
	for(int i=0;i<ret.size();i++){
		if(i)printf(" ");
		printf("%d",ret[i]);
	}
	puts("");
	exit(0);
