	cin>>n>>k;
	for(int i=0;i<n;i++){
		int a;
		scanf("%d",&a);
		v.push_back(a);
	}
	for(int i=0;i<n;i++){
		v.push_back(v[i]);
	}
	for(int i=v.size()-1;i>=0;i--){
		if(i<n){
			int nex=mp[v[i]];
			nex++;
			len[i]=nex-i;
		}
		mp[v[i]]=i;
	}
	int pos=0;
	long long int len2=0;
	long long int A=n*k;
	while(true){
		ex.insert(pos);
		c.push_back(pos);
		if(A-len[pos]<=0){
			make(pos,A);
		}
		len2+=len[pos];
		pos+=len[pos];
		pos%=n;
		A-=len[pos];
		if(ex.count(pos)==0){
			continue;
		}
		long long int w=len2;
		for(int j=0;j<c.size();j++){
			if(c[j]==pos)break;
			w-=len[pos];
		}
		A%=w;
		break;
	}
	len2=0;
	while(true){
		ex.insert(pos);
		c.push_back(pos);
		if(A-len[pos]<=0){
			make(pos,A);
		}
		len2+=len[pos];
		pos+=len[pos];
		pos%=n;
		A-=len[pos];
		if(ex.count(pos)==0){
			continue;
		}
		long long int w=len2;
		for(int j=0;j<c.size();j++){
			if(c[j]==pos)break;
			w-=len[pos];
		}
		A%=w;
		make(pos,A);
		break;
	}
	return 0;
}

