int N;
long long K;
vector<int> A, B;
vector<int> dp, nxt, same[200200];

void print_result(int piv) {
    if (piv == -1) return;
    while (piv < N) {
        if (nxt[piv] <= N) {
            piv = nxt[piv];
            continue;
        } else {
            cout << A[piv++] << endl;
        }
    }
}

int main() {

    cin >> N >> K;

    A.resize(N);
    REP(i, N) cin >> A[i];

    // B : Aを2回繰り返した配列
    REP(i, 2 * N) B.emplace_back(A[i % N]);

    // same[i] : 数iが格納されているindexのvector
    REP(i, 2 * N) same[B[i]].emplace_back(i);

    // nxt[i] : Bの中で, B[i]と同じ数が次に現れるindexの次のindex
    nxt.resize(N);
    REP(i, N) nxt[i] = *upper_bound(same[B[i]].begin(), same[B[i]].end(), i) + 1;

    int cur = 0;
    while (true) {
        if (nxt[cur] > N) {         // 数列を跨ぐとき
            dp.emplace_back(cur);
        }
        if (nxt[cur] % N == 0) {    // 1巡終了
            dp.emplace_back(-1);    // 数列sが空
            break;
        }
        cur = nxt[cur] % N;
    }

    print_result(dp[(K - 1) % (int)dp.size()]);

}

