    for (int i = n; i >= 1; i--){
        M[a[i]] = i;
    }
    for (int i = n; i >= 1; i--){
        ne[i] = mas[a[i]];
        mas[a[i]] = i;
        if (ne[i] == 0){
            ne[i] = M[a[i]];
            d[i] = 1;
        }
        ne[i]++;
        if (ne[i] > n){
            d[i]++;
            ne[i] -= n;
        }
    }
    int t = 1;
    D[1] = 1;
    while (1){
        if (D[t] >= K)
            break;
        fix[t] = 1;
        int to = ne[t];
        int dist = D[t] + d[t];
        if (fix[to]){
            ll dif = dist - D[to];
            K %= dif;
            while (K <= D[to])
                K += dif;
            break;
        }
        D[to] = dist;
        t = to;
    }
    int st = 0;
    for (int i = 1; i <= n; i++)
        if (D[i] == K){
            st = i;
            break;
        }
    if (st == 0){
        go ();
    }
    for (int i = st; i <= n; i++)
