    {
        idx[a[i]].push_back(i);
    }

    Permutation p(n);
    rep(i, idx.size())
    {
        int m = idx[i].size();
        rep(j, m)
        {
            p[idx[i][j]] = (idx[i][(j + 1) % m] - idx[i][j] + 1 + n) % n;
        }
    }
    rep(i, n)
    {
        if (p[i] == 1) {
            p[i] = n + 1;
        }
    }

    UFTree uft(n);
    rep(i, n)
    {
        uft.merge(i, (i + p[i]) % n);
    }
    int64_t T = 0;
    int cnt = 0;
    rep(i, n)
    {
        if (uft.root(0) == uft.root(i)) {
            T += p[i];
            cnt++;
        }
    }

    int64_t M = (k * n) % T;
    int64_t lb = 0, ub = cnt;
    while (ub - lb > 1) {
        int64_t mid = (lb + ub) / 2;

        Permutation q = ppow(p, mid);
        if (q[0] <= M) {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    Permutation q = ppow(p, lb);
    cout << endl;
    return 0;

    vector<int> result;
    int64_t j = q[0];
    while (j < M) {
        if (j + p[j % n] <= M) {
            j += p[j % n];
        } else {
            result.push_back(a[j % n]);
            j++;
        }
    }

    /*rep(i, result.size())
    {
        cout << result[i] + 1 << " ";
    }
    cout << endl;*/

    return 0;
}

