	for (int i = 0; i < N; ++i) {
		num[A[i]].insert(i);
	}
	vector<int>link(N);
	for (int i = 0; i < N; ++i) {
		auto itr = num[A[i]].find(i);
		++itr;
		if (itr == num[A[i]].end()) {
			itr = num[A[i]].begin();
		}
		link[i] = (*itr + 1) % N;
	}
	unordered_map<int, int> node;	//id,cost
	int pos = 0;
	int next;
	int nextCost;
	while (true) {
		next = link[pos];
		if (next <= pos + 1) {
			nextCost = node[pos] + 1;
		}
		else {
			nextCost = node[pos];
		}
		auto itr = node.find(next);
		if (itr != node.end()) {
			break;
		}
		node[next] = nextCost;
		pos = next;
	}
	int period = nextCost - node[next];
	int offset = node[next];
	if (offset < K) {
		K -= offset;
		K %= period;
		K += offset + period;
	}
	pos = 0;
	int cost = 0;
	while (true) {
		int next = link[pos];
		if (next <= pos + 1) {
			++cost;
		}
		if (cost >= K)break;
		pos = link[pos];
	}
	if (pos == 0)return;
	std::vector<int>res;
	res.reserve(N);
	unordered_set<int>kind;
	for (int i = pos; i < N; ++i) {
