vector<int> calc(const vector<int>& a, int start_pos) {
  vector<int> ans;
  set<int> used;

  for (int i = start_pos; i < a.size(); ++i) {
    if (used.count(a[i])) {
      while (ans.back() != a[i]) {
	used.erase(ans.back());
	ans.pop_back();
      }
      used.erase(ans.back());
      ans.pop_back();
    } else {
      ans.push_back(a[i]);
      used.insert(a[i]);
    }
  }

  return ans;
}

