  }

  vector<int> init;
  init.push_back(n);
  int pos = 0;
  for (int i = 0; i < k; ++i) {
    while (true) {
      int val = a[pos];
      const vector<int>& vec = next[val];
      size_t idx = lower_bound(all(vec), pos) - vec.begin();
      if (idx + 1 == vec.size()) {
	break;
      } else {
	pos = vec[idx + 1] + 1;
	if (pos == n) break;
      }
    }
    if (pos == n) break;
    init.push_back(pos);
    pos = (next[a[pos]][0] + 1) % n;
  }

  int start_pos = 0;
  if (init.size() == k + 1) {
    start_pos = init[k];
  } else {
    start_pos = init[k % init.size()];
  }
  vector<int> ans = calc(a, start_pos);
