    int M = a.size();
    rep(i,M){
        printf("%d%c", a[i], (i==M-1)? '\n':' ');
    }
}

void solve(int N, ll K, vi& a) {
    vvi occ(200001);
    rep(i,N){
        occ[a[i]].pb(i);
    }
    rep(x,200001){
        int L = occ[x].size();
        if (L == 0) continue;
        occ[x].resize(L*2);
        rep(i,L) {
            occ[x][L+i] = N + occ[x][i];
        }
    }
    vi nxt(N);
    rep(i,N){
        int ai = a[i];
        nxt[i] = *upper_bound(ALL(occ[ai]), i);
    }

    auto emu = [&](int ofs){
        if (ofs < 0) {
            cout << endl;
            return;
        }
        vi buf;
        map<int,int> occ;
        for (int i=ofs; i<N; ++i){
            int x = a[i];
            if (found(occ, x)) {
                int ix = occ[x];
                for (int h=buf.size()-1; h>=ix; --h) {
                    int y = buf.back();
                    occ.erase(y);
                    buf.pop_back();
                }
            } else {
                occ[x] = buf.size();
                buf.push_back(x);
            }
        }
        render(buf);
    };

    int k = 0, ofs = 0;
    map<int,int> visited;
    vi cyc(1, 0);
    visited[0] = 0;

    int cycle = -1;
    while (true) {
        while (true) {
            int n = nxt[ofs] + 1;
            if (n >= N) {
                if (k == K-1) {
                    emu(ofs);
                    return;
                }
                ofs = n-N; ++k;

                break;
            }
            ofs = n;
        }
        if (ofs == N) {
            visited[ofs] = k;
            cyc.pb(-1);
            ofs -= N;
            ++k;
        }
        if (found(visited, ofs)) {
            cycle = k - visited[ofs];
            break;
        }
        visited[ofs] = k;
        cyc.pb(ofs);
    }
    if (K-1 < cyc.size()) {
        emu(cyc[K-1]);
    } else {
        int dep = cyc.size() - cycle;
        ll rem = K-1 - dep;
        int k_ = dep + rem % cycle;
        emu(cyc[k_]);
    }
}

