            first[a[i]] = i;
        }
        last[a[i]] = i;
    }

    vector<pair<int64_t, int64_t>> arr;
    auto hhh = hop[0];
    while (hhh >= 0) {
        arr.emplace_back(a[hhh], hhh);

        if (hhh == n - 1) {
            break;
        }

        hhh = hop[hhh + 1];
    }

