int count(vector<int> v){
  int a=0,c=0;
  while(1){
    if(a==0&&c!=0)
      break;
    int i;
    if(a==v.size()-1){
        c++;
        i=0;
      }
    else
      i=a+1;
    while(1){
      if(v.at(a)==v.at(i)){
        a=i;
        break;
      }
      if(i==v.size()-1){
        c++;
        i=0;
      }
      else
        i++;
    }
    if(a==v.size()-1){
        c++;
        a=0;
      }
    else
      a++;
  }
  return c;
}

