ll jp(ll x){
  if(edge[0][x]!=-1)
    return edge[0][x];

  auto it=upper_bound(ALL(s[a[x]]),x);
  ll next;
  if(it==s[a[x]].end())
    next=s[a[x]][0];
  else
    next=*it;

  next=(next+1)%n;
  if(s[a[x]].size()==1){
    if(x==n-1)
      edge[0][x]=n;
    else
      edge[0][x]=next;
  }
  else if(next<=x)
    edge[0][x]=next;
  else
    edge[0][x]=jp(next);

  return edge[0][x];
}

