	{
		for(j=0;j<n;j++)
		{
			pq=dp[i-1][j]+1LL;
			pos=(j+pq)%n;
			pq+=dp[i-1][pos];
			if(pq>inf)dp[i][j]=inf;
			else dp[i][j]=pq;
		}
	}
	//printf("%lld\n",dp[1][0]);
