using namespace std;

int main(){
    long long n,k;
    cin>>n>>k;
    multimap<int,int> mp;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin>>a[i];
        mp.emplace(a[i],i);
    }
    vector<int> res;
    vector<vector<int>> ans;
    int mae=a[0];
    for (int i = 0; i < n; ++i) {
        bool rem=true;
        for (int j = i+1; j < n; ++j) {
            if(a[j]==mae){
                rem=false;
                i=j;
            }
        }
        if(rem)res.emplace_back(mae);
        if(i+1<n)mae=a[i+1];
    }
    ans.emplace_back(res);
    while(!res.empty()){
        mae=res.front();
        res.clear();
        int cnt=-1;
        while(cnt<n){
            bool rem=true;
            auto p=mp.equal_range(mae);
            for(auto it=p.first;it!=p.second;++it){
                if(it->second<=cnt)continue;
                cnt=it->second;
                rem=false;
                break;
            }
            if(rem)res.emplace_back(mae);
            if(cnt+1<n)mae=a[cnt+1];
            ++cnt;
        }
        ans.emplace_back(res);
    }
    int ansn=k%ans.size();
    if(ansn==0)ansn=ans.size();
    --ansn;
    for (int i = 0; i < ans[ansn].size(); ++i) {
        cout<<ans[ansn][i];
        if(i==ans[ansn].size()-1)cout<<endl;
        else cout<<" ";
    }
    return 0;
}

