class BDoNotDuplicate {
public:
    ll N, K;
    ll A[202020], Skip[202020];
    vector<ll> indx[202020];
    vector<pair<ll, ll>> Loop; //
    ll modN(ll a) { return (a + N) % N; }

    void solve(std::istream &cin, std::ostream &cout) {
        cin >> N >> K;
        Fill(Skip, -1);
        _for(i, N)cin >> A[i];
        _for(i, N)indx[A[i]].emplace_back(i);
        int curr = 0, nxt, loop = 0;
        while (Skip[curr] == -1) {
            auto nxt_it = upper_bound(all(indx[A[curr]]), curr);
            if (nxt_it == indx[A[curr]].end())nxt = indx[A[curr]][0] + N;
            else nxt = *nxt_it;
            nxt++;
            Loop.emplace_back(curr, nxt - curr);
            Skip[curr] = (nxt) % N;
            curr = nxt % N;
        }

        ll skip_sum = 0;
        for (auto p : Loop)skip_sum += p.second;

        K *= N;
        K = K % skip_sum;

        auto it = Loop.begin();
        while (K >= it->second) {
            K -= it->second;
            it++;
        }
        curr = it->first;
        deque<ll> Q;
        set<ll> unq;
        rep(n, curr, curr + K) {
            n %= N;
            if (!Q.empty() && unq.count(A[n])) {
                while (!Q.empty() && Q.back() != A[n])unq.erase(Q.back()), Q.pop_back();
                if (!Q.empty())unq.erase(Q.back()),Q.pop_back();
            } else Q.push_back(A[n]), unq.insert(A[n]);
        }

        if (!Q.empty())for (auto it = Q.begin(); it != Q.end(); it++)cout << *it << " ";

    }


};


