	for(;!isdigit(c); c=getchar()) if(c=='-') f=0;
	for(; isdigit(c); c=getchar()) x=(x<<3)+(x<<1)+(c^'0');
	if(f) return x;
	return 0-x;
}
int n,a[N],nxt[N],to[N];
ll k;
int check(int x){return x=(x-1)%n+1;}
int main(){
	n=read(), k=read();
	for(int i=1; i<=n; ++i) a[i]=read();
	for(int i=n; i>=1; --i){
		if(nxt[a[i]]) to[i]=nxt[a[i]]+1-i;
		else to[i]=n+1;
		nxt[a[i]]=i;
	}
	int i=check(1+to[1]), round = 1+to[1]>n ? 1 : 0;
	for(; i!=1; i=check(i+to[i])) if(i+to[i]>n) ++round;
	(--k)%=round, ++k;
	i=check(1+to[1]), round = 1+to[1]>n ? 1 : 0;
	if(round!=k)
		for(; ; i=check(i+to[i])){
			if(i+to[i]>n) ++round;
			if(round==k) break;
		}
	if(check(i+to[i])!=1) for(; i<=n; ++i) printf("%d ",a[i]);
	return 0;
}

