ll n, k;
vl a;
map<ll, sl> t;
set<pair<ll, ll> > s;

void solve(vl b) {
	vector<bool> erased(sz(b), false);
	map<ll, sl> bt; 
	rep(i,0,sz(b)) {
		if(bt[b[i]].empty()) {
			bt[b[i]].insert(i);
		} else {
			int j = *bt[b[i]].begin();
			for(; j < i; ++j) {
				bt[b[j]].clear();
			}
		}
	}

	set<ll> ret;
	for(auto it = bt.begin(); it != bt.end(); ++it) {
		if((it->S).empty()) continue;
		ret.insert(*(it->S).begin());
	}
	for(auto it = ret.begin(); it != ret.end(); ++it) {
		cout << b[*it] << ' ';
	}
	cout << endl;
}

int main(void) {
	ios_base::sync_with_stdio(false);cin.tie(0);cout.tie(0);
	//freopen("in.txt", "r", stdin);

	cin >> n >> k;
	a.resize(n);
	rep(i,0,n) {
		cin >> a[i];
	}
	rep(i,0,n) {
		t[a[i]].insert(i);
	}

	ll cnt = 0;
	ll idx = 0;
	s.insert(mp(cnt, idx));

	while(true) {
		sl& b = t[a[idx]];
		auto it = b.upper_bound(idx);
		if(it == b.end()) {
			cnt++;
			idx = ((*b.begin()) + 1)%n;
		} else {
			if((*it)+1 >= n) cnt++;
			idx = ((*it) + 1)%n;
		}
		if(idx == 0) {
			break;
		} else {
			s.insert(mp(cnt, idx));
		}
	}

	k %= cnt;
	auto iit = s.upper_bound(mp(k,0));
	--iit;
	int c = iit->S;
	solve(vl(a.begin()+c, a.end()));
	return 0;
}

