        if (exist.count(a[i]) ) {
            while (ans.back() != a[i]) ans.pop_back();
            ans.pop_back();
            exist.erase(a[i]);
        }
        else {
            ans.push_back(a[i]);
            exist.insert(a[i]);
        }
    }

    for (int _ : ans) cout << _ << ' '; cout << '\n';

    return 0;
}

