  vector<vector<long long>> par(si, vector<long long>(n, 1e18));
  map<int, int> ma;
  for (int i = n - 1; i >= 0; i--) {
    if (ma.count(a[i])) {
      par[0][i] = ma[a[i]] - i;
    }
    ma[a[i]] = i + 1;
  }
  for (int i = n - 1; i >= 0; i--) {
    if (par[0][i] == 1e18) {
      par[0][i] = ma[a[i]] + n - i;
    }
  }
  for (int i = 0; i < si - 1; i++) {
    for (int j = 0; j < n; j++) {
      if (par[i][j] == 1e18) continue;
      int p = (par[i][j] + j) % n;
      if (par[i][j] + par[i][p] <= k * n) {
        par[i + 1][j] = par[i][j] + par[i][p];
      }
    }
  }
  long long sum = 0;
  for (int i = si - 1; i >= 0; i--) {
    if (sum + par[i][sum % n] <= k * n) {
      sum += par[i][sum % n];
    }
  }
  vector<int> ans;
  while (sum < k * n) {
    if (sum + par[0][sum % n] <= k * n) {
      sum += par[0][sum % n];
    } else {
