void solve() {
	ll n, k;
	cin >> n >> k;

	Array a(n);
	REP(i, n) cin >> a[i];

	Array next(n,n+1);//添字iが消えた後の位置
	Array first(202020, n);
	Array pre(202020, n);
	REP(i, n) {
		if (first[a[i]] == n) {
			first[a[i]] = i;
			pre[a[i]] = i;
			continue;
		}

		next[pre[a[i]]] = i - pre[a[i]] + 1;
		next[i] = n + first[a[i]] - i + 1;
		pre[a[i]] = i;
	}

	Matrix t(45,Array(n,-1));//2^i周期進んだ時の位置
	REP(i, n) {
		if (t[0][i] != -1) continue;
		ll now = i;
		Array p;
		p.push_back(now);
		while (now < n) {
			now += next[now];
			if (now < n) {
				if (t[0][now] != -1) {
					now = t[0][now];
					break;
				}
				p.push_back(now);
			}
		}
		for(auto j:p) t[0][j] = now % n;//1周期進んだ位置
	}

	REP(i, 44) {
		REP(j, n) {
			t[i + 1][j] = t[i][t[i][j]];//ダブリング
		}
	}

	ll pos = 0;
	REP(i, 45) {
		if ((k - 1LL) & (1LL << (LL)i)) {
			pos = t[i][pos];
		}
	}

	while (pos != n) {
		while (pos < n && pos + next[pos] <= n) {
			pos += next[pos];
		}
		if (pos < n) {
			cout << a[pos] << " ";
			pos++;
		}
	}
	cout << en;
}

