ll n,k,a[200010],before[200010],pre[200010],nex[200010],l[200010],r[200010],visit[200010]={},cnt=0,cost;
vector<ll> v;

void init(){
	cin>>n>>k;
	rep(i,n)cin>>a[i];
	rep(i,2e5+1){
		before[i]=-1;
		pre[i]=-1;
		nex[i]=1e9;
		l[i]=1e9;
		r[i]=-1;
		visit[i]=-1;
	}
}

int main(void){
	init();
	rep(i,n){
		l[a[i]]=min(l[a[i]],i);
		r[a[i]]=max(r[a[i]],i);
		pre[i]=before[a[i]];
		nex[before[a[i]]]=i;
		before[a[i]]=i;
	}
	rep(i,n){
		if(nex[i]==1e9)nex[i]=l[a[i]];  // ループさせる
	}
	ll p=0;
	cnt=0;
	while(1){
		if(visit[p]!=-1){
			cost = cnt-visit[p];
			break;
		}
		visit[p]=cnt;
		if(p>=nex[p])cnt++;
		if(nex[p]==n-1)cnt++;
		p = (nex[p]+1)%n;
	}
	// rep(i,n)cout<<visit[i]<<" ";
	// cerr<<endl;
	// cerr<<"cost: "<<cost<<endl;
	// cerr<<"p: "<<p<<endl;
	if(k<=visit[p]){
		// 愚直にシミュレーション
		p = 0;
		for(cnt=0;cnt<k;){
			if(p>=nex[p]){
				if(cnt+1>=k){
					// 増やさない
					v.push_back(a[p]);
				}else{
					cnt++;
				}
			}
			if(nex[p]==n-1){
				cnt++;
			}
			p = (nex[p]+1)%n;
		}
	}else{
		k-=visit[p];  // まずpまで行く
		k %= cost;// 次にそこからループする
		// 最後に愚直にシミュレーション
		for(cnt=0;cnt<k;){
			// cerr<<cnt<<" "<<p<<endl;
			if(p>=nex[p]){
				if(cnt+1>=k){
					// 増やさない
					v.push_back(a[p]);
					p++;  // これを入れ忘れて撃沈
					if(p==n)break;
					continue;
				}else{
					cnt++;
				}
			}
			if(nex[p]==n-1){
				cnt++;
			}
			p = (nex[p]+1)%n;
		}
	}
	// 答え
	rep(i,v.size())cout<<v[i]<<" ";
	cout<<endl;
	return 0;
}

