typedef long long ll;

const ll INF = 2e18;

const int MAXN = 2.1e5;
int N;
ll K;
int A[MAXN];

const int MAXV = 2.1e5;
int nxtOcc[MAXV];

const int L = 60;
ll jumpDist[MAXN][L + 1];

int main() {
	scanf("%d %lld", &N, &K);
	for (int i = 0; i < N; i++) {
		scanf("%d", &A[i]);
	}

	// cyclic
	for (int i = N-1; i >= 0; i--) {
		nxtOcc[A[i]] = i+N;
	}
	for (int i = N-1; i >= 0; i--) {
		jumpDist[i][0] = (nxtOcc[A[i]] - i) + 1;
		nxtOcc[A[i]] = i;
	}

	for (int l = 0; l < L; l++) {
		for (int i = 0; i < N; i++) {
			jumpDist[i][l+1] = min(INF, jumpDist[i][l] + jumpDist[(i + jumpDist[i][l]) % N][l]);
		}
	}

	ll curLoc = 0;
	for (int l = L; l >= 0; l--) {
		if (curLoc + jumpDist[curLoc % N][l] <= N * K) {
			curLoc += jumpDist[curLoc % N][l];
		}
	}

	vector<int> ans;
	while (curLoc < N * K) {
		ll nxtLoc = (curLoc + jumpDist[curLoc % N][0]);
		if (nxtLoc <= N * K) {
			curLoc = nxtLoc;
		} else {
			ans.push_back(A[curLoc % N]);
			curLoc++;
		}
	}

	for (int v : ans) {
		printf("%d ", v);
	}
	printf("\n");

	return 0;
}

