// binary search result
struct BSR {
    bool found; // 条件を満たす範囲が見つかったか。falseの場合、begin,endは意味を持たない。
    int128_t begin; // [begin, end]で条件が成り立つ。
    int128_t end;
    BSR(bool found_in, int128_t begin_in, int128_t end_in) { found = found_in; begin = begin_in; end = end_in; }
    //BSR(bool found_in, int128_t begin_in, int128_t end_in) : found(found_in), begin(begin_in), end(end_in) {}
};

//template<class Fn> BSR binary_search(int128_t L, int128_t R, Fn func) {
BSR binary_search(int128_t L, int128_t R, std::function<bool(int128_t)> func) {
    const bool res_L = func(L);
    const bool res_R = func(R);
    if (res_L && res_R) {
        return BSR(true, L, R);
    } else if (!res_L && !res_R) {
        return BSR(false, 0, 0);
    } else {
        int128_t lb = L;
        int128_t ub = R;
        while (lb + 1 < ub) {
            int128_t mid = (lb + ub) / 2;
            if (res_L == func(mid)) {
                lb = mid;
            } else {
                ub = mid;
            }
        }
        return res_L ? BSR(true, L, lb) : BSR(true, ub, R);
    }
}

// 写像mpをxにnum回作用させた場合の結果を計算。
// mpの定義域は10^5程度を想定していて、値域が定義域に含まれていることが条件。
// この場合、numが非常に大きい値であっても、いずれループするのでnumをループのサイズで割った余りに置き換えることができて、計算時間がnumに依存しなくなる。
// mpがmapやunordered_mapのときに
// auto ret = map_loop(mp, x, num);
// の形式で呼び出すことができる。原因があまりよくわからないが、mpをconstにするとコンパイルできない。また、VSCodeでは呼び出したところに赤の波線が表示される。
// 戻り値は、firstが作用後の値で、secondがループのサイズ。
template<template <typename...> class Tm, typename T>
std::pair<T, int> map_loop(Tm<T, T>& mp, T x, int128_t num) {
    Tm<T, int> path; path[x] = 0;
    int loop_size = 0;
    int cnt = 1;
    while (num) {
        x = mp[x];
        num--;
        if (path.count(x)) {
            loop_size = cnt - path[x];
            num = num % loop_size;
        } else {
            path[x] = cnt;
        }
        cnt++;
    }
    return std::pair<T, int>({x, loop_size});
}

