std::unordered_map<int, std::vector<int>> mp;

std::unordered_map<int, int> change;

int top_if[MAX_N];

int main(int argc, char **argv) {
    std::cin >> N >> K;

    rep (i, 0, N-1) {
        std::cin >> A[i];
        mp[A[i]].push_back(i);
    }

    top_if[N] = 0;
    rev (i, N-1, 0) {
        if (mp[A[i]].back() == i) {
            top_if[i] = A[i];
        } else {
            auto bsr = binary_search(0, mp[A[i]].size() - 1, [&](int j){
                return i < mp[A[i]][j];
            });
            assert(bsr.found);
            top_if[i] = top_if[mp[A[i]][bsr.begin] + 1];
        }
    }

    change[0] = top_if[0];
    for (auto p : mp) {
        change[p.first] = top_if[p.second[0]+1];
    }

    auto prev = map_loop(change, 0, K - 1);

    std::vector<int> ret;
    std::set<int> st;
    int start = 0;

    if (prev.first != 0) {
        start = mp[prev.first][0] + 1;
    }

    rep (i, start, N-1) {
        if (st.count(A[i])) {
            while (true) {
                if (ret.back() == A[i]) {
                    st.erase(ret.back());
                    ret.pop_back();
                    break;
                } else {
                    st.erase(ret.back());
                    ret.pop_back();
                }
            }
        } else {
            ret.push_back(A[i]);
            st.insert(A[i]);
        }
    }

    for (int i : ret) {
        std::cout << i << " ";
    }
    std::cout << std::endl;

    return 0;
}

