void getper(){
	int i,j,k;
	for(i=n-1;i>=0;--i) pr[a[i]]=i;
	for(i=n-1;i>=0;--i){
		nx[0][i]=pr[a[i]];
		if(nx[0][i]<=i)
			ds[0][i]=(LL)(n+nx[0][i]-i);
		else
			ds[0][i]=(LL)(nx[0][i]-i);
		++ds[0][i];
