		for(j=0;j<n;++j){
			nx[i][j]=nx[i-1][nx[i-1][j]];
			ds[i][j]=ds[i-1][j]+ds[i-1][nx[i-1][j]];
			ds[i][j]=min(ds[i][j],inf);
