int main2() {
  int N = nextInt();
  ll K = nextLong();
  REP(i, N) A[i] = nextInt();
  REP(i, N) A[i + N] = A[i];

  CLR(last, -1);
  CLR(inc, 0);

  REP(i, 2 * N) {
    if (last[A[i]] >= 0) {
      nxt[ last[A[i]] ] = (i + 1) % N;
      inc[ last[A[i]] ] = (i + 1) / N;
    }
    last[A[i]] = i;
  }
  // pv(A, A+N);
  // pv(nxt, nxt + N);
  // pv(inc, inc + N);

  CLR(vis, -1);
  ll k = 0;
  int pos = 0;
  while (vis[pos] == -1) {
    vis[pos] = k;
    k += inc[pos];
    pos = nxt[pos];
  }

  ll L = k - vis[pos];
  // cout << "L=" << L << endl;
  // cout << "k=" << k << endl;
  if (K - k >= 2) {
    k += (K - k - 1) / L * L;
  } else {
    k = 0;
    pos = 0;
  }
  // cout << "k=" << k << endl;

  while (k < K - 1) {
    k += inc[pos];
    pos = nxt[pos];
  }

  CLR(isin, 0);
  vector<int> stack;

  // cout << "k=" << k << endl;
