	std::vector<int> step(n, 0);
	for (int i = 1; i <= nums.size(); ++i) {
		next[next.size() - i] = prevs[nums[nums.size() - i]];
		step[next.size() - i] = (prevs[nums[nums.size() - i]] - next.size() + i + nums.size() * 2 - 2) % nums.size() + 2;
		prevs[nums[nums.size() - i]] = (next.size() - i + 1) % next.size();
