		if (i + step[(current + i) % step.size()] <= rest) {
			i += step[(current + i) % step.size()];
		}
		if (i != rest) result.push_back(nums[(current + i) % nums.size()]);
	}
	for (auto i = 0; i < result.size(); ++i) {
		if (i != 0) std::cout << ' ';
		std::cout << result[i];
	}
}

