ll N, K;
vector<ll> A;
vector<ll> lastPos;
vector<ll> nextOccDist;
vector<ll> revNOD;
ll aLim = 2e5;
vector<ll> cleared;

int main(int argc, char *argv[]) {
#if defined(DEBUG)
  // GDB on Cygwin ignores redirection at run command.
  if (argc == 2) dup2(open(argv[1], 0), 0);
#else
  // For performance.  We should not use C-style stdio functions
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
#endif
  cout << setprecision(20);

  cin >> N >> K;
  A.resize(N);
  lastPos.resize(aLim+1, -1);
  nextOccDist.resize(N);
  revNOD.resize(N);
  for (ll i = 0; i < N; i++)  cin >> A.at(i);
  for (ll i = 0; i < N; i++) {
    ll a = A.at(i);
    ll p = lastPos.at(a);
    if (p >= 0)  {
      nextOccDist.at(p) = i - p;
      revNOD.at(i % N) = i - p;
    }
    lastPos.at(a) = i;
  }
  for (ll i = 0; i < N; i++) {
    ll a = A.at(i);
    ll p = lastPos.at(a);
    if (p >= 0)  {
      nextOccDist.at(p) = N + i - p;
      revNOD.at(i % N) = N + i - p;
    }
    lastPos.at(a) = -1;
  }


  cleared.resize(N, -1);
  ll i = 0;
  while (i < N*K && cleared.at(i % N) == -1) {
    cleared.at(i % N) = i;
    i += nextOccDist.at(i % N) + 1;
  }
  if (i <= N*K) {
    ll dist = i - cleared.at(i % N);
    assert (dist % N == 0);
    i +=  dist * ((N * K - i) / dist);
  }else {
    i = 0;
  }

  vector<ll> answer;
  while (1) {
    while (1) {
      ll j = i + nextOccDist.at(i % N) + 1;
      if (j > N*K) break;
      i = j;
    }
    if (i == N*K) { break; }
    answer.push_back(A.at(i % N));
    i += 1;
  }

  if (answer.size() > 0) {
    for (ll t = 0; t < (ll)answer.size(); t++) {
      if (t > 0) { cout << " "; }
      cout << answer.at(t);
    }
    cout << endl;
  }

  return 0;
}

//具体例をいくつか試して、「全消しがよく起きるなあ」という気持ちになるのが重要.
//s : x [xではない] xという風になると全消し発生.
//「x = a_iだったら、全消しジャンプは何マス分か？」を作って、シミュレーション。
//これでは間に合わないので、ダブリングして高速化。
//計算量 … ダブリングすればNlogK回くらいしか移動がおこなわれないはずで、各移動をlogK回で決めているから
//O(Nlog^2K)くらい？. うーん、ちょっと厳しそうだけど、ガバガバ解析だから実際は何とかなる？
#include <iostream>
#include <vector>
#include <algorithm>
#define rep(i, n) for(i = 0; i < n; i++)
#define int long long
using namespace std;

int n, K;
int a[200000];
vector<int> posList[200001];
int jumpCount[40][200000];

signed main() {
	int i, j;

	cin >> n >> K;
	rep(i, n) cin >> a[i];
	rep(i, n) posList[a[i]].push_back(i);
	rep(i, n) posList[a[i]].push_back(n + i);

	rep(i, n) {
		int iter = upper_bound(posList[a[i]].begin(), posList[a[i]].end(), i) - posList[a[i]].begin();
		jumpCount[0][i] = posList[a[i]][iter] + 1 - i;
	}

	rep(i, 39) {
		rep(j, n) {
			int nxt = (j + jumpCount[i][j]) % n;
			jumpCount[i + 1][j] = jumpCount[i][j] + jumpCount[i][nxt];
		}
	}

	int jCnt = 0, iter = 0;
	vector<int> ans;
	while (jCnt < n * K) {
		for (i = 39; i >= 0; i--) {
			if (jCnt + jumpCount[i][iter] <= n * K) {
				break;
			}
		}
		if (i >= 0) {
			jCnt += jumpCount[i][iter];
			iter = (iter + jumpCount[i][iter]) % n;
		}
		else {
			ans.push_back(a[iter]);
			iter = (iter + 1) % n;
			jCnt++;
		}
	}

	rep(i, ans.size()) {
		cout << ans[i];
		if (i + 1 < ans.size()) cout << " ";
	}
	cout << endl;
	return 0;
}

