vector<pii> make_graph(const vector<int>& A) {
	vector<pii> G(A.size());
	int N = A.size();
	int ma = 0;
	for (auto& a : A) ma = max(a, ma);
	vector<int> pos(ma + 1);
	RREP(i, N) {
		pos[A[i]] = i;
	}

	RREP(i, N) {
		int cost = (pos[A[i]] - i);
		if (cost <= 0) cost += A.size();
		G[i] = { (pos[A[i]] + 1) % A.size(), cost + 1 };
		pos[A[i]] = i;
	}

	return G;
}

pii find_node(vector<pii>& G, int node, int cost, vector<bool>& memo) {
	auto dst = G[node];
	int dst_node, dst_cost; tie(dst_node, dst_cost) = dst;
	if (memo[dst_node]) {
		return { node, cost };
	}
	memo[dst_node] = true;
	return find_node(G, dst_node, cost + dst_cost, memo);
}

void solve(vector<pii>& G, int node, int cost, int last_index, vector<int>& res) {
	if (cost > last_index) {
		return;
	}

	auto dst = G[node];
	int dst_node, dst_cost; tie(dst_node, dst_cost) = dst;

	if (dst_cost + cost > last_index + 1) {
		res.push_back(node);
		solve(G, node + 1, cost + 1, last_index, res);
	}
	else {
		solve(G, dst_node, cost + dst_cost, last_index, res);
	}
}

void solve() {
	int  N, K; cin >> N >> K;
	vector<int> A(N); for (auto& a : A) cin >> a;
	vector<pii> G = make_graph(A); //node, cost
	vector<bool> memo(A.size());
	pii loop_node = find_node(G, 0, 0, memo);
	memo = vector<bool>(A.size());
	pii loop_cost = find_node(G, loop_node.first, 0, memo);

	int last_index = N * K - 1;
	vector<int> res;

	if (last_index + 1 <= loop_node.second) {
		solve(G, 0, 0, last_index, res);
		REP(i, res.size()) {
			cout << A[res[i]] << (i == res.size() - 1 ? "\n" : " ");
		}
		return;
	}

	last_index -= loop_node.second;
	last_index %= loop_cost.second;
	solve(G, loop_node.first, 0, last_index, res);

	REP(i, res.size()) {
		cout << A[res[i]] << (i == res.size() - 1 ? "\n" : " ");
	}
}

