void func(long long N, long long K, std::vector<long long> A){

    REP(i,0,N){
        v[A[i]].push_back(i);
    }
    dp[0][N] = 0;

    for(lli i=N-1;i>=0;i--){
        auto itr = lower_bound( v[A[i]].begin(), v[A[i]].end(), i+1);
        if(itr == v[A[i]].end()) dp[0][i] = v[A[i]][0] + 1;
        else dp[0][i] = dp[0][(*itr)+1];

        LOG2(i,dp[0][i]);
    }

    REP(i,0,62){
        REP(j,0,N+1){
            dp[i+1][j] = dp[i][dp[i][j]];
        }
    }

    K--;
    lli now = 0;
    REP(i,0,62){
        if(K&(1LL<<i)) now = dp[i][now];
    }

    //cout<<now<<endl;

    //ラストはシミュレーション
    vector<lli> ans;
    REP(i,now,N){
        auto itr = lower_bound(v[A[i]].begin(),v[A[i]].end(),i+1);
        if(itr == v[A[i]].end())ans.push_back(A[i]);
        else i = (*itr);
    }
    REP(i,0,ans.size())cout<<ans[i]<<" ";
    cout<<endl;

}

