int find_num_in_deque(deque<int> deq, int num) {
  auto itr = find(deq.begin(), deq.end(), num);
  size_t index = distance(deq.begin(), itr);
   // 発見したら
  if (index != deq.size()) {
    return index;
  }
  // 発見できなかったら
  else {
    return -1;
  }
}

int main() {
  int n;
  long long k;
  deque<int> s;
  deque<int> t;
  cin >> n >> k;
  int A[n];

  for (int i = 0; i < n; i++) {
    cin >> A[i];
  }
  //繰り返しのパターンを見つける
  int cnt_till_emp = 0;
  for (int j = 0; j < k; j++) {
    for (int i = 0; i <= n-1; i++) {
      int idx = find_num_in_deque(s, A[i%n]);
      if (idx == -1) {
        //cout << "push" << endl;
        s.push_front(A[i%n]);
      } else {
        //cout << "pop" << endl;
        while(idx >= 0) {
          s.pop_front();
          idx--;
        }
      }
    }
    cnt_till_emp++;
    if (s.empty()) {
      break;
    }
  }
  //cout << "cnt: " << cnt_till_emp << endl;
  //cnt_till_empごとに繰り返されるので、kを割った余りまで操作実施すれば良い
  if (cnt_till_emp >= k){
    cnt_till_emp = k;
  } else {
    cnt_till_emp = k % cnt_till_emp;
  }
  for (int i = 0; i <= (cnt_till_emp)*n-1; i++) {
    int idx = find_num_in_deque(t, A[i%n]);
    if (idx == -1) {
      //cout << "push" << endl;
      t.push_front(A[i%n]);
    } else {
      //cout << "pop" << endl;
      while(idx >= 0) {
        t.pop_front();
        idx--;
      }
    }
  }


  int a;
  while(!t.empty()) {
    a = t.back();
    t.pop_back();
    cout << a << ' ';
  }
  cout << endl;
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const INF = 0x1fffffffffffffff;


int main() {
  ll n, k;
  cin >> n >> k;
  vector<ll> a(n);
  for(auto& i : a) cin >> i;
  vector<ll> at(200001); // at[i] = 次に出てくる i の位置
  for(ll i = n - 1; i >= 0; i--) at[a[i]] = i + n;
  vector<vector<ll>> next(50, vector<ll>(n, INF));
  // next[0][i] = s の先頭が X[i] のとき 次に s が空になるときの X の位置,
  // つまり X[i] == X[j] である i より大きい最小の j
  for(ll i = n - 1; i >= 0; i--) {
    next[0][i] = at[a[i]];
    at[a[i]] = i;
  }
  // next[i][j] = s の先頭が X[j] のときから 2^i 回 s が空になったときの X の位置,
  // つまり (X[j] のときから 2^{i - 1} 回 s が空になったときの X の位置) から 2^{i - 1} 回 s が空になったときの X の位置
  for(ll i = 1; i < 50; i++) {
    for(ll j = 0; j < n; j++) {
      next[i][j] = next[i - 1][(next[i - 1][j] + 1) % n] + (next[i - 1][j] + 1) / n * n; // % n で減った分を足す
      if(next[i][j] > INF) next[i][j] = INF; // オーバーフロー注意
    }
  }
  // 最後に空になった位置を求める
  ll last = -1;
  for(ll i = 49; i >= 0; i--) {
    ll at = next[i][(last + 1) % n] + (last + 1) / n * n;
    if(at < n * k) last = at;
  }
  vector<ll> ans;
  vector<bool> in(200001);
  for(ll i = last + 1 - n * (k - 1); i < n; i++) {
    if(in[a[i]]) {
      while(ans.back() != a[i]) {
        in[ans.back()] = false;
        ans.pop_back();
      }
      in[ans.back()] = false;
      ans.pop_back();
    }
    else {
      ans.push_back(a[i]);
      in[a[i]] = true;
    }
  }
  for(ll i = 0; i < ans.size(); i++) cout << ans[i] << " \n"[i + 1 == ans.size()];
}

