ll jump_to[N][K],jump_cost[N][K];
void _(){
    ll n,k;
    cin >> n >> k;
    vl arr(n);
    cin >> arr;
    arr.insert(arr.end(),all(arr));
    map<int,int> last;
    for(int i = 2*n-1; i >= 0; --i){
        if(i < n){
            int p = last[arr[i]];
            jump_to[i][0] = (p+1)%n;
            jump_cost[i][0] = p+1-i;
        }
        last[arr[i]] = i;
    }
    bool ok = true;
    int K_LIM = 0;
    for(int s = 1; s < K; ++s){
        if(!ok)
            break;
        for(int i = 0; i < n; ++i){
            jump_to[i][s] = jump_to[jump_to[i][s-1]][s-1];
            jump_cost[i][s] = jump_cost[i][s-1] + jump_cost[jump_to[i][s-1]][s-1];
            if(jump_cost[i][s] > 1000000000000000000ll){
                ok = false;
                break;
            }
            else{
                K_LIM = s+1;
            }
        }
    }
    ll lim = n*k;
    ll start = 0;
    ll used = 0;
    for(int i = K_LIM-1; i >= 0; --i){
        if(jump_cost[start][i]+used < lim){
            used += jump_cost[start][i];
            start = used%n;
        }
    }
    vi seen(N);
    vi ans;
    while(used < lim){
        int x = arr[used%n];
        if(seen[x] == 0){
            ans.pb(x);
            seen[x] = 1;
        }
        else{
            while(seen[x] >= 1){
                seen[ans.back()]--;
                ans.pop_back();
            }
        }
        ++used;
    }
    print(ans);
}
