    for(int i = 0; i < n; i ++) cin >> v[i];
    for(int i = 0; i < n; i ++) mn[v[i]] = min(mn[v[i]], i);
    for(int i = n - 1; i >= 0; i --) {
        if(nxt[v[i]]) ptr[i] = nxt[v[i]];
        else          ptr[i] = mn [v[i]];
        nxt[v[i]] = i;
    }
    for(int i = n - 1; i >= 0; i --) {
        if((ptr[i] + 1) % n > i and ptr[i] != i) {
            ptr[i] = ptr[(ptr[i] + 1) % n];
        }
    }
    dfs(0, 1, k, n);
}

