		if(wh[i].empty()) continue;
		int len = wh[i].size();
		for(int j = 0; j < len; j++){
			int from = wh[i][j];
			int to = wh[i][(j + 1) % len];
			if(to <= from || to == n - 1){
				cost[0][from] = 1;
				nxt[0][from] = (to + 1) % n;
			} else {
				cost[0][from] = 0;
				nxt[0][from] = (to + 1) % n;
			}
		}
	}
	for(int j = 1; j < maxm; j++){
		for(int i = 0; i < n; i++){
			nxt[j][i] = nxt[j - 1][nxt[j - 1][i]];
			cost[j][i] = cost[j - 1][i] + cost[j - 1][nxt[j - 1][i]];
		}
	}
	vector<int> seq;
	int cur = 0; k--;
	for(int i = maxm - 1; i >= 0; i--){
