const int MAXN = 200002;
const int LOG_N = 40;

int n;
lld k;
vector<int> arr;
unordered_map <int, int> firstOc, lastOc;
lld f[LOG_N][MAXN]; // f^2n = f(f(f(f())))

int main()
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cin >> n >> k;
  arr.assign(n, 0);
  for (int i = 0; i < n; ++i) {
    cin >> arr[i];
    if (lastOc.count(arr[i]) > 0) {
      int l = lastOc[arr[i]];
      f[0][l] = i-l+1;
    } else {
      firstOc[arr[i]] = i;
    }
    f[0][i] = n - i + firstOc[arr[i]] + 1;
    lastOc[arr[i]] = i;
  }

  for (int j = 1; j < LOG_N; ++j) {
    for (int i = 0; i < n; ++i) {
      lld p = f[j-1][i];
      int nextPosition = (p + (lld) i) % n;
      f[j][i] = p + f[j-1][nextPosition];
    }
  }

  int current = 0;
  lld saltos = k * (lld) n;
  for (int j = LOG_N-1; j >= 0; --j) {
    if (f[j][current] <= saltos) {
      saltos-= f[j][current];
      current = ((lld) current + f[j][current]) % n;
      j = LOG_N;
    }
  }

  vector <int> ans;
  unordered_set <int> present;
  for (int i = 0; i < saltos; ++i) {
    if (present.count(arr[current]) > 0) {
      while (ans.back() != arr[current]) {
        present.erase(ans.back());
        ans.pop_back();
      }
      ans.pop_back();
      present.erase(arr[current]);
    } else {
      ans.push_back(arr[current]);
      present.insert(arr[current]);
    }
    current = (current + 1) % n;
  }

  for (int x : ans) {
    cout << x << " ";
  }
  cout << "\n";

  return 0;
}

