    { 0, 1}, {-1, 0}, {0,-1}, {1, 0}
};
constexpr int A_MAX = 100000;

int main() {
    std::ios::sync_with_stdio(false); cin.tie(nullptr);
    ll n, k;
    cin >> n >> k;
    vector<int> a(n), idx[A_MAX+1];
    for(int i=0;i<n;++i){
        cin >> a[i];
        idx[a[i]].push_back(i);
    }

    int cur = 0;
    vector<ll> dists;
    vector<int> continue_pos;
    do {
        auto itr = upper_bound(idx[a[cur]].begin(), idx[a[cur]].end(), cur);
        if(itr == idx[a[cur]].end()) {
            itr = idx[a[cur]].begin();
            dists.push_back(*itr + n - cur + 1);
        } else {
            dists.push_back(*itr - cur + 1);
        }
        cur = ((*itr) + 1) % n;
        continue_pos.push_back(cur);
    } while(cur != 0);

    for(int i=1;i<dists.size();++i) {
        dists[i] += dists[i-1];
    }

    int cnt = n*k % dists.back();
    vector<int> ans;
    auto itr = upper_bound(dists.begin(), dists.end(), cnt);
    --itr;
    cnt -= *itr;
    int i = continue_pos[itr - dists.begin()];
    while(cnt) {
        auto itr = upper_bound(idx[a[i]].begin(), idx[a[i]].end(), i);
        if(itr == idx[a[i]].end()) {
            itr = idx[a[i]].begin();
        }
        int j = *itr;
        int ij_dist = (i == j)?n:((j-i+n)%n);
        if(ij_dist <= cnt-1) {
            cnt -= ij_dist+1;
            continue;
        }
        ans.push_back(a[i]);
        i = (i+1) % n;
        --cnt;
    }

    for(int x: ans) cout << x << " ";
    cout << endl;
}

