vector < int > p (N), a(N), v;
int n;

vector < int > find_cycle (int k) {
  vector < int > res;
  if (k != 0) {
    int i;
    if (p[k] > k) i = p[k];
    else {
      res.push_back(a[k]);
      i = k + 1;
    }
    while (i < n) {
      if (p[i] > i) {
        i = p[i];
      } else {
        res.push_back (a[i]);
        i++;
      }
    }
  }
  return res;
}

int main () {
  ios_base::sync_with_stdio(false);
  cin.tie(0);cout.tie(0);

  ll k;
  cin >> n >> k;
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    adj[a[i]].push_back (i);
  }

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < (int)adj[i].size() - 1; j++) {
      p[adj[i][j]] = adj[i][j + 1] + 1;
    }
    if ((int)adj[i].size() == 1) {
      p[adj[i].back()] = adj[i].back();
    } else if ((int)adj[i].size() > 0) {
      p[adj[i].back()] = adj[i][0] + 1;
    }
  }

  v.push_back(-1);
  v.push_back(p[0]);
  while (true) {
    if (v.back() == n) {
      v.pop_back();
      break;
    }
    if (v.back() == p[v.back()]) {
      if (v.back() == n - 1) {
        v.pop_back();
        break;
      }
      v.push_back(p[v.back() + 1]);
    } else {
      v.push_back (p[v.back()]);
    }
  }

  while (true && v.size() > 1) {
    vector < int > tmp = find_cycle(v.back());
    if (tmp.size() == 0) v.pop_back();
    else break;
  }

  k %= (int)v.size();

  vector < int > ans = find_cycle(v[k]);

  for (auto i : ans) cout << i << " ";
  cout << '\n';
}

