typedef long long ll;
#define FOR(i,a,b) for(ll i=(a);i<(b);i++)
#define REP(i,a) FOR(i,0,a)
using namespace std;
const ll MAX_N=2e5,MAX_A=2e5;
typedef vector<ll> vec;
ll N,K,A[MAX_N];
vec p,invp;
bool flg[MAX_A+1];
vec pmul(vec a,vec b){
    vec ret(a.size());
    REP(i,a.size()){
        ret[i]=a[b[i]];
    }
    return ret;
}
vec ppow(vec a,ll n){
    vec ret(a.size());
    REP(i,a.size())ret[i]=i;
    while(n){
        if(n&1){
            ret=pmul(ret,a);
        }
        a=pmul(a,a);
        n>>=1;
    }
    return ret;
}
int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin>>N>>K;
    REP(i,N)cin>>A[i];
    REP(i,MAX_A+1){
        p.push_back(i);
        invp.push_back(i);
    }
    REP(i,N){
        swap(invp[0],invp[A[i]]);
    }
    REP(i,MAX_A+1){
        p[invp[i]]=i;
    }
    p=ppow(p,K-1);
    vec st;
    if(p[0]!=0){
        st.push_back(p[0]);
        flg[p[0]]=true;
    }
    REP(i,N){
        if(flg[A[i]]){
            while(flg[A[i]]){
                flg[st.back()]=false;
                st.pop_back();
