struct node{
    int idx;
    int next_idx;
    pair <int, int> get_next_same_num_idx(){
        int loop_added = 0;
        if (next_idx <= idx){
            loop_added = 1;
        }
        return {next_idx, loop_added};
    }
};


int main(void){
    ll n; cin >> n;
