    }
    map <int, int> amap;
    vector <node> nodes;
    REP(i, n){
        int num = as[i];
        int cnt = matrix[num].size();
        int next_idx = matrix[num][(cnt + amap[num] + 1) % cnt];
        nodes.push_back({i, next_idx});
        amap[num]++;
    }

    int loop_cnt = 0;
    int idx = 0;
    while (1){
        pair<int, int> p = nodes[idx].get_next_same_num_idx();
        if (p.first == n-1){
            loop_cnt++;
            break;
        } else {
            loop_cnt += p.second;
            idx = p.first + 1;
        }
    }

    ll nk = n*k;
    nk = nk % (loop_cnt*n);

    loop_cnt = 0;
    idx = 0;
    node prev_node = nodes[n-1];
    while ((loop_cnt+2)*n + idx < nk){
        prev_node = nodes[idx];
        pair<int, int> p = nodes[idx].get_next_same_num_idx();
        if (p.first == n-1) {
            loop_cnt++;
            idx = 0;
        } else {
            loop_cnt += p.second;
            idx = p.first + 1;
        }
    }
    dump(loop_cnt*n + idx)
    dump(nk)
    vector <int> ss;
    for(ll i = loop_cnt*n + idx; i<nk; i++){
        int elem = as[i%n];
        auto found = find(ss.begin(), ss.end(), elem);
        if (found != ss.end()){
            ss.erase(found, ss.end());
        } else {
            ss.push_back(elem);
        }
    }
    REP(i, ss.size()){
        if (i < ss.size() - 1){
            cout << ss[i] << " ";
        } else {
            cout << ss[i] << endl;
        }
    }
    return 0;
}

