using namespace std;

constexpr int MAX = 200200;

int main() {
	int n;
	long long k;
	cin >> n >> k;
	vector<int> a(n);
	for (int &e : a) cin >> e;
	for (int i = 0; i < 2 * n; i++) {
		a.push_back(a[i]);
	}

	vector<int> pi(MAX, -1), next(n, -1);
	for (int i = 0; i < 3 * n; i++) {
		if (int j = pi[a[i]]; j != -1 and next[j] == -1) {
			next[j] = (i + 1) % n;
		}
		pi[a[i]] = i % n;
	}

	vector<bool> processed(n, false);
	vector<int> dat(n);
	for (int s = n - 1; s >= 0; s--) {
		if (processed[s]) continue;
		int i = s;
		vector<int> seen;
		for (; next[i] > i + 1; i = next[i]) {
			seen.push_back(i);
		}
		dat[i] = next[i];
		for (int j : seen) {
			processed[j] = true;
			dat[j] = next[i];
		}
	}

	k--;
	int start = 0;
	for (int i = 0; i < 60; i++) {
		if (k & (1LL << i)) start = dat[start];
		vector<int> buff(n);
		for (int j = 0; j < n; j++) {
			buff[j] = dat[dat[j]];
		}
		dat.swap(buff);
	}

	vector<int> ans;
	vector<bool> pushed(MAX, false);
	for (int i = start; i < n; i++) {
		if (pushed[a[i]]) {
			while (ans.back() != a[i]) {
				pushed[ans.back()] = false;
				ans.pop_back();
			}
			pushed[a[i]] = false;
			ans.pop_back();
		} else {
			ans.push_back(a[i]);
			pushed[a[i]] = true;
		}
	}

	for (int e : ans) cout << e << ' ';
	return 0;
}

