int main() {
	int N; ll K; cin >> N >> K;
	vi A(N); rep(i, N) cin >> A[i];

	rep(i, N) {
		A.pb(A[i]);
	}

	map<int, int> lf;

	for (int i = N * 2 - 1; i >= 0; --i) {
		if (i < N) {
			ps[0][i] = lf[A[i]] - i + 1;
		}
		lf[A[i]] = i;
	}

	rep(i, ML-1) {
		rep(j, maxn) {
			if (ps[i][j] == INF) {
				ps[i + 1][j] = INF;
			} else {
				ps[i + 1][j] = ps[i][j] + ps[i][(j + ps[i][j]) % N];
				if (ps[i + 1][j] > INF) ps[i + 1][j] = INF;
			}
		}
	}

	ll len = N * K;
	ll p = 0;

	for (int i = ML-1; i >= 0; --i) {
		if (p + ps[i][p % N] <= len) {
			p += ps[i][p % N];
		}
	}

	vi vec;
	set<int> st;

	for (; p < len; ++p) {
		int x = A[p % N];
		if (st.count(x)) {
			while (st.count(x)) {
				st.erase(vec.back());
				vec.pop_back();
			}
		} else {
			vec.pb(x);
			st.insert(x);
		}
	}

