	while(k > 1){
		int next = *upper_bound(pos[a[to_make]].begin(), pos[a[to_make]].end()-1, to_make);
		k -= next <= to_make;
		to_make = next;
		if(k == 1){
			++to_make;
		}
		else{
			shift(to_make);
			k -= to_make == 1;			
		}
	}
	for(int &i : bfg(to_make))cout << i << ' ';
}

