constexpr int A_MAX = 200000;

int main() {
    std::ios::sync_with_stdio(false); cin.tie(nullptr);
    ll n, k;
    cin >> n >> k;
    vector<int> a(n), idx[A_MAX+1];
    for(int i=0;i<n;++i){
        cin >> a[i];
        idx[a[i]].push_back(i);
    }

    int cur = 0;
    vector<ll> dists;
    vector<int> continue_pos;
    do {
        auto itr = upper_bound(idx[a[cur]].begin(), idx[a[cur]].end(), cur);
        if(itr == idx[a[cur]].end()) {
            itr = idx[a[cur]].begin();
            dists.push_back(*itr + n - cur + 1);
        } else {
            dists.push_back(*itr - cur + 1);
        }
        cur = ((*itr) + 1) % n;
        continue_pos.push_back(cur);
    } while(cur != 0);

    for(int i=1;i<dists.size();++i) {
        dists[i] += dists[i-1];
    }

    ll cnt = n*k;
    if(cnt >= dists.back()) {
        cnt %= dists.back();
    }
    auto itr = upper_bound(dists.begin(), dists.end(), cnt);
    if(itr != dists.begin()) {
        --itr;
        cnt -= *itr;
    }
    int i = continue_pos[itr - dists.begin()];
    deque<int> que;
    vector<bool> used(A_MAX+1, false);
    while(cnt > 0) {
        if(used[a[i]]) {
            while(!que.empty() && que.back() != a[i]) {
                used[que.back()] = false;
                que.pop_back();
            }
            if(!que.empty()) {
                used[que.back()] = false;
                que.pop_back();
            }
        } else {
            auto itr = upper_bound(idx[a[i]].begin(), idx[a[i]].end(), i);
            if(itr == idx[a[i]].end()) {
                itr = idx[a[i]].begin();
            }
            ll d = ((*itr) - i + n) % n;
            if(d == 0) d = n;
            if(d < cnt) {
                i = (i+d+1) % n;
                cnt -= d+1;
            } else {
                que.push_back(a[i]);
                used[a[i]] = true;
                i = (i+1) % n;
                --cnt;
            }   
        }
    }

    while(!que.empty()) {
        cout << que.front() << " ";
        que.pop_front();
    }
    cout << endl;
}

