using namespace std;

int n;
long long k;
vector<int> a;
map<int, vector<int>> nums;


void show(vector<int> v) {
	for (int i = 0; i < v.size(); i++) {
		if (i != 0) {
			cout << " ";
		}
		cout << v[i];
	}
	cout << endl;
}

vector<int> proc(vector<int> v) {
	// printf("---------\n");
	// show(v);
	int idx = 0;

	if (v.empty()) {
		idx = 0;
	} else {
		idx = nums[v[0]][0] + 1;
		v.clear();
	}

	while (idx < n) {
		auto it = find(v.begin(), v.end(), a[idx]);
		if (it == v.end()) {
			v.emplace_back(a[idx]);
		} else {
			v = vector<int>(v.begin(), it);
		}
		idx++;
	}

	// show(v);
	return v;
}

int main() {
	cin >> n >> k;

	a.assign(n, 0);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		nums[a[i]].emplace_back(i);
	}

	vector<vector<int>> v_stat;
	set<vector<int>> s_stat;


	vector<int> v;
	for (int i = 0; i < k; i++) {
		auto stat = proc(v);

		if (s_stat.count(stat) > 0) {
			break;
		}

		v_stat.emplace_back(stat);
		s_stat.insert(stat);
		v = stat;
	}

	int ans_idx = k % s_stat.size() - 1;
	if (ans_idx < 0) {
		ans_idx += s_stat.size();
	}

	auto ans = v_stat[ans_idx];
	show(ans);

	return 0;
}

