void solve() {
  int n; ll k; cin >> n >> k;
  vi a(n); cin >> a;

  Graph<int> pos(2e5+2);
  rep(i,n) pos[a[i]].emplace_back(i);

  vi nxt(n);
  for (auto &vec : pos) {
    if (vec.empty()) continue;
    nxt[vec.back()] = vec.front();
    rep1(i,vec.size()) {
      nxt[vec[i-1]] = vec[i];
    }
  }

  vi last(1, -1);
  int now = 0;

  while (now < n) {
    if (nxt[now] <= now) last.emplace_back(-1);
    last.back() = nxt[now];
    now = nxt[now] + 1;
  }

  k = (k-1) % last.size();

  vb seen(2e5+2, false);
  vi ans;

  REP(i,last[k]+1,n-1) {
    if (!seen[a[i]]) {
      ans.emplace_back(a[i]);
      seen[a[i]] = true;
    } else {
      while (seen[a[i]]) {
        seen[ans.back()] = false;
        ans.pop_back();
      }
    }
  }

  cout << ans << endl;
}


