template<class T>inline bool chmax(T &a, const T &b) { if (b > a) { a = b; return true; } return false; }
template<class T>inline bool chmin(T &a, const T &b) { if (b < a) { a = b; return true; } return false; }

constexpr int dx[4] = {-1, 0, 0, 1}, dy[4] = {0, -1, 1, 0};
constexpr int INF = 1e9;
constexpr int MOD = 1e9 + 7;
constexpr long long LINF = 1e18;
constexpr double EPS = 1e-10;
constexpr double PI = M_PI;

int bound(ll i, ll N, ll K, const vector<vector<ll>> db) {
    int ok = -1, ng = 60;
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;
        if (i + db[mid][i%N] <= N * K) ok = mid;
        else ng = mid;
    }
    return ok;
}

void solve() {
    ll N, K;
    cin >> N >> K;
    vector<int> a(N);
    for (int i=0; i<N; ++i) cin >> a[i];

    vector<vector<ll>> db(60, vector<ll>(N));
    vector<vector<int>> pla(200001);
    for (int i=0; i<N; ++i) pla[a[i]].push_back(i);
    for (int i=0; i<N; ++i) {
        auto iter = upper_bound(pla[a[i]].begin(), pla[a[i]].end(), i);
        if (iter != pla[a[i]].end()) db[0][i] = *iter - i + 1;
        else db[0][i] = N + pla[a[i]].front() - i + 1;
    }
    for (int i=1; i<60; ++i) {
        for (int j=0; j<N; ++j) {
            db[i][j] = db[i-1][j] + db[i-1][(j+db[i-1][j])%N];
        }
    }

    ll cur = 0;
    for (int i=59; i>=0; --i) if (cur + db[i][cur%N] <= N * K) cur += db[i][cur%N];
    vector<int> res;
    while (cur < N * K) {
        int b = bound(cur, N, K, db);
        if (b == -1) {
            res.push_back(a[cur%N]);
            ++cur;
        } else {
            cur += db[b][cur%N];
        }
    }
    for (int i=0; i<(int)res.size(); ++i) {
        cout << res[i];
        if (i == (int)res.size()-1) cout << '\n';
        else cout << ' ';
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

    return 0;
}

