const ll N_MAX = 2e5;
ll n, k;
vll a, next_dis, occurance;

void func() {
    cin >> n >> k;
    a.resize(n);
    next_dis.resize(n, -1);
    occurance.resize(N_MAX + 1, -1);
    for (ll i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (ll i = n - 1; i >= 0; i--) {
        if (occurance[a[i]] != -1) {
            next_dis[i] = occurance[a[i]] - i + 1;
        }
        occurance[a[i]] = i;
    }
    for (ll i = n - 1; i >= 0; i--) {
        if (next_dis[i] == -1) {
            next_dis[i] = occurance[a[i]] - i;
            if (next_dis[i] <= 0) {
                next_dis[i] += n;
            }
            next_dis[i]++;
        }
    }
    ll i = 0, sum = 0;
    while (1) {
        sum += next_dis[i]; i += next_dis[i]; i %= n;
        if (i == 0) {
            break;
        }
    }
    ll elem = (n % sum) * (k % sum); elem %= sum;
    i = 0;
