llint n, k;
llint a[200005], b[400005];
llint npos[200005];
P succ[45][200005];
set<llint> S;
stack<llint> stk;

int main(void)
{
	cin >> n >> k;
	for(int i = 0; i < n; i++) cin >> a[i];
	for(int i = 0; i < 2*n; i++) b[i] = a[i%n];

	for(int i = 2*n-1; i >= 0; i--){
		if(i < n){
			llint x = npos[b[i]]+1;
			succ[0][i] = P(x/n, x%n);
		}
		npos[b[i]] = i;
	}

	for(int i = 1; i < 45; i++){
		for(int j = 0; j < n; j++){
			P p = succ[i-1][j], q = succ[i-1][succ[i-1][j].second];
			llint x = p.first+q.first, y = q.second;
			succ[i][j] = P(x, y);
		}
	}

	llint x = 0, y = 0;
	for(int i = 44; i >= 0; i--){
		llint nx = x + succ[i][y].first, ny = succ[i][y].second;
		if(nx <= k-1) x = nx, y = ny;
	}

	for(; x < k; x++){
		for(; y < n; y++){
			if(!S.count(a[y])){
				S.insert(a[y]);
				stk.push(a[y]);
			}
			else{
				while(stk.top() != a[y]){
					S.erase(stk.top());
					stk.pop();
				}
				S.erase(a[y]);
				stk.pop();
			}
		}
		y = 0;
	}

	vector<llint> ans;
	while(stk.size()){
		ans.push_back(stk.top());
		stk.pop();
	}
	reverse(ans.begin(), ans.end());

	for(int i = 0; i < ans.size(); i++) cout << ans[i] << " "; cout << endl;

	return 0;
}

