int main(){
  long long N, K;
  cin >> N >> K;

  vector<int> A(N);
  for(int i = 0; i < N; i++){
    cin >> A[i];
  }

  // next[0][i] := A[i]から始まるブロックの長さ
  // next[k][i] := A[i]から始まる2^k個のブロックの長さの和
  vector<vector<long long>> next(60, vector<long long>(N));
  {
  // prev_indices[n] := (n == A[i])となる前回のi
  vector<int> prev_indices(2e5 + 1, -1);
  for(int i = 0; i < 2 * N; i++){
    if(prev_indices[A[i % N]] != -1 && prev_indices[A[i % N]] < N){
      next[0][prev_indices[A[i % N]]] = i - prev_indices[A[i % N]] + 1;
    }
    prev_indices[A[i % N]] = i;
  }
  }

  int k;
  for(k = 1; k < 60; k++){
    bool end = false;
    for(int i = 0; i < N; i++){
      next[k][i] = next[k - 1][i] + next[k - 1][((i + next[k - 1][i]) % N)];
      if(next[k][i] > N * K){
        end = true;
        break;
      }
    }
    if(end){
      break;
    }
  }
  int k_max = k - 1;

  long long idx = 0;
  bool conti = true;
  while(conti){
    conti = false;
    for(int k = k_max; k >= 0; k--){
      if(idx + next[k][idx % N] <= N * K){
        idx = idx + next[k][idx % N];
        conti = true;
        break;
      }
    }
  }

  vector<int> ans;
  unordered_set<int> appeared;
  //vector<bool> appeared(2e5 + 1, false);
  for(; idx < N * K; idx++){
    if(appeared.count(A[idx % N])){
      for(int i = ans.size() - 1; i >= 0; i--){
        appeared.erase(ans[i]);
        if(ans[i] == A[idx % N]){
          ans.pop_back();
          break;
        }
        ans.pop_back();
      }
    }else{
      appeared.insert(A[idx % N]);
      ans.push_back(A[idx % N]);
    }
  }

  for(int i = 0; i < ans.size(); i++){
    if(i){
      cout << ' ';
    }
    cout << ans[i];
  }cout << endl;
}

