using lli = long long int;
using Vint = std::vector<int>;
using Wint = std::vector<Vint>;

#define REP(i, n) for(int (i) = 0; (i) < (n); (i)++)
#define FOReq(i, a, b) for(int (i) = (a); (i) <= (b); (i)++)

int main(void){
    lli n, k; scanf("%lld%lld", &n, &k);
    int MX = -1;
    Vint A(n); REP(i, n){
        scanf("%d", &A[i]);
        if(MX < A[i]) MX = A[i];
    }
    Wint Indexes(MX + 1, Vint(0)); // インデックスを表すデータ構造
    REP(i, n) Indexes[A[i]].push_back(i);
    Vint ComeLoop(n, -1); // すでに訪れたかを表すデータ(初めてついた時点でのループの回数)
    Vint Nxt_Index(n, -1); // 次のの場所をさす : x -> x の位置をさす
    FOReq(val, 1, MX) if(Indexes[val].size() != 0){
        int sz = Indexes[val].size();
        REP(i, sz - 1) Nxt_Index[Indexes[val][i]] = Indexes[val][i+1];
        Nxt_Index[Indexes[val][sz-1]] = Indexes[val][0];
    }
    int idx = 0; lli b = 0; int Loop = 0;
    while(true){
        if(ComeLoop[idx] != -1) break;
        ComeLoop[idx] = Loop;
        int nxt_idx = Nxt_Index[idx];
        int cost = (nxt_idx > idx) ? nxt_idx - idx : (n - idx) + nxt_idx;
        b += cost + 1;
        if(nxt_idx <= idx or nxt_idx == n-1) Loop++;
        idx = (nxt_idx + 1) % n;
    }

    lli M = n * k;
    int v;
    if(M < b) v = 0;
    else{
        M -= b; v = idx;
        int LOOP = Loop - ComeLoop[idx];
        M %= (LOOP * n);
    }
    while(true){
        int v2 = Nxt_Index[v];
        int cost = (v2 > v) ? v2 - v : (n - v) + v2; cost++;
        if(cost > M) break;
        M -= cost;
        v = (v2 + 1) % n;
    }
    int buffor = M;
    std::queue<int> RES;
    while(buffor > 0){
        int v2 = Nxt_Index[v];
        int dist = (v2 > v) ? v2 - v : (n - v) + v2; dist++;
        if(dist <= buffor){
            buffor -= dist;
            v = (v2 + 1) % n;
        }
        else{
            RES.push(A[v]); buffor--;
            (v += 1) %= n;
        }
    }
    while(not RES.empty()){
        printf("%d", RES.front()); RES.pop();
        putchar(RES.empty() ? '\n' : ' ');
    }
    return 0;
}

