using namespace std;
constexpr int MAX = 200010;

int main() {
    int N;
    lint K;
    cin >> N >> K;
    --K;

    vector<int> A(N);
    vector<vector<int>> pos(MAX);
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        pos[--A[i]].push_back(i);
    }

    vector<int> nxt(N);
    for (int a = 0; a < MAX; ++a) {
        for (int i = 0; i < pos[a].size(); ++i) {
            nxt[pos[a][i]] = pos[a][(i + 1) % pos[a].size()];
        }
    }
    // cerr << nxt << endl;

    vector<lint> prev(N, -1);
    int idx = 0;
    while (K > 1) {
        // cerr << make_pair(K, idx) << endl;
        if (prev[idx] >= 0) {
            K %= (prev[idx] - K);
            // cerr << make_pair(K, idx) << endl;
            if (K <= 1) break;
        }
        prev[idx] = K;
        int to = nxt[idx];
        if (to <= idx) --K;
        if (to == N - 1) --K;
        idx = (to + 1) % N;
    }

    vector<int> ans;
    set<int> app;

    while (K >= 0) {
        for (int i = idx; i < N; ++i) {
            if (app.count(A[i])) {
                while (app.count(A[i])) {
                    app.erase(ans.back());
                    ans.pop_back();
                }
            } else {
                ans.push_back(A[i]);
                app.insert(A[i]);
            }
        }
        idx = 0;
        --K;
    }

    for (auto a : ans) cout << a + 1 << " ";
    cout << endl;
    return 0;
}

