const ll MOD = 1000000007;
const ll INF = (ll)1e15;

ll A[200005];
bool U[200005];

int main()
{
    ll N, K;
    cin >> N >> K;
    REP(i, N)
    {
        cin >> A[i];
    }
    memset(U, 0, sizeof(U));

    ll loop = K;
    stack<ll> s;
    REP(i, K)
    {
        REP(j, N)
        {
            if (!U[A[j]])
            {
                U[A[j]] = true;
                s.push(A[j]);
                continue;
            }
            while (true)
            {
                ll t = s.top();
                s.pop();
                U[t] = false;
                if (t == A[j])
                    break;
            }
        }
        if (s.empty())
        {
            loop = i + 1;
            break;
        }
    }
    ll n = K % loop;
    memset(U, 0, sizeof(U));
    REP(i, n)
    {
        REP(j, N)
        {
            if (!U[A[j]])
            {
                U[A[j]] = true;
                s.push(A[j]);
                continue;
            }
            while (true)
            {
                ll t = s.top();
                s.pop();
                U[t] = false;
                if (t == A[j])
                    break;
            }
        }
    }

    vector<ll> ans;
    while (!s.empty())
    {
        ll t = s.top();
        s.pop();
        ans.push_back(t);
    }

    REP(i, ans.size())
    {
        cout << ans[ans.size() - 1 - i] << " ";
    }
    cout << endl;
    return 0;
}

