#include<bits/stdc++.h>
using namespace std;

void solve(int n, int arr[], pair<int, long long> st[][40], long long k)
{
    int pos = 0;
    for (int i = 39; i != -1; --i)
    {
        while (k > st[pos][i].second)
        {
            k -= st[pos][i].second;
            pos = st[pos][i].first;
        }
    }

    vector<bool> kek(200000);
    deque<int> s;

    while (k--)
    {
        for (int i = pos; i != n; ++i)
        {
            if (kek[arr[i]])
            {
                while (s.back() != arr[i])
                {
                    kek[s.back()] = 0;
                    s.pop_back();
                }
                kek[s.back()] = 0;
                s.pop_back();
            }
            else
            {
                kek[arr[i]] = 1;
                s.push_back(arr[i]);
            }
        }
        pos = 0;
    }

    for (int x : s)
        cout << x + 1 << ' ';
    cout << '\n';
}

int main()
{
    // ios_base::sync_with_stdio(0);
    // cin.tie(0);

    int n;
    long long k;
    cin >> n >> k;

    int arr[n];
    vector<int> positions[200000];
    for (int i = 0; i != n; ++i)
    {
        cin >> arr[i];
        arr[i]--;

        positions[arr[i]].push_back(i);
    }

    vector<int> counters(200000);
    pair<int, long long> st[n][40];
    for (int i = 0; i != n; ++i)
    {
        int x = arr[i];

        if (counters[x] + 1 == positions[x].size())
            st[i][0] = make_pair(positions[x].front() + 1, 1LL);
        else
            st[i][0] = make_pair(positions[x][counters[x] + 1] + 1, 0LL);

        if (st[i][0].first == n)
        {
            st[i][0].first = 0;
            st[i][0].second++;
        }

        counters[x]++;
    }

    for (int j = 1; j != 40; ++j)
        for (int i = 0; i != n; ++i)
            st[i][j] = make_pair(st[st[i][j - 1].first][j - 1].first, st[st[i][j - 1].first][j - 1].second + st[i][j - 1].second);

    solve(n, arr, st, k);

    return 0;
}

