int n;
ll k;

void finish(ll idx) {
  set<int> s;
  vector<int> v;
  while(idx < n*k) {
    if(s.count(l[idx%n])) {
      while(s.count(l[idx%n])) {
        s.erase(v.back());
        v.pop_back();
      }
    }
    else {
      v.push_back(l[idx%n]);
      s.insert(l[idx%n]);
    }
    idx++;
  }
  for(int out: v) cout << out << " "; cout << "\n";
  exit(0);
}

void solve() {
  cin >> n >> k;
  for(int i = 0; i < n; i++) {
    cin >> l[i];
    found[l[i]].push_back(i);
  }
  for(int i = 0; i < n; i++) {
    if(found[l[i]].size() == 1) {
      inc[i] = n+1;
    }
    else if(found[l[i]].back() == i){
      inc[i] = n+1+found[l[i]][0] - i;
    }
    else {
      inc[i] = 1 + found[l[i]][upper_bound(found[l[i]].begin(), found[l[i]].end(), i) - found[l[i]].begin()] - i;
    }
  }
  set<int> seen;
  vector<ll> v;
  v.push_back(0);
  ll curr = 0;
  ll cycleSize = -1;
  while(true) {
    if(curr == n*k) return;
    if(seen.count(curr%n)) {
      for(ll out: v) {
        if(curr%n == out%n) {
          cycleSize = curr - out;
          break;
        }
      }
      break;
    }
    seen.insert(curr%n);
    ll nextI = curr + inc[curr%n];
    if(nextI == n*k) {
      return;
    }
    if(nextI > n*k) {
      finish(curr);
    }
    curr += inc[curr%n];
    v.push_back(curr);
  }
  assert(cycleSize > 0);
  while(curr + cycleSize <= n*k) {
    int d = 0;
    while(curr + (1LL << (d+1)) * cycleSize < n*k) {
      d++;
    }
    curr += (1LL << d) * cycleSize;
  }
  while(curr + cycleSize <= n*k) {
    curr += cycleSize;
  }
  while(curr + inc[curr%n] <= n*k) curr += inc[curr%n];
  finish(curr);
}

