vector<Int> calc(vector<Int> A, Int s){
  Int N = A.size();
  vector<vector<Int> > Idx(200010);
  for(Int i=0;i<N;i++) Idx[ A[i] ].push_back(i);
  for(Int i=0;i<(Int)Idx.size();i++) Idx[i].push_back(INF);

  vector<Int> res;
  Int i = s;
  while(i < N){
    Int x = A[i];
    Int ni = *upper_bound(Idx[x].begin(), Idx[x].end(), i);
    if(ni != INF){i = ni + 1; continue;}
    res.push_back(x);
    i++;
  }
  return res;
}

Int calc2(vector<Int> &A, Int i){
  static Int mem[400020], used[400020];
  static vector<vector<Int> > Idx;
  if(Idx.empty()){
    Idx.resize(200020);
    Int N = A.size();
    for(Int i=0;i<N;i++) A.push_back(A[i]);
    N = A.size();
    for(Int i=0;i<N;i++) Idx[ A[i] ].push_back(i);
    for(Int i=0;i<(Int)Idx.size();i++) Idx[i].push_back(INF);
    A.resize(A.size() / 2);
  }
  Int N = A.size();
  if(i == N * 2) return N;
  if(used[i]++) return mem[i];
  Int x = A[i%N];
  Int ni = *upper_bound(Idx[x].begin(), Idx[x].end(), i);
  if(ni == INF) return mem[i] = i % N;
  return mem[i] = calc2(A, ni + 1);
}


