Type solve(Type res = Type()){
    ll N,K; cin >> N >> K;
    vector<ll> A(N);
    for(auto& in:A) cin >> in;
    for(int i = 0; i < N;i++){
        st[A[i]].emplace(i);
    }

    ll now = 0;
    ll cnt = 1;
    while(true){
        ll val = A[now];

        auto next_it = st[val].upper_bound(now);

        if(next_it == st[val].end()){
            next_it = st[val].begin();
            cnt++;
        }
        now = (*next_it + 1)%N;
        if(now == 0) break;
    }
    K %= cnt;

    now = 0;
    cnt = 0;
    while(cnt < K-1){
        ll val = A[now];
        auto next_it = st[val].upper_bound(now);
