int main() {
    ll N, K;
    cin >> N >> K;
    vector<ll> Ais(N);
    rep(i,0,N) {
        cin >> Ais[i];
    }
    auto table = make_vec_nd((ll)numeric_limits<ll>::max(), 64, N);
    unordered_map<ll, ll> last_appear;
    rep(i,0,2*N) {
        ll Ai = Ais[i%N];
        if (last_appear.find(Ai) != last_appear.end()) {
            table[0][last_appear[Ai]%N] = i - last_appear[Ai] + 1;
        }
        last_appear[Ai] = i;
    }
    rep(p,1,64) {
        rep(i,0,N) {
            ll next_i = (i + table[p-1][i]) % N;
            table[p][i] = table[p-1][i] + table[p-1][next_i];
            if (table[p][i] > N * K) {
                table[p][i] = N * K;
            }
        }
    }
    ll start_idx = 0;
    while (true) {
        if (start_idx + table[0][start_idx%N] >= N * K) {
            break;
        }
        ll p = 0;
        while (start_idx + table[p][start_idx%N] < N * K) {
            p++;
        }
        p--;
        start_idx += table[p][start_idx%N];
    }
    unordered_map<ll, ll> values_cnt;
    vector<ll> ans;
    rep(i,start_idx,N*K) {
        ll Ai = Ais[i%N];
        if (values_cnt[Ai] == 0) {
            ans.push_back(Ai);
            values_cnt[Ai]++;
        } else {
            while (values_cnt[Ai] > 0) {
                if (ans.back() == Ai) {
                    values_cnt[Ai]--;
                }
                ans.pop_back();
            }
        }
    }
    rep(i,0,ans.size()) {
        cout << ans[i];
        if (i < ans.size()-1) {
            cout << " ";
        }
    }
    cout << endl;
}

