using namespace std;


int A[200000];
queue<int> que[200001];

ll op_num[200000]; // the num of op's when A[i] is the front
ll next_front[200000];

ll ans[200000];

int main(){
    int N;
    ll K;

    cin >> N >> K;


    ll turns = N*K;

    for(int i=0; i<N; i++){
        cin >> A[i];
        que[A[i]].push(i);
    }



    for(int i=0; i<N; i++){
        que[A[i]].pop();
        que[A[i]].push(i);

        int last=que[A[i]].front();
        next_front[i]=(last+1)%N;

        if(last==i){
            op_num[i] = N+1;
        }else if(i < last){
            op_num[i] = last-i+1;
        }else if(last < i){
            op_num[i] = N+last-i+1;
        }
    }

    ll one_cycle=op_num[0];
    for(int temp=next_front[0]; temp!=0; temp=next_front[temp]){
        one_cycle+=op_num[temp];
    }

    turns%=one_cycle;



    int temp=0;
    while(turns>=op_num[temp]){
        turns-=op_num[temp];
        temp = next_front[temp];
    }


    int exist[200001];
    for(int i=0; i<200001; i++){
        exist[i]=-1;
    }
    int idx=0;
    for(int i=0; i<turns; i++){
        int x=A[(i+temp)%N];
        if(exist[x]==-1){
            exist[x]=idx;
            ans[idx]=x;
            idx++;
        }else{
            idx=exist[x];
            exist[x]=-1;
        }
    }

    for(int i=0; i<idx; i++){
        cout<<ans[i];
        if(i==idx-1){
            cout<<endl;
        }else{
            cout<<" ";
        }
    }
    return 0;
}

