        {
            int idx = (pre[A[i % N]] - 1) % N;
            nxt[0][idx] = (i + 1) % N;
            over[0][idx] = (nxt[0][idx] <= idx % N || idx == i % N) ? 1 : 0;
            pre[A[i % N]] = i + 1;
        }
    }

    for(int i = 1; i < 60; i++)
    {
        for(int j = 0; j < N; j++)
        {
            nxt[i][j] = nxt[i - 1][nxt[i - 1][j]];
            over[i][j] = over[i - 1][j] + over[i - 1][nxt[i - 1][j]];
        }
    }

    ll l = 0, r = 1LL << 60;
    ll mem;
    for(int i = 0; i < 64; i++)
    {
        ll mid = (l + r) / 2;
        ll now = 0, cnt = 0;
        for(int j = 0; j < 60; j++)if(mid & (1LL << j))
        {
            cnt += over[j][now];
            now = nxt[j][now];
        }
        if(K - 1 == cnt)
        {
            mem = now;
            break;
        }
        if(cnt < K - 1)l = mid;
        else r = mid;
    }

