int search(int* d, int t, int n) {
	if (d[0] == t)return 0;
	int r = 0;
	for (int i = 20; i >= 0; i--) {
		int c = r | (1 << i);
		if (c >= n)continue;
		if (d[c] == t)return c;
		if (d[c] < t)r = c;
	}
	return -1;
}

int main() {
	int N;
	long long K;
	scanf("%d %lld", &N, &K);
	int *A = new int[N];
	for (int i = 0; i < N; i++) {
		scanf("%d", A + i);
		o[A[i]].push_back(i);
	}
	int s = 0;
	long long cnt = 0;
	while (1) {
		int c = search(o[A[s]].data(), s, o[A[s]].size());
		int sd = (o[A[s]][(c + 1) % o[A[s]].size()] + 1) % N;
		if (sd <= s + 1)cnt++;
		s = sd;
		if (s == 0)break;
	}
	long long kd = K % cnt;
	s = 0;
	for (int q = 0; q < kd;) {
		int c = search(o[A[s]].data(), s, o[A[s]].size());
		int sd = (o[A[s]][(c + 1) % o[A[s]].size()] + 1) % N;
		if (sd <= s + 1)q++;
		if (q < kd)s = sd;
	}
	for (int i = s; i < N; i++) {
		int c = search(o[A[i]].data(), i, o[A[i]].size());
		if (c == o[A[i]].size() - 1) {
			printf("%d ", A[i]);
		}
		else {
			i = o[A[i]][c + 1];
		}
	}
	return 0;
}

