  for(auto &t: A) --t;

  vector< int > nxt(200000), con(N);
  for(int i = 2 * N - 1; i >= 0; i--) {
    if(i < N) con[i] = nxt[A[i]];
    nxt[A[i % N]] = i;
  }


  int64 y = 0, x = 0;
  vector< pair< int64, int64 > > lis;
  lis.emplace_back(y, x);

  vector< int64 > last(N, -1);
  last[0] = 0;
  while(y + 2 < K) {
    x = con[x] + 1;
    while(x >= N) {
      ++y;
      x -= N;
