    lis.emplace_back(y, x);
    if(~last[x]) {
      int64 sa = lis.back().first - lis[last[x]].first;
      if(sa) {
        y += max(0LL, (K - y - 2) / sa) * sa;
      }
    }
    last[x] = (int) lis.size();
