LL N;
LL K;
int A[400000];
int nxt[200000];
map<int, vector<int>> mp;

LL times[200000];
LL period() {
	Fill(times, -1);
	int i = 0;
	LL cnt = 0;
	while (true) {
		if (times[i] >= 0) {
			assert(i == 0);
			return cnt - times[i];
		}
		times[i] = cnt;

		i += nxt[i] + 1;
		cnt += i / N;
		i %= N;
	}
}

void sim() {
	Fill(times, -1);
	int i = 0;
	LL cnt = 0;
	while (cnt < K - 2) {
		times[i] = cnt;
		i += nxt[i] + 1;
		cnt += i / N;
		i %= N;
	}

	int rem = (K - cnt) * N - i;
	map<int, int> mp;
	vector<int> v;
	REP(di, 0, rem) {
		int p = (i + di) % N;
		int val = A[p];
		if (mp[val] == 0) {
			++mp[val];
			v.push_back(val);
		} else {
			while (v.back() != val) {
				--mp[v.back()];
				v.pop_back();
			}
			--mp[v.back()];
			v.pop_back();
		}
	}

	for (int val : v) {
		cout << val << ' ';
	}
	cout << endl;
}

int main() {
	cin >> N >> K;
	REP(i, 0, N) cin >> A[i];
	REP(i, 0, N) A[i + N] = A[i];
	REP(i, 0, 2 * N) {
		mp[A[i]].push_back(i);
	}

	for (auto&& q : mp) {
		int val = q.first;
		const vector<int>& ps = q.second;
		REP(k, 0, ps.size()) {
			int p = ps[k];
			if (p >= N) break;
			nxt[p] = ps[k + 1] - ps[k];
		}
	}

	LL per = period();
	K %= per;
	sim();
	return 0;
}

