#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}

void render(vi& a){
    int M = a.size();
    rep(i,M){
        printf("%d%c", a[i], (i==M-1)? '\n':' ');
    }
}

void solve(int N, ll K, vi& a) {
    vvi occ(200001);
    rep(i,N){
        occ[a[i]].pb(i);
    }
    rep(x,200001){
        int L = occ[x].size();
        if (L == 0) continue;
        occ[x].resize(L*2);
        rep(i,L) {
            occ[x][L+i] = N + occ[x][i];
        }
    }
    vi nxt(N);
    rep(i,N){
        int ai = a[i];
        nxt[i] = *upper_bound(ALL(occ[ai]), i);
    }

    auto emu = [&](int ofs){
        vi buf;
        map<int,int> occ;
        for (int i=ofs; i<N; ++i){
            int x = a[i];
            if (found(occ, x)) {
                int ix = occ[x];
                for (int h=buf.size()-1; h>=ix; --h) {
                    int y = buf.back();
                    occ.erase(y);
                    buf.pop_back();
                }
            } else {
                occ[x] = buf.size();
                buf.push_back(x);
            }
        }
        render(buf);
    };

    int k = 0, ofs = 0;
    map<int,int> visited;
    vi cyc(1, 0);
    visited[0] = 0;

    int cycle = -1;
    while (true) {
        while (true) {
            int n = nxt[ofs] + 1;
            if (n >= N) {
                if (k == K-1) {
                    emu(ofs);
                    return;
                }
                ofs = n-N; ++k;
                break;
            }
            ofs = n;
        }
        if (found(visited, ofs)) {
            cycle = k - visited[ofs];
            break;
        }
        visited[ofs] = k;
        cyc.pb(ofs);
        if (k == 100) break;
    }
    int dep = cyc.size() - cycle;
    ll rem = K-1 - dep;
    int k_ = dep + rem % cycle;
    emu(cyc[k_]);
}

int main() {
    int N; ll K; scanf("%d %lld%*c", &N, &K);
    vi a(N);
    loadvec(a, N);
    solve(N,K,a);
    return 0;
}

