void solve() {
	while (1) {
		if (nk > k) {
			now = n;
			return;
		}
		if (nk == k)return;

		if (used[now] != -1) {
			ll c = ((k - used[now]) / (nk - used[now]));
			nk = used[now] + (nk - used[now]) * c;
			//cout << nk << " " << now << " kore1" << endl;
			return;
		}
		else used[now] = nk;
		if (nx[now] <= now)nk++;
		now = nx[now];
		now = (now + 1) % n;
		if (now == 0)nk++;
		if (nk > k)return;
		//cout << nk << " " << now << endl;
	}
}

