	scanf("%d%lld", &n, &K);
	for (int i = 0; i < n; i++) {
		scanf("%d", a + i);
	}
	for (int i = n - 1; ~i; i--)
		h[a[i]] = i + n;
	for (int i = n - 1; ~i; i--) {
		int suf = h[a[i]];
		fa[i] = (suf + 1) % n;
		c[i] = (suf + 1) / n;
		h[a[i]] = i;
	}
	int p = 0, q;
	vector<int> stk;
	do {
		vis[p] = true;
		stk.push_back(p);
		p = fa[p];
	} while (!vis[p]);
	int sumcost = 0;
