const int MAX_N = 212345;
const int MAX_A = 212345;
int A[MAX_N * 2];
int nxt[MAX_N * 2];
int inc[MAX_N * 2];
int last[MAX_A];
ll vis[MAX_N * 2];
bool isin[MAX_A];

int main2() {
  int N = nextInt();
  ll K = nextLong();
  REP(i, N) A[i] = nextInt();
  REP(i, N) A[i + N] = A[i];

  CLR(last, -1);
  CLR(inc, 0);

  REP(i, 2 * N) {
    if (last[A[i]] >= 0) {
      nxt[ last[A[i]] ] = (i + 1) % N;
      inc[ last[A[i]] ] = (i + 1) >= N;
    }
    last[A[i]] = i;
  }
  // pv(A, A+N);
  // pv(nxt, nxt + N);
  // pv(inc, inc + N);

  CLR(vis, -1);
  ll k = 0;
  int pos = 0;
  while (vis[pos] == -1) {
    vis[pos] = k;
    k += inc[pos];
    pos = nxt[pos];
  }

  ll L = k - vis[pos];

  if (K - k >= 2) {
    k += (K - k - 1) / L * L;
  } else {
    k = 0;
    pos = 0;
  }

  while (k + 1 < K) {
    k += inc[pos];
    pos = nxt[pos];
  }

  CLR(isin, 0);
  vector<int> stack;

  for (; pos < N; pos++) {
    const int v = A[pos];
    if (isin[v]) {
      while (stack.back() != v) {
        isin[stack.back()] = false;
        stack.pop_back();
      }
      stack.pop_back();
      isin[v] = false;
    } else {
      stack.push_back(v);
      isin[v] = true;
    }
  }

  REP(i, stack.size()) {
    if (i > 0) cout << " ";
    cout << stack[i];
  }
  cout << endl;
  return 0;
}

