#include <bits/stdc++.h>

using namespace std;

const int N = 300 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;
const int L = 63;

using ll = uint64_t;

int n;
long long K;
int a[N + N], nx[N + N];
vector<int> vec[N];
ll up[N][L];

bool read() {
    if (!(cin >> n >> K))
        return false;

    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        a[n + i] = a[i];
    }

    return true;
}

void solve() {
    for (int i = 0; i < n + n; ++i)
        vec[a[i]].emplace_back(i);

    for (int i = 0; i < n; ++i) {
        nx[i] = *upper_bound(vec[a[i]].begin(), vec[a[i]].end(), i);
        up[i][0] = nx[i] - i + 1;
    }

    for (int j = 1; j < L; ++j)
        for (int i = 0; i < n; ++i) {
            ll d1 = up[i][j - 1];
            ll i1 = i + d1;
            ll d2 = up[i1 % n][j - 1];
            ll res = 0ull;

            if (d1 != 0 && d2 != 0 && !__builtin_uaddll_overflow(d1, d2, &res))
                up[i][j] = res; // pizdec spasibo blackav
            else
                up[i][j] = 0;
        }

        ll cur = 0;

        for (int j = L - 1; j >= 0; --j) {
            auto i = cur % n;
            ll res = 0ull;

            if (up[i][j] != 0 && !__builtin_uaddll_overflow(cur, up[i][j], &res) && res < K * n)
                cur = res;
        }

        assert(cur / n == K - 1);
        vector<int> res;

        for (int i = cur % n; i < n; )
            if (nx[i] < n) {
                i = nx[i] + 1;
            } else {
                res.emplace_back(a[i++]);
            }

        for (const auto& i : res)
            cout << i << ' ';

        cout << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

