vector<int> simulate(vector<int>& as, int start)
{
	vector<int> result;
	set<int> s;

	for(int i = start; i < (int)as.size(); i++) {

		int a = as[i];

		if(s.count(a) == 0) {
			s.insert(a);
			result.push_back(a);
			continue;
		}

		s.erase(a);
		while(result.back() != a) {
			s.erase(result.back());
			result.pop_back();
		}
		result.pop_back();
	}

	return result;
}

int main()
{
	int n;
	i64 k;
	vector<int> as;
	int max_a = 0;

	scanf("%d%lld", &n, &k);
	as.resize(n);
	for(int i = 0; i < n; i++) {
		scanf("%d", &as[i]);
		max_a = max(max_a, as[i]);
	}

	vector<int> last_pos(max_a + 1, -1);
	vector<int> head_item(n, 0);

	for(int i = n - 1; i >= 0; i--) {

		int a = as[i];
		int lp = last_pos[a];

		last_pos[a] = i;
		head_item[i] = (lp != -1) ? (lp < n - 1 ? head_item[lp + 1] : -1) : a;
		//printf("%d: %d, %d, %d\n", i, a, lp, head_item[i]);
	}

	vector<int> head, loop;
	set<int> in_head;

	int c = 0;

	while(true) {

		if(in_head.count(c) > 0) {
			while(head.back() != c) {
				loop.push_back(head.back());
				head.pop_back();
			}
			loop.push_back(c);
			head.pop_back();
			reverse(loop.begin(), loop.end());
			break;
		}

		head.push_back(c);
		in_head.insert(c);

		int h = head_item[c];
		c = (h == -1) ? 0 : (last_pos[h] + 1) % n;
	}

	/*for(auto h : head) {
		printf("head: %d\n", h);
	}
	for(auto h : loop) {
		printf("loop: %d\n", h);
	}*/

	int start = -1;
	k = k - 1;

	if(k < head.size()) {
		start = head[k];
	} else {
		start = loop[(k - head.size()) % loop.size()];
	}

	//printf("start: %d\n", start);

	vector<int> ans = simulate(as, start);

	for(int i = 0; i < (int)ans.size(); i++) {
		printf("%d%s", ans[i], i == ans.size() - 1 ? "" : " ");
	}
	printf("\n");

	return 0;
}

