    rep(i, n) scanf("%d", &a[i]);

    pil G[n];
    int next[MAX];
    rep(i, MAX) next[i] = n;
    rrep(i, n) next[a[i]] = n + i;
    rrep(i, n){
        lint dist = 1LL * (next[a[i]] - i + 1);
        int to = (next[a[i]] + 1) % n;
        next[a[i]] = i;
        G[i] = pil(to, dist);
