using namespace std;

void solve() {
  long N, K;
  cin >> N >> K;
  vector<long> A(N);
  rep (i, N) cin >> A[i];

  unordered_map<long, vector<long>> shutugen;
  rep (i, N) shutugen[A[i]].push_back(i);

  /*
  for (auto it: shutugen) {
    cout << it.first << ": ";
    for (auto a: it.second) cout << a << " ";
    cout << endl;
  }
  */

  // cout << "--- foo 1" << endl;

  vector<pair<long, long>> next_sentou(N);
  rep (i, N) {
    long a = A[i];
    auto vec = shutugen[a];
    auto it = upper_bound(vec.begin(), vec.end(), i);
    if (it == vec.end()) {
      long index = vec[0];
      long loop = 1;
      index++;
      if (index == N) { index = 0; loop++; }
      next_sentou[i] = make_pair(loop, index);
    } else {
      long index = *it;
      long loop = 0;
      index++;
      if (index == N) { index = 0; loop++; }
      next_sentou[i] = make_pair(loop, index);
    }
  }

  /*
  rep (i, N) {
    cout << i << ": " << next_sentou[i].first << ", " << next_sentou[i].second << endl;
  }
  */

  pair<long, long> current = make_pair(0, 0);
  map<long, pair<long, long>> visited;
  visited[current.second] = current;

  // cout << "--- foo 2" << endl;

  while (true) {
    // cout << "current:  " << current.first << ", " << current.second << endl;
    auto diff = next_sentou[current.second];
    pair<long, long> next = make_pair(current.first + diff.first, diff.second);
    // cout << "next:  " << next.first << ", " << next.second << endl;
    if (next.first >= K) break;
    current = next;
    if (visited.count(current.second)) {
      auto prev = visited[current.second];
      long loopdiff = current.first - prev.first;
      current.first += ((K - 1 - current.first) / loopdiff) * loopdiff;
    }
    visited[current.second] = current;
  }

  // cout << "--- foo 3" << endl;

  vector<long> ans;
  unordered_map<long, long> pos;

  for (long i = current.first * N + current.second; i < N * K; i++) {
    long num = A[i % N];
    if (pos.count(num) == 0) {
      pos[num] = ans.size();
      ans.push_back(A[i % N]);
    } else {
      ans = vector<long>(ans.begin(), ans.begin() + pos[num]);
      pos.erase(num);
    }
  }

  if (ans.size() == 0) return;

  bool flag = false;
  rep (i, ans.size()) {
    if (flag) cout << " ";
    flag = true;
    cout << ans[i];
  }
  cout << endl;
}

