int fst[maxn];
int nxt[maxn];
int dp[maxn];
int t[maxn];
int used[maxn];

void solve() {
  for (int i = 0; i < maxn; i++) {
    fst[i] = n;
  }
  for (int i = n - 1; i >= 0; i--) {
    nxt[i] = fst[a[i]];
    fst[a[i]] = i;
  }
  dp[n] = 0;
  for (int i = n - 1; i >= 0; i--) {
    if (nxt[i] == n) {
      dp[i] = a[i];
    } else {
      dp[i] = dp[nxt[i] + 1];
    }
  }
  for (int i = 0; i < maxn; i++) {
    t[i] = -1;
  }
  int x = 0;
  k--;
  int curt = 0;
  while (k && t[x] == -1) {
    t[x] = curt++;
    x = (x == 0 ? dp[0] : dp[fst[x] + 1]);
    k--;
  }
  if (k) {
    int per = curt - t[x];
    k %= per;
  }
  while (k) {
    x = (x == 0 ? dp[0] : dp[fst[x] + 1]);
    k--;
  }
  for (int i = 0; i < maxn; i++) {
    used[i] = false;
  }
  vector<int> ans;
  int pos = (x == 0 ? 0 : fst[x] + 1);
  for (int i = pos; i < n; i++) {
    if (!used[a[i]]) {
      used[a[i]] = true;
      ans.push_back(a[i]);
      continue;
    }
    int del = -1;
    while (del != a[i]) {
      del = ans.back();
      ans.pop_back();
      used[del] = false;
    }
  }
  for (int i = 0; i < sz(ans); i++) {
    printf("%d ", ans[i]);
  }
  printf("\n");
}

