int main(){
    int n;
    ll k;
    cin>>n>>k;

    vector<ll> a(n);
    for(int i=0;i<n;i++) cin>>a[i];

    vector<int> dp(n+1);
    {
        dp[n]=n;
        dp[n-1]=n-1;
        map<int,int> nex;
        nex[a[n-1]]=n-1;
        for(int i=n-2;i>=0;i--){
            if(nex.count(a[i])) dp[i]=dp[nex[a[i]]+1];
            else dp[i]=i;
            nex[a[i]]=i;

        }
    }
    map<int,int> mp;
    for(int i=n-1;i>=0;i--) mp[a[i]]=i;
    vector<int> p(n+1);
    p[n]=dp[0];
    for(int i=0;i<n;i++){
        int id=mp[a[i]];
        p[i]=dp[id+1];
        // cerr<<p[i]<<endl;
    }

    vector<int> pre;
    vector<int> loop;
    {   
        set<int> s;
        int v=dp[0];
        // cerr<<dp[0]<<endl;
        while(true){
            s.insert(v);
            pre.push_back(v);
            v=p[v];
            if(s.count(v)) break;
        }
        int id=find(pre.begin(),pre.end(),v)-pre.begin();
        for(int i=id;i<pre.size();i++) loop.push_back(pre[i]);
    }
    // for(int i=0;i<pre.size();i++) cerr<<pre[i]<<" ";
    // cerr<<"#"<<endl;
    int beg=(k-1<=pre.size() ? pre[k-1] : loop[(k-1-pre.size())%loop.size()]);

    // cerr<<beg<<endl;
    // cerr<<"#"<<endl;
    map<int,int> cnt;
    vector<int> res;
    for(int i=beg;i<n;i++){
        if(cnt[a[i]]){
            while(cnt[a[i]]){
                assert(res.size());
                cnt[res.back()]--;
                res.pop_back();
            }
        }
        else{
            cnt[a[i]]++;
            res.push_back(a[i]);
        }
    }
    // cerr<<"#"<<endl;
    for(int i=0;i<res.size();i++){
        cout<<res[i]<<(i+1==n ? "\n" : " ");
    }
    return 0;
}

