  unordered_map<ll, ll> mp1;
  vll next_index(2*N);
  REP(i,2*N){
    ll ii = i%N;
    if(mp1.find(A[ii])!=mp1.end()){
      next_index[mp1[A[ii]]] = i+1;
    }
    mp1[A[ii]] = i;
  }


  RREP(i,N-1){
    if(next_index[i]<N){
      next_index[i] = next_index[next_index[i]];
    }
  }

  /*
  REP(i,N){
    debug_print(i, next_index[i]);
  }
  */

  vll shift(N, 0);

  REP(i,N){
    if(next_index[i]>=2*N){
      shift[i] = 2;
    }else{
      shift[i] = 1;
    }
    next_index[i]%=N;
  }

  vvpll par(N, vpll(50));

  REP(i,N){
    par[i][0] = make_pair(next_index[i], shift[i]);
  }
  REP(j,49){
    REP(i,N){
      ll tmp1 = par[par[i][j].first][j].first;
      ll tmp2 = par[i][j].second + par[par[i][j].first][j].second;
      par[i][j+1] = make_pair(tmp1, tmp2);
    }
  }

  ll pos = 0;
