  RREP(i,49){
    if(par[pos][i].second>K) continue;
    K -= par[pos][i].second;
    pos = par[pos][i].first;
    //debug_print(pos, K);
  }

  deque<ll> que;
  unordered_map<ll, ll> mp2;
  for(ll i=pos; i<N*(K+1); ++i){
