vector<int> solve(int N, ll K, const vector<int>& A) {
    map<int, vector<int>> pos;
    REP(i, N) pos[A[i]].push_back(i);
    map<int, ll> seen;
    ll cur = 0;
    ll m = 0;
    while (true) {
        //debug(cur, m);
        if (!seen.insert({cur, m}).second) break;
        ++m;
        int next;
        if (cur == pos[A[cur]].back()) {
            next = pos[A[cur]].front();
            m += N-cur+next;
        } else {
            next = *upper_bound(pos[A[cur]].begin(), pos[A[cur]].end(), cur);
            m += next-cur;
        }
        cur = next+1;
        if (cur == N) cur = 0;
    }
    ll k = seen.find(cur)->second;
    m -= k;
    //ll M = N*K; // TODO too big
    //M = M < k ? M : (M - k) % m + k;
    ll M = N*(K % m) - (k % m);
    if (M < 0) M += m;
    M = M % m + k;
    //debug(N, K, A, m, k, M);
    //debug(solveSlow(N, K, A));

    ll curm = 0;
    cur = 0;
    while (true) {
        //debug("cur:", cur, curm);
        ll nextm, next;
        if (cur == pos[A[cur]].back()) {
            next = pos[A[cur]].front();
            nextm = curm+1 + N-cur+next;
        } else {
            next = *upper_bound(pos[A[cur]].begin(), pos[A[cur]].end(), cur);
            nextm = curm+1 + next-cur;
        }
        //debug("next:", next, nextm);
        if (nextm >= M) {
            vector<int> ans;
            set<int> s;
            //debug(curm, "->", M);
            REP(_, M-curm) {
                //debug("pos:", cur);
                if (!s.insert(A[cur]).second) {
                    while (ans.back() != A[cur]) s.erase(ans.back()), ans.pop_back();
                    s.erase(ans.back()), ans.pop_back();
                } else ans.push_back(A[cur++]);
                if (cur == N) cur = 0;
            }
            return ans;
        }
        curm = nextm;
        cur = next+1;
        if (cur == N) cur = 0;
    }
    assert(false);
    return vector<int>{};

    //return runSlow(N, M, A);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N; ll K; cin >> N >> K;
    vector<int> A(N);
    for (int& a : A) cin >> a;
    auto ans = solve(N, K, A);
    for (int a : ans) cout << a << " ";
    cout << '\n';

    return 0;
}

