void naive_solve(long long N, long long K, std::vector<long long> A) {

    set<int> C;

    vector<int> S;

    for (int i = 0; i < N * K; i++) {
        if (C.count(A[i % N])) {
            while (true) {
                int v = S.back();
                C.erase(v);
                assert(S.size() > 0);
                S.pop_back();

                if (v == A[i % N]) break;
            }

        } else {
            S.push_back(A[i % N]);
            C.insert(A[i % N]);
        }
    }
    for (auto i : S) {
        cout << i << " ";
    }
    cout << endl;
}

vector<long long> B[200010];
vector<long long> AA;
int dp[600010];

int nxt(int p) {
    if (p >= 2 * AA.size()) {
        return p; // possible to be p == A.size() * 2
    }
    if (dp[p] != -1) return dp[p];
    return dp[p] = nxt(*upper_bound(B[AA[p % AA.size()]].begin(), B[AA[p % AA.size()]].end(), p) + 1);
}


int apply(int N, long long K, vector<vector<long long>> perm) {
    int p = 0;
    for(int i = 0 ; i < 40 ; i++){
        if( K >> i & 1 ){
            p = perm[i][p];
        }
    }
    return p;
}

void solve(long long N, long long K, std::vector<long long> A) {
    if (K < 3) {
        naive_solve(N, K, A);
        return;
    }

    AA = A;
    memset(dp, -1, sizeof(dp));
    for (int i = 0; i < 200010; i++) B[i].clear();
    for (int i = 0; i < 3 * N; i++) {
        B[A[i % N]].push_back(i);
    }

    vector<vector<long long>> perm(40, vector<long long>(N));

    for (int i = 0; i < N; i++) {
        perm[0][i] = nxt(i) % N;
    }

    for (int i = 1; i < 40; i++) {
        for (int j = 0; j < N; j++) {
            perm[i][j] = perm[i - 1][perm[i - 1][j]];
        }
    }

    long long MTG = K - 1;
    long long MTG_2 = MTG / 2;
    int lst = apply(N, MTG_2, perm);

    vector<long long> real;


    for (int i = lst; i < N; i++) real.push_back(A[i]);
    if (MTG % 2) {
        for (int i = 0; i < N; i++) real.push_back(A[i]);
    }
    naive_solve(real.size(), 1, real);


}


