#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MAXN = 200005;

int A[MAXN];
ll nxt[MAXN][64];
vector<int> p[MAXN];
bitset<MAXN> inv;

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	ll N, K;
	cin >> N >> K;
	for (int i = 0; i < N; ++i) cin >> A[i];

	for (int i = 0; i < N; ++i) p[A[i]].push_back(i);
	for (int i = 0; i < MAXN; ++i) {
		if (!p[i].empty()) {
			for (int j = 0; j < p[i].size() - 1; ++j) nxt[p[i][j]][0] = p[i][j + 1] + 1 - p[i][j];
			nxt[p[i].back()][0] = p[i].front() + N + 1 - p[i].back();
		}
	}

	for (int j = 0; j < 63; ++j) {
		for (int i = 0; i < N; ++i) {
			if (nxt[i][j] <= N * K) nxt[i][j + 1] = nxt[i][j] + nxt[(i + nxt[i][j]) % N][j];
			else nxt[i][j + 1] = N * K + 1;
		}
	}

	ll x = 0;
	int cnt = 0;
	while (1) {
		int l = 0, h = 63;
		while (l < h) {
			int m = (l + h) >> 1;
			x + nxt[x % N][m] >= N * K ? h = m : l = m + 1;
		}
		if (h <= 0) break;
		x += nxt[x % N][h - 1];
	}

	vector<int> v;
	for (int i = x % N; i < N; ++i) {
		if (inv[A[i]]) {
			while (v.back() != A[i]) {
				inv[v.back()] = 0;
				v.pop_back();
			}
			inv[A[i]] = 0;
			v.pop_back();
		}
		else {
			inv[A[i]] = 1;
			v.push_back(A[i]);
		}
	}
	for (auto& i : v) cout << i << ' ';
}

