typedef long long LL;
const LL Inf = LLONG_MAX / 3;
const int MN = 400005;

int N, A[MN], buk[MN];
LL K, L, Dis[MN][61]; int Bit;
int stk[MN], tp;

int main() {
	scanf("%d%lld", &N, &K), L = N * K;
	for (int i = 1; i <= N; ++i) scanf("%d", &A[i]), A[N + i] = A[i];
	for (int i = N + N; i >= 1; --i) {
		if (i <= N) Dis[i][0] = buk[A[i]] - i + 1;
		buk[A[i]] = i;
	}
	for (int j = 0; j < 59; ++j) {
		LL Mn = Inf;
		for (int i = 1; i <= N; ++i)
			Dis[i][j + 1] = std::min(Inf, Dis[i][j] + Dis[(i + Dis[i][j] - 1) % N + 1][j]),
			Mn = std::min(Mn, Dis[i][j]);
		Bit = j + 1;
		if (Mn > L) break;
	}
	LL S = 1;
	for (int j = Bit; ~j; --j)
		if (S + Dis[(S - 1) % N + 1][j] <= L)
			S += Dis[(S - 1) % N + 1][j];
	for (int i = 1; i <= N; ++i) buk[A[i]] = 0;
	int p = N + N - L + S;
	for (int i = p; i <= N + N; ++i) {
		if (!buk[A[i]]) stk[++tp] = A[i], buk[A[i]] = 1;
		else {
			while (stk[tp] != A[i]) buk[stk[tp--]] = 0;
			buk[stk[tp--]] = 0;
		}
	}
	for (int i = 1; i <= tp; ++i) printf("%d%c", stk[i], " \n"[i == tp]);
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int MX = 200000;

int a[MX], fst[MX + 1], lst[MX + 1], seen[MX + 1];

int main() {
	int n;
	long long k;
	ignore = scanf("%d %lld", &n, &k);
	for (int i = 0; i < n; i++) ignore = scanf("%d", a + i);

	fill(lst, lst + n, -1);

	fst[n] = -1;
	for (int i = n - 1; i >= 0; i--) {
		int x = a[i];
		if (lst[x] == -1) fst[i] = x;
		else fst[i] = fst[lst[x] + 1];
		lst[x] = i;
	}

	fill(seen, seen + n + 1, -1);

	seen[n] = 0;
	seen[0] = 1;

	vector<int> f = {n, 0};
	for (int i = 2; i <= k; i++) {
		int p = f.back();
		if (fst[p] == -1) {
			f.push_back(0);
		}
		else {
			f.push_back(lst[fst[p]] + 1);
		}

		p = f.back();
		if (seen[p] != -1) {
			int s = seen[p];
			k = (k - s) % (i - s) + s;
		}
		else seen[p] = i;
	}

	vector<int> ans;
	set<int> S;
	for (int x = f[k]; x < n; x++) {
		if (S.insert(a[x]).second) {
			ans.push_back(a[x]);
		}
		else {
			while (S.count(a[x]) == 1) {
				S.erase(ans.back());
				ans.pop_back();
			}
		}
	}

	for (int x : ans) printf("%d ", x);
	printf("\n");

	return 0;
}

