  std::vector<int> a(n);
  for (auto& x : a)
  {
    std::cin >> x;
    x--;
  }
  std::vector<int> b;
  loop(2) std::copy(a.begin(), a.end(), std::back_inserter(b));
  int kind = 2e5;
  std::vector<long long> tab0(n);
  std::vector<int> prv(kind, -1);
  for (int i = 2 * n - 1; i >= 0; i--)
  {
    auto crr = b.at(i);
    if (i < n)
    {
      assert(prv.at(crr) != -1);
      tab0.at(i) = prv.at(crr) - i + 1;
    }
    prv.at(crr) = i;
  }
  constexpr long long inf = 1LL << 60;
  int  hight = std::log2(1e18);
  auto table = make_higher_vector<2, long long>(hight, n);
  table.at(0) = std::move(tab0);
  rep(p, 1, hight)
  {
    table.at(p) = table.at(p - 1);
    rep(i, 0, n)
    {
      auto dif1 = at(table, p - 1, i);
      auto dif2 = at(table, p - 1, (i + dif1) % n);
      at(table, p, i) = std::min(inf, dif1 + dif2);
    }
  }
  long long crr = 0;
  for (int p = hight - 1; p >= 0; p--)
  {
    long long next = std::min(inf, crr + at(table, p, crr % n));
    if (next < k)
    {
      crr = next;
    }
  }
  std::vector<int> having(kind, false);
  std::vector<int> ret;
  auto eat = [&] (int x)
  {
    auto& flag = having.at(x);
    if (flag)
    {
      while (true)
      {
        auto y = ret.back(); ret.pop_back();
        having.at(y) = false;
        if (y == x) break;
      }
    }
    else
    {
      ret.push_back(x);
      flag = true;
    }
  };
  while (crr < k)
  {
    auto pos = crr % n;
    eat(a.at(pos));
    crr++;
  }
  int ret_size = ret.size();
  for (int i = 0; i < ret_size; i++)
  {
    std::cout << (i > 0 ? " " : "") << ret.at(i) + 1;
  }
  std::cout << std::endl;
  return 0;
