int const MAXN = 2e5;

int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  int N; int64_t K; std::cin >> N >> K;
  std::vector<int> A(N+N);
  for(int i = 0; i < N; ++i) { std::cin >> A[i]; A[N+i] = A[i]; }
  std::vector<int> prev(MAXN+1, -1);
  std::vector<int> sk(N);
  for(int i = 0; i < N+N; ++i) {
    int p = prev[A[i]];
    if(0 <= p && p < N) sk[p] = i-p+1;
    prev[A[i]] = i;
  }
  std::vector<int64_t> sum({0});
  std::fill_n(prev.begin(), N, -1);
  prev[0] = 0;
  int b;
  for(;;) {
    int64_t nx = sum.back();
    nx += sk[nx%N];
    if(prev[nx%N] >= 0) {
      b = prev[nx%N];
      sum.push_back(nx);
      break;
    }
    prev[nx%N] = sum.size();
    sum.push_back(nx);
  }
  int64_t l = K*N;
  if(l >= sum[b]) {
    l -= sum[b];
    int64_t p = sum.back() - sum[b];
    l %= p;
    auto it = std::upper_bound(sum.begin(), sum.end(), l+sum[b]);
    if(it != sum.begin()) l -= *(it-1) - sum[b];
  } else {
    l -= *(std::upper_bound(sum.begin(), sum.end(), l)-1);
  }
  std::vector<int> ans;
  std::fill_n(prev.begin(), MAXN, -1);
  for(int i = N-l; i < N; ++i) {
    if(prev[A[i]] < 0) {
      prev[A[i]] = ans.size();
      ans.push_back(A[i]);
    } else {
      int nsz = prev[A[i]];
      while(ans.size() > nsz) {
        prev[ans.back()] = -1;
        ans.pop_back();
      }
    }
  }
  fin(ans);
  return 0;
}

