    a.assign(n, 0);
    for (int i = 0; i < n; ++i) cin >> a[i];
    vector<vector<i64>> nexts(n + 1, vector<i64>(50));
    map<i64, i64> fwds;
    for (i64 i = 0; i < n; ++i) {
        if (fwds.count(a[i]) == 0) {
            fwds[a[i]] = i + 1;
        }
    }
    for (i64 i = n - 1; i >= 0; --i) {
        nexts[i][0] = fwds[a[i]];
        fwds[a[i]] = i<n-1&&a[i]==a[i+1]?nexts[i+2][0]:nexts[i + 1][0];
    }
    for (i64 e = 1; e < 50; ++e) {
        for (i64 i = 0; i < n; ++i) {
            i64 j = nexts[i][e - 1];
            nexts[i][e] = nexts[j][e - 1];
        }
    }
    i64 p = 0;
    for (i64 e = 0; e < 50; ++e) {
        if ((k - 1) & (1ll << e)) {
            p = nexts[p][e];
        }
    }
    vector<i64> stk;
    map<i64, i64> ins;
    for (i64 i = p; i < n; ++i) {
        cerr << a[i] << '\t' << ins[a[i]] << endl;
        if (ins[a[i]] > 0) {
            while (true) {
                assert(!stk.empty());
                i64 x = stk.back();
                ins[x]--;
                stk.pop_back();
                if (x == a[i]) break;
