void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n;
	ll k;

	cin >> n >> k;

	vector<int> arr(n);

	for (auto &it : arr)
	{
		cin >> it;
		it--;
	}

	vector<vector<int>> pos((int) 2e5);

	for (int i = 0; i < arr.size(); i++)
		pos[arr[i]].push_back(i);

	int curr = 0, p = 0;

	do
	{
		auto nxt = lower_bound(pos[arr[p]].begin(), pos[arr[p]].end(), p);

		if (++nxt == pos[arr[p]].end())
		{
			nxt = pos[arr[p]].begin();
			curr++;
		}

		auto np = *nxt + 1;

		if (np == n)
		{
			np = 0;
			curr++;
		}

		if (curr >= k)
			break;
		p = np;
	} while (p != 0);

	if (p == 0 && curr < k)
		k %= curr;

	curr = 0;
	p = 0;

	do
	{
		auto nxt = lower_bound(pos[arr[p]].begin(), pos[arr[p]].end(), p);

		if (++nxt == pos[arr[p]].end())
		{
			nxt = pos[arr[p]].begin();
			curr++;
		}

		auto np = *nxt + 1;

		if (np == n)
		{
			np = 0;
			curr++;
		}

		if (curr >= k)
			break;
		p = np;
	} while (p != 0);


	vector<bool> used((int) 2e5);
	vector<int> s;

	for (int i = p; i < n; i++)
	{
		auto it = arr[i];

		if (used[it])
		{
			while (used[it])
			{
				used[s.back()] = false;
				s.pop_back();
			}
		}
		else
		{
			used[it] = true;
			s.push_back(it);
		}
	}

	for (auto it : s)
		cout << it + 1 << ' ';
	cout << endl;
}


