signed main() {
    int N, K;
    cin >> N >> K;
    vector<int> A(N);

    map<int, set<int>> m;

    for (int i = 0; i < N; i++) {
        cin >> A[i];
        m[A[i]].insert(i);
    }

    vector<int> next(N, N);
    for (int i = 0; i < N; i++) {
        auto it = m[A[i]].upper_bound(i);
        if (it == m[A[i]].end()) continue;
        next[i] = *it;
    }

    int D = 1;
    int idx = 0;
    vector<int> first_idxs;
    while (true) {
        int nxt = next[idx];
        if (nxt == N) {
            nxt = *m[A[idx]].begin();
            D++;

            first_idxs.push_back(idx);
        }

        idx = (nxt + 1) % N;
        if (idx == 0) break;
    }

    // 周期
    K = K % D;
    if (K == 0) return 0;

    int first_idx = first_idxs[K - 1];

    vector<int> ans;
    for (int i = first_idx; i < N;) {
        if (next[i] != N) {
            i = next[i] + 1;
        } else {
            ans.push_back(A[i]);
            i++;
        }
    }

    int M = ans.size();
    for (int i = 0; i < M; i++) {
        cout << ans[i];
        if (i != M - 1) cout << " ";
    }
    cout << endl;

    return 0;
}

