std::vector<int> eval(std::vector<int> & x) {
	std::vector<int> vec;
	std::set<int> st;
	for(auto v: x) {
		if(st.count(v)) {
			while(st.count(v)) {
				int p = vec.back();
				vec.pop_back();

				st.erase(p);
			}
		} else {
			st.insert(v);
			vec.push_back(v);
		}
	}

	return vec;
}

