int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  ll n,k; cin>>n>>k;
  vector<int> A(n); for (auto& a:A) cin>>a;

  auto put_ans = [&](int i, ll sum) {
    set<int> Sx;
    vector<int> S;
    for (; sum < k*n; i++, sum++) {
      auto x = A[i%n];
      if (Sx.count(x) == 0) {
        S.push_back(x);
        Sx.insert(x);
      } else {
        while (Sx.count(x)) {
          Sx.erase(S.back());
          S.pop_back();
        }
      }
    }
    for (auto s:S) {
      cout << s << " ";
    }
    cout << endl;
  };

  if (k == 1) {

    put_ans(0, 0);

  } else {

    vector<pair<int,ll>> nxt(n);
    map<int,int> lst;
    for (int i = 0; i < n; i++) {
      auto a = A[i];
      if (lst.count(a) == 0) {
        lst[a] = i;
        nxt[i] = {(i + 1) % n, n + 1};
      } else {
        nxt[i] = {nxt[lst[a]].first, nxt[lst[a]].second - (i - lst[a])};
        nxt[lst[a]] = {(i + 1) % n, i + 1 - lst[a]};
        lst[a] = i;
      }
    }

    constexpr int LOGNK = 54;
    vector<vector<pair<int,ll>>> dbl(LOGNK, vector<pair<int,ll>>(n));
    for (int i = 0; i < n; i++) {
      dbl[0][i] = nxt[i];
    }
    for (int j = 1; j < LOGNK; j++) {
      for (int i = 0; i < n; i++) {
        auto fst = dbl[j-1][i];
        auto nxt = dbl[j-1][fst.first];
        dbl[j][i] = {nxt.first,
                     fst.second + nxt.second};
      }
    }

    int i = 0;
    ll sum = 0;
    for (int j = LOGNK; j >= 0; j--) {
      if (sum + dbl[j][i].second <= k*n) {
        sum += dbl[j][i].second;
        i = dbl[j][i].first;
      }
    }
    put_ans(i, sum);

  }

  return 0;
}

