			if(from == n - 1 && to == n - 1){
				cost[0][from] = 2;
				nxt[0][from] = (to + 1) % n;
			} else if(to <= from || to == n - 1){
				cost[0][from] = 1;
				nxt[0][from] = (to + 1) % n;
			} else {
				cost[0][from] = 0;
				nxt[0][from] = (to + 1) % n;
