  }
  vector<vector<ll>> jump(64, vector<ll>(N, 0));
  vector<int> b(200001, -1);
  int j = 1;
  dump(a);
  for (int j = 1, i = 0; i < N * 2; i++) {
    int t = b[a[i % N]];
    if (t < 0) {
      b[a[i % N]] = i;
    } else {
      if (t < N)
        jump[j][t] = i - t + 1;
      b[a[i % N]] = i;
    }
  }
  int mbit = 1;
  for (int j = 2; j < 64; j++) {
    for (int i = 0; i < N; i++) {
      ll t = jump[j - 1][i];
      jump[j][i] = jump[j - 1][(t + i) % N] + t;
    }
    if ((ll)N * K <= jump[j][0]) {
      mbit = j + 1;
      break;
