const int SIZE = 1 << 17;
int pointer = SIZE;
char buffer[SIZE];

char Advance() {
    if (pointer == SIZE) {
        fread(buffer, 1, SIZE, stdin);
        pointer = 0;
    }
    return buffer[pointer++];
}

int Read() {
    int answer = 0;
    char ch = Advance();
    while (!isdigit(ch))
        ch = Advance();
    while (isdigit(ch)) {
        answer = answer * 10 + ch - '0';
        ch = Advance();
    }
    return answer;
}

const int MAXN = 200000;
const int MAXVAL = 200000;
const int MAXLOG = 57;
const long long INF = 1000000000000000000LL;

int Stack[1 + MAXN], top = 0, v[1 + MAXN];
bool in[1 + MAXVAL];
int last[1 + MAXVAL], first[1 + MAXVAL];
int go[1 + MAXLOG][1 + MAXN];
long long add[1 + MAXLOG][1 + MAXN];

int main() {
    //freopen("tema.in", "r", stdin);
    //freopen("tema.out", "w", stdout);
    int n;
    long long k;
    scanf("%d%lld", &n, &k);
    k *= n;
    for (int i = 1; i <= n; i++)
        scanf("%d", &v[i]);
    for (int i = n; i >= 1; i--)
        if (!last[v[i]])
            last[v[i]] = first[v[i]] = i;
        else {
            go[0][i] = first[v[i]] % n + 1;
            add[0][i] = first[v[i]] - i + 1;
            first[v[i]] = i;
        }
    for (int i = 1; i <= MAXVAL; i++)
        if (last[i]) {
            go[0][last[i]] = first[i] % n + 1;
            add[0][last[i]] = n - last[i] + first[i] + 1;
        }
    for (int i = 1; i <= MAXLOG; i++)
        for (int j = 1; j <= n; j++) {
            go[i][j] = go[i - 1][go[i - 1][j]];
            add[i][j] = min(INF, add[i - 1][j] + add[i - 1][go[i - 1][j]]);
        }
    int x = 1;
    for (int i = MAXLOG; i >= 0; i--)
        if (add[i][x] <= k) {
            k -= add[i][x];
            x = go[i][x];
        }
    for (int i = 1; i <= k; i++, x = x % n + 1) {
        if (!in[v[x]]) {
            top++;
            Stack[top] = v[x];
            in[v[x]] = true;
        }
        else {
            while (Stack[top] != v[x]) {
                in[Stack[top]] = false;
                top--;
            }
            top--;
            in[v[x]] = false;
        }
    }
    for (int i = 1; i <= top; i++)
        printf("%d ", Stack[i]);
    return 0;
}

