int main(){
  const int n = getInt();
  const int k = getInt();
  vector<int> a(n);
  REP(i,n) a[i] = getInt();

  map<int, int> m;
  vector<int> next(n);
  REP(_,2){
    REP(j,n){
      const int i = n - 1 - j;
      next[i] = m[a[i]];
      m[a[i]] = i;
    }
  }

  vector<int> dp(n, -1);
  int index = 0;
  int loop = 0;

  while(true){
    // printf("!%d %d\n", loop, index);
    if(loop == k - 1){
      break;
    }
    if(dp[index] != -1){
      const int lastLoop = dp[index];
      const int diff = loop - lastLoop;
      loop += diff * ((k - 1 - loop) / diff);
      while(loop < k - 1){
	const int i = next[index];
	if(i <= index || i == n - 1) loop++;
	index = (i + 1) % n;
      }
      break;
    }else{
      dp[index] = loop;

      const int i = next[index];
      if(i <= index || i == n - 1) loop++;
      index = (i + 1) % n;
    }
  }

  set<int> s;
  vector<int> ans;
  for(int i = index; i < n; i++){
    if(s.count(a[i])){
      while(true){
	const int t = ans.back();
	ans.pop_back();
	s.erase(t);
	if(t == a[i]) break;
      }
    }else{
      ans.push_back(a[i]);
      s.insert(a[i]);
    }
  }

  REP(i,ans.size()){
    if(i) printf(" ");
    printf("%d", ans[i]);
  }
  puts("");

  return 0;
}

