		pos[i] = n;
	}
	for (int i = n - 1; ~i; --i) {
		nx[i] = pos[a[i]];
		pos[a[i]] = i;
	}
	for (int i = 0; i < n; ++i) {
		if (nx[i] == n) {
			nx[i] = pos[a[i]];
		}
	}
	int p = 0, len = 0;
	do {
		int w = (nx[p] <= p) + (nx[p] == n - 1);
		len += w;
		p = (nx[p] + 1) % n;
	} while (p != 0);
	if (k % len == 0) {
		return 0;
	}
	k %= len;
	while (k > 1) {
