int N, A[200009], nx[200009], c[200009], P[200009];
long long K, L, fi[200009], a, b;

void putans(int x) {
	vector<int> S;
	vector<bool> chk(200009, 0);
	for(int i=x; i<N; i++) {
		if(chk[A[i]]) {
			while(chk[A[i]]) {
				chk[S.back()] = 0;
				S.pop_back();
			}
		}
		else {
			chk[A[i]] = 1;
			S.push_back(A[i]);
		}
	}
	for(auto& it: S) printf("%d ", it);
	exit(0);
}

void go(int i, long long d) {
	if(fi[i] != -1) {
		a = fi[i];
		b = d - fi[i];
		return;
	}
	fi[i] = d;
	go(nx[i], d + c[i]);
}

void Do(int i, long long d) {
	if(d + c[i] <= L) Do(nx[i], d + c[i]);
	else putans(i);
}

int main() {
	scanf("%d%lld",&N,&K);
	L = K*N;
	for(int i=0; i<N; i++) {
		scanf("%d",&A[i]);
		A[i+N] = A[i];
		fi[i] = -1;
	}
	for(int i=2*N-1; i>=0; i--) {
		if(i < N) nx[i] = (P[A[i]] + 1) % N, c[i] = P[A[i]] - i + 1;
		P[A[i]] = i;
	}
	go(0, 0);
	if(L <= a) Do(0, 0);
	else {
		L -= a;
		L %= b;
		if(L == 0) return 0;
		Do(0, 0);
	}
	return 0;
}

