void pop_init(){
    for(ll i=table_num;i<table_num + n;i++){
        table[i] = x[i - table_num]; 
    }
    table_num += n;
    return;
}

void action(){
    ll used[200005];
    for(int i=0;i<=200000;i++){
        used[i] = 0;
    }
    ll table_copy[200005];
    ll action_num = 0;
    for(int i=0;i<table_num;i++){
        //looking at value
        ll look = table[i];
        if(used[look] == 0){
            table_copy[action_num++] = look;
            used[look]++;
        }else{
            used[look] = 0;
            while(1){
                action_num--;
                if(table_copy[action_num] == look){
                    table_copy[action_num] = 0;
                    break;
                }else{
                    used[table_copy[action_num]] --;
                    table_copy[action_num] = 0;
                }
            }
        }
    }
    for(ll i=0;i<action_num;i++){
        table[i] = table_copy[i];
    }
    table_num = action_num;
    return;
}
