VVL doubling(ll N, const VL &A) {
    VL used(200010, -1);
    VVL ret(61, VL(N));
    REP(k, 2) REP(i, N) {
        if(used[A[i]] != -1) {
            ret[0][used[A[i]] % N] = k * N + i - used[A[i]] + 1;
        }
        used[A[i]] = k * N + i;
    }
    FOR(k, 1, 60) REP(i, N) {
        ret[k][i] = ret[k - 1][i] + ret[k - 1][(i + ret[k - 1][i]) % N];
    }
    return ret;
}

signed main() {
    cin >> N >> K;
    REP(i, N) cin >> A[i];
    VVL dbl = doubling(N, A);
    ll now = 0, sum = 0, C = N * K;
    while(1) {
        ll num = 0;
        REP(k, 60) {
            if(dbl[k][now] + sum >= C) {
                num = k - 1;
                break;
            }
        }
        if(num == -1) break;
        sum += dbl[num][now];
        now = sum % N;
    }
    vector<bool> exist(N, false);
    stack<ll> st;
    while(sum < C) {
        if(!exist[A[now]]) {
            st.emplace(A[now]);
            exist[A[now]] = true;
        } else {
            while(exist[A[now]]) {
                exist[st.top()] = false;
                st.pop();
            }
        }
        now++;
        if(now == N) break;
    }
    VL ans;
    while(st.size()) {
        ans.emplace_back(st.top());
        st.pop();
    }
    REPR(i, ans.size() - 1) cout << ans[i] << (i ? " " : "\n");
}

