  map<ll, ll> mp;
  rep(i, n) mp[a[i]] = -1;
  vector<vector<ll>> dp;
  vector<ll> res(n);
  rep(i, 2 * n) {
    if (mp[a[i % n]] != -1 && mp[a[i % n]] < n) res[mp[a[i % n]]] = i - mp[a[i % n]] + 1;
