void solve(long long N, long long K, std::vector<long long> A){
  vector<ll> cpy_A=A;
  sort(cpy_A.begin(),cpy_A.end());
  cpy_A.erase(unique(cpy_A.begin(),cpy_A.end()),cpy_A.end());
  if(cpy_A.size()==A.size()){
    copy(A.begin()+(K-1),prev(A.end()),ostream_iterator<ll>(cout," "));
    cout<<A.back()<<endl;
    return;
  }
  vector<vector<ll>> idxs(200000);
  REP(N){
    idxs[A[i]].push_back(i);
  }
  ll loop=0;
  ll pprev=0;
  vector<ll> loops;
  do{
    auto itr=lower_bound(idxs[A[pprev]].begin(),idxs[A[pprev]].end(),pprev);
    itr=next(itr);
    if(itr==idxs[A[pprev]].end()){
      ++loop;
      pprev=(idxs[A[pprev]].front()+1)%N;
    }else{
      pprev=(*itr+1)%N;
    }
  }while(pprev!=0);
  ++loop;
  dump(loop);
  K=K%loop;
  if(K==0){
    cout<<endl;
    return;
  }else{
    ll l=loops[K];
    vector<ll> ans;
    for(int i=l;i<N;++i){
      auto itr=idxs[A[i]].begin();
      if((itr=upper_bound(idxs[A[i]].begin(),idxs[A[i]].end(),i))!=idxs[A[i]].end()){
        i=*itr;
      }else{
        ans.push_back(A[i]);
      }
    }
    REP(ans.size()){
      cout<<ans[i];
      if(ans.size()-1==i){
        cout<<endl;
      }else{
        cout<<" ";
      }
    }
  }
}

int main(){
    long long N;
    scanf("%lld",&N);
    long long K;
    scanf("%lld",&K);
    std::vector<long long> A(N-1-0+1);
    for(int i = 0 ; i < N-1-0+1 ; i++){
        scanf("%lld",&A[i]);
    }
    solve(N, K, std::move(A));
    return 0;
}

