const size_t BUFF = 1 << 19;
char ibuf[BUFF], *ib = ibuf, *ie = ibuf;
char getc() {
    if (ib == ie) {
        ib = ibuf;
        ie = ibuf + fread(ibuf, 1, BUFF, stdin);
    }
    return ib == ie ? -1 : *ib++;
}

}

LL read() {
    using namespace _buff;
    LL ret = 0;
    bool pos = true;
    char c = getc();
    for (; (c < '0' || c > '9') && c != '-'; c = getc()) {
        assert(~c);
    }
    if (c == '-') {
        pos = false;
        c = getc();
    }
    for (; c >= '0' && c <= '9'; c = getc()) {
        ret = (ret << 3) + (ret << 1) + (c ^ 48);
    }
    return pos ? ret : -ret;
}

const size_t N = 2e5 + 5;
const size_t L = 60;

int n;
LL k, a[N], g[L][N];

int main() {
    n = read();
    k = read();
    generate_n(a, n, read);

    map<int, int> mp;
    for (int i = n - 1; ~i; --i) {
        mp[a[i]] = i + n;
    }
    for (int i = n - 1; ~i; --i) {
        g[0][i] = mp[a[i]] - i + 1;
        mp[a[i]] = i;
    }
    for (int i = 1; i < L; ++i) {
        for (int j = 0; j < n; ++j) {
            g[i][j] = g[i - 1][(j + g[i - 1][j]) % n] + g[i - 1][j];
            if (g[i][j] > 1e18) g[i][j] = 1e18;
        }
    }
    LL pos = 0;
    for (int i = L - 1; i >= 0; --i) {
        if ((pos + g[i][pos % n]) <= n * k) {
            pos += g[i][pos % n];
        }
    }

    deque<int> q;
    set<int> s;
    for (; pos < n * k; ++pos) {
        int val = a[pos % n];
        if (s.count(val)) {
            int t;
            do {
                t = q.back();
                s.erase(t);
                q.pop_back();
            } while (t != val);
        } else {
            s.emplace(val);
            q.push_back(val);
        }
    }

    while (q.size()) {
        printf("%d ", q.front());
        q.pop_front();
    }
    return 0;
}

