#include <bits/stdc++.h>
using namespace std;

int main () {

  long long N, K;
  cin >> N >> K;

  vector<long long> A(2 * N + 1);
  for (long long i = 0; i < N; i++) {
    long long a;
    cin >> a;
    A[i] = a;
    A[N + i] = a;
  }

  vector<long long> next(N);

  for (long long i = 0; i < N; i++) {
    for (long long j = i + 1; ; j++) {
      if (A[i] == A[j]) {
        next[i] = j;
        break;
      }
    }
  }

  long long period = 0;
  long long a = 0;

  while (period == 0 || a != 0) {
    period += next[a] - a + 1;
    a = (next[a] + 1) % N;
  }

  long long rest = K * N % period;

  a = 0;

  while (true) {

    if (rest == 0) return 0;

    else if (rest >= next[a] - a + 1) {
      rest -= (next[a] - a + 1);
      a = (next[a] + 1) % N;
    }

    else {

      stack<long long> ans;
      set<long long> S;

      for (long long i = 0; i < rest; i++) {
        if (!S.count(A[a + i])) {
          ans.push(A[a + i]);
          S.insert(A[a + i]);
        }
        else {
          while (ans.top() != A[a + i]) {
            S.erase(ans.top());
            ans.pop();
          }
          S.erase(ans.top());
          ans.pop();
        }
      }

      vector<long long> vec;

      while (!ans.empty()) {
        vec.push_back(ans.top());
        ans.pop();
      }

      reverse(vec.begin(), vec.end());

      for (long long i = 0; i < vec.size(); i++) {
        cout << vec[i] << " ";
      }

      return 0;

    }
  }

}

#include <iostream>
#include <cstdio>
#include <vector>
#include <stack>
