using namespace std;

typedef long long ll;
typedef pair<int,ll> pil;

const int N = 2e5 + 5;
const int LOG = 50;

int a[N];
int first[N], last[N];
pil nxt[LOG][N];
int u[N];

int main()
{
    int n;
    ll k;
    scanf("%d%lld", &n, &k);
    --k;

    for (int x = 0; x < N; ++x)
        first[x] = last[x] = -1;

    for (int i = 0; i < n; ++i)
    {
        scanf("%d", a + i);
        if (first[a[i]] == -1)
            first[a[i]] = i;
        else
            nxt[0][last[a[i]]] = {(i + 1) % n, i + 1 == n};
        last[a[i]] = i;
    }
    for (int x = 0; x < N; ++x)
        if (last[x] != -1) nxt[0][last[x]] = {(first[x] + 1) % n, 1};

    for (int t = 0; t < LOG - 1; ++t)
    {
        for (int i = 0; i < n; ++i)
        {
            int j = nxt[t][i].first;
            nxt[t + 1][i] = {nxt[t][j].first, nxt[t][j].second + nxt[t][i].second};
        }
    }

    int pos = 0;
    for (int t = LOG - 1; t >= 0; --t)
    {
        if (nxt[t][pos].second <= k)
        {
            k -= nxt[t][pos].second;
            pos = nxt[t][pos].first;
            t = LOG - 1;
        }
    }

    stack<int> St;
    for (int x = 0; x < N; ++x)
        u[x] = 0;
    for (int i = pos; i < n; ++i)
    {
        if (!u[a[i]])
            St.push(a[i]);
        else
        {
            while(St.top() != a[i])
            {
                u[St.top()] = 0;
                St.pop();
            }
            St.pop();
        }

        u[a[i]] ^= 1;
    }

    vector<int> out;
    while(!St.empty())
    {
        out.push_back(St.top());
        St.pop();
    }

    reverse(out.begin(), out.end());
    for (int x : out)
        printf("%d ", x);
}

