    idx = K;
  } else {
    idx = offset + ((K-offset+idx-2) % (idx-offset));
  }

  t = l[idx];

  if (t == -1) {
    o = p[0];
  } else {
    o = p[pr[t]+1];
  }

  // std::cout << t << std::endl;
  // std::cout << o << std::endl;

  vector<long long> ans;
  while (true) {
    if (o == -1) {
      break;
    }
    t = A[o];
    ans.push_back(t);
    o = p[o+1];
  }

