  rrep(i, n) {
    int ne = i;
    while(cnt[ne] == 0) {
      ne = next[ne];
    }
    next[i] = next[ne];
    cnt[i] = 1;
  }
  Doubling dbl(n, next, k);
  int p = dbl.query(0, k-1);
  if(p == 0) cout << "\n";
  else {
    deque<ll> q;
    set<ll> se;
    for(int i=p; i<n; i++) {
      if(se.count(A[i])) {
        while(q.back() != A[i]) {
          se.erase(q.back());
          q.pop_back();
        }
        se.erase(q.back());
        q.pop_back();
      } else {
        q.push_back(A[i]);
        se.insert(A[i]);
      }
    }
    while(!q.empty()) {
      cout << q.front() << ' ';
      q.pop_front();
    }
    cout << "\n";
  }
  return 0;
}

