int n;
long long k;
int a[200000];

set<int> pos[200001];
int nxt[200000];



pair<long long, int> nearest_clear() {
	map<int, long long> memo;
	long long ti = 0;
	int p = 0;

	while (1) {
		int np = nxt[p];
		int t;
		if (p < np) {
			t = np - p + 1;
		}
		else {
			t = n - p + np + 1;
		}
		if (ti + t > n * k)break;

		ti += t;
		p = (np + 1) % n;

		auto it = memo.find(p);
		if (it != memo.end()) {
			long long past = ti - it -> second;
			long long rem = n * k - ti;

			ti += rem - rem % past;
		}
		else {
			memo[p] = ti;
		}
	}
	return make_pair(ti, p);
}


