    memset(vis, -1, sizeof(vis));
    ff(i, 0, n - 1) {
        scanf("%d", &a[i]);
        a[i + n] = a[i];
    }
    ff(i, 0, 2 * n - 1) {
        if(vis[a[i]] == -1) {
            vis[a[i]] = i;
            dp[i][0] = n;
        }
        else {
            dp[vis[a[i]]][0] = i - vis[a[i]];
            vis[a[i]] = i;
            dp[i][0] = n;
        }
    }
    ff(i, 1, 59) {
        ff(j, 0, n - 1) {
            if(dp[j][i - 1] == -1 || dp[(j + dp[j][i - 1] + 1) % (ll)n][i - 1] == -1) {
                dp[j][i] = -1;
            }
            else
            dp[j][i] = dp[j][i - 1] + dp[(j + dp[j][i - 1] + 1) % (ll)n][i - 1] + 1;
            if(dp[j][i] >= d)
                dp[j][i] = -1;
        }
    }
    int now = 0;
    ll up = d;
    fs(i, 59, 0) {
        if(dp[now][i] != -1) {
            if(dp[now][i] + 1 <= up) {
                up -= (dp[now][i] + 1);
                now = (dp[now][i] + now + 1) % n;
            }
        }
    }
    int s = 0;
    memset(vis, -1, sizeof(vis));
    ff(i, n - up, n - 1) {
        if(vis[a[i]] == -1) {
            vis[a[i]] = i;
            s++;
            ans[s] = a[i];

        }
        else {
            while(ans[s] != a[i]) {
                vis[ans[s]] = -1;
                s--;
            }
            vis[ans[s]] = -1;
            s--;
        }
    }
    ff(i, 1, s) {
        printf("%d ", ans[i]);
    }
    return 0;
}

