signed main(){
	cin>>N>>K;
	rep(i,N)cin>>A[i];
	rep(i,N)pos[A[i]].pb(i);
	rep(i,222222){
		if(pos[i].size()==0)continue;
		rep(j,pos[i].size()){
			int x;
			if(j+1<pos[i].size()){
				x=pos[i][j+1];
			}
			else{
				x=pos[i][0];
			}
			nex[pos[i][j]]=x;
		}
	}


	memset(dist,-1,sizeof(dist));
	int v=0;
	int d=1;
	while(true){
		int u=nex[v];
		int nd=d;
		if(u<=v)nd++;
		if(nd>K)break;
		u++;
		if(u==N){
			u=0;
			nd++;
		}
		if(nd>K)break;
		v=u;
		d=nd;
		if(dist[v]!=-1){
			int m=d-dist[v];
			int tmp=(K-d)/m;
			d+=tmp*m;
			break;
		}
		dist[u]=nd;
	}


	vint ans;
	while(d<=K){
		int u=nex[v];
		int nd=d;
		if(u<=v)nd++;
		if(nd>K){
			ans.pb(A[v]);
			v++;
			if(v==N){
				v=0;
				d++;
			}
			continue;
		}

		v=u+1;
		d=nd;
		if(v==N){
