typedef long long ll;
typedef pair<int, int> ii;

const int N = 2e5 + 5; 
int n, a[N], nxt[N], vis[N]; 
ll sum[N][60], k; 
int jump[N][60]; 

int main() {
  scanf("%d %lld", &n, &k); 
  for(int i = 0; i < n; ++i) {
    scanf("%d", &a[i]); 
  }

  for(int i = n - 1; i >= 0; --i) {
    nxt[a[i]] = n + i; 
  }
  for(int i = n - 1; i >= 0; --i) {
    jump[i][0] = (nxt[a[i]] + 1) % n;
    if(nxt[a[i]] + 1 >= n) sum[i][0] = 1; 
    if(nxt[a[i]] + 1 >= 2 * n) sum[i][0] = 2;
    nxt[a[i]] = i;
  }

  int lg = log2(n * k);
  for(int j = 1; j <= lg; ++j) {
    for(int i = 0; i < n; ++i) {
      jump[i][j] = jump[jump[i][j - 1]][j - 1]; 
      sum[i][j] = sum[i][j - 1] + sum[jump[i][j - 1]][j - 1]; 
    }
  }

  int idx = 0;
  ll tot = 1; 
  for(int i = lg; i >= 0; --i) {
    if(tot + sum[idx][i] <= k) {
      tot += sum[idx][i]; 
      idx = jump[idx][i];
    }
  }

  vector<int> v;

  if(tot != k && idx == n - 1) {
    v.push_back(a[idx]); 
    vis[a[idx]] = 1; 
    idx = 0; 
  }

  for(int i = idx; i < n; ++i) {
    if(!vis[a[i]]) {
      vis[a[i]] = 1; 
      v.push_back(a[i]); 
    } else {
      while(vis[a[i]]) {
        vis[v.back()] = 0; 
        v.pop_back();
      }
    }
  }


  for(int x : v) printf("%d ", x); 
  puts("");
}

