ll cnt=0;
ll startr[MAXN];
ll rs[MAXN];

vi ans;

set<ll> ind[MAXN];

void brute(int u){
	bool occ[MAXN];

	forn(i,u,n)
	{
		if(!occ[arr[i]]){
			ans.pb(arr[i]);
			occ[arr[i]]=1;
		}

		else{
			while(occ[arr[i]]){
				occ[ans.back()]=0;
				ans.pop_back();
			}
		}
	}
}

int next(int u){
	startr[u]=cnt;

	set<ll>::iterator it = ind[arr[u]].upper_bound(u);
	if(it!=ind[arr[u]].end()) return *it;

	cnt++;
	return *ind[arr[u]].lower_bound(0);
}

int main()
{
	ios_base::sync_with_stdio(0); cin.tie(0);
	mset(startr,-1);

	cin>>n>>k;
	forn(i,0,n){
		cin>>arr[i];
		ind[arr[i]].insert(i);
	}

	int cur=0;
	while(cnt<k && startr[cur]==-1){
		rs[cnt]=cur;

		cur=next(cur);
		cur++;
		if(cur==n){
			cnt++;
			cur-=n;
		}		
	}

	//forn(i,0,n) cout<<"startr["<<i<<"]="<<startr[i]<<'\n';
	//forn(i,0,n) cout<<"rs["<<i<<"]="<<rs[i]<<'\n';
	//watch(cnt); watch(cur);

	if(cnt>=k){
		if(rs[cnt-1]<n) brute(rs[cnt-1]);
	}
	else{
		ll period=cnt-startr[cur]; watch(period); watch(startr[cur]);
		k-=startr[cur];
		k%=period;
		k--;
		if(k<0) k+=period;
		brute(rs[startr[cur]+k]);
	}

	forn(i,0,ans.size()) cout<<ans[i]<<" ";
	cout<<'\n';

	return 0;
}

