        D[as] = start;
        if (start >= N || U[start])
        {
            as = ((i + 1) + K % (i + 1) - 1) % (i + 1);
            break;
        }
    }

    vector<ll> v;
    memset(U, 0, sizeof(U));
    FOR(i, N, D[as])
    {
        if (!U[A[i]])
        {
            U[A[i]] = true;
            v.push_back(A[i]);
            continue;
        }
        while (true)
        {
            ll t = v[v.size() - 1];
            v.pop_back();
            U[t] = false;
            if (t == A[i])
                break;
        }
    }

    REP(i, v.size())
    {
        cout << v[i] << " ";
    }
