  auto put_ans = [&](int i, ll sum) {
    set<int> Sx;
    vector<int> S;
    for (; sum < k*n; i++, sum++) {
      auto x = A[i%n];
      if (Sx.count(x) == 0) {
        S.push_back(x);
        Sx.insert(x);
      } else {
        while (Sx.count(x)) {
          Sx.erase(S.back());
          S.pop_back();
        }
      }
    }
    for (auto s:S) {
      cout << s << " ";
    }
    cout << endl;
  };

  if (k == 1) {

    put_ans(0, 0);

  } else {

    vector<pair<int,ll>> nxt(n);
    map<int,int> lst;
    for (int i = 0; i < n; i++) {
      auto a = A[i];
      if (lst.count(a) == 0) {
        lst[a] = i;
        nxt[i] = {(i + 1) % n, n + 1};
      } else {
        nxt[i] = {nxt[lst[a]].first, nxt[lst[a]].second - (i - lst[a])};
        nxt[lst[a]] = {(i + 1) % n, i + 1 - lst[a]};
        lst[a] = i;
      }
    }

    constexpr int LOGNK = 60;
    vector<vector<pair<int,ll>>> dbl(LOGNK, vector<pair<int,ll>>(n, {-1,-1}));
    for (int i = 0; i < n; i++) {
      dbl[0][i] = nxt[i];
    }
    for (int j = 1; j < LOGNK; j++) {
      for (int i = 0; i < n; i++) {
        auto fst = dbl[j-1][i];
        if (fst.first == -1)
          continue;
        auto scd = dbl[j-1][fst.first];
        if (scd.first == -1 or fst.second + scd.second > k*n) {
          continue;
        }
        dbl[j][i] = {scd.first,
                     fst.second + scd.second};
      }
    }

    int i = 0;
    ll sum = 0;
    for (int j = LOGNK-1; j >= 0; j--) {
      auto [t, s] = dbl[j][i];
      if (t == -1 or sum + s > k*n)
        continue;
      i = t;
      sum += s;
    }
    put_ans(i, sum);

  }

  return 0;
}

