    }
    cnt.emplace_back(cnti);
  }
  ll tot = 0,l = cnt.size();
  while(tot+n < nk){
    ll idx = tot%n;
    ll beg = 0,end = l-1;
    while(beg+1 < end){
      ll mid = (beg+end)/2;
      if(tot+cnt[mid][idx] < nk) beg = mid;
      else end = mid-1;
    }
    if(tot+cnt[end][idx] < nk) tot += cnt[end][idx];
    else tot += cnt[beg][idx];
  }
  vector<int> ans;
  ll idx = tot%n;
  while(idx < n){
    if(idx+cnt[1][idx] == n) break;
    if(idx+cnt[1][idx] < n) idx += cnt[1][idx];
    else{
      ans.push_back(a[idx]);
      ++idx;
    }
  }
  for(int i : ans) cout << i << ' ';
  return 0;
}

