    for (int i = n; i > 0; --i) {
        if (lst.count(a[i]) ) nxt[i][0] = lst[ a[i] ];
        else nxt[i][0] = -1;
        lst[ a[i] ] = i;
    }

    for (int i = 1; i <= n; ++i) {
        if (nxt[i][0] == -1) nxt[i][0] = lst[ a[i] ];
        if (nxt[i][0] <= i || nxt[i][0] == n) cost[i][0] = 1;
        nxt[i][0] = nxt[i][0] % n + 1;
    }

    for (int j = 1; j < LOG; ++j) {
        for (int i = 1; i <= n; ++i) {
            nxt[i][j] = nxt[ nxt[i][j - 1] ][j - 1];
            cost[i][j] = cost[i][j - 1] + cost[ nxt[i][j - 1] ][j - 1];
        }
    }

    int cur = 1;
    for (int i = LOG - 1; i >= 0; --i) if (cost[cur][i] <= K) {
        K -= cost[cur][i];
        cur = nxt[cur][i];
