const ll N_MAX = 2*1e5;
const ll K_MAX = 1e12;
const ll A_I_MAX = 2*1e5;

ll N, K;
vector<ll> A;

void solve() {
	scanf("%lld%lld", &N, &K);
	A.assign(N, 0);
	rep(i, N) scanf("%lld", &A[i]);

	vector<ll> AA(2*N,0);
	rep(i,2)rep(j,N)AA[N*i+j]=A[j];

	vector<vector<ll>> index(200001);
	rep(i,2*N){
		index[AA[i]].push_back(i);
	}

	debug((log2(K)+log2(N))+1);
	vector<vector<bll>> doubling((log2(K)+log2(N))+1,vector<bll>(N,0));
	rep(i,N){
		ll t=lower_bound(all(index[A[i]]),i)-index[A[i]].begin();
		doubling[0][i]=1+index[A[i]][t+1]-index[A[i]][t];
	}
	repeq(k,doubling.size()-1){
		rep(i,N){
			doubling[k][i]=doubling[k-1][i]+doubling[k-1][(ll)(i+doubling[k-1][i])%N];
		}
	}

	bll nokori=N*K;
	ll i=0;
	while(nokori>0){
		ll k=doubling.size()-1;
		while(k>=0 && nokori-doubling[k][i]<0){debug(nokori-doubling[k][i]);k--;}
		if(k<0){break;}
		nokori-=doubling[k][i];
		i=((ll)(i+doubling[k][i]))%N;
	}

	vector<ll> stacked(200001, -1);
	vector<ll> v;
	while(i<N){
		if(stacked[A[i]]==-1){
			v.push_back(A[i]);
			stacked[A[i]]=i;
		}else{
			while(v[v.size()-1]!=A[i]){
				stacked[v[v.size()-1]]=-1;
				v.pop_back();
			}
			v.pop_back();
			stacked[A[i]]=-1;
		}
		i++;	
	}

	pv(v);
}

