using i64 = long long;

int main() {
    i64 n, k;
    std::cin >> n >> k;
    std::vector<int> a(n), nxt(n, -1), prev(200010, -1), fst(200010, -1);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
        if (prev[a[i]] < 0) {
            fst[a[i]] = i;
            prev[a[i]] = i;
        } else {
            nxt[prev[a[i]]] = i;
            prev[a[i]] = i;
        }
    }
    for (int i = 0; i < n; i++) if (nxt[i] < 0) nxt[i] = fst[a[i]];
    std::deque<std::pair<int, int>> q { { 0, -1 } };
    auto c = std::make_pair(0, 0);
    while (true) {
        auto x = nxt[c.second];
        if (x <= c.second) ++c.first;
        c.second = x;
        q.push_back(c);
        if (c.second == n - 1) break;
        c.second++;
    }

    auto t = q.back().first + 1;
    auto r = k % t;

    std::deque<int> ret;
    std::set<int> ss;
    if (r > 0) {
        auto it = q.begin();
        while (it->first < r) it++;
        --it;
        for (int i = it->second + 1; i < n; i++) {
            if (!ss.count(a[i])) {
                ret.push_back(a[i]);
                ss.insert(a[i]);
            } else {
                while (true) {
                    int v = ret.back();
                    ret.pop_back();
                    ss.erase(v);
                    if (v == a[i]) break;
                }
            }
        }
    }

    for (auto e : ret) std::cout << e << " ";
    std::cout << std::endl;

    return 0;
}

