const int N = 5001000; 

int n;
int nxt[N], fir[N], pos[N], a[N], ans[N], cnt, len[N];
ll k;  

int main() {
  scanf("%d %lld", &n, &k); k *= n; 
  for(int i = 1; i <= n; i++) {
    scanf("%d", &a[i]); 
    if(!fir[a[i]]) {
      fir[a[i]] = i;
      pos[a[i]] = i;  
    }
    else {
      nxt[pos[a[i]]] = i; 
      pos[a[i]] = i;  
    }
    nxt[i] = fir[a[i]]; 
  }
  for(int i = 1; i <= n; i++) {
    if(nxt[i] > i) {
      len[i] = nxt[i] - i + 1; 
    }
    else len[i] = n - (i - nxt[i] - 1); 
  }
  int u = 1; ll num = 0; 
  while(1) {
    num += len[u]; 
    u = nxt[u] + 1;
    if(u > n) u -= n;  
    if(u == 1) break ; 
  }
  k = k % num; 
  if(!k) return 0; 
  u = 1; num = 0; 
  // k *= n; 
  while(1) {
    num += len[u];
    if(num >= k) {
      num -= len[u]; 
      for(int j = u; j <= u + k - num - 1; j++) {
        int t = j; if(t > n) t -= n; 
        ans[++cnt] = a[t]; 
      } 
      for(int i = 1; i <= cnt; i++) 
        pos[ans[i]] = fir[ans[i]] = nxt[i] = 0; 
      for(int i = 1; i <= cnt; i++) {
        if(!fir[ans[i]]) {
          fir[ans[i]] = i;
          pos[ans[i]] = i;  
        }
        else {
          nxt[pos[ans[i]]] = i;   
          pos[ans[i]] = i;  
        }
        nxt[i] = fir[ans[i]]; 
      }
      int p = 1; 
      while(p <= cnt) {
        if(nxt[p] > p) {
          p = nxt[p] + 1; 
        }
        else {
          printf("%d ", ans[p]); 
          p++; 
        }
      }
      return 0; 
    }
    u = nxt[u] + 1; 
    if(u > n) u -= n; 
  }
  return 0; 
}

