const lint mod = 1e9 + 7;
const int MAX = 200010;

int main(){
    int n;
    lint K;
    scanf("%d%lld", &n, &K);
    int a[n];
    rep(i, n) scanf("%d", &a[i]);

    pil G[n];
    int Next[MAX];
    rep(i, MAX) Next[i] = n;
    rrep(i, n) Next[a[i]] = n + i;
    rrep(i, n){
        lint dist = 1LL * (Next[a[i]] - i + 1);
        int to = (Next[a[i]] + 1) % n;
        Next[a[i]] = i;
        G[i] = pil(to, dist);
    }

    lint td = 0;
    int v = 0;
    while(true){
        if(v == 0 && td != 0) break;
        td += G[v].se;
        v = G[v].fi;
    }

    K = K * n % td;
    while(G[v].se < K){
        K -= G[v].se;
        v = G[v].fi;
    }

    deque<int> dq;
    bool used[MAX];
    rep(i, MAX) used[i] = false;
    while(K--){
        if(!used[a[v]]){
            used[a[v]] = true;
            dq.push_back(a[v]);
        }
        else{
            while(*dq.rbegin() != a[v]){
                used[*dq.rbegin()] = false;
                dq.pop_back();
            }
            dq.pop_back();
            used[a[v]] = false;
        }
        v = (v+1) % n;
    }

    while(!dq.empty()){
        printf("%d ", dq[0]);
        dq.pop_front();
    }
}

