    dforsn(i,0,n) {
        if (last[a[i]]) beg[i] = beg[last[a[i]]+1];
        else beg[i] = a[i];

        last[a[i]] = i;
    }

    forn(i,n) if (!follow[a[i]]) follow[a[i]] = i+1;
    forn(i,n) jump[a[i]] = beg[follow[a[i]]];

    int start = EMPTY;
    auto e = k-1;
    while (e > 0) {
        if (e&1) start = jump[start];
        forn(i,n) njump[a[i]] = jump[jump[a[i]]];
        forn(i,n) jump[a[i]] = njump[a[i]];
        e /= 2;
