int N;
ll K;
const int MA = (int)2e5 + 1;
int kth[MA], A[MA], from, to, loopID;
vi pos[MA];
vi ans;

pii f(int id, int k) {
    auto it = lower_bound(all(pos[A[id]]), id + 1);
    if (it == pos[A[id]].end()) {
        id = pos[A[id]][0] + 1;
        k++;
    } else {
        id = *it + 1;
    }
    if (id == N) {
        id = 0;
        k++;
    }
    return { id,k };
}

void jump(int id, int k) {
    if (kth[id] != -1) {
        from = kth[id];
        to = k;
        loopID = id;
        return;
    }
    kth[id] = k;

    int next_id, next_k;
    tie(next_id, next_k) = f(id, k);
    jump(next_id, next_k);
}

void g(int id, int k, int length) {
    if (k >= length)return;

    int next_id, next_k;
    tie(next_id, next_k) = f(id, k);
    if (next_k >= length && (next_id != 0 || next_k != length)) {
        ans.push_back(A[id]);
        if (++id == N) {
            id = 0;
            k++;
        }
        g(id, k, length);
    } else {
        g(next_id, next_k, length);
    }
}

void solve() {
    MEM(kth, -1);

    cin >> N >> K;
    rep(i, N) {
        cin >> A[i];
        pos[A[i]].push_back(i);
    }

    jump(0, 0);
    assert(loopID == 0);

    g(0, 0, (int)(K%to));
    rep(i, sz(ans)) {
        cout << ans[i] << (i == sz(ans) - 1 ? '\n' : ' ');
    }
}

