    Doubling doubling(n, 1e14);

    {
        int now = 0;
        int start = 0;
        do {
            int now_i = v[now];
            auto it = upper_bound(index[now_i].begin(), index[now_i].end(), now);
            int next = (*it) + 1;
            if (next >= n) {
//                printf("%d %d\n", start, next % n);
                doubling.set_next(start, next % n);
                start = next % n;
            }
            now = next % n;
        } while (now != 0);
    }

    doubling.build();

