class C
{
  int N;
  long long K;
  std::vector<int> A;
public:
  void input();
  void solve();
};

void C::input(){
  std::cin>>N>>K;
  A.resize(N);
  for(int i=0;i<N;i++){
    std::cin>>A[i];
  }
}

void C::solve(){
  C::input();

  for(int i=0;i<N;i++) A.push_back(A[i]);
  std::map<int,int> mp;
  // next[i][j]:jからスタートし、Kを2^i回行った後に空でなくなるときのindex
  int next[41][N];
  for(int i=2*N-1;i>=N;i--){
    mp[A[i]]=i;
  }
  for(int i=N-1;i>=0;i--){
    int x=mp[A[i]]+1;
    if(x>=N){
      next[0][i]=(x-N)%N;
    }else{
      next[0][i]=next[0][x];
    }
    mp[A[i]]=i;
  }

  for(int i=1;i<=40;i++){
    for(int j=0;j<N;j++){
      next[i][j]=next[i-1][next[i-1][j]];
    }
  }

  int cur=0;
  K--;
  for(int i=40;i>=0;i--){
    if((1LL<<i)<=K){
      K-=(1LL<<i);
      cur=next[i][cur];
    }
  }


  std::vector<int> ans;
  mp.clear();
  for(int i=cur;i<N;i++){
    if(mp.count(A[i])){
      while(ans.back()!=A[i]){
        mp.erase(ans.back());
        ans.pop_back();
      }
      mp.erase(A[i]);
      ans.pop_back();
    }else{
      ans.push_back(A[i]);
      mp[A[i]]=1;
    }
  }
  for(int a:ans) std::cout<<a<<" ";
  std::cout<<"\n";
  return;
}

int main(){
  C c;
  c.solve();
  return 0;
}

