    FOR(i, y[z], N) {
        if(tmp2[X[i]] != -1 && tmp2[X[i]] < aidx) {
            aidx = tmp2[X[i]];
            tmp2[X[i]] = -1;
        } else {
            tmp2[X[i]] = aidx;
            ans[aidx] = X[i];
            aidx++;
        }
    }
    REP(i, aidx) cout << ans[i] << (i!=aidx-1 ? " " : "");
    cout << endl;
}

