        D[to] = dist;
        t = to;
    }
    int st = 0;
    for (int i = 1; i <= n; i++)
        if (D[i] == K){
            st = i;
            break;
        }
    if (st == 0){
        go ();
    }
    for (int i = st; i <= n; i++)
        A[++nn] = a[i];
    go ();
    return 0;
}

