ll keta(ll k) {
    ll buf = 1;
    ll count = 1;
    while (k > buf) {
        buf *= 2;
        count++;
    }
    return count;
}

int main () {
    ll n = 0, k = 0;
    cin >> n >> k;
    vector<ll> a(n);
    for (int i=0; i<n; i++) {
        cin >> a.at(i);
    }
    ll ketaa = keta(n*k);
    vector<vector<ll>> to(n, vector<ll>(ketaa));
    for (int i=0; i<ketaa; i++) {
        for (int j=0; j<n; j++) {
            if (i == 0) {
                int now = j+1;
                while (true) {
                    if (a.at(j) == a.at(now%n)) {
                        to.at(j).at(i) = now - j + 1;
                        break;
                    }
                    else now++;
                }
            }
            else {
                to.at(j).at(i) = to.at(j).at(i-1) + to.at((to.at(j).at(i-1)+j)%n).at(i-1);
            }
        }
    }
    ll start = 0;
    bool flag = true;
    while (flag) {
        flag = false;
        for (int i=ketaa-1; i>=0; i--) {
            if (start+to.at(start%n).at(i) > n*k-1) continue;
            else {
                start += to.at(start%n).at(i);
                flag = true;
                break;
            }
        }
