            ll pre = check.at(a.at(i%n));
            for (ll j=start+pre; j<start+buf.size(); j++) {
                check.at(a.at(j%n)) = -1;
            }
            buf.resize(pre-start);
        }
        else {
            buf.push_back(a.at(i%n));
            check.at(a.at(i%n)) = start+buf.size()-1;
        }
    }
    for (int i=0; i<buf.size(); i++) {
        cout << buf.at(i);
        if (i != buf.size()-1) cout << " ";
    }
    cout << endl;
    return 0;
}

