void answer(vector<ll>x){
    vector<ll>cnt(200001);
    vector<ll>ans;
    each(i,x){
        if(cnt[i]){
            while(ans.back()!=i){
                cnt[ans.back()]=0;
                ans.pop_back();
            }
            cnt[i]=0;
            ans.pop_back();
        }
        else{
            cnt[i]=1;
            ans.push_back(i);
        }
    }
    out(ans);
    exit(0);
}
