int main() {
  int64_t n, k, start = 0;
  cin >> n >> k;
  int a[2 * n], next[n];
  for (int i = 0; cin >> a[i]; ++i) {
    a[i + n] = a[i];
  }
  map<int, int> index;
  for (int i = 2 * n - 1; i >= n; --i) {
    index[a[i]] = i;
  }
  for (int i = n - 1; i >= 0; --i) {
    auto it = index.find(a[i]);
    next[i] = it->second - i + 1;
    it->second = i;
  }
  do {
    if (start + next[start % n] < n * k) {
      start += next[start % n];
    } else {
      break;
    }
  } while (start % n != 0);
  set<int> set;
  vector<int> result;
  for (auto i = start == 0 ? 0 : n * k / start * start; i < n * k; ) {
    if (i + next[i % n] < n * k) {
      i += next[i % n];
    } else {
      auto it = set.find(a[i % n]);
      if (it == end(set)) {
        set.emplace(a[i % n]);
        result.emplace_back(a[i % n]);
      } else {
        while (result.back() != *it) {
          set.erase(result.back());
          result.pop_back();
        }
        result.pop_back();
        set.erase(it);
      }
      ++i;
    }
  }
  for (auto i : result) {
    cout << i << ' ';
  }
  return 0;
}

