#define REP(i, n) for(int i = 0; i < (int)(n); ++i)

using namespace std;
typedef long long ll;

int n;
int vs[200000+10];
int nextPos[200000+10];
int lastOccur[200000+10];

int memo[200000+10];
int solve(int pos) { // そこからの時の、実際の始まりの位置を返す
  int& res = memo[pos];
  if(res < 0) {
    if(pos == n) {
      res = n;
    } else {
      if(nextPos[pos] < 0) {
        res = pos;
      } else {
        res = solve(nextPos[pos]+1);
      }
    }
  }
  return res;
}

int main(void) {
  ll k;
  scanf("%d%lld", &n, &k);
  REP(i, n) {
    scanf("%d", &vs[i]);
  }
  memset(nextPos, -1, sizeof nextPos);
  memset(lastOccur, -1, sizeof lastOccur);
  for(int i = n-1; i >= 0; --i) {
    int v = vs[i];
    nextPos[i] = lastOccur[v];
    lastOccur[v] = i;
  }
  memset(memo, -1, sizeof memo);

  vector<int> period(1, n);
  for(int start = 0; ; ) {
    // cerr << ">" << start << endl;
    int tmp = solve(start);
    if(tmp == n) {
      break;
    }
    period.push_back(tmp);
    start = lastOccur[vs[tmp]]+1;
  }
  // REP(i, period.size()) {
  //   cerr << period[i] << ",";
  // }
  // cerr << endl;

  int idx = period[k % period.size()];
  vector<int> res;
  for(;;) {
    int tmp = solve(idx);
    if(tmp == n) {
      break;
    }
    res.push_back(vs[tmp]);
    idx = tmp+1;
  }

  REP(i, res.size()) {
    printf("%d%s", res[i], i == (int)res.size()-1 ? "" : " ");
  }
  puts("");

  return 0;
}

