int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);
	int N; long long K;
	cin >> N >> K;
	vector<int> A(N);
	for (int i = 0; i < N; ++i) cin >> A[i];
	vector<int> nxt(N);
	map<int, int> d;
	for (int i = 2 * N - 1; i >= 0; --i) {
		if (i < N) nxt[i] = d[A[i]] - i;
		d[A[i % N]] = i;
	}
	vector<long long> used(N, -1);
	long long pos = 0;
	bool flag = false;
	while (used[pos % N] == -1) {
		used[pos % N] = pos;
		pos += nxt[pos % N] + 1;
		if (pos > N * K) {
			pos -= nxt[pos % N] + 1;
			flag = true;
			break;
		}
	}
	if (!flag) {
		pos = pos + (1LL * N * K - 1 - pos) / (pos - used[pos % N]) * (pos - used[pos % N]);
		while (true) {
			pos += nxt[pos % N] + 1;
			if (pos > N * K) {
				pos -= nxt[pos % N] + 1;
				flag = true;
				break;
			}
		}
	}
	if (pos == N * K) {
		cout << endl;
	}
	else {
		vector<int> arr;
		map<int, int> parity;
		for (long long i = pos; i < N * K; ++i) {
			if (parity[A[i % N]] == 0) {
				parity[A[i % N]] = 1;
				arr.push_back(A[i % N]);
			}
			else {
				parity[A[i % N]] = 0;
				while (arr.back() != A[i % N]) parity[arr.back()] = 0, arr.pop_back();
				arr.pop_back();
			}
		}
		for (int i = 0; i < arr.size(); ++i) {
			if (i) cout << ' ';
			cout << arr[i];
		}
		cout << endl;
	}
	return 0;
}

