const int MAXV = 200000;

// 1 3 1 2 3 2 3

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    ll K;
    cin >> n >> K;
    vector<int> a(n);
    vector<int> conv(n, -1);
    vector<int> prv(MAXV + 1, -1);
    vector<int> fst(MAXV + 1, -1);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        if (prv[a[i]] == -1) {
            prv[a[i]] = i;
            fst[a[i]] = i;
        } else {
            conv[prv[a[i]]] = i + 1 - prv[a[i]];
            prv[a[i]] = i;
        }
    }

    if (n == 1) {
        if (K % 2 == 1) cout << a[0] << "\n";
        return 0;
    }

    for (int i = 1; i <= MAXV; i++) {
        if (fst[i] == -1) continue;
        conv[prv[i]] = fst[i] + n + 1 - prv[i];
    }

    ll cur = 0;
    ll cycle = 0;
    while (true) {
        ll nex = cur + conv[cur % n];
        if (nex > n * K) break;
        cur = nex;
        if (cur % n == 0) {
            cycle = cur / n;
            break;
        }
    }

    if (cycle > 0) K %= cycle;

    cur = 0;
    while (true) {
        ll nex = cur + conv[cur % n];
        if (nex > n * K) {
            cur %= n;
            break;
        }
        if (nex == n * K) {
            cur = n;
            break;
        }
        cur = nex;
    }

    vector<int> ans;
    vector<int> cnt(MAXV + 1, 0);
    for (int i = cur; i < n; i++) {
        if (cnt[a[i]]) {
            while (cnt[a[i]]) {
                cnt[ans.back()]--;
                ans.pop_back();
            }
        } else {
            ans.push_back(a[i]);
            cnt[a[i]]++;
        }
    }

    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i] << " \n"[i + 1 == ans.size()];
    }
    return 0;
}

