		cin >> a[i];
	}

	{
		vector<int> last(N, -1);
		for (int i = n-1; i >= 0; i--) {
			int x = a[i];
			if (last[x] != -1) {
				nxt[0][i] = (last[x]+1)%n;
				cnt[0][i] = last[x]+1 - i;
			}
			last[x] = i;
		}
		for (int i = 0; i < n; i++) {
			int x = a[i];
			if (nxt[0][i] == -1) {
				nxt[0][i] = (last[x]+1)%n;
				cnt[0][i] = n-i + last[x]+1;
			}
		}
	}
	for (int z = 1; z < Z; z++) {
		for (int i = 0; i < n; i++) {
			int j = nxt[z-1][i];
			nxt[z][i] = nxt[z-1][j];
			if (cnt[z-1][i] <= inf - cnt[z-1][j]) {
				cnt[z][i] = cnt[z-1][i] + cnt[z-1][j];
			} else {
				cnt[z][i] = inf;
			}
		}
