			b[0].p[i]-=n;
			b[0].c[i]++;
		}
		las[a[i]]=i;
	}
	rep(i,1,60)b[i]=mul(b[i-1],b[i-1]);
	x=1,now=1;
	per(i,60,0)
		if(now+b[i].c[x]<=K){
			now+=b[i].c[x];
			x=b[i].p[x];
		}
	doit(x);
	return 0;
}

