void sim(vector<int> &A, int cur = 0) {
    vector<int> used(MAX_N, 0);
    deque<int> ans;
    rep(i, cur, A.size()) {
        if(used[A[i]] == 0) {
            ans.push_back(A[i]);
            used[A[i]] = 1;
        }
        else {
            while(1) {
                int top = ans.back();
                ans.pop_back();
                used[top] = 0;
                if(top == A[i]) {
                    break;
                }
            }
        }
    }
    vector<int> b;
    while(!ans.empty()) {
        int top = ans.front();
        ans.pop_front();
        b.pb(top);
    }
    voutput(b);
}

