using namespace std;

const int MX = 200000;

int a[MX], fst[MX + 1], lst[MX + 1], seen[MX + 1];

int main() {
	int n;
	long long k;
	ignore = scanf("%d %lld", &n, &k);
	for (int i = 0; i < n; i++) ignore = scanf("%d", a + i);

	fill(lst, lst + n + 1, -1);

	fst[n] = -1;
	for (int i = n - 1; i >= 0; i--) {
		int x = a[i];
		if (lst[x] == -1) fst[i] = x;
		else fst[i] = fst[lst[x] + 1];
		lst[x] = i;
	}

	fill(seen, seen + n + 1, -1);

	seen[n] = 0;
	seen[0] = 1;

	vector<int> f = {n, 0};
	for (int i = 2; i <= k; i++) {
		int p = f.back();
		if (fst[p] == -1) {
			f.push_back(0);
		}
		else {
			f.push_back(lst[fst[p]] + 1);
		}

		p = f.back();
		if (seen[p] != -1) {
			int s = seen[p];
			k = (k - s) % (i - s) + s;
		}
		else seen[p] = i;
	}

	vector<int> ans;
	set<int> S;
	for (int x = f[k]; x < n; x++) {
		if (S.insert(a[x]).second) {
			ans.push_back(a[x]);
		}
		else {
			while (S.count(a[x]) == 1) {
				S.erase(ans.back());
				ans.pop_back();
			}
		}
	}

	for (int x : ans) printf("%d ", x);
	printf("\n");

	return 0;
}

