typedef long long ll;
const int N=2e5+5;
int tot,n,a[N<<1],b[N],nex[N],bk[N],pre[N];
ll k,A,B;
bool vis[N];
ll getdis(int s,int t)
{
    if(s==0) s=n;
    ll ans=0;
    while(s!=t)
    {
        ans+=nex[s];
        s=(s+nex[s])%n;
        if(s==0) s=n;
    }
    return ans;
}
void getAns(int now)
{
    for(int i=now;i<=n;i++)
    {
        int x=a[i];
        if(pre[x])
        {
            while(b[tot]!=x) pre[b[tot]]--,tot--;
            pre[x]--;tot--;
        }
        else b[++tot]=x,pre[x]++;
    }
}
int main()
{
    scanf("%d%lld",&n,&k);
    for(int i=1;i<=n;i++)
        scanf("%d",&a[i]),a[i+n]=a[i];
    for(int i=n<<1;i>=1;i--)
    {
        if(i<=n)
            nex[i]=bk[a[i]]-i+1;
        bk[a[i]]=i;
    }
    int now=1;
    while(!vis[now])
    {
        vis[now]=true;
        now=(now+nex[now])%n;
        if(now==0) now=n;
    }
    A=getdis(1,now);
    B=getdis(now+nex[now],now)+nex[now];
    k*=n;
    k--;
    if(k<=A)
    {
        int now=1;
        while(k>=nex[now])
        {
            k-=nex[now];
            now=(now+nex[now])%n;
            if(now==0) now=n;
        }
        getAns(now);
    }
    else
    {
        k-=A;
        k%=B;
        while(k>=nex[now])
        {
            k-=nex[now];
            now=(now+nex[now])%n;
            if(now==0) now=n;
        }
        getAns(now);
    }
    for(int i=1;i<=tot;i++)
        printf(i==tot?"%d\n":"%d ",b[i]);
}

