      dp[0][p.second[i]] = p.second[i + 1] - p.second[i] + 1; // 移動距離
    }
  }

  rep(1, dp.size())
  {
    rep_uj(0, N)
    {
      dp[i][j] = dp[i - 1][j] + dp[i - 1][(dp[i - 1][j] + j) % N];
      assert(dp[i][j] < INT64_MAX);
    }
  }

  ull it{ 0 };
  ull it_max = K * N - 1;
  for(ui i = dp.size() - 1;;)
  {
    if (it + dp[i][it % N] <= it_max)
    {
      it += dp[i][it % N];
    }
    if(!i--)
      break;
  }
  assert(it <= it_max);

  Vector ans;
  ans.reserve(N);

  it %= N;
  std::set<ui> dic;
  while(it < N)
  {
    if (dic.count(A[it]))
    {
      while (true)
      {
        ui last = ans.back();
        ans.pop_back();
        dic.erase(last);
        if (last == A[it])
          break;
      }
    }
    else
    {
      ans.push_back(A[it]);
      dic.insert(A[it]);
    }
    ++it;
  }

  std::cout << ans << "\n";

  return;
}

