    V<V<ll>> cnt(Amax+1);
    for(int i = 0; i < N; ++i) cnt[A[i]].push_back(i);
    for(int i = 0; i <= Amax; ++i){

        for(int j = 0; j + 1 < cnt[i].size(); ++j){
            B[cnt[i][j]] = cnt[i][j+1];
        }
        if(cnt[i].size()){
            B[cnt[i].back()] = cnt[i].front();
        }
    }
    Dijkstra<ll> dijk(2*N,LOWINF);
    for(int i = 0; i < N - 1; ++i) dijk.make_edge(N+i,i+1,0);
    dijk.make_edge(N,0,1);   
    for(int i = 0; i < N; ++i) {
        dijk.make_edge(i,N+B[i],i>=B[i]);
    }
    dijk.solve(0);
    ll M = dijk.cost[2*N-1];

    corner(K%M==0,"");

    K %= M;
    ll t = 0;
    for(int i = 0; i < N; ++i) if(dijk.cost[i]==K) t = i;

    V<int> flg(Amax+1,0);
    V<int> ans;

    for(int i = t; i < N; ++i){
        if(flg[A[i]]){
            flg[A[i]] = 0;
            while(ans.size() && ans.back()!=A[i]) ans.pop_back();
            ans.pop_back();
        }
        else{
            ans.push_back(A[i]);
            flg[A[i]] = 1;
        }
    }
    corner(ans.size()==0,"");

    for(auto e:ans) cout << e << " ";
    cout << endl;

    // for(int i = 0; i < N; ++i) cout << dijk.cost[i] << " "; cout << endl;
    // for(int i = 0; i < N; ++i) cout << dijk.cost[N+i] << " "; cout << endl;

    return 0;
}

