signed main(){

    int n, k; cin >> n >> k;
    k = k * n;
    vector<int> a(n);
    for(int i = 0; i < n; i++){
        cin >> a[i];
    }

    vector<vector<int>> g(2000005);
    for(int i = 0; i < n; i++){
        g[a[i]].push_back(i);
    }

    vector<pair<int, int>> info(2000005, {-1, -1});
    for(int i = 0; i < 2000003; i++){
        if(g[i].size() == 0) continue;
        if(g[i].size() == 1){
            int from = g[i][0];
            int to = (from + 1) % n;
            info[from] = {n + 1, to};
        }else{
            for(int j = 0; j < (int)g[i].size(); j++){
                int from = g[i][j];
                int to = (g[i][(j + 1) % g[i].size()] + 1) % n;
                int dist = (to - from + n) % n;
                if(dist == 0) dist = n;
                info[from] = {dist, to};
            }
        }
    }

    //for(int i = 0; i < n; i++) cerr << info[i].first << " " << info[i].second << endl;

    int sum = 0;
    int cur = 0;
    while(1){
        sum += info[cur].first;
        cur = info[cur].second;
        if(cur == 0) break;
    }
    k %= sum;
    cur = 0;
    while(1){
        if(k >= info[cur].first){
            k -= info[cur].first;
            cur = info[cur].second;
        }else break;
    }

    vector<int> ans;
    set<int> st;
    cerr << cur << " " << k << endl;

    for(int i = 0; i < k; i++){

        if(st.empty() or ans.size() == 0 or st.find(a[cur]) == st.end()){
