            while(1){
                if(ans.size() == 0){
                    cout << -1 << endl;
                    return 0;
                }
                int val = ans.back();
                ans.pop_back();
                if(val == a[cur]) break;
            }
            cur++;
            cur %= n;
        }
    }

    if(ans.size() >= 1){

        for(int i = 0; i < ans.size(); i++) cout << ans[i] << " ";
        cout << endl;
    }

    return 0;
}

