const int inf = 1e9;
const ll inf64 = 1e18;

const int LOG = 60;
const int N = 2e5 + 5;

ll m;
int n;
int a[N], where[N];
vector<int> poses[N];
int link[LOG][N];
ll cost[LOG][N];
int used[N];

int main() {

#ifdef debug
    freopen("input.txt", "r", stdin);
#endif

    ios_base::sync_with_stdio(0);
    cin.tie(0);

    cin >> n >> m;

    for (int i = 0; i < n; i++) {
        cin >> a[i];
        where[i] = (int) poses[a[i]].size();
        poses[a[i]].push_back(i);
    }

    for (int i = 0; i < n; i++) {
        int j = where[i];
        j = (j + 1) % (int) poses[a[i]].size();
        j = poses[a[i]][j];
        j = (j + 1) % n;
        link[0][i] = j;
        if ((int) poses[a[i]].size() > 1) {
            cost[0][i] = i <= j ? j - i : n - i + j;
        } else {
            cost[0][i] = n + 1;
        }
//        cout << i << " -> " << link[0][i] << " cost = " << cost[0][i] << "\n";
    }

    for (int j = 1; j < LOG; j++) {
        for (int i = 0; i < n; i++) {
            link[j][i] = link[j - 1][link[j - 1][i]];
            cost[j][i] = min(inf64, cost[j - 1][i] + cost[j - 1][link[j - 1][i]]);
        }
    }

//    for (int j = 0; j <= 2; j++) {
//        cout << j << " : ";
//        for (int i = 0; i < n; i++) {
//            cout << link[j][i] << " ";
//        }
//        cout << "\n";
//    }

    int v = 0;
    ll dist = m * n;

    for (int j = LOG - 1; j >= 0; j--) {
        if (cost[j][v] > dist) continue;
        dist -= cost[j][v];
        v = link[j][v];
    }

//    cout << "v = " << v << "\n";

    vector<int> res;

    if (dist == 0) {v = n;}

    for (int i = v; i < n; i++) {
        int x = a[i];
        if (used[x]) {
            while (1) {
                int y = res.back();
                used[y] = 0;
                res.pop_back();
                if (x == y) break;
            }
        } else {
            used[x] = 1;
            res.push_back(x);
        }
    }

    for (int x : res) {
        cout << x << " ";
    }
    cout << "\n";

    return 0;
}

