	TEST(freopen("debug.txt", "w", stderr));
	int N;
	vector<int> ans;
	cin>>N>>K;
	for(int i=0;i<N;i++) {
		cin>>A[i];
		P[--A[i]].push_back(i);
	}
	if(N==1) {
		if(K&1) cout<<A[0]+1<<'\n';
		return 0;
	}
	for(int i=0;i<N;i++) {
		int idx=upper_bound(P[A[i]].begin(),P[A[i]].end(),i)-P[A[i]].begin();
		if(idx==P[A[i]].size()) {
			int n=P[A[i]][0]+1;
			nxt[i]={n%N,1+(n==N)};
		}
		else {
			int n=P[A[i]][idx]+1;
			nxt[i]={n%N,n==N};
		}
	}
	memset(idx,-1,sizeof(idx));
	for(int i=solve(0);i<N;i++) {
		if(idx[A[i]]==-1) {
			idx[A[i]]=ans.size();
			ans.push_back(A[i]);
		}
		else {
			while(ans.size()>idx[A[i]]) ans.pop_back();
			idx[A[i]]=-1;
		}
	}
	for(auto a: ans) cout<<a+1<<' ';
	return 0;
}

