using namespace std;
const long long MOD = (long long)1e9 + 7;

long long n, k, t, a[200009];
int pos_f[200009], pos_l[200009], cnt[200009], nxt[200009], pre[200009];
int from[200009];   //from[i] means the first positon of answer s, if start from i.
bool vis[200009], ck[200009], stl[200009];
stack<int> stk;
vector<int> vec, ans;

int fun(int cur)
{
	if (cur >= n) return cur;
	if (stl[cur]) return from[cur];
	if (nxt[cur] < 0) {
		from[cur] = cur;
	}
	else {
		int retval = fun(nxt[cur] + 1);
		from[cur] = retval;
	}
	stl[cur] = true;
	return from[cur];
}

int main()
{
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cin >> n >> k;
	k--;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		if (!vis[a[i]]) {
			vis[a[i]] = true;
			pos_f[a[i]] = i;
			//t++;
		}
		pos_l[a[i]] = i;
	}
	memset(pre, 0xff, sizeof(pre));
	memset(nxt, 0xff, sizeof(nxt));
	for (int i = 0; i < n; i++) {
		if (pre[a[i]] < 0) {
			pre[a[i]] = i;
		}
		else {
			nxt[pre[a[i]]] = i;
			pre[a[i]] = i;
		}
	}
	for (int i = 0; i < n; i++) {
		fun(i);
	}
	int G = 0, PRE = -1;
	t++;
	for (int i = 1; i < n; i++) {
		int V;
		if (PRE >= 0) {
			V = a[PRE];
			G = pos_f[V] + 1;
		}
		else {
			G = 0;
		}
		if (G >= n) PRE = -1;
		else PRE = from[G];
		if (PRE == n) break;
		t++;
	}
	k = k % t;
	G = 0, PRE = from[0];
	for (int i = 1; i <= k; i++) {
		int V;
		if (PRE >= 0) {
			V = a[PRE];
			G = pos_f[V] + 1;
		}
		else {
			G = 0;
		}
		if (G >= n) PRE = -1;
		else PRE = from[G];
	}
	memset(vis, 0, sizeof(vis));
	for (int i = G; i < n; i++) {
		if (!vis[a[i]]) {
			stk.push(a[i]);
			vis[a[i]] = true;
		}
		else {
			while (1) {
				int tmp = stk.top();
				stk.pop();
				vis[tmp] = false;
				if (a[i] == tmp) {
					break;
				}
			}
		}
	}
	while (!stk.empty()) {
		int tmp = stk.top();
		stk.pop();
		ans.pb(tmp);
	}
	reverse(ans.begin(), ans.end());
	for (int i = 0; i < (int)ans.size(); i++) {
		cout << ans[i] << " ";
	}
	//system("pause");
	return 0;
}

