int main(int argc, char* argv[])
{
    int n;
    ll K;
    scanf("%d%lld", &n, &K);

    vector<int> a(n), b(n+1);
    int i;
    for(i=0; i<n; i++) {
        scanf("%d", &a[i]);
    }

    map<int,int> z;
    for(i=n-1; i>=0; i--) {
        auto ret = z.insert(make_pair(a[i],i));
        if(ret.second) {
            b[i] = a[i];
        }
        else {
            int k = ret.first->second;
            b[i] = b[k+1];
        }
    }

    map<int,int> id;
    for(i=0; i<n; i++) {
        if(id.find(a[i])==id.end()) {
            id[a[i]]=i;
        }
    }

    int base=0;
    map<int,int> save;
    vector<int> aa;    
    int curr=0, next=0;
    for(i=0; i<n+1; i++) {
        auto it = save.find(curr);
        if(it==save.end()) {
            save[curr]=i;        
        }
        else {
            base = it->second;
            break;
        }
        aa.push_back(curr);
        int tmp=b[curr];
        if(tmp==0) next=0;
        else next = id[tmp]+1;
        curr = next;
    }

    int siz=(int)aa.size();

    int K2=0;
    K--;
    if(K<siz) {
        K2 = (int)K;
    }
    else {
        K2 = base + (K-base)%(siz-base);
    }

    // solve
    curr=aa[K2];
    for(i=curr; i<n; i++) {
        if(b[i]==0) break;
        printf("%d ", b[i]);
    }
    printf("\n");

    return 0;
}

