using namespace std;


void solve(long long N, long long K, std::vector<long long> A){
  vector<long long> p(N+1);
  vector<long long> pr(200000, -1);
  p[N] = -1;
  for (int i = N-1; i >= 0; i--) {
    if (pr[A[i]] == -1) {
      p[i] = i;
      pr[A[i]] = i;
    } else {
      p[i] = p[pr[A[i]]+1];
      pr[A[i]] = i;
    }
  }

  long long idx = 0;
  long long t = -1;
  long long o = -1;
  set<long long> s;
  while (true) {
    idx++;
    if (t == -1) {
      o = p[0];
    } else {
      o = p[pr[t]+1];
    }
    if (o == -1) {
      break;
    }
    t = A[o];
  }

  idx = K % idx;
  t = -1;
  o = -1;
  for (int i = 0; i < idx; i++) {
    if (t == -1) {
      o = p[0];
    } else {
      o = p[pr[t]+1];
    }
    if (i < idx-1) {
      t = A[o];
    }
  }

  vector<long long> ans;
  while (true) {
    if (o == -1) {
      break;
    }
    t = A[o];
    ans.push_back(t);
    o = p[o+1];
  }

  assert(false)

  for (int i = 0; i < ans.size(); i++) {
    if (i == 0) {
      std::cout << ans[i];
    } else {
      std::cout << " " << ans[i];
    }
  }
  std::cout << std::endl;
}

int main(){
  long long N;
  scanf("%lld",&N);
  long long K;
  scanf("%lld",&K);
  std::vector<long long> A(N-1-0+1);
  for(int i = 0 ; i < N-1-0+1 ; i++){
    scanf("%lld",&A[i]);
  }
  solve(N, K, std::move(A));
  return 0;
}

