long long toNextElem[200010];	//到上一个同名元素的位置 

int main()
{
	scanf("%lld%lld", &n, &k);

	for (int i = 0 ; i < n ; i++)
		scanf("%lld", &(a[i]));
	memset(elemCount, 0, sizeof(elemCount));

	for (int i = 0 ; i < n ; i++)
		elems[a[i]].push_back(i);

