	{
		if (elems[i].size() == 0)
			continue;

		if (elems[i].size() == 1)
		{
			toPrevElem[elems[i][0]] = elems[i][0];
			toNextElem[elems[i][0]] = elems[i][0];
			continue;
		}


		for (int j = 0 ; j < elems[i].size() - 1 ; j++)
			toPrevElem[elems[i][j + 1]] = elems[i][j];
		toPrevElem[elems[i][0]] = elems[i][elems[i].size() - 1];

		for (int j = 0 ; j < elems[i].size() - 1 ; j++)
			toNextElem[elems[i][j]] = elems[i][j + 1];
		toNextElem[elems[i][elems[i].size() - 1]] = elems[i][0];
	}

	int section = 1;
	int p = n - 1;
	while (true)
	{
		if (p <= toPrevElem[p])
			section++;
		p = toPrevElem[p];
		if (p == 0)
			break;

		p--;
		if (p < 0)
		{
			p = n - 1;
			section++;			
		}
	}

	int left = k % section;
	p = 0;
	while (left > 1)
	{
		if (p >= toNextElem[p])
			left--;
		p = toNextElem[p];
		p++;
	}

	std::stack<long long> ss;
	std::set<long long> numInStack;

	ss.push(a[p]);
	numInStack.insert(a[p]);
	p++;

	while (p < n)
	{
		if (numInStack.find(a[p]) != numInStack.end())
		{
			while (ss.empty() == false)
			{
				int curP = ss.top();
				ss.pop();
				numInStack.erase(curP);

				if (curP == a[p])
					break;
			}
		}
		else
		{
			ss.push(a[p]);
			numInStack.insert(a[p]);
		}
		p++;
	}

	std::vector<long long> ans;

	while (ss.empty() == false)
	{
		ans.push_back(ss.top());
		ss.pop();
	}

	for (int i = ans.size() - 1 ; i >= 0 ; i--)
	{
		printf("%lld ", ans[i]);
	}
	printf("\n");


	return 0;
}

