const int MAX_N = 2 * 1e5 + 2;

bool is_used[MAX_N];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N, K;
    cin >> N >> K;
    vector<int> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    vector<ll> last_pos(MAX_N, -1);
    vector<ll> next_pos(N, -1);
    for (ll i = 2 * N - 1; i >= 0; i--) {
        if (last_pos[A[i % N]] >= 0) {
            next_pos[i % N] = last_pos[A[i % N]];
        }
        last_pos[A[i % N]] = i % N;
    }
    ll now_idx = 0, next_idx = next_pos[now_idx];
    ll period = 0;
    if (now_idx < next_idx) period += next_idx - now_idx + 1;
    else if (now_idx > next_idx) period += N - now_idx + next_idx + 1;
    else period += N + 1;
    while (next_idx != N - 1) {
        now_idx = (next_idx + 1) % N;
        next_idx = next_pos[now_idx];
        if (now_idx < next_idx) period += next_idx - now_idx + 1;
        else if (now_idx > next_idx) period += N - now_idx + next_idx + 1;
        else period += N + 1;
    }
    ll rest = (N * K) % period;
    vector<int> s;
    ll now_p = 0;
    while (rest > 0) {
        ll next_p = next_pos[now_p];
        ll dist;
        if (now_p < next_p) dist = next_p - now_p + 1;
        else if (now_p > next_p) dist = N - now_p + next_p + 1;
        else dist = N + 1;
        if (rest < dist) {
            for (int i = 0; i < rest; i++) {
                if (is_used[A[now_p]]) {
                    while (is_used[A[now_p]]) {
                        is_used[s[s.size() - 1]] = false;
                        s.pop_back();
                    }
                }
                else {
                    s.push_back(A[now_p]);
                    is_used[A[now_p]] = true;
                }
                now_p = (now_p + 1) % N;
            }
        }
        now_p = next_p + 1;
        rest -= min(rest, dist);
    }
    for (int i = 0; i < s.size(); i++) cout << s[i] << ' ';
    cout << endl;
    return 0;
}

