    for(int i=0;i<N;i++){
        cin >> A[i];
        v[A[i]].push_back(i);
    }
    vector<vector<ll>> ne(N,vector<ll>(60,0)),delta(N,vector<ll>(60,0));
    for(int i=1;i<=200000;i++){
        int n = v[i].size();
        for(int j=0;j<n;j++){
            ne[v[i][j]][0] = (v[i][(j+1)%n]+1)%N;
            delta[v[i][j]][0] = v[i][(j+1)%n]+(j+1==n? N:0)-v[i][j]+1;
        }
    }
    for(int j=1;j<60;j++) for(int i=0;i<N;i++){
        ne[i][j] = ne[ne[i][j-1]][j-1];
        if(delta[i][j-1]+delta[ne[i][j-1]][j-1]<N*K+1) delta[i][j] = delta[i][j-1]+delta[ne[i][j-1]][j-1];
        else delta[i][j] = N*K+1;
    }
    ll id = 0;
    ll res = N*K;
    while(true){
        bool update = false;
        for(int j=59;j>=0;j--){
            if(res>delta[id][j]){
                res -= delta[id][j];
                id = ne[id][j];
                update = true;
                break;
            }
        }
        if(!update) break;
    }
    vector<ll> ans;
    set<ll> s;
