int fun(int cur)
{
	if (cur >= n) return cur;
	if (vis[cur]) return from[cur];
	if (nxt[cur] < 0) {
		from[cur] = cur;
	}
	else {
		int retval = fun(nxt[cur] + 1);
		from[cur] = retval;
	}
	vis[cur] = true;
	return from[cur];
}

int main()
{
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
