typedef unsigned long long base; 
typedef pair<int, int> point;      
typedef complex<double> comp;

const int N = 2e5 + 5;
const int LOG = 40;

base n;
base k;
vector<int> a;
base nxt[LOG][N];
int lst[N];

base curt = 0;
vector<int> ans;

int main() {
    ios::sync_with_stdio(0);
    srand(time(0));
    cin >> n >> k;
    a.resize(n);
    cin >> a;
    for (int i = 0; i < n; ++i) {
        a.pb(a[i]);
        lst[i] = -1;
    }
    for (int i = 0; i < n * 2; ++i) {
        if (lst[a[i]] != -1 && lst[a[i]] < n) {
            nxt[0][lst[a[i]]] = i - lst[a[i]];
        }
        lst[a[i]] = i;
    }
    for (int t = 0; t + 1 < LOG; ++t) {
        for (int i = 0; i < n; ++i) {
            int j = (i + nxt[t][i] + 1) % n;
            nxt[t + 1][i] = nxt[t][i] + 1 + nxt[t][j];
            // chkmin(nxt[t + 1][i], n * k + 2);
        }
    }
    curt = 0;
    while (curt < n * k) {
        int i = curt % n;
        for (int t = LOG; t--;) {
            base v = nxt[t][i];
            if (curt + v < n * k) {
                curt += v + 1;
                i = curt % n;
                ++t;
            }
        }
        if (curt < n * k) {
            ans.pb(a[i]);
            ++curt;
        }
    }
    cout << ans << '\n';
}

