using namespace std;

typedef pair<int, int> P;

int n;
ll k;
int a[maxn], idx[maxn];
const int LOG = 62;
ll add[maxn][LOG];

int ans[maxn], top;

int main()
{
    cin >> n >> k;
    for (int i = 0; i < n; i++)
        scanf("%d", &a[i]);

    for (int i = n - 1; i >= 0; i--)
        idx[a[i]] = i;
    for (int i = n - 1; i >= 0; i--)
    {
        if (idx[a[i]] <= i)
            add[0][i] = idx[a[i]] + n - i;
        else
            add[0][i] = idx[a[i]] - i;
        add[0][i]++;
        idx[a[i]] = i;
    }

    for (int i = 1; i < LOG; i++)
        for (int j = 0; j < n; j++)
        {
            add[i][j] = add[i - 1][(add[i - 1][j] + j) % n] + add[i - 1][j];
            if (add[i][j] > LLONG_MAX / 3)
                add[i][j] = LLONG_MAX / 3;
        }

    ll now = 0;
    for (int i = LOG - 1; i >= 0; i--)
    {
        if (now + add[i][now % n] <= k * n)
            now += add[i][now % n];
    }
    //printf("%lld\n", add[LOG - 1][0]);
    //printf("%lld\n", now);
    memset(idx, -1, sizeof(idx));
    top = 0;
    for (ll i = now; i <= k * n - 1; i++)
    {
        ll now = i % n;
        if (idx[a[now]] >= top || idx[a[now]] == -1)
        {
            idx[a[now]] = top;
            ans[top++] = a[now];
        }
        else
            top = idx[a[now]];
    }
    for (int i = 0; i < top; i++)
        printf("%d ", ans[i]);

    return 0;
}

