void solve(int n, int arr[], pair<int, long long> st[][40], long long k)
{
    int pos = 0;
    for (int i = 39; i != -1; --i)
    {
        while (k > st[pos][i].second)
        {
            k -= st[pos][i].second;
            pos = st[pos][i].first;
        }
    }

    vector<bool> kek(200000);
    deque<int> s;

    while (k--)
    {
        for (int i = pos; i != n; ++i)
        {
            if (kek[arr[i]])
            {
                while (s.back() != arr[i])
                {
                    kek[s.back()] = 0;
                    s.pop_back();
                }
                kek[s.back()] = 0;
                s.pop_back();
            }
            else
            {
                kek[arr[i]] = 1;
                s.push_back(arr[i]);
            }
        }
        pos = 0;
    }

    for (int x : s)
        cout << x + 1 << ' ';
    cout << '\n';
}

int main()
{
