vector<int> sim(vector<int>& v) {
    unordered_set<int> have;
    vector<int> cur;
    for(auto x : v) {
        // cout << x << " | " << cur << endl;
        if (have.count(x)) {
            while (true) {
                // if (cur.empty()) {while(1) {}}
                int last = cur.back();
                cur.pop_back();
                have.erase(last);
                if (last == x) {
                    break;
                }
            }
        } else {
            cur.push_back(x);
            have.insert(x);
        }
    }
    return cur;
}

