struct Problem {

	void Solve() {
		UL N; cin >> N;
		ULL K; cin >> K;
		ULL NK = N * K;
		vector<UL> S(N); rep(i, N) { cin >> S[i]; S[i]--; }
		vector<UL> Nx(N);
		{
			vector<UL> P; P.assign(200000, (UL)-1);
			rep(i, N) {
				if (P[S[i]] != (UL)-1) Nx[P[S[i]]] = i + 1;
				P[S[i]] = i;
			}
			rep(i, N) {
				if (P[S[i]] != (UL)-1) if (P[S[i]] < N) Nx[P[S[i]]] = N + i + 1;
				P[S[i]] = i + N;
			}
		}
		ULL p = 0;
		do { p += (Nx[p % N] - p % N); } while (p % N);
		ULL q = NK - NK % p;
		vector<UL> ans;
		while (q < NK) {
			ULL nxq = q + (Nx[q % N] - q % N);
			if(nxq <= NK) q += (Nx[q % N] - q % N);
			else {
				ans.push_back(S[q % N] + 1); q++;
			}
		}
		rep(i, ans.size()) {
			if (i != 0) cout << " ";
			cout << ans[i];
		}cout << endl;
	}

	Problem();
};
