    for(lint i=0; i<n; i++) {
        a3[i+n+n] = a3[i+n] = a3[i] = a[i];
    }

    vector<P> next(n);
    for(lint i=0; i<n; i++) {
        auto it = find(a3.begin()+i+1, a3.end(), a[i]);
