        lint cost = it - (a3.begin()+i);
        lint idx = (it - a3.begin()) % n;
        next[i] = {idx, cost};
    }

    vector<lint> dist(n);
    lint idx = 0;
    do {
        lint nidx = next[idx].first;
        lint cost = next[idx].second;
        dist[nidx] = dist[idx] + cost;
        idx = nidx;
    } while(idx != 0);

    lint rem = (n*k)%dist[0];
