            tmp.insert(a[i]);
            sta.push(a[i]);
        }
        else
        {
          while(true)
            {
                ll cand = sta.top();
                sta.pop();
                tmp.erase(cand);
                if(cand == a[i])
                {
                    break;
                }
            }
        }
    }
    stack<ll> ansq;
    ll size = sta.size();
    for(int i = 0; i < size; i++)
    {
        ll cand = sta.top();
        sta.pop();
        ansq.push(cand);
    }
    ll anss = ansq.size();
    for(int i = 0; i < anss; i++)
    {
        ll cand = ansq.top();
        ansq.pop();
        cout << cand << " ";
    }
}

