void solve(long long N, long long K, std::vector<long long> A){
  vector<ll> cpy_A=A;
  sort(cpy_A.begin(),cpy_A.end());
  cpy_A.erase(unique(cpy_A.begin(),cpy_A.end()),cpy_A.end());
  if(cpy_A.size()==A.size()){
    copy(A.begin()+(K-1),prev(A.end()),ostream_iterator<ll>(cout," "));
    cout<<A.back()<<endl;
    return;
  }
  vector<vector<ll>> idxs(200000);
  REP(N){
    idxs[A[i]].push_back(i);
  }
  ll loop=0;
  ll pprev=N-1;
  vector<ll> loops;
  while(pprev!=-1){
    if(idxs[A[pprev]].size()==1){
      ++loop;
      --pprev;
      loops.push_back(pprev+1);
      continue;
    }
    auto itr=lower_bound(idxs[A[pprev]].begin(),idxs[A[pprev]].end(),pprev);
    if(itr==idxs[A[pprev]].begin()){
      ++loop;
      pprev=idxs[A[pprev]].back()-1;
      loops.push_back(pprev+1);
    }else{
      pprev=*prev(itr)-1;
    }
  }
  loops.push_back(N);
  reverse(loops.begin(),loops.end());
  ++loop;
  dump(loop);
  K=K%loop;
  if(K==0){
    cout<<endl;
    return;
  }else{
    ll l=loops[K];
    vector<ll> ans;
    for(int i=l;i<N;++i){
      auto itr=idxs[A[i]].begin();
      if((itr=upper_bound(idxs[A[i]].begin(),idxs[A[i]].end(),i))!=idxs[A[i]].end()){
        i=*itr;
      }else{
        ans.push_back(A[i]);
      }
    }
    REP(ans.size()){
      cout<<ans[i];
      if(ans.size()-1==i){
        cout<<endl;
      }else{
        cout<<" ";
      }
    }
  }
}

