int main() {
    init();

    int n; ll k; cin >> n >> k;
    VI a(n); cin >> a;

    constexpr int log = 60;
    auto to = vec<int>(log + 1, n);
    auto len = vec<ll>(log + 1, n);
    map<int, VI> m;
    FOR(i, 0, n)m[a[i]].push_back(i);
    each(i, m)FOR(j, 0, i.second.size()) {
        int x = i.second[j];
        int y = i.second[(j + 1) % int(i.second.size())];
        to[0][x] = (y + 1) % n;
        len[0][x] = x < y ? y - x + 1 : y + n - x + 1;
    }
    FOR(i, 0, log)FOR(j, 0, n) {
        to[i + 1][j] = to[i][to[i][j]];
        len[i + 1][j] = min(len[i][j] + len[i][to[i][j]], LLINF);
    }
    int p = 0; ll q = 0;
    rFOR(i, 0, log) {
        if (q + len[i][p] <= n * k) {
            q += len[i][p];
            p = to[i][p];
        }
    }

    map<int, int> used;
    VI ans;
    FOR(i, p, p + n * k - q) {
        int x = a[i % n];
        if (0 < used[x]) {
            while (used[x]) {
                --used[ans.back()];
                ans.pop_back();
            }
        }
        else {
            ++used[x];
            ans.push_back(x);
        }
    }
    print(ans);

    return 0;
}

