int main()
{
    lint N, K;
    cin >> N >> K;
    vector<int> X(N);
    REP(i, N) cin >> X[i];
    vector<int> first(200001, -1);
    REP(i, N) {
        if(first[X[i]] == -1) first[X[i]] = i;
    }
    vector<int> next(N+1, -1);
    vector<int> bef(N+1, -1);
    vector<int> tmp(200001, -1);
    REP(i, N) {
        if(tmp[X[i]] != -1) {
            bef[i+1] = tmp[X[i]];
        }
        tmp[X[i]] = i;
    }
    IREP(i, N) {
        int be = i+1;
        while(true) {
            if(bef[be] != -1 && next[bef[be]] < i+1) {
                next[bef[be]] = i+1;
                be = bef[be];
            } else {
                break;
            }
        }
    }
    REP(i, N) {
        if(next[i] == -1) {
            next[i] = i;
        }
    }

