const ll MOD = 1e9 + 7;

struct Queue {
    Queue() {}
    Queue(int N) : s(vector<int>(N)), last(0) {}
    vector<int> s;
    int last;
};

void simulate(int N, vector<int>& A, Queue& queue) {
    unordered_map<int, int> positions; // <number, position>
    unordered_map<int, int> numbers; // <position, number>
    REP(i,0,queue.last) {
        positions[queue.s[i]] = i;
        numbers[i] = queue.s[i];
    }
    for (const int a : A) {
//        cout << "a:" << a << '\n';
        if (positions.find(a) != positions.end() && numbers[positions[a]] == a && positions[a] < queue.last) {
            queue.last = positions[a];
        } else {
            queue.s[queue.last] = a;
            positions[a] = queue.last;
            numbers[queue.last] = a;
            queue.last++;
        }
//        REP(i,0,queue.last) {
//            cout << queue.s[i] << " ";
//        }
//        cout << "\n";
    }
}

void solve(int N, int K, vector<int>& A) {
    Queue queue(N);

	int cycle = 0;
	int count = 0;
	unordered_map<int, int> tails;
	while (count < K) {
	    simulate(N, A, queue);
	    count++;
	    if (queue.last == 0) {
	        cycle = count;
	        break;
	    }

	    if (count + queue.last - 1 <= K) {
            count += queue.last-1;
            queue.s[0] = queue.s[queue.last-1];
            queue.last = 1;
            if (tails.find(queue.s[0]) != tails.end()) {
                cycle = count - tails[queue.s[0]];
                K -= count;
                break;
            }
            tails[queue.s[0]] = count;
	    }
	}
	if (cycle != 0) K %= cycle;
    count = 0;
    while (count < K) {
        simulate(N, A, queue);
        count++;
        if (queue.last == 0) break;
    }

    stringstream ss;
    REP(i,0,queue.last-1) {
        ss << queue.s[i] << " ";
    }
    if (queue.last != 0) ss << queue.s[queue.last-1];
	cout << ss.str() << '\n';
    return;
}

