vector<int> go(int N, ll left, const vector<ll> &A, int start) {
    map<ll, int> s;
    vector<int> stk;
    stk.reserve(N);
    for(ll i = start; left > 0; i++, left--) {
        ll a = A[i % N];
        if(s[a] > 0) {
            int sa = s[a];
            while(stk.size() >= sa) {
                s[stk.back()] = 0;
                stk.pop_back();
            }
        } else {
            stk.push_back(a);
            s[a] = stk.size();
        }
        // cerr << i << ": " << stk << endl;
    }
    return stk;
}

int main() {
    int N; ll K; cin >> N >> K;
    vector<ll> A(N); cin >> A;

    vector<int> next_index(N);
    map<ll, int> last;
    for(int i = N * 2 - 1; i >= 0; i--) {
        if(i < N) next_index[i] = last[A[i]];
        last[A[i%N]] = i % N;
    }
    //debug(next_index);
    ll left = K * N;
    vector<int> visited(N, -1);
    vector<ll> log;
    log.reserve(N);
    int now = 0;
    while(left > N) {
        if(visited[now] >= 0) {
            // cerr << "LOOP at " << now << endl;
            ll sum = 0;
            repeat(i, visited[now], log.size()) sum += log[i];
            // cerr << "sum = " << sum << " left = " << left << endl;
            left = left % sum;
        }
        int next = next_index[now];
        ll diff = (next <= now ? next + N - now : next - now) + 1;
        if(diff > left) break;
        left -= diff;
        // cerr << now << " -> " << (next + 1) % N << " (+" << diff << "), left " << left << endl;
        visited[now] = log.size();
        now = (next + 1) % N;
        log.push_back(diff);
    }
    // debug(left);
    // debug(now);
    // debug((left + now) % N);
    //assert((left + now) % N == 0);
    // cerr << "go (left = " << left << " at " << now << endl;
    auto ans =  go(N, left, A, now);
    rep(i, ans.size()) cout << ans[i] << (i == ans.size() - 1 ? "\n" : " ");
    return 0;
}

