class Doubling {
public:
  int N;
  int logK;
  vector<vector<int>> next;

  Doubling(int N, vector<int>& ini, ll K) {
    logK = log2(K);
    next = vector<vector<int>>(logK+1, vector<int>(N));
    rep(i, N) next[0][i] = ini[i];
    rep(k, logK) {
      rep(i, N) {
        next[k+1][i] = (next[k][i] == -1 ? -1 : next[k][next[k][i]]);
      }
    }
  }

  int query(int p, ll q) {
    for(int k=logK; k>=0; k--) {
      if(p == -1) break;
      if((q>>k)&1) p = next[k][p];
    }
    return p;
  }
};
int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int n; ll k; cin >> n >> k;
  vector<ll> A(n); rep(i, n) cin >> A[i];
  rep(i, n) A.push_back(A[i]);
  vector<int> next(n), cnt(n);
  map<ll, vector<int>> pos;
  rep(i, 2*n) pos[A[i]].push_back(i);
  for(auto ele: pos) {
    int prev = -1;
    for(int p: ele.second) {
      if(prev >= n) break;
      if(prev != -1) {
        next[prev%n] = (p+1)%n;
        cnt[prev%n] = (p+1)>=n;
      }
      prev = p;
    }
  }
  rrep(i, n) {
    int ne = i;
    while(cnt[ne] == 0) {
      ne = next[ne];
    }
    next[i] = next[ne];
    cnt[i] = 1;
  }
  Doubling dbl(n, next, k);
  int p = dbl.query(0, k-1);
  deque<ll> q;
  set<ll> se;
  for(int i=p; i<n; i++) {
    if(se.count(A[i])) {
      while(q.back() != A[i]) {
        se.erase(q.back());
        q.pop_back();
      }
      se.erase(q.back());
      q.pop_back();
    } else {
      q.push_back(A[i]);
      se.insert(A[i]);
    }
  }
  while(!q.empty()) {
    cout << q.front() << ' ';
    q.pop_front();
  }
  cout << "\n";
  return 0;
}

