using namespace std;
typedef long long ll;
int n;
ll K;
#define Maxn 400010
ll a[Maxn],last[Maxn];
bool ap[Maxn];
ll to[Maxn],d[Maxn];
ll all[Maxn],cnt=0;
ll num[Maxn];
ll Ans[Maxn],len;
inline void solve(int ans){
	memset(ap,false,sizeof(ap));
	for(register int i=ans;i<=n;++i){
		if(!ap[a[i]])Ans[++len]=a[i],ap[a[i]]=true;
		else{
			while(ap[a[i]]){
				ap[Ans[len]]=false;
				len--;
			}
		}
	}
	for(register int i=1;i<=len;++i)printf("%d ",Ans[i]);
}
int main(){
	scanf("%d%lld",&n,&K);
	K=K*n;
	for(register int i=1;i<=n;++i){
		scanf("%lld",&a[i]);
		a[i+n]=a[i];
	}
	for(register int i=2*n;i>=1;--i){
		if(i<=n){
			if(last[a[i]]>n){
				to[i]=last[a[i]]-n+1;
				if(to[i]>n)to[i]=1;
			}else{
			    to[i]=last[a[i]]+1;
			    if(to[i]>n)to[i]=1;
			}
			d[i]=last[a[i]]-i+1;
		}
		last[a[i]]=i;
	}
	int node=1;
	while(!ap[node]){
		ap[node]=true;
		node=to[node];
	}
	int ans=0;
	ll sum=0;
	int at=1;
	while(at!=node){
		if(sum+d[at]>K){
			ans=at;
			break;
		}	
		sum+=d[at];
		at=to[at];
	}
	if(ans){
		if(sum<K)solve(ans);
		return 0;
	}
	num[0]=node;
	do{
		cnt++;
		all[cnt]=all[cnt-1]+d[at];
		at=to[at];
		num[cnt]=at;
	}while(at!=node);
	ll re=K-(K-sum)/all[cnt]*all[cnt]-sum;
	int l=0,r=cnt;
	while(l<r){
		int mid=(l+r)>>1;
		if(all[mid+1]<=re)l=mid+1;
		else r=mid;
	}
	ans=num[l];
	if(all[l]<re)solve(ans);
	return 0;
}

