using namespace std;

int n;
long long iter;
int s[200005], jump[200005];
int occ[200005];

int loop[200005];

void simulate_till_end(int cur_pos, int cur_iter){
	int stk[200005], p = 0;
	int appear[200005];

	memset(appear, 0, sizeof(appear));

	while(cur_iter <= iter){
		while(cur_pos <= n){
			int elem = s[cur_pos];
			if(appear[elem]){
				int til = appear[elem];
				while(p >= til){
					appear[stk[p]] = 0;
					p--;
				}
			}else{
				appear[elem] = ++p;
				stk[p] = elem;
			}
			cur_pos++;
		}
		cur_pos = 1;
		cur_iter++;
	}

	for(int i = 1; i <= p; i++){
		printf("%d%c", stk[i], i == p ? '\n':' ');
	}
	return;
}

int main(){
	scanf("%d %lld", &n, &iter);
	for(int i = 1; i <= n; i++){
		scanf("%d", &s[i]);
		if(occ[s[i]] != 0){
			jump[occ[s[i]]] = i + 1;
		}
		occ[s[i]] = i;
	}
	for(int i = 1; i <= n; i++){
		if(jump[occ[s[i]]] == 0){
			jump[occ[s[i]]] = i + n + 1;
		}
	}

	int cur_pos = 1, cur_iter = 1;
	loop[1] = 1;
	while(true){
	//	printf("%d %d [%lld]\n", cur_pos, cur_iter, iter);
		int nx = jump[cur_pos];
		int nx_pos = (nx - 1) % n + 1;
		int nx_iter = cur_iter + (nx - 1) / n;
		if(nx_iter > iter){
			// don't do this! Simulate the rest
			simulate_till_end(cur_pos, cur_iter);
			return 0;
		}
		else{
			cur_pos = nx_pos;
			cur_iter = nx_iter;
			if(loop[cur_pos] != 0){
				// visited before, skip ahead!
				int cycle = cur_iter - loop[cur_pos];
				assert(cycle > 0);
				iter -= (iter - cur_iter) / cycle * cycle; // the key trick
			}else{
				loop[cur_pos] = cur_iter;
			}
		}
	}
}

