const lint MOD = 1000000007;
const lint INF = 0x3f3f3f3f3f3f3f3f;
const double EPS = 1e-10;

vector<int> calcStep(vector<int> &a, int size, int maxa) {
    vector<int> last(maxa, -1);
    for (int i = 0; i < size; i++) {
        if (last[a[i]] == -1)
            last[a[i]] = i + size;
    }
    vector<int> res(size);
    for (int i = size - 1; i >= 0; i--) {
        res[i] = last[a[i]] - i;
        last[a[i]] = i;
    }
    return res;
}

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    cin >> A;
    auto step = calcStep(A, N, 200010);
    auto dp = make_v<int>(60, N);
    fill_v(dp, INF);
    for (int i = 0; i < N; i++) {
        dp[0][i] = step[i] + 1;
    }
    for (int i = 1; i < 60; i++) {
        for (int j = 0; j < N; j++) {
            int mid = (j + dp[i - 1][j]) % N;
            if (dp[i - 1][j] >= N * K)
                break;
            dp[i][j] = dp[i - 1][j] + dp[i - 1][mid];
        }
    }
    int L = N * K;
    int sum = 0;
    int pos = 0;
    bool update = true;
    while (update) {
        update = false;
        for (int i = 59; i >= 0; i--) {
            if (dp[i][pos] == INF) continue;
            if (sum + dp[i][pos] >= L)
                continue;
            sum += dp[i][pos];
            pos = (pos + dp[i][pos]) % N;
            update = true;
            break;
        }
    }
    vector<int> cnt(200010, 0);
    stack<int> st;
    for (int i = pos; i < N; i++) {
        if (cnt[A[i]]) {
            while (st.top() != A[i]) {
                cnt[st.top()]--;
                st.pop();
            }
            cnt[st.top()]--;
            st.pop();
        } else {
            cnt[A[i]]++;
            st.push(A[i]);
        }
    }
    vector<int> ans;
    while (!st.empty()) {
        ans.push_back(st.top());
        st.pop();
    }
    REV(ans);
    cout << ans << endl;

    return 0;
}

