ll n, k;
vector<int> solve(vector<int>& a, ll pos) {
    vector<int> ans(n);
    int sz = 0;
    map<int, int> ma;
    FOR(i, pos, n) {
        if(ma[a[i]] > 0) {
            while(ma[a[i]] > 0) {
                ma[ans[sz - 1]]--;
                sz--;
            }
        } else {
            ans[sz] = a[i];
            ma[a[i]]++;
            sz++;
        }
    }
    ans.resize(sz);
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> k;
    vector<int> a(n);
    REP(i, n) cin >> a[i];
    if(n == 1) {
        if(k % 2) {
            cout << a[0] << endl;
        } else {
            cout << endl;
        }
        return 0;
    }
    vector<vector<int>> num(202020);
    REP(i, n) {
        num[a[i]].pb(i);
    }
    vector<int> nxt(n, -1);
    REP(i, 202020) REP(j, num[i].size()) {
        if(j == (int)num[i].size() - 1) {
            nxt[num[i][j]] = num[i][0];
        } else {
            nxt[num[i][j]] = num[i][j + 1];
        }
    }
    ll roop = 1, pos = 0;
    vector<ll> used(n, -1);
    vector<int> ans;
    while(1) {
        used[pos] = roop;
        if(roop == k) {
            ans = solve(a, pos);
            break;
        }
        int end = nxt[pos];
        if(nxt[pos] <= pos) roop++;
        if(end == n - 1 && roop == k) {
            cout << endl;
            return 0;
        }
        if(end != n - 1) {
            pos = end + 1;
        } else {
            pos = 0;
            roop++;
        }
        if(used[pos] != -1) {
            ll p = used[pos], q = roop - used[pos];
            ll d = (k - p) / q - 1;
            roop += d * q;
            while(1) {
                if(roop == k) {
                    ans = solve(a, pos);
                    break;
                }
                int end = nxt[pos];
                if(nxt[pos] <= pos) roop++;
                if(end == n - 1 && roop == k) {
                    cout << endl;
                    return 0;
                }
                if(end != n - 1) {
                    pos = end + 1;
                } else {
                    pos = 0;
                    roop++;
                }
            }
            break;
        }
    }
    cout << ans << endl;
    return 0;
}

#include<iostream>
#include<vector>
#include<map>

class C
{
  int N;
  long long K;
  std::vector<int> A;
public:
  void input();
  void solve();
};

void C::input(){
  std::cin>>N>>K;
  A.resize(N);
  for(int i=0;i<N;i++){
    std::cin>>A[i];
  }
}

void C::solve(){
  C::input();

  const int LOG=44;
  for(int i=0;i<N;i++) A.push_back(A[i]);
  std::map<int,int> mp;
  // next[i][j]:jからスタートし、Kを2^i回行った後に空でなくなるときのindex
  int next[LOG][N+1];
  for(int i=2*N-1;i>=N;i--){
    mp[A[i]]=i;
  }
  for(int i=N-1;i>=0;i--){
    int x=mp[A[i]]+1;
    if(x>=N){
      next[0][i]=x-N;
    }else{
      next[0][i]=next[0][x];
    }
    mp[A[i]]=i;
  }

  next[0][N]=0;
  for(int i=1;i<LOG;i++){
    for(int j=0;j<=N;j++){
      next[i][j]=next[i-1][next[i-1][j]];
    }
  }

  int cur=0;
  K--;
  for(int i=0;i<LOG;i++){
    if((K>>i)&1){
      cur=next[i][cur];
    }
  }

  std::vector<int> ans;
  mp.clear();
  for(int i=cur;i<N;i++){
    if(mp.count(A[i])){
      while(ans.back()!=A[i]){
        mp.erase(ans.back());
        ans.pop_back();
      }
      mp.erase(A[i]);
      ans.pop_back();
    }else{
      ans.push_back(A[i]);
      mp[A[i]]=1;
    }
  }
  for(int a:ans) std::cout<<a<<" ";
  std::cout<<"\n";
  return;
}

int main(){
  C c;
  c.solve();
  return 0;
}

