bool circle;
int tot;

bool Pan()
{
	if(ans[tot].size() != ans[1].size()) return false;
	for(register int i=ans[1].size()-1; i>=0; i--)
		if(ans[tot][i] != ans[1][i])
			return false;
	return true;
}

int main()
{

	scanf("%d %lld", &n, &k);

	int pp=0;
	for(register int i=1; i<=n; i++)
	{
		scanf("%d", &a[i]);
		if(!cnt[a[i]])
		{
			cnt[a[i]] = 1;
			pp++;
		}
	}
	if(pp == n)
	{
		k %= n+1;
		for(register int i=k; i<=n; i++)
			printf("%d ", a[i]);
		return 0;
	}

	memset(cnt, 0, sizeof cnt);
	for(register LL i=1; i<=k; i++)
	{
		for(register int j=1; j<=n; j++)
		{
			if(!cnt[a[j]])
			{
				Q.push(a[j]);
