    ans.push_back(i);
    dfs(i+1);
  } else {
    for(int j=0; j<G[indx[i]].size(); j++){
      if(i==G[indx[i]][j]){
        if(j==G[indx[i]].size()-1) {
          visit[G[indx[i]][0]] = 1;
          ans.push_back(G[indx[i]][0]);
          dfs(G[indx[i]][0]+1);
        } else {
          visit[G[indx[i]][j+1]] = 1;
          ans.push_back(G[indx[i]][j+1]);
          dfs(G[indx[i]][j+1]+1);
        }
