    map<int,vector<int>> idx;
    vector<int> c(N);
    rep(i,2*N){
        int a = A[i%N];

        if(idx.count(a)==0){
            idx[a] = vector<int>();
        }

        if(idx[a].size() > 0)
            c[idx[a].back()] = i - (idx[a].back()) + 1;


        idx[a].push_back(i);
    }
    dump(c);

    const int MAX = 40;
    vector<vector<int>> dp;
    dp = make_v<int>(MAX, N);
    rep(i,N) dp[0][i] = c[i];

    rep(k, MAX-1){
        rep(v, N){
            if(dp[k][v] == INF) dp[k+1][v] = INF;
            else{
                dp[k+1][v] = dp[k][v] + dp[k][(v+dp[k][v])%N];
                if(dp[k+1][v]>K*N) dp[k+1][v]=INF;
            }
        }
    }
    dump(dp[0]);
    dump(dp[1]);
    dump(dp[2]);
    dump(dp[3]);
    dump(dp[4]);

    int now=0;
    for(int k=MAX-1; k>=0; k--){
        dump(dp[k]);
