int n,a[200005],Next[200005],t[200005];
ll k,p;
bool v[200005];

int getNext(int now){
	p++;
	if (Next[now]<=now){
		p+=Next[now]+n-now;
	}else p+=Next[now]-now;
	now=Next[now];
	if (now==n) now=1;
	else now=now+1;
	return now;
}

int main(){
	cin>>n>>k;
	for (int i=1;i<=n;++i){
		scanf("%d",&a[i]);
	}
	for (int i=n;i>=1;--i){
		if (t[a[i]]) Next[i]=t[a[i]];
		t[a[i]]=i;
	}
	memset(t,0,sizeof t);
	for (int i=1;i<=n;++i){
		if (t[a[i]]==0) t[a[i]]=i;
		if (Next[i]==0){
			Next[i]=t[a[i]];
		}
	}
	int now=1;
	while (1){
		if (v[now]){
			k=((k)%p)*(n%p)%p;
			if (k==0) return 0;
			k--; p=0;
			while (1){
				int tt=getNext(now);
				if (p>=k){
					break;
				}
				now=tt;
			}
			break;
		}
		v[now]=1;
		int tt=getNext(now);
		now=tt;
	}
	memset(t,0,sizeof t);
	deque <int> q;
	for (int i=now;i<=n;++i){
		if (t[a[i]]!=0){
			int z;
