				z=q.back(); q.pop_back();
				t[z]=0;
			}while (z!=a[i]);
		}else q.push_back(a[i]),t[a[i]]=1;
	}
	while (!q.empty()){
		cout<<q.front()<<" "; q.pop_front();
	}
	return 0;
}

