vector<int> used;
bool f;
int c;

//loopの始点とcostを求める.
pair<int,int> rec(int u,vector<P> &next){
    c+=next[u].sc;
    if(used[next[u].fs]){
        f=true;
        return next[u];
    }
    used[u]=true;
    auto p = rec(next[u].fs,next);
    if(p.fs == u){
        f=false;
        return make_pair(p.fs,p.sc+next[u].sc);
    }
    else if(f){
        return make_pair(p.fs,p.sc+next[u].sc);
    }
    else{
        return p;
    }
}

int rec2(int u,int k,vector<P> &next){
    if(k==1) return u;
    if(k==0) return next.size();
    return rec2(next[u].fs,k-next[u].sc,next);
}


int main(){
    long n,k;cin >> n >> k;
    vector<int> a(n);
    used.resize(n+1);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    vector<P> next(n,make_pair(-1,-1));
    vector<int> pos(200002,-1);
    for (int i = 0; i < 2; i++) {
        for (int j = n-1; j >= 0; j--) {
            if(next[j].fs==-1) next[j]=make_pair(pos[a[j]],(pos[a[j]]<=j+1?1:0));
            pos[a[j]]=(j+1)%n;
        }
    }
    if(next[n-1].fs==0) next[n-1].sc++;
    auto p = rec(0,next);
    int s;
    if(k<c) s=rec2(0,k,next);
    else s=rec2(p.fs,(k-c)%p.sc+p.sc,next);
    vector<int> ans;
    for (int i = s; i < n;) {
        if(next[i].sc){
            if(i!=n-1&&next[i].fs==0) break;
            ans.pb(a[i]);
            i++;
        }
        else{
            if(next[i].fs<i) break;
            i=next[i].fs;
        }
    }
    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i] << (i==ans.size()-1?"\n":" ");
    }
    return 0;
}

