int _main()
{
        ll n, k;
        llin(n); llin(k);

        V<ll> alist;
        llina(alist, n);

        V<ll> a_to_idxs[200005];
        rep (i, n) a_to_idxs[alist[i]].pb(i);

        V<t2> idx_loops;

        ll a = alist[0];
        idx_loops.pb(t2(0LL, 1LL));

        srep (i, 1, n+10) {
                ll prev_idx = get<0>(idx_loops[idx_loops.size()-1]);
                ll prev_loop = get<1>(idx_loops[idx_loops.size()-1]);

                int idx;
                int loop = prev_loop;
                auto iter = lower_bound(ALL(a_to_idxs[a]), prev_idx+1);
                if (iter == a_to_idxs[a].end()) {
                        idx = a_to_idxs[a][0];
                        loop++;
                }
                else {
                        idx = *iter;
                }

                if (idx == n-1) {
                        idx = 0;
                        loop++;
                }
                else {
                        idx = idx + 1;
                }

                bool finish = false;
                if (idx == 0) finish = true;

                a = alist[idx];
                idx_loops.pb(t2(idx, loop));

                if (finish) break;
        }

        assert(get<0>(idx_loops[idx_loops.size()-1]) == 0LL);
        debug_printf("---- idx_loops\n");
        debug_print(idx_loops);

        ll loopcount = get<1>(idx_loops[idx_loops.size()-1]) - 1LL;
        debug_printf("---- loopcount\n");
