    for (ll i = 0; i < N; i++)
        mas[i] = 0;
    ll num = 0;
    for (ll i = 1; i <= nn; i++){
        if (mas[A[i]] == 0){
            re[++num] = A[i];
            mas[A[i]] = num;
            continue;
        }
        ll le = mas[A[i]];
        while (num >= le){
            mas[re[num]] = 0;
            num--;
        }
    }
    for (ll i = 1; i <= num; i++)
        cout << re[i] << " ";
    cout << endl;
}


main()
{
    //freopen ("in.in", "r", stdin);freopen ("out.out", "w", stdout);
    ios_base::sync_with_stdio(0);
    cin >> n >> K;
    for (ll i = 1; i <= n; i++)
        cin >> a[i];
    for (ll i = n; i >= 1; i--){
        M[a[i]] = i;
    }
    for (ll i = n; i >= 1; i--){
        ne[i] = mas[a[i]];
        mas[a[i]] = i;
        if (ne[i] == 0){
            ne[i] = M[a[i]];
            d[i] = 1;
        }
        ne[i]++;
        if (ne[i] > n){
            d[i]++;
            ne[i] -= n;
        }
    }
    ll t = 1;
    D[1] = 1;
    while (1){
        if (D[t] >= K)
            break;
        fix[t] = 1;
        ll to = ne[t];
        ll dist = D[t] + d[t];
        if (fix[to]){
            ll dif = dist - D[to];
            K %= dif;
            while (K < D[to])
                K += dif;
            break;
        }
        D[to] = dist;
        t = to;
    }
    ll st = 0;
    for (ll i = 1; i <= n; i++)
        if (D[i] == K){
            st = i;
            break;
        }
    if (st == 0){
        go ();
        return 0;
    }
    for (ll i = st; i <= n; i++)
        A[++nn] = a[i];
    go ();
    return 0;
}

