struct MyStack {
    vector<int> st;
    MyStack(int n) : st(n), head(0) {}
    int back(void) {
        return st[head-1];
    }
    void pop_back() {
        head--;
    }
    void push_back(int n) {
        st[head++] = n;
    }
    void clear(void) {
        head = 0;
    }
    int size(void) {
        return head;
    }
    private:
    int head;
};

