        now = getnextid(now , l);
    }
    stack<int> st;
    vector<bool> used(200020,false);
    for(int i = now;i < n;i++){
        if(!used[a[i]]) st.push(a[i]),used[a[i]] = true;
        else{
            while(st.top() != a[i]){
                used[st.top()] = false;
                st.pop();
            }
            st.pop();
            used[a[i]] = false;
        }
    }
    vector<int> ans;
    while(!st.empty()){
        ans.pb(st.top());
        st.pop();
    }
    if(ans.size())reverse(all(ans));
    for(int i = 0;i < ans.size();i++){
        if(!i)cout<< ans[i];
        else cout << ' ' << ans[i];
    }
