int n,k;
int a[N],c[N],d[N];
int nex[N];
int t[N],T;
main()
{
    //freopen("hx.inp","r",stdin);
    n=in;k=in-1;memset(d,-1,sizeof d);
    FOR(i,1,n) a[i]=in;
    FOR(i,n+1,2*n) a[i]=a[i-n];
    ROF(i,1,2*n)
    {
        nex[i]=c[a[i]]+1;
        c[a[i]]=i;
    }
    ROF(i,1,n) if(nex[i]<=n) nex[i]=nex[nex[i]];
    FOR(i,1,n) nex[i]-=n;

    int r=1,cnt;d[1]=0;
    while(1)
    {
        int rnex=nex[r];

        if(d[rnex]>=0) {cnt=d[r]-d[rnex];r=rnex;break;}
        else d[rnex]=d[r]+1,r=rnex;
    }
    cnt++;
    if(d[r]<=k) k-=d[r],k%=cnt;
    FOR(i,1,k) r=nex[r];

    memset(c,0,sizeof c);
    FOR(i,r,n)
    {
        if(c[a[i]]>0)
        {
            while(t[T]!=a[i]) c[t[T--]]=0;T--;
            c[a[i]]=0;
        }
        else t[++T]=a[i],c[a[i]]=1;
    }
    FOR(i,1,T) cout<<t[i]<<" ";
}

