void sim(vector<int> &A, int cur) {
    vector<int> used(MAX_N, 0);
    vector<int> ans;
    rep(i, cur, A.size()) {
        if(used[A[i]] == 0) {
            ans.push_back(A[i]);
            used[A[i]] = 1;
        }
        else {
            while(1) {
                int top = ans.back();
                ans.pop_back();
                used[top] = 0;
                if(top == A[i]) {
                    break;
                }
            }
        }
    }
    voutput(ans);
}

