#define N 600010


int main() {
	long long nex[N];
	long long nexa[N];
	long long a[N];
	long long sylas[N];
	long long bef[N];
	f(i, N)a[i] = 0;
	long long n, k, kk;
	long long x, y, z;
	long long ans[N];
	long long fians;
	bool used[N];
	stack<long long> q;
	bool v = true;
	scanf("%lld %lld", &n, &kk);
	f(i, n) {
		scanf("%lld", &a[i]);
		a[n + i] = a[i];
	}
	f(i, N)bef[i] = -1;
	f(i, 2*n) {
		if (bef[a[i]] != -1) {
			x = bef[a[i]] / n;
			y = (i + 1) / n;
			z = (i + 1) % n;
			nexa[bef[a[i]]] = y - x;
			nex[bef[a[i]]] = z;
		}
		bef[a[i]] = i;
	}
	f(i, N)sylas[i] = -1;
	k = 0;
	sylas[0] = 0;
	k = nexa[0];
	x = nex[0];
	sylas[k] = x;
	while (x != 0) {
		k += nexa[x];
		x = nex[x];
		sylas[k] = x;
	}
	kk = kk % k;
	if (kk == 0) {
		printf("\n");
		return 0;
	}
	if (sylas[kk - 1] == -1) {
		printf("\n");
		return 0;
	}
	x = sylas[kk - 1];
	f(i, N)used[i] = false;
	for (long long i = x; i < n; i++) {
		if (!used[a[i]]) {
			q.push(a[i]);
			used[a[i]] = true;
		}
		else {
			x = q.top();
			while (x != a[i]) {
				q.pop();
				x = q.top();
			}
			q.pop();
			used[a[i]] = false;
		}
	}
	fians = 0;
	while (!q.empty()) {
		x = q.top();
		ans[fians] = x;
		fians++;
		q.pop();
	}
	f(i, fians) {
		printf("%lld", ans[fians - i - 1]);
		if (i < (fians - 1))printf(" ");
		else printf("\n");
	}

	return 0;
}

#include <iostream>
