int main() {
	int n;
	long long k;
	std::cin >> n >> k;
	std::vector<int> a(n);
	for (int &e : a) std::cin >> e;

	int sz = *std::max_element(a.begin(), a.end()) + 1;

	std::vector<int> pre(sz, -1), next(n, -1);
	for (int num = 0; num < 3 * n; num++) {
		const int i = num % n, j = pre[a[i]];
		if (j != -1 and next[j] == -1) {
			next[j] = (i + 1) % n;
		}
		pre[a[i]] = i;
	}

	std::vector<int> dat(n);
	std::vector<bool> processed(n, false);
	for (int s = 0; s < n; s++) {
		if (processed[s]) continue;
		int i;
		std::vector<int> seen;
		for (i = s; i + 1 < next[i]; i = next[i]) {
			seen.push_back(i);
		}
		seen.push_back(i);
		for (int v : seen) {
			dat[v] = next[i];
			processed[v] = true;
		}
	}

	int s = 0; k--;
	for (int i = 0; i < 50; i++) {
		if (k >> i & 1) s = dat[s];
		std::vector<int> buff(n);
		for (int j = 0; j < n; j++) {
			buff[j] = dat[dat[j]];
		}
		dat.swap(buff);
	}

	std::vector<int> sec;
	std::vector<bool> pushed(sz, false);
	for (int i = s; i < n; i++) {
		if (pushed[a[i]]) {
			while (sec.back() != a[i]) {
				pushed[sec.back()] = false;
				sec.pop_back();
			}
			pushed[a[i]] = false;
			sec.pop_back();
		} else {
			sec.push_back(a[i]);
			pushed[a[i]] = true;
		}
	}

	for (int ans : sec) std::cout << ans << ' ';

	return 0;
}

