ll cost[200100];
int main(){
	cin >> N >> K;
	vector<int> zip;
	for(int i=0;i<N;i++){
		cin >> A[i];
		zip.pb(A[i]);
	}
	sort(all(zip));
	zip.erase(unique(all(zip)),zip.end());
	for(int i=0;i<N;i++){
		A[i] = lower_bound(all(zip),A[i])-zip.begin();
		vec[A[i]].pb(i);
		vec[A[i]].pb(i+N);
	}
	for(int i=0;i<zip.size();i++)sort(all(vec[i]));
	for(int i=0;i<N;i++){
		nxt[i] = (*upper_bound(all(vec[A[i]]),i))+1;
		cost[i] = nxt[i]-i;
