	for (int i = 0; i < n; ++i) {
		cin >> a[i];
	}
	vector<int> first(200002, -1), next(200002, -1), vis(n, -1);
	for (int i = n - 1; i >= 0; --i) {
		next[i] = first[a[i]];
		first[a[i]] = i;
	}
	bool skipped = false;
	int pos = 0;
	for (LL i = 0; i < k - 1; ++i) {
		while (true) {
			if (!skipped && vis[pos] >= 0) {
				skipped = true;
				LL t = i - vis[pos];
				i += (max(0LL, (k - i - 3) / t)) * t;
			} else {
				vis[pos] = i;
			}
			int next_pos = next[pos];
			if (next_pos < 0) {
				pos = first[a[pos]] + n + 1;
			} else {
				pos = next_pos + 1;
			}
			if (pos >= n) {
				pos %= n;
				break;
			}
		}
	}
	vector<int> ans;
	for (; pos < n; ++pos) {
		int next_pos = next[pos];
		if (next_pos >= 0) {
			pos = next_pos;
		} else {
			ans.push_back(a[pos]);
		}
	}
	bool f = false;
	for (auto x : ans) {
		if (f) cout << " ";
		f = true;
