    REP(k,L){
        REP(i,N){
            LL nowid = i + nx[k][i];
            LL nextid = nowid + nx[k][nowid%N];
            nx[k+1][i] = nextid - i; //= next[k][i] + next[k][nowid%N]
        }
    }


    LL cur=0;
    CIREP(i,L,0){
        if(cur + nx[i][cur%N] <= K) cur+=nx[i][cur%N];
    }

