//library
ll log_in_Z(ll a, ll b){
    ll p = a;
    ll res = 0;
    ll cnt = 1;
    while(p<b){
        b-=p;
        res += cnt;
        p = p*p;
        cnt++;
    }
    if(b == 0) return res;
    else return res+1;
}
