        ll j = *iter;
        h+=j-i+1;
        next_k_i[1][i] = P(h, (j+1)%N);
    }
    FOR(i, 2, N0){
        rep(j, N){
            ll a = next_k_i[i-1][j].first;
            ll b = next_k_i[i-1][j].second;
            ll c = next_k_i[i-1][b].first;
            ll d = next_k_i[i-1][b].second;
            next_k_i[i][j] = P(a+c, d);
