      if (pos[AA[i]]<N) parent[pos[AA[i]]] = i;
    }
    pos[AA[i]] = i;
  }
  /*for (int i=0; i<N; i++) {
    printf("parent[%d] = %d\n", i, parent[i]);
  }*/
  std::vector<long long> visit(N+4, -1);
  int now = 0;
  visit[now] = 0;
  long long cycle;
  while(true) {
    int step = parent[now] - now + 1;
    int next = (parent[now] + 1) % N;
    cycle = visit[now] + step;
    if (visit[next]!=-1) break;
    visit[next] = cycle;
    now = next;
    cycle = visit[now];
  }
  // printf("cycle=%lld\n", cycle);
  long long num = K*N;
  num %= cycle;
  now = 0;
  long long sum = 0;
  while(true) {
    int step = parent[now] - now + 1;
    int next = (parent[now] + 1) % N;
    if (sum + step > num) break;
    if (next==0) break;
    sum += step;
    now = next;
  }
  num -= sum;
  // printf("now=%d, num=%lld\n", now, num);
  // nowをスタートとしてnum回文字を処理する
  std::vector<int> ans;
  std::map<int, int> mp;
  for (int i=0; i<num; i++) {
    int index = (i + now) % N;
    if (mp[A[index]]==1) {
      while(ans[ans.size()-1]!=A[index]) {
        mp[ans[ans.size()-1]] = 0;
        ans.pop_back();
      }
      mp[A[index]] = 0;
      ans.pop_back();
    } else {
      ans.push_back(A[index]);
      mp[A[index]] = 1;

    }
  }
  for (int p: ans) {
    std::cout << p << std::endl;
  }
  return 0;
}

