void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);
    ll k; llin(k);
    S V<ll> alist; llina(alist, n);

    k--;

    S V<ll> poslist[200005];
    rep (i, n) poslist[alist[i]].pb(i);

    S ll turns[200005];
    rep (i, 200005) turns[i] = -1LL;

    ll base = 0LL;
    ll cycle = 1LL;
    ll next_idx = 0LL;
    turns[next_idx] = 0LL;
    ll now_idx = next_idx;

    for ( ; ; ) {
        ll a = alist[now_idx];
        ll turn = turns[now_idx];
        auto iter1 = upper_bound(ALL(poslist[a]), now_idx);
        auto iter2 = lower_bound(ALL(poslist[a]), 0LL);
        if (iter1 != poslist[a].end()) {
            next_idx = *iter1;
        }
        else {
            next_idx = *iter2;
            turn++;
        }
        next_idx++;
        if (next_idx == n) {
            next_idx = 0LL;
            turn++;
        }

        if (turns[next_idx] >= 0LL) {
            base = turns[next_idx];
            cycle = turn - turns[next_idx];
            break;
        }

        now_idx = next_idx;
        turns[next_idx] = turn;
    }

    debug_printf("---- base=%lld cycle=%lld\n", base, cycle);
    debug_printf("---- turns\n");
    debug_print(turns, n);

    ll target = 0LL;
    if (k < base) target = k;
    else target = (k - base) % cycle;

    ll start_idx = -1LL;
    bool extra = false;

    rrep (i, n) {
        if (turns[i] == target) {
            start_idx = i;
            break;
        }
    }

    if (start_idx < 0LL) {
        rrep (i, n) {
            if (turns[i] == target - 1LL) {
                start_idx = i;
                extra = true;
