const int N = 2e5 + 5;
int a[N];
pii pt[N];
vector<int> pos[N];
int cnt[N];

void solve() {
    int n;
    ll k;
    sc(n, k);
    fr(i, 1, n) {
        sc(a[i]);
        pos[a[i]].pb(i);
    }
    fr(i, 1, N - 1) {
        if(pos[i].empty()) continue;
        fr(j, 0, sz(pos[i]) - 2) {
            pt[pos[i][j]] = {(pos[i][j + 1] % n) + 1, pos[i][j + 1] - pos[i][j]};
        }
        pt[pos[i].back()] = {(pos[i][0] % n) + 1, n - pos[i].back() + pos[i][0]};
    }
    ll cyc = 0;
    int x = 1;
    fr(i, 1, n) {
        pt[i].se++;
        debug(i, pt[i].fi, pt[i].se);
    }
    do {
        cyc += pt[x].se;
        x = pt[x].fi;
    } while(x != 1);
    debug(cyc);
    ll tot = n * k;
    tot %= cyc;
    int st = 1;
    while(tot >= pt[st].se) {
        tot -= pt[st].se;
        st = pt[st].fi;
    }
    vector<int> ans;
    while(tot) {
        tot--;
        ans.pb(a[st]);
        cnt[a[st]]++;
        if(cnt[a[st]] == 2) {
            while(cnt[a[st]]) {
                cnt[ans.back()]--;
                ans.pop_back();
            }
        }
        st = (st % n) + 1;
    }
    // cout << sz(ans) << endl;
    for(int x : ans) {
        cout << x << " ";
    }
}

