const int M = 2 * (int)1e5;
const int H = 50;
int fst[M];
int lst[M];
ll nxt[M][H];

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	ll n, k;
	cin >> n >> k;

	for (int v = 0; v < M; ++v) {
		fst[v] = n;
		lst[v] = -1;
	}

	vector<ll> vals(n);
	for (int i = 0; i < n; ++i) {
		int v;
		cin >> v;
		--v;

		if (lst[v] != -1) {
			nxt[lst[v]][0] = i + 1;
		} else {
			fst[v] = i;
		}
		lst[v] = i;
		vals[i] = v;
	}
	for (int v = 0; v < M; ++v) {
		if (lst[v] != -1) {
			nxt[lst[v]][0] = fst[v] + n + 1;
		}
	}
	for (int j = 1; j < H; ++j) {
		for (int i = 0; i < n; ++i) {
			ll t = nxt[i][j-1];
			ll c = t / n;
			int r = t - c * n;
			nxt[i][j] = n*c + nxt[r][j-1];
		}
	}

	int i = 0;
	for (int j = H - 1; j >= 0; --j) {
		ll t = nxt[i][j];
		ll c = t / n;
		int r = t - c * n;
		if (c >= k) continue;
		k -= c;
		i = r;
	}
	assert(k == 1);

	for (int v = 0; v < M; ++v) {
		fst[v] = -1;
	}

	vector<ll> res;
	for (; i < n; ++i) {
		int v = vals[i];
		if (fst[v] != -1) {
			res.resize(fst[v]);
			fst[v] = -1;
		} else {
			fst[v] = res.size();
			res.push_back(v);
		}
	}
	for (auto v : res) cout << v+1 << ' '; cout << '\n';
}

