long long get(int x) {
	if(vs[x]) return 0;
	vs[x] = 1;
	return get(nx[x]) + c[x];
}

void go(long long x) {
	if(x + c[x%N] <= K*N) go(x + c[x%N]);
	else {
		vector<int> S;
		vector<bool> chk(200009, 0);
		for(int i=x%N; i<N; i++) {
