typedef long long ll;

void printStack(stack<int> stc){
	int size = stc.size();
	vector<int> copy(size);
	for (int i = 0; i < size; i++) {
		copy[i] = stc.top();
		stc.pop();
	}
	for (int i = 0; i < size; i++)cout << copy[size - 1 - i] << " "; cout << endl;
	for (int i = 0; i < copy.size(); i++) stc.push(copy[copy.size() - 1 - i]);
}

bool searchStack(stack<int> stc, int number) {
	int size = stc.size();
	vector<int>copy(size);
	for (int i = 0; i < size; i++) {
		if (stc.top() == number) {
			for (int j = 0; j < i; j++) stc.push(copy[i - 1 - j]);
			return true;
		}
		copy[i] = stc.top();
		stc.pop();
	}
	for (int i = 0; i < copy.size(); i++) stc.push(copy[copy.size() - 1 - i]);
	return false;
}

int main() {
	int n;
	ll k;
	int a[200000];
	cin >> n >> k;
	for (int i = 0; i < n; i++)cin >> a[i];

	set<int> st;
	stack<int> stc;
	for (int i = 0; i < k; i++) {
		for (int j = 0; j < n; j++) {
			auto itr = st.find(a[j]);
			//要素がない
			if (itr == st.end()) {
				st.insert(a[j]);
				stc.push(a[j]);
			}
			//要素がある
			else {
				while (true) {
					if (stc.top() == a[j]) {
						stc.pop();
						st.erase(a[j]);
						break;
					}
					else {
						int top = stc.top();
						stc.pop();
						if (!searchStack(stc, top)) st.erase(top);
					}
				}

			}
		}
	}
	printStack(stc);

	return 0;
}

