    vector<int> current;
    map<int, int> m;
    for (int i = N - 1; i >= 0; i--)
    {
        if (m.find(A[i]) == m.end())
        {
            current.push_back(A[i]);
        }
        else
        {
            int idx = m[A[i]] + 1;

            if (idx >= N)
            {
                current.clear();
            }
            else
            {
                current = dp[idx];
            }
        }
        dp[i] = current;
        m[A[i]] = i;
    }
    // for (auto x : dp)
    // {
    //     for (auto y : x)
    //     {
    //         cout << y << " ";
    //     }
    //     cout << endl;
    // }

    vector<vector<int>> ans(N + 1);
    ans[0].clear();
    ans[1] = current;
    for (int i = 2; i <= N; i++)
    {
        if (current.empty())
        {
            current = dp.front();
        }
        else
        {
            int idx = m[current.back()] + 1;
            if (idx >= N)
            {
                current.clear();
            }
            else
            {
                current = dp[idx];
            }
        }

        ans[i] = current;
