      auto crr = v.at(i), nxt = v.at(i + 1);
      assert(0 <= crr && crr < n && crr < nxt);
      at(table, 0, crr) = nxt - crr + 1;
    }
  }
  constexpr long long inf = 3e17;
  for (int i = 0; i < lg - 1; i++) {
    auto& crr = table.at(i);
    auto& nxt = table.at(i + 1);
    for (int j = 0; j < n; j++) {
      auto a = crr.at(j);           if (a == inf) nxt.at(j) = inf;
      auto b = crr.at((j + a) % n); if (b == inf) nxt.at(j) = inf;
      nxt.at(j) = std::min(inf, a + b);
    }
  }
  auto moved = [&] (auto i, auto x) {
    return x + at(table, i, x % n);
  };
  long long crr = 0, goal = n * k;
  for (int i = lg - 1; i >= 0; i--) {
    auto nxt = moved(i, crr);
    if (nxt < goal) crr = nxt;
  }
  std::vector<int> ans;
  while (crr < goal) {
    auto nxt = moved(0, crr);
    if (nxt <= goal) {
      crr = nxt;
      continue;
    }
    ans.push_back(a.at((crr++ % n)));
  }
  int sz = ans.size();
  for (int i = 0; i < sz; i++) {
    std::cout << (i > 0 ? " " : "") << ans.at(i) + 1;
  }
  std::cout << std::endl;
  return 0;
}

