const int MAX = 2e5 + 41;
int n;
ll k;
int a[MAX];

vi getsuf(int x) {
	vi cnt(MAX, 0);
	vi res;
	fi(x, n - 1) {
		bool f = true;
		while (cnt[a[i]] > 0) {
			f = false;
			cnt[res.back()]--;
			res.pop_back();
		}
		if (f) {
			res.pb(a[i]);
			cnt[a[i]]++;
		}
	}
	return res;
}

int nxt[MAX];
int fp[MAX];
int lp[MAX];
int nxtsuf[MAX];

void solve () {	
	memset(nxt, -1, sizeof(nxt));
	memset(lp, -1, sizeof(lp));
	fdi(n - 1, 0) fp[a[i]] = i;
	fdi(n - 1, 0) {
		nxt[i] = lp[a[i]];
		lp[a[i]] = i;
	}
	nxtsuf[n] = 0;	
	fdi(n - 1, 0) {
		if (nxt[i] == -1) {
		  nxtsuf[i] = fp[a[i]] + 1;
		} else {
			if (nxt[i] == n - 1) {
				nxtsuf[i] = 0;
			} else {
				nxtsuf[i] = nxtsuf[nxt[i] + 1];
			}
		}
	}	

	vi order;
	vi was(n + 1, 0);
	int x = 0;
	while (!was[x]) {
		order.pb(x);
		was[x] = 1;
		x = nxtsuf[x];
	}	
	vi cycle, path;	
	while (sz(order)) {
		int ver = order.back();
		cycle.pb(ver);
		order.pop_back();		
		if (ver == x) break;
	}	
	path = order;
	reverse(cycle.begin(), cycle.end());
	int anssuf = -1;
	if (k <= sz(path)) {
		anssuf = path[k - 1];
	} else {
		ll kk = k - sz(path);
		int pos = (kk - 1) % sz(cycle);
		anssuf = cycle[pos];
	}	
	dbg(anssuf);
	vi resp = getsuf(anssuf);
	for (int x : resp) {
		printf("%d ", x);
	}
