template <typename T>
struct hash_map_t {
    vector <T> v, val, nxt;
    vector <int> head;
    int mod, tot, lastv;
    T lastans;
    bool have_ans;

    hash_map_t (int md = 0) {
        head.clear(); v.clear(); val.clear(); nxt.clear(); tot = 0; mod = md;
        nxt.resize(1); v.resize(1); val.resize(1); head.resize(mod);
        have_ans = 0;
    }

    void clear() { *this = hash_map_t(mod); }

    bool count(int x) {
        int u = x % mod;
        for(register int i = head[u]; i; i = nxt[i]) {
            if(v[i] == x) {
                have_ans = 1;
                lastv = x;
                lastans = val[i];
                return 1;
            }
        }
        return 0;
    }

    void ins(int x, int y) {
        int u = x % mod;
        nxt.push_back(head[u]); head[u] = ++tot;
        v.push_back(x); val.push_back(y);
    }

    int qry(int x) {
        if(have_ans && lastv == x) return lastans;
        count(x);
        return lastans;
    }
};

const int N = 2e5 + 5;

vector <int> t[N];
int a[N], id[N], cnt[N], st[N];
int n, val, top;
ll k;

pii find_next(int x) {
    pii ans;
    if(id[x] == (int)t[a[x]].size() - 1) {
        ans.first = t[a[x]][0] + 1;
        ans.second = 1;
        if(ans.first == n + 1) ans.first = 1, ++ans.second;
    } else {
        ans.first = t[a[x]][id[x] + 1] + 1;
        ans.second = 0;
        if(ans.first == n + 1) ans.first = 1, ++ans.second;
    }
    return ans;
}

int main() {
    read(n); read(k);
    for(register int i = 1; i <= n; i++) read(a[i]), t[a[i]].push_back(i), id[i] = t[a[i]].size() - 1;
    pii ans = find_next(1);
    int now = ans.first; val = ans.second;
    while(now != 1) {
        ans = find_next(now);
        now = ans.first;
        val += ans.second;
    }
    k %= val; now = 1; int nowid = 1;
    if(!k) return 0;
    while(nowid <= k) {
        ans = find_next(now);
        if(nowid + ans.second <= k) {
            now = ans.first;
            nowid += ans.second;
        } else if(nowid + ans.second == k + 1 && ans.first == 1) {
            return 0;
        } else break;
    }
    for(register int i = now; i <= n; i++) {
        if(!cnt[a[i]]) st[++top] = a[i], ++cnt[a[i]];
        else { while(cnt[a[i]]) --cnt[st[top]], --top; }
    }
    for(register int i = 1; i <= top; i++) print(st[i], i == top ? '\n' : ' ');
    return 0;
}

