int main() {
	scanf("%d%I64d", &n, &k);
	for (int i = 0; i < n; i ++) scanf("%d", &a[i]);
	for (int i = 0; i < n; i ++) a[n+i] = a[i];
	for (int i = 2 * n - 1; i >= 0; i --) {
		if (i < n) {
			g[i] = b[a[i]] + 1 - i;
			to[i] = (b[a[i]] + 1) % n;
		}
		b[a[i]] = i;
	}
	c[1] = 0;
	vis[0] = 1;
	int st, d;
	for (int i = 1;; i ++) {
		c[i] = to[c[i-1]];
		if (vis[c[i]]) {
			st = vis[c[i]];
			d = i - st;
			break;
		}
		vis[c[i]] = i;
	}
	ll up = k * n;
	ll p = 1;
	ll cur = 0;
	for (p = 1; p < st; p ++) {
		if (cur + g[c[p]] >= up) break;
		cur += g[c[p]];
	}
