				if (d[i + 1] <= d[i] + 1) {
					if (l) sum++;
					else res++;
				}
			}
			//周期sumで一周する、周期の始まりはres番目
			int r = (k - res - 1) / sum;
			r = r * sum + res + 1;
			//rerが周期の始まりでd[rer]から物が追加され始める
			//つまり、r周期目のd[rer]番目は、何もない状態で、これからいろいろとはじまる状態
			if (r == k) {
				g = d[rer];
				goto loop;
			}
			for (int i = rer; i < d.size(); i++) {
				g = lower_bound(b[a[d[i]]].begin(), b[a[d[i]]].end(), d[i]) - b[a[d[i]]].begin();
				if (g == b[a[d[i]]].size() - 1) {
					g = 0;
				}
				else g++;
				g = b[a[d[i]]][g] + 1;
				if (g == n) g = 0;
				//g番目がこの回の初期化イベントが終了するとき
				if (g <= d[i] + 1) {
					r++;
				}//この会の初期化が次の周期にもつれ込む場合
				if (r == k) {
					goto loop;
				}
			}

		}
		c[t] = 1;
		//今現在t番にいる
		int e = lower_bound(b[a[t]].begin(), b[a[t]].end(), t) - b[a[t]].begin();
		if (e == b[a[t]].size() - 1) {
			e = 0;
		}
		else e++;
		int r = b[a[t]][e] + 1;
		if (r == n) r = 0;
		d.push_back(r);
		t = r;
	}
loop:;
	//[0,ed)
	//g番目からだけシミュレーション
	vector<int>f, h;
	for (int i = 0; i < 300000; i++) {
		b[i].clear();
		c[i] = 0;
	}
	//現在採用されているか
	for (int i = g; i < n; i++) {
		if (!b[a[i]].empty()) {
			for (int j = b[a[i]].size() - 1; j >= 0; j--) {
				if (!c[b[a[i]][j]]) {
					b[a[i]].pop_back();
				}
			}
		}
		if (!b[a[i]].empty()) {
			for (int j = h.size() - 1; j >= 0; j--) {
				bool l = 0;
				if (h[j] == b[a[i]][b[a[i]].size() - 1]) {
					l = 1;
				}
				c[h[h.size() - 1]] = 0;
				h.pop_back(); f.pop_back();
				if (l) {
					goto roop;
				}
			}
		}
		f.push_back(a[i]);
		h.push_back(i);
		b[a[i]].push_back(i);
		c[i] = 1;
	roop:;
	}
	for (int i = 0; i < f.size(); i++) {
		cout << (i == 0 ? "" : " ") << f[i];
	}
	cout << endl;
}

