class Shakutori {
public:
  // 全体の範囲
  // [0, end)
  // 注目している範囲
  // [tail, head)
  Int head, tail, end = 0;
  bool moveHead() {
    if (head == end) {
      return false;
    }
    head++;
    return true;
  }
  void moveTail() { tail++; }
  bool valid() {
    if (head == tail)
      return true;
    // [tail, head)
    // が解として適当か検証する
    return true;
  }
  void solve() {
    head = tail = 0;
    Int ans = 0;
    while (moveHead()) {
      while (!valid()) {
        moveTail();
      }
      // ここで解を更新する
    }
  }
};

class Solver {
public:
  Int N, K;
  vi A;
  vi ans;
  vector<set<Int> > VS;
  Solver() {}
  void input() {
    cin >> N >> K;
    A = vi(N);
    FOR(a, A)cin >> a;
  }
  void solve() {
    if(N == 1){
      if(K % 2 == 0){
        return;
      }
      ans.push_back(A[0]);
      return;
    }
    VS = vector<set<Int>>(2 * Int(1e5) + 1);
    rep(i, N){
      VS[A[i]].insert(i);
    }

    vi path;
    vi need_loop;

    {
      set<Int> visited;
      Int now = 0;

      Int loopFlag = 0;
      while (visited.count(now) == 0) {
        visited.insert(now);
        path.push_back(now);
        need_loop.push_back(loopFlag);
        loopFlag = 0;
        auto it = VS[A[now]].upper_bound(now);
        if (it == VS[A[now]].end()) {
          it = VS[A[now]].begin();
          loopFlag= 1;
        }
        if(*it +1 == N)loopFlag = 1;
        now = (*it + 1)%N;
      }
    }

    dump(path);

    Int loop = 1;
    rep(i, path.size()){
      loop += need_loop[i];
    }
    K--;
    pp(loop);
    pp(K%loop);
    K %= loop;

    Int last2 = 0;
    rep(i, path.size()){
      pp(path[i]);
      pp(K);
      if(K == 0){
        break;
      }
      if(need_loop[i]){
        last2 = path[i];
        K--;
      }
    }
    assert(K == 0);
    pp(last2);
    REP(i, last2, N){
      auto it = VS[A[i]].upper_bound(i);
      if(it == VS[A[i]].end()){
        ans.push_back(A[i]);
      }else{
        i = *it;
      }
    }
  }
  void output() {
    string sep = "";
    FOR(a, ans){
      cout << sep << a;
      sep = " ";
    }
    cout <<endl;
  }
};

