const int max_n = 200222, inf = 1000111222;
const int max_lev = 64;

int n, a[max_n], first[max_n], cnt[max_n];
int nxt[max_lev][max_n];
long long k, h[max_lev][max_n];
vector<int> v;

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    cin >> n >> k;
    memset(first, -1, sizeof(first));
    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
        if (first[a[i]] == -1) {
            first[a[i]] = i;
        }
    }
    for (int i = n - 1; i >= 0; --i) {
        nxt[0][i] = first[a[i]];
        if (i == first[a[i]]) {
            h[0][i] = 1;
        }
        ++nxt[0][i];
        if (nxt[0][i] == n) {
            nxt[0][i] = 0;
            ++h[0][i];
        }
        first[a[i]] = i;
    }
    for (int lev = 1; lev < max_lev; ++lev) {
        for (int i = 0; i < n; ++i) {
            nxt[lev][i] = nxt[lev - 1][nxt[lev - 1][i]];
            h[lev][i] = h[lev - 1][i] + h[lev - 1][nxt[lev - 1][i]];
            if (h[lev][i] >= k) {
                h[lev][i] = k;
                nxt[lev][i] = 0;
            }
        }
    }
    long long curh = 0;
    int pos = 0;
    for (int lev = max_lev - 1; lev >= 0; --lev) {
        if (curh + h[lev][pos] < k) {
            curh += h[lev][pos];
            pos = nxt[lev][pos];
        }
    }
    while (curh < k) {
        if (cnt[a[pos]] == 0) {
            ++cnt[a[pos]];
            v.push_back(a[pos]);
        } else {
            while (cnt[a[pos]]) {
                --cnt[v.back()];
                v.pop_back();
            }
        }
        ++pos;
        if (pos == n) {
            pos = 0;
            ++curh;
        }
    }
    for (int x : v) {
        printf("%d ", x);
    }
    puts("");
    return 0;
}

