  ll n,k;cin>>n>>k;
  vector<ll> A(n), Next(n), memo(n);
  rep(i,n){
    cin>>A[i];
  }
  REP(i,n){
    memo[A[i]] = i;
  }
  REP(i,n){
    Next[i] = memo[A[i]];
    memo[A[i]] = i;
  }
  vector<bool> checked(n,false);
  ll now = 0;
  while(k >= 2){
    ll next = Next[now];
    if(next <= now) k--;
    if(next == n-1) k--;
    now = (next + 1) % n;
    if(checked[next]) break;
    checked[next] = true;
  }
  if(k == 0){
    return 0;
  }
  if(k == 1){
    simulate(k, now, A);
    return 0;
  }

  ll goal = now;

  ll count = 0;
  while(k >= 2){
    ll next = Next[now];
    if(next <= now) count++;
    if(next == n-1) count++;
    now = (next + 1) % n;
    if(now == goal) break;
  }
  if(k == 0){
    return 0;
  }
  if(k == 1){
    simulate(k, now, A);
    return 0;
  }

  k = k % count;
  while(k >= 2){
    ll next = Next[now];
    if(next <= now) k--;
    if(next == n-1) k--;
    now = (next + 1) % n;
  }
  if(k == 0){
    return 0;
  }
  if(k == 1){
    simulate(k, now, A);
    return 0;
  }

  return 0;
}

