// doubling[k][i] := a[i] から始めて 2^k 回操作を行った時の長さ
ll doubling[70][200005];

int main(void){
    int N;
    ll K;
    cin >> N >> K;
    vector<int> a(N);
    vector<vector<int>> pos(2e+5 + 1);  // 要素の位置を表すテーブル
    for(int i = 0; i < N; ++i){
        cin >> a[i];
        pos[a[i]].push_back(i);
    }

    for(int i = 0; i < N; ++i){
        int it = upper_bound(pos[a[i]].begin(), pos[a[i]].end(), i) - pos[a[i]].begin();

        if(it != (int)pos[a[i]].size()){    // (i,N) に同じ要素があるとき
            doubling[0][i] = pos[a[i]][it] - i + 1;
        }
        else{   // (i,N) に同じ要素がないとき
            doubling[0][i] = (N + pos[a[i]][0]) - i + 1;
        }
    }

    for(int k = 1; k < 60; ++k){
        for(int i = 0; i < N; ++i){
            doubling[k][i] = doubling[k-1][i] + doubling[k-1][(i + doubling[k-1][i]) % N];
        }
    }

    // a[0] から操作を行って、K*N を超えない最大値を調べる。
    ll len = 0;
    bool flag = true;   // 更新フラグ　更新がない時にループを抜けられる
    while(flag){
        ll tmp = 0;
        int p = len % N;    // 現在の位置 (modN)
        flag = false;
        for(int i = 0; i < 60; ++i){
            if(len + doubling[i][p] >= K * N)   break;

            tmp = doubling[i][p];
            flag = true;
        }

        if(flag){
            len += tmp;
        }
    }
    int start = len % N;

    deque<int> deq;
    set<int> s;
    for(int i = start; i < N; ++i){
        if(s.find(a[i]) == s.end()){    // deq 内に a[i] がない場合
            deq.push_back(a[i]);
            s.insert(a[i]);
        }
        else{   // deq 内に a[i] がある場合
            while(!deq.empty()){
                int tmp = deq.back();
                deq.pop_back();
                s.erase(tmp);
                if(tmp == a[i])     break;
            }
        }
    }

    while(!deq.empty()){
        cout << deq.front() << " ";
        deq.pop_front();
    }
    cout << "\n";
}

