#define FOR(i, n, m) for(ll (i)=(m);(i)<(n);++(i))
#define REP(i, n) FOR(i,n,0)
#define OF64 std::setprecision(10)

const ll MOD = 1000000007;
const ll INF = (ll) 1e15;

ll A[200005];
vector<ll> V[200005];
bool U[200005];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N, K;
    cin >> N >> K;
    vector<ll> v;
    REP(i, N) {
        cin >> A[i];
        v.push_back(A[i]);
    }
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    REP(i, v.size()) {
        V[v[i]].push_back(-1);
    }
    REP(i, N) {
        V[A[i]].push_back(i);
    }

    vector<ll> t;
    t.push_back(N);
    ll index = N - 1;
    ll cnt = 1;
    do {
        ll n = A[index];
        auto it = lower_bound(V[n].begin(), V[n].end(), index);
        ll nxt = *(--it);
        if (nxt < 0) {
            cnt++;
            nxt = V[n][V[n].size() - 1];
            t.push_back(nxt);
        }
        index = nxt - 1;
    } while (index >= 0);
    K %= cnt;
    ll s = t[(cnt - K) % cnt];
    deque<ll> ans;
    FOR(i, N, s) {
        ll n = A[i];
        if (U[n]) {
            while (true) {
                ll m = ans.back();
                ans.pop_back();
                if (m == n)
                    break;
            }
            U[n] = false;
            continue;
        }
        U[n] = true;
        ans.push_back(n);
    }

    while (!ans.empty()) {
        ll n = ans.front();
        ans.pop_front();
        cout << n << " ";
    }
    cout << endl;
    return 0;
}

