  int lognk = -1;
  for (int t = nk; t > 0; t >>= 1) lognk++;

  map<int, int> nxt;
  vector<vector<ll>> dbl(lognk + 1, vector<ll>(n, INF));
  for (int i = 2 * n - 1; i >= 0; i--) {
