    map<ll, int> last;
    for(int i = N * 2 - 1; i >= 0; i--) {
        if(i < N) next_index[i] = last[A[i]];
        last[A[i%N]] = i % N;
    }
    //debug(next_index);
    ull left = K * N;
    map<int, int> visited;
    vector<ull> log;
    int now = 0;
    while(left) {
        if(visited.count(now)) {
            // cerr << "LOOP at " << now << endl;
            ull sum = 0;
            repeat(i, visited[now], log.size()) sum += log[i];
            // cerr << "sum = " << sum << " left = " << left << endl;
            left = left % sum;
        }
        int next = next_index[now];
        ull diff = (next <= now ? next + N - now : next - now) + 1;
        if(diff > left) break;
