const ll MOD = 1000000007;
const ll HIGHINF = (ll)1e18;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n, k; cin >> n >> k;
    vll a(n); REP(i, n) cin >> a[i];

    ll nk = n*k;
    map<ll, vll> idxes;
    REP(i, n) idxes[a[i]].push_back(i);

    vll w(n);
    for (auto kv: idxes) {
        ll sz = kv.second.size();
        kv.second.push_back(kv.second[0] + n);
        REP(i, sz) w[kv.second[i]] = kv.second[i+1] - kv.second[i] + 1;  // 次までの距離
    }

    const ll L = 60;
    vvll nx{w};
    REP(_, 60) {
        vll x = nx.back();
        vll y(n);
        REP(i, n) y[i] = min(HIGHINF, x[i]+x[(i+x[i])%n]);
        nx.push_back(y);
    }
    ll cur = 0;
    for (ll i=L; i>=0; i--) {
        if (cur + nx[i][cur%n] <= nk) cur += nx[i][cur%n];
    }
    if (cur == nk) return 0;

    vll ans;
    set<ll> has;
    rep(i, cur%n, n) {
        if (has.count(a[i])) {
            while(1) {
                ll v = ans.back();
                ans.pop_back();
                has.erase(v);
                if (v==a[i]) break;
            }
        } else {
            ans.push_back(a[i]);
            has.insert(a[i]);
        }
    }
    REP(i, ans.size()) cout << ans[i] << (i==ans.size()-1?'\n':' ');
    return 0;
}

