vector<int> brute(vector<int> a, ll k)
{
	int n = a.size();
	vector<int> ans;
	int last2[200111] = {0};

	for(ll j=0; j<n*k; ++j)
	{
		if(last2[a[j%n]])
		{
			int l = last2[a[j%n]]-1;
			for(int i=l; i<ans.size(); ++i)
				last2[ans[i]] = 0;

			ans.resize(l);
		}
		else
		{
			ans.push_back(a[j%n]);
			last2[a[j%n]] = ans.size();
		}
	}

	dprint(ans);
	return ans;
}

