void make_table() {

    for (int i = n * 2 - 1; i >= 0; i--) {
        table[i%n][0] = pre[a[i%n]] - i + 1;
        pre[a[i%n]] = i;
    }

    for (int i = 1; i < 64; i++) {
        for (int j = 0; j < n; j++) {
            table[j][i] = table[j][i-1] + table[(table[j][i-1] + j) % n][i-1];
            table[j][i] = min(table[j][i], (1LL << 61));
        }
    }

}

void solve() {
    make_table();
    ll pos = 0;
    ll left = n * k;
    // for (int i = 0; i < 64; i++) {
    //     for (int j = 0; j < n; j++) {
    //         cout << table[j][i] << " ";
    //     }
    //     cout << endl;
    // }
    while (1) {
        // cout << pos << " " << left << endl;
        bool f = 1;
        for (int i = 63; i >= 0; i--) {
            if (left >= table[pos][i]) {
                left -= table[pos][i];
                pos += table[pos][i];
                pos %= n;
                f = 0;
                break;
            }
        }
        if (f) break;
    }

    for (int i = 0; i < (1 << 19); i++) inque[i] = -1;
    vector<int> dq(1 << 19);
    int pp = 0;
    while (left--) {
        if (inque[a[pos]] == -1) {
            dq[pp] = a[pos];
            inque[a[pos]] = pp;
            pp++;
        } else {
            pp = inque[a[pos]];
            inque[a[pos]] = -1;
        }
        pos++;
        pos %= n;
    }

    for (int i = 0; i < pp; i++) {
        cout << dq[i] << " \n"[i == pp - 1];
    }
}

