void solve() {
    ll AMAX = 2e5 + 1;
    ll N, K;
    cin >> N >> K;
    vector<ll> A(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> A[i];
    }
    vector<ll> pos(AMAX, -1);
    for ( int i = N - 1; i >= 0; i-- ) {
        pos[A[i]] = i;
    }
    vector<ll> offset(N);
    for ( int i = N - 1; i >= 0; i-- ) {
        ll b = pos[A[i]] - i;
        if ( b <= 0 ) b += N;
        offset[i] = b;
        pos[A[i]] = i;
    }
    vector<ll> last(N + 3, -1);  // (k+1)周目で最後に全消しになるp
    ll k = 0;
    ll p = 0; 
    for(;;) {
        p += offset[p];
        if ( p >= N ) {
            p -= N;
            k++;
        }
        last[k] = p;
        if ( p >= N-1 ) {
            break;
        }
        p++;
    }
