    K %= kt;

    if ( K == 0 ) {
        cout << "\n";
        return;
    } else {
        vector<int> X;
        set<int> S;
        k = K - 1;
        while ( last[k] == -1 && k > 0 ) k--;
        p = last[k] + 1;
        for(; k <= K - 1; k++ ) {
            for( ; p < N; p++ ) {
                ll a = A[p];
                if ( S.find(a) == S.end() ) {
                    S.insert(a);
                    X.push_back(a);
                } else {
                    for ( int j = X.size() - 1; j >= 0 ; j-- ) {
                        ll xx = X.back();
                        S.erase(xx);
                        X.pop_back();
                        if ( xx == a ) {
                            break;
                        }
                    }
                }
            }
            p = 0;
        }
        for ( int i = 0; i < X.size(); i++ ) {
            cout << X[i] << " ";
        }
        cout << "\n";
    }
