  int j=search(a[i],i);
  if(df)printf("j:%d->",j,deg[a[i]]);
  if(j==deg[a[i]]-1){
    term++;
    j=0;
  }else j++;
  if(df)printf("j:%d,",j);
  i=map[a[i]][j]+1;
  if(i==n){term++; i=0;}
  if(df)printf("i:%d\n",i);
  accum[len_orbit]=term+1;
  orbit[len_orbit++]=i;
  return i;
}

int search(int t,int i){
  int a=0,b=deg[t]-1;
  if(map[t][b]==i)return b;
  while(b-a>0){
    int c=(a+b)/2;
    if(map[t][c]==i)return c;
    if(map[t][c]<i) a=c;
    else b=c;
  }
  return a;
}


int last_orbit(int t){
  int a=0,b=len_orbit-1;
  while(b-a>1){
    int c=(a+b)/2;
    if(accum[c]<= t)a=c;
    else b=c;
  }
  return orbit[a];
}



