fun pow(A: Array<Int>, k: Long): Array<Int> {
    var R = Array(A.size) { it }
    var B = A
    var l = k

    while (l > 0) {
        if (l and 1 != 0L) {
            R = mul(R, B)
        }
        B = mul(B, B)
        l /= 2
    }

    return R
}

