        int[] naive(int[] a, long kk) {
            int[] res = new int[a.length];
            int j = 0;
            Set<Integer> set = new TreeSet<>();
            while (kk-- > 0) {
                for (int i = 0; i < a.length; i++) {
                    if (set.contains(a[i])) {
                        while (set.contains(a[i])) {
                            set.remove(res[--j]);
                        }
                        continue;
                    }
                    res[j++] = a[i];
                    set.add(a[i]);
                }
//            dump(Arrays.copyOf(res, j));
            }
            return Arrays.copyOf(res, j);
        }

        int[] solve2(int[] a, long k) {
            final int L = 60;
            final int n = a.length;
            k *= n;

            long inf = 1L << 60;
            long[] find = new long[Arrays.stream(a).max().getAsInt() + 1];
            long[][] next = new long[L][n];

            for (int i = 0; i < n; i++) {
                if (find[a[i]] == 0) {
                    find[a[i]] = i + n;
                }
            }

            for (int i = n - 1; i >= 0; i--) {
                next[0][i] = find[a[i]] - i + 1;
                find[a[i]] = i;
            }

            for (int i = 1; i < L; i++) {
                for (int j = 0; j < n; j++) {
                    next[i][j] = Math.min(inf, next[i - 1][j] + next[i - 1][(int) ((j + next[i - 1][j]) % n)]);
                }
            }

            long cur = 0;
            for (int i = L - 1; i >= 0; i--) {
                if (cur + next[i][(int) (cur % n)] <= k) {
                    cur += next[i][(int) (cur % n)];
                }
            }

            int[] ary = Arrays.copyOfRange(a, (int) ((cur - 1) % n + 1), n);
            return naive(ary, 1);
        }

        static void printList(PrintWriter out, int[] p) {
            for (int i = 0; i < p.length; i++) {
                out.print(p[i] + (i == p.length - 1 ? "\n" : " "));
            }
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public long nextLong() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            long ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        public int[] nextIntArray(final int n) {
            final int[] res = new int[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextInt();
            }
            return res;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		long K = sc.nextLong();
		int[] A = new int[N];
		for (int i=0; i<N; i++) {
			A[i] = sc.nextInt();
		}
		sc.close();

		Deque<Integer> queue = new ArrayDeque<>();

		for (long k=0; k<K; k++) {
			for (int n=0; n<N; n++) {
				if (queue.contains(A[n])) {
					while (queue.pop() != A[n]);
				}
				else {
					queue.push(A[n]);
				}
			}
			if (queue.isEmpty()) {
				if (K%(k + 1) == 0) {
					break;
				}
				k = K - K%(k + 1) - 1;
			}
		}

		String ans = "";
		while (!queue.isEmpty()) {
			ans = queue.pop() + " " + ans;
		}
		System.out.println(ans.substring(0, ans.length() - 1));
	}
}

