import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();
        int[] a = new int[n];
        for(int i = 0; i < n; i++) {
            int num = sc.nextInt();
            a[i] = num;
        }
        int count = 1;
        int right = 0;
        int left = 1;
        while(true) {
            int num = a[right];
            while(num != a[left]) {
                left++;
                if(left == n) count++;
                left %= n;
            }
            if(left == n - 1) break;
            right = (left + 1) % n;
            left = (right + 1) % n;
            if(left == 0) count++;
        }
        long num = k % count;
        Stack<Integer> stack = new Stack<>();
        HashSet<Integer> set = new HashSet<>();
        while(num != 0) {
            for(int i: a) {
              if(set.contains(i)) {
                  while(stack.peek() != i) {
                      int s = stack.pop();
                      set.remove(s);
                  }
                  stack.pop();
                  set.remove(i);
              } else {
                  stack.push(i);
                  set.add(i);
              }
            }
            num--;
        }
        for(int i: stack) {
          System.out.print(i + " ");
        }
    }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Main {

  private static void solve() {
    int n = ni();
    long k = nl();
    int[] a = na(n);
    int[] next = new int[n];
    int[] step = new int[n];

    Map<Integer, Integer> pre = new HashMap<>();

    for (int i = 0; i < n * 2; i++) {
      int v = a[i % n];
      if (!pre.containsKey(v)) {
        pre.put(v, i % n);
      } else {
        next[pre.get(v)] = i % n;
        pre.put(v, i % n);
      }
    }

    for (int i = 0; i < n; i++) {
      if (next[i] > i) {
        step[i] = next[i] - i + 1;
      } else {
        step[i] = (n - i) + next[i] + 1;
      }
      next[i] = (next[i] + 1) % n;
    }

    long cycle = 0;
    long cnt = n * k;

    int now = 0;
    while (true) {
      cycle += step[now];
      now = next[now];
      if (now == 0)
        break;
    }
    cnt %= cycle;

    while (step[now] <= cnt) {
      cnt -= step[now];
      now = next[now];
    }

    pre.clear();
    int[] ret = new int[n];
    int ptr = 0;
    for (int i = 0; i < cnt; i++) {
      int idx = (i + now) % n;

      if (pre.containsKey(a[idx])) {
        ptr = pre.get(a[idx]);
        pre.remove(a[idx]);
      } else {
        pre.put(a[idx], ptr);
        ret[ptr++] = a[idx];
      }
    }

    System.err.println(Arrays.toString(next));
    System.err.println(Arrays.toString(step));
    System.err.println(cycle);
    System.err.println(now);
    System.err.println(cnt);

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < ptr; i++) {
      sb.append(ret[i] + " ");
    }
    System.out.println(sb.length() > 0 ? sb.substring(0, sb.length() - 1) : "");
  }

