class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}
	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}
	public boolean hasNext() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
		return hasNextByte();
	}
	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
			throw new NumberFormatException();
		return (int) nl;
	}
	public int[] nextintArray(int n){
		int[] a = new int[n];
		for(int i=0;i<n;i++){
			a[i] = nextInt();
		}
		return a;
	}
	public long[] nextlongArray(int n){
		long[] a = new long[n];
		for(int i=0;i<n;i++){
			a[i] = nextLong();
		}
		return a;
	}
	public Integer[] nextIntegerArray(int n){
		Integer[] a = new Integer[n];
		for(int i=0;i<n;i++){
			a[i] = nextInt();
		}
		return a;
	}
	public int[][] nextintMatrix(int h, int w){
		int[][] mat = new int[h][w];
		for(int i=0;i<h;i++){
			for(int j=0;j<w;j++){
				mat[i][j] = nextInt();
			}
		}
		return mat;
	}
	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.util.*;

public class Main {
    static int maxA = 2 * 100000;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long K = sc.nextLong();
        int[] A = new int[N];

        for (int i = 0; i < N; i++) A[i] = sc.nextInt();

        int[] toNext = new int[N];
        int[] first = new int[maxA + 1];
        int[] last = new int[maxA + 1];
        Arrays.fill(first, -1);
        Arrays.fill(last, -1);

        for (int i = 0; i < N; i++) {
            if (first[A[i]] == -1) {
                first[A[i]] = i;
                last[A[i]] = i;
            } else {
                toNext[last[A[i]]] = i - last[A[i]] + 1;
                last[A[i]] = i;
            }
        }

        for (int i = 0; i < N; i++) {
            if (first[A[i]] != -1) {
                toNext[last[A[i]]] = N - last[A[i]] + first[A[i]] + 1;
            }
        }

        int pos = 0;
        long ops = 0;
        long[] firstVisit = new long[N];
        Arrays.fill(firstVisit, -1);

        while (firstVisit[pos] == -1 && ops + toNext[pos] < N * K) {
            if (firstVisit[pos] != -1) {
                long cycleLength = ops - firstVisit[pos];
                ops += ((N * K - ops) / cycleLength) * cycleLength;

            }
            firstVisit[pos] = ops;
            ops += toNext[pos];
            pos = (pos + toNext[pos]) % N;
        }

        long remainingOps = N * K - ops;

        LinkedList<Integer> sol = new LinkedList<>();
        boolean[] contains = new boolean[maxA + 1];

        for (int i = 0; i < remainingOps; i++) {
            int a = A[(pos + i) % N];
            if (contains[a]) {
                int x = sol.pollLast();
                while (x != a) {
                    contains[x] = false;
                    x = sol.pollLast();
                }
                contains[x] = false;
            } else {
                contains[a] = true;
                sol.addLast(a);
            }
        }

        for (int s : sol) {
            System.out.print(s + " ");
        }
    }
}

