import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.IOException;
import java.lang.NumberFormatException;
import java.util.NoSuchElementException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.Map;
import java.util.Set;
public class Main {
  public static void main(String[] args) {
    Main m = new Main();
    m.run();
  }
  private void run() {
    final FastScanner fs = new FastScanner();
    int n = fs.nextInt();
    long k = fs.nextLong();
    int[] a = new int[n];
    for (int i=0;i<n;i++) a[i] = fs.nextInt();
    Map<Node,Long> indxs = new HashMap<>();
    Map<Long,Node> nodes = new HashMap<>();
    LinkedList<Integer> list = new LinkedList<>();
    Set<Integer> set = new HashSet<>();
    long loop = -1L;
    long chain = -1L;
    indxs.put(new Node(new int[0]),0L);
    nodes.put(0L,new Node(new int[0]));
    for (long x=1L;x<k+1L;x++) {
      for (int i=0;i<n;i++) {
        if (set.contains(a[i])) {
          int v = list.pollLast();
          while (v != a[i]) {
            set.remove(v);
            v = list.pollLast();
          }
          set.remove(a[i]);
        } else {
          list.add(a[i]);
          set.add(a[i]);
        }
      }
      int[] b = new int[list.size()];
      int idx = 0;
      for (Iterator<Integer> it = list.iterator();it.hasNext();) {
        b[idx++] = it.next();
      }
      Node tmp = new Node(b);
      if (indxs.containsKey(tmp)) {
        chain = indxs.get(tmp);
        loop = x-chain;
        break;
      }
      indxs.put(tmp,x);
      nodes.put(x,tmp);
    }
    if (chain >= 0L) k = (k-chain)%loop+chain;
    int[] ans = nodes.get(k).arr;
    if (ans.length > 0) {
      StringBuilder sb = new StringBuilder();
      sb.append(ans[0]);
      for (int i=1;i<ans.length;i++) sb.append(" ").append(ans[i]);
      System.out.print(sb);
    }
    System.out.println();
  }
  private class Node {
    private int[] arr;
    Node(int[] arr) {
      this.arr = arr;
    }
    @Override
    public int hashCode() {
      return Arrays.hashCode(arr);
    }
    @Override
    public boolean equals(Object obj) {
      if (this == obj) return true;
      if (obj == null) return false;
      if (getClass() != obj.getClass()) return false;
      Node other = (Node)obj;
      return Arrays.equals(arr,other.arr);
    }
  }
}
class FastScanner {
  private final InputStream in = System.in;
  private final byte[] buffer = new byte[1024];
  private int ptr = 0;
  private int buflen = 0;
  private boolean hasNextByte() {
    if (ptr < buflen) return true;
    ptr = 0;
    try {
      buflen = in.read(buffer);
    } catch (IOException e) {
      e.printStackTrace();
    }
    if (buflen <= 0) return false;
    return true;
  }
  private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
  private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
  private void skipUnprintable() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}
  public boolean hasNext() { skipUnprintable(); return hasNextByte();}
  public int nextInt() { return (int)nextLong();}
  public String next() {
    if (!hasNext()) throw new NoSuchElementException();
    StringBuilder sb = new StringBuilder();
    int b = readByte();
    while (isPrintableChar(b)) {
      sb.appendCodePoint(b);
      b = readByte();
    }
    return sb.toString();
  }
  public long nextLong() {
    if (!hasNext()) throw new NoSuchElementException();
    long n = 0L;
    boolean minus = false;
    int b = readByte();
    if (b == '-') {
      minus = true;
      b = readByte();
    }
    if (b < '0' || '9' < b) throw new NumberFormatException();
    while(true) {
      if ('0' <= b && b <= '9') {
        n *= 10;
        n += b - '0';
      } else if (b == -1 || !isPrintableChar(b)) {
        return minus ? -n : n;
      } else {
        throw new NumberFormatException();
      }
      b = readByte();
    }
  }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;
import java.math.BigInteger;

public class Main implements Runnable {

	static int mod = 1000000007;

    public static void main(String[] args) {
    	new Thread(null, new Main(), "", 1024 * 1024 * 1024).start();
    }

    public void run() {
        PrintWriter out = new PrintWriter(System.out);
        FastScanner sc = new FastScanner();

        int n = sc.nextInt();
        long k = sc.nextLong();

        int[] a = new int[n];
        int max = 0;

        for(int i=0;i<n;i++){
        	a[i] = sc.nextInt();
        	if(max < a[i]){
        		max = a[i];
        	}
        }

        IDList[] idl = new IDList[max+1];
        for(int i=0;i<max+1;i++){
        	idl[i] = new IDList();
        }

        for(int i=0;i<n;i++){
        	idl[a[i]].add(i);
        }

        ArrayList<Integer> cycle = new ArrayList<>();

        int i = 0;
        loop:while(true){
        	while(aftersize(idl[a[i]],i) %2 == 0){
        		i = idl[a[i]].get(idl[a[i]].size()-1) + 1;
            	if(i==n){
            		break loop;
            	}
        	}

        	//i以降に奇数個
    		cycle.add(a[i]);
    		//System.out.println(a[i]);
    		i = idl[a[i]].get(0)+1;

        	if(i==n){
        		break loop;
        	}
        }

        int csize = cycle.size()+1;

        int maelastid = (int)((k-2)%csize);
        if(maelastid < 0){
        	maelastid += csize;
        }
        int maelast = -1;

        if(maelastid == csize-1){
        	maelast = -1;
        }
        else{
        	maelast = cycle.get(maelastid);
        }

        ArrayList<Integer> ans = new ArrayList<>();

        int id = 0;

        if(maelast != -1){
        	id = idl[maelast].get(0) + 1;
        }

        while(id<n){
        	if(aftersize(idl[a[id]],id) > 1){
        		int from = 0;
        		int to = idl[a[id]].size()-1;
        		int lb = lowerBound(idl[a[id]],id,from,to);
        		id = idl[a[id]].get(lb+1) + 1;
        	}
        	else{
        		ans.add(a[id]);
        		id ++;
        	}
        }

		for(int j=0;j<ans.size()-1;j++){
			out.print(ans.get(j));
			out.print(" ");
		}
		if(ans.size()!=0){
			out.println(ans.get(ans.size()-1));
		}
		else{
			out.println();
		}

        out.flush();
    }

	static void print(ArrayList<Integer> a){
		for(int i=0;i<a.size()-1;i++){
			System.out.print(a.get(i));
			System.out.print(" ");
		}
		System.out.println(a.get(a.size()-1));
	}

    int aftersize(IDList l, int id){
    	int size = l.size();
		int from = 0;
		int to = l.size()-1;
    	int lb = lowerBound(l,id,from,to);

    	return size - lb;
    }

	static int lowerBound(IDList a, long key, int from, int to){
		if(from == to){
			if(a.get(from)<key){
				return from+1;
			}
			else{
				return from;
			}
		}
		int m = (from+to+1)/2;	//オーバーフロー対策なし
		long am = a.get(m);

		if(key<=am){
			return lowerBound(a,key,from,m-1);
		}
		else{
			return lowerBound(a,key,m,to);
		}
	}
}

class IDList extends ArrayList<Integer>{
