import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;
import java.math.BigInteger;

public class Main implements Runnable {

	static int mod = 1000000007;

    public static void main(String[] args) {
    	new Thread(null, new Main(), "", 1024 * 1024 * 1024).start();
    }

    public void run() {
        PrintWriter out = new PrintWriter(System.out);
        FastScanner sc = new FastScanner();

        int n = sc.nextInt();
        long k = sc.nextLong();

        int[] a = sc.nextintArray(n);

        IDList[] idl = new IDList[2*10000+1];
        for(int i=0;i<2*10000+1;i++){
        	idl[i] = new IDList();
        }

        for(int i=0;i<n;i++){
        	idl[a[i]].add(i);
        }

        ArrayList<Integer> cycle = new ArrayList<>();

        int i = 0;
        loop:while(true){
        	while(aftersize(idl[a[i]],i) %2 == 0){
        		i = idl[a[i]].get(idl[a[i]].size()-1) + 1;
            	if(i==n){
            		break loop;
            	}
        	}

        	//i以降に奇数個
    		cycle.add(a[i]);
    		//System.out.println(a[i]);
    		i = idl[a[i]].get(0)+1;

        	if(i==n){
        		break loop;
        	}
        }

        int csize = cycle.size()+1;

        int maelastid = (int)(k-2)%csize;
        if(maelastid < 0){
        	maelastid += csize;
        }
        int maelast = -1;

        if(maelastid == csize-1){
        	maelast = -1;
        }
        else{
        	maelast = cycle.get(maelastid);
        }

        ArrayList<Integer> ans = new ArrayList<>();

        int id = 0;

        if(maelast != -1){
        	id = idl[maelast].get(0) + 1;
        }

        while(id<n){
        	if(aftersize(idl[a[id]],id) > 1){
        		int lb = lowerBound(idl[a[id]],id);
        		id = idl[a[id]].get(lb+1) + 1;
        	}
        	else{
        		ans.add(a[id]);
        		id ++;
        	}
        }

		for(int j=0;j<ans.size()-1;j++){
			out.print(ans.get(j));
			out.print(" ");
		}
		if(ans.size()!=0){
			out.println(ans.get(ans.size()-1));
		}
		else{
			out.println();
		}

        out.flush();
    }

	static void print(ArrayList<Integer> a){
		for(int i=0;i<a.size()-1;i++){
			System.out.print(a.get(i));
			System.out.print(" ");
		}
		System.out.println(a.get(a.size()-1));
	}

    int aftersize(IDList l, int id){
    	int size = l.size();
    	int lb = lowerBound(l,id);

    	return size - lb;
    }

	static int lowerBound(IDList a, int key){
		int idx = Collections.binarySearch(a, key, (x,y)->x.compareTo(y)>=0?1:-1);

		if(idx<0){
			idx = ~idx;
		}

		return idx;
	}
}

