import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		long K = sc.nextLong();
		int[] A = new int[N];
		int[][] B = new int[N][2];
		for (int i = 0; i < N; ++i) {
			A[i] = sc.nextInt();
			B[i] = new int[] { A[i], i };
		}

		Arrays.sort(B, new Comparator<int[]>() {
			@Override
			public int compare(int[] o1, int[] o2) {
				if (o1[0] != o2[0])
					return Integer.compare(o1[0], o2[0]);
				else
					return Integer.compare(o1[1], o2[1]);
			}
		});

		long[][] sum = new long[N][60];
		int[][] dst = new int[N][60];
		for (int i = 0; i < sum.length; ++i)
			for (int j = 0; j < sum[i].length; ++j)
				sum[i][j] = -1;
		for (int i = 0; i < N; ++i) {
			int j = i;
			while (j + 1 < N && B[j][0] == B[j + 1][0]) {
				dst[B[j][1]][0] = (B[j + 1][1] + 1) % N;
				sum[B[j][1]][0] = B[j + 1][1] - B[j][1] + 1;
				++j;
			}
			sum[B[j][1]][0] = N + B[i][1] - B[j][1] + 1;
			dst[B[j][1]][0] = (B[i][1] + 1) % N;
			i = j;
		}
		for (int i = 0; i + 1 < sum[0].length; ++i) {
			for (int j = 0; j < N; ++j) {
				sum[j][i + 1] = sum[j][i] + sum[dst[j][i]][i];
				dst[j][i + 1] = dst[dst[j][i]][i];
			}
		}

		long res = K * N;
		int pos = 0;
		while (res > 0) {
			int p = 59;
			while (p >= 0 && sum[pos][p] > res) {
				--p;
			}
			if (p == -1)
				break;
			res -= sum[pos][p];
			pos = dst[pos][p];
		}

		ArrayDeque<Integer> dq = new ArrayDeque<>();
		while (res > 0) {
			if (res >= sum[pos][0]) {
				res -= sum[pos][0];
				pos += sum[pos][0];
			} else {
				dq.addLast(A[pos]);
				++pos;
				--res;
			}
			pos %= N;
		}
		while (!dq.isEmpty()) {
			System.out.print(dq.poll() + (dq.isEmpty() ? "\n" : " "));
		}
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		long K = sc.nextLong();

		ArrayList<Integer> X = new ArrayList<>();
		ArrayList<Integer> s = new ArrayList<>();

		for (int n = 0; n < N; n++) {
			X.add(sc.nextInt());
		}

		// 最後の全消しの位置を求める
		int now = 0;
		int last = 0;
		for (int i = 0; i < N * K; i++) {
			if (X.get(now) == X.get(i % N)) {
				last = i;
				i++;
				now = X.get(i % N);
			}
		}

		for (int i = last; i < N * K; i++) {
			if (s.isEmpty()) { // sが空なら追加
				s.add(X.get(i % N));
			} else if (s.get(0) == X.get(i % N)) { // sの先頭が一致したら全要素削除
				s.clear();
			} else if (s.contains(X.get(i % N))) { // sが要素を含むあいだ、末尾から削除しつづける
				while (s.contains(X.get(i % N))) {
					s.remove(s.size() - 1);
				}
			} else {
				s.add(X.get(i % N));
			}
		}

		// 出力
		for (

				int i = 0; i < s.size(); i++) {
			System.out.print(s.get(i));
			System.out.print(i == s.size() - 1 ? "\n" : " ");
		}
	}
}

