import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		long K = sc.nextLong();
		int[] A = new int[N];
		int[][] B = new int[N][2];
		for (int i = 0; i < N; ++i) {
			A[i] = sc.nextInt();
			B[i] = new int[] { A[i], i };
		}

		Arrays.sort(B, new Comparator<int[]>() {
			@Override
			public int compare(int[] o1, int[] o2) {
				if (o1[0] != o2[0])
					return Integer.compare(o1[0], o2[0]);
				else
					return Integer.compare(o1[1], o2[1]);
			}
		});

		long[][] sum = new long[N][60];
		int[][] dst = new int[N][60];
		for (int i = 0; i < sum.length; ++i)
			for (int j = 0; j < sum[i].length; ++j)
				sum[i][j] = -1;
		for (int i = 0; i < N; ++i) {
			int j = i;
			while (j + 1 < N && B[j][0] == B[j + 1][0]) {
				dst[B[j][1]][0] = (B[j + 1][1] + 1) % N;
				sum[B[j][1]][0] = B[j + 1][1] - B[j][1] + 1;
				++j;
			}
			sum[B[j][1]][0] = N + B[i][1] - B[j][1] + 1;
			dst[B[j][1]][0] = (B[i][1] + 1) % N;
			i = j;
		}
		for (int i = 0; i + 1 < sum[0].length; ++i) {
			for (int j = 0; j < N; ++j) {
				sum[j][i + 1] = Math.min(sum[j][i] + sum[dst[j][i]][i], Long.MAX_VALUE / 3);
				dst[j][i + 1] = dst[dst[j][i]][i];
			}
		}

		long res = K * N;
		int pos = 0;
		while (res > 0) {
			int p = 59;
			while (p >= 0 && sum[pos][p] > res) {
				--p;
			}
			if (p == -1)
				break;
			res -= sum[pos][p];
			pos = dst[pos][p];
		}

		ArrayDeque<Integer> dq = new ArrayDeque<>();
		while (res > 0) {
			if (res >= sum[pos][0]) {
				res -= sum[pos][0];
				pos += sum[pos][0];
			} else {
				dq.addLast(A[pos]);
				++pos;
				--res;
			}
			pos %= N;
		}
		while (!dq.isEmpty()) {
			System.out.print(dq.pollFirst() + (dq.isEmpty() ? "\n" : " "));
		}
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int N;
    static long K;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        K = sc.nextLong();
        A = sc.nextIntArray(N);

        ArrayDeque<Integer> ans = solve();
        System.out.println( mkString(ans, " ") );
    }

    static <A> String mkString(Collection<A> as, String sep) {
        StringJoiner j = new StringJoiner(sep);
        for (A a : as) {
            j.add(String.valueOf(a));
        }
        return j.toString();
    }

    static ArrayDeque<Integer> solve() {
        // G[i] = j
        // iからstartした場合に次はjからstartする
        int[] G = new int[N];
        int[] dist = new int[N];
        int[] prev = new int[200001];
        Arrays.fill(prev, -1);
        Arrays.fill(G, -1);

        for (int i = 0; i < N*2; i++) {
            int a = A[i%N];
            if( prev[a] != -1 && G[prev[a]] == -1) {
                G[prev[a]] = (i+1)%N;
                dist[prev[a]] = (i+1) - prev[a];
            }
            prev[a] = i%N;
        }

        // どこで一周するか、一周する際にどれだけコストがかかるか
        // 余りのあるloopだったら困るので対応しているがそういう例ってあるのか？
        long totalLen = 0;
        long loopLen = 0;
        boolean[] done = new boolean[N];
        int curr = 0;
        done[0] = true;
        int loopStart;
        while(true) {
            int next = G[curr];
            totalLen += dist[curr];
            if( done[next] ) {
                loopStart = next;
                break;
            }
            curr = next;
        }
        curr = loopStart;
        while(true) {
            int next = G[curr];
            loopLen += dist[curr];
            if( next == loopStart ) break;
            curr = next;
        }
        long amariLen = totalLen - loopLen;

        long r = N*K;
        int idx = 0;
        if( r > amariLen ) {
            r -= amariLen;
            idx = loopStart;
        } else {
            return simulate(idx, G, (int)r);
        }

        r %= loopLen;

        while(true) {
            if( r > dist[idx] ) {
                r -= dist[idx];
                idx = G[idx];
            } else {
                return simulate(idx, G, (int)r);
            }
        }
    }

    static ArrayDeque<Integer> simulate(int start, int[] G, int r) {
        // debug(start, r);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        Set<Integer> set = new HashSet<>();
        int i = start;
        while(r --> 0) {
            int a = A[i++];
            if( set.contains(a) ) {
                while(true) {
                    int last = q.pollLast();
                    set.remove(last);
                    if( a == last ) break;
                }
            } else {
                set.add(a);
                q.addLast(a);
            }
        }
        return q;
    }

