	private static void solve() {
		HashMap<Long, Integer> prev = new HashMap<Long, Integer>();

		int n = ni();
		long k = nl();
		long[] as = nls(n);
		int[] next = new int[n];
		int[] to = new int[n];
		int[] dist = new int[n];
		for (int t = 0; t < n * 2; t++) {
			int i = t % n;
			long v = as[i];
			if (prev.containsKey(v)) {
				int prevI = prev.get(v);
				next[prevI] = i;
			}
			prev.put(v, i);
		}
		for (int i = 0; i < n; i++) {
			dist[i] = ((next[i] - i) % n + n) % n;
			if (dist[i] == 0)
				dist[i] = n;
			dist[i]++;
		}
		for (int i = 0; i < n; i++) {
			to[i] = (next[i] + 1) % n;
		}
		long target = n * k;
//		System.out.println("target=" + target);
//		System.out.println("dist sum=" + distSum);
//		System.out.println("mod target=" + target);

		int[] visited = new int[n];
		for (int i = 0; i < n; i++) {
			visited[i] = -1;
		}
		int idx = 0;
		long left = target;
		int turn = 0;
		boolean skip = true;
		while (true) {
//			System.out.println("visit " + idx);
			if (skip && visited[idx] != -1) {
				int length = turn - visited[idx];
				left %= length;
				skip = false;
//				System.out.println("skipped! mod=" + length);
			}
			if (visited[idx] == -1) {
				visited[idx] = turn;
			}

			int nextIdx = to[idx];
			long cost = dist[idx];
			if (left < cost)
				break;
			left -= cost;
			idx = nextIdx;
			turn += cost;
		}

//		System.out.println("begin sim from " + idx + " " + left + " steps");

		{
			long[] s = new long[n];
			int len = 0;
			int apos = idx;
			HashMap<Long, Integer> pos = new HashMap<Long, Integer>();
			for (int t = 0; t < left; t++) {
				long v = as[apos];
				if (pos.containsKey(v)) {
					int cut = pos.get(v);
					for (int spos = cut; spos < len; spos++) {
						pos.remove(s[spos]);
					}
					len = cut;
				} else {
					pos.put(v, len);
					s[len] = v;
					len++;
				}
				apos = (apos + 1) % n;
			}
			StringBuilder sb = new StringBuilder();
			for (int i = 0; i < len; i++) {
				if (i > 0)
					sb.append(" ");
				sb.append(s[i]);
			}
			out(sb.toString());
		}

