public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            long k = in.readLong();
            int[] a = in.readIntArray(n);
            int[] next = new int[n];
            int[] last = new int[200001];
            for (int i = n - 1; i >= 0; i--) {
                last[a[i]] = i;
            }
            for (int i = n - 1; i >= 0; i--) {
                next[i] = last[a[i]];
                last[a[i]] = i;
            }
            long[] repeats = new long[n];
            Arrays.fill(repeats, -1);
            long current = 0;
            boolean doneRepeats = false;
            int at = 0;
            IntList answer = new IntArrayList();
            while (current < k) {
                repeats[at] = current;
                if (next[at] > at) {
                    at = next[at] + 1;
                } else {
                    if (current == k - 1) {
                        answer.add(a[at]);
                        at++;
                        if (at == n) {
                            at = 0;
                            current++;
                        }
                        continue;
                    }
                    at = next[at] + 1;
                    current++;
                }
                if (at == n) {
                    at = 0;
                    current++;
                }
                if (!doneRepeats && repeats[at] != -1) {
                    long delta = current - repeats[at];
                    long remaining = Math.max(k - 1 - current, 0);
                    long add = remaining / delta;
                    current += add * delta;
                    doneRepeats = true;
                }
            }
            out.printLine(answer);
        }

    }

    static interface IntReversableCollection extends IntCollection {
    }

    static interface IntStream extends Iterable<Integer>, Comparable<IntStream> {
        public IntIterator intIterator();

        default public Iterator<Integer> iterator() {
            return new Iterator<Integer>() {
                private IntIterator it = intIterator();

                public boolean hasNext() {
                    return it.isValid();
                }

                public Integer next() {
                    int result = it.value();
                    it.advance();
                    return result;
                }
            };
        }

        default public int compareTo(IntStream c) {
            IntIterator it = intIterator();
            IntIterator jt = c.intIterator();
            while (it.isValid() && jt.isValid()) {
                int i = it.value();
                int j = jt.value();
                if (i < j) {
                    return -1;
                } else if (i > j) {
                    return 1;
                }
                it.advance();
                jt.advance();
            }
            if (it.isValid()) {
                return 1;
            }
            if (jt.isValid()) {
                return -1;
            }
            return 0;
        }

    }

    static interface IntCollection extends IntStream {
        public int size();

        default public void add(int value) {
            throw new UnsupportedOperationException();
        }

        default public IntCollection addAll(IntStream values) {
            for (IntIterator it = values.intIterator(); it.isValid(); it.advance()) {
                add(it.value());
            }
            return this;
        }

    }

    static interface IntList extends IntReversableCollection {
        public abstract int get(int index);

        public abstract void addAt(int index, int value);

        public abstract void removeAt(int index);

        default public IntIterator intIterator() {
            return new IntIterator() {
                private int at;
                private boolean removed;

                public int value() {
                    if (removed) {
                        throw new IllegalStateException();
                    }
                    return get(at);
                }

                public boolean advance() {
                    at++;
                    removed = false;
                    return isValid();
                }

                public boolean isValid() {
                    return !removed && at < size();
                }

                public void remove() {
                    removeAt(at);
                    at--;
                    removed = true;
                }
            };
        }

        default public void add(int value) {
            addAt(size(), value);
        }

    }

    static interface IntIterator {
        public int value() throws NoSuchElementException;

        public boolean advance();

        public boolean isValid();

    }

