            if (b[nidx + 1] == -1) break;

            cur = a[b[nidx+1]];
            list.add(cur);
        }
        int head = list.get((int)((K - 1) % list.size()));

        int[] result = new int[N];
        boolean[] used = new boolean[MAX];
        int tail = 0;

        if (head != -1) {
            result[tail++] = head;
            used[head] = true;
        }
        for (int i = 0; i < N; i++) {
            if (used[a[i]]) {
                while (true) {
                    int next = result[--tail];
                    used[next] = false;
