            b[a[i]] = i;
        }
        for (int i = n - 1; i >= 0; i--) {
            if (next[i] == n) dp[i] = i;
            else if (next[i] == n - 1) dp[i] = -1;
            else dp[i] = dp[next[i] + 1];
        }
        int [] first = new int[200001];
        Arrays.fill(first, -1);
        for (int i = 0; i < n; i++) {
            if (first[a[i]] == -1) first[a[i]] = i;
