public class Main {

	public static void main(String[] args) {
		new Main();
	}

	public Main() {
		FastIO io = new FastIO();
		solve(io);
		io.flush();
	}

	private static void solve(FastIO io) {
		/*
		 * author: 31536000
		 * AGC036 B問題
		 * 考察メモ
		 * とりあえず、サンプル2
		 * 1
		 * 1 2
		 * 1 2 3
		 * 1
		 * 1 3
		 *
		 * 2
		 * 2 3
		 *
		 * 3
		 * さて、考察
		 * まず、順番が逆転するようなパターンは発生しうるか？
		 * 最初の1回では絶対に発生しない
		 * その後繰り返すとき、最初に出てくる重複文字→最初の文字列でも先頭の位置→全消し、なので発生しない
		 * よって何文字目から読むかと同じように考えることができそう
		 * つまり、スタート位置が変わった文字列が幾つかあるようにすると、これだけでO(N^2)まで落ちる
		 * さて、次の開始文字がどれになるか考えていこう
		 * P1. 1 2 3 2 3 → 1 3 → P2
		 * P2. 2 3 2 3 → 3 →P4
		 * P3. 3 2 3 →  → P1
		 * P4. 2 3 → 2 3 → P3
		 * P5. 3 → 3 → P4
		 * と、先頭の文字だけで次のパターンが確定し、サイクルで巡回するのでこれはグラフ問題になるね
		 * 後はK回回した時、は解けます(戻ってきた時点でmod取りに行くと良い)
		 * 次に、このPへの構築を行うよ(全探索は厳しくない？)
		 * P1はまぁシミュレーションするとして、何か高速化の手法が無いかなぁ
		 * 要はこれ、先頭の文字だけ分かればいいことに注目する → 偶奇が分かればいい
		 * 逆順から見たそれぞれの偶奇の情報及び次に出てくる値の場所の情報からO(N)で求められるよ！
		 * いや嘘だ、1 1 1 1 1 1…が辛い
		 * えーとどうしたものかなぁ、逆順に見て何かできないか
		 * できそう、やってみる
		 *
		 * ほぼできた、なんかコーナーケースっぽいので落ちてるけど概ねできてるね
		 * O(N)でできるみたいで安心、後は細部を確認だ！
		 */
		int INF = Integer.MAX_VALUE;
		int MAX = 200001;
		int N = io.nextInt();
		long K = io.nextLong();
		int[] A = io.nextInt(N);

		int[] next = new int[N + 1]; // next[i]は第i番目の文字から開始するとき、次に遷移するパターン
		int[] first = new int[MAX]; // 各A_iについて、最初に出てくる場所
		Arrays.fill(first, INF);
		for (int i = 0;i < N;++ i) first[A[i]] = Math.min(first[A[i]], i);
		int[] last = new int[MAX]; // 自分より後の奴で最後に出てきた場所のメモ
		Arrays.fill(last, INF);
		next[N] = 0; // 何もない場合、次の候補は最初に戻る
		for (int i = N - 1;i >= 0;-- i) { // O(N)
			if (last[A[i]] == INF) { // まだ見てない→自分が残る！
				next[i] = first[A[i]] + 1; // 自分は消えることに注意
			} else { // その値まで消えた
				next[i] = next[last[A[i]] + 1]; // それの次の値が当然残る
			}
			last[A[i]] = i;
		}
		// さて、nextは出次数1の有向グラフ、あとはこれをK週するだけ
		long[] turn = new long[N + 1]; // turn[i]:第i文字目を開始地点とするパターンにどの時点で訪れたか
		int finalPoint = 0;
		Arrays.fill(turn, Long.MAX_VALUE);
		for (long i = 1;;++ i) { // iは第i回目の操作終了後にいる場所 O(N)
			if (i >= K) break; // 操作終了
			if (turn[finalPoint] != Long.MAX_VALUE) { // もう来た→サイクルなので
				K = (K - i) % (i - turn[finalPoint]) + i;
			}
			turn[finalPoint] = i;
			finalPoint = next[finalPoint]; // 次の移動先
		}
		// この時点で、finalPointを開始点とする文字列に一致することが分かった
		// 後は実際にシミュレーションしちゃえばいいね
		boolean[] use = new boolean[MAX];
		Arrays.fill(use, false);
		ArrayDeque<Integer> deque = new ArrayDeque<Integer>();
		for (;finalPoint < N;++ finalPoint) { // O(N)だよ
			if (!use[A[finalPoint]]) {
				use[A[finalPoint]] = true;
				deque.addLast(A[finalPoint]);
			} else {
				while (use[A[finalPoint]]) use[deque.pollLast()] = false;
			}
		}
		for (int i : deque) io.print(i + " ");
	}

