public class Main {
    static void answer(LinkedList<Long> list){
        int i=0;
        for(long e:list){
            System.out.print(e);
            i++;
            if(i<list.size()) System.out.print(" ");
            else System.out.println();
        }
        System.exit(0);
    }
    static LinkedList<Long> simulate(LinkedList<Long> initial, long[] A, int startIndex){
        Set<Long> set = new HashSet<>();
        for(long e:initial) set.add(e);
        for(int n=startIndex; n<A.length; n++){
            if(!set.contains(A[n])){
                initial.addLast(A[n]);
                set.add(A[n]);
            }
            else{
                while(initial.getLast()!=A[n]){
                    set.remove(initial.getLast());
                    initial.removeLast();
                }
                set.remove(A[n]);
                initial.removeLast();
            }
        }
        return initial;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long K = sc.nextLong();
        long[] A = new long[N];
        for(int n=0; n<N; n++) A[n] = sc.nextLong();

        Map<Long, Long> jump = new HashMap<>();
        {
            Map<Long, Long> lastAppear = new HashMap<>();
            for(int n=0; n<N*2; n++){
                if(lastAppear.containsKey(A[n%N])){
                    jump.putIfAbsent(lastAppear.get(A[n%N]), (long)n);
                }
                lastAppear.put(A[n%N], (long)(n%N));
            }
        }

        for(long a=N-1; a>=0; a--){
            if(jump.containsKey(a) && jump.get(a)<N-1){
                jump.put(a, jump.get(jump.get(a)+1));
            }
        }

        long current = 0;
        Map<Long, Long> visited = new HashMap<>();
        visited.put(0L,0L);
        while(current < N*K){
            long curIndex = current%N;
            if(current >= N * (K-1)){
                answer(simulate(new LinkedList<>(), A, (int)curIndex));
            }
            long next = current - curIndex + jump.get(curIndex) + 1;
            if(next >= N*K) {
                answer(simulate(new LinkedList<>(), A, (int)curIndex));
                break;
            }
            if(visited.containsKey(next%N)){
                long period = next - visited.get(next%N);
                long circ = (N*K-next)/period;
                next += period * circ;
            }
            current = next;
        }
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		long K = sc.nextLong();

		ArrayList<Integer> X = new ArrayList<>();
		ArrayList<Integer> s = new ArrayList<>();

		for (int n = 0; n < N; n++) {
			X.add(sc.nextInt());
			if (X.size() > 1 && X.get(X.size() - 1) == X.get(X.size() - 2)) { // 同じ数字が隣接していれば消す
				X.remove(X.size() - 1);
				X.remove(X.size() - 1);
			}
		}

		// Xが空になら終了
		if(X.isEmpty()) {
			System.exit(0);
		}

		for (int i = 0; i < N * K; i++) {
			if (s.isEmpty()) { // sが空なら追加
				s.add(X.get(i % N));
			} else if (s.get(0) == X.get(i % N)) { // sの先頭が一致したら全要素削除
				s.clear();
			} else if (s.contains(X.get(i % N))) { // sが要素を含むあいだ、末尾から削除しつづける
				while (s.contains(X.get(i % N))) {
					s.remove(s.size() - 1);
				}
			} else {
				s.add(X.get(i % N));
			}

		}

		// 出力
		for (int i = 0; i < s.size(); i++) {
			System.out.print(s.get(i));
			System.out.print(i == s.size() - 1 ? "\n" : " ");
		}
	}
}

