        }

        @Override
        public void run() {
            solve();
        }

        public void solve() {
            int n = io.readInt();
            long k = io.readLong();

            int[] seq = new int[n];
            long[] visit = new long[n];
            Arrays.fill(visit, -1L);
            for (int i = 0; i < n; i++) {
                seq[i] = io.readInt();
            }

            int[] next = new int[n];
            Arrays.fill(next, -1);
            Map<Integer, Integer> indexMap = new HashMap<>(n);
            for (int i = n - 1; i >= 0; i--) {
                if (indexMap.containsKey(seq[i])) {
                    next[i] = indexMap.get(seq[i]);
                }
                indexMap.put(seq[i], i);
            }
            for (int i = n - 1; i >= 0; i--) {
                if (next[i] == -1) {
                    next[i] = indexMap.get(seq[i]);
                }
            }

            long loop = 1;
            int index = 0;
            boolean subed = false;
            while (loop < k) {
                if (visit[index] != -1 && !subed) {
                    long diff = loop - visit[index];
                    long remainLoop = k - loop;
                    long skip = remainLoop / diff;
                    loop += skip * diff;
                    subed = true;
                } else {
                    visit[index] = loop;
                }
                if (loop >= k) {
                    break;
                }
                int nextIndex = next[index];
                if (nextIndex <= index) {
                    loop++;
                }
                index = nextIndex + 1;
                if (index >= n) {
                    index = 0;
                    loop++;
                }
            }

            if (loop > k) {
                return;
            }

            Deque<Integer> deque = new ArrayDeque<>(n);
            Set<Integer> contain = new HashSet<>(n);
            for (int i = index; i < n; i++) {
                Integer e = seq[i];
                if (contain.contains(e)) {
                    contain.remove(e);
                    while (!deque.removeLast().equals(e)) {
                    }
                    continue;
                }
                contain.add(e);
                deque.addLast(e);
            }

            while (!deque.isEmpty()) {
                io.cache.append(deque.removeFirst()).append(' ');
            }
        }
    }

    public static class FastIO {
        public final StringBuilder cache = new StringBuilder(20 << 20);
        private final InputStream is;
        private final OutputStream os;
        private final Charset charset;
        private StringBuilder defaultStringBuf = new StringBuilder(1 << 8);
        private byte[] buf = new byte[1 << 20];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastIO(InputStream is, OutputStream os, Charset charset) {
            this.is = is;
            this.os = os;
            this.charset = charset;
        }

        public FastIO(InputStream is, OutputStream os) {
            this(is, os, Charset.forName("ascii"));
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public long readLong() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            long val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public double readDouble() {
            boolean sign = true;
            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+';
                next = read();
            }

            long val = 0;
            while (next >= '0' && next <= '9') {
                val = val * 10 + next - '0';
                next = read();
            }
            if (next != '.') {
                return sign ? val : -val;
            }
            next = read();
            long radix = 1;
            long point = 0;
            while (next >= '0' && next <= '9') {
                point = point * 10 + next - '0';
                radix = radix * 10;
                next = read();
            }
            double result = val + (double) point / radix;
            return sign ? result : -result;
        }

        public String readString(StringBuilder builder) {
            skipBlank();

            while (next > 32) {
                builder.append((char) next);
                next = read();
            }

            return builder.toString();
        }

        public String readString() {
            defaultStringBuf.setLength(0);
            return readString(defaultStringBuf);
        }

        public int readLine(char[] data, int offset) {
            int originalOffset = offset;
            while (next != -1 && next != '\n') {
                data[offset++] = (char) next;
                next = read();
            }
            return offset - originalOffset;
        }

        public int readString(char[] data, int offset) {
            skipBlank();

            int originalOffset = offset;
            while (next > 32) {
                data[offset++] = (char) next;
                next = read();
            }

            return offset - originalOffset;
        }

        public int readString(byte[] data, int offset) {
            skipBlank();

            int originalOffset = offset;
            while (next > 32) {
                data[offset++] = (byte) next;
                next = read();
            }

            return offset - originalOffset;
        }

        public char readChar() {
            skipBlank();
            char c = (char) next;
            next = read();
            return c;
        }

        public void flush() {
            try {
                os.write(cache.toString().getBytes(charset));
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public boolean hasMore() {
            skipBlank();
            return next != -1;
        }
    }

    public static class Debug {
        private boolean allowDebug;

        public Debug(boolean allowDebug) {
            this.allowDebug = allowDebug;
        }

        public void assertTrue(boolean flag) {
            if (!allowDebug) {
                return;
            }
            if (!flag) {
