        long k=fsc.nextLong()*n-1;
        int[] a=new int[n];
        HashMap<Integer, ArrayList<Integer>> map=new HashMap<>();
        for(int i=0;i<n;i++){
            a[i]=fsc.nextInt();
            if(!map.containsKey(a[i])){
                map.put(a[i], new ArrayList<>());
            }
            map.get(a[i]).add(i);
        }
        fsc.close();
        int[] next=new int[n];
        int[] len=new int[n];
        for(int i=0;i<n;i++){
            List<Integer> list=map.get(a[i]);
            int l=0, r=list.size();
            while(r-l>1){
                int m=l+(r-l)/2;
                if(list.get(m)<=i) l=m;
                else r=m;
            }
            next[i]=list.get((l+1)%list.size());
            if(i<next[i]){
                len[i]=next[i]-i;
            } else{
                len[i]=next[i]-i+n;
            }
        }
