        // }
        // System.out.println();
        int begin=-1, end=-1;
        long loop=-1;
        int now=0;
        boolean[] visit=new boolean[n];
        visit[now]=true;
        long d=0;
        long sub=0;
        while(true){
            int nxt=next[now];
            d+=len[now];
            now=(nxt+1)%n;
            if(!visit[now]){
                d++;
                visit[now]=true;
            } else{
                begin=now;
                end=nxt;
                int nw=0;
                while(true){
                    if(nw==now){
                        break;
                    }
                    int nx=next[nw];
                    sub+=len[nw];
                    nw=(nx+1)%n;
                    sub++;
                }
                loop=d-sub+1;
                break;
            }
        }
        if(n==1){
