        if (head != -1) {
            result[tail++] = head;
            used[head] = true;
        }
        for (int i = 0; i < N; i++) {
            if (used[a[i]]) {
                while (true) {
                    int next = result[--tail];
                    used[next] = false;
                    if (next == a[i]) break;
