    		cyclenum[a[i]] = cycle.size();
    		i = idl[a[i]].get(0)+1;

        	if(i==n){
        		break loop;
        	}
        }

        boolean dame = false;
        if(notSimple){
        	if(k > start){
        		dame = true;
        		k -= (start);
        		k++;
        		ArrayList<Integer> newc = new ArrayList<>();
        		for(int l=start-1;l<cycle.size();l++){
        			newc.add(cycle.get(l));
        		}
        		cycle = newc;
        	}
        }

        int csize = cycle.size()+1;
        if(dame){
        	csize --;
        }

        int maelastid = (int)((k-2)%csize);
        if(maelastid < 0){
        	maelastid += csize;
        	if(dame){
        		maelastid = -1;
        	}
        }
        int maelast = -1;

        if(maelastid == csize-1 && !dame){
        	maelast = -1;
        }
        else if(maelastid == -1){
        	maelast = -1;
        }
        else{
        	maelast = cycle.get(maelastid);
        }

        ArrayList<Integer> ans = new ArrayList<>();

        int id = 0;

        if(maelast != -1){
        	id = idl[maelast].get(0) + 1;
        }

        while(id<n){
        	if(aftersize(idl[a[id]],id) > 1){
        		int from = 0;
        		int to = idl[a[id]].size()-1;
        		int lb = lowerBound(idl[a[id]],id,from,to);
        		id = idl[a[id]].get(lb+1) + 1;
        	}
        	else{
        		ans.add(a[id]);
        		id ++;
        	}
        }

		for(int j=0;j<ans.size()-1;j++){
			out.print(ans.get(j));
			out.print(" ");
		}
		if(ans.size()!=0){
			out.println(ans.get(ans.size()-1));
		}
		else{
			out.println();
		}

        out.flush();
    }

	static void print(ArrayList<Integer> a){
		for(int i=0;i<a.size()-1;i++){
			System.out.print(a.get(i));
			System.out.print(" ");
		}
		System.out.println(a.get(a.size()-1));
	}

    int aftersize(IDList l, int id){
    	int size = l.size();
		int from = 0;
		int to = l.size()-1;
    	int lb = lowerBound(l,id,from,to);

    	return size - lb;
    }

	static int lowerBound(IDList a, long key, int from, int to){
		if(from == to){
			if(a.get(from)<key){
				return from+1;
			}
			else{
				return from;
			}
		}
		int m = (from+to+1)/2;	//オーバーフロー対策なし
		long am = a.get(m);

		if(key<=am){
			return lowerBound(a,key,from,m-1);
		}
		else{
			return lowerBound(a,key,m,to);
		}
	}
}

