public class Main {

	public static void main(String[] args) {
		new Main();
	}

	public Main() {
		FastIO io = new FastIO();
		solve(io);
		io.flush();
	}

	private static void solve(FastIO io) {
		/*
		 * author: 31536000
		 * AGC036 B問題
		 * 考察メモ
		 * とりあえず、サンプル2
		 * 1
		 * 1 2
		 * 1 2 3
		 * 1
		 * 1 3
		 *
		 * 2
		 * 2 3
		 *
		 * 3
		 * さて、考察
		 * まず、順番が逆転するようなパターンは発生しうるか？
		 * 最初の1回では絶対に発生しない
		 * その後繰り返すとき、最初に出てくる重複文字→最初の文字列でも先頭の位置→全消し、なので発生しない
		 * よって何文字目から読むかと同じように考えることができそう
		 * つまり、スタート位置が変わった文字列が幾つかあるようにすると、これだけでO(N^2)まで落ちる
		 * さて、次の開始文字がどれになるか考えていこう
		 * P1. 1 2 3 2 3 → 1 3 → P2
		 * P2. 2 3 2 3 → 3 →P4
		 * P3. 3 2 3 →  → P1
		 * P4. 2 3 → 2 3 → P3
		 * P5. 3 → 3 → P4
		 * と、先頭の文字だけで次のパターンが確定し、サイクルで巡回するのでこれはグラフ問題になるね
		 * 後はK回回した時、は解けます(戻ってきた時点でmod取りに行くと良い)
		 * 次に、このPへの構築を行うよ(全探索は厳しくない？)
		 * P1はまぁシミュレーションするとして、何か高速化の手法が無いかなぁ
		 * 要はこれ、先頭の文字だけ分かればいいことに注目する → 偶奇が分かればいい
		 * 逆順から見たそれぞれの偶奇の情報及び次に出てくる値の場所の情報からO(N)で求められるよ！
		 * いや嘘だ、1 1 1 1 1 1…が辛い
		 * えーとどうしたものかなぁ、逆順に見て何かできないか
		 * できそう、やってみる
		 */
		int INF = Integer.MAX_VALUE;
		int N = io.nextInt();
		long K = io.nextLong();
		int[] A = io.nextInt(N);

		int[] P = new int[N]; // P[i]は第i番目の文字から開始するとき、次に遷移するパターン
		int[] next = new int[N + 1]; // 第i番目の文字について、採用文字
		int[] first = new int[200001]; // 各A_iについて、最初に出てくる場所
		Arrays.fill(first, INF);
		for (int i = 0;i < N;++ i) first[A[i]] = Math.min(first[A[i]], i);
		int[] last = new int[200001]; // 自分より後の奴で最後に出てきた場所のメモ
		Arrays.fill(last, INF);
		next[N] = 0; // 何もない場合、次の候補は最初に戻る
		for (int i = N - 1;i >= 0;-- i) {
			if (last[A[i]] == INF) { // まだ見てない→自分が残る！
				next[i] = first[A[i]] + 1;
			} else { // その値まで消えた
				next[i] = next[last[A[i]] + 1]; // それの次の値が当然残る
			}
			last[A[i]] = i;
		}
		// さて、nextは出次数1の有効グラフ、あとはこれをK週するだけ
		long[] turn = new long[N];
		int finalPoint = 0;
		Arrays.fill(turn, INF);
		for (long i = 1;;++ i) { // iは第i回目の操作終了後にいる場所
			if (i >= K) break;
			if (turn[finalPoint] != INF) { // もう来た
				K = (K - turn[finalPoint]) % (i - turn[finalPoint]) + turn[finalPoint];
			}
			turn[finalPoint] = i;
			finalPoint = next[finalPoint];
		}
		// この時点で、finalPointを開始点とする文字列に一致することが分かった
		// 後は実際にシミュレーションしちゃえばいいね
		boolean[] use = new boolean[200001];
		Arrays.fill(use, false);
		ArrayDeque<Integer> deque = new ArrayDeque<Integer>();
		for (;finalPoint < N;++ finalPoint) {
			if (!use[A[finalPoint]]) {
				use[A[finalPoint]] = true;
				deque.addLast(A[finalPoint]);
			} else {
				while (use[A[finalPoint]]) use[deque.pollLast()] = false;
			}			
		}
		for (int i : deque) io.print(i + " ");
	}

	// 以下、ライブラリ

	public class FastIO {
		private final InputStream in;
		private final byte[] buffer = new byte[1024];
		private int read = 0;
		private int length = 0;
		public final PrintWriter out;
		public final PrintWriter err;

		public FastIO() {
			this(System.in, System.out, System.err);
		}

		public FastIO(InputStream in, PrintStream out, PrintStream err) {
			this.in = in;
			this.out = new PrintWriter(out, false);
			this.err = new PrintWriter(err, false);
		}

		private boolean hasNextByte() {
			if (read < length) return true;
			read = 0;
			try {
				length = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			return length > 0;
		}

		private int readByte() {
			return hasNextByte() ? buffer[read++] : -1;
		}

		private boolean isPrintableChar(int c) {
			return 33 <= c && c <= 126;
		}

		private boolean isNumber(int c) {
			return '0' <= c && c <= '9';
		}

		public boolean hasNext() {
			while (hasNextByte() && !isPrintableChar(buffer[read])) read++;
			return hasNextByte();
		}

		public char nextChar() {
			if (!hasNextByte())  throw new NoSuchElementException();
			return (char)readByte();
		}

		public char[][] nextChar(int height) {
			char[][] ret = new char[height][];
			for (int i = 0;i < ret.length;++ i) ret[i] = next().toCharArray();
			return ret;
		}

		public String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b;
			while (isPrintableChar(b = readByte())) sb.appendCodePoint(b);
			return sb.toString();
		}

		public long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (!isNumber(b)) throw new NumberFormatException();
			while (true) {
				if (isNumber(b)) {
					n *= 10;
					n += b - '0';
				} else if (b == -1 || !isPrintableChar(b)) return minus ? -n : n;
				else throw new NumberFormatException();
				b = readByte();
			}
		}

