public class Main {
  public static void main(String[] args) {
    Main m = new Main();
    m.run();
  }
  private void run() {
    final FastScanner fs = new FastScanner();
    int n = fs.nextInt();
    long k = fs.nextLong();
    int[] a = new int[n];
    for (int i=0;i<n;i++) a[i] = fs.nextInt();
    Map<String,Long> indxs = new HashMap<>();
    Map<Long,String> nodes = new HashMap<>();
    LinkedList<Integer> list = new LinkedList<>();
    Set<Integer> set = new HashSet<>();
    long loop = -1L;
    long chain = -1L;
    indxs.put("",0L);
    nodes.put(0L,"");
    for (long x=1L;x<k+1L;x++) {
      for (int i=0;i<n;i++) {
        if (set.contains(a[i])) {
          int v = list.pollLast();
          while (v != a[i]) {
            set.remove(v);
            v = list.pollLast();
          }
          set.remove(a[i]);
        } else {
          list.add(a[i]);
          set.add(a[i]);
        }
      }
      int[] b = new int[list.size()];
      int idx = 0;
      for (Iterator<Integer> it = list.iterator();it.hasNext();) {
        b[idx++] = it.next();
      }
      String tmp = arrToString(b);
      if (indxs.containsKey(tmp)) {
        chain = indxs.get(tmp);
        loop = x-chain;
        break;
      }
      indxs.put(tmp,x);
      nodes.put(x,tmp);
    }
    if (chain >= 0L) k = (k-chain)%loop+chain;
    System.out.println(nodes.get(k));
  }
  private String arrToString(int[] a) {
    StringBuilder sb = new StringBuilder();
    if (a.length > 0) {
      sb.append(a[0]);
      for (int i=1;i<a.length;i++) sb.append(" ").append(a[i]);
    }
    return sb.toString();
  }
}
class FastScanner {
  private final InputStream in = System.in;
  private final byte[] buffer = new byte[1024];
  private int ptr = 0;
  private int buflen = 0;
  private boolean hasNextByte() {
    if (ptr < buflen) return true;
    ptr = 0;
    try {
      buflen = in.read(buffer);
    } catch (IOException e) {
      e.printStackTrace();
    }
    if (buflen <= 0) return false;
    return true;
  }
  private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
  private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
  private void skipUnprintable() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}
  public boolean hasNext() { skipUnprintable(); return hasNextByte();}
  public int nextInt() { return (int)nextLong();}
  public String next() {
    if (!hasNext()) throw new NoSuchElementException();
    StringBuilder sb = new StringBuilder();
    int b = readByte();
    while (isPrintableChar(b)) {
      sb.appendCodePoint(b);
      b = readByte();
    }
    return sb.toString();
  }
  public long nextLong() {
    if (!hasNext()) throw new NoSuchElementException();
    long n = 0L;
    boolean minus = false;
    int b = readByte();
    if (b == '-') {
      minus = true;
      b = readByte();
    }
    if (b < '0' || '9' < b) throw new NumberFormatException();
    while(true) {
      if ('0' <= b && b <= '9') {
        n *= 10;
        n += b - '0';
      } else if (b == -1 || !isPrintableChar(b)) {
        return minus ? -n : n;
      } else {
        throw new NumberFormatException();
      }
      b = readByte();
    }
  }
}

