/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        B_DoNotDuplicate solver = new B_DoNotDuplicate();
        solver.solve(1, in, out);
        out.close();
    }

    static class B_DoNotDuplicate {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            final int N = (int) (2e5 + 1);
            int n = in.nextInt();
            long k = in.nextLong();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
            }

            int[] whoIsLastIfStartAt = new int[n + 1];
            int[] latest = new int[N + 1];
            Arrays.fill(latest, n);
            whoIsLastIfStartAt[n] = N;
            for (int i = n - 1; i >= 0; i--) {
                int x = a[i];
                if (latest[x] == n) {
                    whoIsLastIfStartAt[i] = x;
                } else {
                    whoIsLastIfStartAt[i] = whoIsLastIfStartAt[latest[x] + 1];
                }
                latest[x] = i;
            }

            int[] whoLeavesIfXEnters = new int[N + 1];
            for (int x = 0; x < N; x++) {
                if (latest[x] == n) {
                    continue;
                }
                int pos = latest[x] + 1;
                whoLeavesIfXEnters[x] = whoIsLastIfStartAt[pos];
            }
            whoLeavesIfXEnters[N] = whoIsLastIfStartAt[0];

            --k;
            int[] seen = new int[N + 1];
            Arrays.fill(seen, -1);
            int cur = N;
            int step;
            for (step = 0; step < k; step++) {
                if (seen[cur] >= 0) {
                    break;
                }
                seen[cur] = step;
                cur = whoLeavesIfXEnters[cur];
            }

            int cycleLength = step - seen[cur];
            long stepsLeft = step == k ? 0 : (k - step) % cycleLength;
            while (stepsLeft > 0) {
                cur = whoLeavesIfXEnters[cur];
                --stepsLeft;
            }

            int pos = Math.min(n, latest[cur] + 1);
            int[] c = simulate(Arrays.copyOfRange(a, pos, n));

            for (int i = 0; i < c.length; i++) {
                if (i > 0) {
                    out.print(" ");
                }
                out.print(c[i]);
            }
            out.println();
        }

        private int[] simulate(int[] a) {
            int[] b = new int[a.length];
            int p = 0;
            Set<Integer> set = new HashSet<>();
            for (int x : a) {
                if (!set.contains(x)) {
                    b[p++] = x;
                    set.add(x);
                } else while (set.contains(x)) {
                    set.remove(b[--p]);
                }
            }
            return Arrays.copyOf(b, p);
        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Main {

  private static void solve() {
    int n = ni();
    long k = nl();
    int[] a = na(n);
    int[] ret = solve(a, k);

    StringBuilder sb = new StringBuilder();
    for (int v : ret) {
      sb.append(v + " ");
    }
    System.out.println(sb.length() > 0 ? sb.substring(0, sb.length() - 1) : "");


  }

  private static int[] solve(int[] a, long k) {
    int n = a.length;
    int[] next = new int[n];
    int[] step = new int[n];

    Map<Integer, Integer> pre = new HashMap<>();
    Arrays.fill(next, -1);
    for (int i = 0; i < n * 2; i++) {
      int v = a[i % n];
      if (!pre.containsKey(v)) {
        pre.put(v, i % n);
      } else if (next[pre.get(v)] < 0) {
        next[pre.get(v)] = i % n;
        pre.put(v, i % n);
      }
    }

    for (int i = 0; i < n; i++) {
      if (next[i] > i) {
        step[i] = next[i] - i + 1;
      } else {
        step[i] = (n - i) + next[i] + 1;
      }
      next[i] = (next[i] + 1) % n;
    }

    long cycle = 0;
    long cnt = n * k;

    int now = 0;
    while (true) {
      cycle += step[now];
      now = next[now];
      if (now == 0)
        break;
    }
    cnt %= cycle;

    while (step[now] <= cnt) {
      cnt -= step[now];
      now = next[now];
    }

    pre.clear();
    int[] ret = sim(a, now, cnt);
    return ret;
  }

  private static int[] sim(int[] a, int offset, long cnt) {
    int n = a.length;
    int now = offset;
    int ptr = 0;
    int[] ret = new int[n];
    Set<Integer> set = new HashSet<>();
    for (int i = 0; i < cnt; i++) {
      int idx = (i + now) % n;

      if (set.contains(a[idx])) {
        while (ptr > 0 && ret[ptr - 1] != a[idx]) {
          ptr--;
          set.remove(ret[ptr]);
        }
        ptr--;
        set.remove(ret[ptr]);

      } else {
        set.add(a[idx]);
        ret[ptr++] = a[idx];
      }
    }
    return Arrays.copyOf(ret, ptr);
  }

