class Program
{
    private int N;
    private long K;
    private int[] A;

    static void Main(string[] args)
    {
        new Program().Solve();
    }

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        K = sc.NextLong();
        A = sc.IntArray();

        var nextIndex = new int[N];
        var map = new Dictionary<int, int>();
        var b = new bool[N];
        for (int i = 0; i < N; i++)
        {
            int o;
            if (map.TryGetValue(A[i], out o))
            {
                nextIndex[o] = i;
                b[o] = true;
            }

            map[A[i]] = i;
        }

        for (int i = 0; i < N; i++)
        {
            int o;
            if (map.TryGetValue(A[i], out o))
            {
                if (!b[o])
                {
                    nextIndex[o] = i + N;
                    b[o] = true;
                }
            }
        }


        int index = 0;
        long cnt = 1;
        bool flag = false;
        while (true)
        {
            int next = nextIndex[index];
            //Console.WriteLine($"{index} {next}");

            if (next >= N)
            {
                cnt++;
                //Console.WriteLine($"I {next}");
            }
            if (next % N == N - 1)
            {
                break;
            }



            index = (next + 1) % N;
        }

        K %= cnt;
        // Console.WriteLine(cnt);
        index = 0;
        cnt = 0;

        if (K == 0)
        {
            Console.WriteLine();
            return;
        }
        while (true)
        {
            int next = nextIndex[index];
            if (next >= N)
            {
                cnt++;
            }

            if (cnt >= K)
            {
                break;
            }

            index = (next + 1) % N;
        }
        // Console.WriteLine(index);
        var stack = new Stack<int>();
        var hs = new HashSet<int>();
        for (int i = index; i < N; i++)
        {
            if (hs.Add(A[i]))
            {
                stack.Push(A[i]);
            }
            else
            {
                while (true)
                {
                    int p = stack.Pop();
                    hs.Remove(p);
                    if (p == A[i])
                    {
                        break;
                    }
                }
            }
        }

        Console.WriteLine(string.Join(" ", hs));
    }
}

class Scanner
