using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int n = int.Parse(input[0]);
		long k = long.Parse(input[1]);
		int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
    int[] turns = new int[n];//それぞれの数のターン
    int a = 200001;
    List<int>[] positionList = new List<int>[a];
    for(int i = 0; i < a; i++) positionList[i] = new List<int>();
    int[] numsCount = new int[a];
    int[] numsNumber = new int[n];//それぞれの数は、何番目-1に出たものか

    for(int i = 0; i < n; i++)
    {
      positionList[nums[i]-1].Add(i);
      numsNumber[i] = numsCount[nums[i]-1];
      numsCount[nums[i]-1]++;
    }

    int lookingPosition = 0;
    int nowTurn = 1;
    while(true)
    {
      if(positionList[nums[lookingPosition]-1][positionList[nums[lookingPosition]-1].Count()-1]
        == lookingPosition)
      {
        nowTurn++;
        turns[lookingPosition] = nowTurn;
        lookingPosition = positionList[nums[lookingPosition]-1][0]+1;
        if(lookingPosition == n) break;
      }else
      {
        turns[lookingPosition] = nowTurn;
        lookingPosition 
          = positionList[nums[lookingPosition]-1][numsNumber[lookingPosition]+1]+1;
        if(lookingPosition == n) break;
      }
    }

    k %= nowTurn;

    int leftPosition = 0;
    for(int i = 0; i < n; i++)
    {
      if(turns[i] == k)
      {
        if(numsNumber[i] != numsCount[nums[i]-1]-1)
        {
          leftPosition = positionList[nums[i]-1][numsNumber[i]+1]+1;
        }else leftPosition = positionList[nums[i]-1][0]+1;
      }
    }

    var stack = new Stack<int>();
    bool[] used = new bool[a];
    for(int i = leftPosition; i < n; i++)
    {
      if(!used[nums[i]])
      {
        stack.Push(nums[i]);
        used[nums[i]] = true;
      }else
      {
        while(true)
        {
          int topMemo = stack.Peek();
          used[topMemo] = false;
          stack.Pop();
          if(topMemo == nums[i]) break;
        }
      }
    }

    int aa = stack.Count;
    int[] answers = new int[aa];
    for(int i = 0; i < aa; i++)
    {
      int popMemo = stack.Peek();
      answers[aa-1-i] = popMemo;
      stack.Pop();
    }

		Console.WriteLine(string.Join(" ", answers));
	}
}

using System;
using System.Linq;
using System.Collections.Generic;
class ProgramB
    {
        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            int n = int.Parse(input[0]);
            long k = long.Parse(input[1]);

            var a_array = new List<int>();
            var s = new List<int>();
            string[] input_a = Console.ReadLine().Split(' ');
            for(int i = 0; i < n;i++)
            {
                int a = int.Parse(input_a[i]);
                a_array.Add(a);
            }

            int count = 0;

            do
            {
                for(int i = 0 ;i < n;i++)
                {
                    if(s.IndexOf(a_array[i]) == -1)
                        s.Add(a_array[i]);
                    else
                        s.RemoveRange(s.IndexOf(a_array[i]),s.Count()- s.IndexOf(a_array[i]));
                }
                count++;
                if(k == count)
                    break;
            } while(s.Count() != 0);

            if(k == count)
            {
                for(int i = 0; i < s.Count(); i++)
                {
                   Console.Write(s[i]);
                   Console.Write(" ");
                }
            }
            else
            {
                int c2 = (int)(k % count);
                for(int j = 0;j < c2;j++)
                {
                    for(int i = 0 ;i < n;i++)
                    {
                        if(s.IndexOf(a_array[i]) == -1)
                            s.Add(a_array[i]);
                        else
                            s.RemoveRange(s.IndexOf(a_array[i]),s.Count()- s.IndexOf(a_array[i]));
                    }
                }
                for(int i = 0; i < s.Count(); i++)
                {
                   Console.Write(s[i]);
                   Console.Write(" ");
                }
            }
        }
    }

