using System;
using System.Collections.Generic;

namespace ConsoleApp1
{
    class Program
    {

        static int Search(List<int> indexes, int startindex)
        {
            int last = indexes[indexes.Count - 1];
            if (startindex >= last)
            {
                return indexes[0];
            }
            else
            {
                return indexes[indexes.FindIndex(x => x == startindex) + 1];
            }
        }

        static void Main(string[] args)
        {
            var s = Console.ReadLine().Split(' ');
            int n = int.Parse(s[0]);
            long k = long.Parse(s[1]);
            int[] a = new int[n];
            var tempamap = new Dictionary<int, List<int>>();
            var amap = new Dictionary<int, int[]>();
            var ss = Console.ReadLine().Split(' ');
            for (int i = 0; i < n; i++)
            {
                a[i] = int.Parse(ss[i]);
                if (tempamap.ContainsKey(a[i]))
                {
                    tempamap[a[i]].Add(i);
                }
                else
                {
                    var temp = new List<int>();
                    temp.Add(i);
                    tempamap.Add(a[i], temp);
                }
            }
            // 先頭の推移をみる
            int topindex = 0;
            int linecount = 0;
            int count = 0;
            int[] topindexes = new int[n];
            int[] linecounts = new int[n];
            int nexttopindex = Search(tempamap[a[topindex]], topindex) + 1;
            if (nexttopindex == n)
            {
                nexttopindex = 0;
            }
            if (nexttopindex <= topindex + 1)
            {
                linecount++;
            }
            bool hasfinished = false;
            int finaltopindex = -1;
            if (linecount >= k)
            {
                hasfinished = true;
                finaltopindex = 0;
            }
            count++;
            topindexes[count] = nexttopindex;
            linecounts[count] = linecount;
            topindex = nexttopindex;
            while (topindex != 0 && linecount < k)
            {
                nexttopindex = Search(tempamap[a[topindex]], topindex) + 1;
                if (nexttopindex == n)
                {
                    nexttopindex = 0;
                }
                if (nexttopindex <= topindex + 1)
                {
                    linecount++;
                }
                if (nexttopindex != 0)
                {
                    count++;
                    topindexes[count] = nexttopindex;
                    linecounts[count] = linecount;
                }
                if (linecount == k)
                {
                    hasfinished = true;
                    break;
                }
                topindex = nexttopindex;
            }
            if (finaltopindex < 0)
            {
                finaltopindex = topindex;
            }
            if (!hasfinished)
            {
                int leftline = (int)(k % linecount);
                finaltopindex = topindexes[Array.FindLastIndex(linecounts, x => x == leftline - 1 || x == leftline - 1 + linecount)];
            }
            // finaltopindexを含めてそこからの数列を作る
            var lasta = new List<int>();
            for (int i = finaltopindex; i < n; i++)
            {
                if (lasta.Contains(a[i]))
                {
                    int remindex = lasta.FindIndex(x => x == a[i]);
                    lasta.RemoveRange(remindex, lasta.Count - remindex);
                }
                else
                {
                    lasta.Add(a[i]);
                }
            }
            Console.WriteLine(string.Join(" ", lasta));


#if DEBUG
            Console.ReadKey();
#endif
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Numerics;
using System.Runtime.CompilerServices;
using System.Text;
using System.Threading.Tasks;

namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			var cin = new Scanner2();
			int n = cin.Int();
			long k = cin.Long();
			var a = cin.ArrayInt(n);

			long max = n * k;
			int maxLog = 0;
			long temp = max;
			while (temp > 1) {
				++maxLog;
				temp /= 2;
			}

			var dub = new long[maxLog + 1, n];
			for (int i = 0; i < maxLog + 1; i++) {
				for (int j = 0; j < n; j++) {
					dub[i, j] = -1;
				}
			}

			var dic = new Dictionary<int, int>();
			for (int i = 0; i < n * 2; i++) {
				int target = i % n;
				if (dic.ContainsKey(a[target]) == false) {
					dic[a[target]] = i;
				} else {
					if (dub[0, dic[a[target]] % n] == -1) {
						dub[0, dic[a[target]] % n] = i + 1 - dic[a[target]];
					}
					dic[a[target]] = i;
				}
			}

			for (int i = 1; i < maxLog + 1; i++) {
				for (int j = 0; j < n; j++) {
					if (dub[i - 1, j] >= 0 && dub[i - 1, (j + dub[i - 1, j]) % n] >= 0) {
						dub[i, j] = dub[i - 1, (j + dub[i - 1, j]) % n] + dub[i - 1, j];
					}
				}
			}

			var ans = new List<int>();
			long cnt = 0;
			int index = 0;
			while (cnt < max) {
				for (int i = maxLog; i >= 0; i--) {
					if (dub[i, index] > 0 && dub[i, index] + cnt > 0) {
						if (dub[i, index] + cnt == max) {
							cnt = max;
							break;
						} else if (dub[i, index] + cnt < max) {
							cnt += dub[i, index];
							index = (int)(cnt % n);
							break;
						}
					}

					if (i == 0) {
						ans.Add(a[index]);
						++index;
						++cnt;
						break;
					}
				}
			}

			if (ans.Count == 0) {
				Console.WriteLine("");
			} else {
				Console.WriteLine(string.Join(" ", ans));
			}
		}
	}

	public static class Helper
	{
		public static void UpdateMin32<T>(T array, int index, int value) where T : IList<int>
			=> array[index] = Math.Min(array[index], value);
		public static void UpdateMax32<T>(T array, int index, int value) where T : IList<int>
			=> array[index] = Math.Max(array[index], value);
		public static void UpdateMin64<T>(T array, int index, long value) where T : IList<long>
			=> array[index] = Math.Min(array[index], value);
		public static void UpdateMax64<T>(T array, int index, long value) where T : IList<long>
			=> array[index] = Math.Max(array[index], value);

		public static T[] Array<T>(int n, Func<int, T> init)
			=> Enumerable.Range(0, n).Select(x => init(x)).ToArray();
		public static List<T> List<T>(int n, Func<int, T> init)
			=> Enumerable.Range(0, n).Select(x => init(x)).ToList();
	}

	public class Scanner2
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private readonly Func<string> reader_;
		private string[] buf_;
		private int index_;

		public Scanner2(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}
}

