namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			var cin = new Scanner2();
			int n = cin.Int();
			long k = cin.Long();
			var a = cin.ArrayInt(n);

			var aa = new List<int>(n * 2);
			aa.AddRange(a);
			aa.AddRange(a);

			long max = n * k;
			int maxLog = 0;
			long temp = max;
			while (temp > 1) {
				++maxLog;
				temp /= 2;
			}

			var dub = new long[maxLog + 1, n];
			for (int i = 0; i < maxLog + 1; i++) {
				for (int j = 0; j < n; j++) {
					dub[i, j] = -1;
				}
			}

			var dic = new Dictionary<int, int>();
			for (int i = 0; i < n * 2; i++) {
				int target = i % n;
				if (dic.ContainsKey(aa[target]) == false) {
					dic[aa[target]] = i;
				} else {
					if (dub[0, dic[aa[target]] % n] == -1) {
						dub[0, dic[aa[target]] % n] = i + 1 - dic[aa[target]];
					}
					dic[aa[target]] = i;
				}
			}

			for (int i = 1; i < maxLog + 1; i++) {
				for (int j = 0; j < n; j++) {
					if (dub[i - 1, j] >= 0 && dub[i - 1, (j + dub[i - 1, j]) % n] >= 0) {
						dub[i, j] = dub[i - 1, (j + dub[i - 1, j]) % n] + dub[i - 1, j];
					}
				}
			}

			var ans = new List<int>();
			long cnt = 0;
			int index = 0;
			while (cnt < max) {
				for (int i = maxLog; i >= 0; i--) {
					if (dub[i, index] != -1) {
						if (dub[i, index] + cnt == max) {
							cnt = max;
							break;
						} else if (dub[i, index] + cnt < max) {
							cnt += dub[i, index];
							index = (int)(cnt % n);
							break;
						}
					}

					if (i == 0) {
						ans.Add(a[index]);
						++index;
						++cnt;
						break;
					}
				}
			}

			if (ans.Count == 0) {
				Console.WriteLine("");
			} else {
				Console.WriteLine(string.Join(" ", ans));
			}
		}
	}

