public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		long K = GetLong();
		var A = GetLongs(N);

		var g = new long[60, N];
		for(long i = 0; i < N; i++)
			g[0, i] = -1;

		var idx = Range(0, 202020).Select(_ => new List<long>()).ToArray();
		for(long i = 0; i < 2 * N; i++)
		{
			long X = A[i % N];
			if(idx[X].Count > 0 && g[0, idx[X].Last() % N] == -1)
				g[0, idx[X].Last() % N] = i - idx[X].Last() + 1;

			idx[X].Add(i);
		}

		long INF = long.MaxValue / 2;
		for(long k = 1; k < 60; k++)
		{
			for(long i = 0; i < N; i++)
				g[k, i] = Min(INF, g[k - 1, i] + g[k - 1, (i + g[k - 1, i]) % N]);
		}

		long pos = 0;
		while(true)
		{
			long cand = -1;
			for(long k = 0; k < 60; k++)
			{
				if(pos + g[k, pos % N] >= N * K)
					break;
				else
					cand = k;
			}
			if(cand == -1)
				break;

			pos += g[cand, pos % N];
		}

		WriteLine(string.Join(" ", sim(N, K, A, pos)));
	}

	private List<long> sim(long N, long K, long[] A, long pos)
	{
		var res = new List<long>();
		var set = new HashSet<long>();
		for(long i = pos; i < N * K; i++)
		{
			long x = A[i % N];
			if(set.Contains(x))
			{
				while(set.Contains(x))
				{
					set.Remove(res.Last());
					res.RemoveAt(res.Count - 1);
				}
			}
			else
			{
				set.Add(x);
				res.Add(x);
			}
		}
		return res;
	}
}

