    {
        int n = ri, k = ri;
        List<int> a = new List<int>();
        int t = -1;
        for (int i = 0; i < n; i++)
        {
            a.Add(ri);
            if (t > -1 && a[a.Count - 1] != a[a.Count - 2])
            {
                a.RemoveRange(t, a.Count - t - 2);
            }
            else if (t == -1 && a.Count > 1 && a[a.Count - 1] == a[a.Count - 2])
            {
                t = a.Count - 2;
            }
        }
        n = a.Count;
        List<int> s = new List<int>();
        string[] ss = new string[n+1];
        int m = n;
        for (int j=0;j<m;j++) {
            for (int i = 0; i < n; i++)
            {
                t = s.IndexOf(a[i]);
                if (t > -1)
                {
                    s.RemoveRange(t, s.Count - t);
                }
                else
                {
                    s.Add(a[i]);
                }
            }
            ss[j+1] = string.Join(" ", s);
            if (!s.Any()) { m = j + 1; }
        }
        Write(ss[k%m]);
    }

