    class Mod
    {
        readonly int _divider = 1000000007;
        public Mod(int divider = 1000000007)
        {
            _divider = divider;
        }

        public int Add(int a, int b) => (int)Add((long)a, (long)b);
        public int Sub(int a, int b) => (int)Sub((long)a, (long)b);
        public int Mul(int a, int b) => (int)Mul((long)a, (long)b);
        public int Div(int a, int b) => (int)Div((long)a, (long)b);
        public int Pow(int a, int p) => (int)Pow((long)a, (long)p);

        public long Add(long a, long b) => (a + b) % _divider;

        public long Sub(long a, long b)
        {
            var t = (a - b) % _divider;
            if (t < 0)
                t += _divider;
            return t;
        }

        public long Mul(long a, long b) => (a * b) % _divider;

        public long Div(long a, long b) => Mul(a, Inv(b));

        public long Pow(long a, long p)
        {
            switch (p)
            {
                case 0: return 1;
                case 1: return a;
                default:
                    var halfP = p / 2;
                    var halfPowered = Pow(a, halfP);
                    var powered = Mul(halfPowered, halfPowered);
                    return p % 2 == 0 ? powered : Mul(powered, a);
            }
        }

        readonly Dictionary<long, long> invCache = new Dictionary<long, long>();
        long Inv(long a)
        {
            long cache = 0L;
            if (invCache.TryGetValue(a, out cache))
                return cache;

            var result = Pow(a, _divider - 2);
            invCache.Add(a, result);
            return result;
        }

        readonly List<int> facCache = new List<int>() { 1 };
        public int Fac(int a)
        {
            if (a < facCache.Count)
                return facCache[a];

            var val = facCache.Last();
            var start = facCache.Count;
            for (int i = start; i <= a; i++)
            {
                val = Mul(val, i);
                facCache.Add(val);
            }

            return val;
        }

        public int Perm(int n, int r)
        {
            if (n < r)
                return 0;

            if (r <= 0)
                return 1;

            int nn = Fac(n);
            int nr = Fac(n - r);
            return Div(nn, nr);
        }

        public int Comb(int n, int r)
        {
            if (n < r)
                return 0;

            if (n == r)
                return 1;

            int nn = Fac(n);
            int nr = Fac(n - r);
            int rr = Fac(r);
            return Div(Div(nn, nr), rr);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Diagnostics;

public class Solution
{
    public static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        var N = (int)vals[0];
        var K = vals[1];
        var A = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var sw = Stopwatch.StartNew();
        var max = (int)Math.Log(K, 2) + 1;
        var AA = A.Concat(A).ToArray();
        // nexts[j][i] : iから2^j分先のAに移動した位置

        var next = new int[N];
        var indexs = new Dictionary<int, int>(); // a -> index
        for (int i = 0; i < N * 2; i++)
        {
            var a = AA[i];
            if (indexs.ContainsKey(a))
            {
                var prev = indexs[a];
                if (prev < N)
                {
                    next[prev] = i + 1;
                }
            }
            indexs[a] = i;
        }
        for (int i = N - 1; i >= 0; i--)
        {
            while (next[i] < N)
            {
                next[i] = next[next[i]];
            }
        }
        for (int i = 0; i < N; i++)
        {
            next[i] %= N;
        }

        var nexts = new int[max][];
        nexts[0] = next;
        for (int j = 1; j < max; j++)
        {
            nexts[j] = new int[N];
            for (int i = 0; i < N; i++)
            {
                var t = nexts[j - 1][i];
                nexts[j][i] = nexts[j - 1][t];
            }
        }

        var p = 0;
        for (var k = K - 1; k > 0;)
        {
            var log = (int)Math.Log(k, 2);
            p = nexts[log][p];
            k -= (long)Math.Pow(2, log);
        }

        var list = new List<int>();
        indexs.Clear();
        for (; p < N; p++)
        {
            var a = A[p];
            if (!indexs.ContainsKey(a))
            {
                indexs[a] = list.Count;
                list.Add(a);
            }
            else
            {
                var index = indexs[a];
                foreach (var aa in list.Skip(index))
                {
                    indexs.Remove(aa);
                }
                list.RemoveRange(index, list.Count - index);
            }
        }

        Console.WriteLine(string.Join(" ", list));
    }
}

