        public IEnumerable<string> Solve()
        {
            var n = ScanInt;
            var k = Scan;
            var a = ScanLongs(n);
            var nexts = Loop((int)n).Select(_ => -1).ToArray();
            var tails = Loop(200001).Select(_ => -1).ToArray();

            {
                var memoCount = 0;
                var pointer = 0;
                while (memoCount < n)
                {
                    var aa = a[pointer];

                    if (tails[aa] >= 0 && nexts[tails[aa]] < 0)
                    {
                        nexts[tails[aa]] = (pointer + 1) % n;
                        memoCount++;
                    }

                    tails[aa] = pointer;

                    pointer++;
                    pointer %= n;
                }
            }


            var mod = 0;
            {
                var pointer = 0;
                do
                {
                    var t = nexts[pointer];
                    if (pointer >= t - 1)
                        mod++;
                    pointer = t;
                }
                while (pointer != 0);
            }

            {
                var current = 0;
                var kk = (k - 1) % mod;
                var pointer = 0;
                do
                {
                    var t = nexts[pointer];
                    if (pointer >= t - 1)
                    {
                        if (current >= kk)
                            break;

                        current++;
                    }
                    pointer = t;
                }
                while (true);

                var res = new List<long>();
                var memo = new Dictionary<long, int>();
                var tail = -1;

                for (int i = pointer; i < n; i++)
                {
                    var aa = a[i];
                    if (memo.ContainsKey(aa) && memo[aa] >= 0)
                    {
                        tail = memo[aa] - 1;
                        memo[aa] = -1;
                    }
                    else
                    {
                        tail++;
                        if (tail < memo.Count)
                            res[tail] = aa;
                        else
                            res.Add(aa);
                        memo[aa] = tail;
                    }
                }

                yield return string.Join(" ", res.Take(tail + 1));

            }
        }
    }

