            }

            return low;
        }
    }

    class Mod
    {
        readonly int _divider = 1000000007;
        public Mod(int divider = 1000000007)
        {
            _divider = divider;
        }

        public int Add(int a, int b) => (int)Add((long)a, (long)b);
        public int Sub(int a, int b) => (int)Sub((long)a, (long)b);
        public int Mul(int a, int b) => (int)Mul((long)a, (long)b);
        public int Div(int a, int b) => (int)Div((long)a, (long)b);
        public int Pow(int a, int p) => (int)Pow((long)a, (long)p);

        public long Add(long a, long b) => (a + b) % _divider;

        public long Sub(long a, long b)
        {
            var t = (a - b) % _divider;
            if (t < 0)
                t += _divider;
            return t;
        }

        public long Mul(long a, long b) => (a * b) % _divider;

        public long Div(long a, long b) => Mul(a, Inv(b));

        public long Pow(long a, long p)
        {
            switch (p)
            {
                case 0: return 1;
                case 1: return a;
                default:
                    var halfP = p / 2;
                    var halfPowered = Pow(a, halfP);
                    var powered = Mul(halfPowered, halfPowered);
                    return p % 2 == 0 ? powered : Mul(powered, a);
            }
        }

        readonly Dictionary<long, long> invCache = new Dictionary<long, long>();
        long Inv(long a)
        {
            long cache = 0L;
            if (invCache.TryGetValue(a, out cache))
                return cache;

            var result = Pow(a, _divider - 2);
            invCache.Add(a, result);
            return result;
        }

        readonly List<int> facCache = new List<int>() { 1 };
        public int Fac(int a)
        {
            if (a < facCache.Count)
                return facCache[a];

            var val = facCache.Last();
            var start = facCache.Count;
            for (int i = start; i <= a; i++)
            {
                val = Mul(val, i);
                facCache.Add(val);
            }

            return val;
        }

        public int Perm(int n, int r)
        {
            if (n < r)
                return 0;

            if (r <= 0)
                return 1;

            int nn = Fac(n);
            int nr = Fac(n - r);
            return Div(nn, nr);
        }

        public int Comb(int n, int r)
        {
            if (n < r)
                return 0;

            if (n == r)
                return 1;

            int nn = Fac(n);
            int nr = Fac(n - r);
            int rr = Fac(r);
            return Div(Div(nn, nr), rr);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Text.RegularExpressions;
namespace AGC036B
{
    class Program
    {
        static void Main(string[] args)
        {
            var matches = Regex.Matches(Console.ReadLine(), "[0-9]+");
            var N = long.Parse(matches[0].Value);
            var K = long.Parse(matches[1].Value);
            var A = Regex.Matches(Console.ReadLine(), "[0-9]+").Cast<Match>().Select(item=>int.Parse(item.Value)).ToList();
            var footprints = new List<List<int>>();

            var state = new List<int>();
             long repeatIndex = 0;
            long lastIndex = 0;
            bool find = false;

            for(long i = 0; i < K; i++)
            {
                foreach (var item in A)
                {
                    if (state.Contains(item)) state = state.TakeWhile(it => it != item).ToList();
                    else state.Add(item);
                }
                var c = 0;

                foreach (var f in footprints)
                {
                    if (Check(f, state)) { repeatIndex = c;lastIndex = i; find = true; goto AFTER; }
                    c++;
                }
                if (find) break;
                footprints.Add(state.Select(p=>p).ToList());
            }
            AFTER:
            if (find)
            {
                state = footprints[(int)((K - 1 - repeatIndex) % (lastIndex - repeatIndex) + repeatIndex)];
            }
            Console.WriteLine(string.Join(" ", state));
        }
        static bool Check(List<int> r, List<int> l)
        {
            var n = r.Count;
            if (l.Count != n) return false;
            for (var i = 0; i < n; i++)
            {
                if (r[i] != l[i]) return false;
            }
            return true;
        }

    }
}

