namespace Program
{
    public static class AGC036B
    {
        static public void Solve()
        {
            var N = NN;
            var K = NN;
            var AList = NNList(N);

            var dblCnt = (long)(Log(N * K) / Log(2)) + 1;

            var gotoTable = new long[N, dblCnt];
            var gotoCount = new long[N, dblCnt];
            var colorTable = new long?[200001];
            for (var i = 0; i < N * 2; i++)
            {
                var num = AList[i % N];
                if (colorTable[num].HasValue)
                {
                    gotoTable[colorTable[num].Value, 0] = (i + 1) % N;
                    gotoCount[colorTable[num].Value, 0] = i + 1 - colorTable[num].Value;
                    colorTable[num] = null;
                }
                if (i < N)
                {
                    colorTable[num] = i;
                }
            }

            for (var i = 1; i < dblCnt; i++)
            {
                var ok = true;
                for (var j = 0; j < N; j++)
                {
                    gotoTable[j, i] = gotoTable[gotoTable[j, i - 1], i - 1];
                    gotoCount[j, i] = gotoCount[gotoTable[j, i - 1], i - 1] + gotoCount[j, i - 1];
                    if (gotoCount[j, i] > 1000000000000000000)
                    {
                        ok = false;
                        break;
                    }
                }
                if (!ok)
                {
                    dblCnt = i;
                    break;
                }
            }

            var nowPoint = 0L;
            var nowDist = 0L;
            for (var i = dblCnt - 1; i >= 0; i--)
            {
                while (nowDist + gotoCount[nowPoint, i] < N * K)
                {
                    nowDist += gotoCount[nowPoint, i];
                    nowPoint = gotoTable[nowPoint, i];
                }
            }
            var outNum = new long[N];
            var idx = 0L;
            var colorTable2 = new long?[200001];
            for (var i = nowDist; i < N * K; i++)
            {
                var num = AList[i % N];
                if (colorTable2[num].HasValue && colorTable2[num] < idx)
                {
                    idx = colorTable2[num].Value;
                }
                else
                {
                    colorTable2[outNum[idx]] = null;
                    outNum[idx] = num;
                    colorTable2[num] = idx;
                    ++idx;
                }
            }

            var first = true;
            for (var i = 0; i < idx; i++)
            {
                if (!first) Console.Write(" ");
                first = false;
                Console.Write(outNum[i]);
            }
            Console.WriteLine();
        }

