                return indexes[indexes.FindIndex(x => x == startindex) + 1];
            }
        }

        static void Main(string[] args)
        {
            var s = Console.ReadLine().Split(' ');
            int n = int.Parse(s[0]);
            long k = long.Parse(s[1]);
            int[] a = new int[n];
            var tempamap = new Dictionary<int, List<int>>();
            var amap = new Dictionary<int, int[]>();
            var ss = Console.ReadLine().Split(' ');
            for (int i = 0; i < n; i++)
            {
                a[i] = int.Parse(ss[i]);
                if (tempamap.ContainsKey(a[i]))
                {
                    tempamap[a[i]].Add(i);
                }
                else
                {
                    var temp = new List<int>();
                    temp.Add(i);
                    tempamap.Add(a[i], temp);
                }
            }
            // 先頭の推移をみる
            int topindex = 0;
            int linecount = 0;
            int count = 0;
            int[] topindexes = new int[n];
            int[] linecounts = new int[n];
            int nexttopindex = Search(tempamap[a[topindex]], topindex) + 1;
            if (nexttopindex == n)
            {
                nexttopindex = 0;
            }
            if (nexttopindex <= topindex + 1)
            {
                linecount++;
            }
            count++;
            topindexes[count] = nexttopindex;
            linecounts[count] = linecount;
            topindex = nexttopindex;
            bool hasfinished = false;
            while (topindex != 0 && linecount < k)
            {
                nexttopindex = Search(tempamap[a[topindex]], topindex) + 1;
                if (nexttopindex == n)
                {
                    nexttopindex = 0;
                }
                if (nexttopindex <= topindex + 1)
                {
                    linecount++;
                }
                if (nexttopindex != 0)
                {
                    count++;
                    topindexes[count] = nexttopindex;
                    linecounts[count] = linecount;
                }
                if (linecount == k)
                {
                    hasfinished = true;
                    break;
                }
                topindex = nexttopindex;
            }
            int finaltopindex = topindex;
            if (!hasfinished)
            {
                int leftline = (int)(k % linecount);
                finaltopindex = topindexes[Array.FindLastIndex(linecounts, x => x == leftline - 1 || x == leftline - 1 + linecount)];

            }
            // finaltopindexを含めてそこからの数列を作る
            var lasta = new List<int>();
            for (int i = finaltopindex; i < n; i++)
            {
                if (lasta.Contains(a[i]))
                {
                    int remindex = lasta.FindIndex(x => x == a[i]);
                    lasta.RemoveRange(remindex, lasta.Count - remindex);
                }
                else
                {
                    lasta.Add(a[i]);
                }
            }
            Console.WriteLine(string.Join(" ", lasta));







#if DEBUG
            Console.ReadKey();
#endif
        }
    }
