            public Deque(int cap = 16) { b = new T[c = cap]; }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            int gi(int i) { if (i >= c) throw new Exception(); var r = o + i; return r >= c ? r - c : r; }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public void PushFront(T x) { if (Count == c) e(); if (--o < 0) o += b.Length; b[o] = x; ++Count; }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public T PopFront() { if (Count-- == 0) throw new Exception(); var r = b[o++]; if (o >= c) o -= c; return r; }
            public T Front => b[o];
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public void PushBack(T x) { if (Count == c) e(); var i = o + Count++; b[i >= c ? i - c : i] = x; }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public T PopBack() { if (Count == 0) throw new Exception(); return b[gi(--Count)]; }
            public T Back => b[gi(Count - 1)];
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            void e() { T[] nb = new T[c << 1]; if (o > c - Count) { var l = b.Length - o; Array.Copy(b, o, nb, 0, l); Array.Copy(b, 0, nb, l, Count - l); } else Array.Copy(b, o, nb, 0, Count); b = nb; o = 0; c <<= 1; }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public void Insert(int i, T x) { if (i > Count) throw new Exception(); this.PushFront(x); for (int j = 0; j < i; j++) this[j] = this[j + 1]; this[i] = x; }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public T RemoveAt(int i) { if (i < 0 || i >= Count) throw new Exception(); var r = this[i]; for (int j = i; j > 0; j--) this[j] = this[j - 1]; this.PopFront(); return r; }
        }
    }
}

using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

class Program
{
    private int N;
    private long K;
    private int[] A;

    static void Main(string[] args)
    {
        new Program().Solve();
    }

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        K = sc.NextLong();
        A = sc.IntArray();

        var nextIndex = new int[N];
        var map = new Dictionary<int, int>();
        var b = new bool[N];
        for (int i = 0; i < N; i++)
        {
            int o;
            if (map.TryGetValue(A[i], out o))
            {
                nextIndex[o] = i;
                b[o] = true;
            }

            map[A[i]] = i;
        }

        for (int i = 0; i < N; i++)
        {
            int o;
            if (map.TryGetValue(A[i], out o))
            {
                if (!b[o])
                {
                    nextIndex[o] = i + N;
                    b[o] = true;
                }
            }
        }


        int index = 0;
        long cnt = 1;
        bool flag = false;
        while (true)
        {
            int next = nextIndex[index];
            //Console.WriteLine($"{index} {next}");
            if (next % N == N - 1)
            {
                break;
            }

            if (next >= N)
            {
                cnt++;
                //Console.WriteLine($"I {next}");
            }


            index = (next + 1) % N;
        }

        K %= cnt;
        // Console.WriteLine(cnt);
        index = 0;
        cnt = 0;

        if (K == 0)
        {
            Console.WriteLine();
        }
        while (true)
        {
            int next = nextIndex[index];
            if (next >= N)
            {
                cnt++;
            }

            if (cnt >= K)
            {
                break;
            }

            index = (next + 1) % N;
        }
        // Console.WriteLine(index);
        var stack = new Stack<int>();
        var hs = new HashSet<int>();
        for (int i = index; i < N; i++)
        {
            if (hs.Add(A[i]))
            {
                stack.Push(A[i]);
            }
            else
            {
                while (true)
                {
                    int p = stack.Pop();
                    hs.Remove(p);
                    if (p == A[i])
                    {
                        break;
                    }
                }
            }
        }

        Console.WriteLine(string.Join(" ", hs));
    }
}

class Scanner
{
    public Scanner()
    {
        _stream = new StreamReader(Console.OpenStandardInput());
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private readonly StreamReader _stream;
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = _stream.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

    #endregion

    #region 型変換

    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }

    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }

    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }

    #endregion

    #region 配列取得

    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = _stream.ReadLine().Split(Separator);

        _pos = _line.Length;
        return _line;
    }

    public int[] IntArray()
    {
        return ToIntArray(Array());
    }

    public long[] LongArray()
    {
        return ToLongArray(Array());
    }

    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }

    #endregion
}

