using Number = System.Int64;

class Solver
{
    public void Solve()
    {
        int num;long k;
        Input.Make(out num, out k);
        var ar = Input.ar;
        var db = Create(60, () => Create(num, () => -1L));
        var next = Create(2 * (int)1e5 + 1, () => -1);
        for (var i = num - 1; i >= 0; i--)
            next[ar[i]] = i + num;
        for(var i = num - 1; i >= 0; i--)
        {
            db[0][i] = next[ar[i]] + 1 - i;
            next[ar[i]] = i;
        }
        for (var p = 1; p < 60; p++)
            for (var i = 0; i < num; i++)
                db[p][i] = db[p - 1][i] + db[p - 1][(i+db[p - 1][i]) % num];
        var idx = 0L;
        while (true)
        {
            for (var i = 59; i >= 0; i--)
                if (db[i][idx % num] + idx <= num * k - 1)
                { idx += db[i][idx % num]; goto END; }
            break;
        END:;
        }
        var use = new bool[2 * (int)1e5 + 1];
        var st = new Stack<int>();
        for (var i = idx % num; i < num; i++)
        {
            var v = ar[i];
            if (use[v])
            {
                while (st.Peek() != v)
                    use[st.Pop()] = false;
                use[st.Pop()] = false;
            }
            else { st.Push(v); use[v] = true; }
        }
        var res = new List<int>();
        while (st.Any())
            res.Add(st.Pop());
        res.Reverse();
        if (res.Count != 0)
            Console.WriteLine(string.Join(" ", res));

    }
}

