    public static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        var N = (int)vals[0];
        var K = vals[1];
        var A = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var max = (int)Math.Log(K, 2) + 1;
        var AA = A.Concat(A).ToArray();
        // nexts[j][i] : iから2^j分先のAに移動した位置

        var next = new int[N];
        var indexs = new Dictionary<int, int>(); // a -> index
        for (int i = 0; i < N * 2; i++)
        {
            var a = AA[i];
            if (indexs.ContainsKey(a))
            {
                var prev = indexs[a];
                if (prev < N)
                {
                    next[prev] = i + 1;
                }
            }
            indexs[a] = i;
        }
        for (int i = N - 1; i >= 0; i--)
        {
            while (next[i] < N)
            {
                next[i] = next[next[i]];
            }
        }
        for (int i = 0; i < N; i++)
        {
            next[i] %= N;
        }

        var nexts = new int[max][];
        nexts[0] = next;
        for (int j = 1; j < max; j++)
        {
            nexts[j] = new int[N];
            for (int i = 0; i < N; i++)
            {
                var t = nexts[j - 1][i];
                nexts[j][i] = nexts[j - 1][t];
            }
        }

        var p = 0;
        for (var k = K - 1; k > 0;)
        {
            var log = (int)Math.Log(k, 2);
            p = nexts[log][p];
            k -= (long)Math.Pow(2, log);
        }

        var list = new List<int>();
        for (; p < N; p++)
        {
            var a = A[p];
            var index = list.IndexOf(a);
            if (index == -1)
            {
                list.Add(a);
            }
            else
            {
                list.RemoveRange(index, list.Count - index);
            }
        }

        Console.WriteLine(string.Join(" ", list));
    }
}

