        static public void Solve()
        {
            var N = NN;
            var K = NN;
            var AList = NNList(N);

            var pos = Repeat(-1, N + 1).ToArray();
            var state = new long[N * 2];
            var idx = 0;
            for (var i = 0L; i < K; ++i)
            {
                if (i > 0)
                {
                    if (idx == 0)
                    {
                        var cnt = K % i;
                        i = K - cnt;
                    }
                }
                foreach (var item in AList)
                {
                    if (pos[item] == -1)
                    {
                        pos[item] = idx;
                        state[idx] = item;
                        ++idx;
                    }
                    else
                    {
                        var tmp = pos[item];
                        for (var j = pos[item]; j < idx; j++)
                        {
                            pos[state[j]] = -1;
                        }
                        idx = tmp;
                    }
                }
            }
            var first = true;
            for (var i = 0; i < idx; i++)
            {
                if (!first) Console.Write(" ");
                first = false;
                Console.Write(state[i]);
            }
        }

