                long memoCount = 0;
                long pointer = 0;
                while (memoCount < n)
                {
                    var aa = a[(int)pointer];

                    if (tails[aa] >= 0 && nexts[tails[aa]] < 0)
                    {
                        nexts[tails[aa]] = (pointer + 1) % n;
                        memoCount++;
                    }

                    tails[aa] = pointer;

                    pointer++;
                    pointer %= n;
                }
            }


            long mod = 0;
            {
                var pointer = 0L;
                do
                {
                    var t = nexts[pointer];
                    if (pointer >= t - 1)
                        mod++;
                    pointer = t;
                }
                while (pointer != 0);
            }

            {
                var current = 0L;
                var kk = (k + mod - 1) % mod;
                var pointer = 0L;
                do
                {
                    var t = nexts[pointer];
                    if (pointer >= t - 1)
                    {
                        if (current >= kk)
                            break;

                        current++;
                    }
                    pointer = t;
                }
                while (true);

                var res = new List<long>();
                var memo = new Dictionary<long, int>();
                int tail = -1;

                for (long i = pointer; i < n; i++)
                {
                    var aa = a[(int)i];
                    if (memo.ContainsKey(aa) && memo[aa] >= 0)
                    {
                        tail = memo[aa] - 1;
                        memo[aa] = -1;
                    }
                    else
                    {
                        tail++;
                        if (tail < res.Count)
                            res[tail] = aa;
                        else
                            res.Add(aa);
                        memo[aa] = tail;
                    }
                }

                foreach (var x in res.Take(tail + 1))
                {
                    yield return x.ToString();
                    yield return " ";
                }
            }
        }
