class Myon
{
    public Myon() { }
    public static int Main()
    {
        cin = new Scanner();
        new Myon().calc();
        return 0;
    }

    static Scanner cin;
    Random r;

    void calc()
    {
        int N;
        long K;
        N = cin.nextInt();
        K = cin.nextLong();
        int[] A = cin.ArrayInt(N);

        int MAX = 200001;
        int[] first = new int[MAX];
        for (int i = 0; i < MAX; i++)
        {
            first[i] = -1;
        }

        int[] next = new int[N];
        long[] preStep = new long[N];
        for (int i = 0; i < N; i++)
        {
            preStep[i] = -1;
        }

        for (int i = N - 1; i >= 0; i--)
        {
            next[i] = first[A[i]];
            first[A[i]] = i;
        }

        List<int> ans = new List<int>();
        long nowTurn = 0;
        int nowPos = 0;
        bool skipFlag = true;

        while (nowTurn < K)
        {


            if (skipFlag)
            {
                if(preStep[nowPos] != -1)
                {
                    long diff = nowTurn - preStep[nowPos];
                    long nokori = (K - 1) - nowTurn;
                    long skipNum = nokori / diff;
                    nowTurn += diff * skipNum;
                    skipFlag = false;
                }
                else
                {
                    preStep[nowPos] = nowTurn;
                }
            }
            if(next[nowPos] != -1)
            {
                nowPos = next[nowPos] + 1;
            }
            else if(nowTurn <= K - 2)
            {
                nowPos = first[A[nowPos]] + 1;
                nowTurn++;
            }
            else
            {
                ans.Add(A[nowPos]);
                nowPos++;
            }

            if(nowPos == N)
            {
                nowTurn++;
                nowPos = 0;
            }

        }

        Console.WriteLine(string.Join(" ", ans));
    }

}



