namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			var cin = new Scanner2();
			int n = cin.Int();
			long k = cin.Long();
			var a = cin.ArrayInt(n);

			ulong max = (ulong)(n * k);
			int maxLog = 0;
			ulong temp = max;
			while (temp > 1) {
				++maxLog;
				temp /= 2;
			}

			var dub = new ulong[maxLog + 1, n];

			var dic = new Dictionary<int, int>();
			for (int i = 0; i < n * 2; i++) {
				int target = i % n;
				if (dic.ContainsKey(a[target]) == false) {
					dic[a[target]] = i;
				} else {
					if (dub[0, dic[a[target]] % n] == 0) {
						dub[0, dic[a[target]] % n] = (ulong)(i + 1 - dic[a[target]]);
					}
					dic[a[target]] = i;
				}
			}

			for (int i = 1; i < maxLog + 1; i++) {
				for (uint j = 0; j < n; j++) {
					if (dub[i - 1, j] > 0 && dub[i - 1, (j + dub[i - 1, j]) % (uint)n] > 0) {
						dub[i, j] = dub[i - 1, (j + dub[i - 1, j]) % (uint)n] + dub[i - 1, j];
					}
				}
			}

			var ans = new List<int>();
			ulong cnt = 0;
			int index = 0;
			while (cnt < max) {
				for (int i = maxLog; i >= 0; i--) {
					if (dub[i, index] > 0) {
						if (dub[i, index] + cnt == max) {
							cnt = max;
							break;
						} else if (dub[i, index] + cnt < max) {
							cnt += dub[i, index];
							index = (int)(cnt % (uint)n);
							break;
						}
					}

					if (i == 0) {
						ans.Add(a[index]);
						++index;
						++cnt;
						break;
					}
				}
			}

			if (ans.Count == 0) {
				Console.WriteLine("");
			} else {
				Console.WriteLine(string.Join(" ", ans));
			}
		}
	}

