        public IEnumerable<string> Solve()
        {
            var n = Scan;
            var k = Scan;
            var a = ScanLongs(n);

            //var r = new Random((int)DateTime.Now.Ticks);
            ////k = r.Next(int.MaxValue) * int.MaxValue;
            //a = Loop(200001).Select(_ => (long)r.Next(200000) + 1).ToList();
            ////a = Loop(200001).Select(_ => (long)_).ToList();
            //n = a.Count;
            //k = 1;

            var nexts = Loop((int)n).Select(_ => -1L).ToArray();

            {
                var tails = Loop(200002).Select(_ => -1L).ToArray();

                long memoCount = 0;
                long pointer = 0;
                while (memoCount < n)
                {
                    var aa = a[(int)pointer];

                    if (tails[aa] >= 0 && nexts[tails[aa]] < 0)
                    {
                        nexts[tails[aa]] = (pointer + 1) % n;
                        memoCount++;
                    }

                    tails[aa] = pointer;

                    pointer++;
                    pointer %= n;
                }
            }


            long mod = 0;
            {
                var pointer = 0L;
                do
                {
                    var t = nexts[pointer];
                    if (pointer >= t - 1)
                        mod++;
                    pointer = t;
                }
                while (pointer != 0);
            }

            {
                var current = 0L;
                var kk = (k + mod - 1) % mod;
                var pointer = 0L;
                do
                {
                    var t = nexts[pointer];
                    if (pointer >= t - 1)
                    {
                        if (current >= kk)
                            break;

                        current++;
                    }
                    pointer = t;
                }
                while (true);

                var res = new List<long>();
                var memo = new Dictionary<long, int>();
                int tail = -1;

                for (long i = pointer; i < n; i++)
                {
                    var aa = a[(int)i];
                    if (memo.ContainsKey(aa) && memo[aa] >= 0)
                    {
                        tail = memo[aa] - 1;
                        memo[aa] = -1;
                    }
                    else
                    {
                        tail++;
                        if (tail < res.Count)
                            res[tail] = aa;
                        else
                            res.Add(aa);
                        memo[aa] = tail;
                    }
                }

                yield return string.Join(" ", res.Take(tail + 1));

            }
        }
    }

