using System;
using System.Collections.Generic;
using System.Linq;
using System.Diagnostics;

public class Solution
{
    public static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        var N = (int)vals[0];
        var K = vals[1];
        var A = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var sw = Stopwatch.StartNew();
        var max = (int)Math.Log(N * K, 2) + 1;
        var AA = A.Concat(A).ToArray();
        // nexts[j][i] : iから2^j回分移動した位置

        var next = new long[N];
        var indexs = new Dictionary<int, int>(); // a -> index
        for (int i = 0; i < N * 2; i++)
        {
            var a = AA[i];
            if (indexs.ContainsKey(a))
            {
                var prev = indexs[a];
                if (prev < N)
                {
                    next[prev] = i + 1 - prev;
                }
            }
            indexs[a] = i;
        }

        var nexts = new long[max][];
        nexts[0] = next;
        for (int j = 1; j < max; j++)
        {
            nexts[j] = new long[N];
            for (int i = 0; i < N; i++)
            {
                var t = nexts[j - 1][i % N];
                nexts[j][i] = t + nexts[j - 1][(i + t) % N];
            }
        }

        long p = 0;
        for (var k = N * K - 1; k > N;)
        {
            for (int j = max - 1; j >= 0; j--)
            {
                if (nexts[j][p % N] < k)
                {
                    k -= nexts[j][p % N];
                    p += nexts[j][p % N];
                    break;
                }
            }
        }

        var list = new List<int>();
        indexs.Clear();
        for (p = (p == N * K) ? p : p % N; p < N; p++)
        {
            var a = A[p];
            if (!indexs.ContainsKey(a))
            {
                indexs[a] = list.Count;
                list.Add(a);
            }
            else
            {
                var index = indexs[a];
                foreach (var aa in list.Skip(index))
                {
                    indexs.Remove(aa);
                }
                list.RemoveRange(index, list.Count - index);
            }
        }

        Console.WriteLine(string.Join(" ", list));
    }
}

