                }
            }

            for (var i = 1; i < dblCnt; i++)
            {
                var ok = true;
                for (var j = 0; j < N; j++)
                {
                    gotoCount[j, i] = gotoCount[(gotoCount[j, i - 1] + j) % N, i - 1] + gotoCount[j, i - 1];
                    if (gotoCount[j, i] > 1000000000000000000)
                    {
                        ok = false;
                        break;
                    }
                }
                if (!ok)
                {
                    dblCnt = i;
                    break;
                }
            }

            var nowDist = 0L;
            for (var i = dblCnt - 1; i >= 0; i--)
            {
                while (nowDist + gotoCount[nowDist % N, i] < N * K - 1)
                {
                    nowDist += gotoCount[nowDist % N, i];
                }
            }
            var outNum = new long[N * 2];
            var idx = 0L;
            colorTable = new long?[200001];
            for (var i = nowDist; i < N * K; i++)
            {
                var num = AList[i % N];
                if (colorTable[num].HasValue && colorTable[num] < idx)
                {
                    idx = colorTable[num].Value;
                }
                else
                {
                    colorTable[outNum[idx]] = null;
                    outNum[idx] = num;
                    colorTable[num] = idx;
                    ++idx;
                }
            }

            var first = true;
            for (var i = 0; i < idx; i++)
            {
                if (!first) Console.Write(" ");
                first = false;
                Console.Write(outNum[i]);
            }
            Console.WriteLine();
        }

