using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

static class Program
{
    static int Cycle(int N, int[] next)
    {
        int i = 0;
        int cnt = 1;
        while (i < N)
        {
            if (next[i] <= i) { ++cnt; }
            i = next[i] + 1;
        }
        return cnt;
    }

    static int[] Make(int N, int[] A, int[] next, int cnt)
    {
        if (cnt == 0) { return new int[] { }; }
        int i = 0;
        while (cnt > 1)
        {
            if (next[i] <= i || next[i] + 1 == N) { --cnt; }
            i = (next[i] + 1) % N;
        }
        var list = new List<int>();
        while (i < N)
        {
            if (next[i] > i)
            {
                i = next[i] + 1;
            }
            else
            {
                list.Add(A[i]);
                ++i;
            }
        }
        return list.ToArray();
    }

    static int[] Solve(int N, long K, int[] A)
    {
        var next = new int[N];
        var dict = new Dictionary<int, List<int>>();
        for (int i = 0; i < N; ++i)
        {
            if (!dict.ContainsKey(A[i])) { dict[A[i]] = new List<int>(); }
            dict[A[i]].Add(i);
        }
        foreach (var list in dict.Values)
        {
            int C = list.Count;
            for (int i = 0; i < C; ++i)
            {
                next[list[i]] = list[(i + 1) % C];
            }
        }
        int cycle = Cycle(N, next);
        return Make(N, A, next, (int)(K % cycle));
    }

    static void Main(string[] args)
    {
        var V1 = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
        var A = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        Console.WriteLine(string.Join(" ", Solve((int)V1[0], V1[1], A)));
    }
}

