func NextSearch(A *[]int, v int) int {
  n := len((*A))
  if (*A)[n - 1] == v {
    return 0
  }
  high := n
  low := 0
  mid := 0
  for ; high > low; {
    mid = (high + low) / 2
    if (*A)[mid] == v {
      break
    }
    if (*A)[mid] < v {
      low = mid
    } else {
      high = mid
    }
  }
  return mid + 1
}

