	return i
}

func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)
	k := getNextInt64(scanner)
	aa := make([]int, n)

	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
	}
	nx := make([]int, n)
	m := map[int]int{}
	for i := n - 1; i >= 0; i-- {
		m[aa[i]] = n + i
	}

	for i := n - 1; i >= 0; i-- {
		nx[i] = m[aa[i]]
		for nx[i]+1 < n {
			nx[i] = nx[nx[i]+1]
		}
		m[aa[i]] = i
	}
	rng58 := makeInts(60, n+1)
	for i := n - 1; i >= 0; i-- {
		rng58[0][i] = nx[i] + 1
		if rng58[0][i] >= n {
			rng58[0][i] -= n
		}
	}
	for bit := 1; bit < 60; bit++ {
		for i := 0; i <= n; i++ {
			rng58[bit][i] = rng58[bit-1][rng58[bit-1][i]]
		}
	}

	s := n
	for i := 60 - 1; i >= 0; i-- {
		if k>>uint(i)&1 == 0 {
			continue
		}
		s = rng58[i][s]
	}

	ans := make([]int, n)
	ai := 0
	mm := map[int]int{}
	for i := s; i < n; i++ {
		if _, ok := mm[aa[i]]; ok {
			for ai > 0 {
				ai--
				delete(mm, ans[ai])
				if ans[ai] == aa[i] {
					break
				}
			}
			continue
		}
		ans[ai] = aa[i]
		mm[aa[i]] = 1
		ai++
	}

	for i := 0; i < ai; i++ {
		fmt.Fprintln(writer, ans[i])
	}
	writer.Flush()
}

func makeInts(h, w int) [][]int {
	index := make([][]int, h, h)
	data := make([]int, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

