}

func contains(s []int, e int) bool {
	for _, v := range s {
		if e == v {
			return true
		}
	}
	return false
}

func remove(s []int, e int) []int {
	answer := []int{}
	for i := len(s) - 1; i >= 0; i-- {
		if e == s[i] {
			if i == 0 {
				answer = []int{}
			} else {
				answer = s[:i]
			}
			break
		}
	}
	return answer
}

