package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func configure(scanner *bufio.Scanner) {
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 1000005), 1000005)
}
func getNextString(scanner *bufio.Scanner) string {
	scanned := scanner.Scan()
	if !scanned {
		panic("scan failed")
	}
	return scanner.Text()
}
func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}
func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}
func getNextFloat64(scanner *bufio.Scanner) float64 {
	i, _ := strconv.ParseFloat(getNextString(scanner), 64)
	return i
}
func main() {
	fp := os.Stdin
	wfp := os.Stdout
	extra := 0
	if os.Getenv("I") == "IronMan" {
		fp, _ = os.Open(os.Getenv("END_GAME"))
		extra = 100
	}
	scanner := bufio.NewScanner(fp)
	configure(scanner)
	writer := bufio.NewWriter(wfp)
	defer func() {
		r := recover()
		if r != nil {
			fmt.Fprintln(writer, r)
		}
		writer.Flush()
	}()
	solve(scanner, writer)
	for i := 0; i < extra; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}
}
func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	k := getNextInt(scanner)
	aa := make([]int, n)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
	}
	last := map[int]int{}

	dbl := makeGrid(64, n+1)
	for i := n - 1; i >= 0; i-- {
		last[aa[i]] = i + n
	}
	for i := n - 1; i >= 0; i-- {
		if last[aa[i]] >= n {
			if last[aa[i]]+1 == n<<1 {
				dbl[0][i] = n
			} else {
				dbl[0][i] = (last[aa[i]] + 1) % n
			}
		} else {
			dbl[0][i] = dbl[0][(last[aa[i]]+1)%n]
		}
		last[aa[i]] = i
	}
	for i := 1; i < 64; i++ {
		for j := 0; j < n+1; j++ {
			dbl[i][j] = dbl[i-1][dbl[i-1][j]]
		}
	}
	p := 0
	for i := 60; i >= 0; i-- {
		if (k-1)>>uint(i)&1 == 1 {
			p = dbl[i][p]
		}
	}
	stack := make([]int, 0)
	m := map[int]int{}
	for i := p; i < n; i++ {
		if m[aa[i]] == 0 {
			m[aa[i]] = 1
			stack = append(stack, aa[i])
			continue
		}
		l := len(stack)
		for stack[l-1] != aa[i] {
			delete(m, stack[l-1])
			stack = stack[:l-1]
			l--
		}
		delete(m, stack[l-1])
		stack = stack[:l-1]
	}
	if len(stack) == 0 {
		fmt.Fprintln(writer, "")
		return
	}
	for i := 0; i < len(stack); i++ {
		fmt.Fprintln(writer, stack[i])
	}
}
func makeGrid(h, w int) [][]int {
	index := make([][]int, h, h)
	data := make([]int, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

