    sc.Split(bufio.ScanWords)
    for i := range as {
        sc.Scan()
        as[i], _ = strconv.Atoi(sc.Text())
    }

    m := make(map[int]int)
    to := make([]int, n*2)
    for i := 0; i < n*2; i++ {
        v := as[i%n]
        if b, ok := m[v]; ok && b > -1 {
            to[b] = i - b
            m[v] = i
        } else {
            m[v] = i
        }
    }

    var i, j int
    for {
        j += (to[j] + 1)
        if j >= n {
            i++
            j %= n
        }
        if j == 0 {
            k = k % i
            break
        }
    }

    var s []int
    m = make(map[int]int)
    for i := 0; i < k; i++ {
        for j := range as {
            if b, ok := m[as[j]]; ok && b > -1 {
                for l := len(s) - 1; s[l] != as[j]; l-- {
                    m[s[l]] = -1
                }
                m[as[j]] = -1
                s = s[0:b]
            } else {
                s = append(s, as[j])
                m[as[j]] = len(s) - 1
            }
        }
        if len(s) == 0 {
            k = k % (i + 1)
            i = -1
        }
    }

    for i := range s {
        if i == len(s)-1 {
            fmt.Println(s[i])
        } else {
            fmt.Printf("%d ", s[i])
        }
    }
}

