var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  var line, buffer []byte
  var isPrefix bool = true
  var err error
  for isPrefix {
    line, isPrefix, err = reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
  }
  return string(buffer)
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func NextSearch(A *[]int, v int) int {
  n := len((*A))
  if (*A)[n - 1] == v {
    return 0
  }
  high := n
  low := 0
  mid := 0
  for ; high > low; {
    mid = (high + low) / 2
    if (*A)[mid] == v {
      break
    }
    if (*A)[mid] < v {
      low = mid
    } else {
      high = mid
    }
  }
  return mid + 1
}

func main() {
  NK := NextIntVec()
  N := NK[0]
  A := NextIntVec()
  D := make([][]int, 200001)
  for i := range D {
    D[i] = make([]int, 0)
  }
  for i, a := range A {
    D[a] = append(D[a], i)
  }
  k := 1
  v := -1
  for ; v < N - 1; {
    v += 1
    a := A[v]
    idx := NextSearch(&D[a], v)
    v = D[a][idx]
    if idx == 0 {
      k += 1
      if NK[1] < k { break }
    }
  }
  K := NK[1] % k
  v = 0
  for ; K > 0; v++ {
    a := A[v]
    idx := NextSearch(&D[a], v)
    if idx == 0 {
      K -= 1
      if K == 0 { break }
    }
    v = D[a][idx]
  }
  S := make([]int, 0)
  for ; v < N; v++ {
    a := A[v]
    idx := NextSearch(&D[a], v)
    if idx == 0 {
      S = append(S, a)
    } else {
      v = D[a][idx]
    }
  }
  ans := ""
  if len(S) > 0 {
    ans = strconv.Itoa(S[0])
    for i := 1; i < len(S); i++ {
      ans += " " + strconv.Itoa(S[i])
    }
  }
  Write(ans)
  Output()
}

