import (
	"fmt"
)

func main() {
	var (
		n, k int
	)
	fmt.Scan(&n, &k)
	nums := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&nums[i])
	}

	answer := []int{}
	for j := 0; j < k; j++ {
		for i := 0; i < n; i++ {
			if contains(answer, nums[i]) {
				answer = remove(answer, nums[i])
			} else {
				answer = append(answer, nums[i])
			}
		}
	}

	// fmt.Print(answer)
	for i, v := range answer {
		fmt.Print(v)
		if i != len(answer)-1 {
			fmt.Print(" ")
		}
	}
}

func contains(s []int, e int) bool {
	for _, v := range s {
		if e == v {
			return true
		}
	}
	return false
}

func remove(s []int, e int) []int {
	answer := []int{}
	for i := len(s) - 1; i >= 0; i-- {
		if e == s[i] {
			if i == 0 {
				answer = []int{}
			} else {
				answer = s[:i]
			}
			break
		}
	}
	return answer
}

