func getScanner(fp *os.File) *bufio.Scanner {
	scanner := bufio.NewScanner(fp)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 500001), 500000)
	return scanner
}

func getNextString(scanner *bufio.Scanner) string {
	scanner.Scan()
	return scanner.Text()
}

func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}

func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}

func getNextUint64(scanner *bufio.Scanner) uint64 {
	i, _ := strconv.ParseUint(getNextString(scanner), 10, 64)
	return i
}

func getNextFloat64(scanner *bufio.Scanner) float64 {
	i, _ := strconv.ParseFloat(getNextString(scanner), 64)
	return i
}

func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)
	k := getNextInt64(scanner)
	aa := make([]int, n)

	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
	}
	nx := make([]int, n)
	m := map[int]int{}
	for i := n - 1; i >= 0; i-- {
		m[aa[i]] = n + i
	}

	for i := n - 1; i >= 0; i-- {
		nx[i] = m[aa[i]] + 1
		for nx[i] < n {
			nx[i] = nx[nx[i]]
		}
		m[aa[i]] = i
	}
	rng58 := makeInts(60, n)
	for i := 0; i < n; i++ {
		rng58[0][i] = nx[i]
	}
	for bit := 1; bit < 60; bit++ {
		for i := 0; i < n; i++ {
			rng58[bit][i] = rng58[bit-1][rng58[bit-1][i]%n]
		}
	}

	k--
	s := 0
	for i := 60 - 1; i >= 0; i-- {
		if k>>uint(i)&1 == 0 {
			continue
		}
		s = rng58[i][s%n]
	}

	ans := make([]int, n)
	ai := 0
	mm := map[int]int{}
	for i := s - n; i < n; i++ {
		if _, ok := mm[aa[i]]; ok {
			for ai > 0 {
				ai--
				delete(mm, ans[ai])
				if ans[ai] == aa[i] {
					break
				}
			}
			continue
		}
		ans[ai] = aa[i]
		mm[aa[i]] = 1
		ai++
	}

	for i := 0; i < ai; i++ {
		fmt.Fprintln(writer, ans[i])
	}
	writer.Flush()
}

func makeInts(h, w int) [][]int {
	index := make([][]int, h, h)
	data := make([]int, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	var n, k int
	fmt.Scan(&n, &k)

	as := make([]int, n)
	var sc = bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	for i := range as {
		sc.Scan()
		as[i], _ = strconv.Atoi(sc.Text())
	}

	m := make(map[int]int)
	to := make([]int, n*2)
	for i := 0; i < n*2; i++ {
		v := as[i%n]
		if b, ok := m[v]; ok && b > -1 {
			to[b] = i - b
			m[v] = i
		} else {
			m[v] = i
		}
	}

	var i, j int
	for {
		j += (to[j] + 1)
		if j >= n {
			i++
			j %= n
		}
		if j == 0 {
			k = k % i
			break
		}
	}

	var s []int
	m = make(map[int]int)
	for i := 0; i < k; i++ {
		for j := range as {
			if b, ok := m[as[j]]; ok && b > -1 {
				for l := len(s) - 1; s[l] != as[j]; l-- {
					m[s[l]] = -1
				}
				m[as[j]] = -1
				s = s[0:b]
			} else {
				s = append(s, as[j])
				m[as[j]] = len(s) - 1
			}
		}
		if len(s) == 0 {
			k = k % (i + 1)
			i = -1
		}
	}

	for i := range s {
		if i == len(s)-1 {
			fmt.Println(s[i])
		} else {
			fmt.Printf("%d ", s[i])
		}
	}
}

