package main

import (
	"fmt"
)

func main() {
	var (
		n, k int
	)
	fmt.Scan(&n, &k)
	nums := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&nums[i])
	}

	answer := []int{}
	for j := 0; j < k; j++ {
		for i := 0; i < n; i++ {
			if contains(answer, nums[i]) {
				answer = remove(answer, nums[i])
			} else {
				answer = append(answer, nums[i])
			}
			fmt.Println(answer)
		}
	}

	// fmt.Print(answer)
	for i, v := range answer {
		fmt.Print(v)
		if i != len(answer)-1 {
			fmt.Print(" ")
		}
	}
}

func contains(s []int, e int) bool {
	for _, v := range s {
		if e == v {
			return true
		}
	}
	return false
}

func remove(s []int, e int) []int {
	answer := []int{}
	for i := len(s) - 1; i >= 0; i-- {
		if e == s[i] {
			if i == 0 {
				answer = []int{}
			} else {
				answer = s[:i]
			}
			break
		}
	}
	return answer
}

package main

import (
  "bufio"
  "container/list"
  "fmt"
  "os"
  "strconv"
  "strings"
)

func main() {
  input := Input{bufio.NewReaderSize(os.Stdin,10000)}
  n,k := input.NextInts()
  a := input.NextIntArray()
  idx := map[int]int{}
  g := make([][]int64,60)
  for i:=0;i<60;i++ { g[i] = make([]int64,n) }
  for i:=0;i<n;i++ {
    if _,ok := idx[a[i]];!ok { idx[a[i]] = n+i }
  }
  for i:=n-1;i>-1;i-- {
    g[0][i] = int64(idx[a[i]]-i)
    idx[a[i]] = i
  }
  x := int64(0)
  r := int64(n)*k-1
  for i:=1;i<60;i++ {
    for j:=0;j<n;j++ {
      if g[i-1][(g[i-1][j]+int64(j))%int64(n)]+g[i-1][j] <= 2*(r+1) {
        g[i][j] = g[i-1][(g[i-1][j]+int64(j))%int64(n)]+g[i-1][j]
      }
    }
  }
  for x+g[0][x%int64(n)] <= r {
    for i:=59;i>-1;i-- {
      if x+g[i][x%int64(n)] <= r { x += g[i][x%int64(n)] }
    }
  }
  queue := list.New()
  set := make(map[int]struct{})
  for ;x<=r;x++ {
    if _,ok := set[a[x%int64(n)]];ok {
      for {
        y,_ := queue.Remove(queue.Back()).(int)
        delete(set,y)
        if y == a[x%int64(n)] { break }
      }
      continue
    }
    queue.PushBack(a[x%int64(n)])
    set[a[x%int64(n)]] = struct{}{}
  }
  for queue.Len() > 0 {
    v,_ := queue.Remove(queue.Front()).(int)
    fmt.Print(v)
    if queue.Len() == 0 { break }
    fmt.Print(" ")
  }
  fmt.Println()
}

type Input struct { reader *bufio.Reader }
func(i *Input) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := i.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextInts() (int,int64) {
  s := strings.Fields(i.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.ParseInt(s[1],10,64)
  return x,y
}
func(i *Input) NextIntArray() []int {
  s := strings.Fields(i.NextLine())
  a := make([]int,len(s))
  for i:=0;i<len(s);i++ { a[i],_ = strconv.Atoi(s[i]) }
  return a
}

