var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  var line, buffer []byte
  var isPrefix bool = true
  var err error
  for isPrefix {
    line, isPrefix, err = reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
  }
  return string(buffer)
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func main() {
  NK := NextIntVec()
  N := NK[0]
  A := NextIntVec()
  D := make([][]int, 200001)
  for i := range D {
    D[i] = make([]int, 0)
  }
  H := make([]int, N)
  for i, a := range A {
    D[a] = append(D[a], i)
  }
  for i, _ := range D {
    for j := 0; j < len(D[i]); j++ {
      next := (j + 1) % len(D[i])
      H[D[i][j]] = D[i][next]
    }
  }
  k := 1
  for v := -1 ; v < N - 1; {
    v += 1
    next := H[v]
    if next <= v { k += 1 }
    v = next
  }
  K := NK[1] % k
  v := 0
  for ; K > 0; v++ {
    if H[v] <= v {
      K -= 1
      if K == 0 { break }
    }
    v = H[v]
  }
  S := make([]int, 0)
  for ; v < N; v++ {
    if H[v] <= v {
      S = append(S, A[v])
    } else {
      v = H[v]
    }
  }
  ans := ""
  if len(S) > 0 {
    ans = strconv.Itoa(S[0])
    for i := 1; i < len(S); i++ {
      ans += " " + strconv.Itoa(S[i])
    }
  }
  Write(ans)
  Output()
}

