func main() {
  input := Input{bufio.NewReaderSize(os.Stdin,10000)}
  n,k := input.NextInts()
  a := input.NextIntArray()
  idx := map[int]int{}
  g := make([][]int64,60)
  for i:=0;i<60;i++ { g[i] = make([]int64,n) }
  for i:=0;i<n;i++ {
    if _,ok := idx[a[i]];!ok { idx[a[i]] = n+i }
  }
  for i:=n-1;i>-1;i-- {
    g[0][i] = int64(idx[a[i]]-i)
    idx[a[i]] = i
  }
  for i:=1;i<60;i++ {
    for j:=0;j<n;j++ { g[i][j] = g[i-1][(g[i-1][j]+int64(j))%int64(n)]+g[i-1][j] }
  }
  x := int64(0)
  r := int64(n)*k-1
  for x+g[0][x%int64(n)] <= r {
    for i:=59;i>-1;i-- {
      if x+g[i][x%int64(n)] <= r { x += g[i][x%int64(n)] }
    }
  }
  queue := list.New()
  set := make(map[int]struct{})
  for x < r {
    x++
    if _,ok := set[a[x%int64(n)]];ok {
      for {
        y,_ := queue.Remove(queue.Back()).(int)
        delete(set,y)
        if y == a[x%int64(n)] { break }
      }
      continue
    }
    queue.PushBack(a[x%int64(n)])
    set[a[x%int64(n)]] = struct{}{}
  }
  for queue.Len() > 0 {
    v,_ := queue.Remove(queue.Front()).(int)
    fmt.Print(v)
    if queue.Len() == 0 { break }
    fmt.Print(" ")
  }
  fmt.Println()
