// ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- //

void solve(){
	int n = read.to!int;
	long k = read.to!long;

	int[] as;
	foreach(i; 0 .. n) as ~= read.to!int;
	log("as:", as);

	int[][int] aq;
	foreach(int i, a; as){
		if(a !in aq) aq[a] = [];
		aq[a] ~= i;
	}
	log("aq:", aq);

	int[int] next; // next[i] = i2 ならば i は i2 でクリアされる
	bool[int] over; // over[i] は i はその周期の中でクリアされない
	int[] aqks = aq.keys;
	foreach(a; aqks){
		for(int ix = 0; ix < aq[a].length; ix ++){
			if(ix < aq[a].length - 1){
				next[aq[a][ix]] = (aq[a][ix + 1] + 1) % n;
				over[aq[a][ix]] = 0;
			}
			else{
				next[aq[a][ix]] = (aq[a][0] + 1) % n;
				over[aq[a][ix]] = 1;
			}
		}
	}
	log("next:", next);
	log("over:", over);

	int[int] last; // last[j] は j ( = 0 , ...) 回目の周期が実質どこから始まるか (=最後にクリアしたときの i に対して、i + 1)
	int cnt = 0; // 何周でもとにもどるか
	for(int i = 0; ; i = next[i]){
		if(over[i]){
			last[cnt] = i;
			cnt += 1;
		}
		if(next[i] == 0){
			last[cnt] = i;
			cnt += 1;
			break;
		}
	}
	log("last:", last);
	log("cnt:", cnt);

	int k2 = (k % cnt).to!int; // 実質、何周すればよいか
	log("k2:", k2);

	if(k2 == 0){
		"".writeln;
		return;
	}

	int i2 = last[k2 - 1]; // 実質、ここから始める
	log("i2:", i2);

	int[] ans;
	for(int i = i2; i < n; ){
		if(over[i]){
			ans ~= as[i];
			i += 1;
		}
		else i = next[i];
		if(i == 0) break;
	}

	ans.map!(to!string).array.join(" ").writeln;
}

