        writeln(K % 2 ? A.front.to!string : "");
        return;
    }

    auto next = new int[](N);
    next[] = -1;
    int[long] prev;

    foreach (i; 0..2*N) {
        int idx = i % N;
        if (A[idx] in prev) {
            next[prev[A[idx]]] = idx;
        }
        prev[A[idx]] = idx;
    }


    int[int] mem;
    Tuple!(int, long)[] mem_array;
    long lap = 0;
    int idx = 0;

    while(true) {
        if (idx in mem) {
            break;
