            nx = (next[idx]+1) % N;
            if (nx <= idx) lap++;
        }
        else if (next[idx] > idx) {
            nx = (next[idx]+1) % N;
            if (nx <= idx) lap++;
        }
        else {
            nx = (idx + 1) % N;
            ans ~= A[idx];
            if (nx == 0) lap++;
        }
        if (lap == K) {
            break;
        }
        idx = nx;
    }

    debug {idx.writeln; mem_array.writeln; next.writeln;}

    ans.map!(to!string).join(" ").writeln;
}

