void search(ll now, ll step)
{
	if(vis[now])
	{
		if(vis[now] == cnt) start = now, link[now] = step - s[now];
		return;
	}
	vis[now] = cnt;
	s[now] = step;
	search(nex[now], step + w[now]);
	if(start == now) start = 0;
	if(start) link[now] = link[nex[now]];
	return ;
}

