def main():
    from collections import defaultdict

    N, K = map(int, readline().split())
    A = list(map(int, readline().split()))

    c = N * K
    b = 0
    while 2 ** b < c:
        b += 1

    doubling = [[0] * N for _ in range(b + 1)]

    idx = defaultdict(list)
    for i, x in enumerate(A):
        idx[x].append(i)

    for i in range(1, 200001):
        d = idx[i]
        l = len(d)
        for j in range(l):
            cur = d[j]
            nx = d[(j + 1) % l]
            if nx <= cur:
                doubling[0][cur] = N - (cur - nx) + 1
            else:
                doubling[0][cur] = nx - cur + 1

    for i in range(1, b + 1):
        for j in range(N):
            p = doubling[i - 1][j]
            doubling[i][j] = p + doubling[i - 1][(j + p) % N]

    cnt = 0
    cur = 0
    while c - cnt > 200000:
        for i in range(b, -1, -1):
            if cnt + doubling[i][cur] < c:
                cnt += doubling[i][cur]
                cur = cnt % N
                break

    rem = c - cnt
    res = []
    res_set = set()

    while rem > 0:
        num = A[cur]
        if num in res_set:
            while True:
                back = res[-1]
                res.pop()
                res_set.discard(back)
                if back == num:
                    break
        else:
            res.append(num)
            res_set.add(num)
        rem -= 1
        cur += 1
        cur %= N

    print(*res)


