from itertools import product
import numpy as np


def calc(N: int, K: int, A: np.ndarray) -> np.ndarray:
    loop_values, rest_iter = calc_until_find_loop(N, K, A)
    loop_len = loop_values.shape[0]
    return loop_values[rest_iter % loop_len]


def calc_until_find_loop(N: int, K: int, A: np.ndarray):  # (loop_values, rest_iter)
    results = []
    values_to_idx = {}
    values = np.array([])
    for i in range(K):
        values = one_iter(A, values)
        tup_values = tuple(values)

        if tup_values in values_to_idx:
            return np.array(results[values_to_idx[tup_values] :]), (K - i - 1)

        values_to_idx[tup_values] = len(results)
        results.append(values)

    return np.array([values]), 0


def one_iter(A: np.ndarray, prev_values: np.ndarray) -> np.ndarray:
    values = np.array(prev_values.tolist() + A.tolist())
    mask = np.ones_like(values)
    ptr = 0
    for ptr in range(len(values)):
        if mask[ptr] == 0:
            continue
        for i in range(ptr + 1, len(values)):
            if values[i] != values[ptr]:
                continue

            mask[ptr : i + 1] = 0
            break
    return values[mask.astype(bool)]


