N, K = map(int, input().split())
a = list(map(int, input().split()))


def solve(remain_count):
    s = deque()
    for i in range(0, remain_count):
        for j in range(0, N):
            if a[j] in s:
                while s[-1] != a[j] and a[j] in s:
                    s.pop()
                s.pop() # pop last

                # 子数列の最後の時点で結果がカラであれば、その倍数分は省略できる実装
                if len(s) == 0 and (j == N - 1):
                    new_remain_count = K % (i + 1)
                    if new_remain_count < remain_count and ( N * new_remain_count < (N * remain_count - (i + 1) * (j + 1))):
                        return solve(new_remain_count)
            else:
                s.append(a[j])
    return s


