import collections


def main():
    N, K = [int(x) for x in input().split()]
    A = [int(x) for x in input().split()]
    to_next = [0] * N

    occs = collections.defaultdict(list)

    for i, a in enumerate(A):
        occs[a].append(i)
        if len(occs[a]) > 1:
            to_next[occs[a][-2]] = i - occs[a][-2] + 1

    for i, a in enumerate(A):
        to_next[occs[a][-1]] = N - occs[a][-1] + occs[a][0] + 1

    pos = 0
    ops = 0
    first_visit = [-1] * N

    while first_visit[pos] == -1 and ops + to_next[pos] < N * K:
        first_visit[pos] = ops
        ops += to_next[pos]
        pos = (pos + to_next[pos]) % N

    if first_visit[pos] != -1:
        rem_ops = (N * K - ops) % (ops - first_visit[pos])
        # ops += (N * K - ops) // (ops - first_visit[ops])

    else:
        rem_ops = N * K - ops

    sol = []
    contains = set()

    for i in range(rem_ops):
        a = A[(pos + i) % N]
        if a in contains:
            x = sol.pop()
            while x != a:
                contains.remove(x)
                x = sol.pop()
            contains.remove(x)
        else:
            contains.add(a)
            sol.append(a)

    print(' '.join(str(x) for x in sol))


