def get_remain(a, next_, index):
    used = [False] * len(a)
    ans  = []

    for i in range(index, len(a)):
        if used[i] == True:
            continue

        if next_[i] > i:
            for j in range(i, next_[i]+1):
                used[j] = True
        else:
            ans.append(a[i])

    return ans        

