    B = [None]*N
    firstPos = {}
    lastPos = {}

    for p, a in enumerate(A):
        if a in lastPos:
            B[lastPos[a]] = p
            B[p] = firstPos[a]
        else:
            firstPos[a] = p
            B[p] = p

        lastPos[a] = p

    C = [None]*N
    for p, b in enumerate(B):
        c = (b - p)%N
        if c == 0:
            c = N

        C[p] = c + 1

