            size = len(dd[v])
            if p < size:
                pos = dd[v][p]+1
                if pos == N:
                    conv[i] = 0
                    break
            else:
                conv[i] = dd[A[pos]][0] + 1
                break
    conv[N] = 0

    dp = [[0]*(N+1) for _ in range(41)]
    for i in range(N+1):
        dp[0][i] = conv[i]

    for k in range(1, 41):
        for n in range(N+1):
            dp[k][n] = dp[k - 1][dp[k - 1][n]]

    res = []
    t = K-1
    for i in range(41):
        if (t>>i)&1:
            res.append(i)

    pos = 0
    for i in res:
        pos = dp[i][pos]

    ans = []
    while pos < N:
        num = A[pos]
        pp = bisect_right(dd[num], pos)
        if pp < len(dd[num]):
            pos = dd[num][pp]+1
        else:
            ans.append(num)
