use std::collections::HashMap;
fn main() {
    input! { n, k, a: [usize; n] };
    let mut cost = vec![std::usize::MAX; n + 1];
    let mut next = (0..n + 1).collect::<Vec<_>>();
    let mut prev = HashMap::new();
    for i in 0..n * 2 {
        if prev.contains_key(&a[i % n]) {
            next[prev[&a[i % n]]] = i % n;
        }
        prev.insert(a[i % n], i % n);
    }
    let mut b = vec![0; n + 1];
    let mut i = 0;
    let mut acc = vec![];
    loop {
        let ni = (next[i] + 1) % (n + 1);
        acc.push(i);
        if next[i] <= i {
            for &x in &acc {
                b[x] = ni;
            }
            acc.clear();
        }
        i = ni;
        if i == 0 {
            break;
        }
    }
    let mut p = n;
    let mut i = b[p];
    cost[p] = 0;
    while cost[i] == std::usize::MAX {
        cost[i] = cost[p] + 1;
        p = i;
        i = b[i];
