use std::collections::HashMap;
fn main() {
    input! { n, k, a: [usize; n] };
    let mut cost = vec![std::usize::MAX; n];
    let mut next = (0..n).collect::<Vec<_>>();
    let mut prev = HashMap::new();
    for i in 0..n * 2 {
        if prev.contains_key(&a[i % n]) {
            next[prev[&a[i % n]]] = i % n;
        }
        prev.insert(a[i % n], i % n);
    }
    let mut i = (next[0] + 1) % n;
    let mut p = 0;
    cost[0] = 0;
    while cost[i] == std::usize::MAX {
        cost[i] = cost[p];
        if i <= p + 1 {
            cost[i] += 1;
        }
        p = i;
        i = (next[i] + 1) % n;
    }
    let mut x = k - 1;
    if x >= cost[i] {
        x = (x - cost[i]) % (cost[p] + 1 - cost[i]) + cost[i];
    }
    let mut j = 0;
    let mut p;
    if x > 0 {
        // j = (next[p] + 1) % n;
        while x > 0 {
            p = j;
            j = (next[j] + 1) % n;
            if j <= p + 1 {
                x -= 1;
            }
        }
    }
    let mut res = vec![];
    while j < n {
        if next[j] <= j {
            res.push(a[j]);
        } else {
            j = next[j];
        }
        j += 1;
    }
    for x in res.into_iter() {
        print!("{} ", x);
    }
    println!("");
}

