#[derive(Debug, Clone)]
struct Cons {
    value: usize,
    curr: usize,
    next: usize,
    next_orig: usize,
    overwrap: usize,
}

fn main() {
    input! {
        n: usize,
        k: u64,
        xs: [usize; n],
    }
    let k = k - 1;

    debug!(n);
    debug!(k);
    debug!(xs);

    const MAX: usize = (2.0 * 1e5 + 1.0) as usize;
    let mut next_values = vec![0; MAX];
    for i in (0..n).rev() {
        next_values[xs[i]] = i;
    }

    let mut edges = vec![];
    for i in (0..n).rev() {
        let j = (next_values[xs[i]] + 1) % n;
        edges.push(Cons {
            value: xs[i],
            curr: i,
            next: j,
            next_orig: next_values[xs[i]],
            overwrap: if j <= (i + 1) { 1 } else { 0 },
        });
        next_values[xs[i]] = i;
    }
    edges.reverse();

    debug!(edges);

    // Notice that G = (V, E) where V = xs, E = edges, can be regarded as a directed simple graph.
    // Each connected component is a loop.
    // Futhermore, for all v in V, there is just one e in E s.t. source (resp. target) of e is v.
    // Proof:
    //   It is enough to show that f: E -> V; e -> target(e) is injective.
    //   This follows from g: E -> V; e -> source(e) is injective and #V = #E is finite.

    // Take the connected component containing 0.
    let mut chain = vec![];
    let mut next = 0;
    for _ in 0..n {
        let e = edges[next].clone();
        next = e.next;
        chain.push(e);
        if next == 0 {
            break;
        }
    }

    let chain_overwrap: usize = chain.iter().map(|ref e| e.overwrap).sum();

    debug!(chain);
    debug!(chain_overwrap);

    let mut c = (k % (chain_overwrap as u64)) as usize;
    let mut next = 0;
    for e in &chain {
        if c == 0 {
            break;
        }

        c -= e.overwrap;
        next = e.next;
    }

    let mut rs = vec![];
    loop {
        let e = &edges[next];

        if next < e.next_orig {
            next = e.next_orig + 1;
        } else {
            rs.push(e.value);
            next = next + 1;
        }

        if next == n {
            break;
        }
    }

    debug!(rs);

    println!("{}", rs.iter().map(|&r| format!("{}", r)).vec().join(" "));
}

