fn run() {
    input! {
        n: usize,
        k: usize,
        a: [usize; n],
    }

    if n == 1 {
        if k % 2 == 1 {
            println!("{}", a[0]);
        }
        return;
    }

    let mut last = HashMap::new();
    let mut next = vec![usize::max_value(); 2 * n];
    for i in 0..2 * n {
        let x = a[i % n];
        if last.contains_key(&x) {
            next[last[&x]] = i + 1;
        }
        last.insert(x, i);
    }

    let mut cur_idx = 0;
    let mut period = 0;
    let mut period_map = HashMap::new();
    period_map.insert(0, 0);

    let mut start = 0;
    loop {
        let mut next_idx = next[cur_idx];
        while next_idx >= n {
            next_idx -= n;
            period += 1;
        }
        cur_idx = next_idx;
        if period_map.contains_key(&cur_idx) {
            start = period_map[&cur_idx];
            period = period - start;
            break;
        }
        period_map.insert(cur_idx, period);
    }

    let mut rest = n * if k <= start { k } else { (k - start) % period };
    let mut cur_idx = 0;
    loop {
        let mut next_idx = next[cur_idx];
        while next_idx >= n {
            next_idx -= n;
            if rest < n {
                rest = 0;
            } else {
                rest -= n;
            }
        }
        if next_idx >= rest {
            break;
        }
        cur_idx = next_idx;
    }

    let mut used = HashSet::new();
    let mut state = VecDeque::new();
    for i in cur_idx..n {
        let x = a[i];
        if !used.contains(&x) {
            used.insert(x);
            state.push_back(x);
        } else {
            while let Some(y) = state.pop_back() {
                used.remove(&y);
                if x == y {
                    break;
                }
            }
        }
    }
    let mut first = true;
    for x in state {
        if first {
            first = false;
        } else {
            print!(" ");
        }
        print!("{}", x);
    }
    println!("");
}

//{{{ ---- template ----
fn main() {
    let _ = ::std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap();
}

pub trait SetMinMax {
    fn set_min(&mut self, v: Self) -> bool;
    fn set_max(&mut self, v: Self) -> bool;
}

impl<T> SetMinMax for T
where
    T: PartialOrd,
{
    fn set_min(&mut self, v: T) -> bool {
        *self > v && {
            *self = v;
            true
        }
    }
    fn set_max(&mut self, v: T) -> bool {
        *self < v && {
            *self = v;
            true
        }
    }
}

#[derive(PartialEq, Eq, Debug, Copy, Clone, Default, Hash)]
pub struct Reverse<T>(pub T);

impl<T: PartialOrd> PartialOrd for Reverse<T> {
    #[inline]
    fn partial_cmp(&self, other: &Reverse<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }

    #[inline]
    fn lt(&self, other: &Self) -> bool {
        other.0 < self.0
    }
    #[inline]
    fn le(&self, other: &Self) -> bool {
        other.0 <= self.0
    }
    #[inline]
    fn ge(&self, other: &Self) -> bool {
        other.0 >= self.0
    }
    #[inline]
    fn gt(&self, other: &Self) -> bool {
        other.0 > self.0
    }
}

impl<T: Ord> Ord for Reverse<T> {
    #[inline]
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

