use std::collections::HashSet;
fn main() {
    let v = read_vec::<usize>();
    let n = v[0];
    let k = v[1];

    let a = read_vec::<u64>();


    let mut i:usize = 1;
    let mut p: u64 = a[0];
    let mut blocksize: usize = 0;

    if a.iter().collect::<HashSet<&u64>>().len() == n {
        blocksize = n * n;
    } else {
        loop {
            if a[i % n] == p {
                if i % n == n - 1 {
                    blocksize = i + 1;
                    break;
                } else {
                    p = a[i % n + 1];
                    i += 2;
                }
            } else {
                i += 1;
            }
        }
    }

    let rest = n * k % blocksize;

    let mut s = vec![];
    for i in 0..rest {
        let aa = a[i % n];
        if s.contains(&aa) {
            while s.pop().unwrap() != aa {}
        }
        else {
            s.push(a[i % n])
        }
    }
    let ans = s.into_iter().map(|i| i.to_string()).collect::<Vec<String>>().join(" ");
    println!("{}", ans);
}

