fn main() {
    input! { n, k, a: [usize; n] };
    const M: usize = 60;
    let mut idx = HashMap::new();
    let mut d = vec![vec![0u128; M + 1]; n];
    for i in 0..n {
        idx.entry(a[i]).or_insert(vec![]).push(i);
    }
    for (_a, v) in idx.into_iter() {
        for i in 0..v.len() {
