use std::collections::HashMap;
fn main() {
    input! { n, k, a: [usize; n] };
    let mut cost = vec![std::usize::MAX; n];
    let mut next = (0..n).collect::<Vec<_>>();
    let mut prev = HashMap::new();
    for i in 0..n * 2 {
        if prev.contains_key(&a[i % n]) {
            next[prev[&a[i % n]]] = i % n;
        }
        prev.insert(a[i % n], i % n);
    }
    let mut i = (next[0] + 1) % n;
    let mut p = 0;
    cost[0] = 0;
    while cost[i] == std::usize::MAX {
        cost[i] = cost[p];
        if i <= p + 1 {
            cost[i] += 1;
        }
        p = i;
        i = (next[i] + 1) % n;
    }
    let mut x = k - 1;
    if x > cost[i] {
        x = (x - cost[i]) % (cost[p] + 1 - cost[i]) + cost[i];
    }
    let mut j = 0;
    while x > 0 {
        let nj = (next[j] + 1) % n;
        if nj <= j + 1 {
            x -= 1;
        }
        j = nj;
    }
    let mut res = vec![];
    while j < n {
        if next[j] <= j {
            res.push(a[j]);
        } else {
            j = next[j];
        }
        j += 1;
    }
    for x in res.into_iter() {
        print!("{} ", x);
    }
    println!("");
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

