use std::cmp::{min, max};
use std::collections::{HashMap, HashSet};

fn main() {
    input!{
        n: usize,
        k: usize,
        v: [usize; n]
    }
    let mut dels: HashSet<usize> = HashSet::new();
    let mut w = vec![];
    let mut map: HashMap<usize, usize> = HashMap::new();
    let mut rep = false;
    for &x in &v {
        if map.contains_key(&x) {
            loop {
                let y = w.pop().unwrap();
                *map.get_mut(&y).unwrap() -= 1;
                if map.get(&y) == Some(&0) {
                    map.remove(&y);
                    dels.insert(y);
                }
                if y == x {
                    break;
                }
            }
        } else {
            if dels.contains(&x) {
                rep = true;
            }
            map.insert(x, 1);
            w.push(x);
        }
    }
    let mut c;
    if rep {
        c = 1;
        let mut w2 = w.clone();
        while w2.len() > 0 {
            update(&mut w2, &v);
            c += 1;
        }
    } else {
        c = w.len() + 1;
    }
    let k = k % c;
    if k > 0 {
        if !rep {
            print!("{}", w[k - 1]);
            for i in k..w.len() {
                print!(" {}", w[i]);
            }
        } else {
            for i in 1..k {
                update(&mut w, &v);
            }
            print!("{}", w[0]);
            for i in 1..w.len() {
                print!(" {}", w[i]);
            }
        }
    }
    println!("");
}

fn update(w: &mut Vec<usize>, v: &Vec<usize>) {
    let mut map: HashMap<usize, usize> = HashMap::new();
    for &x in w.iter() {
        map.insert(x, 1);
    }
    for &x in v {
        if map.contains_key(&x) {
            loop {
                let y = w.pop().unwrap();
                *map.get_mut(&y).unwrap() -= 1;
                if y == x {
                    map.remove(&y);
                    break;
                }
                if map.get(&y) == Some(&0) {
                    map.remove(&y);
                }
            }
        } else {
            map.insert(x, 1);
            w.push(x);
        }
    }
}

