use std::collections::HashMap;
fn main() {
    input! { n, k, a: [usize; n] };
    let mut cost = vec![std::usize::MAX; n];
    let mut next = (0..n).collect::<Vec<_>>();
    let mut prev = HashMap::new();
    for i in 0..n * 2 {
        if prev.contains_key(&a[i % n]) {
            next[prev[&a[i % n]]] = i % n;
        }
        prev.insert(a[i % n], i % n);
    }
    let mut i = (next[0] + 1) % n;
    let mut p = 0;
    cost[0] = 0;
    while cost[i] == std::usize::MAX {
        cost[i] = cost[p] + 1;
        p = i;
        i = (next[i] + 1) % n;
    }
    let mut x = k - 1;
    if x > cost[i] {
        if cost[i] < cost[p] + 1 {
            println!("{}", x);
            x = (x - cost[i]) % (cost[p] + 1 - cost[i]) + cost[i];
            println!("{}", x);
        }
    }
    let mut j = 0;
    while x > 0 {
        j = (next[j] + 1) % n;
        x -= 1;
    }
    let mut res = vec![];
    let mut i = 0;
    while i < n {
        if next[i] == i {
            res.push(a[i]);
        } else {
            i = next[i];
        }
        i += 1;
    }
    for x in res.into_iter() {
        print!("{} ", x);
    }
    println!("");
    println!("{:?}", &cost);
    println!("{:?}", &next);
}

