#[derive(Debug, Clone)]
struct Cons {
    value: usize,
    curr: usize,
    next: usize,
    overwrap: usize,
}

fn main() {
    input! {
        n: usize,
        k: u64,
        xs: [usize; n],
    }
    let k = k - 1;

    debug!(n);
    debug!(k);
    debug!(xs);

    let mut ys = xs.clone();
    ys.append(&mut xs.clone());
    debug!(ys);

    let mut edges = vec![];
    'outer: for i in 0..n {
        for j in (i+1)..(2 * n) {
            if xs[i] == ys[j] {
                edges.push(Cons {
                    value: ys[j],
                    curr: i,
                    next: (j + 1) % n,
                    overwrap: min(1, (j + 1) / n),
                });
                continue 'outer;
            }
        }
        unreachable!();
    }

    debug!(edges);

    // Notice that G = (V, E) where V = xs, E = edges, can be regarded as a directed simple graph.
    // Each connected component is a loop.
    // Futhermore, for all v in V, there is just one e in E s.t. source (resp. target) of e is v.
    // Proof:
    //   It is enough to show that f: E -> V; e -> target(e) is injective.
    //   This follows from g: E -> V; e -> source(e) is injective and #V = #E is finite.

    // Take the connected component containing 0.
    let mut chain = vec![];
    let mut next = 0;
    for _ in 0..n {
        let e = edges[next].clone();
        next = e.next;
        chain.push(e);
        if next == 0 {
            break;
        }
    }

    let chain_overwrap: usize = chain.iter().map(|ref e| e.overwrap).sum();

    debug!(chain);
    debug!(chain_overwrap);

    let mut c = (k % (chain_overwrap as u64)) as usize;
    let mut next = 0;
    for e in &chain {
        if c == 0 {
            break;
        }

        c -= e.overwrap;
        next = e.next;
    }

    let mut rs = vec![];
    while next != 0 {
        let e = &edges[next];

        if next == n - 1 {
            rs.push(e.value);
            next = (next + 1) % n;
        } else if e.next == 0 {
            break;
        } else {
            match e.overwrap {
                0 => {
                    next = e.next;
                },
                1 => {
                    rs.push(e.value);
                    next = (next + 1) % n;
                }
                _ => unreachable!(),
            }
        }
    }

    debug!(rs);

    println!("{}", rs.iter().map(|&r| format!("{}", r)).vec().join(" "));
}

macro_rules! get {
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    get!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    get!($($t),*)
        ).collect::<Vec<_>>()
    };
    ($t:ty |) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty | $n:expr) => {
        (0..$n).map(|_| get!($t |)).collect::<Vec<_>>()
    };
}

