#[derive(Debug, Clone)]
struct Cons {
    value: usize,
    curr: usize,
    next: usize,
    overwrap: usize,
}

fn main() {
    input! {
        n: usize,
        k: u64,
        xs: [usize; n],
    }
    let k = k - 1;

    debug!(n);
    debug!(k);
    debug!(xs);

    const MAX: usize = (2.0 * 1e5 + 1.0) as usize;
    let mut next_values = vec![0; MAX];
    for i in (0..n).rev() {
        next_values[xs[i]] = i;
    }

    let mut edges = vec![];
    for i in (0..n).rev() {
        let j = (next_values[xs[i]] + 1) % n;
        edges.push(Cons {
            value: xs[i],
            curr: i,
            next: j,
            overwrap: if j <= (i + 1) { 1 } else { 0 },
        });
        next_values[xs[i]] = i;
    }
    edges.reverse();

    debug!(edges);

    // Notice that G = (V, E) where V = xs, E = edges, can be regarded as a directed simple graph.
    // Each connected component is a loop.
    // Futhermore, for all v in V, there is just one e in E s.t. source (resp. target) of e is v.
    // Proof:
    //   It is enough to show that f: E -> V; e -> target(e) is injective.
    //   This follows from g: E -> V; e -> source(e) is injective and #V = #E is finite.

    // Take the connected component containing 0.
    let mut chain = vec![];
    let mut next = 0;
    for _ in 0..n {
        let e = edges[next].clone();
        next = e.next;
        chain.push(e);
        if next == 0 {
            break;
        }
    }

    let chain_overwrap: usize = chain.iter().map(|ref e| e.overwrap).sum();

    debug!(chain);
    debug!(chain_overwrap);

    let mut c = (k % (chain_overwrap as u64)) as usize;
    let mut next = 0;
    for e in &chain {
        if c == 0 {
            break;
        }

        c -= e.overwrap;
        next = e.next;
    }

    let mut rs = vec![];
    while next != 0 {
        let e = &edges[next];

        if next == n - 1 {
            rs.push(e.value);
            next = (next + 1) % n;
        } else if e.next == 0 {
            break;
        } else {
            match e.overwrap {
                0 => {
                    next = e.next;
                },
                1 => {
                    rs.push(e.value);
                    next = (next + 1) % n;
                }
                _ => unreachable!(),
            }
        }
    }

    debug!(rs);

    println!("{}", rs.iter().map(|&r| format!("{}", r)).vec().join(" "));
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let n: usize = sc.read();
    let k: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);
    let max_a = *a.iter().max().unwrap();
    let mut add = vec![0; n];
    let mut last: Vec<Option<usize>> = vec![None; max_a + 1];
    for i in 0..(2 * n) {
        let a = a[i % n];
        if let Some(x) = last[a] {
            if x < n {
                add[x] = i - x;
            }
        }
        last[a] = Some(i);
    }
    assert!(add.iter().all(|&add| add > 0));

    let (first, second) = find_cycle(&add);
    let length = (n * k - first) % (second - first) + first;

    let mut set: Vec<bool> = vec![false; max_a + 1];
    let mut ans: Vec<usize> = vec![];
    for i in 0..length {
        let a = a[i % n];
        if set[a] {
            while let Some(tail) = ans.pop() {
                assert!(set[tail]);
                set[tail] = false;
                if tail == a {
                    break;
                }
            }
        } else {
            set[a] = true;
            ans.push(a);
        }
    }
    for (i, ans) in ans.into_iter().enumerate() {
        if i > 0 {
            print!(" ");
        }
        print!("{}", ans);
    }
    println!();
}

fn find_cycle(add: &Vec<usize>) -> (usize, usize) {
    let n = add.len();
    let mut last: Vec<Option<usize>> = vec![None; n];
    let mut cur = 0;
    for i in 0..1000000 {
        if let Some(first) = last[cur % n] {
            return (first, cur);
        }

        last[cur % n] = Some(cur);
        cur += add[cur % n] + 1;
    }
    unreachable!()
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

