use std::collections::{BTreeMap, BTreeSet};

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n = sc.read();
    let k: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);
    let mut prev = BTreeMap::new();
    let mut jump = vec![vec![0; n]; 30];

    for i in 0..n {
        if let Some(x) = prev.get_mut(&a[i]) {
            jump[0][*x] = i - *x;
            *x = i;
        } else {
            prev.insert(a[i], i);
        }
    }

    for i in 0..n {
        if let Some(x) = prev.remove(&a[i]) {
            jump[0][x] = n + i - x;
        }
    }

    for t in 1..30 {
        for i in 0..n {
            let jump1 = jump[t - 1][i];
            let next = (i + jump1 + 1) % n;
            let jump2 = jump[t - 1][next];
            jump[t][i] = jump1 + 1 + jump2;
        }
    }

    let l = k * n;
    let mut pos = 0;
    for t in (0..30).rev() {
        loop {
            let next = jump[t][pos % n] + pos + 1;
            if next < l {
                pos = next;
            } else {
                break;
            }
        }
    }

    let mut set = BTreeSet::new();
    let mut ans = vec![];
    for i in pos..l {
        let d = i % n;
        if set.remove(&a[d]) {
            while let Some(p) = ans.pop() {
                if p == a[d] {
                    break;
                }
            }
        } else {
            set.insert(a[d]);
            ans.push(a[d]);
        }
    }

    for (i, a) in ans.into_iter().enumerate() {
        if i > 0 {
            print!(" ");
        }
        print!("{}", a);
    }
    println!();
}

