use std::io::{stdout, stdin, BufWriter, Write};

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      k: u64,
      aa: [usize; n],
    }

    const MAX: usize = 2 * 100000 + 2;
    let mut next_n = vec![None; n];
    let mut last_n = vec![None; MAX];
    let mut first_n = vec![n; MAX];
    for i in 0..n {
        let a = aa[i];
        if let Some(idx) = last_n[a] {
            next_n[idx] = Some(i);
        }
        last_n[a] = Some(i);
        if first_n[a] == n {
            first_n[a] = i;
        }
    }

    let mut memo = vec![None; n];

    let mut cnt = 0;
    let mut left = None;
    loop {
        cnt += 1;
        let mut start_pos = 0usize;
        if let Some(l) = left {
            start_pos = first_n[l] + 1;
        }

        if start_pos == n {
            break;
        }

        let mut cur = start_pos;
        while cur < n {
            if let Some(v) = memo[cur] {
                memo[start_pos] = Some(v);
                break;
            }

            let a = aa[cur];
            if let Some(idx) = next_n[cur] {
                cur = idx + 1;
            } else {
                // fix next number
                memo[start_pos] = Some(a);
                break;
            }
        }

        if let Some(v) = memo[start_pos] {
            left = Some(v);
        } else {
            break;
        }
    }
    let k = k%cnt;
    if k == 0 {
        return puts!("{}\n", "");
    }

    let mut start_pos = 0;
    for i in 0..k-1 {
        let nv = memo[start_pos].unwrap();
        start_pos = first_n[nv] + 1;
    }

    // 最終的な文字列を求める
    let mut cur = start_pos;
    let mut ans = vec![];
    while cur < n {
        if next_n[cur].is_some() {
            cur = next_n[cur].unwrap() + 1;
            continue;
        } else {
            ans.push(aa[cur]);
            cur += 1;
        }
    }
    for &a in ans.iter() {
        if a == ans[ans.len()-1] {
            puts!("{}", a);
        } else {
            puts!("{} ", a);
        }
    }
    puts!("\n");
}

use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, k: usize, a: [usize; n]);
    let mut d = std::collections::HashMap::new();
    for i in 0..n {
        d.entry(a[i]).or_insert(vec![]).push(i);
    }
    let mut b = vec![0];
    while b[b.len() - 1] % n != 0 || b[b.len() - 1] == 0 {
        let mut i = b[b.len() - 1];
        let ai = a[i % n];
        let j = d[&ai].binary_search(&(i % n + 1)).unwrap_or_else(|x| x);
        if j == d[&ai].len() {
            i += n + d[&ai][0] + 1 - (i % n);
        } else {
            i += d[&ai][j] + 1 - (i % n);
        }
        b.push(i);
    }

    let len = b[b.len() - 1];
    let r = (n * k) % len;
    let r = match b.binary_search(&r) {
        Ok(_) => 0,
        Err(i) => r - b[i - 1],
    };
    let mut s = std::collections::HashSet::<usize>::new();
    let mut stack = vec![];
    'outer: for i in (n - r)..n {
        if let Some(&ai) = s.get(&a[i]) {
            while let Some(aj) = stack.pop() {
                s.remove(aj);
                if *aj == ai {
                    continue 'outer;
                }
            }
        }
        stack.push(&a[i]);
        s.insert(a[i]);
    }
    println!(
        "{}",
        stack
            .into_iter()
            .map(|i| i.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

