fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: usize,
        xs: [usize1; n],
    }
    if n == 1 {
        if m % 2 == 0 {
        } else {
            writeln!(buf, "{}", xs[0] + 1);
        }
        return buf;
    }
    let mut prev = vec![0; 2_00000];
    let mut next = vec![0; n];
    for i in (0..2 * n).rev() {
        if i < n {
            next[i] = prev[xs[i % n]] % n;
        }
        prev[xs[i % n]] = i;
    }
    // eprintln!("next = {:?}", next);
    let seq = {
        let mut res = vec![];
        let mut p = 0;
        res.push(p);
        p = (next[p] + 1) % n;
        while p != 0 {
            res.push(p);
            p = (next[p] + 1) % n;
        }
        res
    };
    // eprintln!("seq = {:?}", seq);
    let mut r = 0;
    for i in 1..seq.len() {
        if seq[i - 1] + 1 % n == seq[i] || seq[i - 1] > seq[i] {
            r += 1;
        }
        if i == seq.len() - 1 && seq[i] == n - 1 {
            r += 1;
        }
    }
    r += 1;
    let mut ps = vec![0; r];
    // eprintln!("r = {:?}", r);
    if m % r == 0 {
        return buf;
    }
    r = 0;
    for i in 1..seq.len() {
        if seq[i - 1] + 1 == seq[i] || seq[i - 1] > seq[i] {
            r += 1;
            ps[r] = seq[i];
        }
        if i == seq.len() - 1 && seq[i] == n - 1 {
            r += 1;
        }
    }
    r += 1;
