fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let n: usize = sc.read();
    let k: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);
    let max_a = *a.iter().max().unwrap();
    let mut add = vec![0; n];
    let mut last: Vec<Option<usize>> = vec![None; max_a + 1];
    for i in 0..(2 * n) {
        let a = a[i % n];
        if let Some(x) = last[a] {
            if x < n {
                add[x] = i - x;
            }
        }
        last[a] = Some(i);
    }
    assert!(add.iter().all(|&add| add > 0));

    let (first, second) = find_cycle(&add);
    let length = (n * k - first) % (second - first) + first;

    let mut set: Vec<bool> = vec![false; max_a + 1];
    let mut ans: Vec<usize> = vec![];
    for i in 0..length {
        let a = a[i % n];
        if set[a] {
            while let Some(tail) = ans.pop() {
                assert!(set[tail]);
                set[tail] = false;
                if tail == a {
                    break;
                }
            }
        } else {
            set[a] = true;
            ans.push(a);
        }
    }
    for (i, ans) in ans.into_iter().enumerate() {
        if i > 0 {
            print!(" ");
        }
        print!("{}", ans);
    }
    println!();
}

fn find_cycle(add: &Vec<usize>) -> (usize, usize) {
    let n = add.len();
    let mut last: Vec<Option<usize>> = vec![None; n];
    let mut cur = 0;
    loop {
        match last[cur % n] {
            Some(first) => {
                return (first, cur);
            }
            None => {
                last[cur % n] = Some(cur);
                cur += add[cur % n] + 1;
            }
        }
    }
}

