fn solve(a: &Vec<u64>, l: usize) -> Vec<u64> {
    let n = a.len();
    let mut prev = BTreeMap::new();
    let mut jump = vec![vec![0; n]; 50];

    for i in 0..n {
        if prev.contains_key(&a[i]) {
            let x = prev[&a[i]];
            jump[0][x] = i - x;
            prev.insert(a[i], i);
        } else {
            prev.insert(a[i], i);
        }
    }

    for i in 0..n {
        if let Some(x) = prev.remove(&a[i]) {
            jump[0][x] = n + i - x;
        }
    }

    for t in 1..50 {
        for i in 0..n {
            let jump1 = jump[t - 1][i];
            let next = (i + jump1 + 1) % n;
            let jump2 = jump[t - 1][next];
            jump[t][i] = jump1 + 1 + jump2;
        }
    }

    let mut pos = 0;
    for t in (0..50).rev() {
        loop {
            let next = jump[t][pos % n] + pos + 1;
            if next < l {
                pos = next;
            } else {
                break;
            }
        }
    }
    assert!(pos < l);

    naive(&a, pos, l)
}

fn naive(a: &Vec<u64>, pos: usize, l: usize) -> Vec<u64> {
    let n = a.len();
    let mut set = BTreeSet::new();
    let mut ans = vec![];
    for i in pos..l {
        let d = i % n;
        let a = a[d];
        if set.contains(&a) {
            while let Some(p) = ans.pop() {
                set.remove(&p);
                if p == a {
                    break;
                }
            }
            set.remove(&a);
        } else {
            set.insert(a);
            ans.push(a);
        }
    }
    ans
}

