  #[allow(unused_macros)]
  macro_rules! dbg {
    ($($x:expr),+) => {{
      eprintln!(concat!("[{}:{}] ", $(stringify!($x), " = {:?}; "),+), file!(), line!(), $($x),+);
    }};
  }

  let (n, k) = scan!(usize, u64);
  let a = scan!(u64; n);

  let mut map = HashMap::<u64, Vec<usize>>::new();

  for i in 0..n {
    map.entry(a[i]).or_insert(vec![]).push(i);
  }

  let tapi = |max_offset: usize| {
    let (mut offset, mut i) = if map[&a[0]].len() == 1 {
      (1, 1)
    } else {
      (0, 0)
    };

    let mut j = 0;
    let mut is_first = true;

    while is_first || i != 0 || j != 0 {
      dbg!(offset, i, j);

      j = {
        let mut ok = map[&a[i]].len() as isize - 1;

        if map[&a[i]][ok as usize] <= i {
          offset += 1;

          if offset == max_offset {
            return (i, j, offset);
          }

          0
        } else {
          let mut ng = -1isize;

          while ok - ng > 1 {
            let mid = (ok + ng) / 2;

            if map[&a[i]][mid as usize] > i {
              ok = mid;
            } else {
              ng = mid;
            }
          }

          ok as usize
        }
      };

      i = map[&a[i]][j];

      i += 1;

      if i == n {
        offset += 1;
        i = 0;
        j = 0;
        break;
      }

      is_first = false;
    }

    dbg!(offset);

    (i, j, offset)
  };

  let offset = tapi(1145141919810).2;

  let (i, mut j, _) = tapi((k % offset as u64) as usize);

  if i == 0 && j == 0 {
    println!("");
    return;
  }

  dbg!(i, j);

  let mut s = Vec::<u64>::new();

  {
    let mut k = i;

    while k < n {
      dbg!(k, a[k], map[&a[k]], j);

      if {
        let mut ok = map[&a[k]].len() as isize - 1;
        let mut ng = -1isize;

        while ok - ng > 1 {
          let mid = (ok + ng) / 2;

          if map[&a[k]][mid as usize] >= k {
            ok = mid;
          } else {
            ng = mid;
          }
