const A_BOUND: usize = 200_001;

fn next_occurrence_indices(xs: &[u32]) -> Vec<usize> {
    let mut occurrences_of = vec![Vec::new(); A_BOUND];
    let mut first_occurrences = vec![None; A_BOUND];
    for (i, &x) in xs.iter().enumerate() {
        occurrences_of[x as usize].push(i);
        if first_occurrences[x as usize].is_none() {
            first_occurrences[x as usize] = Some(i);
        }
    }
    for v in occurrences_of.iter_mut() {
        v.reverse();
    }

    let mut res = Vec::with_capacity(xs.len());
    for &x in xs {
        occurrences_of[x as usize].pop().unwrap();
        res.push(occurrences_of[x as usize].last().cloned().unwrap_or_else(|| {
            first_occurrences[x as usize].unwrap() + xs.len()
        }))
    }
    res
}

#[test]
fn test_ind() {
    assert_eq!(next_occurrence_indices(&[0, 0, 1, 0, 2, 2]),
               vec![1, 3, 8, 6, 5, 10]);
}

fn period(table: &[usize]) -> usize {
    let mut i = (table[0] + 1) % table.len();
    let mut ans = (table[0] + 1) / table.len();
    while i != 0 {
        dbg!(i);
        i = table[i] + 1;
        if i >= table.len() {
            ans += i / table.len();
            i %= table.len();
        }
    }
    ans
}

fn main() {
    read!(n = usize, k = usize);
    read!(aa = Vec<u32>);
    let table = next_occurrence_indices(&aa);
    let k = k % dbg!(period(&table));

    let mut rep = 0;
    let mut i = 0;
    let mut ans = Vec::new();
    while rep < k {
        if n*rep + table[i] + 1 <= n*k {
            i = table[i] + 1;
        } else {
            ans.push(aa[i]);
            i += 1;
        }
        rep += i / n;
        i %= n;
    }

    println!("{}", ans.into_iter().join(" "));
}

