use std::collections::HashMap;
fn main() {
    input! { n, k, a: [usize; n] };
    const M: usize = 60;
    let mut idx = HashMap::new();
    let mut d = vec![vec![0; M + 1]; n];
    for i in 0..n {
        idx.entry(a[i]).or_insert(vec![]).push(i);
    }
    for (_a, v) in idx.into_iter() {
        for i in 0..v.len() {
            let j = v[i];
            let nj = v[(i + 1) % v.len()];
            d[j][0] = if nj > j { nj - j } else { nj + n - j } + 1;
        }
    }
    for m in 1..M + 1 {
        for i in 0..n {
            d[i][m] = d[i][m - 1] + d[(i + d[i][m - 1]) % n][m - 1];
        }
    }
    let mut i = 0;
    let mut m = M;
    let mut b = 0;
    while b < k * n {
        if b + d[i][m] > k * n {
            if m == 0 {
                print!("{} ", a[i]);
                b += 1;
                i = (i + 1) % n;
            } else {
                m -= 1;
            }
        } else {
            b += d[i][m];
            i = (i + d[i][m]) % n;
        }
    }
    println!("");
}

