fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize, k: i64,
        a: [usize; n],
    }
    let mut occ = HashMap::new();
    for i in 0..n {
        occ.entry(a[i]).or_insert(vec![]).push(i);
    }
    const B: usize = 60;
    let mut dp = vec![vec![(0i64, 0); n]; B];
    for (_, indices) in occ {
        let k = indices.len();
        for i in 0..k {
            let x = indices[i];
            let y = indices[(i + 1) % k];
            dp[0][x] = (if i + 1 == k { 1 } else { 0 } + ((y + 1) / n) as i64,
                        (y + 1) % n);
        }
    }
    for i in 0..B - 1 {
        for j in 0..n {
            let (x, tmp) = dp[i][j];
            let (y, tmp) = dp[i][tmp];
            dp[i + 1][j] = (x + y, tmp);
        }
    }
    let mut x = 0;
    let mut y = 0;
    for i in (0..B).rev() {
        let (z, nxt) = dp[i][y];
        if x + z < k {
            x += z;
            y = nxt;
        }
    }
    // process elements one by one.
    assert_eq!(x, k - 1);
    let mut occ = HashSet::new();
    let mut v = vec![];
    for i in y..n {
        if !occ.contains(&a[i]) {
            v.push(a[i]);
            occ.insert(a[i]);
        } else {
            while let Some(x) = v.pop() {
                if x == a[i] {
                    break;
                }
            }
            occ.remove(&a[i]);
        }
    }
    for a in v {
        puts!("{} ", a);
    }
    puts!("\n");
}

