pub fn writeln_vec<T: Display>(s: &mut String, xs: &Vec<T>) {
    if xs.len() == 0 {
        writeln!(s, "");
    } else {
        write!(s, "{}", xs[0]);
        for x in xs.iter().skip(1) {
            write!(s, " {}", x);
        }
        writeln!(s, "");
    }
}

