fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: usize,
        xs: [usize1; n],
    }
    let mut prev = vec![0; 2_00000];
    let mut next = vec![0; n];
    for i in (0..2 * n).rev() {
        if i < n {
            next[i] = prev[xs[i % n]] % n;
        }
        prev[xs[i % n]] = i;
    }
    // eprintln!("next = {:?}", next);
    let seq = {
        let mut res = vec![];
        let mut p = 0;
        res.push(p);
        p = (next[p] + 1) % n;
        while p != 0 {
            res.push(p);
            p = (next[p] + 1) % n;
        }
        res
    };
    // eprintln!("seq = {:?}", seq);
    let mut r = 0;
    for i in 1..seq.len() {
        if seq[i - 1] + 1 == seq[i] || seq[i - 1] > seq[i] {
            r += 1;
        }
    }
    r += 1;
    let mut ps = vec![0; r];
    // eprintln!("r = {:?}", r);
    r = 0;
    for i in 1..seq.len() {
        if seq[i - 1] + 1 == seq[i] || seq[i - 1] > seq[i] {
            r += 1;
            ps[r] = seq[i];
        }
    }
    r += 1;
    // eprintln!("ps = {:?}", ps);
    let begin = ps[(m + r - 1) % r];
    // eprintln!("begin.. = {:?}", &xs[begin..]);
    // (v,pos)
    let mut res = vec![];
    // x -> vec![i];
    let mut x_to_is = vec![vec![]; 2_00000];
    for (i, &x) in xs[begin..n].iter().enumerate() {
        let i = i + begin;
        // eprintln!("i = {}", i);
        if x_to_is[x].is_empty() {
            res.push((x, i));
            x_to_is[x].push(i);
        } else {
            let prev_i = x_to_is[x][x_to_is[x].len() - 1];
            loop {
                if res.last().unwrap().1 > prev_i {
                    x_to_is[res.last().unwrap().0].pop();
                    res.pop();
                } else {
                    break;
                }
            }
            res.pop();
            x_to_is[x].pop();
        }
    }
    let res: Vec<usize> = res.iter().map(|&(x, _)| x + 1).collect();
    writeln_vec(&mut buf, &res);
    buf
}

use std::cmp::{max, min};
