fn main() {
    let mut input_str = String::new();
    std::io::stdin().read_to_string(&mut input_str).unwrap();

    let input_parts = input_str.split_whitespace().collect::<Vec<_>>();
    let mut input_parts_it = input_parts.iter().cloned();

    let n: usize = input_parts_it.next().unwrap().parse().unwrap();
    let k: u64 = input_parts_it.next().unwrap().parse().unwrap();

    let mut a: Vec<u32> = (0..n).map(|_|  input_parts_it.next().unwrap().parse().unwrap()).collect();

    const NONE: usize = 0xffffffff;
    let mut group_end: Vec<usize> = vec![NONE; a.len()];

    let mut next_a_same_value_for_a: Vec<usize> = vec![NONE; a.len()];
    let mut last_a_for_aval: Vec<usize> = vec![NONE; 200000];

    for (i, &aval) in a.iter().enumerate().rev() {
        next_a_same_value_for_a[i] = last_a_for_aval[aval as usize];
        last_a_for_aval[aval as usize] = i;
    }

    for (i, &aval) in a.iter().enumerate() {
        // find the next `aval` elem with an identical value
        let mut k = next_a_same_value_for_a[i];
        if k == NONE {
            k = last_a_for_aval[aval as usize];
            debug_assert!(k != NONE);
            k += a.len();
        }
        k += 1;

        group_end[i] = k;
    }

    // check the cycle length
    let mut cycle_len = 0;
    {
        let mut i = 0;
        loop {
            let mut hop = group_end[i] - i;
            cycle_len += hop as u64;
            i = group_end[i];
            while i >= a.len() {
                i -= a.len();
            }
            if i == 0 {
                break;
            }
        }
    }

    // skip cycles
    let mut step = n as u64 * k;
    step = step %cycle_len;


    let mut state: Vec<u32> = Vec::with_capacity(a.len());
    let mut index: Vec<usize> = vec![NONE; 200000];

    {
        let mut i = 0;
        let mut remaining_steps = step;

        while remaining_steps >= (group_end[i] - i) as u64 {
            remaining_steps -= (group_end[i] - i) as u64;
            i = group_end[i];
            while i >= a.len() {
                i -= a.len();
            }
        }

        while remaining_steps > 0 {
            let aval = a[i];

            if index[aval as usize] == NONE {
                index[aval as usize] = state.len();
                state.push(aval);
            } else {
                while state.len() > index[aval as usize] {
                    let k = state.pop().unwrap();
                    index[k as usize] = NONE;
                }
            }

            i += 1;
            while i >= a.len() {
                i -= a.len();
            }
            remaining_steps -= 1;
        }
    }

    if state.is_empty() {
        println!("");
    } else {
        print!("{}", state[0]);
        for &x in state[1..].iter() {
            print!(" {}", x);
        }
    }
}

use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, k: usize, a: [usize; n]);
    let mut d = std::collections::HashMap::new();
    for i in 0..n {
        d.entry(a[i]).or_insert(vec![]).push(i);
    }
    let mut b = vec![0];
    while b[b.len() - 1] % n != 0 || b[b.len() - 1] == 0 {
        let mut i = b[b.len() - 1];
        let ai = a[i % n];
        let j = d[&ai].binary_search(&(i % n + 1)).unwrap_or_else(|x| x);
        if j == d[&ai].len() {
            i += n + d[&ai][0] + 1 - (i % n);
        } else {
            i += d[&ai][j] + 1 - (i % n);
        }
        b.push(i);
    }

    let len = b[b.len() - 1];
    let r = (n * k) % len;
    let r = match b.binary_search(&r) {
        Ok(_) => 0,
        Err(i) => r - b[i - 1],
    };
    let mut s = std::collections::HashMap::<usize, usize>::new();
    let mut stack = vec![];
    for i in (n - r)..n {
        if let Some(&j) = s.get(&a[i]) {
            stack = stack[..j].to_vec();
        } else {
            stack.push(a[i]);
            s.insert(a[i], stack.len() - 1);
        }
    }
    println!(
        "{}",
        stack
            .into_iter()
            .map(|i| i.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

