#[derive(Debug, Clone)]
struct Next {
    value: usize,
    curr: usize,
    next: usize,
    overwrap: usize,
}

fn main() {
    input! {
        n: usize,
        k: u64,
        xs: [usize; n],
    }
    let k = k - 1;

    debug!(n);
    debug!(k);
    debug!(xs);

    let mut ys = xs.iter().map(|&x| (x, 0)).vec();
    ys.append(&mut xs.iter().map(|&x| (x, 1)).vec());
    debug!(ys);

    let mut next_table = vec![];
    'outer: for i in 0..n {
        for j in (i+1)..(2 * n) {
            if xs[i] == ys[j].0 {
                next_table.push(Next {
                    value: ys[j].0,
                    curr: i,
                    next: (j + 1) % n,
                    overwrap: min(1, (j + 1) / n),
                });
                continue 'outer;
            }
        }
        unreachable!();
    }

    debug!(next_table);

    let mut chain = vec![];
    let mut checked = vec![None; n];
    let mut next = 0;
    let mut loop_init = 0;
    for i in 0..n {
        match checked[next] {
            Some(j) => {
                loop_init = j;
                break;
            },
            None => {
                checked[next] = Some(i);
                let nt = next_table[next].clone();
                next = nt.next;
                chain.push(nt);
            }
        }
    }

    debug!(loop_init);
    debug!(chain);

    let mut init_part = 0;
    let mut loop_part = 0;

    for i in 0..loop_init {
        init_part += chain[i].overwrap;
    }
    for i in loop_init..chain.len() {
        loop_part += chain[i].overwrap;
    }

    debug!(init_part);
    debug!(loop_part);

    let pos = if k <= (init_part as u64) {
        let mut c = k;
        let mut pos = 0;

        for next in &chain[..loop_init] {
            if c == 0 && next.overwrap > 0 {
                pos = next.curr;
                break;
            }

            c -= next.overwrap as u64;
        }

        pos
    } else {
        let mut c = (k - (init_part as u64)) % (loop_part as u64);
        let mut pos = 0;

        for next in &chain[loop_init..] {
            debug!(c);
            debug!(next);
            if c == 0 && next.overwrap > 0 {
                pos = next.curr;
                break;
            }            

            c -= next.overwrap as u64;
        }

        pos
    };

    debug!(pos);

    let xs = &xs[pos..];
    let mut ys = vec![];

    for x in xs {
        let mut truncate = false;
        for i in 0..ys.len() {
            if x == ys[i] {
                truncate = true;
                ys.truncate(i);
                break;
            }
        }

        if !truncate {
            ys.push(x);
        }
    }

    debug!(ys);

    for (i, &y) in ys.iter().enumerate() {
        print!("{}{}", if i == 0 { "" } else { " " }, y)
    }
    println!("");
}

