use std::collections::HashMap;
fn main() {
    input! { n, k, a: [usize; n] };
    const M: usize = 60;
    let mut idx = HashMap::new();
    let mut d = vec![vec![0; M + 1]; n];
    for i in 0..n {
        idx.entry(a[i]).or_insert(vec![]).push(i);
    }
    for (_a, v) in idx.into_iter() {
        for i in 0..v.len() {
            let j = v[i];
            let nj = v[(i + 1) % v.len()];
            d[j][0] = if nj > j { nj - j } else { nj + n - j } + 1;
        }
    }
    for m in 1..M + 1 {
        for i in 0..n {
            d[i][m] = d[i][m - 1].saturating_add(d[(i + d[i][m - 1]) % n][m - 1]);
        }
    }
    let mut m = M;
    let mut b = 0;
    let u = k * n;
    while b < u {
        let i = b % n;
        if b + d[i][m] > u {
            if m == 0 {
                print!("{} ", a[i]);
                b += 1;
            } else {
                m -= 1;
            }
        } else {
            b += d[i][m];
        }
    }
    println!("");
}

use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, k: usize, a: [usize; n]);
    let mut d = std::collections::HashMap::new();
    for i in 0..n {
        d.entry(a[i]).or_insert(vec![]).push(i);
    }
    let mut b = vec![0];
    while b[b.len() - 1] % n != 0 || b[b.len() - 1] == 0 {
        let mut i = b[b.len() - 1];
        let ai = a[i % n];
        let j = d[&ai].binary_search(&(i % n + 1)).unwrap_or_else(|x| x);
        if j == d[&ai].len() {
            i += n + d[&ai][0] + 1 - (i % n);
        } else {
            i += d[&ai][j] + 1 - (i % n);
        }
        b.push(i);
    }

    let len = b[b.len() - 1];
    let r = (n * k) % len;
    let r = match b.binary_search(&r) {
        Ok(_) => 0,
        Err(i) => r - b[i - 1],
    };
    let mut s = std::collections::HashMap::<usize, usize>::new();
    let mut stack = vec![];
    for i in (n - r)..n {
        if let Some(&j) = s.get(&a[i]) {
            if j < stack.len() {
                stack = stack[..j].to_vec();
            }
            continue;
        }
        stack.push(a[i]);
        s.insert(a[i], stack.len() - 1);
    }
    println!(
        "{}",
        stack
            .into_iter()
            .map(|i| i.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

