fn run() {
    input! {
        n: usize,
        k: usize,
        a: [usize; n],
    }
    let mut b = a.clone();
    let mut c = a.clone();
    b.append(&mut c);
    let m = 200000 + 1;
    let mut next = vec![2 * n + 1; m];
    for i in (n..(2 * n)).rev() {
        next[b[i]] = i;
    }
    let mut dp = vec![vec![]; 60];
    dp[0].resize(n, 0);
    for i in (0..n).rev() {
        dp[0][i] = next[b[i]] - i + 1;
        next[b[i]] = i;
    }
    let mut depth = 0;
    while dp[depth][0] < n * k {
        depth += 1;
        dp[depth].resize(n, 0);
        for i in 0..n {
            let x = dp[depth - 1][i];
            let y = dp[depth - 1][(i + x) % n];
            dp[depth][i] = x + y;
        }
    }
    let mut step = 0;
    loop {
        if step + dp[depth][step % n] < n * k {
            step += dp[depth][step % n];
        } else if depth == 0 {
            break;
        } else {
            depth -= 1;
        }
    }
    let mut elem = vec![false; m];
    let mut ans = vec![];
    while step < n * k {
        let x = step % n;
        let v = a[x];
        step += 1;
        if elem[v] {
            while let Some(z) = ans.pop() {
                elem[z] = false;
                if v == z {
                    break;
                }
            }
        } else {
            elem[v] = true;
            ans.push(v);
        }
    }
    let mut out = String::new();
    for v in ans {
        out.push_str(&v.to_string());
        out.push(' ');
    }
    out.pop();
    println!("{}", out);
}

fn main() {
    run();
}

