fn main() {
    let param = read_vector::<u64>();
    let (n, k) = (param[0], param[1]);
    let arr = read_vector::<u64>();
    if n == 1 && k == 1 {
        println!("{}", arr[0]);
        return;
    }
    let mut positions = HashMap::<u64, Vec<u64>>::new();
    for i in 0..arr.len() {
        if positions.contains_key(&arr[i]) {
            positions.get_mut(&arr[i]).unwrap().push(i as u64);
        } else {
            positions.insert(arr[i], vec![i as u64]);
        }
    }
    let mut dp = vec![vec![n * k + 1; arr.len()]; ((n * k) as f64).log2() as usize];
    for (_, indices) in positions.into_iter() {
        for i in 0..indices.len() {
            if i < indices.len() - 1 {
                dp[0][indices[i] as usize] = indices[i + 1] - indices[i] + 1;
            } else {
                dp[0][indices[i] as usize] = indices[0] + n - indices[i] + 1;
            }
        }
    }
    for i in 1..dp.len() {
        for j in 0..arr.len() {
            dp[i][j] = min(dp[i - 1][j] + dp[i - 1][((j as u64 + dp[i - 1][j]) % n) as usize], dp[i][j]);
        }
    }
    let mut index = 0;
    let mut crt = 0;
    while index < n * (k - 1) {
        for i in (0..dp.len()).rev() {
            if index + dp[i][crt] > n * k {
                continue;
            }
            index += dp[i][crt];
            crt = (index % n) as usize;
        }
    }
    if index == n * k {
        println!("");
        return;
    }
    for elem in solve(&arr, crt).into_iter() {
        print!("{} ", elem);
    }
    println!("");
}

fn solve(arr: &[u64], init: usize) -> Vec<u64> {
    let mut ans = vec![];
    let mut nums = HashMap::new();
    for i in init..arr.len() {
        if nums.contains_key(&arr[i]) {
            let j = *nums.get(&arr[i]).unwrap();
            for k in (j..ans.len()).rev() {
                nums.remove(&ans[k]);
                ans.pop().unwrap();
            }
        } else {
            nums.insert(arr[i], ans.len());
            ans.push(arr[i]);
        }
    }
    ans
}


