            ret
        }};
        ($($t:tt),*) => {{
            let line = readln();
            let mut it = line.split_whitespace();
            _read!(it; $($t),*)
        }};
    }

    macro_rules! _read {
        ($it:ident; [char]) => {
            _read!($it; String).chars().collect::<Vec<_>>()
        };
        ($it:ident; [u8]) => {
            Vec::from(_read!($it; String).into_bytes())
        };
        ($it:ident; [$t:ty]) => {
            $it.map(|s| s.parse::<$t>().unwrap_or_else(|e| panic!("{}", e))).collect::<Vec<_>>()
