fn main() {
    let param = read_vector::<u64>();
    let (n, k) = (param[0] as usize, param[1]);
    let arr = read_vector::<usize>();
    let mut period = vec![0];
    let mut first = HashMap::new();
    for i in 0..n {
        if !first.contains_key(&arr[i]) {
            first.insert(arr[i], i);
        }
    }
    let mut init = 0;
    loop {
        if let Some(first_num) = operate(&arr, init) {
            init = *first.get(&first_num).unwrap() + 1;
            period.push(init);
        } else {
            break;
        }
    }
    let start = ((k % period.len() as u64 + period.len() as u64 - 1) % period.len() as u64) as usize;
    let ans = solve(&arr, start);
    for i in 0..ans.len() {
        if i < ans.len() - 1 {
            print!("{} ", i);
        } else {
            print!("{}", i);
        }
    }
    println!("");
}

fn operate(arr: &[usize], init: usize) -> Option<usize> {
    if init == arr.len() {
        return None;
    }
    let mut first_num = arr[init];
    let mut index = init + 1;
    while index < arr.len() {
        if arr[index] == first_num {
            if index == arr.len() - 1 {
                return None;
            }
            first_num = arr[index + 1];
            index = index + 2;
        }
    }
    Some(first_num)
}

fn solve(arr: &[usize], init: usize) -> Vec<usize> {
    let mut ans = vec![];
    if init == arr.len() {
        return ans;
    }
    let mut nums = HashMap::new();
    let mut index = 0;
    for i in init..arr.len() {
        if nums.contains_key(&arr[i]) {
            let &j = nums.get(&arr[i]).unwrap();
            if j < index {
                index = j;
            }
            nums.remove(&arr[i]);
        } else {
            if index == ans.len() {
                ans.push(arr[i]);
            } else {
                ans[index] = arr[i];
            }
            nums.insert(arr[i], index);
            index += 1;
        }
    }
    while ans.len() == index {
        ans.pop().unwrap();
    }
    ans
}

#[allow(dead_code)]
fn read<T>() -> T where T: std::str::FromStr, T::Err: std::fmt::Debug {
    let mut buf = String::new();
    stdin().read_line(&mut buf).unwrap();
    return buf
        .trim()
        .parse()
        .unwrap();
}

#[allow(dead_code)]
fn read_vector<T>() -> Vec<T> where T: std::str::FromStr, T::Err: std::fmt::Debug {
    let mut buf = String::new();
    stdin().read_line(&mut buf).unwrap();
    return buf
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();
}

#[allow(dead_code)]
fn read_matrix<T>() -> Vec<Vec<T>> where T: std::str::FromStr, T::Err: std::fmt::Debug {
    use std::io::prelude::*;
    let stdin = stdin();
    return stdin
        .lock()
        .lines()
        .map(|line| line
            .unwrap()
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect())
        .collect();
}
